/* Personal Agent WaterMelon - frontend.
   Every panel reads through the backend API; nothing touches storage directly. */
"use strict";

/* SIGNED IN BY THE BROWSER, NOT BY THIS SCRIPT. Every request to /api/
   needs the agent's key; this page never holds it. The agent opens the page
   through a link that signs the browser in once, and from then on the
   browser sends a cookie no script can read - this one included - with each
   request of this page, and with nothing a page anywhere else asks for
   (api/access.py). So the requests below send nothing of their own, and
   all there is to do here is say so when the browser is not signed in: the
   page was opened from a bookmark after the browser was closed, say. */
let signInNoticeShown = false;
function signInNeeded(response) {
  if (response.status !== 401 || signInNoticeShown) return;
  signInNoticeShown = true;
  const notice = document.createElement("div");
  notice.setAttribute("role", "alert");
  notice.style.cssText = "position:fixed;left:0;right:0;top:0;z-index:10000;" +
    "padding:10px 16px;background:#7a2e1f;color:#fff;font:14px/1.4 system-ui,sans-serif;" +
    "text-align:center";
  notice.textContent = "This page is not signed in to the agent. Open it again " +
    "from the agent's icon beside the clock, or from its window.";
  (document.body || document.documentElement).appendChild(notice);
}

/* The zone this page is in, by name - sent with every request, so the
   agent keeps a reminder in "your own time" on the zone you are in when it
   is made (scheduler/core/zones.py). */
const PAGE_ZONE = (() => {
  try { return Intl.DateTimeFormat().resolvedOptions().timeZone || ""; } catch (err) { return ""; }
})();

const api = {
  async get(path) {
    const response = await fetch(path, { headers: { Accept: "application/json",
                                                    "X-Time-Zone": PAGE_ZONE } });
    signInNeeded(response);
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || response.statusText);
    return data;
  },
  /* The answer, or null when it is the same as the one tagged `tag` -
     for something asked again and again while it is followed, so an
     unchanged report is neither sent again nor drawn again. */
  async getIfChanged(path, tag) {
    const headers = { Accept: "application/json", "X-Time-Zone": PAGE_ZONE };
    if (tag) headers["If-None-Match"] = tag;
    const response = await fetch(path, { headers });
    signInNeeded(response);
    if (response.status === 304) return { changed: false, tag };
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || response.statusText);
    return { changed: true, data, tag: response.headers.get("ETag") };
  },
  async post(path, body) {
    const response = await fetch(path, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Time-Zone": PAGE_ZONE },
      body: JSON.stringify(body || {}),
    });
    signInNeeded(response);
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || response.statusText);
    return data;
  },
};

const $ = (selector, scope = document) => scope.querySelector(selector);
const $$ = (selector, scope = document) => Array.from(scope.querySelectorAll(selector));

/* "Add to to-do": no more notifications about it, and listed in To do on
   the Overview, beside the Summary task's progress bars. */
const TO_TODO_LABEL = "Add to to-do (no more notifications; listed in To do on the Overview)";
/* Dismissed, and a lesson: fewer like it from now on. */
const BAD_LABEL = "Bad notification (no more notifications + fewer similar ones in future)";
/* How long "Remind me in ..." waits - the agent's own number, when it has
   said it (/api/notifications). */
let remindLaterMinutes = 30;

/* A notification, shown in the page: with a way to say it was a bad one,
   and long enough on screen to say it. */
function notificationToast(n) {
  const item = document.createElement("div");
  item.className = "toast-item toast-notification";
  if (n.kind === "warning" || n.kind === "error") {
    item.style.borderLeftColor = "var(--err)";
  }
  const words = document.createElement("div");
  words.textContent = `${n.title}: ${n.message}`;
  // EACH BUTTON SAYS WHAT HAPPENS: how long until it is back, or that it
  // never is.
  const button = (label, then) => {
    const one = document.createElement("button");
    one.type = "button";
    one.className = "small secondary";
    one.textContent = label;
    one.addEventListener("click", then);
    return one;
  };
  const gotIt = button("Got it (no more notifications)", async () => {
    try {
      await api.post("/api/notifications/read", { id: n.id });
      item.remove();
    } catch (err) { toast(err.message, "error"); }
  });
  const toTodo = button(TO_TODO_LABEL, async () => {
    try {
      await api.post("/api/notifications/todo", { id: n.id });
      item.remove();
      toast("On your to-do list - see To do on the Overview");
      loadTodos();
    } catch (err) { toast(err.message, "error"); }
  });
  const bad = document.createElement("button");
  bad.type = "button";
  bad.className = "small secondary";
  bad.textContent = BAD_LABEL;
  bad.addEventListener("click", () => markBadNotification(n.id, item));
  const buttons = document.createElement("div");
  buttons.className = "toast-buttons";
  // A reminder can come back in half an hour; a notice is only read.
  if (((n.metadata || {}).template || "") !== "passive") {
    const later = document.createElement("button");
    later.type = "button";
    later.className = "small secondary";
    later.textContent = `Remind me in ${remindLaterMinutes} minutes`;
    later.addEventListener("click", async () => {
      try {
        await api.post("/api/notifications/later", { id: n.id });
        item.remove();
        toast(`It will remind you again in ${remindLaterMinutes} minutes`);
      } catch (err) { toast(err.message, "error"); }
    });
    buttons.append(gotIt, later);
  } else {
    buttons.append(gotIt);
  }
  buttons.append(toTodo, bad);
  item.append(words, buttons);
  $("#toast").appendChild(item);
  setTimeout(() => item.remove(), 20000);
}


function toast(message, kind = "info") {
  const item = document.createElement("div");
  item.className = "toast-item";
  item.textContent = message;
  if (kind === "error") item.style.borderLeftColor = "var(--err)";
  $("#toast").appendChild(item);
  setTimeout(() => item.remove(), 6000);
}

function bars(container, rows, { onClick, onExpand, onSelectChild, expanded } = {}) {
  container.innerHTML = "";
  const max = Math.max(1, ...rows.map((r) => r.value));
  rows.forEach((row) => {
    const children = row.children || [];
    const isOpen = Boolean(expanded && expanded.has(row.label));
    const el = document.createElement(onClick && !children.length ? "button" : "div");
    // Only a row that does something gets the affordance of one, and a row
    // that does something is reachable by keyboard as well as by pointer.
    el.className = `bar-row${onClick ? " clickable" : ""}${row.selected ? " selected" : ""}`;
    el.dataset.label = row.label;
    if (el.tagName === "BUTTON") el.type = "button";
    el.title = row.title || row.label;
    const bar = `<div class="bar-track"><div class="bar-fill"
        style="width:${(row.value / max) * 100}%"></div></div>
      <div class="bar-value">${escapeHtml(String(row.display ?? row.value))}</div>`;
    if (children.length) {
      // Two things to do with one row, so two controls: the arrow opens what
      // the application was used for, the name opens its activity log. One
      // control doing both would make every glance at the detail a commitment.
      el.innerHTML = `<button type="button" class="bar-caret" aria-expanded="${isOpen}"
          title="${isOpen ? "Hide" : "Show"} what this was used for">${
            isOpen ? "▾" : "▸"}</button>
        <button type="button" class="bar-name">${escapeHtml(row.label)}</button>
        ${bar}`;
    } else {
      el.innerHTML = `<div class="bar-label">${escapeHtml(row.label)}</div>${bar}`;
    }
    if (onClick) {
      const name = el.querySelector(".bar-name");
      if (name) name.addEventListener("click", () => onClick(row));
      else el.addEventListener("click", () => onClick(row));
    }
    const caret = el.querySelector(".bar-caret");
    if (caret && onExpand) caret.addEventListener("click", () => onExpand(row));
    if (onSelectChild) {
      // Bound after the child list is appended, below.
    }
    container.appendChild(el);
    if (isOpen && children.length) {
      const list = document.createElement("div");
      list.className = "bar-children";
      list.innerHTML = children
        .map((child) => `<div class="bar-child${
            child.selected ? " selected" : ""}">
            <button type="button" class="bar-sub" data-app="${escapeHtml(row.label)}"
              data-site="${escapeHtml(child.label)}"
              title="Show only this in the log">${
                cut(child.label, `c:${row.label}:${child.label}`, 44)}</button>
            <span class="muted">${child.count}</span></div>`)
        .join("");
      container.appendChild(list);
      if (onSelectChild) {
        $$(".bar-sub", list).forEach((button) =>
          button.addEventListener("click", () =>
            onSelectChild(button.dataset.app, button.dataset.site)));
      }
    }
  });
  if (!rows.length) container.innerHTML = '<div class="muted">No data yet.</div>';
  // An arrow nobody has noticed is an arrow that does not exist, so the list
  // says once what it is for - and stops saying it as soon as one is opened.
  else if (onExpand && expanded && !expanded.size
           && rows.some((r) => (r.children || []).length)) {
    const hint = document.createElement("div");
    hint.className = "muted expand-hint";
    hint.textContent = "click ▸ to break one down";
    container.appendChild(hint);
  }
}

/* ------------------------------------------------------------ experience */
/* All the user's shown work as the stages of its loop, one piece of work at
   a time, how they work as principles and patterns, a way to try the
   retrieval, and the agent working on a piece when the user starts it. */
const experienceState = { unit: null, stage: null, card: null, units: [],
                          graph: null, all: [], tree: null, node: null,
                          open: new Set(), scope: "live" };

/* There is one experience: what was learned. */
function xpScoped(url) {
  return url;
}

const XP_KIND_COLOUR = {
  goal: "#8e6bd8", plan: "#3d6be5", execution: "#2f9e6b",
  evaluation: "#d08a2c", adjustment: "#cf4b45", delivery: "#1f8a9e",
};

/* A PROJECT'S OR A TASK'S TITLE IS ITS NAME: no "Project:" or "Task:" put
   before it - whoever named it, the list says what kind it is by where it
   is, not by a word in front of every name. */
const XP_KIND_PREFIX = /^\s*(?:new\s+project|project|task)\s*(?::|\s[-–—]\s)\s*/i;
function xpName(name) {
  const said = String(name || "");
  const bare = said.replace(XP_KIND_PREFIX, "");
  return bare.trim() ? bare : said;
}

/* Units the user added themselves: a project made of their folders, or one
   made for the agents. Theirs to describe, and to give folders. */
function xpUserAdded(unit) {
  return Boolean(unit) && (unit.kind === "directory" || unit.kind === "new project");
}

/* TOKENS, SHORT: 1.2M, 85k, 950. */
function xpTokens(n) {
  const value = Number(n || 0);
  if (value >= 1e6) return `${(value / 1e6).toFixed(value >= 1e7 ? 0 : 1).replace(/\.0$/, "")}M`;
  if (value >= 1e3) return `${(value / 1e3).toFixed(value >= 1e4 ? 0 : 1).replace(/\.0$/, "")}k`;
  return String(Math.round(value));
}

/* WHAT WENT IN AND WHAT CAME OUT, apart: "1.2M in · 85k out". A run kept
   before the two were counted apart has only its total - said as that. */
function xpTokenSplit(used) {
  const u = used || {};
  if (u.tokens_in !== undefined || u.tokens_out !== undefined) {
    return `${xpTokens(u.tokens_in)} in · ${xpTokens(u.tokens_out)} out`;
  }
  return `${xpTokens(u.tokens)} tokens`;
}

/* THE LIMITS a run is started or continued with: minutes, what goes in and
   what comes out - limited apart - and model calls. */
const XP_LIMITS = ["minutes", "tokens_in", "tokens_out", "calls"];
const XP_INPUT_TOKENS_ABOUT = "All that the models read - what they read from the "
  + "provider's prompt cache too, which is most of it";

/* A SOUND WHEN IT ENDS: ticked, the application plays one sound when the run
   reaches its end - finished, failed, stopped or at a limit - and never for a
   model call or a round. Played by the application itself: heard with this
   page closed. `attrs` say which box it is. */
function xpSoundBox(attrs, checked) {
  return `<label class="xp-sound" title="Played by the application once, when the run
    ends - finished, failed, stopped or at a limit - with this page open or not"><input
    type="checkbox" ${attrs}${checked ? " checked" : ""}> Play a sound when it ends</label>`;
}

/* The box beside a run's Continue: that session's own choice. */
/* A RUN THAT DID NOT STOP CLEANLY (agent/work/runner.py, GOES_BACK): cut
   off by the application closing, stopped at once, or failed - Resume takes
   it back to its last save point. Why it goes back, said plainly. */
const XP_GOES_BACK = { interrupted: "the application closed while it was going",
  "stopped at once": "you stopped it at once, before it wrapped up",
  failed: "it failed before it could stop" };
function xpGoesBack(run) {
  return Object.prototype.hasOwnProperty.call(XP_GOES_BACK, (run || {}).status || "");
}

/* RESUME OR CONTINUE, AS A CARD (the user, 2026-10-27: one run-on line was
   unreadable): the button and where it goes on from; why, and what happens
   to the files; this resume's own settings; what to change. */
function xpResumeCard(run, from, versions, book) {
  const id = escapeHtml(run.id);
  const back = !from && xpGoesBack(run) && (run.milestone || {}).version;
  const point = back && run.milestone.resume;
  const where = point
    ? `Goes back to its progress point: ${run.milestone.label || ""}`
    : back ? `Goes back to version ${run.milestone.version}: ${run.milestone.label || ""}`
    : !from ? "Goes on from where it stopped"
    : from === versions.head ? `Goes on from version ${from}, the latest`
    : `Goes on from version ${from}`;
  // Each piece a text of its own, as the language tables hold it.
  const why = back
    ? `<span class="xp-spec-label">${escapeHtml("Why")}</span>
      <span>${escapeHtml(XP_GOES_BACK[run.status] || "")}</span> ·
      <span>${escapeHtml("Its files and where it stood come back as they were then; what came after is given up.")}</span>`
    : from && from !== versions.head
      ? `<span>${escapeHtml("Its files and where it stood come back, and it goes on as a new branch - the versions after it are kept.")}</span>`
      : "";
  return `<div class="xp-resume-card xp-continue-row">
    <div class="xp-resume-head">
      <button type="button" class="small" data-xp-continue="${id}">${
        !from && xpGoesBack(run) ? "Resume" : "Continue"}</button>
      <span class="xp-resume-where">${escapeHtml(where)}</span>${
        point ? ` <span class="xp-resume-chip">${escapeHtml("not checked")}</span>` : ""}
      ${from ? `<button type="button" class="small secondary" data-xp-version-latest="${
        id}">From the latest instead</button>` : ""}
    </div>
    ${why ? `<p class="xp-resume-why muted">${why}</p>` : ""}
    <div class="xp-resume-settings">
      <span class="xp-spec-label">${escapeHtml("This time")}</span>
      <label>${escapeHtml("Python packages")} <select data-xp-continue-packages="${id}">
        <option value="ask"${book.chosen && book.mode === "ask" ? " selected" : ""}>${
          escapeHtml("Ask first")}</option>
        <option value="auto"${book.chosen && book.mode === "ask" ? "" : " selected"}>Auto</option>
      </select></label>
      ${xpContinueSound(run.id)}
      ${xpContinueUnconfined(run)}
      <span class="muted">${escapeHtml("Limits: as set above")}</span>
    </div>
    ${from ? `<p class="muted">${escapeHtml(`What to change from there: under ${from} in Versions`)}</p>`
      : xpContinueWords(run.id)}
  </div>`;
}

function xpContinueSound(runId) {
  // As the run last ran, unless chosen here (the user, 2026-10-27).
  const kept = xpVersionsState();
  const chosen = kept.sound[runId];
  return xpSoundBox(`data-xp-continue-sound="${escapeHtml(runId)}"`,
    chosen !== undefined ? chosen : xpRecordSpec(kept.runs[runId]).sound);
}

/* WITHOUT THE SANDBOX (agent/work/unconfined.py): the user's own work only -
   never a way of the Work debugger - and always with what it means beside
   it. Off unless chosen, each session. */
const XP_UNCONFINED_WARNING = "Without the sandbox, the agent works on this computer as you: it "
  + "can read what your account can read, reach the network, and change or delete files "
  + "anywhere. Its permission rules still hold: whatever needs your approval is refused, and "
  + "it asks you only when every other way has failed. Never - approved or not: the agent's "
  + "own data, your sign-ins, or anything sent out with your accounts.";

function xpIsDebugRun(run) {
  return /^dbg_/.test(String((run || {}).unit_id || ""));
}

function xpUnconfinedBox(attrs) {
  return `<span class="xp-unconfined"><label><input type="checkbox" ${attrs}> Work without
    the sandbox</label> <span class="xp-warning xp-unconfined-warning">${
    escapeHtml(XP_UNCONFINED_WARNING)}</span></span>`;
}

function xpContinueUnconfined(run) {
  // As the run last ran (the user, 2026-10-27), its warning beside it.
  return xpIsDebugRun(run) ? ""
    : xpUnconfinedBox(`data-xp-continue-unconfined="${escapeHtml(run.id)}"${
      xpRecordSpec(run).sandbox ? "" : " checked"}`);
}

/* THE USER'S DESCRIPTION of a project they added - in their own words, never
   what reading its folders says it is for - with a small control to change
   it in place. `where` says which of its two places this is: its row in the
   list, or the top of the opened project. */
function xpAbout(unit, where) {
  if (!xpUserAdded(unit)) return "";
  const id = escapeHtml(unit.id);
  const editing = experienceState.aboutEditing;
  if (editing && editing.unit === unit.id && editing.where === where) {
    return `<div class="xp-about xp-about-editing" data-xp-about-box="${id}">
      <label class="xp-about-label" for="xp-about-${where}-${id}">Your description</label>
      <textarea id="xp-about-${where}-${id}" rows="3" maxlength="4000"
        data-xp-about-text="${id}">${escapeHtml(editing.text ?? unit.description ?? "")}</textarea>
      <span class="xp-about-buttons"><button type="button" class="small"
        data-xp-about-save="${id}">Save</button>
      <button type="button" class="small secondary" data-xp-about-cancel="${id}">Cancel</button></span>
    </div>`;
  }
  const words = String(unit.description || "");
  return `<div class="xp-about" data-xp-about-box="${id}">
    <span class="xp-about-label">Your description</span>
    ${words ? `<span class="xp-about-words">${escapeHtml(words)}</span>`
      : `<span class="muted">none yet</span>`}
    <span class="xp-about-edit" role="button" tabindex="0" data-xp-about-edit="${id}"
      data-xp-about-where="${where}">${words ? "edit" : "add one"}</span>
  </div>`;
}

/* A PROJECT'S FOLDERS, as a list: each with × to take it out - asked first,
   in place - and a way to add one, chosen in the machine's own folder
   dialog. Changed, the project is read again from the start. The last one
   stays: a project is its folders. */
function xpFolderList(unit, paths) {
  const id = escapeHtml(unit);
  const asking = experienceState.folderAsk || {};
  const list = (paths || []).filter((one) => String(one || "").trim());
  return `<ul class="xp-folder-list" data-xp-folders-of="${id}">${list.map((f) => {
    const confirming = asking.unit === unit && asking.path === f;
    return `<li class="xp-folder${confirming ? " xp-folder-asking" : ""}"><code title="${
      escapeHtml(f)}">${escapeHtml(f)}</code>${confirming
      ? `<span class="xp-folder-ask">Take this folder out? The project is read again
          from the start. <button type="button" class="small danger"
          data-xp-folder-yes="${id}" data-xp-folder-path="${escapeHtml(f)}">Take it out</button>
          <button type="button" class="small secondary" data-xp-folder-no="${id}">Keep it</button></span>`
      : list.length > 1 ? `<button type="button" class="xp-folder-x" data-xp-folder-remove="${id}"
          data-xp-folder-path="${escapeHtml(f)}" title="Take this folder out"
          aria-label="Take ${escapeHtml(f)} out">×</button>` : ""}</li>`;
  }).join("")}<li><span class="xp-unit-folder-edit" role="button" tabindex="0"
      data-xp-folder-add="${id}">Add a folder…</span></li></ul>`;
}

/* WHILE SOMETHING IS BEING TYPED in a part of the page, that part is not
   drawn again: what is typed, where the caret is and what is selected stay
   as they are. What would have been drawn is drawn once the typing leaves
   that part (see the focusout below). */
const XP_EDITABLE = /^(INPUT|TEXTAREA|SELECT)$/;
function xpEditing(selector) {
  const at = document.activeElement;
  const scope = $(selector);
  // Reading a version's slides - the frame has the focus, its keys move
  // through them - is not interrupted either.
  return Boolean(at && scope && scope.contains(at) && (XP_EDITABLE.test(at.tagName)
    || at.isContentEditable || at.tagName === "IFRAME"));
}
/* A part of the tab drawn again with what it already shows: left as it is -
   not replaced by the same, which loses where its boxes were scrolled and
   what was selected in it. True when it was drawn. (Drawn by anything else
   since, it is drawn.) */
function xpPut(el, html) {
  if (!el) return false;
  if (el._xpHtml === xpShows(html) && el._xpFirst === el.firstChild
      && el._xpCount === el.childNodes.length) return false;
  el.innerHTML = html;
  el._xpHtml = xpShows(html);
  el._xpFirst = el.firstChild;
  el._xpCount = el.childNodes.length;
  return true;
}
const xpDeferred = new Map();       // selector -> what to draw once it is left
function xpDefer(selector, draw) {
  xpDeferred.set(selector, draw);
}
function xpDrawDeferred() {
  xpDeferred.forEach((draw, selector) => {
    if (xpEditing(selector)) return;
    xpDeferred.delete(selector);
    draw();
  });
}
// A field left by pressing a button beside it - Continue, Save: the part is
// drawn only once that click has been had, or the button would be gone
// from under the pointer before it was clicked.
let xpPointerDown = false;
document.addEventListener("pointerdown", () => { xpPointerDown = true; }, true);
document.addEventListener("pointerup", () => {
  setTimeout(() => { xpPointerDown = false; xpDrawDeferred(); }, 0);
}, true);
document.addEventListener("focusout", () => {
  // Where the focus goes next: drawn once it is outside the part.
  setTimeout(() => { if (!xpPointerDown) xpDrawDeferred(); }, 0);
});

function xpWriter(written) {
  if (!written) return "";
  if (typeof written === "string") return written;
  return written.model
    ? `${written.model}${written.provider ? ` (${written.provider})` : ""}` : "";
}



/* A PROJECT IS NO LONGER LEARNED BY ITS OWN BUTTON (2026-10-21): the
   learning runs for all of the user's work, from Work's Learning panel. */
function xpLearning(unit) {
  return "";
}

async function loadExperience(full) {
  let status;
  try {
    status = await api.get(xpScoped("/api/experience"));
  } catch (err) {
    $("#xp-units").innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  loadLearning();
  xpLoadDrafts();
  experienceState.units = status.units || [];
  if (!experienceState.units.some((u) => u.id === experienceState.unit)) {
    experienceState.unit = (experienceState.units[0] || {}).id || null;
  }
  xpDrawUnits();
  await xpLoadProjects();
  await xpOpenUnit();
}

/* WORK'S LEARNING (learning/service.py): the switch and the times, the
   update open or the last one - Update now, Pause, Continue - the places it
   reads (and the agents search), and what it spent. Read again every few
   seconds while an update or a search build is going. */
const learningState = { timer: null, data: null, chartOpen: false, removing: null,
                        detail: null, detailData: null };

async function loadLearning() {
  try {
    learningState.data = await api.get("/api/learning");
  } catch (err) {
    const host = $("#xp-learn");
    if (host) host.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  drawLearning();
}

async function learningDo(body, said) {
  try {
    learningState.data = await api.post("/api/learning", body);
    if (said) toast(said);
    drawLearning();
  } catch (err) {
    toast(err.message, "error");
  }
}

/* THE LOCAL INDEX'S OWN BAR, beside the learning's (the user, 2026-10-24):
   an update brings the local index up to date before it reads anything, and
   that is shown as itself - not as the learning standing at 0%. The share is
   of the files the last build walked; with none known (a folder never
   built) and while the file is made small again, the bar only says it is
   going. */
function learningIndexHtml(s) {
  const ix = s.index || {};
  if (!ix.building) {
    return ix.done_at ? `<p class="muted">Local index: ${Number(ix.files || 0).toLocaleString()} files,
      brought up to date ${escapeHtml(localStamp(ix.done_at))}.</p>` : "";
  }
  const state = ix.waiting ? "Waiting: the computer is on its battery."
    : ix.tidying ? "Making the index file smaller…"
      : ix.root ? `Reading: ${ix.root}` : "Starting…";
  const walked = Number(ix.walked || 0).toLocaleString();
  const known = ix.share !== null && ix.share !== undefined && !ix.tidying;
  const share = known ? Math.round(Number(ix.share) * 100) : 0;
  return `<div class="xp-learn-progress"><span class="xp-learn-what">Local index</span>
      ${known ? `<progress max="100" value="${share}" aria-label="How far the local index is"></progress>
      <span>${share}%</span>
      <span class="muted">${walked} of ${Number(ix.expected || 0).toLocaleString()} files</span>`
    : `<progress aria-label="How far the local index is"></progress>
      <span class="muted">${walked} files looked at</span>`}</div>
    <p class="muted">${escapeHtml(state)}</p>`;
}

function learningUpdateHtml(s) {
  const u = s.update;
  const open = u && ["running", "paused", "waiting"].includes(u.state);
  const limit = Number(s.daily_tokens || 0);
  const spentToday = Number(s.tokens_today || 0).toLocaleString();
  const today = limit ? `${spentToday} of ${limit.toLocaleString()} tokens today`
    : `${spentToday} tokens today`;
  let buttons = "";
  if (open && u.state === "paused") {
    buttons = `<button type="button" class="small" data-learn="continue">Continue</button>`;
  } else if (open) {
    buttons = `<button type="button" class="small secondary" data-learn="pause">Pause</button>`;
  } else {
    buttons = `<button type="button" class="small" data-learn="update"${s.over_limit
      ? " disabled" : ""}>Update now</button>`;
  }
  const lines = [];
  if (open) {
    const share = Math.round(Number(u.share || 0) * 100);
    const state = u.state === "paused" ? "Paused - the times set are skipped until you continue."
      : u.state === "waiting" ? "Today's token limit is used up: it carries on tomorrow."
        : u.now_reading === "the local index" ? "It reads once the local index is up to date."
          : u.now_reading ? `Reading: ${u.now_reading}` : "Starting…";
    lines.push(`<div class="xp-learn-progress"><span class="xp-learn-what">Learning</span>
        <progress max="100" value="${share}" aria-label="How far the update is"></progress>
        <span>${share}%</span>
        ${u.units ? `<span class="muted">${Number(u.units_done || 0)} of ${u.units} places read</span>` : ""}
      </div>`);
    lines.push(`<p class="muted">Reading what you did up to ${escapeHtml(localStamp(u.cutoff))}
      (${u.by === "you" ? "you started it" : "at a time set"}). ${escapeHtml(state)}</p>`);
  } else if (u) {
    lines.push(`<p class="muted">${u.state === "done"
      ? `Last update: what you did up to ${escapeHtml(localStamp(u.cutoff))}, finished ${
        escapeHtml(localStamp(u.finished_at))}.`
      : `The last update stopped: ${escapeHtml(u.note || u.state)}`}</p>`);
  } else {
    lines.push(`<p class="muted">Nothing learned yet.</p>`);
  }
  if (s.over_limit && !open) lines.push(`<p class="muted">Today's token limit is used up.</p>`);
  for (const at of (u && u.skipped) || []) {
    lines.push(`<p class="muted">Skipped at ${escapeHtml(localStamp(at))}: the update before was
      still going.</p>`);
  }
  if (u && u.note && u.state === "done") lines.push(`<p class="muted">${escapeHtml(u.note)}</p>`);
  return `<div class="xp-learn-row">${buttons}<span class="muted">${escapeHtml(today)}</span></div>
    ${learningIndexHtml(s)}${lines.join("")}`;
}

/* THE LESSONS (learning/service.py `lessons`, the user, 2026-10-24): every
   one the learning reads, in three groups - your own folders and projects,
   what you added, what the heartbeat added - each turned off (not read,
   nothing of it given to a run) or on, or deleted for good (it goes on the
   never list); then the never list itself, each one taken off it again. */
const LEARN_WHAT = { cases: "cases", rules: "rules", reference: "a reference" };

function learningCadence(cadence) {
  if (cadence === "once") return "read once";
  if (cadence === "update") return "read again at every update";
  const days = String(cadence || "").startsWith("days:") ? cadence.slice(5) : "";
  return days ? `read again every ${days} days` : "";
}

function learningKind(one) {
  if (one.kind === "work") return "Work project";
  if (one.kind === "place") return "folder";
  if (one.kind === "rules") return "your rules for every agent";
  if (one.kind === "url") {
    return one.scope === "repo" ? "repository" : one.scope === "prefix" ? "web pages" : "web page";
  }
  if (one.kind === "text") return "passage";
  if (one.kind === "folder") return "folder";
  if (one.kind === "file") return "file";
  return one.kind || "";
}

function learningCounts(one) {
  const n = (v) => Number(v || 0).toLocaleString();
  if (!Number(one.cases || 0) && !Number(one.judgments || 0)) {
    return one.first_read || one.read_at ? "nothing learned from it" : "not read yet";
  }
  return `${n(one.cases)} cases, ${n(one.judgments)} judgments, bearing on ${n(one.reasons)} reasons`;
}

/* A lesson's own buttons: turn it off or on, show what was learned, and
   delete - which asks first, in the row itself. */
function learningActions(unit, off, extra = "") {
  const asking = learningState.removing === unit;
  if (asking) {
    return `<div class="xp-unit-ask" role="alert">Delete it for good? Everything learned from it
      goes, and it is put on the list of what is never learned. Nothing on your computer or on
      the web is touched.
      <button type="button" class="small danger" data-learn-delete-yes="${escapeHtml(unit)}">Delete</button>
      <button type="button" class="small secondary" data-learn-remove-no="1">Keep it</button></div>`;
  }
  return `<div class="xp-lesson-actions">${extra}
    <button type="button" class="small secondary" data-learn-detail="${escapeHtml(unit)}">${
      learningState.detail === unit ? "Hide what was learned" : "What was learned"}</button>
    <button type="button" class="small secondary" data-learn-toggle="${escapeHtml(unit)}"
      data-on="${off ? "1" : ""}">${off ? "Turn on" : "Turn off"}</button>
    <button type="button" class="small secondary danger" data-learn-delete="${escapeHtml(unit)}">Delete</button>
  </div>`;
}

/* What was learned of one lesson, opened from its row. */
function learningDetailHtml(unit) {
  if (learningState.detail !== unit) return "";
  const d = learningState.detailData;
  if (!d || d.unit !== unit) return `<div class="xp-lesson-detail muted">Opening&hellip;</div>`;
  if (!(d.cases || []).length) return `<div class="xp-lesson-detail muted">Nothing learned from it yet.</div>`;
  const STRENGTH = { written: "you wrote it down", noted: "noted from your words",
    endorsed: "you endorse it", changed: "you changed it", approved: "you said yes",
    accepted: "you let it stand" };
  const cases = d.cases.map((c) => `<li><strong>${escapeHtml(c.title)}</strong>
      ${c.looks_like ? `<div>${escapeHtml(c.looks_like)}</div>` : ""}
      ${(c.judgments || []).length ? `<ul>${c.judgments.map((j) => `<li>${escapeHtml(j.direction)}
        <span class="muted">(${escapeHtml(STRENGTH[j.strength] || j.strength)}${j.said
          ? `: "${escapeHtml(j.said)}"` : ""})</span></li>`).join("")}</ul>` : ""}</li>`).join("");
  const reasons = (d.reasons || []).map((r) => `<li>${escapeHtml(r.statement)}
      <span class="muted">(${escapeHtml(r.source === "adopted" ? "adopted from it"
        : r.source === "stated" ? "in your own words" : "inferred")}, ${escapeHtml(
        r.state === "active" ? "in use" : r.state === "candidate" ? "forming" : r.state)})</span></li>`).join("");
  return `<div class="xp-lesson-detail"><h5>Cases</h5><ul>${cases}</ul>${reasons
    ? `<h5>Reasons it bears on</h5><ul>${reasons}</ul>` : ""}</div>`;
}

function learningUnitRow(one) {
  const off = one.state === "inactive";
  const folders = (one.folders || []).slice(0, 4).map((f) => `<code>${escapeHtml(f)}</code>`).join(" ");
  return `<li class="xp-lesson${off ? " xp-lesson-off" : ""}">
    <div class="xp-lesson-head"><strong>${escapeHtml(one.title || one.id)}</strong>
      <span class="muted">${escapeHtml(learningKind(one))}</span>
      ${off ? `<span class="xp-lesson-badge">turned off</span>` : ""}</div>
    ${folders ? `<div class="xp-lesson-where">${folders}</div>` : ""}
    <div class="muted">${escapeHtml(learningCounts(one))}</div>
    ${learningActions(one.id, off)}
    ${learningDetailHtml(one.id)}
  </li>`;
}

function learningItemRow(one) {
  const off = one.state === "inactive";
  const whose = one.whose === "mine" ? "Yours - learned in full"
    : "Someone else's - a reference you endorse";
  const learns = (one.learn || []).map((key) => LEARN_WHAT[key] || key).join(", ");
  const status = one.status === "pending" ? `<span class="xp-lesson-badge xp-lesson-wait">waiting for you to look</span>`
    : one.status === "unreachable" ? `<span class="xp-lesson-badge">can not be read now</span>` : "";
  const evidence = (one.evidence || []).map((ev) => `<li>${escapeHtml(ev.what || "")}${ev.quote
    ? ` <span class="muted">"${escapeHtml(ev.quote)}"${ev.by_user ? "" : " (not certain to be yours)"}</span>` : ""}
    ${ev.at ? `<span class="muted">${escapeHtml(localStamp(ev.at))}</span>` : ""}</li>`).join("");
  const where = one.kind === "text" ? `<blockquote class="xp-lesson-text">${escapeHtml(one.text || "")}</blockquote>`
    : `<div class="xp-lesson-where"><code>${escapeHtml(one.source)}</code></div>`;
  return `<li class="xp-lesson${off ? " xp-lesson-off" : ""}">
    <div class="xp-lesson-head"><strong>${escapeHtml(one.title)}</strong>
      <span class="muted">${escapeHtml(learningKind(one))}</span>
      ${off ? `<span class="xp-lesson-badge">turned off</span>` : ""} ${status}
      ${one.large ? `<span class="xp-lesson-badge xp-lesson-large" title="${escapeHtml(
        `About ${Number(one.estimate || 0).toLocaleString()} tokens a reading`)}">large</span>` : ""}</div>
    ${where}
    <div>${escapeHtml(whose)}. ${learns ? escapeHtml(`Learns ${learns}`) + "." : ""}
      <span class="muted">${escapeHtml(learningCadence(one.cadence))}</span></div>
    ${one.angle ? `<div><span class="muted">${escapeHtml(one.origin === "heartbeat"
      ? "Its purpose, as the heartbeat saw it:" : "From the angle:")}</span> ${escapeHtml(one.angle)}</div>` : ""}
    ${evidence ? `<div class="muted">Why the heartbeat added it:</div><ul class="xp-lesson-evidence">${evidence}</ul>` : ""}
    ${one.note ? `<div class="muted">${escapeHtml(one.note)}</div>` : ""}
    <div class="muted">${escapeHtml(learningCounts(one))}${one.read_at
      ? ` - last read ${escapeHtml(localStamp(one.read_at))}` : ""}</div>
    ${learningActions(one.unit_id, off,
      `<button type="button" class="small secondary" data-learn-edit="${escapeHtml(one.id)}">Change its plan</button>`)}
    ${learningDetailHtml(one.unit_id)}
  </li>`;
}

/* WHAT WAITS FOR YOU: the first reading of your own work on the web, and of
   anything the heartbeat added - nothing of it is given to a run until you
   keep it. */
function learningPendingHtml(s) {
  const lessons = s.lessons || {};
  const waiting = [...(lessons.added || []), ...(lessons.heartbeat || [])]
    .filter((one) => one.status === "pending");
  if (!waiting.length) return "";
  return `<h3>Waiting for you</h3>
    <p class="muted">Read for the first time. Nothing of it is used until you keep it - look at
      what was learned first.</p>
    <ul class="xp-lessons">${waiting.map((one) => `<li class="xp-lesson">
      <div class="xp-lesson-head"><strong>${escapeHtml(one.title)}</strong>
        <span class="muted">${escapeHtml(learningKind(one))}, ${escapeHtml(one.origin === "heartbeat"
          ? "added by the heartbeat" : "added by you")}</span></div>
      <div class="muted">${escapeHtml(learningCounts(one))}</div>
      <div class="xp-lesson-actions">
        <button type="button" class="small secondary" data-learn-detail="${escapeHtml(one.unit_id)}">${
          learningState.detail === one.unit_id ? "Hide what was learned" : "What was learned"}</button>
        <button type="button" class="small" data-learn-accept="${escapeHtml(one.id)}">Keep it</button>
        <button type="button" class="small secondary" data-learn-reject="${escapeHtml(one.id)}">Don't keep it</button>
      </div>
      ${learningDetailHtml(one.unit_id)}</li>`).join("")}</ul>`;
}

function learningLessonsHtml(s) {
  const lessons = s.lessons || {};
  const records = s.records || {};
  const has = (kind) => (s.places || []).some((one) => one.kind === kind);
  const listed = (s.places || []).map((one) => `<li><code>${escapeHtml(one.path)}</code>${one.kind === "claude"
    ? ` <span class="muted">${escapeHtml("Your Claude Code conversations")}</span>` : one.kind === "codex"
      ? ` <span class="muted">${escapeHtml("Your Codex conversations")}</span>` : ""}</li>`).join("");
  const found = (s.found || []).filter((one) => !one.excluded).map((one) => `<li>
      <code>${escapeHtml(one.path)}</code> <span class="muted">found through your ${escapeHtml(
        (one.via || []).map((v) => v === "claude" ? "Claude Code" : "Codex").join(" and "))} conversations,
        not read yet</span></li>`).join("");
  const yours = (lessons.yours || []).map(learningUnitRow).join("")
    || `<li class="muted">Nothing read yet: your Work projects are read, and the folders you add here.</li>`;
  const added = (lessons.added || []).map(learningItemRow).join("")
    || `<li class="muted">Nothing yet. Add a web page, a site, a passage you like, a folder or a file.</li>`;
  const heart = (lessons.heartbeat || []).map(learningItemRow).join("")
    || `<li class="muted">Nothing yet. Once a day the heartbeat looks for what you show you endorse, and adds it here with its evidence.</li>`;
  const never = (lessons.never || []).map((one) => `<li><code>${escapeHtml(one.title)}</code>
      <button type="button" class="small secondary" data-learn-never-off="${escapeHtml(one.key)}">Take off the list</button></li>`).join("")
    || `<li class="muted">Nothing on it.</li>`;
  return `<h3>Your own folders and projects</h3>
    <p class="muted">Your Work projects, the folders listed here with everything in them, and your
      coding agents' conversations - also what the agents search. Never the agent's own data, and
      never a key or password: they are taken out before anything is read.</p>
    ${listed ? `<ul class="xp-learn-places">${listed}</ul>` : ""}
    <div class="xp-learn-row">
      <button type="button" class="small secondary" data-learn-add="folder">Add a folder…</button>
      <button type="button" class="small secondary" data-learn-add="claude"${!records.claude
        || has("claude") ? " disabled" : ""}>Add Claude Code records</button>
      <button type="button" class="small secondary" data-learn-add="codex"${!records.codex
        || has("codex") ? " disabled" : ""}>Add Codex records</button>
    </div>
    <ul class="xp-lessons">${yours}</ul>
    ${found ? `<h4>Folders your conversations worked in</h4><ul class="xp-learn-places">${found}</ul>` : ""}
    <h3>Added by you</h3>
    <div class="xp-learn-row"><button type="button" class="small" data-learn-new="1">Add to learning…</button>
      <span class="muted">A web page or site, a passage, a folder or a file - yours, or someone else's
        you endorse. Also beside selected text ("Learn") and in Explorer ("Add to learning").</span></div>
    <ul class="xp-lessons">${added}</ul>
    <h3>Added by the heartbeat</h3>
    <ul class="xp-lessons">${heart}</ul>
    <h3>Never learned</h3>
    <p class="muted">What you deleted. Nothing here is learned again - nor added by the heartbeat -
      until you take it off the list.</p>
    <ul class="xp-learn-places">${never}</ul>`;
}

async function learningOpenDetail(unit) {
  if (learningState.detail === unit) {
    learningState.detail = null;
    drawLearning();
    return;
  }
  learningState.detail = unit;
  learningState.detailData = null;
  drawLearning();
  try {
    learningState.detailData = await api.get(`/api/learning/unit?id=${encodeURIComponent(unit)}`);
  } catch (err) {
    toast(err.message, "error");
    learningState.detail = null;
  }
  drawLearning();
}

/* LEARN: what is handed to the learning, and its plan to check
   (learning/plan.py). Opened empty from the panel, on a draft from the
   selection's "Learn" or Explorer's "Add to learning", or on an item to
   change its plan. Nothing is learned before Add. */
const learnState = { draft: null, timer: null, editing: null, plan: null };
const LEARN_SOLO = new URLSearchParams(location.search).get("solo") === "learn";
if (LEARN_SOLO) {
  document.body.classList.add("learn-solo");
  document.title = "Learn - Personal Agent WaterMelon";
  $("#learn-box").addEventListener("close", () => setTimeout(() => window.close(), 60));
  try {
    const w = Math.min(760, screen.availWidth), h = Math.min(860, screen.availHeight);
    window.resizeTo(w, h);
    window.moveTo((screen.availLeft || 0) + Math.round((screen.availWidth - w) / 2),
                  (screen.availTop || 0) + Math.round((screen.availHeight - h) / 2));
  } catch (_err) { /* left as it opened */ }
}

function learnButtons(which) {
  const show = { draft: which === "pick", add: which === "plan", now: which === "plan",
                 save: which === "edit" };
  $("#learn-draft").hidden = !show.draft;
  $("#learn-add").hidden = !show.add;
  $("#learn-now").hidden = !show.now;
  $("#learn-save").hidden = !show.save;
}

function openLearnBox() {
  const dialog = $("#learn-box");
  clearTimeout(learnState.timer);
  learnState.draft = null;
  learnState.editing = null;
  learnState.plan = null;
  learnButtons("pick");
  $("#learn-body").innerHTML = `<p class="muted">What should it learn from? A web address, a
      passage, a folder or a file.</p>
    <label class="learn-field">Web address <input type="url" id="learn-url" placeholder="https://"></label>
    <label class="learn-field">Or a passage <textarea id="learn-text" rows="5"></textarea></label>
    <div class="xp-learn-row">
      <button type="button" class="small secondary" id="learn-pick-folder">Choose a folder…</button>
      <button type="button" class="small secondary" id="learn-pick-file">Choose a file…</button>
      <span class="muted" id="learn-picked"></span>
    </div>`;
  if (!dialog.open) dialog.showModal();
}

async function learnDraft(handed) {
  const dialog = $("#learn-box");
  if (!dialog.open) dialog.showModal();
  learnButtons("none");
  $("#learn-body").innerHTML = `<p class="muted">Looking at it&hellip;</p>`;
  try {
    const said = await learningPost({ action: "draft", ...handed });
    learnFollow(said.draft.id);
  } catch (err) {
    $("#learn-body").innerHTML = `<p class="delegate-error">${escapeHtml(err.message)}</p>`;
  }
}

async function learningPost(body) {
  return api.post("/api/learning", body);
}

async function learnFollow(id) {
  clearTimeout(learnState.timer);
  const dialog = $("#learn-box");
  if (!dialog.open) dialog.showModal();
  let draft;
  try {
    draft = (await api.get(`/api/learning/draft?id=${encodeURIComponent(id)}`)).draft;
  } catch (err) {
    $("#learn-body").innerHTML = `<p class="delegate-error">${escapeHtml(err.message)}</p>`;
    learnButtons("none");
    return;
  }
  learnState.draft = draft;
  if (draft.state === "failed") {
    $("#learn-body").innerHTML = `<p class="delegate-error">${escapeHtml(draft.error || "It could not be looked at.")}</p>`;
    learnButtons("none");
    return;
  }
  if (draft.state !== "ready") {
    $("#learn-body").innerHTML = `<p class="muted">${draft.state === "looking"
      ? "Looking at it…" : "Drafting the plan…"}</p>`;
    learnState.timer = setTimeout(() => learnFollow(id), 1500);
    return;
  }
  learnShowPlan(draft.plan, false);
}

/* The plan, to change: whose it is, what to learn of it, the angle, how
   much of it, how often - and what a reading costs. */
function learnShowPlan(plan, editing) {
  learnState.plan = plan;
  const kind = plan.kind;
  const scopes = kind === "url" ? [["page", "This page"], ["prefix", "The pages under this address"],
    ["repo", "The repository"]] : [];
  const cadence = String(plan.cadence || "update");
  const days = cadence.startsWith("days:") ? cadence.slice(5) : "7";
  const page = plan.page && plan.page.url ? plan.page : null;
  $("#learn-body").innerHTML = `
    ${kind === "text" && !editing && page ? `<fieldset class="learn-field"><legend>What to learn</legend>
      <label class="checkbox"><input type="radio" name="learn-source" value="text" checked> Only the passage you selected</label>
      <label class="checkbox"><input type="radio" name="learn-source" value="page"> The page it is on:
        <code>${escapeHtml(page.url)}</code></label></fieldset>` : ""}
    <div class="learn-where">${kind === "text" ? `<blockquote class="xp-lesson-text">${escapeHtml(
      String(plan.text || "").slice(0, 600))}</blockquote>` : `<code>${escapeHtml(plan.source || "")}</code>`}</div>
    <label class="learn-field">Title <input type="text" id="learn-title-in" value="${escapeHtml(plan.title || "")}"></label>
    <label class="learn-field">What it is <textarea id="learn-about" rows="2">${escapeHtml(plan.about || "")}</textarea></label>
    <fieldset class="learn-field"><legend>Whose it is</legend>
      <label class="checkbox"><input type="radio" name="learn-whose" value="mine"${plan.whose === "mine"
        ? " checked" : ""}> Mine - learned in full, its decisions as mine</label>
      <label class="checkbox"><input type="radio" name="learn-whose" value="others"${plan.whose !== "mine"
        ? " checked" : ""}> Someone else's - a reference I endorse, never taken as mine</label>
      ${plan.whose_why ? `<p class="muted">${escapeHtml(plan.whose_why)}</p>` : ""}</fieldset>
    <fieldset class="learn-field"><legend>What to learn of it</legend>
      ${["cases", "rules", "reference"].map((key) => `<label class="checkbox"><input type="checkbox"
        name="learn-what" value="${key}"${(plan.learn || []).includes(key) ? " checked" : ""}> ${escapeHtml(
        { cases: "Cases - what it looks like, how it is made", rules: "Rules - what work should follow",
          reference: "A reference - to look at while making something" }[key])}</label>`).join("")}</fieldset>
    <label class="learn-field">From what angle, and why
      <textarea id="learn-angle" rows="3" placeholder="${escapeHtml(
        "What of it to learn - of someone else's work, only this is learned")}">${escapeHtml(plan.angle || "")}</textarea></label>
    ${scopes.length ? `<label class="learn-field">How much of it <select id="learn-scope">${scopes.map(([key, said]) =>
      `<option value="${key}"${plan.scope === key ? " selected" : ""}>${escapeHtml(said)}</option>`).join("")}</select></label>` : ""}
    <label class="learn-field">How often <select id="learn-cadence">
      <option value="once"${cadence === "once" ? " selected" : ""}>Once</option>
      <option value="update"${cadence === "update" ? " selected" : ""}>At every learning update</option>
      <option value="days"${cadence.startsWith("days:") ? " selected" : ""}>Every few days</option></select>
      <input type="number" id="learn-days" min="1" max="365" value="${escapeHtml(days)}"${cadence.startsWith("days:")
        ? "" : " hidden"}></label>
    ${plan.estimate ? `<p class="${plan.large ? "delegate-error" : "muted"}">${escapeHtml(
      `About ${Number(plan.estimate).toLocaleString()} tokens a reading`)}${plan.large
      ? ` - ${escapeHtml("large: marked so in the list")}` : ""}.</p>` : ""}
    ${plan.not_learned ? `<p class="muted">${escapeHtml(`Left out: ${plan.not_learned}`)}</p>` : ""}
    ${(plan.questions || []).length ? `<div class="muted">To say in the angle, if you know:<ul>${plan.questions.map((q) =>
      `<li>${escapeHtml(q)}</li>`).join("")}</ul></div>` : ""}`;
  const select = $("#learn-cadence");
  select?.addEventListener("change", () => { $("#learn-days").hidden = select.value !== "days"; });
  learnButtons(editing ? "edit" : "plan");
}

function learnRead() {
  const plan = Object.assign({}, learnState.plan || {});
  const chosen = document.querySelector('input[name="learn-source"]:checked');
  if (chosen && chosen.value === "page" && plan.page && plan.page.url) {
    plan.kind = "url";
    plan.source = plan.page.url;
    plan.text = "";
    plan.scope = "page";
  }
  plan.title = ($("#learn-title-in") || {}).value || plan.title;
  plan.about = ($("#learn-about") || {}).value || "";
  plan.whose = (document.querySelector('input[name="learn-whose"]:checked') || {}).value || plan.whose;
  plan.learn = [...document.querySelectorAll('input[name="learn-what"]:checked')].map((one) => one.value);
  plan.angle = ($("#learn-angle") || {}).value || "";
  if ($("#learn-scope")) plan.scope = $("#learn-scope").value;
  const cadence = ($("#learn-cadence") || {}).value || "update";
  plan.cadence = cadence === "days" ? `days:${Math.max(1, Number($("#learn-days").value || 7))}` : cadence;
  return plan;
}

async function learnAdd(now) {
  const plan = learnRead();
  if (!(plan.learn || []).length) { toast("Choose what to learn of it", "error"); return; }
  try {
    const said = await learningPost({ action: "item_add", plan, learn_now: now });
    learningState.data = said;
    $("#learn-box").close();
    toast(said.note || (now ? "Added - learning it now" : "Added to the learning list"));
    drawLearning();
  } catch (err) {
    toast(err.message, "error");
  }
}

async function learnSave() {
  if (!learnState.editing) return;
  const plan = learnRead();
  try {
    learningState.data = await learningPost({ action: "item_change", item: learnState.editing, plan });
    $("#learn-box").close();
    toast("Saved: read so from the next update");
    drawLearning();
  } catch (err) {
    toast(err.message, "error");
  }
}

function learnEdit(itemId) {
  const lessons = (learningState.data || {}).lessons || {};
  const item = [...(lessons.added || []), ...(lessons.heartbeat || [])].find((one) => one.id === itemId);
  if (!item) return;
  learnState.editing = itemId;
  const dialog = $("#learn-box");
  if (!dialog.open) dialog.showModal();
  learnShowPlan(Object.assign({}, item, { page: null }), true);
}

document.addEventListener("click", async (event) => {
  const target = event.target;
  if (!target || !target.closest || !target.closest("#learn-box")) return;
  const id = target.id;
  if (id === "learn-cancel") {
    clearTimeout(learnState.timer);
    $("#learn-box").close();
  } else if (id === "learn-pick-folder") {
    const path = await xpChooseFolder("A folder to learn from");
    if (path) { learnState.picked = { kind: "folder", source: path }; $("#learn-picked").textContent = path; }
  } else if (id === "learn-pick-file") {
    try {
      const chosen = await api.post("/api/learning/choose-file", {});
      if (chosen.selected) {
        learnState.picked = { kind: "file", source: chosen.selected };
        $("#learn-picked").textContent = chosen.selected;
      }
    } catch (err) { toast(err.message, "error"); }
  } else if (id === "learn-draft") {
    const url = ($("#learn-url") || {}).value || "";
    const text = ($("#learn-text") || {}).value || "";
    const handed = url.trim() ? { kind: "url", source: url.trim() }
      : text.trim() ? { kind: "text", text } : learnState.picked;
    if (!handed) { toast("Give an address, a passage, a folder or a file", "error"); return; }
    learnState.picked = null;
    await learnDraft(handed);
  } else if (id === "learn-add") {
    await learnAdd(false);
  } else if (id === "learn-now") {
    await learnAdd(true);
  } else if (id === "learn-save") {
    await learnSave();
  }
});

/* WHAT IT HAS LEARNED, counted: the places, cases, judgments, reasons and
   terms, each with what it is made of (store.breakdown). */
function learningLearnedHtml(s) {
  const b = s.breakdown || {};
  const counts = s.counts || {};
  const n = (value) => Number(value || 0).toLocaleString();
  const sum = (group) => Object.values(group || {}).reduce((a, v) => a + Number(v || 0), 0);
  // Each part its own phrase - a text of the tables - in the order given;
  // the parts of a line are put side by side, with commas.
  const parts = (group, words) => words.filter(([key]) => Number((group || {})[key] || 0))
    .map(([key, said]) => said(n(group[key])));
  const ASPECT = [["output", (v) => `${v} on what output you want`],
                  ["habit", (v) => `${v} on how you work`],
                  ["requirement", (v) => `${v} on what is asked for`],
                  ["evaluation", (v) => `${v} on how you evaluate`]];
  const SOURCE = [["stated", (v) => `${v} in your own words`], ["inferred", (v) => `${v} inferred from what you did`],
                  ["adopted", (v) => `${v} adopted from work you endorse`]];
  const rows = [];
  const places = b.places || {};
  if (sum(places)) {
    rows.push(["Places read", n(sum(places)), [
      parts(places, [["work", (v) => `${v} Work projects`], ["place", (v) => `${v} folders you listed or worked in`],
                     ["rules", (v) => `${v} of your rules for every agent`]]),
      [`cases found in ${n((b.places_with_cases || {}).all)} of them`]]]);
  }
  rows.push(["Cases", n(counts.cases),
    [["pieces of work you made, each with how it was made and how you judged it"]]]);
  if (Number(counts.judgments || 0)) {
    const state = b.judgments_state || {};
    rows.push(["Judgments", n(counts.judgments), [
      parts(b.judgments_strength, [["written", (v) => `${v} you wrote down as rules`],
        ["changed", (v) => `${v} you changed or turned down`],
        ["approved", (v) => `${v} you said yes to`], ["accepted", (v) => `${v} you let stand`],
        ["noted", (v) => `${v} from an agent's memory of your words`]]),
      parts(b.judgments_aspect, ASPECT),
      parts(state, [["linked", (v) => `${v} explained by a reason`],
                    ["pool", (v) => `${v} not explained by a reason yet`]])]]);
  }
  if (Number(counts.reasons || 0) || Number(counts.forming || 0)) {
    const competing = Number((b.reasons_competing || {}).all || 0);
    rows.push(["Reasons", `${n(counts.reasons)} in use`, [
      parts(b.reasons_in_use, SOURCE).concat(competing
        ? [`${n(competing)} competing with another`] : []),
      parts(b.reasons_aspect, ASPECT)]]);
  }
  if (Number(counts.forming || 0)) {
    rows.push(["Reasons forming", n(counts.forming), [parts(b.reasons_forming, SOURCE),
      ["used only once they hold"]]]);
  }
  const terms = b.terms || {};
  if (sum(terms)) {
    rows.push(["Terms", n(sum(terms)), [parts(terms, [["fixed", (v) => `${v} set from the start`],
                                                      ["trial", (v) => `${v} on trial`]])]]);
  }
  return `<h3>What it has learned</h3>
    <table class="xp-learn-counts"><tbody>${rows.map(([name, count, lines]) => `<tr>
      <th scope="row">${escapeHtml(name)}</th><td class="xp-learn-count">${escapeHtml(count)}</td>
      <td>${lines.filter((line) => line.length).map((line) => `<div>${line.map((part) =>
        `<span>${escapeHtml(part)}</span>`).join(", ")}</div>`).join("")}</td>
    </tr>`).join("")}</tbody></table>`;
}

/* WHAT LEARNING SPENT: a bar a day, the last thirty - its calls' tokens. */
function learningChartHtml(s) {
  const byDay = {};
  for (const row of s.spending || []) {
    const day = byDay[row.day] || (byDay[row.day] = { tokens: 0, calls: 0, parts: [] });
    day.tokens += Number(row.tokens || 0);
    day.calls += Number(row.calls || 0);
    day.parts.push(`${String(row.task || "").replace("learning_", "")}: ${
      Number(row.tokens || 0).toLocaleString()}`);
  }
  const days = Object.keys(byDay).sort();
  if (!days.length) return `<h3>What it spent</h3><p class="muted">No tokens spent on learning yet.</p>`;
  const most = Math.max(...days.map((d) => byDay[d].tokens), 1);
  const bars = days.map((d) => {
    const one = byDay[d];
    const height = Math.max(2, Math.round(one.tokens / most * 100));
    const said = `${d}: ${one.tokens.toLocaleString()} tokens, ${one.calls} calls (${one.parts.join(", ")})`;
    return `<span class="xp-learn-bar" style="height:${height}%" title="${escapeHtml(said)}"
      aria-label="${escapeHtml(said)}"></span>`;
  }).join("");
  const total = days.reduce((sum, d) => sum + byDay[d].tokens, 0);
  return `<h3>What it spent</h3>
    <p class="muted">${total.toLocaleString()} tokens in the last 30 days - a bar a day.</p>
    <div class="xp-learn-chart" role="img" aria-label="Tokens spent on learning, a bar a day">${bars}</div>`;
}

function drawLearning() {
  const host = $("#xp-learn");
  const s = learningState.data;
  if (!host || !s) return;
  clearTimeout(learningState.timer);
  const going = (s.update && ["running", "waiting"].includes(s.update.state))
    || (s.index && s.index.building);
  if (going && activeTab === "learning") {
    learningState.timer = setTimeout(loadLearning, 3000);
  }
  const counts = s.counts || {};
  const status = $("#xp-status");
  if (status) {
    status.textContent = `Learned: ${Number(counts.cases || 0)} cases, ${
      Number(counts.reasons || 0)} reasons${counts.forming ? ` (${counts.forming} forming)` : ""}`;
  }
  // Not while a time or the limit is being typed.
  if (host.contains(document.activeElement) && document.activeElement.matches("input")) return;
  host.innerHTML = `<h2>Learning</h2>
    <p class="muted">Your own work - and work of others you endorse - read into cases and the
      reasons behind how you judge it: what a Work run's reviewer asks of when it checks the
      agent's work.</p>
    <div class="xp-learn-row">
      <label class="checkbox"><input type="checkbox" id="xp-learn-on"${s.on ? " checked" : ""}>
        Learn by itself</label>
      <span class="xp-learn-times"><strong>each day at</strong></span>
    </div>
    <p class="muted">${s.on && (s.times || []).length
      ? `Next: ${escapeHtml(localStamp(s.next))}.`
      : s.on ? "Add a time for it to learn by itself."
        : "Off: it learns only when you press Update now."}</p>
    ${learningUpdateHtml(s)}
    <div class="xp-learn-row"><label>Tokens a day, at most
      <input type="number" id="xp-learn-limit" min="0" step="100000"
        value="${Number(s.daily_tokens || 0)}"></label>
      <span class="muted">0: no limit</span></div>
    ${learningPendingHtml(s)}
    ${learningLessonsHtml(s)}
    ${learningLearnedHtml(s)}
    ${learningChartHtml(s)}`;
  const control = recommendTimesControl((s.times || []).join(", "),
    "No time set: it learns only when you press Update now.");
  let waiting = null;
  control.addEventListener("change", () => {
    clearTimeout(waiting);
    waiting = setTimeout(() => learningDo({ action: "auto", times: control.value },
      control.value ? "Saved: learning each day at " + control.value
        : "Saved: no time - it learns only when you ask"), 600);
  });
  const line = host.querySelector(".xp-learn-times");
  line.appendChild(control);
  if (s.time_zone) {
    line.insertAdjacentHTML("beforeend", `<span class="muted">(${escapeHtml(s.time_zone)})</span>`);
  }
  host.querySelector("#xp-learn-on").addEventListener("change", (event) =>
    learningDo({ action: "auto", on: event.target.checked },
      event.target.checked ? "Learning by itself at the times set" : "Learning only when you ask"));
  host.querySelector("#xp-learn-limit").addEventListener("change", (event) =>
    learningDo({ action: "auto", daily_tokens: Math.max(0, Number(event.target.value || 0)) },
      "Saved: the day's limit"));
}

document.addEventListener("click", async (event) => {
  const target = event.target;
  if (!target || !target.closest || !target.closest("#xp-learn")) return;
  const act = target.dataset.learn;
  if (act === "update") {
    await learningDo({ action: "update" }, "Learning: updating now");
  } else if (act === "pause") {
    await learningDo({ action: "pause" }, "Paused");
  } else if (act === "continue") {
    await learningDo({ action: "continue" }, "Carrying on");
  } else if (target.dataset.learnAdd) {
    const kind = target.dataset.learnAdd;
    const path = kind === "folder" ? await xpChooseFolder("A folder of your work to learn from") : "";
    if (kind === "folder" && !path) return;
    await learningDo({ action: "add", kind, path }, "Added");
  } else if (target.dataset.learnRemove) {
    learningState.removing = target.dataset.learnRemove;
    drawLearning();
  } else if (target.dataset.learnRemoveNo) {
    learningState.removing = null;
    drawLearning();
  } else if (target.dataset.learnRemoveYes) {
    learningState.removing = null;
    await learningDo({ action: "remove", path: target.dataset.learnRemoveYes }, "Removed");
  } else if (target.dataset.learnExclude) {
    await learningDo({ action: "exclude", path: target.dataset.learnExclude,
                       out: Boolean(target.dataset.out) });
  } else if (target.dataset.learnToggle) {
    const on = Boolean(target.dataset.on);
    await learningDo({ action: on ? "activate" : "deactivate", unit: target.dataset.learnToggle },
      on ? "Turned on: read again, and used" : "Turned off: not read, and not used");
  } else if (target.dataset.learnDelete) {
    learningState.removing = target.dataset.learnDelete;
    drawLearning();
  } else if (target.dataset.learnDeleteYes) {
    learningState.removing = null;
    await learningDo({ action: "delete", unit: target.dataset.learnDeleteYes },
      "Deleted, and put on the list of what is never learned");
  } else if (target.dataset.learnDetail) {
    await learningOpenDetail(target.dataset.learnDetail);
  } else if (target.dataset.learnAccept) {
    await learningDo({ action: "accept", item: target.dataset.learnAccept }, "Kept: it is used now");
  } else if (target.dataset.learnReject) {
    await learningDo({ action: "reject", item: target.dataset.learnReject },
      "Not kept: what was learned from it is gone, and it is turned off");
  } else if (target.dataset.learnNeverOff) {
    await learningDo({ action: "never_off", key: target.dataset.learnNeverOff },
      "Taken off the list: it may be learned again");
  } else if (target.dataset.learnNew) {
    openLearnBox();
  } else if (target.dataset.learnEdit) {
    learnEdit(target.dataset.learnEdit);
  }
});

/* The list of projects and tasks - not while a description in it is being
   written: then once that is left. */
function xpDrawUnits() {
  if (xpEditing("#xp-units")) { xpDefer("#xp-units", xpDrawUnits); return; }
  // DELEGATED WORK AMONG THE REST, by when it last moved - work just handed
  // over is at the top (its run counts, `units`) - marked as delegated.
  const row = (unit) => `
    <div class="xp-unit${unit.id === experienceState.unit ? " selected" : ""}${
      unit.active ? " xp-unit-active" : ""}"
      data-xp-row="${escapeHtml(unit.id)}"
      title="${unit.active ? "At work now - found from what you are doing"
        : "Learned from; not at work now"}">
      ${experienceState.removing === unit.id ? `<div class="xp-unit-ask" role="alert">
        Remove this project? It leaves this list, and its folders are no longer
        read for learning. What was already learned from it stays.
        <button type="button" class="small danger" data-xp-remove-yes="${escapeHtml(unit.id)}">Remove</button>
        <button type="button" class="small secondary" data-xp-remove-no="${escapeHtml(unit.id)}">Keep it</button>
      </div>` : `<button type="button" class="xp-unit-remove link" data-xp-remove="${
        escapeHtml(unit.id)}" title="Remove this project from Work">Remove</button>`}
      <div class="xp-unit-open" data-xp-unit="${escapeHtml(unit.id)}" role="button"
        tabindex="0">
        ${escapeHtml(xpName(unit.name))}
        ${unit.delegated ? `<span class="muted xp-unit-delegated">delegated</span>` : ""}
        ${unit.way ? `<span class="xp-way xp-way-${escapeHtml(unit.way)}">${
          unit.way === "quick" ? "Quick" : "Thorough"}</span>` : ""}
        ${(unit.names_before || []).length ? `<span class="muted xp-unit-was">earlier called ${
          escapeHtml(unit.names_before.join("; "))}</span>` : ""}
        <span class="xp-unit-run" data-xp-unit-run="${escapeHtml(unit.id)}">${xpUnitRunBadge(unit.id)}</span>
        ${unit.kind === "new project" ? "" : `<span class="muted">${unit.stages} stages${unit.pending
          ? ` · ${unit.pending} states not yet learned` : ""}</span>`}
        ${unit.last_active ? `<span class="muted xp-unit-when">last active ${
          escapeHtml(localStamp(unit.last_active))}</span>` : ""}
        ${unit.kind === "directory" ? `<span class="xp-unit-folder muted">${unit.processed_until
          ? `read to ${escapeHtml(localStamp(unit.processed_until))}`
          : "not read yet"}</span>` : unit.workspace ? `<span class="xp-unit-folder muted" title="${escapeHtml(
          unit.workspace)}">${escapeHtml(unit.workspace)}${unit.processed_until
          ? ` · read to ${escapeHtml(localStamp(unit.processed_until))}`
          : " · not read yet"}${unit.workspace_origin === "detected" ? " (found)" : ""}</span>
          <span class="xp-unit-folder-edit" data-xp-folder-unit="${escapeHtml(unit.id)}"
            role="button" tabindex="0">change</span>` : ""}
      </div>
      ${xpAbout(unit, "row")}
      ${unit.kind === "directory" ? xpFolderList(unit.id, unit.paths || [unit.workspace]) : ""}
      ${xpLearning(unit)}
    </div>`;
  xpPut($("#xp-units"), experienceState.units.map(row).join("")
    || `<p class="muted">Nothing shown in the overview yet.</p>`);
}

/* THE RUNS GOING NOW, AND HOW - asked every few seconds, whichever tab is
   open: each project in the list says whether its run is going, paused or
   waiting for you, and the Experience tabs say how many runs wait for you -
   so a run that needs you is seen at a glance. */
const workGoing = { byUnit: {} };

function xpUnitRunBadge(unitId) {
  const one = workGoing.byUnit[unitId];
  if (!one) return "";
  const waiting = one.state === "waiting_for_you";
  const words = waiting ? (one.waiting_on === "model" ? "waiting for you: the model"
    : "waiting for you") : (XP_LIVE_STATE[one.state] || one.state);
  return `<span class="xp-live-state xp-live-state-${escapeHtml(one.state)}" title="${
    escapeHtml(one.why || one.activity || "")}">${escapeHtml(words)}</span>`;
}

function setTabWaiting(tab, count) {
  const button = $(`#tabs button[data-tab="${tab}"]`);
  if (!button) return;
  let badge = button.querySelector(".tab-wait");
  if (!count) {
    if (badge) badge.remove();
    return;
  }
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "tab-wait";
    button.appendChild(badge);
  }
  badge.textContent = `${count} waiting`;
  badge.title = `${count} run${count === 1 ? "" : "s"} waiting for you`;
}

async function watchWorkGoing() {
  try {
    if (!document.hidden) {
      const { going } = await api.get("/api/work/going");
      const before = workGoing.byUnit;
      workGoing.byUnit = {};
      let mine = 0;
      let debug = 0;
      (going || []).forEach((one) => {
        if (!one.debug) workGoing.byUnit[one.unit] = one;
        if (one.state === "waiting_for_you") {
          if (one.debug) debug += 1; else mine += 1;
        }
      });
      // A TO-DO'S WORK, TRACKED: where each version stands, as it moves;
      // one that ended - asked again, to say how.
      const tracked = new Set(ovTodos.flatMap((one) => ovTodoVersions(one)
        .map((version) => version.unit).filter(Boolean)));
      if (typeof delegateFolderCheck === "function" && $("#delegate") && $("#delegate").open) {
        delegateFolderCheck();
      }
      // WORK'S LINE OF THE GOING RUN, as it is now - paused, resumed or
      // stopped from the to-do, say; one that ended, the panel asked again.
      const titled = experienceState.titleGoing;
      if (titled && typeof xpDrawTitleRun === "function") {
        if (workGoing.byUnit[titled.unit_id]) xpDrawTitleRun(titled);
        else if (activeTab === "experience") xpLoadRuns();
      }
      if (Object.keys(before).some((unit) => tracked.has(unit) && !workGoing.byUnit[unit])) {
        loadTodos();
      } else if (typeof ovPlaceTodos === "function") {
        ovPlaceTodos();
      }
      $$("[data-xp-unit-run]").forEach((span) => {
        const html = xpUnitRunBadge(span.dataset.xpUnitRun);
        if (span._xpHtml !== xpShows(html)) {
          span.innerHTML = html;
          span._xpHtml = xpShows(html);
        }
      });
      setTabWaiting("experience", mine);
      setTabWaiting("xdebug", debug);
    }
  } catch (err) {
    /* the next look catches up */
  }
  setTimeout(watchWorkGoing, 4000);
}
setTimeout(watchWorkGoing, 1000);

/* THE CHOSEN PIECE OF WORK, drawn: its tree, and the agents' work on it.
   Choosing another redraws only this - the list is already there. */
async function xpOpenUnit(force = false) {
  $$("#xp-units .xp-unit").forEach((row) => row.classList.toggle("selected",
    (row.querySelector("[data-xp-unit]") || {}).dataset?.xpUnit === experienceState.unit));
  if (experienceState.unit) await xpLoadGraph(experienceState.unit, force);
  await xpLoadRuns(force);
}

/* THE USER'S OWN PROJECTS: folders they choose, processed when they ask -
   Process the first time, Update after that, which reads only what changed
   since the last time. */
async function xpLoadProjects() {
  let projects = [];
  try {
    projects = (await api.get("/api/experience/projects")).projects || [];
  } catch (err) {
    $("#xp-projects").innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  const when = (value) => localStamp(value);
  xpPut($("#xp-projects"), projects.map((p) => {
    const going = p.progress || {};
    return `<div class="xp-project" data-xp-project="${escapeHtml(p.id)}">
      <div class="xp-project-name"><strong>${escapeHtml(xpName(p.name))}</strong>
        <span class="muted">${p.stages} stages</span></div>
      ${p.description ? `<div class="xp-about"><span class="xp-about-label">Your
        description</span> <span class="xp-about-words">${escapeHtml(p.description)}</span></div>`
        : ""}
      <div class="xp-project-folders">${xpFolderList(p.id, p.paths)}</div>
      <div class="muted">${p.processed_until ? `Read up to ${escapeHtml(
        when(p.processed_until))}` : "Not read yet"} - learned from its row above.</div>
      <div class="xp-project-actions">
        <button type="button" class="small secondary" data-xp-project-remove="${escapeHtml(p.id)}">Remove</button>
      </div>
    </div>`;
  }).join("") || `<p class="muted">None yet.</p>`);
  experienceState.projects = projects;
}

/* A NEW PROJECT: its title, what it is for, and its folders - one or more,
   each chosen in the machine's own folder dialog, listed with × to take it
   out again before it is made. */
const xpNew = { paths: [] };

function xpNewPaths() {
  $("#xp-new-paths").innerHTML = xpNew.paths.length ? xpNew.paths.map((f, i) =>
    `<li class="xp-folder"><code title="${escapeHtml(f)}">${escapeHtml(f)}</code>
      <button type="button" class="xp-folder-x" data-xp-new-drop="${i}"
        title="Take this folder out" aria-label="Take ${escapeHtml(f)} out">×</button></li>`).join("")
    : `<li class="muted">no folder chosen</li>`;
}

/* A folder, from the machine's own dialog - or typed, where there is none. */
async function xpChooseFolder(title) {
  try {
    const chosen = await api.post("/api/settings/choose-directory", { title });
    // Said when it could not open, rather than a click that does nothing.
    if (chosen.available === false && chosen.reason) toast(chosen.reason, "error");
    return chosen.available === false ? (window.prompt(`${title}:`, "") || "").trim()
      : (chosen.selected || "");
  } catch (err) {
    toast(err.message);
    return "";
  }
}

document.addEventListener("click", async (event) => {
  const id = event.target.id;
  if (id === "xp-plus") {
    $("#xp-new").hidden = !$("#xp-new").hidden;
    return;
  }
  if (id === "xp-new-cancel") {
    $("#xp-new").hidden = true;
    return;
  }
  if (id === "xp-new-choose") {
    const path = await xpChooseFolder("A folder of the project");
    if (path && !xpNew.paths.includes(path)) xpNew.paths.push(path);
    xpNewPaths();
    return;
  }
  const dropAt = event.target.closest && event.target.closest("[data-xp-new-drop]");
  if (dropAt) {
    xpNew.paths.splice(Number(dropAt.dataset.xpNewDrop), 1);
    xpNewPaths();
    return;
  }
  if (id !== "xp-new-create") return;
  const name = ($("#xp-new-title").value || "").trim();
  const description = ($("#xp-new-description").value || "").trim();
  if (!name) { toast("Give it a title."); return; }
  if (!xpNew.paths.length) { toast("Add at least one folder."); return; }
  try {
    const said = await api.post("/api/experience/projects",
      { action: "create", name, description, paths: [...xpNew.paths] });
    if (said.error) { toast(said.error); return; }
    $("#xp-new-title").value = "";
    $("#xp-new-description").value = "";
    xpNew.paths = [];
    xpNewPaths();
    $("#xp-new").hidden = true;
    experienceState.unit = (said.project || {}).unit_id || experienceState.unit;
    await loadExperience(false);
  } catch (err) {
    toast(err.message);
  }
});

/* THE MOST LATELY ACTIVE FIRST - the order is the server's (units()). */

/* A project's folders as they are now - from its row, or the projects. */
function xpPathsOf(unit) {
  const row = (experienceState.units || []).find((u) => u.id === unit) || {};
  const made = (experienceState.projects || []).find((p) => p.id === unit) || {};
  return [...(row.paths || made.paths || [])];
}

async function xpSetPaths(unit, paths) {
  try {
    const out = await api.post("/api/experience/projects", { action: "set", unit, paths });
    if (out.error) toast(out.error);
  } catch (err) {
    toast(err.message);
  }
  await loadExperience(false);
}

document.addEventListener("click", async (event) => {
  const addAt = event.target.closest("[data-xp-folder-add]");
  const xAt = event.target.closest("[data-xp-folder-remove]");
  const yesAt = event.target.closest("[data-xp-folder-yes]");
  const noAt = event.target.closest("[data-xp-folder-no]");
  if (addAt || xAt || yesAt || noAt) {
    // Inside a row of the list: the row itself is not chosen by it.
    event.stopPropagation();
  }
  if (addAt) {
    const unit = addAt.dataset.xpFolderAdd;
    const path = await xpChooseFolder("Another folder of the project");
    const now = xpPathsOf(unit);
    if (path && !now.includes(path)) await xpSetPaths(unit, [...now, path]);
    return;
  }
  if (xAt || noAt) {
    // Asked in place first: the × turns into the question.
    experienceState.folderAsk = xAt ? { unit: xAt.dataset.xpFolderRemove,
                                        path: xAt.dataset.xpFolderPath } : null;
    xpDrawUnits();
    await xpLoadProjects();
    return;
  }
  if (yesAt) {
    const unit = yesAt.dataset.xpFolderYes;
    experienceState.folderAsk = null;
    await xpSetPaths(unit, xpPathsOf(unit).filter((one) => one !== yesAt.dataset.xpFolderPath));
    return;
  }
  const aboutEditAt = event.target.closest("[data-xp-about-edit]");
  const aboutSaveAt = event.target.closest("[data-xp-about-save]");
  const aboutCancelAt = event.target.closest("[data-xp-about-cancel]");
  if (aboutEditAt || aboutSaveAt || aboutCancelAt) {
    event.stopPropagation();
    if (aboutEditAt) {
      const unit = aboutEditAt.dataset.xpAboutEdit;
      experienceState.aboutEditing = { unit, where: aboutEditAt.dataset.xpAboutWhere };
      xpRedrawAbout();
      const box = $(`[data-xp-about-box="${CSS.escape(unit)}"] textarea`);
      if (box) {
        box.focus({ preventScroll: true });
        box.setSelectionRange(box.value.length, box.value.length);
      }
      return;
    }
    const unit = (aboutSaveAt || aboutCancelAt).dataset[aboutSaveAt ? "xpAboutSave" : "xpAboutCancel"];
    const box = $(`[data-xp-about-text="${CSS.escape(unit)}"]`);
    const description = box ? box.value : "";
    experienceState.aboutEditing = null;
    if (aboutSaveAt) {
      try {
        const out = await api.post("/api/experience/projects",
          { action: "update", unit, description });
        if (out.error) toast(out.error);
      } catch (err) {
        toast(err.message);
      }
      await loadExperience(false);
    } else {
      xpRedrawAbout();
    }
    return;
  }
  const removeAt = event.target.closest("[data-xp-project-remove]");
  if (removeAt) {
    const out = await api.post("/api/experience/projects",
      { action: "remove", unit: removeAt.dataset.xpProjectRemove });
    if (out.error) toast(out.error);
    await xpLoadProjects();
    await loadExperience(false);
  }
});

// What is typed in a description is kept as it is typed: a redraw of the
// list does not lose it.
document.addEventListener("input", (event) => {
  const box = event.target.closest && event.target.closest("[data-xp-about-text]");
  if (box && experienceState.aboutEditing) experienceState.aboutEditing.text = box.value;
});

/* Both places a description is shown, drawn again. */
function xpRedrawAbout() {
  xpDrawUnits();
  xpDrawUnitAbout();
}

/* The opened project's description, at its top - not while it is being
   written. */
function xpDrawUnitAbout() {
  const box = $("#xp-unit-about");
  if (!box) return;
  if (xpEditing("#xp-unit-about")) { xpDefer("#xp-unit-about", xpDrawUnitAbout); return; }
  const unit = (experienceState.units || []).find((u) => u.id === experienceState.unit);
  xpPut(box, unit ? xpAbout(unit, "top") : "");
}







/* WHERE EACH STAGE SITS: one column right of everything it depends on - the
   stages its edges point at, and the attempt before it in its card - so the
   picture shows dependency and nothing else. Not time: placed by when they
   happened, a week with no work drew a long edge and a busy afternoon a
   pile of dots on top of each other. Columns are evenly spaced. */
function xpColumns(stages, edges) {
  const needs = new Map(stages.map((s) => [s.id, []]));
  const lastIn = new Map();
  stages.forEach((s) => {
    const card = s.card_id || "";
    if (lastIn.has(card)) needs.get(s.id).push(lastIn.get(card));
    lastIn.set(card, s.id);
  });
  (edges || []).forEach((e) => {
    if (needs.has(e.source) && needs.has(e.target) && e.source !== e.target) {
      needs.get(e.source).push(e.target);
    }
  });
  const column = new Map();
  const placing = new Set();
  const place = (id) => {
    if (column.has(id)) return column.get(id);
    if (placing.has(id)) return 0;          // a loop: never drawn twice
    placing.add(id);
    const before = needs.get(id).map(place);
    placing.delete(id);
    const at = before.length ? Math.max(...before) + 1 : 0;
    column.set(id, at);
    return at;
  };
  stages.forEach((s) => place(s.id));
  return column;
}

/* THE ROWS ARE THE CARDS: the root, then each card after the one it is a
   piece of, indented by how deep it sits. A stage - an attempt - is drawn in
   its card's row; one written before there were cards, in the root's. */
function xpRows(graph) {
  const cards = graph.cards || [];
  if (!cards.length) return { rows: [{ id: "", title: "", depth: 0 }], rowOf: () => 0 };
  const at = new Map(cards.map((c, i) => [c.id, i]));
  return { rows: cards, rowOf: (s) => (at.has(s.card_id) ? at.get(s.card_id) : 0) };
}

const XP_CARD_MARK = { done: "✓ ", set_aside: "⤳ ", open: "○ ", working: "" };

/* WHERE A TREE IS DRAWN: one piece of work, all of them, and the agents' own
   work on one - each with the box its card opens in and what is chosen. */
const XP_VIEWS = {
  unit: { graphs: () => [experienceState.graph || {}], box: "#xp-stage",
          frame: "#xp-graph", stage: "stage", card: "card" },
  work: { graphs: () => [experienceState.workTree || {}], box: "#xp-work-stage",
          frame: "#xp-work-tree", stage: "workStage", card: "workCard", work: true },
};

function xpCardLabel(card, x, y, where, chars) {
  if (!card.id) return "";
  const pad = "  ".repeat(card.depth || 0);
  const chosen = experienceState[XP_VIEWS[where].card];
  return `<text x="${x}" y="${y}" xml:space="preserve" class="xp-card-row xp-card-${
    escapeHtml(card.status || "open")}${card.depth ? "" : " xp-card-root"}${
    chosen === card.id ? " selected" : ""}" data-xp-card="${escapeHtml(card.id)}"
    data-xp-where="${where}">${escapeHtml(pad + (XP_CARD_MARK[card.status] || "")
      // The root is the project or task itself: its name alone.
      + (card.depth ? card.title || card.statement || ""
        : xpName(card.title || card.statement || "")).slice(0, chars - pad.length))}<title>${
    escapeHtml(`${card.level}: ${card.statement || card.title}`)}</title></text>`;
}


function xpDot(stage, cx, cy, r, where) {
  const verdict = (stage.evaluation || {}).verdict || "";
  const chosen = experienceState[XP_VIEWS[where].stage];
  return `<g class="xp-dot${chosen === stage.id ? " selected" : ""}"
    data-xp-stage="${escapeHtml(stage.id)}" data-xp-where="${where}"
    tabindex="0" role="button">
    <circle cx="${cx.toFixed(1)}" cy="${cy}" r="${r}"
      fill="${XP_KIND_COLOUR[stage.kind] || "#888"}"/>
    ${verdict && r >= 7 ? `<text x="${cx.toFixed(1)}" y="${cy + 3}"
      class="xp-verdict">${verdict.startsWith("rej") ? "✗"
        : verdict.startsWith("acc") || verdict === "pass" ? "✓" : "~"}</text>` : ""}
    <title>${escapeHtml(`${stage.kind}: ${stage.summary}`)}</title></g>`;
}

/* AN ARROWHEAD OF ITS OWN for each drawing. One id shared by every drawing
   on the page meant every arrow used the first drawing's head - and where
   that drawing was hidden (another tab, a way not in front), no arrow had a
   head at all. */
let xpMarkerCount = 0;
function xpMarkerId(base) {
  xpMarkerCount += 1;
  return `${base}-${xpMarkerCount}`;
}

/* WHAT A DRAWING SHOWS, its arrowheads' numbers left out: each draw takes a
   new number, so the same picture drawn again never read as the same - and
   every "nothing changed, leave it" check redrew it anyway, taking the
   reader's selection and scroll with it. */
const XP_MARKER_NUMBER = /\b((?:xp-head|sb-arrow|sb-tt-arrow)-)\d+/g;
function xpShows(html) {
  return String(html).replace(XP_MARKER_NUMBER, "$1");
}

/* A DIRECTED EDGE: from the stage depended on to the stage that depends on
   it - the way the work went - stopping short of the dot so the arrowhead
   shows. */
function xpArrow(x1, y1, x2, y2, r, kind, head = "xp-head") {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const length = Math.hypot(dx, dy) || 1;
  const end = Math.max(0, length - r - 2);
  return `<line x1="${x1.toFixed(1)}" y1="${y1}" x2="${(x1 + dx * end / length)
    .toFixed(1)}" y2="${(y1 + dy * end / length).toFixed(1)}"
    class="xp-edge xp-edge-${escapeHtml(kind || "")}" marker-end="url(#${head})">
    <title>${escapeHtml(kind || "")}</title></line>`;
}

function xpHead(id) {
  return `<defs><marker id="${id}" viewBox="0 0 8 8" refX="7" refY="4"
  markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L8 4 L0 8 z"
  class="xp-head"/></marker></defs>`;
}

function xpKey() {
  return `<p class="sb-key">${Object.entries(XP_KIND_COLOUR).map(([kind, colour]) =>
    `<span><svg width="11" height="11"><circle cx="5.5" cy="5.5" r="5"
      fill="${colour}"/></svg> ${kind}</span>`).join("")}</p>`;
}

/* -- one piece of work ---------------------------------------------------- */
async function xpLoadGraph(unitId, chosen = false) {
  // CHOSEN BY THE USER: the panel is switched at once - the project's name,
  // and a wheel turning while its picture is read - not left on the last
  // one until it comes. And only the latest asked is drawn: a slow answer
  // for a project clicked past is dropped.
  const asked = (experienceState.graphAsked || 0) + 1;
  experienceState.graphAsked = asked;
  if (chosen) {
    const unit = experienceState.units.find((one) => one.id === unitId);
    if (unit) $("#xp-graph-title").textContent = xpName(unit.name);
  }
  let graph;
  try {
    graph = await api.get(
      xpScoped(`/api/experience/graph?unit=${encodeURIComponent(unitId)}`));
  } catch (err) {
    return;
  }
  if (asked !== experienceState.graphAsked || unitId !== experienceState.unit) return;
  experienceState.graph = graph;
  // A project or a task is headed by its name, nothing more.
  $("#xp-graph-title").textContent = xpName(graph.unit.name);
  xpDrawUnitAbout();
  // WHAT WAS LEARNED OF THE USER'S OWN WORK IS NOT DRAWN (2026-10-18): it
  // is kept, and the agents use it; the panel shows the agent's own Work
  // on the project (#xp-work). The project's record is still read, for its
  // name, what it is about and its folders.
}

/* One row per card, a dot per stage - an attempt at that card - coloured by
   its kind in the column its dependencies put it in, and a line from each
   stage to what it depends on. */
function xpGraphSvg(graph, where = "unit") {
  const stages = graph.stages || [];
  if (!stages.length) {
    return `<p class="muted">Nothing learned of this yet - Start learning
      it in Projects.</p>`;
  }
  const { rows, rowOf } = xpRows(graph);
  const column = xpColumns(stages, graph.edges);
  const left = 260;
  const gap = 44;
  const width = Math.max(700, left + 40 + Math.max(0, ...column.values()) * gap);
  const step = 30;
  const height = rows.length * step + 30;
  const x = (s) => left + 12 + (column.get(s.id) || 0) * gap;
  const y = (s) => 20 + rowOf(s) * step;
  const at = new Map(stages.map((s) => [s.id, s]));
  const head = xpMarkerId("xp-head");
  const lines = (graph.edges || []).map((e) => {
    const a = at.get(e.source); const b = at.get(e.target);
    if (!a || !b) return "";
    return xpArrow(x(b), y(b), x(a), y(a), 8, e.kind, head);
  }).join("");
  const labels = rows.map((card, i) => xpCardLabel(card, 6, 24 + i * step,
    where, 38)).join("");
  const dots = stages.map((s) => xpDot(s, x(s), y(s), 8, where)).join("");
  return `${xpKey()}<div class="xp-frame"><svg width="${width}" height="${height}">${
    xpHead(head)}${lines}${labels}${dots}</svg></div>`;
}

/* WHAT THE STAGE SAYS ABOUT THE WORK: what it was for, what was done, what
   it was judged by, how it came out - and where everything it made and used
   is, each with what it is a good reference for. */
/* A STAGE'S TEXT, ITS REFERENCES POINTED AT: escaped, and each "[r2]" in
   it a link to that reference in the stage's list. */
function xpCite(text) {
  return escapeHtml(String(text || "")).replace(/\[(r\d+)\]/g,
    (_whole, id) => `<a href="#" class="xp-cite" data-xp-cite="${id}">[${id}]</a>`);
}

function xpStageWork(work, stage) {
  const FROM = { user: "you", stage: "an earlier stage", material: "material",
                 workspace: "the folder" };
  const decided = work.decision || {};
  const output = work.output || {};
  const made = (stage || {}).deliverable || {};
  const refs = xpRefList(work.references || []);
  const named = (id) => {
    const found = [experienceState.graph || {}, experienceState.workTree || {},
      ...Object.values(experienceState.xdTrees || {})]
      .flatMap((g) => g.stages || []).find((s) => s.id === id);
    return found ? found.summary : "";
  };
  return [
    (work.input || []).length ? `<p><strong>Input</strong> - what the decision
      was based on:</p><ul class="xp-work-list">${work.input.map((one) => `<li>
        ${one.from ? `<span class="xp-ref-kind">${escapeHtml(FROM[one.from]
          || one.from)}</span> ` : ""}${xpCite(one.what || "")}${one.ref
          && !String(one.what || "").includes(`[${one.ref}]`)
          ? ` <a href="#" class="xp-cite" data-xp-cite="${escapeHtml(one.ref)}">[${
            escapeHtml(one.ref)}]</a>` : ""}
        ${one.stage && named(one.stage) ? `<div class="muted">From: ${
          escapeHtml(named(one.stage).slice(0, 160))}</div>` : ""}
        ${one.location || one.material || (one.copies && Object.keys(one.copies).length)
          ? `<ul class="xp-work-list xp-refs xp-input-ref">${xpRefList([{ ...one,
              what: "", location: one.location || "", event: one.material || "" }])}</ul>`
          : ""}</li>`).join("")}</ul>` : "",
    decided.chose ? `<div class="xp-decision"><p><strong>Decision</strong>
      <span class="xp-by xp-by-${escapeHtml(decided.by || "unknown")}">${
        decided.by === "user" ? "made by you" : decided.by === "agent"
          ? "made by the agent" : "who decided is not recorded"}</span></p>
      <p>${xpCite(decided.about || "")}</p>
      ${(decided.options || []).length ? `<div class="muted">Options: ${
        decided.options.map(xpCite).join("; ")}</div>` : ""}
      <div>Chose: ${xpCite(decided.chose)}</div>
      ${decided.why ? `<div class="muted">Why: ${xpCite(decided.why)}</div>` : ""}
      ${decided.rejected ? `<div class="muted">Turned down: ${
        xpCite(decided.rejected)}</div>` : ""}</div>` : "",
    output.what || (output.specification || []).length || output.design
      || (output.rationale || {}).why || made.excerpt || (made.references || []).length
      ? `<p><strong>Output</strong>${output.what ? `: ${xpCite(output.what)}` : ""}</p>
      ${(output.specification || []).length ? `<p class="xp-sub">Specification -
        what it had to satisfy:</p><ul class="xp-work-list">${output.specification
          .map((one) => `<li>${xpCite(one.requirement || "")}
            <div class="muted">${xpCite(one.source || "")}</div></li>`).join("")}</ul>`
        : ""}
      ${output.design ? `<p class="xp-sub">Design:</p><p>${
        xpCite(output.design)}</p>` : ""}
      ${(output.rationale || {}).why ? `<p class="xp-sub">Rationale <span class="xp-by">${
        output.rationale.from === "user" ? "your words" : "inferred"}</span></p><p>${
        xpCite(output.rationale.why)}</p>` : ""}
      ${made.excerpt || (made.references || []).length ? `<p class="xp-sub">Example${
        made.type ? ` (${escapeHtml(made.type)})` : ""}: ${escapeHtml(made.excerpt || "")}</p>
        ${(made.references || []).length ? `<ul class="xp-work-list xp-refs">${
          xpRefList(made.references)}</ul>` : ""}` : ""}` : "",
    refs ? `<p><strong>References:</strong></p>
      <ul class="xp-work-list xp-refs">${refs}</ul>` : "",
  ].join("");
}

/* References as a list: each with whether it can be opened, and the copies
   kept of it - for a stage's references and for what it produced alike. */
function xpRefList(references) {
  const ACCESS = { local: "on this computer", public: "public page",
                   "sign-in": "needs your sign-in", "screen-only": "seen on screen" };
  return references.map((r) => `<li${r.id ? ` data-xp-ref-id="${escapeHtml(r.id)}"` : ""}>
      ${r.id ? `<span class="xp-ref-id">${escapeHtml(r.id)}</span>` : ""}
      <span class="xp-ref-kind">${escapeHtml(r.kind || "")}</span>
      <code class="xp-ref-where">${escapeHtml(r.location || "")}</code>
      ${r.access ? `<span class="xp-ref-access xp-ref-${escapeHtml(r.access)}">${
        escapeHtml(ACCESS[r.access] || r.access)}</span>` : ""}
      ${r.what ? `<span class="muted">- ${escapeHtml(r.what)}</span>` : ""}
      ${r.event ? `<span class="muted">(${escapeHtml(r.event)})</span>` : ""}
      ${Object.entries(r.copies || {}).map(([which, path]) =>
        `<div class="xp-ref-copy">${escapeHtml(
          { text: "Its text", raw: "The file as it was", picture: "Picture" }[which]
          || which)}: <code>${escapeHtml(path)}</code></div>`).join("")}
      ${r.copied === "now" ? `<div class="xp-ref-copy">(copied when the stage was
        written - the file as it is now, not as it was then)</div>` : ""}
      ${r.transcript ? `<div class="xp-ref-copy">The whole conversation: <code>${
        escapeHtml(r.transcript)}</code></div>` : ""}
      ${(r.files || []).length ? `<div class="xp-ref-copy">Files changed (${
        r.files.length}): ${r.files.slice(0, 12).map((f) => `<code>${
        escapeHtml(f)}</code>`).join(" ")}${r.files.length > 12 ? " …" : ""}</div>` : ""}
      ${r.local ? `<div class="xp-ref-copy">Local copy: <code>${
        escapeHtml(r.local)}</code></div>` : ""}
      ${r.snapshot ? `<div class="xp-ref-copy">What you saw, saved: <code>${
        escapeHtml(r.snapshot)}</code></div>` : ""}
      ${(r.screenshots || []).length ? `<div class="xp-ref-copy">Pictures (${
        r.screenshots.length}): ${r.screenshots.map((one) => `<code>${
        escapeHtml(one)}</code>`).join(" ")}</div>` : ""}
    </li>`).join("");
}

/* WHAT THE STAGE SHOWS ABOUT THE USER: the natures written from it - how
   they judge a result, what they prefer - each with the pattern it was
   grouped into. */
function xpStageNatures(stage) {
  const natures = stage.natures || [];
  if (!natures.length) {
    return `<p class="muted xp-stage-natures">${(stage.notes || {}).natured
      ? "Read for what it shows about you: nothing new."
      : "Not yet read for what it shows about you."}</p>`;
  }
  // Grouped by what each is about: how you judge, what you want made,
  // the rest of how you work, who you are.
  const ASPECTS = [["evaluation", "How you evaluate"], ["output", "What output you want"],
                   ["", "Written before natures were only these two"]];
  const known = new Set(ASPECTS.map(([key]) => key));
  const groups = ASPECTS.map(([key, name]) => [name, natures.filter((n) =>
    (known.has(n.aspect || "") ? n.aspect || "" : "") === key)]).filter(([, list]) => list.length);
  return `<div class="xp-stage-natures"><p><strong>What it shows about you
    (${natures.length}):</strong> <span class="muted">click one for the whole of it</span></p>${
      groups.map(([name, list]) => `<p class="muted">${
      escapeHtml(name)}</p><ul class="xp-work-list">${list.map((n) => `<li>
      <span class="xp-nature-open" data-xp-nature="${escapeHtml(n.id)}" role="button"
        tabindex="0">${n.kind && n.kind !== "work" ? `<span class="xp-ref-kind">${
        escapeHtml(n.kind)}</span> ` : ""}${escapeHtml(n.title)}</span>
      <div class="xp-nature-detail" data-xp-nature-detail="${escapeHtml(n.id)}" hidden></div>
      ${(n.example || {}).what ? `<div class="xp-nature-example">For example: ${
        escapeHtml(n.example.what)}${(n.example.references || []).filter((r) => r.location)
          .map((r) => ` <code>${escapeHtml(r.location)}</code>`).join("")}</div>` : ""}
      ${n.pattern ? `<div class="muted">In the pattern: ${escapeHtml(n.pattern)}</div>`
        : `<div class="muted">Not yet grouped into a pattern.</div>`}</li>`).join("")}
    </ul>`).join("")}</div>`;
}

/* EVERY CASE A NATURE WAS SEEN IN, newest first: what was done, in which
   project and task, when, the user's own words in it, quoted, what came of
   it, and every place it can be opened - each as text. The words are the
   case: a nature is what the user said and did, not the agent's account of
   it. All of them, in a list that scrolls when it is long. */
function xpNatureExamples(n) {
  const examples = n.examples || [];
  const total = Number(n.examples_total || examples.length);
  const day = (value) => localStamp(value, "date");
  const KIND = { state: "a state" };
  return `<p><strong>Examples (${total}):</strong>${total > examples.length
    ? ` <span class="muted">the newest ${examples.length} shown</span>` : ""}</p>
    <ol class="xp-nature-examples">${examples.map((e) => {
      const span = day(e.began) && day(e.ended) && day(e.began) !== day(e.ended)
        ? `${day(e.began)} to ${day(e.ended)}` : day(e.began || e.ended);
      const where = [e.project, e.task].filter(Boolean)
        .filter((one, i, all) => all.indexOf(one) === i);
      return `<li class="xp-nature-example-row" data-xp-example="${escapeHtml(e.id || "")}">
        <div class="xp-nx-head"><strong>${escapeHtml(e.title || e.what
          || (e.missing ? "(this lesson is no longer kept)" : "(untitled)"))}</strong>
          <span class="muted">${[KIND[e.kind] || e.kind, span].filter(Boolean)
            .map(escapeHtml).join(" · ")}</span></div>
        ${where.length ? `<div class="xp-nx-where muted">${where.map(escapeHtml)
          .join(" › ")}</div>` : ""}
        ${e.what && e.what !== e.title ? `<div class="xp-nx-label">${e.own_example
          ? "<strong>For example:</strong> " : ""}${escapeHtml(e.what)}</div>` : ""}
        ${e.said ? `<div class="xp-nx-said"><span class="muted">You said:</span>${
          String(e.said).split("\n").filter((one) => one.trim()).map((one) =>
            `<blockquote>“${escapeHtml(one.trim())}”</blockquote>`).join("")}</div>` : ""}
        ${e.summary ? `<div class="xp-nx-summary">${escapeHtml(e.summary)}</div>` : ""}
        ${e.deliverable ? `<div class="muted">Came of it: ${escapeHtml(e.deliverable)}</div>` : ""}
        ${(e.locations || []).length ? `<ul class="xp-nx-places">${e.locations.map((r) =>
          `<li><code>${escapeHtml(r.location)}</code>${r.what ? ` <span class="muted">- ${
            escapeHtml(r.what)}</span>` : ""}</li>`).join("")}</ul>` : ""}
      </li>`;
    }).join("")}</ol>`;
}

/* WHAT A NATURE SAID BEFORE: each earlier version, newest first, with when
   it was written and replaced, why, and the natures merged into it or the
   one it was split from. */
function xpNatureHistory(n) {
  const history = n.history || [];
  const day = (value) => localStamp(value, "date");
  const named = (one) => escapeHtml((one || {}).title || (one || {}).id || "");
  return `<details class="xp-nature-history"><summary>History (${history.length
    ? `${history.length} earlier version${history.length === 1 ? "" : "s"}`
    : "no earlier versions"})</summary>
    ${history.length ? `<ol class="xp-nature-versions">${history.map((v) => `<li>
      <div><strong>${escapeHtml(v.title || "")}</strong></div>
      <div class="muted">written ${escapeHtml(day(v.at) || "?")}${v.replaced_at
        ? ` · replaced ${escapeHtml(day(v.replaced_at))}` : ""}${v.run
        ? ` · run ${escapeHtml(v.run)}` : ""}${v.by ? ` · by ${escapeHtml(v.by)}` : ""}</div>
      ${v.why ? `<div>Why it changed: ${escapeHtml(v.why)}</div>` : ""}
      ${(v.merged_from || []).length ? `<div class="muted">Merged from: ${
        v.merged_from.map(named).join("; ")}</div>` : ""}
      ${(v.split_from || {}).id ? `<div class="muted">Split from: ${named(v.split_from)}</div>` : ""}
      ${v.summary ? `<div>${escapeHtml(v.summary)}</div>` : ""}
      ${v.body ? `<details><summary class="muted">That version whole</summary>
        <pre class="record-body">${escapeHtml(v.body)}</pre></details>` : ""}
    </li>`).join("")}</ol>`
    : `<p class="muted">No earlier versions: it still says what it said when it
      was first written${n.created_at ? `, ${escapeHtml(day(n.created_at))}` : ""}.</p>`}
  </details>`;
}

/* A NATURE, OPENED where it is listed: what it says, the case it was seen
   in and where that can be opened, the pattern and principle it is grouped
   into - each with when it was last active - and every lesson it is
   attached to, any of them opened from here. */
async function xpOpenNature(id, at) {
  const box = at.parentElement.querySelector(`[data-xp-nature-detail="${CSS.escape(id)}"]`);
  if (!box) return;
  if (!box.hidden) { box.hidden = true; return; }
  box.hidden = false;
  box.innerHTML = `<p class="muted">Reading…</p>`;
  let n;
  try {
    n = await api.get(`/api/experience/nature?id=${encodeURIComponent(id)}`);
  } catch (err) {
    box.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  const ex = n.example || {};
  const when = (value) => (value ? localStamp(value, "date") : "not seen yet");
  const examples = n.examples || [];
  // The lessons open in the Experience tab's own card; elsewhere - the
  // overview - the examples already say what each was.
  const inExperience = Boolean(at.closest("#experience"));
  box.innerHTML = `
    ${n.summary ? `<p>${escapeHtml(n.summary)}</p>` : ""}
    ${examples.length ? xpNatureExamples(n)
      : ex.what ? `<p><strong>For example:</strong> ${escapeHtml(ex.what)}</p>
      ${(ex.references || []).length ? `<ul class="xp-refs">${xpRefList(ex.references)}</ul>` : ""}`
      : `<p class="muted">No example kept with it.</p>`}
    ${xpNatureHistory(n)}
    ${(n.pattern || {}).id ? `<p><strong>In the pattern:</strong> ${escapeHtml(
      n.pattern.statement || "(not yet named)")} <span class="muted">· last active ${
      escapeHtml(when(n.pattern.last_active))}</span></p>`
      : `<p class="muted">Not yet grouped into a pattern.</p>`}
    ${(n.principle || {}).id ? `<p><strong>Under the principle:</strong> ${escapeHtml(
      n.principle.statement || "(not yet named)")} <span class="muted">· last active ${
      escapeHtml(when(n.principle.last_active))}</span></p>` : ""}
    ${inExperience ? `<p><strong>Lessons it is attached to (${(n.lessons || []).length}):</strong></p>
    <ul class="xp-work-list">${(n.lessons || []).map((s) => `<li><a href="#"
      data-xp-stage="${escapeHtml(s.id)}" data-xp-where="unit">${escapeHtml(s.kind)}</a>
      ${escapeHtml(localStamp(s.began, "date"))} - ${escapeHtml(
        String(s.summary || "").slice(0, 160))}</li>`).join("")}</ul>` : ""}
    <details><summary class="muted">The whole record</summary>
      <pre class="record-body">${escapeHtml(n.body || "")}</pre>
      <p class="muted">${escapeHtml(n.source || "")}${n.written_by
        ? ` · written with ${escapeHtml(n.written_by)}` : ""}</p></details>`;
}

/* A CARD: what is true when it is done, how it is judged, why the card
   above needs it - and its attempts, in order, each opening its stage. */
function xpShowCard(cardId, where) {
  const view = XP_VIEWS[where];
  const graphs = view.graphs();
  let card = null;
  let graph = null;
  graphs.forEach((g) => {
    const found = (g.cards || []).find((c) => c.id === cardId);
    if (found) { card = found; graph = g; }
  });
  const box = $(view.box);
  if (!card) { box.innerHTML = ""; return; }
  experienceState[view.card] = cardId;
  experienceState[view.stage] = null;
  const cards = graph.cards || [];
  const parent = cards.find((c) => c.id === card.parent_id);
  const under = cards.filter((c) => c.parent_id === card.id);
  const attempts = (graph.stages || []).filter((s) => s.card_id === card.id
    || (!card.depth && !cards.some((c) => c.id === s.card_id)));
  const replaced = cards.find((c) => c.id === card.replaced_by);
  const checked = card.checked_by || {};
  const STATUS = { open: "not started", working: "under way", done: "done",
                   set_aside: "set aside" };
  box.innerHTML = `<div class="xp-stage-card xp-card-card">
    <h3>${escapeHtml(card.level)}${card.type ? ` · ${escapeHtml(card.type)}` : ""} · ${
      escapeHtml(STATUS[card.status] || card.status)}${
      where === "all" ? ` · ${escapeHtml(graph.unit.name)}` : ""}</h3>
    <p><strong>${escapeHtml(card.title || "")}</strong></p>
    ${card.statement ? `<p><strong>Done means:</strong> ${xpCite(card.statement)}</p>` : ""}
    ${parent ? `<p class="muted">A piece of: <a href="#" data-xp-card="${
      escapeHtml(parent.id)}" data-xp-where="${where}">${escapeHtml(parent.title
      || parent.statement || "")}</a></p>` : ""}
    ${(card.why || {}).why ? `<p><strong>Why it is needed${card.why.from === "user"
      ? " (your words)" : " (inferred)"}:</strong> ${xpCite(card.why.why)}</p>` : ""}
    ${(card.specification || []).length ? `<p><strong>What you required:</strong></p>
      <ul class="xp-work-list">${card.specification.map((one) => `<li>${
        xpCite(one.requirement || "")}<div class="muted">${xpCite(one.source || "")}</div></li>`)
        .join("")}</ul>` : ""}
    ${(checked.criteria || []).length ? `<p><strong>What it must meet</strong>
      <span class="muted">- written by the reviewer, from your work</span></p>
      <ul class="xp-work-list">${checked.criteria.map((one) => `<li>${escapeHtml(one.text)}
        <div class="muted">backed by ${escapeHtml(one.backed_by || "own judgement")}${
        (one.because || []).length ? ` · ${one.because.map(escapeHtml).join(", ")}` : ""}</div></li>`)
        .join("")}</ul>
      ${checked.approach ? `<p><strong>How to go about it:</strong> ${
        escapeHtml(checked.approach)}</p>` : ""}`
      : checked.by ? `<p><strong>Checked by ${escapeHtml(
      { test: "a test", user: "you", agent: "an agent" }[checked.by] || checked.by)}:</strong> ${
      xpCite(checked.what || "")}</p>` : ""}
    ${card.status_why ? `<p class="muted">${escapeHtml(STATUS[card.status] || card.status)}: ${
      escapeHtml(card.status_why)}${replaced ? ` - replaced by <a href="#" data-xp-card="${
      escapeHtml(replaced.id)}" data-xp-where="${where}">${escapeHtml(replaced.title)}</a>`
      : ""}</p>` : ""}
    ${under.length ? `<p><strong>Its pieces (${under.length}):</strong></p>
      <ul class="xp-work-list">${under.map((c) => `<li><a href="#" data-xp-card="${
        escapeHtml(c.id)}" data-xp-where="${where}">${escapeHtml(c.title || c.statement)}</a>
        <span class="muted">${escapeHtml(STATUS[c.status] || c.status)}</span></li>`).join("")}</ul>` : ""}
    <p><strong>Attempts (${attempts.length}):</strong></p>
    ${attempts.length ? `<ol class="xp-work-list">${attempts.map((s) => `<li>
      <a href="#" data-xp-stage="${escapeHtml(s.id)}" data-xp-where="${where}"><span
        style="color:${XP_KIND_COLOUR[s.kind] || "inherit"}">${escapeHtml(s.kind)}</span>${
        (s.evaluation || {}).verdict ? ` (${escapeHtml(s.evaluation.verdict)})` : ""}</a>
      - ${escapeHtml(String(s.summary || "").slice(0, 220))}</li>`).join("")}</ol>`
      : `<p class="muted">None yet.</p>`}
    ${(card.refs || []).length ? `<p><strong>References</strong></p>
      <ul class="xp-refs">${xpRefList(card.refs)}</ul>` : ""}
    ${xpWriter(card.written_by) ? `<p class="muted">written by ${
      escapeHtml(xpWriter(card.written_by))}</p>` : ""}
  </div>`;
  const frame = view.frame;
  $$(`${frame} [data-xp-card]`).forEach((g) =>
    g.classList.toggle("selected", g.dataset.xpCard === cardId));
  $$(`${frame} [data-xp-stage]`).forEach((g) => g.classList.remove("selected"));
}

/* WHAT A STAGE IS FOUND BY - worked out by code when it was written: its
   strongest words, and the places it worked. What a reviewer looking for
   past work like the step in hand matches it on. */
function xpFoundBy(stage) {
  const found = stage.found_by || {};
  const words = found.words || [];
  const places = found.places || [];
  if (!words.length && !places.length) return "";
  return `<p class="muted xp-found-by"><strong>Found by:</strong> ${
    words.map(escapeHtml).join(", ")}${places.length ? ` · <strong>where:</strong> ${
    places.map(escapeHtml).join(", ")}` : ""}</p>`;
}

/* EVERY REVIEW OF A STAGE THE AGENTS DID: of each version proposed, and of
   the result - the verdict, and each comment with what it rests on. */
function xpReviews(stage) {
  const notes = stage.notes || {};
  const reviews = notes.reviews || [];
  const proposals = notes.proposals || [];
  // A round: what it claims, each with its evidence, and the checks it failed.
  const claims = (notes.claims || []).length ? `<p><strong>What the round claims
    (${notes.claims.length}):</strong></p><ul class="xp-work-list">${notes.claims.map((c) =>
    `<li>${escapeHtml(c.claim || "")}<div class="muted">${(c.evidence || []).map((e) =>
      e.path ? `<code>${escapeHtml(e.path)}</code>` : `ran <code>${escapeHtml(e.command || "")}</code>`)
      .join(" · ")}</div></li>`).join("")}</ul>` : "";
  const failed = (notes.checks_failed || []).length ? `<p><strong>Failed the checks</strong>
    - sent back without a review:</p><ul class="xp-work-list">${notes.checks_failed.map(
    (one) => `<li>${escapeHtml(one)}</li>`).join("")}</ul>` : "";
  const cut = notes.interrupted ? `<p class="muted">Cut off by a limit - what it did
    so far is kept, and the rest is on the run's to-do list.</p>` : "";
  if (!reviews.length) return notes.instruction ? `<p class="muted">What you asked.</p>`
    : `${claims}${failed}${cut}`;
  return `${claims}${failed}${cut}<div class="xp-reviews">
    ${proposals.length > 1 ? `<p class="muted">Proposed ${proposals.length} times:
      ${proposals.map((one, i) => `<span>${i + 1}. ${escapeHtml(
        String(one.summary || "").slice(0, 120))}</span>`).join(" ")}</p>` : ""}
    ${notes.dropped ? `<p><strong>Dropped by the reviewer</strong> - the approach
      was set aside.</p>` : ""}
    <p><strong>The reviewer (${reviews.length}):</strong></p>
    <ol class="xp-work-list">${reviews.map((r) => `<li>
      <strong>${escapeHtml(r.verdict || "")}</strong> · on ${escapeHtml(r.on || "")}${
        r.round ? ` (round ${escapeHtml(String(r.round))})` : ""}
      ${(r.comments || []).map((c) => `<div>${escapeHtml(c.say || "")}
        <span class="muted">- ${escapeHtml([].concat(c.because || []).join(", ")
          || "own judgement")}</span></div>`).join("")}
      ${r.change ? `<div class="muted">Change: ${escapeHtml(r.change)}</div>` : ""}
      ${(r.checked || []).length ? `<div class="muted">Looked at: ${
        r.checked.map(escapeHtml).join("; ")}</div>` : ""}
    </li>`).join("")}</ol></div>`;
}

/* WHAT A STAGE SHOWED OF THE USER, and what it is found by: asked for when
   its card is opened - the pictures carry the stages alone. Drawn again
   once they come, if it is still the one open. */
async function xpStageDetail(stage, stageId, where) {
  if (stage.natures !== undefined || stage.detailAsked) return;
  stage.detailAsked = true;
  try {
    const said = await api.get(`/api/experience/stage_detail?stage=${encodeURIComponent(stageId)}`);
    stage.natures = said.natures || [];
    stage.found_by = said.found_by || {};
  } catch (err) {
    stage.natures = [];
  }
  const view = XP_VIEWS[where];
  if (view && experienceState[view.stage] === stageId) xpShowStage(stageId, where);
}

function xpShowStage(stageId, where) {
  const view = XP_VIEWS[where];
  const graphs = view.graphs();
  let stage = null;
  let graph = null;
  graphs.forEach((g) => {
    const found = (g.stages || []).find((s) => s.id === stageId);
    if (found) { stage = found; graph = g; }
  });
  const box = $(view.box);
  if (!stage) { box.innerHTML = ""; return; }
  experienceState[view.stage] = stageId;
  const said = stage.evaluation || {};
  const task = (graph.tasks || []).find((t) => t.id === stage.task_id);
  const card = (graph.cards || []).find((c) => c.id === stage.card_id)
    || (graph.cards || [])[0];
  experienceState[view.card] = null;
  box.innerHTML = `<div class="xp-stage-card">
    <h3><span style="color:${XP_KIND_COLOUR[stage.kind] || "inherit"}">${
      escapeHtml(stage.kind)}</span> · ${escapeHtml(stage.medium || "")}${
      where === "all" ? ` · ${escapeHtml(graph.unit.name)}` : ""}</h3>
    ${card ? `<p class="muted">An attempt at: <a href="#" data-xp-card="${
      escapeHtml(card.id)}" data-xp-where="${where}">${escapeHtml(card.title
      || card.statement || "")}</a> (${escapeHtml(card.level || "")})</p>` : ""}
    <p>${xpCite(stage.summary)}</p>
    ${xpStageWork(stage.work || {}, stage)}
    ${said.verdict ? `<p><strong>Verdict:</strong> ${escapeHtml(said.verdict)}</p>` : ""}
    ${(XP_VIEWS[where] || {}).work ? xpReviews(stage) : stage.natures === undefined
      ? `<p class="muted xp-stage-natures">Reading what it shows about you…</p>`
      : xpStageNatures(stage)}
    ${xpFoundBy(stage)}
    ${(said.criteria || []).length ? `<p><strong>Checked:</strong> ${
      said.criteria.map(escapeHtml).join("; ")}</p>` : ""}
    ${(said.words || []).length && !(XP_VIEWS[where] || {}).work ? `<p><strong>Your words:</strong> ${
      said.words.map((w) => `“${escapeHtml(w)}”`).join(" ")}</p>` : ""}
    <p class="muted">${escapeHtml(localStamp(stage.began))}
      · ${(stage.states || []).length} states${task ? ` · task: ${
      escapeHtml(task.title)}` : ""}${xpWriter(stage.written_by)
      ? ` · written by ${escapeHtml(xpWriter(stage.written_by))}` : ""}</p>
  </div>`;
  const frame = view.frame;
  $$(`${frame} [data-xp-stage]`).forEach((g) =>
    g.classList.toggle("selected", g.dataset.xpStage === stageId));
  $$(`${frame} [data-xp-card]`).forEach((g) => g.classList.remove("selected"));
  if (!view.work) xpStageDetail(stage, stageId, where);
}


/* A TREE OF NODES, drawn left to right: you, then your principles, then -
   for each principle opened - its patterns beside it. Clicking a principle
   opens it (and closes it again); clicking any node shows its card below,
   as a state's does. A principle is sized by what supports it and wears an
   emblem of its own, as a task does. */
const XP_PRINCIPLE_COLOUR = "#8e6bd8";
const XP_PATTERN_COLOUR = "#3d6be5";
const XP_UNNAMED_COLOUR = "#8a8f98";
const XP_KIND_SAID = {
  work: ["Work nature", "your taste and standards in work, and how you like to work together - what the agent plans your work by"],
  personal: ["Personal nature", "your habits, rhythm and interests - kept for a companion, not used to plan work"],
  "": ["Not sorted yet", "built before there were two kinds; sorted on the next pattern round"],
};








/* -- the agent working on it ---------------------------------------------------- */
/* ONE RUN OF THE AGENTS: its results first - the slides and where each
   deliverable is - then what is left, the contract, the decisions made for
   you, the final review, and the rounds. */
function xpRun(run, idle, first) {
  const plan = run.plan || {};
  const contract = plan.contract || {};
  const deck = plan.deck || null;
  const todo = plan.todo || null;
  const list = (items, draw) => items.length
    ? `<ul class="xp-work-list">${items.map(draw).join("")}</ul>` : "";
  const SUPPORT = { strong: "strongly backed by your past work",
                    some: "partly backed by your past work",
                    none: "not backed by your past work" };
  // Packages: how this run asks, and every request it made. One waiting for
  // your answer is asked in the live session, below.
  const book = plan.packages || {};
  const requests = book.requests || [];
  const names = (items) => (items || []).map((one) => `<code>${escapeHtml(one)}</code>`).join(", ");
  // Its versions: how many, the head, and the tree; and the version Continue
  // is set to go on from, if one was picked.
  const kept = xpVersionsState();
  const versions = run.versions || {};
  const from = kept.from[run.id] || "";
  const id = escapeHtml(run.id);
  // THE VERSION PICKED in its tree, if it is not the head: the run is shown
  // as it stood then - its contract, its slides, its files - under a line
  // that says so, with the way back to the latest.
  const seen = xpVersionSeen(run);
  // THE CONTRACT IN FORCE - the one the line the run is on holds - always
  // shown, on top: from the server with each deliverable's card as it
  // stands; else from the plan alone.
  const inForce = run.contract_in_force || (contract.goal ? {
    goal: contract.goal, scope: contract.scope || [], out_of_scope: contract.out_of_scope || [],
    instructions: contract.instructions || [], branch: versions.branch || "",
    deliverables: (contract.deliverables || []).map((d) => ({ ...d, criteria: [] })),
  } : null);
  const shownContract = seen
    ? ((seen.contract || {}).goal ? xpContractBlock(seen.contract, `<h4 class="xp-contract-title muted">Contract
        at ${escapeHtml(seen.id || "")} - not in force</h4>`, seen.amended, `${run.id}@${seen.id}`, true)
      : `<p class="muted">No contract yet at ${escapeHtml(seen.id || "")}.</p>`)
    : inForce ? xpContractBlock(inForce, `<h4 class="xp-contract-title">Contract in force
      <span class="xp-contract-where">${escapeHtml(inForce.branch || "main")}${inForce.since
        ? `, since ${escapeHtml(inForce.since)}` : ""}</span></h4>`, inForce.amended,
      run.id, false) : "";
  const deckOpen = Boolean(kept.decks[run.id]);
  return `<details class="xp-run" data-xp-run-box="${id}" data-xp-keep="run:${id}"${
      run.alive || first ? " open" : ""}>
    <summary>${plan.way ? `<span class="xp-way xp-way-${escapeHtml(plan.way)}">${
        plan.way === "quick" ? "Quick" : "Thorough"}</span> ` : ""}<strong>${
        escapeHtml(run.status)}${run.alive && run.paused
        && run.status !== "paused" ? " · paused" : ""}</strong> ·
      ${escapeHtml(localStamp(run.started_at))} ·
      ${escapeHtml(run.instruction || "carry it forward")}</summary>
    ${seen ? `<p class="xp-version-showing" data-xp-keep="showing:${id}">Showing
      <strong>${escapeHtml(seen.id || "")}</strong> - ${escapeHtml(
        xpVersionMessage(xpVersionWithMessage(run.id, seen)).title || seen.label || "")}
      <span class="muted">(${escapeHtml(localStamp(seen.at))},
        ${escapeHtml(seen.branch || "main")})</span> ·
      <button type="button" class="small secondary" data-xp-version-latest="${id}">back to
        latest (head${versions.head ? ` ${escapeHtml(versions.head)}` : ""})</button></p>` : ""}
    ${seen ? "" : xpHanded(run)}
    ${shownContract ? `<div class="xp-contract-box" data-xp-keep="contract:${id}">${
      shownContract}</div>` : ""}
    ${!seen && inForce && (contract.amended || []).length ? `<p class="muted">Added by the reviewer
      during the work: ${contract.amended.map((a) => `round ${a.round}: ${(a.added || [])
      .map(escapeHtml).join(", ")}`).join("; ")}</p>` : ""}
    <p class="muted" data-xp-run-totals="${id}">${xpRunTotals(run)}</p>
    ${plan.unconfined && !xpIsDebugRun(run) ? `<p class="xp-warning">This session works
      without the sandbox. ${escapeHtml(XP_UNCONFINED_WARNING)}</p>` : ""}
    ${xpResultsRow(run)}
    ${run.folder ? `<p class="muted xp-logs-row">Logs: <code>${escapeHtml(run.log_dir || "")}</code>
      <button type="button" class="small" data-xp-open-logs="${id}"
        title="The project's run logs - a folder per run, by when it started, with its full transcript">Open
        log folder</button></p>` : ""}
    ${(run.transcript || []).length ? `<details class="xp-transcript"><summary class="muted">Full
      transcript: <span data-xp-transcript-count="${id}">${xpTranscriptCount(run)}</span>
      - every model call of the builder and the reviewer, whole, in the order made</summary>
      ${run.run_log_dir ? `<p class="muted">In <code>${escapeHtml(run.run_log_dir)}</code></p>` : ""}
      <ul class="xp-work-list xp-transcript-list" data-xp-transcript-list="${id}"
        data-xp-keep="transcript:${id}">${xpTranscriptList(run)}</ul>
    </details>` : ""}
    ${versions.count ? xpVersionsModule(run, idle) : ""}
    ${xpCallsSection(run)}
    ${xpLiveSection(run)}
    ${xpAnswer(run)}
    ${plan.way === "quick" && idle && !run.alive ? `<p class="xp-continue-row">
      <button type="button" class="small" data-xp-thorough="${id}">Continue thoroughly</button>
      <span class="muted">${(run.final || {}).thorough ? `It said: ${escapeHtml(
        run.final.thorough)} · ` : ""}a builder and a reviewer carry it on from what it
        made, with the limits above</span></p>` : ""}
    ${run.extendable && !from && idle ? `<div class="xp-continue-row xp-continue-next">
      ${xpContinueWords(run.id, true)}
      <button type="button" class="small" data-xp-continue="${id}"
        data-xp-continue-needs-words="1">Continue</button>
      ${xpContinueSound(run.id)}
      ${xpContinueUnconfined(run)}
      <span class="muted">from the finished work, with the limits above: the contract is
        amended by what you say - the goal too, if it calls for it - and the work goes on ·</span>
    </div>` : ""}
    ${(run.continuable || from) && idle && !run.alive ? xpResumeCard(run, from, versions, book)
      : ""}
    ${requests.length ? `<details class="xp-packages"><summary><strong>Packages
      (${requests.length} request${requests.length === 1 ? "" : "s"})</strong> - ${
      book.mode === "auto" ? "installed without asking you (Auto)"
        : "each request approved by you"}</summary>
      ${list(requests, (one) => `<li>${names(one.packages)}: <strong>${
        escapeHtml(one.status || "")}</strong>${(one.installed || []).length ? ` - ${
        one.installed.map((p) => escapeHtml(`${p.name} ${p.version}`)).join(", ")}` : ""}${
        one.error ? ` <span class="muted">${escapeHtml(one.error)}</span>` : ""}${
        one.note ? ` <span class="muted">(${escapeHtml(one.note)})</span>` : ""}
        <div class="muted">why: ${escapeHtml(one.why || "")}</div></li>`)}
    </details>` : ""}
    ${deck && !seen ? `<div class="xp-results" data-xp-keep="results:${id}">
      <h4>The results${deck.finished === false ? " - not finished" : ""}</h4>
      <p><button type="button" class="small secondary" data-xp-deck="${id}">${deckOpen
        ? "Hide the slides" : "Show the slides"}</button>
        <span class="muted">saved as <code>${escapeHtml(run.folder)}/runs/${
        id}/presentation.html</code></span></p>
      <div class="xp-deck" id="xp-deck-${id}"${deckOpen ? "" : " hidden"}>${deckOpen
        ? `<iframe class="xp-deck-frame" title="The results" src="/api/work/presentation?run=${
          encodeURIComponent(run.id)}"></iframe>` : ""}</div>
      <div class="xp-deliverables-box"><table class="xp-deliverables"><thead><tr><th>Deliverable</th><th>Where</th>
        <th>What it is</th></tr></thead><tbody>${(deck.deliverables || []).map((d) => `<tr>
        <td><strong>${escapeHtml(d.name || "")}</strong></td>
        <td><a href="#" data-xp-reveal="${escapeHtml(d.location || "")}"
          data-xp-run="${id}" title="Show it in its folder"><code>${
          escapeHtml(d.location || "")}</code></a></td>
        <td>${escapeHtml(d.what || "")}</td></tr>`).join("")}</tbody></table></div>
    </div>` : ""}
    ${todo && run.status !== "done" && !seen ? `<div class="xp-todo" data-xp-keep="todo:${id}"><h4>To do</h4>
      ${list(todo.next || [], (one) => `<li>${escapeHtml(one)}</li>`)}
      ${(todo.open || []).length ? `<p class="muted">Open cards:</p>${list(todo.open,
        (one) => `<li><strong>${escapeHtml(one.title)}</strong>${one.queued
          ? ` <span class="muted">(queued by the reviewer)</span>` : ""} - ${
          escapeHtml(one.done_means || "")}</li>`)}` : ""}
      ${(todo.blocked || []).length ? `<p class="muted">Blocked:</p>${list(todo.blocked,
        (one) => `<li>${escapeHtml(one.title)}: needs ${escapeHtml(one.missing)}</li>`)}` : ""}
    </div>` : ""}
    ${(plan.decisions || []).length ? `<details class="xp-decisions"><summary><strong>Decisions
      made for you (${plan.decisions.length})</strong></summary>
      ${list(plan.decisions, (one) => `<li><strong>${escapeHtml(one.about)}</strong>: ${
        escapeHtml(one.chose)}${one.over ? ` <span class="muted">over ${escapeHtml(one.over)}</span>`
        : ""} - ${escapeHtml(one.why || "")}<div class="muted">${escapeHtml(
        SUPPORT[one.support] || one.support || "")}${(one.because || []).length
        ? ` · ${one.because.map(escapeHtml).join(", ")}` : ""}</div></li>`)}
    </details>` : ""}
    ${((plan.final_review || {}).findings || []).length ? `<details class="xp-final-review"><summary><strong>The
      final review (${plan.final_review.findings.length})</strong></summary>
      ${list(plan.final_review.findings, (one) => `<li>(${escapeHtml(one.severity || "")}) ${
        escapeHtml(one.say || "")}${one.file ? ` <code>${escapeHtml(one.file)}</code>` : ""}</li>`)}
    </details>` : ""}
    ${(plan.rounds || []).length ? `<details class="xp-rounds"><summary><strong>Rounds (${
      plan.rounds.length})</strong></summary>
      <ol class="xp-work-list">${plan.rounds.map((one) => `<li><a href="#" data-xp-stage="${
        escapeHtml(one.stage)}" data-xp-where="work">${escapeHtml(one.card)}</a>: ${
        escapeHtml(one.objective || "")} - <strong>${escapeHtml(one.progress || "")}</strong>${
        one.full ? " (full review)" : ""}</li>`).join("")}</ol>
    </details>` : ""}
    <details class="xp-steps"><summary class="muted">What it did, step by step</summary>
      <ol class="xp-log" data-xp-run-log="${id}" data-xp-keep="steps:${id}">${xpRunLog(run)}</ol>
    </details>
  </details>`;
}

/* A run's tiny counters and its growing lists, each drawn by one function -
   for the run drawn whole, and for the same place changed in place while it
   goes (xpRunPatch). */
function xpRunTotals(run) {
  const plan = run.plan || {};
  const total = (run.final || {}).total || plan.total || {};
  const sessions = (plan.sessions || []).length;
  return `Folder: <code>${escapeHtml(run.folder)}</code> ·
      ${sessions} session${sessions === 1 ? "" : "s"} · ${escapeHtml(xpTokenSplit(total))},
      ${Number(total.calls || 0)} calls in all${(run.final || {}).reason
        ? ` · ${escapeHtml(run.final.reason)}` : ""}`;
}

function xpTranscriptCount(run) {
  const n = (run.transcript || []).length;
  return `${n} file${n === 1 ? "" : "s"}`;
}

function xpTranscriptList(run) {
  return (run.transcript || []).map((one) => `<li><code>${escapeHtml(one)}</code></li>`).join("");
}

function xpRunLog(run) {
  return (run.log || []).slice(-30).map((e) => `<li>${
    escapeHtml(localStamp(e.at, "time"))} ${escapeHtml(e.what)}${e.tool
      ? `: ${escapeHtml(e.tool)}` : ""}${e.verdict || e.progress ? `: ${
      escapeHtml(e.verdict || e.progress)}` : ""}${e.result
      ? ` - ${escapeHtml(String(e.result).slice(0, 200))}` : ""}</li>`).join("");
}

/* WHAT A SINGLE MODEL SAID - the Experience debugger's first way, which
   has no contract, no reviewer and no deck: its report, as it wrote it - the
   last one while it works, its final one once it says it is done. Changed
   in place as it writes a new one: the box keeps where you were reading. */
function xpAnswerParts(run) {
  const plan = run.plan || {};
  const said = (run.final || {}).answer || plan.last_report || "";
  const done = run.status === "done";
  return { said, title: done ? "Its final report" : "Its last report",
           next: !done && plan.next ? `Next, it said: ${plan.next}` : "" };
}

/* WHAT THE USER GETS, AND HOW (handed.py): each result the run handed
   over, as it will be opened - an email as a message, an event with its
   time - with what opens it: the user's own mail or calendar, filled in,
   for them to send or save; the text to copy; the file. Nothing is sent or
   saved for them. */
const xpHandedItems = {};               // "run:n" -> the item, for its buttons
const XP_HANDED_KIND = { email: "Email", event: "Event", text: "Text to paste",
                         file: "File", folder: "Folder", answer: "Answer" };

/* THE RESULT, TO OPEN (the user, 2026-10-27: not the log folder alone) -
   whatever it is: what the work handed over (an email opened in your mail,
   an event in your calendar, a file, a folder; text to copy), and what it
   made - the deliverables its deck lists, else the folder it worked in. */
function xpResultsRow(run) {
  const id = escapeHtml(run.id);
  const handed = (run.handed || []).map((one, n) => {
    const key = `${run.id}:${n}`;
    xpHandedItems[key] = one;
    const at = escapeHtml(key);
    const title = escapeHtml(one.title || XP_HANDED_KIND[one.kind] || one.kind || "");
    if (one.kind === "text" || one.kind === "answer") {
      return `<button type="button" class="small secondary" data-xp-handed-copy="${at}"
        title="${title}">${one.kind === "answer" ? "Copy the answer" : "Copy the text"}</button>`;
    }
    const words = one.kind === "email" ? "Open the email" : one.kind === "event"
      ? "Add the event" : one.kind === "folder" ? "Open the folder" : "Open the file";
    return `<button type="button" class="small" data-xp-handed-open="${at}"
      title="${title}">${words}</button>`;
  });
  const made = (run.results || []).map((one) => `<button type="button" class="small${
      handed.length ? " secondary" : ""}" data-xp-open-result="${id}"
      data-xp-result-path="${escapeHtml(one.path)}" title="${escapeHtml(one.path)}">${
      one.kind === "folder" ? (one.work_folder ? "Open the work folder" : "Open the folder")
        : "Open"} <code>${escapeHtml(one.name)}</code></button>`);
  if (!handed.length && !made.length) return "";
  return `<p class="xp-results-row"><strong>The result:</strong> ${handed.join(" ")} ${
    made.join(" ")}</p>`;
}

document.addEventListener("click", async (event) => {
  const at = event.target.closest && event.target.closest("[data-xp-open-result]");
  if (!at) return;
  try {
    await api.post("/api/work/reveal", { run: at.dataset.xpOpenResult,
                                         path: at.dataset.xpResultPath, open: true });
  } catch (err) {
    toast(err.message, "error");
  }
});

function xpHanded(run) {
  const items = run.handed || [];
  if (!items.length) return "";
  const id = escapeHtml(run.id);
  return `<div class="xp-results xp-handed" data-xp-keep="handed:${id}">
    <h4>What you get</h4>${items.map((one, n) => {
      const key = `${run.id}:${n}`;
      xpHandedItems[key] = one;
      const acts = one.actions || {};
      const at = escapeHtml(key);
      const open = (words) => `<button type="button" class="small" data-xp-handed-open="${at}">${
        escapeHtml(words)}</button>`;
      const copy = acts.copy ? `<button type="button" class="small secondary"
        data-xp-handed-copy="${at}">Copy the text</button>` : "";
      let body = "";
      let buttons = "";
      if (one.kind === "email") {
        body = `<dl class="xp-handed-mail">${(one.to || []).length ? `<dt>To</dt><dd>${
          escapeHtml(one.to.join(", "))}</dd>` : ""}${(one.cc || []).length ? `<dt>Cc</dt><dd>${
          escapeHtml(one.cc.join(", "))}</dd>` : ""}<dt>Subject</dt><dd>${
          escapeHtml(one.subject || "")}</dd></dl><pre class="xp-handed-text">${
          escapeHtml(one.body || "")}</pre>`;
        buttons = open(`Open in ${acts.in || "your mail"}`) + copy + (acts.whole === false
          ? `<span class="muted">too long for the link: copy the text, then paste it into
            the message</span>` : `<span class="muted">a new message, filled in - you send it</span>`);
      } else if (one.kind === "event") {
        body = `<p>${escapeHtml(localStamp(one.start) || one.start || "")}${one.end
          ? ` - ${escapeHtml(localStamp(one.end) || one.end)}` : ""}${one.where
          ? ` · ${escapeHtml(one.where)}` : ""}</p>${one.details
          ? `<pre class="xp-handed-text">${escapeHtml(one.details)}</pre>` : ""}`;
        buttons = open(`Add to ${acts.in || "your calendar"}`)
          + `<span class="muted">filled in - you save it</span>`;
      } else if (one.kind === "text" || one.kind === "answer") {
        body = `<pre class="xp-handed-text">${escapeHtml(one.text || "")}</pre>`;
        buttons = copy;
      } else {
        body = `<p><code>${escapeHtml(one.path || "")}</code></p>`;
        buttons = open(one.kind === "folder" ? "Open the folder" : "Open it");
      }
      return `<div class="xp-handed-item"><p class="xp-handed-head"><span class="xp-way">${
        escapeHtml(XP_HANDED_KIND[one.kind] || one.kind)}</span> <strong>${
        escapeHtml(one.title || "")}</strong></p>${body}
        <p class="xp-handed-buttons">${buttons}</p></div>`;
    }).join("")}</div>`;
}

document.addEventListener("click", async (event) => {
  if (!event.target.closest) return;
  const openAt = event.target.closest("[data-xp-handed-open]");
  const copyAt = event.target.closest("[data-xp-handed-copy]");
  if (!openAt && !copyAt) return;
  const key = (openAt || copyAt).dataset[openAt ? "xpHandedOpen" : "xpHandedCopy"];
  const one = xpHandedItems[key] || {};
  if (copyAt) {
    try {
      await navigator.clipboard.writeText((one.actions || {}).copy || "");
      toast("Copied");
    } catch (err) { toast(err.message, "error"); }
    return;
  }
  const at = key.lastIndexOf(":");
  try {
    // Opened by the agent in your own browser - where you are signed in -
    // not in this window.
    await api.post("/api/work/handed/open", { run: key.slice(0, at), n: Number(key.slice(at + 1)) });
  } catch (err) { toast(err.message, "error"); }
});

function xpAnswer(run) {
  const parts = xpAnswerParts(run);
  if (!parts.said) return "";
  const id = escapeHtml(run.id);
  return `<div class="xp-results xp-answer" data-xp-answer="${id}" data-xp-keep="answer:${id}">
    <h4 data-xp-answer-title="${id}">${escapeHtml(parts.title)}</h4>
    <pre class="xp-answer-text" data-xp-answer-text="${id}">${escapeHtml(parts.said)}</pre>
    <p class="muted" data-xp-answer-next="${id}"${parts.next ? "" : " hidden"}>${
      escapeHtml(parts.next)}</p>
  </div>`;
}

/* WHAT MAKES A RUN DRAWN AGAIN WHOLE - and nothing else. Its state, the part
   of the run it is in, whether it goes, is stopping or paused, how it
   ended, what it was asked, what can be done with it (Continue, from which
   version), its requests, its contract, its plan's lists. Not what only
   grows while it goes: its tokens and calls, its log, its transcript's
   files, its report's words, its versions - those are changed in place
   (xpRunPatch), and the page around them stays as it is. */
function xpRunSig(run) {
  const plan = run.plan || {};
  const book = plan.packages || {};
  const final = run.final || {};
  const kept = xpVersionsState();
  const picked = xpVersionPicked(run.id);
  const answer = xpAnswerParts(run);
  return JSON.stringify([run.id, run.status, plan.phase || "", Boolean(run.alive),
    Boolean(run.stopping), Boolean(run.paused), run.ended_at || "", run.instruction || "",
    Boolean(run.continuable), Boolean(run.extendable), Boolean((run.versions || {}).count),
    picked, Boolean(xpVersionSeen(run)), kept.from[run.id] || "",
    book.mode || "", (book.requests || []).map((one) => `${one.id}:${one.status}`),
    Boolean(plan.deck), (plan.decisions || []).length, (plan.rounds || []).length,
    ((plan.final_review || {}).findings || []).length, Boolean((run.transcript || []).length),
    run.run_log_dir || "", final.reason || "", Boolean(answer.said),
    run.contract_in_force || null, (plan.contract || {}).goal || "",
    (run.handed || []).map((one) => [one.kind, one.title, one.subject || "", one.body || "",
                                      one.text || "", one.start || "", one.path || "",
                                      (one.actions || {}).open || ""]),
    (plan.contract || {}).amended || null, plan.todo || null, (plan.sessions || []).length,
    run.milestone || null]);
}

/* A RUN CHANGED IN PLACE while it goes: its counters, its log, its
   transcript's files, its report, its chart, its live session's head and
   its versions' tree - each only if it changed, each keeping where it is
   scrolled to. Nothing else of the run is touched: what you read, select
   or type in stays exactly where it is. */
function xpRunPatch(run) {
  const kept = xpVersionsState();
  kept.runs[run.id] = run;
  const key = CSS.escape(run.id);
  const box = $(`[data-xp-run-box="${key}"]`);
  if (!box) return;
  const put = (selector, html, text) => {
    const at = box.querySelector(selector);
    if (!at || at._xpHtml === xpShows(html)) return;
    const top = at.scrollTop;
    const bottom = top > 0 && at.scrollHeight - top - at.clientHeight < 24;
    if (text) at.textContent = html; else at.innerHTML = html;
    at._xpHtml = xpShows(html);
    at.scrollTop = bottom ? at.scrollHeight : top;
  };
  put(`[data-xp-run-totals="${key}"]`, xpRunTotals(run));
  put(`[data-xp-run-log="${key}"]`, xpRunLog(run));
  put(`[data-xp-transcript-count="${key}"]`, xpTranscriptCount(run), true);
  put(`[data-xp-transcript-list="${key}"]`, xpTranscriptList(run));
  const answer = xpAnswerParts(run);
  put(`[data-xp-answer-title="${key}"]`, answer.title, true);
  put(`[data-xp-answer-text="${key}"]`, answer.said, true);
  const next = box.querySelector(`[data-xp-answer-next="${key}"]`);
  if (next) {
    next.hidden = !answer.next;
    put(`[data-xp-answer-next="${key}"]`, answer.next, true);
  }
  if (xpCallsTake(run.id, run.calls)) xpCallsDraw(run.id);
  const live = xpLiveState(run.id);
  if (live.open && xpLiveBody(run.id)) {
    xpLiveDraw(run.id, null);
    if (run.alive) xpLiveFollow(run.id);
  }
  xpVersionsRefresh(run);
}

/* A RUN'S TOKENS, ADDED UP OVER TIME: how much the run has taken so far -
   what went in on top, what came out below - as lines that only climb.

   It was a stem per call, the call's own tokens; what you watch a run for is
   what it has spent, and a field of stems never said it - the sum was the
   sum of a hundred heights. Now the running total is drawn, a step at each
   call where it ended: flat while nothing is spent, up by what the call
   took. The call's own tokens are still said - on hover, and in the table.

   Two panels, one above the other, sharing the time axis - never one chart
   with two scales: what goes in is counted whole, the cached input too, and
   is a hundred times what comes out; on one scale the output would be a
   line along the floor, and two scales on one plot invent a relation that
   is not there. Each panel has its own scale, from zero.

   Who made the calls - the builder, the reviewer, or the single model of
   the Experience debugger's first way - each has its own line, in the token
   chart's first colours (TOKEN_COLOURS, validated together on this app's
   own panel colours in both themes; see --xp-call-* in styles.css); and
   ALL OF THEM TOGETHER are a line of their own in every panel - the TOTAL,
   in the page's ink and a little heavier, so it is never taken for one of
   them: four lines at most, each named in the legend and, where they do not
   crowd, at its end. (With the single model alone, its line and the total
   are one: the total is drawn over it, and both are named.) A call that
   failed took nothing: a hollow ring where it sits on its line. Long
   pauses - a run continued the next day - are drawn as a short break in the
   axis, not as a stretch of nothing.

   Hovering finds the nearest call (within XP_CALLS_HIT pixels): a crosshair
   there, a dot on each line, and the tip says the total then, each one's
   total then, and the call itself - what went in and out, who, in which part of the run, when it
   began and ended. The same with the keyboard: the chart is focusable, and
   ← → go from call to call. And every value is in the table beneath it
   too, the running total beside it - nothing is reachable only by hovering.

   It is drawn on IN PLACE as calls come - the chart's own box, nothing
   around it - and its box is as tall as the chart, axis and all, from the
   first call: the page does not grow under you as it is drawn.

   Kept per run as the panel is redrawn: the calls seen so far - from the
   runs' list, then from the live session as they come - which one is
   hovered, and whether the chart and its table are open. */
const XP_CALLS_WHO = [
  { who: "builder", label: "builder", colour: "var(--xp-call-builder)" },
  { who: "reviewer", label: "reviewer", colour: "var(--xp-call-reviewer)" },
  { who: "single", label: "single model", colour: "var(--xp-call-single)" },
  // Helper agents the builder or the reviewer handed a task (delegate).
  { who: "helper", label: "helper agents", colour: "var(--xp-call-helper)" },
  // The two final checks: each a kind of its own (runner.CALL_WHO).
  { who: "quality check", label: "quality check", colour: "var(--xp-call-quality)" },
  { who: "privacy check", label: "privacy check", colour: "var(--xp-call-privacy)" },
];
// All of them together: a line of their own, in the page's ink - not a hue.
const XP_CALLS_TOTAL = { who: "", label: "total", colour: "var(--ink)" };
const XP_CALLS_KEEP = 600;              // the most held per run - as the server keeps
const XP_CALLS_GAP = 10 * 60 * 1000;    // a pause longer than this is a break in the axis
const XP_CALLS_BREAK = 16;              // px a break takes
const XP_CALLS_HIT = 24;                // px within which the pointer finds a call
const XP_CALLS_LAYOUT = { left: 50, right: 96, inTop: 24, inHeight: 104, gap: 32,
                          outHeight: 76, axis: 22 };
const XP_CALLS_HEIGHT = XP_CALLS_LAYOUT.inTop + XP_CALLS_LAYOUT.inHeight
  + XP_CALLS_LAYOUT.gap + XP_CALLS_LAYOUT.outHeight + XP_CALLS_LAYOUT.axis;

/* THE LINES SHOWN: a line is hidden by clicking its name in the legend -
   builder, reviewer, the single model or the total - and shown again the
   same way; the scales fit what is left, so a small line can be read. One
   choice for every chart, real work's and the debugger's, kept in this
   browser. */
const XP_CALLS_HIDDEN_KEY = "pa-calls-hidden";

function xpCallsHidden() {
  if (!experienceState.callsHidden) {
    let kept = [];
    try {
      kept = JSON.parse(localStorage.getItem(XP_CALLS_HIDDEN_KEY) || "[]");
    } catch (err) { kept = []; }
    experienceState.callsHidden = new Set(Array.isArray(kept) ? kept.map(String) : []);
  }
  return experienceState.callsHidden;
}

function xpCallsToggle(key) {
  const hidden = xpCallsHidden();
  if (hidden.has(key)) hidden.delete(key);
  else hidden.add(key);
  try {
    localStorage.setItem(XP_CALLS_HIDDEN_KEY, JSON.stringify([...hidden]));
  } catch (err) { /* kept for this page only */ }
  xpCallsDrawAll();
}

/* A line's key in that choice: who made the calls, or "total". */
function xpCallsKeyOf(line) {
  return line.who || "total";
}

function xpCallsState(runId) {
  experienceState.calls = experienceState.calls || {};
  if (!experienceState.calls[runId]) {
    experienceState.calls[runId] = { list: [], last: 0, hover: null, open: true,
                                     table: false };
  }
  return experienceState.calls[runId];
}

/* Calls taken in - those not seen yet, in order. How many were new. */
function xpCallsTake(runId, calls) {
  const kept = xpCallsState(runId);
  const known = new Set(kept.list.map((one) => Number(one.n)));
  let added = 0;
  (calls || []).forEach((one) => {
    const n = Number((one || {}).n || 0);
    if (!n || known.has(n)) return;
    known.add(n);
    kept.list.push(one);
    added += 1;
  });
  if (added) {
    kept.list.sort((a, b) => Number(a.n) - Number(b.n));
    if (kept.list.length > XP_CALLS_KEEP) kept.list.splice(0, kept.list.length - XP_CALLS_KEEP);
    kept.last = kept.list.reduce((most, one) => Math.max(most, Number(one.n)), kept.last);
  }
  return added;
}

function xpCallsWho(who) {
  return XP_CALLS_WHO.find((one) => one.who === who)
    || { who, label: String(who || "?"), colour: "var(--muted)" };
}

/* Its place in a run: the legend, the chart - its box as tall as the chart
   will be - and its table. */
function xpCallsSection(run) {
  xpCallsTake(run.id, run.calls);
  const kept = xpCallsState(run.id);
  if (!kept.list.length && !run.alive) return "";
  const id = escapeHtml(run.id);
  return `<details class="xp-calls" data-xp-calls="${id}" data-xp-keep="calls:${id}"${
    kept.open ? " open" : ""}>
    <summary><strong>Tokens so far</strong> - added up over the run, call by call: what
      went in above, what came out below, each on its own scale</summary>
    <div class="xp-calls-legend" data-xp-calls-legend="${id}"></div>
    <div class="xp-calls-chart" data-xp-calls-chart="${id}" tabindex="0" role="img"
      style="height:${XP_CALLS_HEIGHT}px"
      aria-label="The run's tokens added up over time: in, and out"></div>
    <details class="xp-calls-table" data-xp-calls-table="${id}"${kept.table ? " open" : ""}>
      <summary class="muted">As a table</summary><div class="xp-calls-rows-box"
        data-xp-calls-rows="${id}" data-xp-keep="calls-rows:${id}"></div></details>
  </details>`;
}

/* A clean top for a scale - its half clean too: 1, 1.2, 1.5, 2, 2.5, 3, 4,
   5, 6 or 8 times a power of ten, the first at or above the most. */
function xpCallsNice(value) {
  const v = Math.max(1, Number(value) || 0);
  const power = Math.pow(10, Math.floor(Math.log10(v)));
  const step = [1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10].find((one) => one * power >= v) || 10;
  return step * power;
}

/* THE X AXIS: the clock ("time"), or the run's own time ("spent") - what it
   had run when each call ended, paused stretches and waits for the user left
   out, as the run counted it. Calls from before it counted are estimated:
   every gap longer than a pause is taken out. One choice, kept in this
   browser. */
let xpCallsAxisChosen = "";
function xpCallsAxis() {
  if (xpCallsAxisChosen) return xpCallsAxisChosen;
  try {
    return localStorage.getItem("xp-calls-axis") === "spent" ? "spent" : "time";
  } catch (_err) {
    return "time";
  }
}

function xpCallsSpent(calls) {
  const order = calls.slice().sort((a, b) => xpCallsTimes(a).end - xpCallsTimes(b).end
    || Number(a.n) - Number(b.n));
  const at = new Map();
  let est = 0;
  let prev = null;
  let estimated = false;
  order.forEach((call) => {
    const { end } = xpCallsTimes(call);
    const own = Math.max(0, Number(call.seconds || 0)) * 1000;
    if (prev === null) est = own;
    else {
      const gap = Math.max(0, end - prev);
      est += gap > XP_CALLS_GAP ? own : gap;
    }
    prev = end;
    if (call.active !== undefined && call.active !== null) {
      est = Number(call.active) * 1000;
    } else {
      estimated = true;
    }
    at.set(Number(call.n), est);
  });
  return { at, estimated };
}

function xpCallsTimes(call) {
  const end = Date.parse(call.finished) || Date.parse(call.started) || 0;
  const start = Math.min(Date.parse(call.started) || end, end);
  return { start, end };
}

/* THE RUNNING TOTALS: the calls in the order they ended, each with what had
   been taken by then - by each who made calls, and by all of them. A failed
   call took nothing. `lines`: who has a line - each who, then the total,
   always last, drawn on top. */
function xpCallsCumulative(calls, spent = null) {
  const tOf = (call) => (spent ? spent.at.get(Number(call.n)) || 0 : xpCallsTimes(call).end);
  const order = calls.slice().sort((a, b) => tOf(a) - tOf(b)
    || Number(a.n) - Number(b.n));
  const present = new Set(order.map((one) => one.who));
  const whos = [...XP_CALLS_WHO.filter((one) => present.has(one.who)),
                ...[...present].filter((w) => !XP_CALLS_WHO.some((one) => one.who === w))
                  .map(xpCallsWho)];
  const sums = { "": { in: 0, out: 0 } };
  whos.forEach((one) => { sums[one.who] = { in: 0, out: 0 }; });
  const points = order.map((call) => {
    const tin = call.failed ? 0 : Number(call.tokens_in || 0);
    const tout = call.failed ? 0 : Number(call.tokens_out || 0);
    sums[call.who].in += tin;
    sums[call.who].out += tout;
    sums[""].in += tin;
    sums[""].out += tout;
    const cum = {};
    Object.entries(sums).forEach(([who, sum]) => { cum[who] = { in: sum.in, out: sum.out }; });
    return { call, n: Number(call.n), t: tOf(call), cum };
  });
  return { points, lines: [...whos, XP_CALLS_TOTAL], whos, sums,
           total: { in: sums[""].in, out: sums[""].out } };
}

/* Time to x: the calls' stretches of activity laid side by side, each as
   wide as its share of the time worked, with a short break between two
   that a long pause parts. */
function xpCallsTimeScale(calls, x0, x1, spent = null) {
  if (spent) {
    // The run's own time: one stretch from its start, no breaks - there
    // are no pauses in it.
    const most = Math.max(60 * 1000, ...[...spent.at.values()]);
    const span = { from: 0, to: most, lo: 0, hi: most * 1.02, x0, x1, spent: true };
    return { x: (t) => x0 + (t / span.hi) * (x1 - x0), spans: [span] };
  }
  const ends = calls.map((one) => xpCallsTimes(one).end).sort((a, b) => a - b);
  const spans = [];
  ends.forEach((t) => {
    const last = spans[spans.length - 1];
    if (!last || t - last.to > XP_CALLS_GAP) spans.push({ from: t, to: t });
    else last.to = t;
  });
  const worked = spans.reduce((sum, one) => sum + (one.to - one.from), 0);
  // A stretch of one call, or a few close together, still gets some room.
  const least = Math.max(60 * 1000, worked * 0.04);
  spans.forEach((one) => {
    const wide = Math.max(one.to - one.from, least);
    const pad = (wide - (one.to - one.from)) / 2 + wide * 0.03;
    one.lo = one.from - pad;
    one.hi = one.to + pad;
  });
  const total = spans.reduce((sum, one) => sum + (one.hi - one.lo), 0) || 1;
  const room = Math.max(40, x1 - x0 - XP_CALLS_BREAK * (spans.length - 1));
  let at = x0;
  spans.forEach((one) => {
    one.x0 = at;
    one.x1 = at + room * ((one.hi - one.lo) / total);
    at = one.x1 + XP_CALLS_BREAK;
  });
  const x = (t) => {
    const span = spans.find((one) => t <= one.hi) || spans[spans.length - 1];
    return span.x0 + ((t - span.lo) / ((span.hi - span.lo) || 1)) * (span.x1 - span.x0);
  };
  return { x, spans };
}

/* The time axis: ticks at a clean step in each stretch, labelled where
   they do not crowd - the first of a stretch after a break with its day,
   when the day changed. */
function xpCallsTicks(spans) {
  const STEPS = [10, 30, 60, 120, 300, 600, 900, 1800, 3600, 7200, 21600]
    .map((s) => s * 1000);
  if (spans.length === 1 && spans[0].spent) {
    // Time spent: how long it had run, from nothing.
    const span = spans[0];
    const perMs = (span.x1 - span.x0) / (span.hi || 1);
    const step = STEPS.find((s) => s * perMs >= 72) || STEPS[STEPS.length - 1];
    const ticks = [];
    for (let t = 0; t <= span.hi; t += step) {
      ticks.push({ t, label: t ? xpCallsDuration(t / 1000) : "0" });
    }
    return ticks;
  }
  const ticks = [];
  let lastDay = "";
  spans.forEach((span, index) => {
    const perMs = (span.x1 - span.x0) / ((span.hi - span.lo) || 1);
    const step = STEPS.find((s) => s * perMs >= 72) || STEPS[STEPS.length - 1];
    const first = Math.ceil(span.lo / step) * step;
    const marks = [];
    for (let t = first; t <= span.hi; t += step) marks.push(t);
    if (!marks.length) marks.push((span.lo + span.hi) / 2);
    marks.forEach((t, i) => {
      const when = new Date(t);
      const day = when.toLocaleDateString([], { month: "short", day: "numeric" });
      const time = when.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit",
        ...(step < 60000 ? { second: "2-digit" } : {}), hour12: false });
      const withDay = i === 0 && (index > 0 || spans.length > 1) && day !== lastDay;
      if (i === 0) lastDay = day;
      ticks.push({ t, label: withDay ? `${day} ${time}` : time });
    });
  });
  return ticks;
}

function xpCallsDuration(seconds) {
  const s = Math.max(0, Math.round(Number(seconds) || 0));
  if (s < 60) return `${s} s`;
  if (s < 3600) return `${Math.floor(s / 60)} min ${s % 60} s`;
  return `${Math.floor(s / 3600)} h ${Math.floor((s % 3600) / 60)} min`;
}

/* The chart itself, as SVG, for `width` pixels: what it draws, and where
   each call is - for the hover. */
function xpCallsSvg(calls, width) {
  const L = XP_CALLS_LAYOUT;
  const x0 = L.left;
  const x1 = Math.max(x0 + 60, width - L.right);
  const inTop = L.inTop;
  const inBase = inTop + L.inHeight;
  const outTop = inBase + L.gap;
  const outBase = outTop + L.outHeight;
  const height = outBase + L.axis;
  const spent = xpCallsAxis() === "spent" ? xpCallsSpent(calls) : null;
  const { x, spans } = xpCallsTimeScale(calls, x0 + 6, x1 - 6, spent);
  const sums = xpCallsCumulative(calls, spent);
  const { points } = sums;
  const hidden = xpCallsHidden();
  const lines = sums.lines.filter((line) => !hidden.has(xpCallsKeyOf(line)));
  // Scaled to the lines shown: with the total hidden, the builder's fills
  // the panel.
  const most = (key) => Math.max(0, ...lines.map((line) => sums.sums[line.who][key]));
  const topIn = xpCallsNice(lines.length ? most("in") : sums.total.in);
  const topOut = xpCallsNice(lines.length ? most("out") : sums.total.out);
  const yIn = (v) => inBase - (Number(v || 0) / topIn) * L.inHeight;
  const yOut = (v) => outBase - (Number(v || 0) / topOut) * L.outHeight;
  // Kept only from a later call - the oldest of a long run let go: added up
  // from there, and the panels say so.
  const since = calls.length && Number(calls[0].n) > 1 ? ` - since call ${Number(calls[0].n)}` : "";
  const panels = [["in", `Input tokens, added up${since}`, inTop, inBase, topIn, yIn],
                  ["out", `Output tokens, added up${since}`, outTop, outBase, topOut, yOut]];
  const parts = [];
  // The panels: their names, gridlines at 0, half and the top, the scales.
  panels.forEach(([, name, top, , most, y]) => {
    parts.push(`<text class="xp-calls-panel" x="${x0}" y="${top - 6}">${escapeHtml(name)}</text>`);
    [0, most / 2, most].forEach((v) => {
      const at = y(v).toFixed(1);
      parts.push(`<line class="${v ? "xp-calls-grid" : "xp-calls-base"}" x1="${x0}" x2="${x1}"
        y1="${at}" y2="${at}"></line>`,
      `<text class="xp-calls-tick" x="${x0 - 6}" y="${(Number(at) + 3.5).toFixed(1)}"
        text-anchor="end">${escapeHtml(xpTokens(v))}</text>`);
    });
  });
  // The time axis.
  xpCallsTicks(spans).forEach((tick, i, all) => {
    const at = x(tick.t);
    if (at < x0 || at > x1) return;
    const before = all.slice(0, i).filter((one) => !one.skipped).pop();
    if (before && Math.abs(x(before.t) - at) < 64) { tick.skipped = true; return; }
    parts.push(`<line class="xp-calls-tickmark" x1="${at.toFixed(1)}" x2="${at.toFixed(1)}"
      y1="${outBase}" y2="${outBase + 4}"></line>`,
    `<text class="xp-calls-tick" x="${at.toFixed(1)}" y="${outBase + 16}"
      text-anchor="middle">${escapeHtml(tick.label)}</text>`);
  });
  // The lines: from nothing at the left, a step up at each call where it
  // ended, on to the last call - all of them ending there, where they are
  // named. The total last, on top.
  const xStart = spans.length ? spans[0].x0 : x0;
  const xEnd = points.length ? x(points[points.length - 1].t) : xStart;
  const ends = [];
  panels.forEach(([key, , , , , y]) => {
    lines.forEach((line) => {
      let d = `M${xStart.toFixed(1)},${y(0).toFixed(1)}`;
      let value = 0;
      points.forEach((p) => {
        if (line.who && p.call.who !== line.who) return;
        const next = p.cum[line.who][key];
        if (next === value) return;
        d += `H${x(p.t).toFixed(1)}V${y(next).toFixed(1)}`;
        value = next;
      });
      d += `H${xEnd.toFixed(1)}`;
      parts.push(`<path class="xp-calls-line${line.who ? "" : " xp-calls-line-total"}"
        data-xp-line="${escapeHtml(line.who || "all")}" data-xp-panel="${key}"
        data-xp-sum="${value}" style="stroke:${line.colour}" d="${d}"></path>`);
      ends.push({ key, line, value, y: y(value) });
    });
    // A call that failed took nothing: a ring where it sits on its line.
    points.filter((p) => p.call.failed && !hidden.has(p.call.who)).forEach((p) => {
      const line = xpCallsWho(p.call.who);
      const value = p.cum[p.call.who][key];
      parts.push(`<circle class="xp-call-failed" data-xp-call="${p.n}" cx="${
        x(p.t).toFixed(1)}" cy="${y(value).toFixed(1)}" r="4" style="stroke:${line.colour}"></circle>`);
    });
  });
  // Each line's end: a dot, and - where it does not crowd another - its
  // name and what it has come to. The total is named first.
  const named = [];
  ["in", "out"].forEach((key) => {
    const mine = ends.filter((one) => one.key === key)
      .sort((a, b) => (a.line.who ? 1 : 0) - (b.line.who ? 1 : 0));
    const placed = [];
    mine.forEach((one) => {
      parts.push(`<circle class="xp-calls-end" cx="${xEnd.toFixed(1)}" cy="${one.y.toFixed(1)}"
        r="4" style="fill:${one.line.colour}"></circle>`);
      if (placed.some((y) => Math.abs(y - one.y) < 14)) return;
      placed.push(one.y);
      const words = `${one.line.label} ${xpTokens(one.value)}`;
      named.push(words);
      parts.push(`<text class="xp-calls-endlabel" x="${(xEnd + 8).toFixed(1)}" y="${
        (one.y + 3.5).toFixed(1)}">${escapeHtml(words)}</text>`);
    });
  });
  // A break between stretches, over the lines that cross it.
  spans.slice(1).forEach((span) => {
    const at = (span.x0 - XP_CALLS_BREAK / 2).toFixed(1);
    [[inTop, inBase], [outTop, outBase]].forEach(([top, base]) => {
      parts.push(`<line class="xp-calls-break" x1="${at}" x2="${at}" y1="${top - 2}"
        y2="${base}"></line>`);
    });
  });
  // The crosshair and its dots, at the call the pointer found.
  parts.push(`<line class="xp-calls-cross" x1="0" x2="0" y1="${inTop}" y2="${outBase}"
    visibility="hidden"></line><g class="xp-calls-focus"></g>`);
  const hits = points.map((p) => ({ n: p.n, x: x(p.t),
    dots: lines.map((line) => ({ colour: line.colour, yIn: yIn(p.cum[line.who].in),
                                 yOut: yOut(p.cum[line.who].out) })) }));
  return { hits, height, points, named, lines: sums.lines,
           svg: `<svg class="xp-calls-svg" width="${width}" height="${height}"
             viewBox="0 0 ${width} ${height}" aria-hidden="true">${parts.join("")}</svg>` };
}

/* The lines, named - each who made calls, and the total - each with what
   it has come to; the hollow ring of a call that failed, when one did; and
   how many calls. */
function xpCallsLegend(calls) {
  const { lines, sums } = xpCallsCumulative(calls);
  const failed = calls.some((c) => c.failed);
  const hidden = xpCallsHidden();
  const keys = lines.map((one) => {
    const off = hidden.has(xpCallsKeyOf(one));
    return `<button type="button" class="xp-calls-key${one.who ? "" : " xp-calls-key-total"}${
      off ? " xp-calls-key-off" : ""}" data-xp-calls-key="${escapeHtml(xpCallsKeyOf(one))}"
      aria-pressed="${off ? "false" : "true"}" title="${off ? "Show" : "Hide"} this line"><span
      class="xp-calls-swatch" style="background:${one.colour}"></span>${escapeHtml(one.label)}
      <span class="muted">${escapeHtml(xpTokenSplit({ tokens_in: sums[one.who].in,
        tokens_out: sums[one.who].out }))}</span></button>`;
  });
  if (failed) {
    keys.push(`<span class="xp-calls-key"><span class="xp-calls-ring"></span>failed</span>`);
  }
  keys.push(`<span class="muted xp-calls-sum">${calls.length} call${calls.length === 1 ? ""
    : "s"}</span>`);
  // The x axis: the clock, or the run's own time.
  const axis = xpCallsAxis();
  const estimated = axis === "spent" && xpCallsSpent(calls).estimated;
  keys.push(`<span class="xp-calls-axis" role="group" aria-label="Across">${
    [["time", "Clock time"], ["spent", "Time spent"]].map(([key, label]) =>
      `<button type="button" class="small${axis === key ? "" : " secondary"}"
        data-xp-calls-axis="${key}" aria-pressed="${axis === key}">${label}</button>`).join("")}${
    estimated ? `<span class="muted"> earlier calls estimated</span>` : ""}</span>`);
  return keys.join("");
}

/* One moment, said whole - the totals then first, then the call that made
   it: what it took, who, where and when. Written as text, never as markup. */
function xpCallsTip(tip, point, lines) {
  tip.replaceChildren();
  const line = (cls, text, colour) => {
    const div = document.createElement("div");
    if (cls) div.className = cls;
    div.textContent = text;
    if (colour) {
      const key = document.createElement("span");
      key.className = "xp-calls-tip-key";
      key.style.background = colour;
      div.prepend(key);
    }
    tip.appendChild(div);
    return div;
  };
  const sum = (one) => `${Number(one.in).toLocaleString()} in · ${Number(one.out).toLocaleString()} out`;
  const call = point.call;
  line("xp-calls-tip-value", `total ${sum(point.cum[""])} so far`);
  lines.filter((one) => one.who).forEach((one) => {
    line("xp-calls-tip-who", `${one.label}: ${sum(point.cum[one.who])}`, one.colour);
  });
  const who = xpCallsWho(call.who);
  line("xp-calls-tip-call", `call ${Number(call.n)} · ${who.label}${call.part ? ` · ${call.part}` : ""}: ${
    call.failed ? "failed" : sum({ in: Number(call.tokens_in || 0), out: Number(call.tokens_out || 0) })}`);
  const when = (iso) => {
    const at = new Date(iso);
    return Number.isNaN(at.getTime()) ? "" : at.toLocaleTimeString([], { hour12: false });
  };
  const { start, end } = xpCallsTimes(call);
  const seconds = call.seconds !== undefined ? call.seconds : (end - start) / 1000;
  line("muted", `${when(call.started)} → ${when(call.finished)} · ${xpCallsDuration(seconds)}`);
  if (call.active !== undefined && call.active !== null) {
    line("muted", `${xpCallsDuration(call.active)} of the run's own time by then`);
  }
  if (call.tokens_in_cached || call.tokens_in_cache_written) {
    line("muted", `of what went in: ${Number(call.tokens_in_cached || 0).toLocaleString()
    } read from the cache, ${Number(call.tokens_in_cache_written || 0).toLocaleString()
    } written to it`);
  }
  if (call.failed && call.error) line("muted", String(call.error));
}

/* The table: every call kept, the latest first - its own tokens, and the
   totals by then. */
function xpCallsTable(calls) {
  const when = (iso) => {
    const at = new Date(iso);
    return Number.isNaN(at.getTime()) ? "" : at.toLocaleString([], { hour12: false });
  };
  const { points } = xpCallsCumulative(calls);
  return `<table class="xp-calls-rows"><thead><tr><th>#</th><th>Began</th><th>Took</th>
    <th>Who</th><th>Part</th><th class="num">In</th><th class="num">Out</th>
    <th class="num">Total in so far</th><th class="num">Total out so far</th></tr></thead>
    <tbody>${points.slice().reverse().map(({ call: one, cum }) => `<tr${one.failed
      ? ` class="xp-calls-row-failed"` : ""}><td>${Number(one.n)}</td>
      <td>${escapeHtml(when(one.started))}</td>
      <td>${escapeHtml(xpCallsDuration(one.seconds !== undefined ? one.seconds
        : (xpCallsTimes(one).end - xpCallsTimes(one).start) / 1000))}</td>
      <td>${escapeHtml(xpCallsWho(one.who).label)}</td><td>${escapeHtml(one.part || "")}</td>
      <td class="num">${one.failed ? "failed" : Number(one.tokens_in || 0).toLocaleString()}</td>
      <td class="num">${one.failed ? "" : Number(one.tokens_out || 0).toLocaleString()}</td>
      <td class="num">${Number(cum[""].in).toLocaleString()}</td>
      <td class="num">${Number(cum[""].out).toLocaleString()}</td>
      </tr>`).join("")}</tbody></table>`;
}

/* A run's chart drawn - as wide as its place is now; not while it has no
   width (a run folded away): drawn when it is opened. Only the chart's own
   box, its legend and its table are touched; the table keeps where it was
   scrolled to - the rows above what you read grow, and what you read stays. */
function xpCallsDraw(runId) {
  const kept = xpCallsState(runId);
  const key = CSS.escape(runId);
  const legend = $(`[data-xp-calls-legend="${key}"]`);
  if (legend) legend.innerHTML = kept.list.length ? xpCallsLegend(kept.list) : "";
  const rows = $(`[data-xp-calls-rows="${key}"]`);
  if (rows && rows.closest("details").open) {
    const top = rows.scrollTop;
    const tall = rows.scrollHeight;
    rows.innerHTML = kept.list.length ? xpCallsTable(kept.list)
      : `<p class="muted">No calls yet.</p>`;
    if (top > 0) rows.scrollTop = top + (rows.scrollHeight - tall);
  }
  const box = $(`[data-xp-calls-chart="${key}"]`);
  if (!box) return;
  const width = Math.floor(box.clientWidth);
  if (!width) {
    // NOT LAID OUT YET - a tab not shown, a way of the Work debugger not the
    // one in front, a panel just drawn: drawn the moment it has a width.
    // It used to wait for the run's next call, so a chart stood empty until
    // the run moved on.
    xpCallsWhenSized(box, runId);
    return;
  }
  if (!kept.list.length) {
    box.innerHTML = `<p class="muted">No model calls yet - what they take is added up here
      as they are made.</p>`;
    return;
  }
  const drawn = xpCallsSvg(kept.list, width);
  box.innerHTML = `${drawn.svg}<div class="xp-calls-tip" hidden></div>`;
  box._xpCalls = drawn.hits;
  const tip = box.querySelector(".xp-calls-tip");
  const cross = box.querySelector(".xp-calls-cross");
  const focus = box.querySelector(".xp-calls-focus");
  const show = (n) => {
    const point = drawn.points.find((one) => one.n === n);
    const hit = drawn.hits.find((one) => one.n === n);
    if (!point || !hit) {
      kept.hover = null;
      tip.hidden = true;
      cross.setAttribute("visibility", "hidden");
      focus.innerHTML = "";
      return;
    }
    kept.hover = n;
    cross.setAttribute("x1", hit.x.toFixed(1));
    cross.setAttribute("x2", hit.x.toFixed(1));
    cross.setAttribute("visibility", "visible");
    focus.innerHTML = hit.dots.map((dot) => ["yIn", "yOut"].map((at) => `<circle
      class="xp-calls-dot" cx="${hit.x.toFixed(1)}" cy="${dot[at].toFixed(1)}" r="4"
      style="fill:${dot.colour}"></circle>`).join("")).join("");
    xpCallsTip(tip, point, drawn.lines);
    tip.hidden = false;
    // Beside the call, on the side with room, and never off the chart.
    const room = box.clientWidth;
    const wide = tip.offsetWidth;
    const left = hit.x + 12 + wide > room ? hit.x - 12 - wide : hit.x + 12;
    tip.style.left = `${Math.max(0, Math.min(left, room - wide))}px`;
    tip.style.top = `${XP_CALLS_LAYOUT.inTop}px`;
  };
  box.onpointermove = (event) => {
    const svg = box.querySelector("svg");
    if (!svg) return;
    const px = event.clientX - svg.getBoundingClientRect().left;
    let best = null;
    drawn.hits.forEach((one) => {
      if (!best || Math.abs(one.x - px) < Math.abs(best.x - px)) best = one;
    });
    show(best && Math.abs(best.x - px) <= XP_CALLS_HIT ? best.n : null);
  };
  box.onpointerleave = () => { if (document.activeElement !== box) show(null); };
  box.onblur = () => show(null);
  box.onfocus = () => {
    if (kept.hover === null && drawn.hits.length) show(drawn.hits[drawn.hits.length - 1].n);
  };
  box.onkeydown = (event) => {
    if (!["ArrowLeft", "ArrowRight", "Escape", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    if (event.key === "Escape") { show(null); return; }
    const order = drawn.hits.slice().sort((a, b) => a.x - b.x || a.n - b.n);
    const at = order.findIndex((one) => one.n === kept.hover);
    const next = event.key === "Home" ? 0 : event.key === "End" ? order.length - 1
      : at < 0 ? order.length - 1
        : Math.max(0, Math.min(order.length - 1, at + (event.key === "ArrowRight" ? 1 : -1)));
    show(order[next].n);
  };
  // A call hovered when it was drawn again stays said.
  if (kept.hover !== null) show(kept.hover);
}

document.addEventListener("click", (event) => {
  const key = event.target.closest && event.target.closest("button[data-xp-calls-key]");
  if (key) xpCallsToggle(key.dataset.xpCallsKey);
  // The x axis, for every chart: the clock or the run's own time.
  const axis = event.target.closest && event.target.closest("button[data-xp-calls-axis]");
  if (axis) {
    xpCallsAxisChosen = axis.dataset.xpCallsAxis === "spent" ? "spent" : "time";
    try { localStorage.setItem("xp-calls-axis", xpCallsAxisChosen); } catch (_err) { /* kept here */ }
    xpCallsDrawAll();
  }
});

/* Every chart in a part of the page, drawn. */
/* A chart box with no width yet, watched until it has one - then drawn,
   and let go. */
const xpCallsUnsized = new Map();
let xpCallsSizer = null;
function xpCallsWhenSized(box, runId) {
  if (typeof ResizeObserver === "undefined") return;
  if (!xpCallsSizer) {
    xpCallsSizer = new ResizeObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.target.isConnected) {
          xpCallsSizer.unobserve(entry.target);
          xpCallsUnsized.delete(entry.target);
          return;
        }
        if (entry.contentRect.width < 1) return;
        const which = xpCallsUnsized.get(entry.target);
        xpCallsSizer.unobserve(entry.target);
        xpCallsUnsized.delete(entry.target);
        if (which) xpCallsDraw(which);
      });
    });
  }
  if (xpCallsUnsized.has(box)) return;
  xpCallsUnsized.set(box, runId);
  xpCallsSizer.observe(box);
}

function xpCallsDrawAll(scope) {
  $$("[data-xp-calls-chart]", scope || document).forEach((box) => {
    xpCallsDraw(box.dataset.xpCallsChart);
  });
}

// Opened - a run, the chart, its table - it is drawn; closed, it stays closed
// as the panel is redrawn.
document.addEventListener("toggle", (event) => {
  const at = event.target;
  if (!at || !at.matches) return;
  if (at.matches("[data-xp-calls]")) {
    xpCallsState(at.dataset.xpCalls).open = at.open;
    if (at.open) xpCallsDraw(at.dataset.xpCalls);
  } else if (at.matches("[data-xp-calls-table]")) {
    xpCallsState(at.dataset.xpCallsTable).table = at.open;
    if (at.open) xpCallsDraw(at.dataset.xpCallsTable);
  } else if (at.open && at.matches(".xp-run")) {
    xpCallsDrawAll(at);
  }
}, true);

// A version in the tree, picked with the keyboard as with the pointer.
document.addEventListener("keydown", (event) => {
  const at = event.target;
  if (!at || !at.matches || !at.matches("[data-xp-version-node]")) return;
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  at.dispatchEvent(new MouseEvent("click", { bubbles: true }));
});

// As wide as their place: drawn again when the window changes size.
window.addEventListener("resize", () => {
  clearTimeout(experienceState.callsResize);
  experienceState.callsResize = setTimeout(() => xpCallsDrawAll(document), 150);
});

/* THE LIVE SESSION of a run - beside the agents' tree and the slides, a
   view like a terminal: what the work agent and the reviewer do as they do
   it, newest at the bottom, with where the run stands against its limits
   on top. Requests waiting for your answer are asked in it, at the bottom,
   where the run stopped to ask. The run lives in the application, not the
   page: closing the page changes nothing, and opening it again picks the
   session up where it is.

   Kept per run as the panel is redrawn: the events seen so far, the last
   one's number (only newer ones are asked for), the latest answer, and
   whether the view is open. The view's own element is kept too - moved
   into the redrawn panel - so its scroll stays where you left it. */
const XP_LIVE_EVERY = 1000;        // ms between looks while it is followed
const XP_LIVE_KEEP = 2000;         // events held on the page
const XP_LIVE_SHOWN = 600;         // lines drawn; older ones are in the run's log
const XP_LIVE_WHO = { worker: "worker", reviewer: "reviewer", run: "run", you: "you" };
const XP_LIVE_STATE = { going: "going", paused: "paused", waiting_for_you: "waiting for you",
                        ended: "ended", interrupted: "interrupted" };

function xpLiveState(runId) {
  experienceState.live = experienceState.live || {};
  if (!experienceState.live[runId]) {
    experienceState.live[runId] = { events: [], last: 0, tag: null, data: null,
                                    open: undefined, following: false, drawn: {} };
  }
  return experienceState.live[runId];
}

function xpLiveBody(runId) {
  return $(`[data-xp-live-body="${CSS.escape(runId)}"]`);
}

/* Its place in a run: open by default while the run is going - it is where
   the run asks you things. Closed, a request waiting for you is said on the
   run itself, with a way to open it. */
function xpLiveSection(run) {
  const live = xpLiveState(run.id);
  if (live.open === undefined) live.open = Boolean(run.alive);
  const waiting = run.alive && (run.status === "waiting for you"
    || ((run.plan || {}).packages || {}).requests?.some((one) => one.status === "pending")
    || ((live.data || {}).pending || []).length);
  const id = escapeHtml(run.id);
  return `${!live.open && waiting ? `<p><button type="button" class="small xp-live-badge"
      data-xp-live-open="${id}">waiting for you - open the session</button></p>` : ""}
    <details class="xp-live" data-xp-live="${id}"${live.open ? " open" : ""}>
      <summary data-xp-live-toggle="${id}"><strong>Live session</strong> - what the work
        agent and the reviewer are doing${run.alive ? ", as it happens" : ", as it went"}</summary>
      <div class="xp-live-body" data-xp-live-body="${id}"></div>
    </details>`;
}

/* A request waiting for you, as the session asks it. */
/* A moment, as the user reads it: "23:50", or "Oct 12 23:50" when it is not
   today - and how long until it. */
function xpWhen(iso) {
  const at = new Date(iso);
  if (!iso || Number.isNaN(at.getTime())) return "";
  const today = at.toDateString() === new Date().toDateString();
  const clock = at.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: false });
  const minutes = Math.round((at.getTime() - Date.now()) / 60000);
  const left = minutes <= 0 ? "" : minutes < 90 ? ` (in ${minutes} min)`
    : ` (in ${Math.floor(minutes / 60)} h ${minutes % 60} min)`;
  return `${today ? "" : `${at.toLocaleDateString([], { month: "short", day: "numeric" })} `}${clock}${left}`;
}

/* THE RUN WAITS ON ITS MODEL: what failed and why, where to mend it, when
   it looks again by itself - Try again now, or End the run. */
function xpModelAsk(runId, ask) {
  const id = escapeHtml(runId);
  const fix = ask.fix || {};
  const limit = ask.trouble === "limit";
  const resets = limit && ask.resets_at ? `<p>Resets at <strong>${escapeHtml(xpWhen(ask.resets_at))}</strong></p>` : "";
  const next = ask.next_look ? `<p class="muted">Looks again by itself at ${escapeHtml(xpWhen(ask.next_look))}${
    ask.looks ? ` · looked ${Number(ask.looks)} time${ask.looks === 1 ? "" : "s"} so far` : ""}</p>` : "";
  return `<div class="xp-package-ask xp-live-ask xp-model-ask">
    <p><strong>${escapeHtml(ask.title || "The model needs you")}</strong></p>
    <p>${escapeHtml(ask.what || "")}</p>
    ${resets}${next}
    <p class="muted">${escapeHtml(ask.note || "")}</p>
    ${fix.action ? `<button type="button" class="small" data-xp-model-fix="${escapeHtml(fix.provider || "")}">${
      escapeHtml(fix.label || "Open Settings")}</button>` : ""}
    ${fix.url ? `<a class="small" href="${escapeHtml(fix.url)}" target="_blank" rel="noopener">${
      escapeHtml(fix.url_label || fix.url)}</a>` : ""}
    <button type="button" class="small secondary" data-xp-approve="${id}"
      data-xp-request="${escapeHtml(ask.id)}" data-xp-allow="1">Try again now</button>
    <button type="button" class="small secondary danger" data-xp-approve="${id}"
      data-xp-request="${escapeHtml(ask.id)}" data-xp-allow="0"
      title="It ends not finished: Continue it once the model answers again">End the run</button>
  </div>`;
}

function xpLiveAsk(runId, ask) {
  if (ask.kind === "model") return xpModelAsk(runId, ask);
  const id = escapeHtml(runId);
  if (ask.kind === "action") {
    // A command outside the sandbox, asked only after other ways were tried.
    return `<div class="xp-package-ask xp-live-ask xp-action-ask">
      <p><strong>The agent asks you to approve a command, run outside the sandbox</strong></p>
      <p class="muted">Shell: <code>${escapeHtml(ask.shell || "")}</code></p>
      <p class="muted">Folder: <code>${escapeHtml(ask.cwd || "")}</code></p>
      <pre class="xp-action-command">${escapeHtml(ask.what || "")}</pre>
      <p>Why: ${escapeHtml(ask.why || "")}</p>
      ${(ask.tried || []).length ? `<p>What it tried first:</p><ul>${ask.tried.map((one) =>
        `<li>${escapeHtml(one)}</li>`).join("")}</ul>` : ""}
      <p class="muted">${escapeHtml(ask.note || "")}</p>
      <button type="button" class="small" data-xp-approve="${id}"
        data-xp-request="${escapeHtml(ask.id)}" data-xp-allow="1">Approve</button>
      <button type="button" class="small secondary" data-xp-approve="${id}"
        data-xp-request="${escapeHtml(ask.id)}" data-xp-allow="0">Deny</button>
    </div>`;
  }
  return `<div class="xp-package-ask xp-live-ask">
    <p><strong>The agent asks to install</strong> ${(ask.items || []).map((one) =>
      `<code>${escapeHtml(one)}</code>`).join(", ")}</p>
    <p>Why: ${escapeHtml(ask.why || "")}</p>
    <p class="muted">${escapeHtml(ask.note || "")}</p>
    <button type="button" class="small" data-xp-approve="${id}"
      data-xp-request="${escapeHtml(ask.id)}" data-xp-allow="1">Approve</button>
    <button type="button" class="small secondary" data-xp-approve="${id}"
      data-xp-request="${escapeHtml(ask.id)}" data-xp-allow="0">Deny</button>
  </div>`;
}

/* One line of the session: when, who, and what happened. A request shows
   its answer once it has one. */
function xpLiveRow(e) {
  // A PROGRESS POINT KEPT BEFORE ITS OWN LINE EXISTED (until 2026-10-27 it
  // was a bare note, "resume point saved", lost among the tool calls): shown
  // as one is now.
  if (e.kind === "note" && String(e.text || "").startsWith("resume point saved")) {
    e = Object.assign({}, e, { kind: "saved",
      text: "Saved a progress point: if the run is cut off, it goes on from here" });
  }
  const at = new Date(e.at);
  const time = Number.isNaN(at.getTime()) ? String(e.at || "").slice(11, 19)
    : at.toLocaleTimeString([], { hour12: false });
  const who = XP_LIVE_WHO[e.who] || e.who || "";
  const detail = e.detail || {};
  const failed = detail.ok === false;
  return `<li class="xp-live-ev xp-live-who-${escapeHtml(who)} xp-live-kind-${
    escapeHtml(e.kind || "")}${failed ? " xp-live-failed" : ""}" data-xp-live-seq="${
    Number(e.seq)}"><span class="xp-live-at">${escapeHtml(time)}</span>
    <span class="xp-live-who">${escapeHtml(who)}</span>
    <span class="xp-live-text">${escapeHtml(e.text || "")}</span>${
    e.kind === "permission" && detail.request ? ` <span class="xp-live-answer"
      data-xp-live-req="${escapeHtml(detail.request)}"></span>` : ""}${
    detail.tokens_in !== undefined || detail.tokens_out !== undefined
      ? ` <span class="xp-live-cost">${escapeHtml(xpTokenSplit(detail))}</span>`
      : detail.tokens ? ` <span class="xp-live-cost">${Number(detail.tokens).toLocaleString()} tokens</span>`
      : ""}${detail.full ? `<details class="xp-live-more"><summary>all of it</summary><pre
      class="xp-live-full">${escapeHtml(detail.full)}</pre></details>` : ""}${
    e.kind === "contract" && detail.diff ? `<details class="xp-contract-diff
      xp-live-diff"><summary>what changed</summary>${xpContractDiff(detail.diff)}</details>`
      : ""}</li>`;
}

/* One limit as a bar: what is used of it - or, with none set, what is used.
   `more`: said after it, as the tokens in and out. */
function xpLiveBar(label, used, limit, unit, more = "") {
  const value = Number(used || 0);
  const cap = Number(limit || 0);
  const share = cap > 0 ? Math.min(100, (value / cap) * 100) : 0;
  return `<div class="xp-live-bar"><span class="xp-live-bar-label">${escapeHtml(label)}</span>
    <span class="xp-live-bar-track"><span class="xp-live-bar-fill${share >= 90 ? " xp-live-bar-full" : ""}"
      style="width:${share.toFixed(1)}%"></span></span>
    <span class="xp-live-bar-value">${escapeHtml(value.toLocaleString())}${cap > 0
      ? ` / ${escapeHtml(cap.toLocaleString())}` : ""} ${escapeHtml(unit)}${cap > 0 ? "" : " (no limit)"}${
      more ? ` · ${escapeHtml(more)}` : ""}</span></div>`;
}

/* PAUSE, or RESUME when paused - for a run still going and not stopping;
   "" otherwise. Paused, the run stops at its next safe point and waits. */
function xpPauseButton(run, data) {
  const p = (data || {}).progress || {};
  const state = (data || {}).state || (run.alive ? (run.paused ? "paused" : "going")
    : run.status === "interrupted" ? "interrupted" : "ended");
  const id = escapeHtml(run.id);
  const going = ["going", "paused", "waiting_for_you"].includes(state);
  return !going || p.stopping || run.stopping ? ""
    : p.pause_asked || state === "paused"
      ? `<button type="button" class="small" data-xp-live-resume="${id}">Resume</button>`
      : `<button type="button" class="small secondary" data-xp-live-pause="${id}"
          title="Stops at the next safe point - before a model call, before a tool call, between rounds - and waits for you">Pause</button>`;
}

/* WORK'S SETTINGS ARE FOR THE NEXT START OR CONTINUE (the user, 2026-10-27):
   never sent to a run that goes. The going run's own are on the card at the
   top of its live session - changed there, sent to it at once. */
const XP_SETTINGS_NEXT = "These settings are for the next start or Continue. The run "
  + "going now is changed on \"Running with now\", at the top of its live session.";

/* THE ACTIVE SPEC CHANGED ON ITS CARD: sent to the run at once - all of the
   card, which shows what the run has. */
document.addEventListener("change", async (event) => {
  const card = event.target.closest && event.target.closest("[data-xp-active-spec]");
  if (!card || !card.dataset.xpAlive) return;
  const runId = card.dataset.xpActiveSpec;
  const limits = {};
  card.querySelectorAll("[data-xp-as-limit]").forEach((input) => {
    if (input.value.trim() !== "") limits[input.dataset.xpAsLimit] = Number(input.value);
  });
  const picked = card.querySelector(`input[name="xp-as-pk-${CSS.escape(runId)}"]:checked`);
  const sandbox = card.querySelector(`input[name="xp-as-sb-${CSS.escape(runId)}"]:checked`);
  const sound = card.querySelector(`input[name="xp-as-snd-${CSS.escape(runId)}"]:checked`);
  // The one just chosen lit at once, before the run says it back.
  if (event.target.type === "radio") {
    event.target.closest(".xp-seg").querySelectorAll("label").forEach((label) =>
      label.classList.toggle("xp-seg-lit", label.contains(event.target)));
  }
  try {
    await api.post("/api/work/settings", { run: runId, limits,
      ...(picked ? { packages: picked.value } : {}),
      ...(sound ? { sound: sound.value === "on" } : {}),
      ...(sandbox && !sandbox.disabled ? { unconfined: sandbox.value === "off" } : {}) });
    toast("Changed - in effect now");
    xpLiveFetch(runId).catch(() => {});
  } catch (err) {
    toast(err.message);
  }
});

/* A run's spec from what its record keeps - for a run whose own process
   says none (one started before it said its spec, going on still). */
function xpRecordSpec(run, progress) {
  const plan = (run || {}).plan || {};
  const session = (plan.sessions || []).slice(-1)[0] || {};
  const p = progress || {};
  return { way: plan.way || "", limits: p.limits || session.limits || plan.limits || {},
           packages: p.packages || (plan.packages || {}).mode || "auto",
           // Chosen by the user, not the default of the time it started.
           packages_chosen: Boolean((plan.packages || {}).chosen),
           sandbox: !plan.unconfined,
           sound: p.sound !== undefined ? Boolean(p.sound) : Boolean(session.sound) };
}

/* WHAT IT RUNS WITH NOW (the user, 2026-10-27): beside the live session the
   whole time - its way, its limits, how packages are asked for, the sandbox,
   the sound - as the run says them, changed when a Resume changes them. */
const XP_WAY_NAMES = { full: "the thorough way", quick: "the quick way",
  single: "one model alone", noctx: "a builder and a reviewer, without your context" };
const XP_LIMIT_NAMES = { minutes: "minutes", tokens_in: "input tokens",
  tokens_out: "output tokens", calls: "model calls", tokens: "tokens" };

function xpLiveSpec(spec, run) {
  if (!spec) return "";
  const alive = Boolean((run || {}).alive);
  const id = escapeHtml((run || {}).id || "");
  const off = alive ? "" : " disabled";
  const limits = spec.limits || {};
  const limit = (name, step = "") => `<label class="xp-spec-limit">${escapeHtml(
      XP_LIMIT_NAMES[name] || name)}<input type="number" min="0"${step ? ` step="${step}"` : ""}
      data-xp-as-limit="${name}" value="${Number(limits[name]) > 0
        ? escapeHtml(String(limits[name])) : ""}" placeholder="none"${off}></label>`;
  const way = XP_WAY_NAMES[spec.way] || spec.way_name || spec.way || "";
  const debug = typeof xpIsDebugRun === "function" && xpIsDebugRun(run || {});
  // A choice of two as one segmented control: the one in force lit.
  const seg = (name, choices, now, attrs, kind = "") => `<span class="xp-seg ${kind}">${
    choices.map(([value, words]) => `<label class="xp-seg-${value}${value === now
      ? " xp-seg-lit" : ""}"><input type="radio" name="${name}" value="${value}"${
      value === now ? " checked" : ""}${attrs}><span>${escapeHtml(words)}</span></label>`)
      .join("")}</span>`;
  return `<section class="xp-active-spec${spec.sandbox ? "" : " xp-spec-unsandboxed"}"
      data-xp-active-spec="${id}"${alive ? ' data-xp-alive="1"' : ""}>
    <div class="xp-spec-head"><strong>${alive ? "Running with now" : "Ran with"}</strong>
      ${alive ? `<span class="muted">- changes go to this run at once</span>` : ""}</div>
    <div class="xp-spec-grid">
      ${way ? `<div class="xp-spec-item"><span class="xp-spec-label">Way</span>
        <span class="xp-spec-chip">${escapeHtml(way)}</span></div>` : ""}
      <div class="xp-spec-item"><span class="xp-spec-label">Python packages</span>
        ${seg(`xp-as-pk-${id}`, [["ask", "Ask first"], ["auto", "Auto"]],
              spec.packages === "auto" ? "auto" : "ask", off)}</div>
      <div class="xp-spec-item"><span class="xp-spec-label">Sandbox</span>
        ${seg(`xp-as-sb-${id}`, [["on", "On"], ["off", "Off"]], spec.sandbox ? "on" : "off",
              debug ? " disabled" : off, "xp-seg-sandbox")}</div>
      <div class="xp-spec-item"><span class="xp-spec-label">Sound at the end</span>
        ${seg(`xp-as-snd-${id}`, [["on", "On"], ["off", "Off"]], spec.sound ? "on" : "off", off)}</div>
      ${spec.sandbox ? "" : `<p class="xp-warning xp-spec-warning">${
        escapeHtml(XP_UNCONFINED_WARNING)}</p>`}
      <div class="xp-spec-item xp-spec-limits"><span class="xp-spec-label">Limits</span>
        ${limit("minutes")} ${limit("tokens_in", "100000")} ${limit("tokens_out", "10000")}
        ${limit("calls")} <span class="muted">empty or 0: no limit</span></div>
    </div></section>`;
}

/* Where the run stands, like a progress bar: its state, the part of the
   run it is in, rounds and cards, the limits - and Pause or Resume, unless
   `pause` is false: in the Experience debugger they are beside the way's
   name, with Stop and Clear. */
function xpLiveHead(run, data, pause = true) {
  const p = (data || {}).progress || {};
  const state = (data || {}).state || (run.alive ? (run.paused ? "paused" : "going")
    : run.status === "interrupted" ? "interrupted" : "ended");
  const used = p.used || {};
  const limits = p.limits || ((run.plan || {}).limits) || {};
  const button = pause ? xpPauseButton(run, data) : "";
  const cards = p.cards !== undefined && p.cards !== null
    ? ` · ${Number(p.cards_done || 0)}/${Number(p.cards || 0)} cards done` : "";
  // The contract in force, in a line: what the work is held to, its line,
  // and its deliverables done of all.
  const c = (data || {}).contract || run.contract_in_force || null;
  const goal = c ? String(c.goal || "") : "";
  // THE INSTRUCTION IN FORCE, WHOLE: what the run was asked, and the words
  // each amendment of this line added - never cut, however long.
  const words = [String(run.instruction || ""), ...(((run.contract_in_force || {}).instructions)
    || ((run.plan || {}).contract || {}).instructions || []).map(String)]
    .filter((one) => one.trim());
  const instruction = words.length ? `<div class="xp-live-instruction"><span
    class="muted">instruction in force:</span>${words.map((one) =>
    `<div class="xp-live-instruction-words">${escapeHtml(one)}</div>`).join("")}</div>` : "";
  const contractLine = c && goal ? `<div class="xp-live-contract">
    <span class="muted">contract${c.amended || (c.instructions || []).length
      ? " (amended)" : ""}:</span> ${escapeHtml(goal)}
    <span class="muted">· ${escapeHtml(c.branch || "main")} · ${Number(c.done || 0)}/${
      Number(c.total || 0)} deliverables done</span></div>` : "";
  return `${instruction}${contractLine}${xpLiveSpec(p.spec || xpRecordSpec(run, p), run)}<div class="xp-live-line"><span class="xp-live-state xp-live-state-${escapeHtml(state)}">${
      escapeHtml(XP_LIVE_STATE[state] || state)}</span>
    <strong>${escapeHtml(p.stage || p.phase || "")}</strong>
    <span class="muted">${Number(p.rounds_done || 0)} round${Number(p.rounds_done) === 1 ? "" : "s"}
      done${cards}${Number(p.paused_minutes || 0) > 0 ? ` · ${escapeHtml(String(p.paused_minutes))}
      min paused (not counted)` : ""}</span> ${button}</div>
    ${xpLiveBar("minutes", used.minutes, limits.minutes, "min")}
    ${xpLiveTokenBars(used, limits)}
    ${xpLiveBar("model calls", used.calls, limits.calls, "")}${p.sound
      ? `<p class="muted xp-live-sound">A sound is played when it ends.</p>` : ""}`;
}

/* TOKENS against their limits: what went in and what came out, each against
   its own. A run started before the two were limited apart - or by a
   caller that set one limit on both - has that one: shown as it was, on
   the two together. */
function xpLiveTokenBars(used, limits) {
  const apart = limits.tokens_in !== undefined || limits.tokens_out !== undefined;
  const split = used.tokens_in !== undefined || used.tokens_out !== undefined
    ? xpTokenSplit(used) : "";
  const total = !apart || Number(limits.tokens || 0) > 0
    ? xpLiveBar("tokens", used.tokens, limits.tokens, "", split) : "";
  if (!apart) return total;
  return `${xpLiveBar("input tokens", used.tokens_in, limits.tokens_in, "")}
    ${xpLiveBar("output tokens", used.tokens_out, limits.tokens_out, "")}${total}`;
}

/* What it is doing this moment, with a spinner while it works. */
function xpLiveDoing(run, data) {
  const p = (data || {}).progress || {};
  const state = (data || {}).state || "";
  if (state === "ended" || state === "interrupted" || (!data && !run.alive)) return "";
  if (p.pause_asked && !p.held) return "pausing - at the next safe point…";
  return p.activity || (state === "waiting_for_you" ? "waiting for your answer" : "working…");
}

/* The session drawn - the first time whole, after that only what is new:
   the lines are added below, and the view follows them down only if you
   were already at the bottom. Scrolled up to read a line, it stays exactly
   where it is - the lines come in below, out of sight - and a small "N new
   ↓" at its foot says how many came, and takes you down when pressed; at
   the bottom again, it goes. Nothing here moves the page itself: the box is
   as tall from its first line as at its six hundredth. */
function xpLiveDraw(runId, fresh, force) {
  const body = xpLiveBody(runId);
  if (!body) return;
  const live = xpLiveState(runId);
  const run = xpVersionsState().runs[runId] || { id: runId };
  let first = false;
  if (!body.querySelector(".xp-live-scroll")) {
    body.innerHTML = `<div class="xp-live-head"></div>
      <p class="xp-live-doing"><span class="xp-live-spin" aria-hidden="true"></span>
        <span class="xp-live-doing-text"></span></p>
      <div class="xp-live-scroll" tabindex="0" aria-label="The live session"
        data-xp-keep="live:${escapeHtml(runId)}">
        <ol class="xp-live-log"></ol><div class="xp-live-asks"></div>
        <p class="xp-live-foot muted"></p>
        <button type="button" class="small xp-live-new" hidden
          title="Down to the newest line"></button></div>`;
    live.drawn = {};
    live.unseen = 0;
    fresh = live.events;
    first = true;
    const scroller = body.querySelector(".xp-live-scroll");
    const jump = body.querySelector(".xp-live-new");
    scroller.addEventListener("scroll", () => {
      if (scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 24 && live.unseen) {
        live.unseen = 0;
        jump.hidden = true;
      }
    }, { passive: true });
    jump.addEventListener("click", () => {
      live.unseen = 0;
      jump.hidden = true;
      scroller.scrollTop = scroller.scrollHeight;
    });
  }
  const scroller = body.querySelector(".xp-live-scroll");
  const atBottom = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 24;
  const data = live.data;
  // Each part redrawn only when it changed - the spinner keeps turning.
  // No Pause in its line: it is beside the project's name (real work) or
  // the way's (the Experience debugger), with Stop.
  const parts = { head: xpLiveHead(run, data, false), doing: xpLiveDoing(run, data) };
  if (body.closest("#xp-work") && run.alive) xpDrawTitleRun(run);
  // Before the session is first heard from, a request is asked from the
  // run as the panel has it.
  const pending = data && Array.isArray(data.pending) ? data.pending
    : (run.alive ? (((run.plan || {}).packages || {}).requests || [])
      .filter((one) => one.status === "pending").map((one) => ({
        id: one.id, items: one.packages || [], why: one.why || "",
        note: "From PyPI, wheels only, into this run's own folder. The run waits for "
          + "your answer; the wait does not count against its minutes." })) : []);
  parts.asks = pending.map((one) => xpLiveAsk(runId, one)).join("");
  const resumes = (data || {}).resumes_from || (xpGoesBack(run) ? run.milestone : null);
  const why = XP_GOES_BACK[run.status] || XP_GOES_BACK.interrupted;
  parts.foot = resumes && resumes.version
    ? (resumes.resume
      ? `It did not stop cleanly - ${escapeHtml(why)}. Resume goes back to its progress
        point, ${escapeHtml(resumes.label || "")} - saved every 10 minutes of work, not
        checked; what came after is given up.`
      : `It did not stop cleanly - ${escapeHtml(why)}. Resume goes back to its last version:
      ${escapeHtml(resumes.version)} - ${escapeHtml(resumes.label || "")}; what came after is
      given up.`)
    : !live.events.length ? (run.alive ? "Nothing yet - it starts in a moment."
      : "Nothing was kept of this session.") : "";
  // Not drawn again while the run's card is being changed: its values follow
  // once the field is left (the change is sent as it is made).
  const editing = document.activeElement && document.activeElement.closest
    && document.activeElement.closest(".xp-active-spec");
  if ((force || live.drawn.head !== parts.head) && !(editing && body.contains(editing))) {
    body.querySelector(".xp-live-head").innerHTML = parts.head;
  }
  if (force || live.drawn.doing !== parts.doing) {
    body.querySelector(".xp-live-doing-text").textContent = parts.doing;
    // Nothing being done - the run ended: the line is kept, empty, so the
    // session below it does not jump up under the reader.
    body.querySelector(".xp-live-doing").classList.toggle("xp-live-doing-none", !parts.doing);
    body.querySelector(".xp-live-spin").hidden = /^paused|^pausing|^waiting/.test(parts.doing);
  }
  if (force || live.drawn.asks !== parts.asks) body.querySelector(".xp-live-asks").innerHTML = parts.asks;
  if (force || live.drawn.foot !== parts.foot) body.querySelector(".xp-live-foot").innerHTML = parts.foot;
  live.drawn = parts;
  const log = body.querySelector(".xp-live-log");
  if (fresh && fresh.length) {
    log.insertAdjacentHTML("beforeend", fresh.slice(-XP_LIVE_SHOWN).map(xpLiveRow).join(""));
    while (log.children.length > XP_LIVE_SHOWN) log.firstElementChild.remove();
  }
  // Each request's answer, beside where it was asked.
  const requests = (data || {}).requests || {};
  $$("[data-xp-live-req]", log).forEach((span) => {
    const said = requests[span.dataset.xpLiveReq];
    const status = said ? said.status : "";
    span.textContent = !status ? "" : status === "pending" ? "- waiting for your answer, below"
      : `- ${status}${said.note ? ` (${said.note})` : ""}`;
    span.className = `xp-live-answer xp-live-answer-${status === "approved"
      || status === "installed" ? "yes" : status === "pending" ? "wait" : "no"}`;
  });
  const jump = body.querySelector(".xp-live-new");
  if (atBottom || first) {
    scroller.scrollTop = scroller.scrollHeight;
    live.unseen = 0;
  } else if (fresh && fresh.length) {
    live.unseen = (live.unseen || 0) + fresh.length;
  }
  if (jump) {
    jump.hidden = !live.unseen;
    jump.textContent = `${live.unseen} new ↓`;
  }
  // Where the run is drawn in a way of the Experience debugger, the way's
  // own heading says its state too - changed in place with the session.
  xdWayFollow(runId);
}

/* What the session said, taken in: the new events, and where it stands.
   The panel around it is redrawn when what it shows has changed - the
   run's state, a request, a version, a part of the run begun or ended. */
function xpLiveTake(runId, data) {
  const live = xpLiveState(runId);
  const before = live.data;
  const fresh = (data.events || []).filter((e) => Number(e.seq) > live.last);
  live.events.push(...fresh);
  if (live.events.length > XP_LIVE_KEEP) live.events.splice(0, live.events.length - XP_LIVE_KEEP);
  live.last = Math.max(live.last, Number(data.last || 0), ...fresh.map((e) => Number(e.seq)));
  live.data = data;
  xpLiveDraw(runId, fresh);
  // The calls made since, onto the chart as they come.
  if (xpCallsTake(runId, data.calls)) xpCallsDraw(runId);
  if (before && (before.state !== data.state
      || (before.pending || []).length !== (data.pending || []).length
      || fresh.some((e) => ["version", "end", "answer"].includes(e.kind)))) {
    xpLiveRedrawPanel();
  }
}

async function xpLiveFetch(runId) {
  const live = xpLiveState(runId);
  // Its model calls too - those after the last one seen - for the chart.
  const got = await api.getIfChanged(`/api/work/live?run=${encodeURIComponent(runId)
    }&since=${live.last}&calls=${xpCallsState(runId).last}`, live.tag);
  live.tag = got.tag;
  if (got.changed && got.data) xpLiveTake(runId, got.data);
}

/* Followed about once a second while the view is open and can be seen -
   not while the page is hidden or another tab is shown, and not after the
   run has ended: then one last look, and the following stops. */
async function xpLiveFollow(runId) {
  const live = xpLiveState(runId);
  if (live.following) return;
  live.following = true;
  const unit = experienceState.unit;
  // The tab the run is drawn in - the Experience tab, or the Debugger's
  // Experience debugger - and whether it is the one shown.
  const tabOf = () => ((xpLiveBody(runId) || {}).closest?.(".tab") || {}).id || "";
  try {
    while (live.open && xpLiveBody(runId)
           && (tabOf() !== "experience" || experienceState.unit === unit)) {
      if (!document.hidden && activeTab === tabOf()) {
        try {
          await xpLiveFetch(runId);
        } catch (err) {
          /* following is an aid: the next look tries again */
        }
        const state = (live.data || {}).state;
        if (state === "ended" || state === "interrupted") break;
      }
      await new Promise((resolve) => setTimeout(resolve, XP_LIVE_EVERY));
    }
  } finally {
    live.following = false;
  }
}

/* The panel redrawn soon - not while something in it is being typed: then
   once that is left (xpLoadRuns defers itself). */
function xpLiveRedrawPanel() {
  clearTimeout(experienceState.liveRedraw);
  experienceState.liveRedraw = setTimeout(() => {
    if (activeTab === "experience") xpLoadRuns();
    else if (activeTab === "xdebug") loadDebuggerExperience();
  }, 250);
}

/* A RUN'S VERSIONS - saved at each key point: the contract approved, a
   round that advanced, a full review, the final review, the deck, the end
   of a session. Kept here as the panel is redrawn: each run's tree once
   loaded, which are open, the version viewed, and the one Continue is set
   to go on from. */
function xpVersionsState() {
  experienceState.runVersions = experienceState.runVersions
    || { trees: {}, open: {}, views: {}, from: {}, runs: {} };
  const kept = experienceState.runVersions;
  // Which version each run is shown at (xpVersionPicked); what its tree was
  // loaded for - how many versions, and the head - so it is asked for again
  // only when a version was saved; and whose results slides are open.
  kept.picked = kept.picked || {};
  kept.treeSig = kept.treeSig || {};
  kept.decks = kept.decks || {};
  // What you are writing for Continue - kept as the panel is redrawn - and
  // which deliverables you opened to read what they must meet.
  kept.words = kept.words || {};
  kept.criteria = kept.criteria || {};
  // Whether a sound is to be played when the session Continue starts ends.
  kept.sound = kept.sound || {};
  return kept;
}

/* WHAT AN AMENDMENT CHANGED in the contract, clause by clause: "+" a clause
   put in, "-" one taken out, the rest as it was. */
function xpContractDiff(diff) {
  const lines = String(diff || "").split("\n").filter((one) => one.trim());
  if (!lines.length) return `<p class="muted">No clause changed.</p>`;
  return `<pre class="xp-diff">${lines.map((one) => {
    const mark = one.slice(0, 2);
    const kind = mark === "+ " ? "add" : mark === "- " ? "del" : "same";
    return `<span class="xp-diff-${kind}">${escapeHtml(one)}</span>`;
  }).join("\n")}</pre>`;
}

/* The words a line was continued with, verbatim - and, folded, what they
   changed in its contract. */
function xpAmendedNote(amended) {
  if (!amended) return "";
  const said = amended.said || (amended.words || []).slice(-1)[0] || "";
  return `<div class="xp-amended">
    <span class="xp-badge-instruction">instruction</span>
    <span class="xp-amended-words">${escapeHtml(said)}</span>
    ${(amended.reopened || []).length ? `<span class="muted">· opened again: ${
      amended.reopened.map(escapeHtml).join("; ")}</span>` : ""}
    <details class="xp-contract-diff"><summary>contract changes</summary>
      ${xpContractDiff(amended.diff)}</details>
  </div>`;
}

/* Where to say what to change from here - optional: said, the contract is
   amended for the line the run goes on before any more work. */
function xpContinueWords(runId, needed = false) {
  const words = xpVersionsState().words[runId] || "";
  // A FINISHED RUN goes on only with words: the next thing to do, building
  // on what is done.
  return `<label class="xp-continue-words"><span>${needed
      ? "What to do next, building on what is done"
      : "What to change from here (optional)"}</span>
    <textarea rows="2" maxlength="4000" data-xp-continue-instruction="${escapeHtml(runId)}"
      placeholder="${needed
        ? "In your own words - a new task on top of the finished work. The contract is amended by it first (the reviewer checks it follows your words), then the work goes on."
        : "In your own words. The contract is amended for this branch first - the reviewer checks it follows your words - then the work goes on. Left empty, it goes on as it is."}">${
      escapeHtml(words)}</textarea></label>`;
}

const XP_DELIVERABLE_STATUS = { done: "done", working: "working", open: "open",
                                set_aside: "set aside" };

/* A CONTRACT: its goal and scope, the user's words for its line, and each
   deliverable with where it stands - what it must meet and how to go about
   it, the standard the work agent is given, one click away. `heading` says
   which contract it is - the one in force, or a version's, which is not;
   `amended` is what the line's words changed in it; `key` keeps which
   deliverables are open as the panel is redrawn. */
/* THE CORE PROMISES, as the reviewer or the tester last found each - and
   what only the user can check or do, from every milestone. */
const XP_PROMISE_STATE = { yes: "holds", no: "does not hold", untried: "not tried yet",
                           needs_user: "needs you" };

function xpPromisesBlock(c) {
  const promises = c.promises || [];
  const yours = c.for_user || [];
  const list = promises.length ? `<p class="xp-contract-line"><strong>Core promises</strong>
    <span class="muted">what you asked for, tried as you would use it - the work is not
    done until each holds</span></p>
    <ul class="xp-promises">${promises.map((one) => {
      const state = one.holds || "untried";
      return `<li><span class="xp-promise-state xp-promise-${escapeHtml(state)}">${escapeHtml(
        XP_PROMISE_STATE[state] || state)}</span> <strong>${escapeHtml(one.id || "")}</strong>
        ${escapeHtml(one.promise || "")}
        ${one.real_condition ? `<div class="muted">tried by: ${escapeHtml(one.real_condition)}</div>` : ""}
        ${state === "no" && one.failed ? `<div class="xp-promise-failed">last failed: ${
          escapeHtml(one.failed)}</div>` : ""}
        ${state === "needs_user" && one.user_does ? `<div>for you: ${escapeHtml(one.user_does)}</div>` : ""}
      </li>`;
    }).join("")}</ul>` : "";
  const mine = yours.length ? `<div class="xp-for-user"><p class="xp-contract-line"><strong>For you
    to check or do</strong> <span class="muted">only what the work could not do or check
    itself</span></p><ul>${yours.map((one) => `<li>${escapeHtml(one.do || "")}${one.promise
      ? ` <span class="muted">(${escapeHtml(one.promise)})</span>` : ""} <span class="muted">- from
      ${escapeHtml(one.milestone || "")}${one.why ? `: ${escapeHtml(one.why)}` : ""}</span></li>`)
      .join("")}</ul></div>` : "";
  return list + mine;
}

/* WHAT WAS ADDED, NOT YOUR WORDS - what the reviewer or the work agent found
   you would expect, by whom and on what; each can be taken out (on a run
   not working now). The added words are the agent's, never translated. */
const XP_ADDED_KIND = { implied: "part of a core promise", needed: "needed",
                        nice: "nice to have" };
const XP_ADDED_BY = { "the reviewer": "added by the reviewer",
                      "the work agent": "added by the work agent" };

function xpAddedBlock(c) {
  const added = c.added || [];
  if (!added.length) return "";
  return `<div class="xp-added"><p class="xp-contract-line"><strong>Added - not your
    words</strong> <span class="muted">what the work found you would expect; take out
    what you do not want</span></p>
    <ul>${added.map((one) => `<li><span class="xp-added-kind">${escapeHtml(
      XP_ADDED_KIND[one.kind] || one.kind || "")}</span>
      <span class="xp-added-words">${escapeHtml(one.need || "")}</span>
      <span class="muted">${escapeHtml(XP_ADDED_BY[one.by] || one.by || "")}</span>${one.promise
        ? ` <span class="muted xp-added-words">(${escapeHtml(one.promise)})</span>` : ""}
      ${(one.because || []).length ? `<div class="muted"><span>rests on:</span> <span
        class="xp-added-words">${escapeHtml(one.because.join("; "))}</span></div>` : ""}
      ${c.run ? `<button type="button" class="small" data-xp-take-out="${escapeHtml(
        one.id || "")}" data-xp-take-out-run="${escapeHtml(c.run)}">Take it out</button>` : ""}
    </li>`).join("")}</ul></div>`;
}

function xpContractBlock(c, heading, amended, key, notInForce) {
  const kept = xpVersionsState();
  const items = c.deliverables || [];
  const words = c.instructions || [];
  const done = items.filter((d) => d.status === "done").length;
  const anyStatus = items.some((d) => d.status);
  return `<section class="xp-contract-now${notInForce ? " xp-contract-not-in-force" : ""}">
    ${heading}
    <p class="xp-contract-line"><strong>Goal:</strong> ${escapeHtml(c.goal || "")}</p>
    ${(c.scope || []).length ? `<p class="xp-contract-line"><strong>In scope:</strong> ${
      c.scope.map(escapeHtml).join("; ")}</p>` : ""}
    ${(c.out_of_scope || []).length ? `<p class="xp-contract-line"><strong>Out of scope:</strong> ${
      c.out_of_scope.map(escapeHtml).join("; ")}</p>` : ""}
    ${words.length ? `<div class="xp-contract-words"><span class="xp-badge-instruction">your
      words for this branch</span>${words.map((one) => `<blockquote class="xp-amended-words">${
      escapeHtml(one)}</blockquote>`).join("")}
      ${amended && amended.diff ? `<details class="xp-contract-diff"><summary>what changed in
        the contract</summary>${xpContractDiff(amended.diff)}</details>` : ""}</div>` : ""}
    ${xpPromisesBlock(c)}
    ${xpAddedBlock(c)}
    ${items.length ? `<p class="xp-contract-line"><strong>Deliverables</strong> <span
      class="muted">${anyStatus ? `${done}/${items.length} done · ` : ""}open one for what it
      must meet</span></p>
    <ul class="xp-contract-deliverables">${items.map((d) => {
      const at = `${key}|${d.card || d.title}`;
      const criteria = d.criteria || [];
      const status = d.status || "";
      return `<li><details class="xp-deliverable"${kept.criteria[at] ? " open" : ""}>
        <summary data-xp-deliverable="${escapeHtml(at)}">${status ? `<span
          class="xp-status xp-status-${escapeHtml(status)}">${escapeHtml(
          XP_DELIVERABLE_STATUS[status] || status)}</span> ` : ""}${d.tier ? `<span
          class="xp-tier xp-tier-${escapeHtml(d.tier)}" title="${escapeHtml(
          (d.serves || []).length ? `serves ${d.serves.join(", ")}` : d.tier)}">${escapeHtml(
          d.tier)}</span> ` : ""}<strong>${escapeHtml(
          d.title || "")}</strong> - ${escapeHtml(d.statement || "")} <span class="muted">·
          ${criteria.length} criteri${criteria.length === 1 ? "on" : "a"}</span></summary>
        <div class="xp-deliverable-body">
          ${criteria.length ? `<p><strong>It must meet:</strong></p><ol class="xp-criteria">${
            criteria.map((one) => `<li>${escapeHtml(one.text || "")}${one.backed_by
              ? ` <span class="muted">(${escapeHtml(one.backed_by)})</span>` : ""}</li>`).join("")}</ol>`
            : `<p class="muted">Its criteria are not written yet: the reviewer writes them
              before its first round.</p>`}
          ${d.approach ? `<p><strong>How to go about it:</strong> ${escapeHtml(d.approach)}</p>` : ""}
          ${d.card && !notInForce ? `<p><a href="#" data-xp-card="${escapeHtml(d.card)}"
            data-xp-where="work">Its card in the tree</a> <span class="muted">- with what
            each criterion rests on</span></p>` : ""}
        </div></details></li>`;
    }).join("")}</ul>` : ""}
  </section>`;
}

const XP_VERSION_KIND = {
  contract: "contract approved", amended: "contract amended", round: "round advanced",
  "full review": "full review",
  "final review": "final review", deck: "deck made", finished: "finished",
  paused: "paused", stopped: "stopped", "limit reached": "limit reached", ended: "ended",
  turn: "turn",
};

/* A RUN'S VERSIONS, AS A TREE YOU CAN WALK - drawn like a commit graph: a
   row per version, the newest on top, each with what it changed in a line
   (its message's title - or, saved before versions had messages, its
   label), how many files it added, changed and deleted, and when. On the
   left the graph: the main line straight down its lane, each branch -
   continued from an older version - on a lane of its own, forking from the
   version it began at. A dot per version; the head ringed; the version
   shown filled, its row marked. In a box of its own size, with its own
   scrollbar: a long history scrolls in the box, and the page does not grow.

   CLICKING A VERSION SHOWS THE WHOLE RUN AS IT STOOD THEN: what it changed
   - its message whole, and its files - the contract it held, its slides,
   where it stood - instead of the latest; a line on top of the run says
   so, with the way back to the latest. The choice is the run's, kept as the
   panel is redrawn and the page reloaded (in this browser: XP_PICKED_KEY).
   "Continue from here" is offered on the version shown - from the head it
   is the ordinary Continue; from another it rolls back, and goes on as a
   new branch, the versions after it kept.

   A version saved while you look is added to the tree in place: a new row
   on top, the one you picked still picked, the box where you scrolled it -
   at the top, if that is where you were, to follow the newest. The same
   versions are also a list - "As a list" - every one a line of text. */
const XP_PICKED_KEY = "pa.xp.version.";
const XP_VGRAPH = { row: 26, lane: 16, left: 12, r: 5 };

/* What a version changed: its message - a title, its points, its files -
   or, for one saved before versions had messages, its label alone. */
function xpVersionMessage(v) {
  const said = (v && typeof v.message === "object" && v.message) || {};
  const files = said.files || {};
  const list = (name) => (Array.isArray(files[name]) ? files[name].map(String) : []);
  return { title: String(said.title || (v || {}).label || ""),
           body: (Array.isArray(said.body) ? said.body : said.body ? [said.body] : [])
             .map(String).filter((one) => one.trim()),
           added: list("added"), modified: list("modified"), deleted: list("deleted"),
           known: Boolean(said.files) };
}

/* +added ~modified -deleted, as a commit list says it. */
function xpVersionCounts(m, id) {
  if (!m.known) return "";
  const said = `${m.added.length} added, ${m.modified.length} changed, ${m.deleted.length} deleted`;
  return `<span class="xp-vfiles" title="${escapeHtml(said)}"${id ? ` data-xp-vfiles="${
    escapeHtml(id)}"` : ""}><span class="xp-vfiles-add">+${m.added.length}</span>
    <span class="xp-vfiles-mod">~${m.modified.length}</span>
    <span class="xp-vfiles-del">−${m.deleted.length}</span></span>`;
}

/* The version shown, said as a commit is: its title whole, its points, and
   the files it added, changed and deleted - folded, in a box of their own
   size. */
function xpVersionHeader(v) {
  const m = xpVersionMessage(v);
  const files = (name, label) => (m[name].length ? `<div class="xp-vmsg-files-${name}"><strong>${
    label} (${m[name].length})</strong><ul class="xp-work-list">${m[name].map((one) =>
    `<li><code>${escapeHtml(one)}</code></li>`).join("")}</ul></div>` : "");
  const all = m.added.length + m.modified.length + m.deleted.length;
  return `<div class="xp-vmsg" data-xp-vmsg="${escapeHtml(v.id || "")}">
    <h4 class="xp-vmsg-title"><span class="xp-vrow-id">${escapeHtml(v.id || "")}</span>
      ${escapeHtml(m.title || XP_VERSION_KIND[v.kind] || v.kind || "")}</h4>
    ${m.body.length ? `<ul class="xp-vmsg-body">${m.body.map((one) =>
      `<li>${escapeHtml(one)}</li>`).join("")}</ul>` : ""}
    ${m.known ? `<details class="xp-vmsg-files"><summary class="muted">Files it changed
      (${all}) ${xpVersionCounts(m)}</summary><div class="xp-vmsg-files-box">${
      files("added", "Added")}${files("modified", "Changed")}${files("deleted", "Deleted")}${
      all ? "" : `<p class="muted">No file changed.</p>`}</div></details>` : ""}
  </div>`;
}

/* The tree drawn: the graph's lanes as SVG on the left, a row per version
   beside it - each row as tall as the graph's step, so the two line up. */
function xpVersionGraph(run, tree) {
  if (!tree) return `<p class="muted">loading…</p>`;
  const all = (tree.versions || []).slice();
  if (!all.length) return `<p class="muted">No versions yet.</p>`;
  const G = XP_VGRAPH;
  // The newest on top.
  const order = all.map((v, i) => ({ v, i }))
    .sort((a, b) => (Number(b.v.n) || b.i + 1) - (Number(a.v.n) || a.i + 1)).map((one) => one.v);
  // Lanes in the order the lines began: the first line on the left.
  const lanes = [];
  const laneOf = {};
  order.slice().reverse().forEach((v) => {
    const line = v.branch || "main";
    if (!(line in laneOf)) { laneOf[line] = lanes.length; lanes.push(line); }
  });
  const at = {};
  order.forEach((v, row) => {
    at[v.id] = { x: G.left + laneOf[v.branch || "main"] * G.lane, y: row * G.row + G.row / 2 };
  });
  const picked = xpVersionPicked(run.id);
  const id = escapeHtml(run.id);
  const width = G.left * 2 + (lanes.length - 1) * G.lane;
  const height = order.length * G.row;
  const parts = [];
  // Each version joined to the one it was saved after: straight up its
  // lane; a branch leaves its parent's lane in a curve, then goes up its own.
  order.forEach((v) => {
    const to = at[v.id];
    const from = at[v.parent || ""];
    if (!from) return;
    if (from.x === to.x) {
      parts.push(`<line class="xp-vedge" x1="${from.x}" y1="${from.y}" x2="${to.x}" y2="${to.y}"></line>`);
      return;
    }
    const bend = Math.max(to.y, from.y - G.row);
    parts.push(`<path class="xp-vedge" d="M${from.x},${from.y} C${from.x},${(from.y + bend) / 2} ${
      to.x},${(from.y + bend) / 2} ${to.x},${bend} L${to.x},${to.y}"></path>`);
  });
  order.forEach((v) => {
    const { x, y } = at[v.id];
    parts.push(`<circle class="xp-vnode-dot${v.id === tree.head ? " xp-vnode-head" : ""}${
      v.id === picked ? " xp-vnode-shown" : ""}" data-xp-vdot="${escapeHtml(v.id)}" cx="${x}"
      cy="${y}" r="${G.r}"></circle>`);
  });
  const rows = order.map((v) => {
    const m = xpVersionMessage(v);
    const head = v.id === tree.head;
    const shown = v.id === picked;
    const title = m.title || XP_VERSION_KIND[v.kind] || v.kind || "";
    const said = `${v.id}: ${title}${head ? " (head)" : ""}`;
    return `<li class="xp-vrow${head ? " xp-vrow-head" : ""}${shown ? " xp-vrow-shown" : ""}"
      data-xp-version-node="${escapeHtml(v.id)}" data-xp-version-run="${id}" tabindex="0"
      role="button" aria-pressed="${shown ? "true" : "false"}" aria-label="${escapeHtml(said)}">
      <span class="xp-vrow-id">${escapeHtml(v.id)}</span>
      <span class="xp-vrow-title" title="${escapeHtml(title)}">${escapeHtml(title)}</span>
      ${xpVersionCounts(m, v.id)}
      ${head ? `<span class="xp-vrow-tag">head</span>` : ""}
      <span class="xp-vrow-when muted">${escapeHtml(localStamp(v.at, "short"))} · ${escapeHtml(v.branch || "main")}</span>
    </li>`;
  }).join("");
  return `<div class="xp-vlog" style="--xp-vrow:${G.row}px">
    <svg class="xp-vlog-lanes" width="${width}" height="${height}" viewBox="0 0 ${width} ${
      height}" aria-hidden="true">${parts.join("")}</svg>
    <ol class="xp-vlog-rows" style="margin-left:${width}px" aria-label="The run's versions,
      the newest first">${rows}</ol></div>`;
}

/* The version a run is shown at - "" for the latest. */
function xpVersionPicked(runId) {
  const kept = xpVersionsState();
  if (!(runId in kept.picked)) {
    let saved = "";
    try { saved = localStorage.getItem(XP_PICKED_KEY + runId) || ""; } catch (err) { saved = ""; }
    kept.picked[runId] = saved;
  }
  return kept.picked[runId] || "";
}

function xpVersionPick(runId, versionId) {
  const kept = xpVersionsState();
  kept.picked[runId] = versionId || "";
  try {
    if (versionId) localStorage.setItem(XP_PICKED_KEY + runId, versionId);
    else localStorage.removeItem(XP_PICKED_KEY + runId);
  } catch (err) { /* kept for this page only */ }
}

/* The version picked, as loaded - if it is one the run is not at now: the
   run is then shown as it stood at it. Null when the latest is shown. */
function xpVersionSeen(run) {
  const kept = xpVersionsState();
  const picked = xpVersionPicked(run.id);
  const view = kept.views[run.id];
  if (!picked || !view || view.picked !== picked) return null;
  const head = (kept.trees[run.id] || {}).head || (run.versions || {}).head || "";
  return picked === head ? null : view;
}

/* Under the tree: the version shown - its slides, where it stood, its
   files - and Continue from it; or, with the latest shown, how to look. */
function xpVersionPickedHtml(run, idle) {
  const kept = xpVersionsState();
  const picked = xpVersionPicked(run.id);
  const v = kept.views[run.id];
  if (!picked) {
    return `<p class="muted xp-version-hint">The latest is shown. Click a version in the tree to
      see the whole run as it stood then.</p>`;
  }
  if (!v || v.picked !== picked) return `<p class="muted">loading ${escapeHtml(picked)}…</p>`;
  const tree = kept.trees[run.id] || {};
  const head = v.id === (tree.head || (run.versions || {}).head);
  const going = run.alive || tree.alive;
  // From the head is the ordinary Continue; from any other version it rolls
  // back - for a finished run too. Not while a run is going.
  const canFrom = idle && !going && (!head || run.continuable || run.extendable);
  const from = kept.from[run.id] || "";
  const id = escapeHtml(run.id);
  return `${canFrom ? (from === v.id ? `<div class="xp-version-continue">
      ${xpContinueWords(run.id, head && run.extendable)}
      <button type="button" class="small" data-xp-continue="${id}">Continue
        from ${escapeHtml(v.id || "")}</button>
      ${xpContinueSound(run.id)}</div>`
    : `<p class="xp-version-from-row"><button type="button" class="small" data-xp-version-from="${
      escapeHtml(v.id)}" data-xp-version-run="${id}">Continue from here</button>
      <span class="muted">${head ? "- the latest: where it stopped"
        : `- its files and where it stood come back, and it goes on as a new branch from
          ${escapeHtml(v.id || "")}; the versions after it are kept`}</span></p>`) : ""}
    ${xpVersionHeader(xpVersionWithMessage(run.id, v))}
    ${xpVersionView(run, v)}`;
}

/* A version as loaded, with its message - from the version itself, else
   from its line in the tree. */
function xpVersionWithMessage(runId, v) {
  const line = (((xpVersionsState().trees[runId] || {}).versions) || [])
    .find((one) => one.id === v.id) || {};
  return { ...line, ...v, message: v.message || line.message, label: v.label || line.label };
}

/* Its place in a run: the tree, the version shown under it, the list. */
function xpVersionsModule(run, idle) {
  const kept = xpVersionsState();
  const id = escapeHtml(run.id);
  const tree = kept.trees[run.id];
  const count = tree ? (tree.versions || []).length : Number((run.versions || {}).count || 0);
  return `<div class="xp-versions-module" data-xp-keep="versions:${id}">
    <h4 class="xp-versions-title">Versions (<span data-xp-versions-count="${id}">${count}</span>)
      <span class="muted">- saved at each key point: click one to see the run as it stood
      then, and continue from it</span></h4>
    <div class="xp-progress-point" data-xp-progress="${id}">${xpProgressPoint(run, tree, idle)}</div>
    <div class="xp-version-graph" data-xp-version-graph="${id}" data-xp-keep="vgraph:${id}">${
      xpVersionGraph(run, tree)}</div>
    <div class="xp-version-picked" id="xp-version-view-${id}" data-xp-keep="vpicked:${id}">${
      xpVersionPickedHtml(run, idle)}</div>
    <details class="xp-versions"${kept.open[run.id] ? " open" : ""}>
      <summary data-xp-versions="${id}" class="muted">As a list</summary>
      <div class="xp-version-list" id="xp-versions-${id}" data-xp-keep="vlist:${id}">${tree
        ? xpVersionTree(run, tree, idle) : `<p class="muted">loading…</p>`}</div>
    </details>
  </div>`;
}

/* THE PROGRESS POINT (agent/work/runner.py, PROGRESS_POINT_MINUTES): saved
   every ten minutes of work, in the middle of a round too - the latest only,
   and not a version: nothing checked it. A run cut off goes on from it; a
   run stopped can be continued from it. */
function xpProgressPoint(run, tree, idle) {
  const point = tree && tree.progress;
  if (!point) return "";
  const kept = xpVersionsState();
  const going = run.alive || tree.alive;
  const picked = kept.from[run.id] === "progress";
  const id = escapeHtml(run.id);
  return `<p class="xp-progress-line"><strong>Progress point</strong>
      <span class="xp-progress-unchecked">not checked</span>
      ${escapeHtml(point.label || "")} <span class="muted">· ${escapeHtml(localStamp(point.at))}
      · ${Number(point.files || 0)} files · saved every 10 minutes of work; if the run is
      cut off, it goes on from here</span>
      ${idle && !going && !picked ? `<button type="button" class="small secondary"
        data-xp-progress-from="${id}">Continue from here</button>` : ""}</p>
    ${idle && !going && picked ? `<div class="xp-version-continue">
      ${xpContinueWords(run.id, false)}
      <button type="button" class="small" data-xp-continue="${id}">Continue from the
        progress point</button>
      ${xpContinueSound(run.id)}</div>` : ""}`;
}

/* The tree and the list drawn again in their boxes - each only if it
   changed, each keeping where it is scrolled to (at the right end, it
   follows the newest). */
function xpVersionsPut(runId) {
  const kept = xpVersionsState();
  const run = kept.runs[runId];
  const tree = kept.trees[runId];
  if (!run || !tree) return;
  const key = CSS.escape(runId);
  const idle = kept.idle && runId in kept.idle ? kept.idle[runId] : !kept.going;
  // `newestFirst`: rows come in on top - scrolled down, the box keeps the
  // rows you read where they were; at the top, it shows the newest.
  const put = (at, html, newestFirst) => {
    if (!at || at._xpHtml === xpShows(html)) return;
    const left = at.scrollLeft;
    const top = at.scrollTop;
    const tall = at.scrollHeight;
    at.innerHTML = html;
    at._xpHtml = xpShows(html);
    at.scrollLeft = left;
    at.scrollTop = newestFirst && top > 0 ? top + (at.scrollHeight - tall) : top;
  };
  put($(`[data-xp-progress="${key}"]`), xpProgressPoint(run, tree, idle));
  put($(`[data-xp-version-graph="${key}"]`), xpVersionGraph(run, tree), true);
  put($(`#xp-versions-${key}`), xpVersionTree(run, tree, idle));
  const count = $(`[data-xp-versions-count="${key}"]`);
  if (count) count.textContent = String((tree.versions || []).length);
}

/* What a tree was loaded for: how many versions, the head, and how many
   still have their slides being drawn - drawn behind the work, each added to
   its version when it is ready, and the tree asked for again then. */
function xpVersionsSigOf(tree) {
  const versions = (tree || {}).versions || [];
  const drawing = versions.filter((v) => (v.summary || {}).slides === "drawing").length;
  return `${versions.length}|${(tree || {}).head || ""}|${drawing}`;
}

function xpRunVersionsSig(versions) {
  return `${Number(versions.count)}|${versions.head || ""}|${Number(versions.drawing || 0)}`;
}

/* A version saved while the run goes: its tree asked for again, and drawn
   in place - nothing else. */
async function xpVersionsRefresh(run) {
  const kept = xpVersionsState();
  const versions = run.versions || {};
  if (!versions.count) return;
  if (kept.treeSig[run.id] === xpRunVersionsSig(versions)) return;
  if (kept.treeLoading && kept.treeLoading[run.id]) return;
  kept.treeLoading = kept.treeLoading || {};
  kept.treeLoading[run.id] = true;
  try {
    await xpLoadVersions(run.id);
  } finally {
    kept.treeLoading[run.id] = false;
  }
}

/* Before a panel is drawn whole: each run's tree - asked for only when a
   version was saved since - and the version each run is shown at, so the
   run is drawn as it is shown, not drawn and then changed. A version picked
   that is gone (its way cleared) is let go: the latest is shown. */
async function xpVersionsReady(runs) {
  const kept = xpVersionsState();
  await Promise.all(runs.map(async (run) => {
    const versions = run.versions || {};
    if (!versions.count) return;
    const sig = xpRunVersionsSig(versions);
    if (!kept.trees[run.id] || kept.treeSig[run.id] !== sig) {
      try {
        const tree = await api.get(`/api/work/versions?run=${encodeURIComponent(run.id)}`);
        kept.trees[run.id] = tree;
        kept.treeSig[run.id] = (tree.versions || []).length ? xpVersionsSigOf(tree) : sig;
      } catch (err) { /* drawn without it; asked again next time */ }
    }
    const picked = xpVersionPicked(run.id);
    const tree = kept.trees[run.id] || {};
    if (picked && (tree.versions || []).length && !tree.versions.some((v) => v.id === picked)) {
      xpVersionPick(run.id, "");
      return;
    }
    const view = kept.views[run.id];
    const listed = (tree.versions || []).find((v) => v.id === picked);
    if (picked && !(view && view.picked === picked)) {
      await xpVersionLoad(run.id, picked);
    } else if (picked && view && (view.slides || {}).status === "drawing"
        && listed && (listed.summary || {}).slides !== "drawing") {
      await xpVersionLoad(run.id, picked);
    }
  }));
}

/* One version, asked for: kept as the one the run is shown at. */
async function xpVersionLoad(runId, versionId) {
  const kept = xpVersionsState();
  try {
    const got = await api.get(`/api/work/version?run=${encodeURIComponent(runId)
      }&id=${encodeURIComponent(versionId)}`);
    kept.views[runId] = { ...got, id: got.id || versionId, picked: versionId };
    return true;
  } catch (err) {
    toast(err.message);
    return false;
  }
}

/* The versions as a list, a line per version: a line of work goes straight
   down; a branch - continued from an older version - is drawn indented
   under the version it began from, so both lines stay in view. The head is
   marked: Continue goes on from it unless another is picked. View shows the
   whole run at that version, as a click on it in the tree does; Continue
   from here picks it, and asks what to change under the tree. */
function xpVersionTree(run, tree, idle) {
  const all = tree.versions || [];
  if (!all.length) return `<p class="muted">No versions yet.</p>`;
  const after = {};
  all.forEach((v) => { (after[v.parent || ""] = after[v.parent || ""] || []).push(v); });
  const rows = [];
  const walk = (v, depth) => {
    rows.push([v, depth]);
    const next = after[v.id] || [];
    next.filter((c) => c.branch !== v.branch).forEach((c) => walk(c, depth + 1));
    next.filter((c) => c.branch === v.branch).forEach((c) => walk(c, depth));
  };
  (after[""] || []).forEach((v) => walk(v, 0));
  const going = run.alive || tree.alive;
  return `<ol class="xp-version-tree">${rows.map(([v, depth]) => {
    const s = v.summary || {};
    const head = v.id === tree.head;
    // From the head is the ordinary Continue; from any other version it
    // rolls back - for a finished run too. Not while a run is going.
    const canFrom = idle && !going && (!head || run.continuable || run.extendable);
    return `<li class="xp-version${head ? " xp-version-head" : ""}" data-xp-version-row="${
      escapeHtml(v.id)}" style="margin-left:${depth * 1.4}em">
      ${depth ? `<span class="xp-version-branch" aria-hidden="true">↳</span>` : ""}
      <strong>${escapeHtml(v.id)}</strong>
      <span class="xp-version-kind">${escapeHtml(XP_VERSION_KIND[v.kind] || v.kind || "")}</span>
      ${escapeHtml(xpVersionMessage(v).title)}
      <span class="muted">· ${escapeHtml(localStamp(v.at))}
        · ${escapeHtml(v.branch || "main")} · ${Number(s.rounds || 0)} round${
        s.rounds === 1 ? "" : "s"}${s.cards === null ? "" : ` · ${Number(s.cards_done || 0)}/${
        Number(s.cards || 0)} cards done`}${s.todo ? ` · ${Number(s.todo)} to do` : ""}${s.deck ? " · deck" : ""}
        · ${Number(v.files || 0)} files${s.tokens_in !== undefined
          ? ` · ${escapeHtml(xpTokenSplit(s))} so far` : ""}${s.slides === "made" ? " · slides"
          : s.slides === "drawing" ? " · slides being drawn…"
          : s.slides === "not made" ? " · slides not made" : ""}</span>
      ${head ? `<span class="xp-version-here">head - Continue goes on from here</span>` : ""}
      <button type="button" class="small secondary" data-xp-version-view="${escapeHtml(v.id)}"
        data-xp-version-run="${escapeHtml(run.id)}">View</button>
      ${canFrom ? `<button type="button" class="small" data-xp-version-from="${escapeHtml(v.id)}"
        data-xp-version-run="${escapeHtml(run.id)}">Continue from here</button>` : ""}
      ${xpAmendedNote(v.amended)}
    </li>`;
  }).join("")}</ol>`;
}

/* ONE VERSION, opened: ITS SLIDES - where the whole work stood at it, as the
   work agent showed it when the version was saved - drawn by the run deck's
   own renderer, with ← and → (or the buttons) to go through them. A version
   saved before versions had slides, or one whose slides could not be made,
   says so, and where it stood in a line. Its files, folded; and the run's
   results deck as it was then, when there was one. */
function xpVersionView(run, v) {
  const size = (n) => (Number(n) >= 1024 ? `${Math.round(Number(n) / 1024)} KB` : `${Number(n)} B`);
  const s = v.summary || {};
  const slides = v.slides || {};
  const brief = [`${Number(s.rounds || (v.rounds || []).length || 0)} round${
    Number(s.rounds) === 1 ? "" : "s"}`, `${Number(s.cards_done || 0)}/${Number(s.cards || 0)} cards done`,
    s.todo ? `${Number(s.todo)} to do` : "", `${(v.files || []).length} files`,
    s.tokens_in !== undefined ? `${xpTokenSplit(s)} so far` : "",
    v.goal ? `goal: ${v.goal}` : "",
    ((v.todo || {}).next || []).length ? `to do then: ${v.todo.next.join("; ")}` : ""]
    .filter(Boolean).join(" · ");
  return `<div class="xp-version-view">
    <h4>Version ${escapeHtml(v.id || "")} - ${escapeHtml(v.label || "")}${
      v.head ? ` <span class="xp-version-here">head</span>` : ""}</h4>
    <p class="muted">${escapeHtml(XP_VERSION_KIND[v.kind] || v.kind || "")} · ${
      escapeHtml(localStamp(v.at))} · ${
      escapeHtml(v.branch || "main")}${v.parent ? ` · after ${escapeHtml(v.parent)}` : ""}</p>
    ${slides.status === "made" && slides.page ? `<p class="muted xp-version-slides-note">${
      Number(slides.count || 0)} slides - where the whole work stood at ${escapeHtml(v.id || "")}${
      slides.fallback ? " (in words: the figures could not be made)" : ""};
      click into them, then ← and → to go through them, F or ⛶ for full screen</p>
      <iframe class="xp-deck-frame xp-version-slides${String(slides.page).includes('class="deck with-notes"')
        ? " xp-slides-with-notes" : ""}" allow="fullscreen" allowfullscreen
        title="The slides of version ${escapeHtml(v.id || "")}" data-xp-version-slides="${
        escapeHtml(v.id || "")}"></iframe>`
      : slides.status === "drawing" ? `<p class="xp-version-noslides"><strong>The slides of
        this version are being drawn</strong> <span class="muted">- behind the work, which
        went on without waiting for them; they appear here when they are ready</span></p>
      <p class="muted">${escapeHtml(brief)}</p>`
      : `<p class="xp-version-noslides"><strong>${slides.status === "not made"
        ? "The slides of this version were not made"
        : slides.status === "skipped" ? "No slides for the contract's version"
        : "No update slides for this version"}</strong>
        <span class="muted">${slides.status === "not made"
          ? `- ${escapeHtml(slides.why || "the model could not be asked when it was saved")}`
          : slides.status === "skipped" ? "- there is no work to show yet"
          : "- it was saved before versions had them"}</span></p>
      <p class="muted">${escapeHtml(brief)}</p>`}
    ${v.contract ? `<details class="xp-version-contract"><summary class="muted">Its contract
      - ${v.head ? "in force" : "not in force"}</summary>${xpContractBlock(v.contract,
      `<h4 class="xp-contract-title${v.head ? "" : " muted"}">Contract at ${escapeHtml(v.id || "")
      } - ${v.head ? "in force" : "not in force"}</h4>`, v.amended, `${run.id}@${v.id}`, !v.head)}
    </details>` : ""}
    <details class="xp-version-files-box"><summary class="muted">Files it holds (${
      (v.files || []).length + (v.granted || []).length})</summary>
    <ul class="xp-work-list xp-version-files">${(v.files || []).map((f) => `<li><code>${
      escapeHtml(f.path)}</code> <span class="muted">${size(f.size)}</span></li>`).join("")}${
      (v.granted || []).map((f) => `<li><code>${escapeHtml(f.path)}</code> <span
      class="muted">written by the agent in your folders</span></li>`).join("")}</ul></details>
    ${v.deck ? `<p><button type="button" class="small secondary" data-xp-version-deck="${
      escapeHtml(run.id)}" data-xp-version-id="${escapeHtml(v.id)}">Show the results deck
      as it was then</button></p>
      <div class="xp-deck" id="xp-version-deck-${escapeHtml(run.id)}" hidden></div>` : ""}
  </div>`;
}

/* MAKING THE USER'S FILES READABLE TO THE AGENTS' CODE - a one-time grant,
   in the background: while it goes, a line under the folders says how far
   it has got; one that failed says why, briefly; when all are done, nothing.
   Asked again every few seconds only while the Experience tab is seen and
   it is going; the line is changed in place - nothing else is drawn. */
const XP_READING_EVERY = 2000;
function xpReadingText() {
  const roots = experienceState.reading || [];
  const going = roots.filter((one) => one.state === "running");
  const failed = roots.filter((one) => one.state === "failed");
  if (going.length) {
    const now = going[0];
    return `Making your files readable to the agents' code: ${Number(now.done || 0)}/${
      Number(now.total || 0)} - now: ${now.root || ""} (one-time, in the background; until it
      finishes, the code can read only the work's own folders - the agents still read anything
      with read_file)`.replace(/\s+/g, " ");
  }
  if (failed.length) {
    return `Making your files readable to the agents' code failed for ${failed.map((one) =>
      `${one.root || ""}: ${String(one.error || "unknown error").slice(0, 160)}`).join("; ")}`;
  }
  return "";
}

function xpReadingDraw() {
  const line = $("#xp-reading");
  if (!line) return;
  const text = xpReadingText();
  if (line.textContent !== text) line.textContent = text;
  line.hidden = !text;
}

async function xpReadingFollow() {
  if (experienceState.readingFollowing) return;
  experienceState.readingFollowing = true;
  try {
    for (;;) {
      if (!document.hidden && activeTab === "experience") {
        try {
          experienceState.reading = (await api.get("/api/work/reading")).roots || [];
        } catch (err) { /* asked again next time */ }
        xpReadingDraw();
        if (!(experienceState.reading || []).some((one) => one.state === "running")) break;
      }
      await new Promise((resolve) => setTimeout(resolve, XP_READING_EVERY));
    }
  } finally {
    experienceState.readingFollowing = false;
  }
}

/* A version's slides, put in their frame: the page the deck's renderer made,
   as it is - its own look, its own buttons and keys. */
/* SLIDES AS TALL AS THE SLIDE: each deck in a frame says how tall it must be
   for its slide to fill the frame's width, and the frame is made exactly
   that tall - nothing above or below the slide to scroll past - but never
   taller than the window, so the whole slide is always in view. A deck with
   notes has them under the slide, whole: as tall as slide and notes, the
   page scrolling past them as a page does - never the frame. */
window.addEventListener("message", (event) => {
  const wanted = Number((event.data || {}).deckHeight);
  if (!wanted || !(wanted > 0)) return;
  const frame = [...document.querySelectorAll("iframe.xp-deck-frame")]
    .find((one) => one.contentWindow === event.source);
  if (!frame) return;
  frame.dataset.deckHeight = String(wanted);
  frame.dataset.notesBelow = (event.data || {}).notesBelow ? "1" : "";
  xpDeckFrameFit(frame);
});
window.addEventListener("resize", () => {
  document.querySelectorAll("iframe.xp-deck-frame[data-deck-height]").forEach(xpDeckFrameFit);
});

function xpDeckFrameFit(frame) {
  const wanted = Number(frame.dataset.deckHeight);
  if (!wanted) return;
  const border = frame.offsetHeight - frame.clientHeight;
  const most = frame.dataset.notesBelow ? Infinity : window.innerHeight - 16;
  const height = Math.max(160, Math.min(wanted + border, most));
  frame.style.maxHeight = "none";
  frame.style.minHeight = "0";
  frame.style.aspectRatio = "auto";
  frame.style.height = `${Math.round(height)}px`;
}

function xpVersionSlides(scope, v) {
  const frame = scope && scope.querySelector("[data-xp-version-slides]");
  if (frame && v && v.slides && v.slides.page) frame.srcdoc = v.slides.page;
}

async function xpLoadVersions(runId) {
  const kept = xpVersionsState();
  try {
    kept.trees[runId] = await api.get(`/api/work/versions?run=${encodeURIComponent(runId)}`);
    kept.treeSig[runId] = xpVersionsSigOf(kept.trees[runId]);
  } catch (err) {
    toast(err.message);
    return;
  }
  xpVersionsPut(runId);
}

/* NEVER MOVE THE USER'S VIEW. A panel drawn again whole - a run started or
   ended, a version picked, a button pressed - is put back exactly as it was
   seen: the window where it was scrolled, with what was at the top of the
   window still there; every box that scrolls - the live session, a line's
   "all of it", the report, the contract, the versions, the table of calls -
   where it was scrolled, a live session at its bottom kept at its bottom;
   every fold open or closed as it was; the text selected still selected.

   Each box is found again by A KEY OF ITS OWN, not by where it is in the
   page: the nearest data-xp-keep or id above it, then the way down from
   there - each step named by what it is (its data-x* name, else its tag and
   classes). A run that appeared above it does not give it another's place.
   Only two alike at one place are told apart by their order.

   The panels' parts that fold by themselves - a run's live session, its
   chart and table, its versions' list, a deliverable - keep their own state
   (xpLiveState, xpCallsState, xpVersionsState); every other fold is put
   back as it was. */
const XP_STICKY = ".xp-live-scroll, .xp-log";
const XP_OWN_FOLD = "[data-xp-live], [data-xp-calls], [data-xp-calls-table], .xp-versions, "
  + ".xp-deliverable";

function xpNamedAttr(el) {
  for (const a of el.attributes) {
    if (a.value && a.name !== "data-xp-keep" && /^data-x[pd]-/.test(a.name)) {
      return `[${a.name}=${a.value}]`;
    }
  }
  return "";
}

/* Every element under `scope`, with its key - parents before children. */
function xpWalkKeys(scope, visit) {
  const counts = new Map();
  const walk = (el, base) => {
    for (const child of el.children) {
      if (child.namespaceURI !== "http://www.w3.org/1999/xhtml") continue;
      const keep = child.getAttribute("data-xp-keep");
      let key = keep ? `[${keep}]` : child.id ? `#${child.id}` : `${base}>${child.tagName}${
        xpNamedAttr(child) || `.${(child.getAttribute("class") || "").trim().split(/\s+/).join(".")}`}`;
      const n = (counts.get(key) || 0) + 1;
      counts.set(key, n);
      if (n > 1) key = `${key}~${n}`;
      visit(child, key);
      walk(child, key);
    }
  };
  walk(scope, "");
}

/* Where a point of a selection is: the element's key, and how many
   characters into its text. */
function xpTextOffset(el, node, offset) {
  if (node.nodeType !== Node.TEXT_NODE) {
    const before = Array.from(node.childNodes).slice(0, offset);
    return before.reduce((sum, one) => sum + (one.textContent || "").length, 0)
      + (node === el ? 0 : xpTextOffset(el, node, 0));
  }
  let count = 0;
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  for (let at = walker.nextNode(); at; at = walker.nextNode()) {
    if (at === node) return count + offset;
    count += at.textContent.length;
  }
  return count;
}

function xpTextAt(el, chars) {
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  let left = chars;
  let last = null;
  for (let at = walker.nextNode(); at; at = walker.nextNode()) {
    if (left <= at.textContent.length) return { node: at, offset: left };
    left -= at.textContent.length;
    last = at;
  }
  return last ? { node: last, offset: last.textContent.length } : null;
}

function xpViewKeep(scope) {
  if (!scope) return null;
  const snap = { x: window.scrollX, y: window.scrollY, boxes: {}, open: {}, frames: {},
                 anchor: null, sel: null };
  // What is selected, if it is in here: its two ends, found again by key.
  const sel = window.getSelection ? window.getSelection() : null;
  let range = null;
  if (sel && sel.rangeCount && !sel.isCollapsed) {
    const r = sel.getRangeAt(0);
    if (scope.contains(r.commonAncestorContainer)) range = r;
  }
  const elOf = (node) => (node.nodeType === Node.TEXT_NODE ? node.parentElement : node);
  const startEl = range ? elOf(range.startContainer) : null;
  const endEl = range ? elOf(range.endContainer) : null;
  if (range) snap.sel = {};
  const top = 56;      // under the page's own sticky header
  let best = null;
  xpWalkKeys(scope, (el, key) => {
    if (el.scrollTop > 0 || el.scrollLeft > 0 || el.matches(XP_STICKY)) {
      snap.boxes[key] = { top: el.scrollTop, left: el.scrollLeft,
                          bottom: el.scrollHeight - el.scrollTop - el.clientHeight < 24 };
    }
    if (el.tagName === "DETAILS" && !el.matches(XP_OWN_FOLD)) snap.open[key] = el.open;
    if (el.tagName === "IFRAME") {
      try {
        const y = el.contentWindow ? el.contentWindow.scrollY : 0;
        if (y) snap.frames[key] = y;
      } catch (err) { /* another origin's page: left as it loads */ }
    }
    // What is at the top of the window: the keyed box starting nearest it.
    if (el.hasAttribute("data-xp-keep")) {
      const r = el.getBoundingClientRect();
      if (r.height && r.bottom > top && r.top < window.innerHeight
          && (!best || Math.abs(r.top - top) < Math.abs(best.top - top))) {
        best = { key, top: r.top };
      }
    }
    if (range && el === startEl) {
      snap.sel.start = { key, at: xpTextOffset(el, range.startContainer, range.startOffset) };
    }
    if (range && el === endEl) {
      snap.sel.end = { key, at: xpTextOffset(el, range.endContainer, range.endOffset) };
    }
  });
  snap.anchor = best;
  // WHAT IS BEING TYPED IN STAYS WHERE IT IS ON THE SCREEN: while the user
  // types, it - not the box nearest the top - is what is held in place.
  // Holding the other one moved the field they were typing in up the page
  // whenever what lay between the two changed.
  const active = document.activeElement;
  if (active && scope.contains(active) && XP_EDITABLE.test(active.tagName)) {
    snap.typing = { el: active, id: active.id || "", top: active.getBoundingClientRect().top };
  }
  return snap;
}

/* Put back. `late`: a second pass once what is drawn later has come - only
   the boxes not yet back where they were. */
function xpViewPut(scope, snap, late = false) {
  if (!scope || !snap) return;
  let anchor = null;
  const ends = {};
  xpWalkKeys(scope, (el, key) => {
    if (!late && key in snap.open && el.tagName === "DETAILS" && el.open !== snap.open[key]) {
      el.open = snap.open[key];
    }
    const box = snap.boxes[key];
    if (box && !box.done) {
      if (box.bottom && el.matches(XP_STICKY)) {
        el.scrollTop = el.scrollHeight;
        box.done = el.scrollHeight > el.clientHeight || !box.top;
      } else {
        el.scrollTop = box.top;
        el.scrollLeft = box.left;
        box.done = Math.abs(el.scrollTop - box.top) < 2 && Math.abs(el.scrollLeft - box.left) < 2;
      }
    }
    if (!late && el.tagName === "IFRAME" && snap.frames[key]) {
      const y = snap.frames[key];
      el.addEventListener("load", () => {
        try { el.contentWindow.scrollTo(0, y); } catch (err) { /* left as it loads */ }
      }, { once: true });
    }
    if (snap.anchor && key === snap.anchor.key) anchor = el;
    if (snap.sel && snap.sel.start && key === snap.sel.start.key) ends.start = el;
    if (snap.sel && snap.sel.end && key === snap.sel.end.key) ends.end = el;
  });
  if (late) return;
  window.scrollTo(snap.x, snap.y);
  const typing = snap.typing && (snap.typing.el.isConnected ? snap.typing.el
    : (snap.typing.id ? document.getElementById(snap.typing.id) : null));
  if (typing) {
    const moved = typing.getBoundingClientRect().top - snap.typing.top;
    if (Math.abs(moved) >= 1) window.scrollBy(0, moved);
    anchor = null;
  }
  if (anchor) {
    const moved = anchor.getBoundingClientRect().top - snap.anchor.top;
    if (Math.abs(moved) >= 1) window.scrollBy(0, moved);
  }
  if (ends.start && ends.end) {
    const a = xpTextAt(ends.start, snap.sel.start.at);
    const b = xpTextAt(ends.end, snap.sel.end.at);
    const active = document.activeElement;
    if (a && b && !(active && XP_EDITABLE.test(active.tagName))) {
      try {
        const range = document.createRange();
        range.setStart(a.node, a.offset);
        range.setEnd(b.node, b.offset);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      } catch (err) { /* the text changed under it: nothing selected */ }
    }
  }
}

/* The live sessions drawn so far, kept and moved into the panel drawn
   again: their lines stay as they are (where each is scrolled to is put
   back with the rest of the view - an element taken out and put back
   forgets its scroll). */
function xpLiveKeep(scope) {
  const kept = {};
  $$("[data-xp-live-body]", scope).forEach((node) => { kept[node.dataset.xpLiveBody] = node; });
  return kept;
}

function xpLivePut(scope, kept) {
  $$("[data-xp-live-body]", scope).forEach((slot) => {
    const old = kept[slot.dataset.xpLiveBody];
    if (old && old !== slot) slot.replaceWith(old);
  });
}

/* ONLY WHAT IS LIVE CHANGES. A panel of runs is drawn whole only when
   something about it changed in kind - a run started or ended, its state
   or its part of the work changed, what can be done with it, its lists -
   which the panel's signature says (xpRunSig, and the panel's own parts).
   Asked again while a run goes, with nothing of that changed, each run is
   changed in place (xpRunPatch) and nothing else is touched. */
function xpPanelSame(scope, sig) {
  return Boolean(scope && scope._xpSig === sig && scope.childElementCount);
}

/* THE WORK PANEL, asked for again: changed in place when only what is live
   changed; drawn whole only when something changed in kind - and NEVER
   UNDER THE USER'S TYPING: while a field in it has the focus - the words
   for Continue, the instruction, a limit, a choice - it is not replaced
   (the live parts still follow the run), and it is drawn once the field is
   left, with what was typed kept (kept.words, the drafts). `force`: drawn
   whole now, whatever has the focus - the focus, the caret and the
   selection put back where they were. Drawn whole, the view is put back as
   it was (xpViewKeep / xpViewPut). */
/* THE RUN GOING ON THIS PROJECT, BESIDE ITS NAME: where it stands (with
   the spinner while it works), Pause or Resume, and Stop - or, wrapping
   up, Stop now. Changed in place, as the runs are asked for again and as
   its live session moves; nothing when no run is going. */
function xpDrawTitleRun(going) {
  const box = $("#xp-title-run");
  if (!box) return;
  experienceState.titleGoing = going || null;
  let html = "";
  if (going) {
    const live = xpLiveState(going.id);
    // AS IT IS THIS MOMENT (the user, 2026-10-27: resumed from the to-do, and
    // Work still showed Resume): the runs going, asked every few seconds
    // whichever tab is shown (watchWorkGoing), before what this panel last
    // loaded.
    const now = (workGoing.byUnit || {})[going.unit_id];
    const fresh = now && now.run === going.id ? now : null;
    const data = fresh ? { state: fresh.state, progress: { pause_asked: fresh.pause_asked,
                                                          stopping: fresh.stopping } }
      : live.open ? live.data : null;
    const p = (data || {}).progress || {};
    let state = data && data.state ? data.state
      : going.status === "waiting for you" ? "waiting_for_you"
        : going.paused ? "paused" : "going";
    if (p.pause_asked && state === "going") state = "pausing";
    const id = escapeHtml(going.id);
    const stopping = fresh ? Boolean(fresh.stopping) : going.stopping || p.stopping;
    html = `<span class="xp-live-state xp-live-state-${escapeHtml(state)}">${
        escapeHtml(XP_LIVE_STATE[state] || state)}</span>${state === "going"
        ? `<span class="xp-live-spin xd-way-spin" aria-hidden="true"></span>` : ""}
      ${xpPauseButton(fresh ? Object.assign({}, going, { paused: state === "paused" })
        : going, data)}
      ${stopping
        ? `<span class="muted">wrapping up…</span> <button type="button"
            class="small secondary danger" data-xp-stop-now="${id}"
            title="Stop at once - no slides, no to-do list">Stop now</button>`
        : `<button type="button" class="small secondary" data-xp-stop="${id}"
            title="It wraps up: slides of what exists, and a to-do list">Stop</button>`}`;
  }
  if (box._xpHtml !== xpShows(html)) {
    box.innerHTML = html;
    box._xpHtml = xpShows(html);
  }
}

async function xpLoadRuns(force = false) {
  const unit = experienceState.unit;
  const panel = $("#xp-work");
  if (!unit) { panel.innerHTML = ""; panel._xpSig = ""; xpDrawTitleRun(null); return; }
  let runs = [];
  let folders = { folders: [], warning: "" };
  let limits = { defaults: {} };
  try {
    [runs, folders, limits] = await Promise.all([
      api.get(`/api/work/runs?unit=${encodeURIComponent(unit)}`).then((r) => r.runs),
      api.get(`/api/work/folders?unit=${encodeURIComponent(unit)}`),
      experienceState.limits ? Promise.resolve(experienceState.limits)
        : api.get("/api/work/limits")]);
    experienceState.limits = limits;
  } catch (err) { /* the panel goes on without them */ }
  runs = runs || [];
  try {
    experienceState.workTree = await api.get(`/api/work/tree?unit=${encodeURIComponent(unit)}`);
  } catch (err) { experienceState.workTree = null; }
  // Another piece of work chosen while this one was asked for: its own
  // drawing wins.
  if (unit !== experienceState.unit) return;
  const going = runs.find((run) => run.alive);
  xpDrawTitleRun(going);
  const kept = xpVersionsState();
  kept.going = Boolean(going);
  kept.idle = kept.idle || {};
  runs.forEach((run) => { kept.runs[run.id] = run; kept.idle[run.id] = !going; });
  const unitRow = (experienceState.units || []).find((u) => u.id === unit) || {};
  const fresh = !unitRow.stages && !((experienceState.workTree || {}).stages || []).length;
  const tree = experienceState.workTree || {};
  const sigOf = () => JSON.stringify([unit, fresh, Boolean((tree.cards || []).length),
    folders.folders || [], folders.warning || "", folders.isolation || "",
    experienceState.revokeAsk || "", (limits || {}).defaults || {}, runs.map(xpRunSig)]);
  if (!force && xpPanelSame(panel, sigOf())) {
    // Only what is live: each run in place, and the agents' tree.
    runs.forEach(xpRunPatch);
    const treeBox = $("#xp-work-tree");
    if (treeBox && (tree.cards || []).length) {
      const html = xpGraphSvg(tree, "work");
      if (treeBox._xpHtml !== xpShows(html)) {
        const frame = treeBox.querySelector(".xp-frame");
        const at = frame ? [frame.scrollLeft, frame.scrollTop] : [0, 0];
        treeBox.innerHTML = html;
        treeBox._xpHtml = xpShows(html);
        const again = treeBox.querySelector(".xp-frame");
        if (again) [again.scrollLeft, again.scrollTop] = at;
      }
    }
    xpRunsTimer(going);
    return;
  }
  if (!force && xpEditing("#xp-work")) {
    xpDefer("#xp-work", () => xpLoadRuns());
    xpRunsTimer(going);
    return;
  }
  await xpVersionsReady(runs);
  if (unit !== experienceState.unit) return;
  const draft = ($("#xp-instruction") || {}).value || "";
  // THE WORK'S SETTINGS ARE KEPT (the user, 2026-10-27): for the next start,
  // what its latest run last ran with - else Auto and the defaults - unless
  // changed here, kept as it is redrawn.
  const last = runs.length ? xpRecordSpec(runs[0]) : null;
  // What is typed in the form is kept only while it is this work's form.
  const mine = panel.dataset.formUnit === String(unit);
  const inForm = (selector) => (mine ? $(selector) : null);
  const packagesMode = (inForm('input[name="xp-packages"]:checked') || {}).value
    || (last && last.packages_chosen ? last.packages : "auto");
  // A sound when the run ends: as ticked, kept as it is redrawn - at first,
  // as the latest run last ran.
  const soundBox = inForm("#xp-sound");
  if (soundBox) experienceState.startSound = soundBox.checked;
  else experienceState.startSound = last ? last.sound : false;
  const asked = (name) => {
    const typed = (inForm(`#xp-limit-${name}`) || {}).value;
    if (typed !== undefined && typed !== "") return typed;
    if (last && (last.limits || {})[name] !== undefined) return last.limits[name];
    return (limits.defaults || {})[name] ?? "";
  };
  // What was being typed in, if it is drawn anyway: found again after, by
  // what it is, and given back its caret and selection.
  const was = document.activeElement;
  const typed = was && panel.contains(was) && XP_EDITABLE.test(was.tagName) ? {
    key: was.id ? `#${CSS.escape(was.id)}` : Array.from(was.attributes)
      .filter((a) => a.name.startsWith("data-xp-")).map((a) =>
        `[${a.name}="${CSS.escape(a.value)}"]`).join(""),
    start: was.selectionStart, end: was.selectionEnd, top: was.scrollTop } : null;
  if (!force && xpEditing("#xp-work")) {
    // Something was focused while the panel was being asked for.
    xpDefer("#xp-work", () => xpLoadRuns());
    return;
  }
  const view = xpViewKeep(panel);
  const lives = xpLiveKeep(panel);
  panel.innerHTML = `<h3>Let the agents work on this</h3>
    <p class="muted">A work agent drafts a contract - the goal, the scope, the
      deliverables - and a reviewer writes what each deliverable must meet, from
      how you have judged work like it, and approves it. Then the work agent works
      in rounds, each claim with its evidence, and the reviewer checks every round,
      reviews the whole at the end, and the results are shown as slides. At a
      limit the run pauses with what it has and a to-do list, to continue later.
      They write only in this work's own folder under agent_work in your
      workspace, and in the folders you add below. Python packages they need come
      from PyPI into the run's own folder - pip runs under the same guard, able to
      reach PyPI and nothing else. Everything they do is recorded as theirs.</p>
    <div class="xp-folders"><strong>Folders they may change:</strong>
      ${(folders.folders || []).length ? `<ul class="xp-folder-list">${folders.folders.map((f) =>
        experienceState.revokeAsk === f ? `<li class="xp-folder xp-folder-asking"><code title="${
          escapeHtml(f)}">${escapeHtml(f)}</code><span class="xp-folder-ask">The agents may no
          longer change it? <button type="button" class="small danger" data-xp-revoke-yes="${
          escapeHtml(f)}">Take it out</button> <button type="button" class="small secondary"
          data-xp-revoke-no="1">Keep it</button></span></li>`
        : `<li class="xp-folder"><code title="${escapeHtml(f)}">${escapeHtml(f)}</code>
          <button type="button" class="xp-folder-x" data-xp-revoke="${escapeHtml(f)}"
          title="Take this folder out" aria-label="Take ${escapeHtml(f)} out">×</button></li>`)
        .join("")}</ul>`
        : ` <span class="muted">none besides its own</span>`}
      <button type="button" class="small secondary" id="xp-grant">Add a folder…</button>
      <p class="muted xp-warning">${escapeHtml(folders.warning || "")}</p>
      <p class="muted xp-reading" id="xp-reading"${xpReadingText() ? "" : " hidden"}>${
        escapeHtml(xpReadingText())}</p></div>
    <div class="xp-limits"><strong>Limits:</strong>
      <label>minutes <input type="number" id="xp-limit-minutes"
        value="${escapeHtml(String(asked("minutes")))}"></label>
      <label title="${escapeHtml(XP_INPUT_TOKENS_ABOUT)}">input tokens
        <input type="number" id="xp-limit-tokens_in" step="100000"
        value="${escapeHtml(String(asked("tokens_in")))}"></label>
      <label title="What the models wrote">output tokens
        <input type="number" id="xp-limit-tokens_out" step="10000"
        value="${escapeHtml(String(asked("tokens_out")))}"></label>
      <label>model calls <input type="number" id="xp-limit-calls"
        value="${escapeHtml(String(asked("calls")))}"></label>
      <span class="muted">0 or less: no limit</span></div>
    <div class="xp-packages-mode"><strong>Python packages:</strong>
      <label><input type="radio" name="xp-packages" value="ask"${
        packagesMode !== "auto" ? " checked" : ""}> Ask me before installing packages</label>
      <label><input type="radio" name="xp-packages" value="auto"${
        packagesMode === "auto" ? " checked" : ""}> Auto</label>
      <span class="muted">from PyPI only, wheels only, into the run's own folder</span>
      ${String(folders.isolation || "").startsWith("not OS-isolated")
        ? `<p class="xp-warning">${escapeHtml(folders.isolation)} - Auto is not
          available: every install is asked</p>` : ""}</div>
    <div class="xp-unconfined-mode">${xpUnconfinedBox(`id="xp-unconfined"${
      (inForm("#xp-unconfined") ? inForm("#xp-unconfined").checked : last && !last.sandbox)
        ? " checked" : ""}`)}</div>
    ${going ? `<p class="muted xp-settings-later">${escapeHtml(XP_SETTINGS_NEXT)}</p>` : ""}
    <textarea id="xp-instruction" rows="2"
      placeholder="${fresh ? "what you want done - needed: this is new work"
        : "what you want done this time (optional)"}">${escapeHtml(draft)}</textarea>
    ${going
      ? `<span class="muted">A run is going - Pause and Stop are beside the project's
          name, above.</span>`
      : `<button type="button" class="small" id="xp-start">Start working on this</button>
        ${xpSoundBox('id="xp-sound"', experienceState.startSound)}`}
    ${(tree.cards || []).length ? `<h3>The agents' work on it</h3>
      <div id="xp-work-tree">${xpGraphSvg(tree, "work")}</div>
      <div id="xp-work-stage"></div>` : ""}
    ${runs.map((run, i) => xpRun(run, !going, i === 0)).join("")}`;
  // What it was drawn for - with each run's versions as they are now loaded.
  panel._xpSig = sigOf();
  panel.dataset.formUnit = String(unit);
  const treeBox = $("#xp-work-tree");
  if (treeBox) treeBox._xpHtml = xpShows(xpGraphSvg(tree, "work"));
  // How far making the files readable has got: looked at, and followed
  // while it goes.
  xpReadingFollow();
  // A version shown has its slides put back in their frame.
  runs.forEach((run) => {
    if (kept.views[run.id]) {
      xpVersionSlides($(`#xp-version-view-${CSS.escape(run.id)}`), kept.views[run.id]);
    }
  });
  // Each open live session: its kept element put back, drawn against the
  // run as it now is, and followed while it can change.
  xpLivePut(panel, lives);
  runs.forEach((run) => {
    if (!xpLiveState(run.id).open) return;
    xpLiveDraw(run.id, null, true);
    xpLiveFollow(run.id);
  });
  // Each run's chart of its tokens, as wide as its place.
  xpCallsDrawAll(panel);
  // What was open in the agents' tree stays open as it is redrawn.
  if (experienceState.workStage) xpShowStage(experienceState.workStage, "work");
  else if (experienceState.workCard) xpShowCard(experienceState.workCard, "work");
  // And the view as it was: the window, every box, every fold, the text
  // selected.
  xpViewPut(panel, view);
  xpRunsTimer(going);
  if (typed && typed.key) {
    const again = $(`#xp-work ${typed.key}`);
    if (again) {
      again.focus({ preventScroll: true });
      try {
        if (typed.start !== null && typed.start !== undefined) {
          again.setSelectionRange(typed.start, typed.end);
        }
      } catch (err) { /* a field with no caret */ }
      again.scrollTop = typed.top;
    }
  }
  // What came a moment later - a frame's page, a box filled - put back too.
  requestAnimationFrame(() => xpViewPut(panel, view, true));
}

/* While a run is going it is looked at again every few seconds - changed in
   place, and drawn whole only when something about it changed in kind. Not
   while another tab is shown: opening this one asks at once. */
function xpRunsTimer(going) {
  clearTimeout(experienceState.runsTimer);
  if (!going) return;
  experienceState.runsTimer = setTimeout(() => {
    if (activeTab === "experience" && !document.hidden) xpLoadRuns();
    // Another tab shown: kept asking, so Work is as it is when it comes back.
    else xpRunsTimer(true);
  }, 5000);
}

// What you write for Continue is kept as you type, so a redraw of the panel
// does not lose it.
$("#experience")?.addEventListener("input", (event) => {
  const box = event.target.closest && event.target.closest("[data-xp-continue-instruction]");
  if (box) xpVersionsState().words[box.dataset.xpContinueInstruction] = box.value;
});

// Whether a sound is played when a run ends - ticked or not, for Start or
// for a run's Continue, wherever the run is drawn - kept as the panel is
// redrawn.
document.addEventListener("change", (event) => {
  const at = event.target;
  if (!at || !at.matches) return;
  if (at.matches("[data-xp-continue-sound]")) {
    xpVersionsState().sound[at.dataset.xpContinueSound] = at.checked;
    $$(`[data-xp-continue-sound="${CSS.escape(at.dataset.xpContinueSound)}"]`)
      .forEach((other) => { other.checked = at.checked; });
  } else if (at.matches("#xp-sound")) {
    experienceState.startSound = at.checked;
  }
});

$("#experience")?.addEventListener("click", async (event) => {
  const folderAt = event.target.closest("[data-xp-folder-unit]");
  if (folderAt) {
    // A project's folder, corrected: it is read again from the beginning.
    event.stopPropagation();
    const unit = folderAt.dataset.xpFolderUnit;
    const now = (experienceState.units.find((u) => u.id === unit) || {}).workspace || "";
    const path = window.prompt("This project's folder (it is read again from the start):", now);
    if (path && path !== now) {
      const said = await api.post("/api/experience/workspaces", { unit, path });
      if (said.error) toast(said.error);
      await loadExperience(false);
    }
    return;
  }
  // REMOVE A PROJECT: asked first, in its row.
  const removeAt = event.target.closest("[data-xp-remove], [data-xp-remove-yes], [data-xp-remove-no]");
  if (removeAt) {
    event.stopPropagation();
    if (removeAt.dataset.xpRemove) {
      experienceState.removing = removeAt.dataset.xpRemove;
    } else if (removeAt.dataset.xpRemoveNo) {
      experienceState.removing = null;
    } else {
      const unit = removeAt.dataset.xpRemoveYes;
      experienceState.removing = null;
      try {
        const said = await api.post("/api/experience/remove", { unit });
        if (said.error) toast(said.error);
        else {
          toast("Removed");
          if (experienceState.unit === unit) experienceState.unit = null;
        }
      } catch (err) {
        toast(err.message);
      }
      await loadExperience(false);
      return;
    }
    xpDrawUnits();
    return;
  }
  const openAt = event.target.closest("[data-xp-open-unit]");
  // THE WHOLE ROW CHOOSES IT - its name, and the rest too: a click on the
  // long description under the name chose nothing, which read as the
  // project refusing to open. Not a control in it, and not text being
  // selected - a drag across the words to copy them is not a choice.
  const rowAt = event.target.closest("#xp-units [data-xp-row]");
  const plainInRow = rowAt
    && !event.target.closest("button, a, input, textarea, select, label, [role=button]")
    && !String(window.getSelection ? window.getSelection() : "").trim();
  const unitAt = event.target.closest("[data-xp-unit]") || (plainInRow ? rowAt : null);
  if (openAt || unitAt) {
    experienceState.unit = openAt ? openAt.dataset.xpOpenUnit
      : (unitAt.dataset.xpUnit || unitAt.dataset.xpRow);
    experienceState.stage = null;
    experienceState.card = null;
    $("#xp-stage").innerHTML = "";
    // Chosen by the user: drawn now - another unit's panel is not deferred.
    await xpOpenUnit(true);
    if (openAt) $("#xp-graph-title").scrollIntoView({ behavior: "smooth" });
    return;
  }
  const stageAt = event.target.closest("[data-xp-stage]");
  if (stageAt) {
    event.preventDefault();
    xpShowStage(stageAt.dataset.xpStage, stageAt.dataset.xpWhere);
    return;
  }
  const natureAt = event.target.closest("[data-xp-nature]");
  if (natureAt) {
    event.preventDefault();
    await xpOpenNature(natureAt.dataset.xpNature, natureAt);
    return;
  }
  const cardAt = event.target.closest("[data-xp-card]");
  if (cardAt) {
    event.preventDefault();
    xpShowCard(cardAt.dataset.xpCard, cardAt.dataset.xpWhere);
    return;
  }
  const citeAt = event.target.closest("[data-xp-cite]");
  if (citeAt) {
    event.preventDefault();
    const card = citeAt.closest(".xp-stage-card") || document;
    const found = card.querySelector(`[data-xp-ref-id="${citeAt.dataset.xpCite}"]`);
    if (found) {
      found.scrollIntoView({ block: "nearest", behavior: "smooth" });
      found.classList.remove("xp-ref-flash");
      void found.offsetWidth;
      found.classList.add("xp-ref-flash");
    }
    return;
  }
  if (event.target.id === "xp-start") {
    // Empty is the default; 0 or less is no limit.
    const limit = (name) => {
      const typed = ($(`#xp-limit-${name}`) || {}).value;
      return typed === undefined || typed === "" ? undefined : Number(typed);
    };
    // EVERY START OF WORK: context collected and a plan to check first - the
    // run goes when the user presses Start on it (openDelegate).
    openDelegate({ unit: experienceState.unit, source: "add",
      instruction: ($("#xp-instruction") || {}).value || "",
      limits: Object.fromEntries(XP_LIMITS.map((name) => [name, limit(name)])),
      packages: (document.querySelector('input[name="xp-packages"]:checked')
        || {}).value || "ask",
      sound: Boolean(($("#xp-sound") || {}).checked),
      ...(($("#xp-unconfined") || {}).checked ? { unconfined: true } : {}) });
    return;
  }
  if (event.target.id === "xp-grant") {
    // A folder the agents may change: chosen in the machine's own folder
    // dialog, which says plainly what granting it means - typed only where
    // there is no dialog.
    const warning = ($(".xp-warning") || {}).textContent || "";
    let path = "";
    try {
      const chosen = await api.post("/api/settings/choose-directory", {
        title: "A folder the agents may change - they can edit and delete "
          + "anything in it. Keep a backup elsewhere." });
      if (chosen.available === false) {
        path = window.prompt(`A folder the agents may change.\n\n${warning}`, "") || "";
      } else {
        path = chosen.selected || "";
      }
    } catch (err) {
      toast(err.message);
    }
    if (path) {
      try {
        const said = await api.post("/api/work/folders", { unit: experienceState.unit, path });
        toast(said.warning || warning);
      } catch (err) {
        toast(err.message);
      }
      await xpLoadRuns(true);
    }
    return;
  }
  const revokeAt = event.target.closest("[data-xp-revoke]");
  const revokeNoAt = event.target.closest("[data-xp-revoke-no]");
  if (revokeAt || revokeNoAt) {
    // Asked in place first: the × turns into the question.
    experienceState.revokeAsk = revokeAt ? revokeAt.dataset.xpRevoke : null;
    await xpLoadRuns(true);
    return;
  }
  const revokeYesAt = event.target.closest("[data-xp-revoke-yes]");
  if (revokeYesAt) {
    experienceState.revokeAsk = null;
    try {
      await api.post("/api/work/folders/remove", { unit: experienceState.unit,
        path: revokeYesAt.dataset.xpRevokeYes });
    } catch (err) {
      toast(err.message);
    }
    await xpLoadRuns(true);
    return;
  }
  await xpRunClick(event, XP_HOST);
});

/* WHAT A RUN'S CONTROLS DO - Stop, Continue, its versions, its live
   session, Pause and Resume, an answer to a request, its slides, its log
   folder - wherever the run is drawn: in the Experience tab, or in the
   Experience debugger's panel, each with its own `host`:
     redraw(force)  draws the panel the run is in again;
     limits(at)     the limits set beside the control at `at` - each one
                    left empty is not sent;
     continueUrl    where Continue is posted (the run's own work's route);
     extra(runId)   what else Continue says.
   True when the click was one of these. */
async function xpRunClick(event, host) {
  const takeOutAt = event.target.closest("[data-xp-take-out]");
  if (takeOutAt) {
    try {
      await api.post("/api/work/contract/take_out", { run: takeOutAt.dataset.xpTakeOutRun,
        added: takeOutAt.dataset.xpTakeOut });
      toast("Taken out");
    } catch (err) {
      toast(err.message);
    }
    await host.redraw(true);
    return true;
  }
  const stopAt = event.target.closest("[data-xp-stop]");
  const stopNowAt = event.target.closest("[data-xp-stop-now]");
  if (stopAt || stopNowAt) {
    await api.post("/api/work/stop", stopAt ? { run: stopAt.dataset.xpStop }
      : { run: stopNowAt.dataset.xpStopNow, now: true });
    await host.redraw(true);
    return true;
  }
  const thoroughAt = event.target.closest("[data-xp-thorough]");
  if (thoroughAt) {
    // A quick run's work carried on the thorough way, from what it made.
    thoroughAt.disabled = true;
    thoroughAt.textContent = "Starting\u2026";
    try {
      await api.post("/api/work/thorough", { run: thoroughAt.dataset.xpThorough,
        limits: host.limits(thoroughAt) });
    } catch (err) {
      toast(err.message);
    }
    await host.redraw(true);
    return true;
  }
  const continueAt = event.target.closest("[data-xp-continue]");
  if (continueAt) {
    const runId = continueAt.dataset.xpContinue;
    const kept = xpVersionsState();
    // From the version picked, if one was: an older one rolls back first.
    const from = kept.from[runId] || "";
    // What to change from here, if you said: the contract is amended for
    // the line it goes on, before any more work.
    const box = $(`[data-xp-continue-instruction="${CSS.escape(runId)}"]`);
    const words = String((box ? box.value : kept.words[runId]) || "").trim();
    // A finished run, from where it finished: only with the next thing to do.
    const head = ((kept.trees || {})[runId] || {}).head;
    const needsWords = continueAt.dataset.xpContinueNeedsWords
      || (from && from === head && (kept.runs[runId] || {}).extendable);
    if (needsWords && !words) {
      toast("Say what to do next, building on the finished work.");
      if (box) box.focus({ preventScroll: true });
      return true;
    }
    // SAID AT ONCE: a run takes some seconds to be set going - its folder
    // put back, its sandbox made - and a button that did nothing meanwhile
    // read as one that had not been pressed.
    continueAt.disabled = true;
    continueAt.textContent = /resume/i.test(continueAt.textContent)
      ? "Resuming\u2026" : "Starting\u2026";
    try {
      // Packages asked about as the run did before, unless changed beside it.
      const asking = $(`[data-xp-continue-packages="${runId}"]`);
      // A sound when this session ends: this Continue's own choice.
      const card = continueAt.closest(".xp-resume-card, .xp-continue-row");
      const sound = (card && card.querySelector("[data-xp-continue-sound]"))
        || $(`[data-xp-continue-sound="${CSS.escape(runId)}"]`);
      // Without the sandbox: this Continue's own choice (never a debugger way's).
      const unconfined = $(`[data-xp-continue-unconfined="${CSS.escape(runId)}"]`);
      const said = await api.post(host.continueUrl || "/api/work/continue", { run: runId,
        ...(host.extra ? host.extra(runId) : {}),
        limits: host.limits(continueAt),
        sound: Boolean(sound && sound.checked),
        ...(unconfined && unconfined.checked ? { unconfined: true } : {}),
        ...(asking ? { packages: asking.value } : {}),
        ...(from ? { from_version: from } : {}),
        ...(words ? { instruction: words } : {}) });
      delete kept.from[runId];
      delete kept.views[runId];
      delete kept.words[runId];
      delete kept.sound[runId];
      // What a rollback left as you had it, said.
      const back = (said || {}).rolled_back;
      if (back) {
        toast(`Back to ${back.version} (${back.branch})${(back.kept || []).length
          ? ` - ${back.kept.join("; ")}` : ""}`);
      }
    } catch (err) {
      toast(err.message);
    }
    await host.redraw(true);
    return true;
  }
  const versionsAt = event.target.closest("[data-xp-versions]");
  if (versionsAt) {
    // Opened, the run's versions are loaded; closed, they stay closed as
    // the panel is redrawn. (The click comes before the details toggles.)
    const kept = xpVersionsState();
    const runId = versionsAt.dataset.xpVersions;
    const opening = !versionsAt.parentElement.open;
    kept.open[runId] = opening;
    if (opening) await xpLoadVersions(runId);
    return true;
  }
  const versionViewAt = event.target.closest("[data-xp-version-view], [data-xp-version-node]");
  if (versionViewAt) {
    // A version picked - in the tree, or View in the list: the whole run is
    // shown as it stood then. The one shown already, picked again: nothing.
    const runId = versionViewAt.dataset.xpVersionRun;
    const versionId = versionViewAt.dataset.xpVersionView || versionViewAt.dataset.xpVersionNode;
    const kept = xpVersionsState();
    if (xpVersionPicked(runId) === versionId && (kept.views[runId] || {}).picked === versionId) {
      return true;
    }
    if (!(await xpVersionLoad(runId, versionId))) return true;
    xpVersionPick(runId, versionId);
    await host.redraw(true);
    return true;
  }
  const progressAt = event.target.closest("[data-xp-progress-from]");
  if (progressAt) {
    // Continue is set to go on from the progress point: the form under it
    // says so, and nothing happens until it is pressed.
    const runId = progressAt.dataset.xpProgressFrom;
    xpVersionsState().from[runId] = "progress";
    await host.redraw(true);
    const words = $(`.xp-progress-point [data-xp-continue-instruction="${CSS.escape(runId)}"]`);
    if (words) words.focus({ preventScroll: true });
    return true;
  }
  const versionFromAt = event.target.closest("[data-xp-version-from]");
  if (versionFromAt) {
    // Continue is set to go on from this version - picked, the run shown as
    // it stood then: the form under the tree says so, with the limits
    // above, and nothing happens until it is pressed.
    const kept = xpVersionsState();
    const runId = versionFromAt.dataset.xpVersionRun;
    const versionId = versionFromAt.dataset.xpVersionFrom;
    if ((kept.views[runId] || {}).picked !== versionId) await xpVersionLoad(runId, versionId);
    xpVersionPick(runId, versionId);
    kept.from[runId] = versionId;
    await host.redraw(true);
    // The form opens under the version you picked, the page where it is:
    // what to change is ready to be typed.
    const words = $(`.xp-version-continue [data-xp-continue-instruction="${CSS.escape(runId)}"]`);
    if (words) words.focus({ preventScroll: true });
    return true;
  }
  const deliverableAt = event.target.closest("[data-xp-deliverable]");
  if (deliverableAt) {
    // A deliverable opened for what it must meet stays open as the panel
    // is redrawn. (The click comes before the details toggles.)
    xpVersionsState().criteria[deliverableAt.dataset.xpDeliverable] =
      !deliverableAt.parentElement.open;
    return true;
  }
  const latestAt = event.target.closest("[data-xp-version-latest]");
  if (latestAt) {
    // Back to the latest: shown as it is now, and continued from there.
    const runId = latestAt.dataset.xpVersionLatest;
    delete xpVersionsState().from[runId];
    xpVersionPick(runId, "");
    await host.redraw(true);
    return true;
  }
  const versionDeckAt = event.target.closest("[data-xp-version-deck]");
  if (versionDeckAt) {
    // The slides as they were at that version.
    const runId = versionDeckAt.dataset.xpVersionDeck;
    const box = $(`#xp-version-deck-${CSS.escape(runId)}`);
    if (!box) return true;
    if (box.hidden) {
      box.innerHTML = `<iframe class="xp-deck-frame" title="The results then" src="/api/work/presentation?run=${
        encodeURIComponent(runId)}&version=${encodeURIComponent(versionDeckAt.dataset.xpVersionId)}"></iframe>`;
      box.hidden = false;
      versionDeckAt.textContent = "Hide the results deck";
    } else {
      box.hidden = true;
      box.innerHTML = "";
      versionDeckAt.textContent = "Show the results deck as it was then";
    }
    return true;
  }
  const liveToggleAt = event.target.closest("[data-xp-live-toggle]");
  const liveOpenAt = event.target.closest("[data-xp-live-open]");
  if (liveToggleAt || liveOpenAt) {
    // The live session opened - followed from now - or closed, and no
    // longer asked for. (The click comes before the details toggles.)
    const runId = liveToggleAt ? liveToggleAt.dataset.xpLiveToggle
      : liveOpenAt.dataset.xpLiveOpen;
    const live = xpLiveState(runId);
    live.open = liveOpenAt ? true : !liveToggleAt.parentElement.open;
    if (liveOpenAt) {
      event.preventDefault();
      await host.redraw(true);
      $(`[data-xp-live="${CSS.escape(runId)}"]`)?.scrollIntoView({ block: "nearest" });
    } else if (live.open) {
      xpLiveDraw(runId, null, true);
      xpLiveFollow(runId);
    }
    return true;
  }
  const pauseAt = event.target.closest("[data-xp-live-pause]");
  const resumeAt = event.target.closest("[data-xp-live-resume]");
  if (pauseAt || resumeAt) {
    // Paused, the run stops at its next safe point and waits; resumed, it
    // goes on exactly there.
    const runId = pauseAt ? pauseAt.dataset.xpLivePause : resumeAt.dataset.xpLiveResume;
    const clicked = pauseAt || resumeAt;
    clicked.disabled = true;
    // SHOWN AS CLICKED (the user, 2026-10-27: Resume made it wait): the
    // button says what is being done until the answer redraws it.
    clicked.textContent = pauseAt ? "Pausing…" : "Resuming…";
    try {
      await api.post(pauseAt ? "/api/work/pause" : "/api/work/resume", { run: runId });
    } catch (err) {
      toast(err.message);
    }
    try { await xpLiveFetch(runId); } catch (err) { /* the next look catches up */ }
    await host.redraw(true);
    return true;
  }
  const approveAt = event.target.closest("[data-xp-approve]");
  if (approveAt) {
    // Your answer to a request: the run waits for it. Asked in the live
    // session, and answered there.
    approveAt.closest(".xp-package-ask")?.querySelectorAll("button")
      .forEach((b) => { b.disabled = true; });
    const runId = approveAt.dataset.xpApprove;
    const card = approveAt.closest(".xp-package-ask");
    try {
      await api.post("/api/work/approve", { run: runId,
        request: approveAt.dataset.xpRequest, allow: approveAt.dataset.xpAllow === "1" });
    } catch (err) {
      toast(err.message);
    }
    try { await xpLiveFetch(runId); } catch (err) { /* the next look catches up */ }
    await host.redraw(true);
    // Tried again and still waiting: the same card, to be answered again.
    if (card && card.isConnected && card.classList.contains("xp-model-ask")) {
      setTimeout(() => card.querySelectorAll("button").forEach((b) => { b.disabled = false; }), 3000);
    }
    return true;
  }
  const modelFixAt = event.target.closest("[data-xp-model-fix]");
  if (modelFixAt) {
    // Where the model is mended: Settings, at its provider's sign-in. The
    // run goes on waiting - Try again once it is done.
    await openModelSettings(modelFixAt.dataset.xpModelFix);
    return true;
  }
  const deckAt = event.target.closest("[data-xp-deck]");
  if (deckAt) {
    // The slides, drawn from the run's own record: arrow keys move through
    // them once they have the focus.
    const box = $(`#xp-deck-${deckAt.dataset.xpDeck}`);
    if (!box) return true;
    // Open or not, kept: the panel drawn again keeps them as they are.
    xpVersionsState().decks[deckAt.dataset.xpDeck] = box.hidden;
    if (box.hidden) {
      box.innerHTML = `<iframe class="xp-deck-frame" title="The results" src="/api/work/presentation?run=${
        encodeURIComponent(deckAt.dataset.xpDeck)}"></iframe>`;
      box.hidden = false;
      deckAt.textContent = "Hide the slides";
    } else {
      box.hidden = true;
      box.innerHTML = "";
      deckAt.textContent = "Show the slides";
    }
    return true;
  }
  // OPEN LOG FOLDER: the project's run logs, in the machine's own file
  // manager - made first if no run has written there yet.
  const logsAt = event.target.closest("[data-xp-open-logs]");
  if (logsAt) {
    event.preventDefault();
    try {
      await api.post("/api/work/open_logs", { run: logsAt.dataset.xpOpenLogs });
    } catch (err) {
      toast(err.message);
    }
    return true;
  }
  const revealAt = event.target.closest("[data-xp-reveal]");
  if (revealAt) {
    event.preventDefault();
    try {
      await api.post("/api/work/reveal", { run: revealAt.dataset.xpRun,
                                           path: revealAt.dataset.xpReveal });
    } catch (err) {
      toast(err.message);
    }
  }
  return false;
}

/* The Experience tab's runs: the limits are those of its one form. */
const XP_HOST = {
  redraw: (force) => xpLoadRuns(force),
  limits: () => {
    const limit = (name) => {
      const typed = ($(`#xp-limit-${name}`) || {}).value;
      return typed === undefined || typed === "" ? undefined : Number(typed);
    };
    return Object.fromEntries(XP_LIMITS.map((name) => [name, limit(name)]));
  },
};

$("#xp-search-form")?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const q = $("#xp-search-q").value.trim();
  if (!q) return;
  const kinds = $("#xp-search-kind").value;
  $("#xp-search-out").innerHTML = `<p class="muted">searching…</p>`;
  let said;
  try {
    said = await api.get(`/api/experience/retrieve?q=${encodeURIComponent(q)}${
      kinds ? `&kinds=${encodeURIComponent(kinds)}` : ""}`);
  } catch (err) {
    $("#xp-search-out").innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  // EACH EXAMPLE IN ORDER: the steps before the match, the match, the steps
  // after it - as the work went, and as the agent is given it.
  $("#xp-search-out").innerHTML = `<h3>Examples (${(said.chains || []).length})</h3>
    ${(said.chains || []).map((chain) => `<ol class="xp-chain">${
      (chain.stages || []).map((s) => `<li class="${s.position === 0
        ? "xp-chain-match" : ""}"><span class="muted">${s.position === 0 ? "▶ match"
        : s.position > 0 ? `+${s.position}` : s.position}</span>
        <strong style="color:${XP_KIND_COLOUR[s.kind] || "inherit"}">${
        escapeHtml(s.kind)}</strong> ${escapeHtml(s.summary)}</li>`).join("")}
      </ol>`).join("")}
    <h3>Rules (${(said.rules || []).length})</h3>
    <ul>${(said.rules || []).map((r) => `<li><span class="xp-unit-kind">${
      escapeHtml(r.kind)}</span> ${escapeHtml(r.statement)} <span class="muted">${
      r.score}</span></li>`).join("")}</ul>`;
});

/* ------------------------------------------------------------------ tabs */
let activeTab = "overview";
$$("#tabs button").forEach((button) => {
  button.addEventListener("click", () => {
    $$("#tabs button").forEach((b) => b.classList.remove("active"));
    $$(".tab").forEach((t) => t.classList.remove("active"));
    button.classList.add("active");
    $(`#${button.dataset.tab}`).classList.add("active");
    if (activeTab === "debugger" && window.debuggerPanel) window.debuggerPanel.deactivate();
    if (activeTab === "chatdebug" && window.chatDebuggerPanel) {
      window.chatDebuggerPanel.deactivate();
    }
    if (activeTab === "listenerdebug" && window.listenerDebuggerPanel) {
      window.listenerDebuggerPanel.deactivate();
    }
    activeTab = button.dataset.tab;
    // THE PANEL IN THE ADDRESS, so a refresh opens the panel being looked
    // at - not the one the page was first opened on, which the address
    // went on naming (the page opens the tab after the #). Replaced, not
    // added: switching tabs is not a trail to walk back through.
    if (typeof DELEGATE_SOLO === "undefined" || !DELEGATE_SOLO) {
      const keep = activeTab === "chat" ? location.search : "";
      try {
        history.replaceState(null, "", `${location.pathname}${keep}#${activeTab}`);
      } catch (_err) { /* an address it may not change: left as it was */ }
    }
    if (activeTab === "chat") {
      // The conversations again, and the follow-ups put back in their
      // margin: it was measured while the tab had no width.
      chat?.activate();
    }
    // One look when the state heartbeat is opened, and an attachment to
    // whatever is in flight. It replaces a Refresh button: a round that
    // is running says so by itself, and one that is not has nothing to
    // refresh into.
    // The paper drawn as the tab opens, not at the next refresh.
    if (activeTab === "recommend" && typeof followKnowCard === "function") followKnowCard();
    if (activeTab === "statebeat" && typeof loadStateBeat === "function") {
      loadStateBeat();
      loadStateBeatConnections();
      if (typeof loadNotThisWork === "function") loadNotThisWork();
    }
    // Read when opened and after each change, not every fifteen seconds:
    // a list that redraws itself would take the person being edited out
    // from under the user.
    if (activeTab === "connections") loadConnections();
    if (activeTab === "experience") loadExperience(true);
    if (activeTab === "learning") loadLearning();
    if (activeTab === "resourcedebug") rdTick();
    if (activeTab === "overview") ovCentreTheCurrent();
    refresh();
  });
});

/* -------------------------------------------------------------- overview */
$("#ov-clear").addEventListener("click", clearApplicationSelection);
// Back returns to the application the page was found in, which is where the
// user was: a page opened from an application is a step down, not a new place.
$("#ov-detail-back").addEventListener("click", () => {
  if (overviewState.application) loadApplicationDetail(overviewState.application);
});

/* How much of a log fits beside the list before it stops being readable. */
const INTERACTIONS_SHOWN = 6;
const ITEMS_PER_INTERACTION = 12;
const VISITS_SHOWN = 20;
const TITLE_CHARS = 70;

/* Which cut lines the user has opened. Kept outside the render so that a
   refresh does not fold up what they were reading. */
const unfolded = new Set();

/* One log line, short enough to scan, with a way to see the rest.

   The log is a list read at a glance, so a title or address that runs to
   several hundred characters cannot sit in it whole. But a cut with no handle
   is worse than either: it hides that there was more, and leaves the panel no
   way to ask for it. So the cut carries its own small toggle, and which ones
   were opened is remembered. */
/* What a page was about: its keywords, the line of it that carries them,
   and - on request - the opening of what was read there.

   Worked out on the agent from the text the screen listener read (no model
   asked), and joined to the page or window by title. The text itself is
   behind a toggle, because it is the most personal thing on this panel and
   a list of pages should not become a wall of other people's messages by
   default. The toggle is remembered the way every other fold here is, so a
   refresh does not shut it in the middle of reading. */
function ovAbout(item, key) {
  const words = item.keywords || [];
  if (!words.length && !item.excerpt) return "";
  const open = unfolded.has(key);
  const chips = words.map((word) =>
    `<span class="ov-kw">${escapeHtml(word)}</span>`).join("");
  const read = Number(item.characters || 0);
  const toggle = item.excerpt
    ? `<button type="button" class="cut-toggle ov-read-toggle"
         data-cut="${escapeHtml(key)}">${open ? "▴ hide what was read"
         : `▸ what was read${read ? ` (${read.toLocaleString()} characters)` : ""}`
       }</button>`
    : "";
  const line = item.description
    ? `<div class="ov-about-line muted">${escapeHtml(item.description)}</div>`
    : "";
  const body = open && item.excerpt
    ? `<pre class="ov-read">${escapeHtml(item.excerpt)}${
        read > String(item.excerpt).length
          ? `\n\n… the first ${String(item.excerpt).length.toLocaleString()} of ${
              read.toLocaleString()} characters` : ""}</pre>`
    : "";
  return `<div class="ov-about">${chips}${toggle}${line}${body}</div>`;
}

function cut(text, key, limit = TITLE_CHARS) {
  const full = String(text || "").trim();
  if (!full) return "";
  if (full.length <= limit) return escapeHtml(full);
  const open = unfolded.has(key);
  const body = open ? full : full.slice(0, limit);
  const handle = open
    ? "▴ fold"
    : `▸ ${full.length - limit} more`;
  return `${escapeHtml(body)}<button type="button" class="cut-toggle"
    data-cut="${escapeHtml(key)}">${handle}</button>`;
}

/* Every cut line on the panel, wired to fold and unfold in place. */
function bindCuts(scope, rerender) {
  $$(`${scope} .cut-toggle`).forEach((button) =>
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const key = button.dataset.cut;
      if (unfolded.has(key)) unfolded.delete(key);
      else unfolded.add(key);
      rerender();
    }));
}

const overviewState = { application: null, hours: 24, page: null, site: null,
                        showAllInteractions: false,
                        expanded: new Set(), openApps: new Set(),
                        detail: null, held: null };

/* What the tab asks for, one request per panel.

   EACH PANEL DRAWS WHEN ITS OWN ANSWER ARRIVES. They were asked for
   together and drawn together, so the whole tab waited for the slowest
   answer - twenty seconds and more while the status measured the library -
   with answers that had been back for a second sitting unused. */
const OVERVIEW_ASKS = {
  overview: () => api.get("/api/overview?hours=24"),
  history: () => api.get("/api/overview/history?days=7"),
  hourly: () => api.get(`/api/overview/hourly?hours=${overviewState.hours}`),
  pages: () => api.get(`/api/overview/pages?hours=${overviewState.hours}`),
  files: () => api.get(`/api/overview/files?hours=${overviewState.hours}`),
  assistants: () =>
    api.get(`/api/overview/assistants?hours=${overviewState.hours}`),
  activity: () =>
    api.get(`/api/overview/file-activity?hours=${overviewState.hours}`),
  // The drawing of what is running, trimmed to what it needs: the
  // debugger's own report of the same round is megabytes of prompts
  // and exchanges, which is the right payload for investigating a
  // round and the wrong one for the tab this page is.
  picture: () => api.get("/api/state_heartbeat/picture").catch(() => null),
  principles: () => api.get("/api/experience/patterns").catch(() => null),
  lessonsPackage: () => api.get("/api/lessons/package").catch(() => null),
  // To do, beside the Summary task's progress bars.
  todos: () => api.get("/api/todos").catch(() => null),
};

/* WHAT THE COMPUTER WAS USED FOR - in the Debugger tab, asked for while it
   is open; the rest is the Overview's. */
const USAGE_PARTS = ["overview", "history", "hourly", "pages", "files", "assistants",
                     "activity"];
//: The natures, drawn - in the Nature debugger, asked for while it is open.
const NATURE_PARTS = ["principles"];
const OVERVIEW_PARTS = Object.keys(OVERVIEW_ASKS).filter((part) => !USAGE_PARTS.includes(part)
  && !NATURE_PARTS.includes(part));

/* ------------------------------------------------- the lessons package

   PACKAGE ALL LESSONS and LOAD LESSONS. Either runs in the background, one
   at a time; while one does, the card asks again every second and a half
   and says what it is doing, and the buttons that would start another are
   off. What the last packaging did - how long it took, what the model calls
   cost, what was new and what was reused - stays on the card with the ones
   before it, and the last load says what it added, updated and skipped. */
const lessonsPackageState = { timer: null, held: null };

function lpBytes(value) {
  let size = Number(value || 0);
  for (const unit of ["B", "KB", "MB", "GB"]) {
    if (size < 1024 || unit === "GB") {
      return unit === "B" ? `${size.toFixed(0)} B` : `${size.toFixed(1)} ${unit}`;
    }
    size /= 1024;
  }
  return `${size.toFixed(1)} GB`;
}

function lpNumber(value) {
  return Number(value || 0).toLocaleString();
}

function lpWhen(iso) {
  if (!iso) return "?";
  const when = new Date(iso);
  return Number.isNaN(when.getTime()) ? String(iso) : when.toLocaleString();
}

function lpTokens(stats) {
  const cached = Number(stats.tokens_in_cached || 0);
  return `${lpNumber(stats.calls)} model call${Number(stats.calls) === 1 ? "" : "s"} · ` +
    `tokens in ${lpNumber(stats.tokens_in)}` +
    (cached ? ` (${lpNumber(cached)} from cache)` : "") +
    ` · out ${lpNumber(stats.tokens_out)}`;
}

/* What one packaging did, in lines: when and how long, what it cost,
   each kind of lesson, the references, and the sizes. */
function lpStatsHtml(stats) {
  const items = Object.entries(stats.items || {}).map(([kind, n]) =>
    `<li><b>${escapeHtml(kind)}</b> ${lpNumber(n.total)}` +
    ` <span class="muted">(${lpNumber(n.new)} new, ${lpNumber(n.updated)} updated, ` +
    `${lpNumber(n.unchanged)} unchanged)</span></li>`).join("");
  const r = stats.references || {};
  const refs = `${lpNumber(r.references)} references, ${lpNumber(r.files)} files: ` +
    `${lpNumber(r.copied)} copied, ${lpNumber(r.compressed)} compressed, ` +
    `${lpNumber(r.summarised)} summarised, ${lpNumber(r.reused)} reused, ` +
    `${lpNumber(r.missing)} missing, ${lpNumber(r.excluded)} excluded` +
    (r.unsummarised ? `, ${lpNumber(r.unsummarised)} too large and not summarised` : "") +
    (r.urls ? ` · ${lpNumber(r.urls)} web addresses kept as addresses` : "");
  return `<div class="ov-lp-stats">` +
    `<div>Packaged ${escapeHtml(lpWhen(stats.finished_at))} in ` +
    `${escapeHtml(String(stats.seconds_total ?? stats.seconds ?? "?"))} s ` +
    `<span class="muted">(zip ${escapeHtml(String(stats.zip_seconds ?? "?"))} s)</span></div>` +
    `<div>${escapeHtml(lpTokens(stats))}</div>` +
    `<div>${escapeHtml(refs)}</div>` +
    `<div>Added ${escapeHtml(lpBytes(stats.bytes_added))} · package ` +
    `${escapeHtml(lpBytes(stats.package_bytes))} · zip ` +
    `<span class="ov-lp-zip">${escapeHtml(stats.zip || "-")}</span> ` +
    `${escapeHtml(lpBytes(stats.zip_bytes))}</div>` +
    `<ul class="ov-lp-items">${items}</ul></div>`;
}

function lpReportHtml(report) {
  if (!report) return "";
  const t = report.totals || {};
  const r = report.references || {};
  const c = report.calendar || {};
  const kinds = Object.entries(report.kinds || {}).map(([kind, n]) =>
    `<li><b>${escapeHtml(kind)}</b> ${lpNumber(n.added)} added, ` +
    `${lpNumber(n.updated)} updated, ${lpNumber(n.skipped)} skipped</li>`).join("");
  const conflicts = (report.conflicts || []).slice(0, 20).map((one) =>
    `<li>${escapeHtml(one)}</li>`).join("");
  return `<div class="ov-lp-load"><div><b>Last load</b> ` +
    `${escapeHtml(lpWhen(report.finished_at))}: ${escapeHtml(report.path || "")}` +
    ` <span class="muted">(package ${escapeHtml(report.package_id || "?")}` +
    `${report.machine ? ` from ${escapeHtml(report.machine)}` : ""})</span></div>` +
    `<div class="ov-lp-load-totals">${lpNumber(t.added)} added, ` +
    `${lpNumber(t.updated)} updated, ${lpNumber(t.skipped)} skipped · ` +
    `${lpNumber(r.files_copied)} files and ${lpNumber(r.summaries)} summaries copied here · ` +
    `${lpNumber(c.lessons_added)} notification lessons added` +
    `${c.summarised_again ? " (summarised again)" : ""}</div>` +
    `<ul class="ov-lp-items">${kinds}</ul>` +
    (conflicts ? `<div class="muted">Left as they were:</div><ul>${conflicts}</ul>` : "") +
    `</div>`;
}

function renderLessonsPackage(state) {
  lessonsPackageState.held = state;
  const running = Boolean(state && state.running);
  $("#ov-lp-package").disabled = running;
  $("#ov-lp-load").disabled = running;
  $("#ov-lp-load-folder").disabled = running;
  $("#ov-lp-cancel").hidden = !running;
  if (!state) {
    $("#ov-lp-progress").textContent = "The lessons package could not be read.";
    return;
  }
  const p = state.progress || {};
  $("#ov-lp-progress").textContent = running
    ? `${p.kind === "loading" ? "Loading" : "Packaging"}: ${p.phase || "starting"}` +
      (p.total ? ` (${lpNumber(p.done)} of ${lpNumber(p.total)})` : "") + "…"
    : (state.last_error || "");
  $("#ov-lp-last").innerHTML = state.last
    ? lpStatsHtml(state.last)
    : `<p class="muted">Not packaged yet. The package will be kept in ` +
      `${escapeHtml(state.folder || "the workspace")}.</p>`;
  $("#ov-lp-report").innerHTML = lpReportHtml(state.last_load);
  const history = (state.history || []).slice(0, 10).map((one) =>
    `<li><span>${escapeHtml(lpWhen(one.finished_at))}</span> · ` +
    `${escapeHtml(String(one.seconds_total ?? one.seconds ?? "?"))} s · ` +
    `${escapeHtml(lpTokens(one))} · added ${escapeHtml(lpBytes(one.bytes_added))} · ` +
    `zip ${escapeHtml(lpBytes(one.zip_bytes))}</li>`).join("");
  $("#ov-lp-history").innerHTML = history
    ? `<details class="ov-lp-history"><summary>Packagings so far ` +
      `(${(state.history || []).length})</summary><ul>${history}</ul></details>`
    : "";
  clearTimeout(lessonsPackageState.timer);
  if (running) {
    lessonsPackageState.timer = setTimeout(refreshLessonsPackage, 1500);
  }
}

async function refreshLessonsPackage() {
  try {
    renderLessonsPackage(await api.get("/api/lessons/package"));
  } catch (err) {
    console.warn("lessons package", err);
  }
}

async function packageAllLessons() {
  try {
    renderLessonsPackage(await api.post("/api/lessons/package", {}));
  } catch (err) { toast(err.message, "error"); refreshLessonsPackage(); }
}

/* LOAD LESSONS: the package is chosen with the machine's own chooser - its
   zip, or its folder; where no chooser can be shown, its path is typed. */
async function loadLessonsPackage(pick) {
  try {
    let answer = await api.post("/api/lessons/load", { pick });
    if (!answer.started && answer.chooser && answer.chooser.available === false) {
      const typed = window.prompt("The lessons package to load - the path of its zip or folder:");
      if (!typed) return;
      answer = await api.post("/api/lessons/load", { path: typed });
    }
    if (!answer.started) return;
    toast("Loading lessons from " + answer.path);
    renderLessonsPackage(answer);
  } catch (err) { toast(err.message, "error"); }
}

$("#ov-lp-package").addEventListener("click", packageAllLessons);
$("#ov-lp-cancel").addEventListener("click", async () => {
  try { await api.post("/api/lessons/package/cancel", {}); } catch (err) { toast(err.message, "error"); }
  refreshLessonsPackage();
});
$("#ov-lp-load").addEventListener("click", () => loadLessonsPackage("zip"));
$("#ov-lp-load-folder").addEventListener("click", () => loadLessonsPackage("folder"));
$("#ov-lp-open").addEventListener("click", async () => {
  try { await api.post("/api/lessons/package/open", {}); } catch (err) { toast(err.message, "error"); }
});

async function loadOverview(parts = Object.keys(OVERVIEW_ASKS)) {
  // What was drawn last stays up until its own answer is replaced, so a
  // refresh never empties a panel to wait for it.
  // Starting over (nothing held) draws everything again, changed or not.
  if (!overviewState.held) overviewState.drawnFrom = {};
  const held = Object.assign({}, overviewState.held || {});
  overviewState.held = held;
  // DRAWN AGAIN ONLY WHEN IT CHANGED. Every fifteen seconds each panel
  // was rebuilt whether or not anything in it had moved - the task picture
  // included, which redrew under the reader's pointer, closed what they
  // were hovering and reset what they were looking at. An answer the same
  // as the one on screen leaves the panel as it is.
  const drawnFrom = overviewState.drawnFrom || (overviewState.drawnFrom = {});
  await Promise.allSettled(parts.map((part) => [part, OVERVIEW_ASKS[part]]).map(
    ([part, ask]) => ask().then((answer) => {
      held[part] = answer;
      if (overviewState.held !== held) return;   // a newer load took over
      const said = JSON.stringify(answer ?? null);
      if (drawnFrom[part] === said) return;
      drawnFrom[part] = said;
      drawOverviewPart(part, held);
    }).catch((err) => console.warn(`overview: ${part}`, err))));
  if (overviewState.held !== held || !parts.includes("overview")) return;
  // A refresh must not silently drop what the user was reading.
  if (overviewState.page) await loadPageDetail(overviewState.page);
  else if (overviewState.application) await loadApplicationDetail(overviewState.application);
}

/* The tab again, from the answers already here.

   Opening an application's breakdown, choosing a site inside it and opening
   out a cut label change only how the same answers are drawn - and each of
   them fetched everything again and rebuilt every panel, both charts
   included. The caret in "Usage by application" cost a reload of the whole
   tab, which is what made clicking one feel like waiting for it.
*/
async function redrawOverview() {
  if (!overviewState.held) return loadOverview();
  await drawOverview(overviewState.held);
}

async function drawOverview(held) {
  Object.keys(OVERVIEW_ASKS).forEach((part) => {
    if (part in held) drawOverviewPart(part, held);
  });
  // A refresh must not silently drop what the user was reading. The panel
  // reloads itself every fifteen seconds, and rebuilding the application's log
  // over an open page would take the user back out of it while they were
  // reading - looking, from where they sit, as though the panel closed itself.
  if (overviewState.page) await loadPageDetail(overviewState.page);
  else if (overviewState.application) await loadApplicationDetail(overviewState.application);
}

function drawOverviewPart(part, held) {
  const answer = held[part];
  if (part === "picture") { drawWhatIsRunning(answer); return; }
  if (part === "principles") { renderPrinciples(answer); return; }
  if (part === "lessonsPackage") { renderLessonsPackage(answer); return; }
  if (part === "todos") {
    if (answer) ovTodos = answer.todos || [];
    ovPlaceTodos();
    return;
  }
  if (!answer) return;
  if (part === "overview") {
    const overview = answer;
    $("#ov-total").textContent = overview.total_human;
    const period = `last ${overview.window_hours} hours`;
    $("#ov-window").textContent = period;
    // Every panel drawn from this window says so. One heading carrying the
    // period and the rest carrying none reads as though the rest covered
    // something else - and "Usage by application" is the one people compare
    // against their own memory of the day, where the period is the whole
    // question.
    document.querySelectorAll("[data-window]").forEach((node) => {
      node.textContent = period;
    });
    bars(
      $("#ov-apps"),
      overview.applications.map((a) => ({
        label: a.application, value: a.seconds, display: a.human,
        selected: a.application === overviewState.application,
        children: (a.breakdown || []).map((b) => ({
          label: b.label, count: b.count, url: b.url || "",
          selected: a.application === overviewState.application
            && b.label === overviewState.site,
        })),
      })),
      {
        onClick: (row) => selectApplication(row.label),
        onExpand: (row) => {
          if (overviewState.openApps.has(row.label)) overviewState.openApps.delete(row.label);
          else overviewState.openApps.add(row.label);
          redrawOverview();
        },
        onSelectChild: (application, site) => selectSite(application, site),
        expanded: overviewState.openApps,
      }
    );
    bindPageLinks("#ov-apps");
    bindCuts("#ov-apps", redrawOverview);
    return;
  }
  if (part === "history") {
    // Historical activity is a read-out, not a control: it must not offer the
    // click affordance that the application list does.
    bars(
      $("#ov-history"),
      answer.days.map((d) => ({
        label: d.date, value: d.total_seconds,
        display: d.total_human,
        title: d.top_application ? `most used: ${d.top_application}` : "no activity recorded",
      }))
    );
    return;
  }
  if (part === "hourly") renderHourly(answer);
  else if (part === "pages") renderPages(answer);
  else if (part === "files") renderFiles(answer);
  else if (part === "assistants") renderAssistants(answer);
  else if (part === "activity") renderFileActivity(answer);
}

async function selectApplication(name) {
  // Selecting the one already selected clears it: the control that made the
  // selection is the obvious place to reach for to undo it, and it costs
  // nothing to let it do that.
  if (overviewState.application === name) {
    clearApplicationSelection();
    return;
  }
  const changed = overviewState.application !== name;
  overviewState.application = name;
  overviewState.page = null;
  // Each application's log starts folded: how far the last one was opened
  // says nothing about this one.
  if (changed) {
    overviewState.expanded = new Set();
    overviewState.showAllInteractions = false;
    overviewState.site = null;
  }
  $$("#ov-apps .bar-row").forEach((row) =>
    row.classList.toggle("selected", row.dataset.label === name));
  $("#ov-clear").hidden = false;
  await loadApplicationDetail(name);
}

/* Section 9, as amended: one site inside an application is a narrower version
   of the same question, so it narrows the same log rather than opening
   something else. Choosing the site already in view widens it again. */
async function selectSite(application, site) {
  const same = overviewState.application === application && overviewState.site === site;
  overviewState.application = application;
  overviewState.site = same ? null : site;
  overviewState.expanded = new Set();
  overviewState.showAllInteractions = false;
  overviewState.page = null;
  overviewState.detail = null;
  $("#ov-clear").hidden = false;
  // The list is redrawn from what is here; the log is a different question
  // of the server, because narrowing to a site narrows what it answers.
  await redrawOverview();
  await loadApplicationDetail(application);
}

/* Section 9, as amended: a selection the user made is a selection they can
   undo. Without this the panel keeps one application in view until another is
   picked, and there is no way back to looking at everything. */
function clearApplicationSelection() {
  overviewState.application = null;
  overviewState.page = null;
  overviewState.site = null;
  overviewState.detail = null;
  overviewState.expanded = new Set();
  overviewState.showAllInteractions = false;
  $$("#ov-apps .bar-row").forEach((row) => row.classList.remove("selected"));
  $("#ov-clear").hidden = true;
  $("#ov-detail-back").hidden = true;
  $("#ov-detail-title").textContent = "Application detail";
  $("#ov-detail-name").textContent = "";
  $("#ov-detail").className = "muted";
  // Not "above": the panel sits beside the list on a wide window and below it
  // on a narrow one, so the words must not claim a direction.
  $("#ov-detail").textContent = "Select an application to inspect its activity log.";
}

/* Section 19, as amended: what was read, and what was written.

   Different from the list of files above, which answers "what has been
   worked on most" by collapsing everything about one file into a count.
   This answers "what have I just been doing", which is a sequence and keeps
   its order.

   Read and written are told apart because they are different things. Windows
   reports both as one kind of change and the Listener separates them by
   whether the content actually moved - so a file the user only opened is not
   reported back as one they edited.
*/
const activityState = { filter: "", rows: [], held: null };

function renderFileActivity(data) {
  if (data) activityState.held = data;
  const held = activityState.held;
  const host = $("#ov-activity-body");
  if (!host || !held) return;

  const rows = (held.activity || []).filter((row) =>
    !activityState.filter ? true
      : activityState.filter === "read" ? row.read : !row.read);

  const note = $("#ov-activity-note");
  if (note) {
    note.textContent = held.total
      ? `${held.written} changed · ${held.read} read · last ${
        held.window_hours || 24} hours`
      : "";
  }

  if (!rows.length) {
    host.innerHTML = `<p class="muted">${held.collection && !held.collection.enabled
      ? escapeHtml(held.collection.reason)
      : activityState.filter
        ? "Nothing of that kind in this window."
        : "No file activity recorded in this window."}</p>`;
    return;
  }

  host.innerHTML = `<ul class="activity-list">` + rows.map((row) => {
    // How many times and over how long, said only where it means something:
    // one touch has no span, and a file saved twenty times while it is being
    // written is one stretch of work rather than twenty events.
    const again = row.times > 1
      ? `<span class="muted activity-again">${row.times}×${
        row.over_human ? ` over ${escapeHtml(row.over_human)}` : ""}</span>`
      : "";
    return `<li class="activity-row">
      <span class="muted activity-at">${clock(row.last_at)}</span>
      <span class="activity-what ${row.read ? "read" : "wrote"}">${
        escapeHtml(row.what)}</span>
      <span class="activity-name" title="${escapeHtml(row.path)}">${
        cut(row.name, `fa:${row.path}`)}</span>
      <span class="muted activity-folder">${cut(row.folder, `fd:${row.path}`)}</span>
      ${again}${ovAbout(row, `ra:f:${row.path}:${row.what}`)}</li>`;
  }).join("") + `</ul>`;
  bindCuts("#ov-activity-body", () => renderFileActivity());
}

function wireFileActivity() {
  const filter = $("#ov-activity-filter");
  if (filter) {
    filter.addEventListener("change", () => {
      activityState.filter = filter.value;
      renderFileActivity();
    });
  }
}

/* Section 9, as amended: how activity moved through the day, not only what it
   added up to. One line per application, so the shape shows what was being
   used when. */
const SERIES_COLORS = ["#3d6be5", "#2f9e6b", "#d08a2c", "#8b5cf6", "#cf4b45", "#0e93a8"];

function renderHourly(hourly) {
  const host = $("#ov-hourly");
  if (!host) return;
  const buckets = hourly.buckets || [];
  const series = hourly.series || [];
  if (!buckets.length || !series.length) {
    host.innerHTML = '<div class="muted">No activity recorded in this window yet.</div>';
    return;
  }
  const width = 720;
  const height = 220;
  const pad = { top: 12, right: 12, bottom: 40, left: 44 };
  const plotW = width - pad.left - pad.right;
  const plotH = height - pad.top - pad.bottom;
  // A SHARE OF THE HOUR, not minutes. Minutes scaled to the busiest hour
  // shown meant the same height said different things on different days;
  // a share of the hour reads the same everywhere - half the line's height
  // is half the hour. The hour still going is measured against how much of
  // it there has been, which the agent reports with each hour.
  const shareOf = (b, name) => {
    const span = Number(b.span_seconds || 3600);
    return Math.min(100, ((b.applications[name] || 0) / span) * 100);
  };
  const x = (i) => pad.left + (buckets.length === 1 ? plotW / 2
    : (i / (buckets.length - 1)) * plotW);
  const y = (percent) => pad.top + plotH - (percent / 100) * plotH;

  const gridLines = [0, 25, 50, 75, 100].map((value) =>
    `<line x1="${pad.left}" y1="${y(value)}" x2="${width - pad.right}" y2="${y(value)}"
       class="chart-grid"/>
     <text x="${pad.left - 8}" y="${y(value) + 4}" class="chart-axis" text-anchor="end">${
       value}%</text>`).join("");

  const everyNth = Math.max(1, Math.round(buckets.length / 8));
  // Section 9, as amended: an hour label alone is ambiguous across midnight,
  // so each day boundary is drawn and named.
  // A forced day-boundary label and a regular one can land side by side, so
  // the regular one gives way.
  const dayBreaks = buckets.map((b, i) => (b.starts_a_day ? i : -1)).filter((i) => i >= 0);
  const xLabels = buckets.map((b, i) => {
    const nearBreak = dayBreaks.some((index) => index !== i && Math.abs(index - i) < everyNth);
    const show = b.starts_a_day || (i % everyNth === 0 && !nearBreak);
    if (!show) return "";
    const hour = `<text x="${x(i)}" y="${height - 14}" class="chart-axis"
      text-anchor="middle">${escapeHtml(b.label)}</text>`;
    const day = (b.starts_a_day || i === 0)
      ? `<text x="${x(i)}" y="${height - 2}" class="chart-axis chart-date"
           text-anchor="middle">${escapeHtml(b.date_label)}</text>`
      : "";
    const rule = b.starts_a_day && i > 0
      ? `<line x1="${x(i)}" y1="${pad.top}" x2="${x(i)}" y2="${pad.top + plotH}"
           class="chart-daybreak"/>`
      : "";
    return rule + hour + day;
  }).join("");

  const paths = series.map((name, index) => {
    const color = SERIES_COLORS[index % SERIES_COLORS.length];
    const points = buckets.map((b, i) => `${x(i)},${y(shareOf(b, name))}`);
    const dots = buckets.map((b, i) => {
      const minutes = (b.applications[name] || 0) / 60;
      if (!minutes) return "";
      // The share on the axis and the minutes it is a share of, both.
      return `<circle cx="${x(i)}" cy="${y(shareOf(b, name))}" r="3" fill="${color}"><title>${
        escapeHtml(name)} · ${escapeHtml(b.label)} · ${Math.round(shareOf(b, name))}% of the hour (${
        minutes.toFixed(0)}m)</title></circle>`;
    }).join("");
    return `<polyline points="${points.join(" ")}" fill="none" stroke="${color}"
              stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>${dots}`;
  }).join("");

  const legend = series.map((name, index) =>
    `<span class="legend-item"><i style="background:${
      SERIES_COLORS[index % SERIES_COLORS.length]}"></i>${escapeHtml(name)}</span>`).join("");

  host.innerHTML = `
    <div class="chart-period muted">${escapeHtml(hourly.period || "")}</div>
    <div class="chart-legend">${legend}</div>
    <svg viewBox="0 0 ${width} ${height}" class="line-chart" role="img"
         aria-label="Activity by hour, one line per application">
      ${gridLines}${xLabels}${paths}
    </svg>`;
}

/* An empty view has two very different causes, and the panel must not present
   them identically: nothing happened, or nothing was being recorded. */
function collectionNotice(collection, hasRecords) {
  if (!collection || collection.enabled !== false) return "";
  const reason = escapeHtml(collection.reason || "this source is turned off");
  // Saying "nothing is recorded" above a list of records is a contradiction:
  // an off source explains why the list is empty, or why it has stopped growing.
  return `<div class="collection-off">${hasRecords
    ? `Nothing new is being recorded: ${reason}. These are earlier records.`
    : `Nothing is recorded here: ${reason}.`}</div>`;
}

function renderPages(data) {
  const host = $("#ov-pages");
  if (!host) return;
  $("#ov-pages-count").textContent = data.total_pages
    ? `${data.total_pages} pages · ${data.total_visits} visits`
    : "";
  const notice = collectionNotice(data.collection, data.pages.length > 0);
  if (!data.pages.length) {
    host.innerHTML = notice ||
      '<div class="muted">No pages recorded in this window.</div>';
    return;
  }
  host.innerHTML = notice + `<ul class="detail-list">${data.pages.map((page) => `
    <li>
      <div class="detail-head">
        <span class="detail-count">${page.visits}×</span>
        <span class="detail-name" title="${escapeHtml(page.url)}">${
          escapeHtml(page.title || page.url)}</span>
        <span class="muted detail-when">${escapeHtml(shortTime(page.last_visited))}</span>
      </div>
      <div class="muted detail-sub">${escapeHtml(page.site || "")}${
        page.browser ? ` · ${escapeHtml(page.browser)}` : ""}</div>
    </li>`).join("")}</ul>`;
}

function renderFiles(data) {
  const host = $("#ov-files");
  if (!host) return;
  $("#ov-files-count").textContent = data.total_files
    ? `${data.total_files} files · ${data.total_changes} changes`
    : "";
  const notice = collectionNotice(data.collection, data.files.length > 0);
  if (!data.files.length) {
    host.innerHTML = notice ||
      '<div class="muted">No files recorded in this window.</div>';
    return;
  }
  host.innerHTML = notice + `<ul class="detail-list">${data.files.map((file) => `
    <li>
      <div class="detail-head">
        <span class="detail-count">${file.changes}×</span>
        <span class="detail-name" title="${escapeHtml(file.path)}">${
          escapeHtml(file.name)}</span>
        <span class="muted detail-when">${escapeHtml(shortTime(file.last_change))}</span>
      </div>
      <div class="muted detail-sub">${escapeHtml(file.change || "")}${
        file.folder ? ` · ${escapeHtml(file.folder)}` : ""}</div>
    </li>`).join("")}</ul>`;
}

function renderAssistants(data) {
  const host = $("#ov-assistants");
  if (!host) return;
  $("#ov-assistants-count").textContent = data.total_projects
    ? `${data.total_projects} projects · ${data.total_sessions} sessions`
    : "";
  const notice = collectionNotice(data.collection, data.projects.length > 0);
  if (!data.projects.length) {
    host.innerHTML = notice ||
      '<div class="muted">No assistant sessions recorded in this window.</div>';
    return;
  }
  host.innerHTML = notice + `<ul class="detail-list">${data.projects.map((row) => `
    <li>
      <div class="detail-head">
        <span class="detail-count">${row.sessions}×</span>
        <span class="detail-name" title="${escapeHtml(row.project)}">${
          escapeHtml(row.name || row.project)}</span>
        <span class="muted detail-when">${escapeHtml(shortTime(row.last_activity))}</span>
      </div>
      <div class="muted detail-sub">${escapeHtml(row.tool)} · ${
        row.exchanges} exchanges · ${escapeHtml(row.project)}</div>
    </li>`).join("")}</ul>`;
}

/* A MOMENT THE AGENT WROTE DOWN - in UTC, as it keeps them - IN THE USER'S
   TIME ZONE, this computer's: "2026-10-12 08:20" ("minute"), the date, the
   time to the second, or "10-12 08:20" ("short"). Cut from the text as it
   was, it read five hours off. A date alone, or a time written with no
   zone, is shown as written. */
function localStamp(value, part = "minute") {
  const text = String(value || "");
  const zoned = /T\d\d:\d\d.*(Z|[+-]\d\d:?\d\d)$/.test(text);
  const when = zoned ? new Date(text) : null;
  if (!when || Number.isNaN(when.getTime())) {
    if (part === "date") return text.slice(0, 10);
    if (part === "time") return text.slice(11, 19);
    if (part === "short") return text.slice(5, 16).replace("T", " ");
    return text.slice(0, 16).replace("T", " ");
  }
  const pad = (n) => String(n).padStart(2, "0");
  const date = `${when.getFullYear()}-${pad(when.getMonth() + 1)}-${pad(when.getDate())}`;
  const minute = `${pad(when.getHours())}:${pad(when.getMinutes())}`;
  if (part === "date") return date;
  if (part === "time") return `${minute}:${pad(when.getSeconds())}`;
  if (part === "short") return `${date.slice(5)} ${minute}`;
  return `${date} ${minute}`;
}

function shortTime(value) {
  if (!value) return "";
  const when = new Date(value);
  if (Number.isNaN(when.getTime())) return "";
  const sameDay = when.toDateString() === new Date().toDateString();
  return sameDay
    ? when.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" })
    : when.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

async function loadApplicationDetail(name) {
  const site = overviewState.site;
  const detail = await api.get(`/api/overview/application?name=${encodeURIComponent(name)}`
    + `&hours=${overviewState.hours}`
    + (site ? `&site=${encodeURIComponent(site)}` : ""));
  // Held so that opening a stretch, or showing more of them, can redraw from
  // what is already here (see redrawApplicationDetail).
  overviewState.detail = { name, site, detail };
  drawApplicationDetail(name, site, detail);
}

/* The same log again, from the answer already in hand.

   Expanding a stretch of use, showing more of them, and opening out a cut
   title are all changes to how the same data is drawn - and each of them
   asked the server for it again. The panel is rebuilt either way, so the
   request bought nothing and cost a round trip on every click: on this
   machine that endpoint took 300ms before its query was given an index.
*/
function redrawApplicationDetail() {
  const held = overviewState.detail;
  if (!held) return;
  drawApplicationDetail(held.name, held.site, held.detail);
}

function drawApplicationDetail(name, site, detail) {
  $("#ov-detail-title").textContent = site ? "Site detail" : "Application detail";
  $("#ov-detail-name").textContent = site ? `${site} · in ${name}` : name;
  $("#ov-detail-back").hidden = true;
  $("#ov-detail").className = "";

  // Section 9, as amended: a stretch of use is shown with what was open during
  // it. A list of durations answers "how long" and never "doing what", which
  // is the question someone opens this panel with.
  const interactions = detail.interactions || [];
  const rowsFor = (interaction, index) => {
    // Which stretch is open is remembered by the stretch, not by its position.
    //
    // The panel is rebuilt on every refresh, and by then the list has moved:
    // a new stretch of use goes on the front and everything shifts down one.
    // Held by position, "the third row is open" then meant a different third
    // row - so the stretch the user had opened closed itself, seconds after
    // they opened it, while some other one sprang open in its place.
    const key = interaction.ongoing
      ? "ongoing"
      : String(interaction.started_at || interaction.ended_at || index);
    const open = overviewState.expanded.has(key);
    const all = [...(interaction.pages || []), ...(interaction.files || []),
                 ...(interaction.windows || []), ...(interaction.assistant || []),
                 ...(interaction.reads || [])]
      .sort((a, b) => String(b.at).localeCompare(String(a.at)));
    // One busy stretch can hold hundreds of visits; the panel shows the most
    // recent of them and says how many it is not showing, rather than
    // becoming unreadable the moment it is opened.
    const items = all.slice(0, ITEMS_PER_INTERACTION);
    const trimmed = all.length - items.length;
    const contents = items
      .map((item) => item.kind === "page"
        ? `<li><span class="muted">${clock(item.at)}</span>
             <a href="#" class="ov-page" data-url="${escapeHtml(item.url || "")}">${
               cut(item.title || item.url || "untitled", `p:${item.at}:${item.url}`)}</a>
             <span class="muted">${escapeHtml(item.site || "")}</span>
             ${ovAbout(item, `ra:p:${item.at}:${item.url}`)}</li>`
        : item.kind === "assistant"
        ? `<li><span class="muted">${clock(item.at)}</span>
             <span class="who">${escapeHtml(item.role === "user" ? "you"
               : item.role === "assistant" ? item.tool || "assistant" : item.role)}</span>
             ${cut(item.text, `a:${item.at}:${item.role}`, 160)}</li>`
        : item.kind === "window"
        ? `<li><span class="muted">${clock(item.at)}</span>
             ${cut(item.title, `w:${item.at}:${item.title}`)}
             <span class="muted">window</span>
             ${ovAbout(item, `ra:w:${item.at}:${item.title}`)}</li>`
        : item.kind === "read"
        // Read in a window that matched no page or window of its own - a
        // desktop application, a terminal.
        ? `<li><span class="muted">${clock(item.at)}</span>
             ${cut(item.title, `r:${item.at}:${item.title}`)}
             <span class="muted">read</span>
             ${ovAbout(item, `ra:r:${item.at}:${item.title}`)}</li>`
        : `<li><span class="muted">${clock(item.at)}</span>
             ${cut(item.name || item.path, `f:${item.at}:${item.path}`)}
             <span class="muted">${escapeHtml(item.change || "")}</span></li>`)
      .join("");
    const when = interaction.ongoing
      ? "still going"
      : `${clock(interaction.started_at)} – ${clock(interaction.ended_at)}`;
    // A stretch shared with another window spans more than it spent here.
    // Shown as "4m of 8m" rather than as one number, because the duration
    // alone reads as the whole stretch and the span alone counts somebody
    // else's time as this application's.
    const spent = interaction.span_human
      ? `${interaction.duration_human} of ${interaction.span_human}`
      : (interaction.duration_human || "");
    const count = interaction.item_count || 0;
    return `<div class="interaction${open ? " open" : ""}">
      <div class="interaction-head">
        <button type="button" class="small secondary ov-expand" data-key="${escapeHtml(key)}"
          ${count ? "" : "disabled"}>${open ? "Collapse" : "Expand"}</button>
        <span class="interaction-when">${when}</span>
        <span class="muted">${escapeHtml(spent)}</span>
        <span class="interaction-title">${
          cut(interaction.window_title || "", `w:${interaction.ended_at}`)}</span>
        <span class="muted">${count ? `${count} recorded` : "nothing recorded"}</span>
      </div>
      ${open && count ? `<ul class="interaction-items">${contents}${
        trimmed > 0 ? `<li class="muted">and ${trimmed} more</li>` : ""}</ul>` : ""}</div>`;
  };

  // The panel is a column beside the list, not a page of its own: showing
  // every stretch of use pushes everything below it off the screen. A few are
  // shown, and the rest are behind one control that says how many there are.
  const shown = overviewState.showAllInteractions
    ? interactions
    : interactions.slice(0, INTERACTIONS_SHOWN);
  const hidden = interactions.length - shown.length;
  // When narrowed, say so plainly and offer the way back: the stretches shown
  // are a subset, and a log that quietly omits things misleads.
  const narrowed = site
    ? `<div class="muted narrowed">Only what happened on
         <strong>${escapeHtml(site)}</strong>.
         <button type="button" class="small secondary" id="ov-widen">Show all of ${
           escapeHtml(name)}</button></div>`
    : "";
  // Said, because a panel that shows a slice and calls it a day is worse
  // than one that says it is a slice.
  // Not named "cut": that is the function every label in this panel is
  // trimmed with, and shadowing it here put all of them in the temporal
  // dead zone - which is not a rendering bug, it is the panel not existing.
  const overflowed = detail.complete === false
    ? `<div class="muted narrowed">More happened in this window than this
         panel reads. The oldest of it is not shown.</div>`
    : "";
  $("#ov-detail").innerHTML = interactions.length
    ? `${narrowed}${overflowed}<div class="muted">Each stretch of use in the last ${
         detail.window_hours || 24} hours, most recent first. Expand one to see
         the ${site ? "visits" : "pages and files"} in it.</div>
       ${shown.map(rowsFor).join("")}
       ${hidden > 0 || overviewState.showAllInteractions
          ? `<button type="button" class="small secondary" id="ov-more">${
              hidden > 0 ? `Show ${hidden} earlier` : "Show fewer"}</button>`
          : ""}`
    : `${narrowed}<div class="muted">${site
        ? "Nothing recorded on this site in this window."
        : "Nothing recorded for this application yet."}</div>`;

  const widen = $("#ov-widen");
  if (widen) widen.addEventListener("click", () => selectSite(name, site));

  const more = $("#ov-more");
  if (more) more.addEventListener("click", () => {
    overviewState.showAllInteractions = !overviewState.showAllInteractions;
    redrawApplicationDetail();
  });

  $$("#ov-detail .ov-expand").forEach((button) =>
    button.addEventListener("click", () => {
      const key = button.dataset.key;
      if (overviewState.expanded.has(key)) overviewState.expanded.delete(key);
      else overviewState.expanded.add(key);
      redrawApplicationDetail();
    }));
  bindPageLinks();
  bindCuts("#ov-detail", redrawApplicationDetail);
}

/* A page inside an interaction is itself something the user did, so it can be
   opened in its own right rather than only ever being a line in a list. */
function bindPageLinks(scope = "#ov-detail") {
  $$(`${scope} .ov-page`).forEach((link) =>
    link.addEventListener("click", async (event) => {
      event.preventDefault();
      if (link.dataset.url) await loadPageDetail(link.dataset.url);
    }));
}

async function loadPageDetail(url) {
  const detail = await api.get(`/api/overview/page?url=${encodeURIComponent(url)}`);
  overviewState.page = url;
  $("#ov-detail-title").textContent = "Page detail";
  $("#ov-detail-name").textContent = detail.title || detail.url;
  $("#ov-detail").className = "";
  const back = $("#ov-detail-back");
  back.hidden = !overviewState.application;
  const visits = detail.visits
    .slice(0, VISITS_SHOWN)
    .map((v) => `<tr><td>${clock(v.at)}</td>
      <td>${cut(v.title || "", `v:${v.at}`)}</td>
      <td class="muted">${escapeHtml(v.application || v.browser || "")}</td></tr>`)
    .join("");

  $("#ov-detail").innerHTML = `
    <div class="muted page-url">${cut(detail.url, `u:${detail.url}`)}</div>
    <div class="muted">${detail.visit_count} visit${detail.visit_count === 1 ? "" : "s"}${
      detail.applications.length
        ? ` · ${detail.applications.map((a) => escapeHtml(a.name)).join(", ")}` : ""}</div>
    ${detail.visits.length
      ? `<table><thead><tr><th>At</th><th>Title</th><th>In</th></tr></thead>
         <tbody>${visits}</tbody></table>${
           detail.visits.length > VISITS_SHOWN
             ? `<div class="muted">showing the most recent ${VISITS_SHOWN} of ${
                 detail.visits.length}</div>` : ""}`
      : '<div class="muted">no visits recorded</div>'}`;
  bindCuts("#ov-detail", () => loadPageDetail(url));
}

/* A time of day, which is what these logs are read by. */
/* HOW YOU WORK: each kind's principles, most recently active first, each
   opening to its patterns - with when each was last seen in your work. One
   not seen for a month says so: it may be a way you no longer work. */
const OV_QUIET_DAYS = 30;


/* HOW YOU WORK, DRAWN WITH THE TASKS' OWN PICTURE: the same time line - a
   day as wide as theirs, the same dates along the foot - and for each
   principle the same row: its colour, a segment for each stretch it was
   seen in your work with the gaps left empty, a disc with its emblem where
   it was last active, its words beside the disc and the line under them.
   Principles only, most recently active at the top. One not seen for a
   month is drawn quiet, as a task left alone is, and says so. */
function renderPrinciples(tree) {
  const host = $("#ov-principles");
  if (!host) return;
  const at = (moment) => new Date(moment).getTime();
  const DAY = 86400000;
  const now = Date.now();
  // ACTIVE IN THE LAST SO MANY DAYS, as the tasks are chosen: only the
  // principles seen inside the window, on a time line of the window - a
  // week drawn as a week, a stretch from before it cut at its start.
  const days = ovRecentDays();
  const since = days ? now - days * DAY : null;
  const every = ((tree || {}).kinds || []).filter((one) => one.kind)
    .flatMap((one) => (one.principles || []).map((pr) => ({...pr, kind: one.kind})))
    .filter((pr) => (pr.stretches || []).length || pr.last_active);
  const rows = every
    .filter((pr) => !since || at(pr.last_active) >= since)
    .map((pr) => (!since ? pr : {...pr, stretches: (pr.stretches || [])
      .filter((pair) => at(pair[1] || pair[0]) >= since)
      .map((pair) => [new Date(Math.max(at(pair[0]), since)).toISOString(),
                      pair[1] || pair[0]])}))
    .sort((a, b) => String(b.last_active || "").localeCompare(String(a.last_active || "")));
  const bar = ovRecentBar();
  if (!every.length) {
    host.innerHTML = `<p class="muted">No principles yet: they are grouped
      from what your projects teach once you learn them in Work.</p>`;
    return;
  }
  if (!rows.length) {
    host.innerHTML = `${bar}<p class="muted">No principle was active in the last
      ${days === 1 ? "day" : `${days} days`}.</p>`;
    return;
  }
  const starts = rows.flatMap((pr) => (pr.stretches || []).map((pair) => at(pair[0])))
    .filter(Number.isFinite);
  const first = since || Math.min(...starts, now - DAY);
  const last = now;
  const SB_DAY_WIDE = 26;
  const width = Math.max(SB_WIDTH, Math.ceil((last - first) / DAY) * SB_DAY_WIDE);
  const left = 8;
  const right = width - 8;
  const across = (moment) => {
    const here = at(moment);
    if (!Number.isFinite(here)) return left;
    return left + ((here - first) / Math.max(1, last - first)) * (right - left - 12);
  };
  const step = 54;
  const height = rows.length * step + 44;
  const sizeOf = (pr) => Math.max(7, Math.min(17, 6 + Math.sqrt(Number(pr.support || 1)) * 2.2));
  const quiet = (pr) => pr.last_active && (now - at(pr.last_active)) / DAY > OV_QUIET_DAYS;
  const asideOf = (pr) => `${pr.kind === "work" ? "in your work" : "who you are"} · ${
    ovSaid(pr.last_active)}`;
  const wide = Math.max(width, ...rows.map((pr) => across(pr.last_active || last)
    + sizeOf(pr) + 26 + Math.max(...sbWrapName(pr.statement || "").map((line) =>
      sbTextWide(line)), sbTextWide(asideOf(pr), 5.6))));
  const drawn = rows.map((pr, index) => {
    const y = 26 + index * step;
    // Its own colour, whichever rows the window leaves showing.
    const colour = sbColour(sbStable(pr.id || pr.statement), true);
    const size = sizeOf(pr);
    const cx = across(pr.last_active || last);
    const stretches = pr.stretches || [];
    const line = (began, ended, extra) => {
      const x1 = across(began);
      const x2 = Math.max(x1 + 2, across(ended || began));
      return `<line x1="${x1.toFixed(1)}" y1="0" x2="${x2.toFixed(1)}" y2="0"
        class="sb-tt-span${extra}" stroke="${colour}"/>`;
    };
    const spans = stretches.length > 1
      ? line(stretches[0][0], stretches[stretches.length - 1][1], " sb-tt-span-gap")
        + stretches.map((pair) => line(pair[0], pair[1], "")).join("")
      : stretches.map((pair) => line(pair[0], pair[1], "")).join("");
    const title = pr.statement || "(not yet named)";
    return `<g class="sb-tt-row sb-tt-node ov-pr-row${quiet(pr) ? " sb-tt-quiet" : ""}${
        ovState.principle === pr.id ? " sb-tt-open" : ""}"
        data-ov-principle="${escapeHtml(pr.id)}"
        style="transform:translateY(${y}px)" tabindex="0" role="button">
      ${spans}
      <circle cx="${cx.toFixed(1)}" cy="0" r="${size.toFixed(1)}" fill="${colour}"
        stroke="${colour}" stroke-width="2" class="sb-tt-disc"/>
      <g transform="translate(${cx.toFixed(1)} 0)" class="sb-tt-emblem">${
        sbEmblem(String(pr.id || ""), colour, size)}</g>
      <g class="sb-tt-label">${sbWrapName(title).map((said, n) =>
        `<text x="${(cx + size + 9).toFixed(1)}" y="${1 + n * 13}" fill="${colour}"
           class="sb-tt-name ov-pr-name">${escapeHtml(said)}</text>`).join("")}</g>
      <text x="${(cx + size + 9).toFixed(1)}" y="${1 + sbWrapName(title).length * 13}"
        class="sb-tt-aside ov-pr-aside">${escapeHtml(asideOf(pr))}</text>
      <title>${escapeHtml(`${title} - ${stretches.length} stretch${
        stretches.length === 1 ? "" : "es"} seen in your work, ${ovSaid(pr.last_active)}`)}</title>
    </g>`;
  }).join("");
  // A DATE EVERY SO MANY PIXELS along the foot, as the tasks' picture has.
  const from = left;
  const to = right - 20;
  const EVERY = 140;
  const marks = [];
  for (let x = from; x <= to + 1; x += EVERY) marks.push(Math.min(x, to));
  if (marks[marks.length - 1] < to - EVERY / 2) marks.push(to);
  const foot = marks.map((x, n) => {
    const share = (to > from) ? (x - from) / (to - from) : 0;
    const when = new Date(first + share * (last - first));
    return `<g class="sb-tt-mark">
      <line x1="${x.toFixed(1)}" y1="-4" x2="${x.toFixed(1)}" y2="0" class="sb-tt-axis"/>
      <text x="${x.toFixed(1)}" y="15" class="sb-tt-when" text-anchor="${n === 0
        ? "start" : n === marks.length - 1 ? "end" : "middle"}">${
        escapeHtml(sbWhenShort(when, new Date(last)))}</text></g>`;
  }).join("");
  // WHERE THE READER LEFT IT stays where they left it as the overview
  // refreshes; the first time, the most recent end is in view, as it is
  // for the tasks.
  const held = host.querySelector(".ov-pr-frame");
  const place = held && held.dataset.placed
    ? {left: held.scrollLeft, top: held.scrollTop} : null;
  ovState.tree = tree;
  ovState.rows = rows;
  host.innerHTML = `${bar}<div class="sb-tree-frame ov-pr-frame">
    <svg viewBox="0 0 ${wide} ${height}" style="width:${wide.toFixed(0)}px;height:${
      height}px" class="ov-pr-graph" preserveAspectRatio="xMinYMin meet"
      role="img" aria-label="your principles, and when each was seen in your work">
      ${drawn}
      <g class="sb-tt-foot" style="transform:translateY(${height - 20}px)">
        <line x1="${left}" y1="0" x2="${to}" y2="0" class="sb-tt-axis"/>${foot}</g>
    </svg></div>
    <p class="muted sb-figure-note">A circle is a principle, placed where it was
      last active; the line through it is each stretch of time its natures were
      seen in your work. Faint: not seen for a month - you may have changed.
      Drag to move along it; click a principle to read it below.</p>
    <div class="sb-task-card ov-principle-card" id="ov-principle-card"></div>`;
  const frame = host.querySelector(".ov-pr-frame");
  if (place) {
    frame.scrollLeft = place.left;
    frame.scrollTop = place.top;
    frame.dataset.placed = "1";
  } else {
    frame.scrollLeft = frame.scrollWidth;
  }
  if (ovState.principle) ovShowPrinciple(ovState.principle);
}

const ovState = { principle: null, tree: null, rows: [] };

/* The window the principles are drawn for - the tasks' choices, and all of
   them; remembered in this browser. 30 days to start: a principle not seen
   in a month is the one that may no longer hold. */
const OV_RECENT_DAYS = [1, 7, 15, 30, 180, 0];

function ovRecentDays() {
  if (ovState.recentDays === undefined) {
    let kept = null;
    try { kept = localStorage.getItem("ov-principles-days"); } catch (_err) { kept = null; }
    ovState.recentDays = kept !== null && OV_RECENT_DAYS.includes(Number(kept))
      ? Number(kept) : 30;
  }
  return ovState.recentDays;
}

function ovRecentBar() {
  const which = ovRecentDays();
  return `<span class="sb-sort-bar sb-recent-bar ov-recent-bar"><span class="muted">active in
    the last</span>
    ${OV_RECENT_DAYS.map((days) => `<button type="button" class="small${
      which === days ? "" : " secondary"} sb-sort" data-ov-recent="${days}"
      title="${days ? `Only principles seen in the last ${days} day${days === 1 ? "" : "s"}`
        : "Every principle"}">${days === 0 ? "all" : days === 1 ? "1 day"
        : `${days} days`}</button>`).join("")}</span>`;
}

document.addEventListener("click", (event) => {
  const at = event.target.closest && event.target.closest("[data-ov-recent]");
  if (!at) return;
  ovState.recentDays = Number(at.dataset.ovRecent);
  try { localStorage.setItem("ov-principles-days", String(ovState.recentDays)); }
  catch (_err) { /* remembered for this visit only */ }
  // Drawn again for the new window, from the start of it.
  const frame = $("#ov-principles .ov-pr-frame");
  if (frame) delete frame.dataset.placed;
  if (ovState.tree) renderPrinciples(ovState.tree);
});

/* WHAT A PRINCIPLE OR PATTERN WAS BEFORE: each earlier wording, when, how
   many it was worded from, and why it changed - reworded when a good part
   of what it holds changed, or split when it had become two things. */
function ovHistoryFold(history, what) {
  const rows = [...(history || [])].reverse();
  const day = (value) => escapeHtml(localStamp(value));
  return `<details class="ov-history"><summary>History${rows.length
      ? ` (${rows.length})` : ""}</summary>${rows.length
    ? `<ol class="sb-history-list">${rows.map((one) => `<li>
        <strong>${escapeHtml(one.statement || "(not yet worded)")}</strong>
        <span class="muted"> &middot; ${day(one.at)}${one.members
          ? ` &middot; from ${Number(one.members)}` : ""}${one.why
          ? ` &middot; ${escapeHtml(one.why)}` : ""}${one.split_from
          ? ` &middot; split from ${escapeHtml(String(one.split_from))}` : ""}</span>
        ${one.detail ? `<div class="muted sb-history-said">${escapeHtml(
          one.detail)}</div>` : ""}</li>`).join("")}</ol>`
    : `<p class="muted">No earlier versions: this ${what} has had only the
        words it has now.</p>`}</details>`;
}

/* A PRINCIPLE, OPENED under the picture as a task is: its words and what it
   means, when it was last active and each stretch it was seen, and its
   patterns - each with when it was last active, and the natures in it. */
function ovShowPrinciple(id) {
  const box = $("#ov-principle-card");
  if (!box) return;
  const pr = (ovState.rows || []).find((one) => one.id === id);
  if (!pr) { box.innerHTML = ""; return; }
  ovState.principle = id;
  $$("#ov-principles [data-ov-principle]").forEach((row) =>
    row.classList.toggle("sb-tt-open", row.dataset.ovPrinciple === id));
  const day = (value) => localStamp(value, "date");
  box.innerHTML = `<h3>${escapeHtml(pr.statement || "(not yet named)")}</h3>
    <p class="muted">${pr.kind === "work" ? "In your work" : "Who you are"} · ${
      escapeHtml(ovSaid(pr.last_active))} · ${Number(pr.support || 0)} records</p>
    ${pr.detail ? `<p>${escapeHtml(pr.detail)}</p>` : ""}
    ${ovHistoryFold(pr.history, "principle")}
    ${(pr.stretches || []).length ? `<p><strong>When it was seen:</strong> ${
      pr.stretches.map((pair) => escapeHtml(day(pair[0]) === day(pair[1])
        ? day(pair[0]) : `${day(pair[0])} to ${day(pair[1])}`)).join(" · ")}</p>` : ""}
    <p><strong>Its patterns (${(pr.patterns || []).length}):</strong></p>
    <ul class="xp-work-list">${[...(pr.patterns || [])].sort((a, b) =>
      String(b.last_active || "").localeCompare(String(a.last_active || "")))
      .map((p) => `<li><details data-ov-pattern="${escapeHtml(p.id || "")}"${
        ovNatureState.patterns.has(p.id) ? " open" : ""}><summary>${escapeHtml(
        p.statement || "(not yet named)")}
        <span class="muted">· ${escapeHtml(ovSaid(p.last_active))}</span></summary>
        ${p.detail ? `<p class="muted">${escapeHtml(p.detail)}</p>` : ""}
        ${ovHistoryFold(p.history, "pattern")}
        <ul>${(p.members || []).map((n) => `<li><span class="xp-nature-open"
          data-ov-nature="${escapeHtml(n.id || "")}" role="button" tabindex="0"
          title="Click for all its examples">${escapeHtml(n.title || "")}</span>${
          /* How many real cases it was seen in: a trait seen again is one
             more example of it, not another row. */
          Number(n.examples) > 0 ? ` <span class="muted xp-nx-count">· ${Number(n.examples)
          } example${Number(n.examples) === 1 ? "" : "s"}</span>` : ""}
          <div class="xp-nature-detail" data-xp-nature-detail="${escapeHtml(n.id || "")}"
            hidden></div></li>`).join("")}</ul>
      </details></li>`).join("")}</ul>`;
  // What was open before the overview refreshed is open again - from what
  // was read then, not asked for again every fifteen seconds.
  ovNatureState.open.forEach((html, nature) => {
    const detail = box.querySelector(`[data-xp-nature-detail="${CSS.escape(nature)}"]`);
    if (!detail) return;
    detail.hidden = false;
    detail.innerHTML = html;
  });
}

/* A NATURE IN A PRINCIPLE'S PATTERNS, CLICKED: opened below it as it is in
   Experience - all its examples, its history - and kept open, with the
   patterns that were open, as the overview refreshes. */
const ovNatureState = { patterns: new Set(), open: new Map() };

document.addEventListener("toggle", (event) => {
  const at = event.target;
  if (!at || !at.matches || !at.matches("#ov-principle-card details[data-ov-pattern]")) return;
  if (at.open) ovNatureState.patterns.add(at.dataset.ovPattern);
  else ovNatureState.patterns.delete(at.dataset.ovPattern);
}, true);

async function ovOpenNature(at) {
  const id = at.dataset.ovNature;
  await xpOpenNature(id, at);
  const detail = at.parentElement.querySelector(`[data-xp-nature-detail="${CSS.escape(id)}"]`);
  if (detail && !detail.hidden) ovNatureState.open.set(id, detail.innerHTML);
  else ovNatureState.open.delete(id);
}

document.addEventListener("click", (event) => {
  const at = event.target.closest && event.target.closest("#ov-principle-card [data-ov-nature]");
  if (!at) return;
  event.preventDefault();
  ovOpenNature(at);
});

document.addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  const at = event.target.closest && event.target.closest("#ov-principle-card [data-ov-nature]");
  if (!at) return;
  event.preventDefault();
  ovOpenNature(at);
});

document.addEventListener("click", (event) => {
  const row = event.target.closest && event.target.closest("[data-ov-principle]");
  if (!row) return;
  const id = row.dataset.ovPrinciple;
  if (ovState.principle === id) {
    ovState.principle = null;
    $("#ov-principle-card").innerHTML = "";
    row.classList.remove("sb-tt-open");
    return;
  }
  ovShowPrinciple(id);
});

/* DRAGGED, IT MOVES like the tasks' picture: a hand on a map, both ways. */
(() => {
  let held = null;
  document.addEventListener("pointerdown", (event) => {
    const svg = event.target.closest && event.target.closest(".ov-pr-graph");
    if (!svg || event.button !== 0 || event.target.closest("[data-ov-principle]")) return;
    const frame = svg.closest(".ov-pr-frame");
    event.preventDefault();
    held = {x: event.clientX, y: event.clientY, frame,
            left: frame.scrollLeft, top: frame.scrollTop};
    frame.classList.add("sb-frame-held");
  });
  document.addEventListener("pointermove", (event) => {
    if (!held) return;
    held.frame.scrollLeft = held.left - (event.clientX - held.x);
    held.frame.scrollTop = held.top - (event.clientY - held.y);
    held.frame.dataset.placed = "1";
  });
  document.addEventListener("pointerup", () => {
    if (held) held.frame.classList.remove("sb-frame-held");
    held = null;
  });
})();

/* When it was last seen, said the way a task's quiet line says it. */
function ovSaid(value) {
  if (!value) return "not seen yet";
  const days = Math.floor((Date.now() - Date.parse(value)) / 86400000);
  const when = localStamp(value, "date");
  if (!Number.isFinite(days)) return `last active ${when}`;
  const ago = days <= 0 ? "today" : days === 1 ? "yesterday" : `${days} days ago`;
  return days > OV_QUIET_DAYS
    ? `last active ${when} (${ago}) - not seen since; you may have changed`
    : `last active ${when} (${ago})`;
}

function clock(value) {
  if (!value) return "—";
  const when = new Date(value);
  if (Number.isNaN(when.getTime())) return String(value).slice(11, 16) || "—";
  const today = when.toDateString() === new Date().toDateString();
  const time = when.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  return today ? time : `${when.toLocaleDateString(undefined,
    { month: "short", day: "numeric" })} ${time}`;
}
function startOfDay(date) {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

/* -------------------------------------------------------------- calendar
   Section 10, as amended. The calendar is a dated grid drawn from the date,
   not from the data: an empty month still shows its days.
*/
const calendarState = {
  //: The task whose detail is open, if any.
  openTask: null,
  //: Days whose chips are all showing. A month cell holds about three before
  //  the grid stops looking like a month, and the rest were simply counted -
  //  "+13 more" with no way to reach the thirteen. A day with sixteen things
  //  on it is exactly the day worth opening.
  expandedDays: new Set(),
  anchor: startOfDay(new Date()),   // any date inside the displayed period
  selected: startOfDay(new Date()),
  tasks: [],
  //: THE VIEW: the month, or one day hour by hour - as the user left it.
  view: (() => {
    try { return localStorage.getItem("calendar-view") === "day" ? "day" : "month"; }
    catch (err) { return "month"; }
  })(),
};

const WEEKDAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const DAY_MS = 86400000;

function sameDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
    && a.getDate() === b.getDate();
}

/* Monday-first week containing the given date. */
function startOfWeek(date) {
  const start = startOfDay(date);
  const weekday = (start.getDay() + 6) % 7;
  start.setDate(start.getDate() - weekday);
  return start;
}

/* THE PERIOD SHOWN: a month - each day with what falls on it - or one
   day, hour by hour, where an event is put at its time by clicking it. */
function periodBounds() {
  if (calendarState.view === "day") {
    const from = startOfDay(calendarState.selected);
    return { from, to: new Date(from.getTime() + DAY_MS), monthStart: from };
  }
  const monthStart = new Date(calendarState.anchor.getFullYear(),
                              calendarState.anchor.getMonth(), 1);
  const from = startOfWeek(monthStart);
  const to = new Date(from.getTime() + 42 * DAY_MS);
  return { from, to, monthStart };
}

function periodLabel() {
  if (calendarState.view === "day") {
    return calendarState.selected.toLocaleDateString(undefined,
      { weekday: "long", year: "numeric", month: "long", day: "numeric" });
  }
  return calendarState.anchor.toLocaleDateString(undefined,
    { month: "long", year: "numeric" });
}

async function loadCalendar() {
  const { from, to } = periodBounds();
  // Section 34.1, as amended: states are internal and are not drawn here.
  // Every task writes one, so the calendar would show each of them twice -
  // once as the task and once as a span saying the task is going to happen -
  // and the rest are the agent's inferences about the user, which belong in
  // the Debugger rather than in the user's own diary.
  // Fetch a little either side so tasks near the edges still appear.
  const data = await api.get(
    `/api/tasks?limit=500&expand=1&start=${encodeURIComponent(new Date(from.getTime() - DAY_MS).toISOString())}`
    + `&end=${encodeURIComponent(new Date(to.getTime() + DAY_MS).toISOString())}`);
  calendarState.tasks = data.tasks || [];
  renderCalendar();
}

/* Section 10, as amended: a detail opens beside the thing it is about.

   A card centred on the screen makes the reader find their place again
   afterwards: it covers the grid, it points at nothing, and when it closes the
   eye has to search for the event it was about. Opening beside the event keeps
   the answer next to the question - the grid stays visible around it, and what
   was clicked is still where it was.
*/
const POPOVER_GAP = 8;

function openPopover(anchor, inner, onClose) {
  const host = $("#event-detail");
  host.innerHTML = `<div class="event-card" role="dialog">${inner}</div>`;
  host.hidden = false;
  const card = host.firstElementChild;

  const close = () => {
    host.hidden = true;
    host.innerHTML = "";
    document.removeEventListener("keydown", onKey, true);
    window.removeEventListener("resize", place);
    if (onClose) onClose();
  };
  const onKey = (event) => {
    // Escape closes what Escape is expected to close, and does not reach the
    // page underneath.
    if (event.key === "Escape") {
      event.stopPropagation();
      close();
    }
  };

  function place() {
    if (!anchor || !anchor.getBoundingClientRect) return;
    const at = anchor.getBoundingClientRect();
    const box = card.getBoundingClientRect();
    // Beside it if there is room, otherwise on the other side: a card that
    // runs off the screen is worse than one on the unexpected side.
    let left = at.right + POPOVER_GAP;
    if (left + box.width > window.innerWidth - POPOVER_GAP) {
      left = at.left - box.width - POPOVER_GAP;
    }
    if (left < POPOVER_GAP) {
      // Narrow window: centre it horizontally rather than clipping it.
      left = Math.max(POPOVER_GAP,
                      (window.innerWidth - box.width) / 2);
    }
    // Aligned with the event's top, pulled up only as far as it must be to
    // stay on screen, so it still reads as belonging to that row.
    let top = at.top;
    if (top + box.height > window.innerHeight - POPOVER_GAP) {
      top = window.innerHeight - box.height - POPOVER_GAP;
    }
    card.style.left = `${Math.round(Math.max(POPOVER_GAP, left))}px`;
    card.style.top = `${Math.round(Math.max(POPOVER_GAP, top))}px`;
  }

  place();
  host.addEventListener("click", (event) => {
    if (event.target === host) close();          // the backdrop, not the card
  });
  document.addEventListener("keydown", onKey, true);
  window.addEventListener("resize", place);
  return { close, card };
}

function stateChip(state) {
  const whose = state.about === "agent" ? "agent" : "user";
  // Section 34.1, as amended: a state is a thing on the calendar, so it opens
  // like the other things on the calendar. Being told the working day is on
  // Madrid time, with no way to ask who decided that or when it applies, is worse
  // than not being told.
  // No horizon on the chip or in its tooltip. "short term" beside a period
  // is the period again in a word, and the word was what the eye went to.
  return `<button type="button" class="cal-state ${escapeHtml(whose)}"
    data-state="${escapeHtml(state.id)}"
    title="${escapeHtml(state.title)} · from ${escapeHtml(state.source || "")}">
    <span class="cal-state-mark">${state.about === "agent" ? "◆" : "●"}</span>
    ${escapeHtml(state.title)}</button>`;
}

/* Where a state came from, said in a sentence rather than a field value. The
   difference between something the user decided and something the agent
   inferred from watching them is the whole reason the source is recorded. */
const STATE_ORIGIN = {
  user: "You told the agent this.",
  agent: "The agent inferred this from your activity. It was not told.",
  task: "This accompanies a task the agent scheduled.",
};

/* Section 34.1, as amended: what the agent inferred this from.

   The agent is describing the user's own situation back to them, and it can
   be wrong about it. A claim with no evidence is one the user cannot argue
   with - they can only accept it or delete it, and neither teaches the agent
   anything. */
/* What the state rests on: the files, the pages, the windows.

   Kept apart from the evidence, which is the argument for believing the
   state. These are the things themselves, written out in full - the whole
   URL, the whole path - because a reader who disagrees with a state needs
   what it was built from rather than a description of what it was built
   from, and "a browser tab" is not something anybody can go and look at. */
function stateSources(state) {
  const sources = (state.metadata || {}).sources || [];
  if (!sources.length) return "";
  return `<details class="state-trace" open>
    <summary class="muted">What it was built from</summary>
    <ul class="trace-evidence">${sources.map((item) =>
      `<li><code class="state-source">${escapeHtml(String(item))}</code></li>`)
      .join("")}</ul>
  </details>`;
}

function inferenceTrace(state) {
  const meta = state.metadata || {};
  const evidence = meta.evidence || [];
  const reasoning = meta.reasoning || "";
  if (!evidence.length && !reasoning) {
    if (state.source !== "agent") return "";
    return `<div class="event-row"><span class="event-label">Evidence</span>
      <span class="missing">None was recorded, so there is no way to check this.</span></div>`;
  }
  return `<details class="state-trace" open>
    <summary class="muted">Why the agent believes this</summary>
    ${reasoning ? `<div class="trace-reasoning">${escapeHtml(reasoning)}</div>` : ""}
    ${evidence.length
      ? `<ul class="trace-evidence">${evidence
          .map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`
      : ""}
  </details>`;
}

/* The window the heartbeat was looking at when it wrote this state.

   Every state carries it and none of them was asked for it: it is a fact
   about the run rather than a reading of anything, so the script that
   wrote the state stamped it. Says the events as well as the clock,
   because a quarter of an hour with two events in it and one with three
   hundred are not the same evidence. */
function stateReadFrom(state) {
  // Off the state as stored, or off the report's own account of what was
  // written - the same fact, reached by two different readers.
  const seen = (state.metadata || {}).looked_at || state.looked_at;
  if (!seen || typeof seen !== "object") return "";
  const at = (value) => {
    const when = value ? new Date(value) : null;
    return when && !Number.isNaN(when.getTime()) ? when.toLocaleTimeString() : "";
  };
  const first = at(seen.first_event);
  const last = at(seen.last_event);
  const span = first && last ? `${first} to ${last}`
    : `${at(seen.from) || "?"} to ${at(seen.to) || "?"}`;
  const mins = Number(seen.minutes || 0);
  const count = Number(seen.events || 0);
  return `${span}${mins ? ` · ${mins} minute window` : ""}`
    + (count ? ` · ${count} events` : " · nothing recorded in it");
}

function openDebuggerState(state, anchor) {
  if (!state) return;
  const from = state.starts_at ? new Date(state.starts_at) : null;
  const to = state.ends_at ? new Date(state.ends_at) : null;
  const row = (label, value) => value
    ? `<div class="event-row"><span class="event-label">${escapeHtml(label)}</span>
       <span>${escapeHtml(String(value))}</span></div>` : "";
  const opened = openPopover(anchor, `
      <div class="event-head">
        <span class="badge ${state.about === "agent" ? "" : "ok"}">${
          state.about === "agent" ? "the agent intends" : "the user"}</span>
        <h3>${escapeHtml(state.title)}</h3>
        <button type="button" class="small secondary" id="event-close">Close</button>
      </div>
      ${row("From", from ? from.toLocaleString() : "no start recorded")}
      ${row("Until", to ? to.toLocaleString() : "no end recorded")}
      ${row("Lasts", state.span_hours ? `${state.span_hours} hours` : "")}
      ${/* How much of the window went to this one. The period says when
            the state runs; this says how much of it the user actually
            spent here, which is a different question and the one somebody
            looking at four states at once is asking. */ ""}
      ${row("Time spent", (state.metadata || {}).minutes
        ? `${(state.metadata || {}).minutes} minutes of the window` : "")}
      ${/* The stretch the review that wrote this actually looked at.

            Not the state's own period, which is when the situation ran:
            this is how much evidence there was to read it from. "40
            minutes" written out of a fifteen-minute window and the same
            forty written out of a four-hour one are different claims, and
            the state alone cannot tell them apart. Put here by the
            heartbeat, not by the model. */ ""}
      ${row("Read from", stateReadFrom(state))}
      ${row("Status", state.status)}
      ${/* When the agent wrote this down, which is not when the situation
            it describes began. A state written this morning about a
            fortnight of work has both, and telling them apart is how a
            reader knows whether the agent has been watching this for two
            weeks or decided it an hour ago. The task card and the record
            page have said it all along; the state card did not. */ ""}
      ${row("Added", state.created_at
        ? new Date(state.created_at).toLocaleString() : "")}
      ${row("Extended", state.extensions ? `${state.extensions} times` : "")}
      <div class="event-detail-body">
        <div class="muted">Detail</div>
        ${state.detail
          ? `<div class="event-body">${escapeHtml(state.detail)}</div>`
          : `<div class="event-body missing">No detail was written for this state.</div>`}
      </div>
      <div class="event-row"><span class="event-label">Where from</span>
        <span>${escapeHtml(STATE_ORIGIN[state.source] || state.source || "")}</span></div>
      ${stateSources(state)}
      ${inferenceTrace(state)}
      <div class="muted event-note">A state is shown, never run. The scheduler
        is what makes things happen.</div>`);
  $("#event-close").addEventListener("click", opened.close);
}

function tasksOn(date) {
  return calendarState.tasks
    .filter((task) => {
      const when = new Date(task.scheduled_at);
      return !Number.isNaN(when.getTime()) && sameDay(when, date);
    })
    .sort((a, b) => new Date(a.scheduled_at) - new Date(b.scheduled_at));
}

function taskChip(task, options = {}) {
  const when = new Date(task.scheduled_at);
  const time = when.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  // In a time grid the row already says when, so repeating it inside the chip
  // spends the width that the name needs - which is how a title becomes an
  // ellipsis and the chip stops saying anything at all.
  const showTime = options.showTime !== false;
  // Section 52.2: which of these will interrupt has to be visible without
  // opening each one, or the calendar cannot be read for the thing the user
  // most wants to know about it.
  const notifies = taskNotifies(task);
  const bell = notifies
    ? `<span class="cal-chip-bell" aria-label="notifies you">●</span>` : "";
  // A later run of a repeating task is drawn from the rule, not stored. It is
  // shown lighter so the calendar does not claim more than it knows.
  const projected = Boolean(task.occurrence_of)
    && task.occurrence_index !== task.runs;
  return `<button type="button" class="cal-chip status-${escapeHtml(task.status)}${
    notifies ? " notifies" : ""}${projected ? " projected" : ""}"
    data-task="${escapeHtml(task.id)}" title="${escapeHtml(task.title)} · ${
    escapeHtml(time)} · ${escapeHtml(task.execution_type)} · ${
    escapeHtml(statusLabel(task.status))} · ${
    task.status === "closed" || task.status === "cancelled"
      ? `${escapeHtml(task.status)}: ${escapeHtml(String(
          (task.metadata || {})[`${task.status}_reason`] || "no reason recorded"))}`
      : notifies ? "interrupts you" : "stays on the calendar"}">
    ${showTime ? `<span class="cal-chip-time">${escapeHtml(time)}</span>` : ""}
    ${bell}<span class="cal-chip-title">${escapeHtml(task.title)}</span>${
    task.status === "disabled"
      ? `<span class="cal-chip-off">disabled by user</span>` : ""}</button>`;
}

function renderCalendar() {
  $("#cal-period").textContent = periodLabel();
  $$("[data-cal-view]").forEach((button) => button.classList.toggle(
    "active", button.dataset.calView === calendarState.view));
  if (calendarState.view === "day") renderDayView();
  else renderMonth();
  renderDayPanel();
  // A time of the day clicked: an event at it.
  $$("#calendar-surface [data-cal-slot]").forEach((slot) =>
    slot.addEventListener("click", (event) => {
      if (event.target.closest(".cal-chip")) return;
      openAddEvent(new Date(Number(slot.dataset.calSlot)), slot);
    }));
  $$("#calendar-surface .cal-chip").forEach((chip) =>
    chip.addEventListener("click", (event) => {
      event.stopPropagation();
      openTask(chip.dataset.task, chip);
    }));
  // Opening a day is not selecting it, and it is not opening a task either,
  // so it stops the event before either of those sees it.
  $$("#calendar-surface [data-expand-day]").forEach((button) =>
    button.addEventListener("click", (event) => {
      event.stopPropagation();
      const key = button.dataset.expandDay;
      if (calendarState.expandedDays.has(key)) calendarState.expandedDays.delete(key);
      else calendarState.expandedDays.add(key);
      renderCalendar();
    }));
  $$("#calendar-surface .cal-day").forEach((cell) => {
    cell.addEventListener("click", (event) => {
      if (event.target.closest("[data-expand-day]")) return;
      selectDay(new Date(Number(cell.dataset.date)));
    });
    // A day of the month opened: that day, hour by hour.
    cell.addEventListener("dblclick", (event) => {
      if (event.target.closest(".cal-chip, [data-expand-day]")) return;
      calendarState.selected = startOfDay(new Date(Number(cell.dataset.date)));
      setCalendarView("day");
    });
  });
}

/* ONE DAY, HOUR BY HOUR - as a calendar's day view is: a row each half
   hour, each event a block at its time as long as it lasts, the ones at
   the same time side by side; clicking a time puts an event there. */
const CAL_ROW_PX = 22;
//: How long an event is drawn when it says nothing of how long it lasts.
const CAL_DEFAULT_MINUTES = 30;

function eventMinutes(task) {
  const said = Number((task.task_payload || {}).duration_minutes);
  return Number.isFinite(said) && said > 0 ? said : CAL_DEFAULT_MINUTES;
}

function renderDayView() {
  const day = startOfDay(calendarState.selected);
  const rows = [];
  for (let slot = 0; slot < 48; slot += 1) {
    const at = new Date(day.getTime() + slot * 30 * 60000);
    const hour = slot % 2 === 0;
    rows.push(`<div class="cal-slot${hour ? " hour" : ""}" data-cal-slot="${at.getTime()}"
      title="Add an event at ${escapeHtml(at.toLocaleTimeString(undefined,
        { hour: "2-digit", minute: "2-digit" }))}">${hour ? `<span class="cal-slot-time">${
        escapeHtml(at.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" }))
        }</span>` : ""}</div>`);
  }
  // Side by side where they overlap: each in the first lane free at its start.
  const items = tasksOn(day).map((task) => {
    const start = new Date(task.scheduled_at);
    const from = (start - day) / 60000;
    return { task, from, to: from + eventMinutes(task) };
  });
  const laneEnds = [];
  items.forEach((item) => {
    let lane = laneEnds.findIndex((end) => end <= item.from);
    if (lane < 0) { lane = laneEnds.length; laneEnds.push(0); }
    laneEnds[lane] = item.to;
    item.lane = lane;
  });
  const lanes = Math.max(1, laneEnds.length);
  const blocks = items.map((item) => `<div class="cal-event" style="top:${
    (item.from / 30) * CAL_ROW_PX}px;height:${Math.max(CAL_ROW_PX - 2,
    ((item.to - item.from) / 30) * CAL_ROW_PX - 2)}px;left:calc(${
    (item.lane * 100) / lanes}% + 2px);width:calc(${100 / lanes}% - 4px)">${
    taskChip(item.task)}</div>`).join("");
  const now = new Date();
  const line = sameDay(now, day) ? `<div class="cal-now" style="top:${
    ((now - day) / 60000 / 30) * CAL_ROW_PX}px" aria-hidden="true"></div>` : "";
  $("#calendar-surface").innerHTML = `
    <div class="cal-dayview" id="cal-dayview">
      <div class="cal-slots">${rows.join("")}</div>
      <div class="cal-events">${blocks}${line}</div>
    </div>`;
  // Opened at the morning, or at what is on the day - not at midnight.
  const first = items.length ? Math.min(...items.map((item) => item.from)) : 7 * 60;
  $("#cal-dayview").scrollTop = Math.max(0, (Math.min(first, 7 * 60) / 30) * CAL_ROW_PX - 8);
}

function setCalendarView(view) {
  calendarState.view = view === "day" ? "day" : "month";
  try { localStorage.setItem("calendar-view", calendarState.view); } catch (err) { /* this page only */ }
  if (calendarState.view === "month") calendarState.anchor = startOfDay(calendarState.selected);
  loadCalendar();
}

/* ADD AN EVENT: its title, when, how long, notes - and whether it
   reminds you - beside where it was asked for. */
const CAL_DURATIONS = [15, 30, 45, 60, 90, 120, 180, 240];

function openAddEvent(at, anchor) {
  const pad = (n) => String(n).padStart(2, "0");
  const date = `${at.getFullYear()}-${pad(at.getMonth() + 1)}-${pad(at.getDate())}`;
  const time = `${pad(at.getHours())}:${pad(at.getMinutes())}`;
  const popover = openPopover(anchor, `
    <form class="event-edit cal-add-form">
      <h4>New event</h4>
      <label>Title<input name="title" required autocomplete="off"></label>
      <div class="cal-add-when">
        <label>Day<input name="day" type="date" value="${date}" required></label>
        <label>Starts<input name="time" type="time" value="${time}" required></label>
        <label>Lasts<select name="minutes">${CAL_DURATIONS.map((m) => `<option value="${m}"${
          m === 60 ? " selected" : ""}>${m < 60 ? `${m} min` : `${m / 60} h`}</option>`).join("")
        }</select></label>
      </div>
      <label>Notes<textarea name="notes" rows="2"></textarea></label>
      <label class="cal-add-notify"><input name="notify" type="checkbox" checked>
        Remind me when it starts</label>
      <div class="ov-lp-buttons"><button type="submit">Add</button>
        <button type="button" class="secondary" data-cal-add-cancel>Cancel</button></div>
    </form>`);
  const form = $("#event-detail .cal-add-form");
  if (!form) return;
  form.elements.title.focus();
  form.querySelector("[data-cal-add-cancel]").addEventListener("click", () => popover.close());
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const starts = new Date(`${form.elements.day.value}T${form.elements.time.value}`);
    if (Number.isNaN(starts.getTime())) { toast("Say when it starts", "error"); return; }
    try {
      await api.post("/api/tasks", {
        title: form.elements.title.value.trim(),
        description: form.elements.notes.value.trim(),
        scheduled_at: starts.toISOString(),
        timezone_name: (Intl.DateTimeFormat().resolvedOptions() || {}).timeZone || "UTC",
        execution_type: "notification",
        notify: form.elements.notify.checked,
        payload: { duration_minutes: Number(form.elements.minutes.value) },
      });
      const title = form.elements.title.value.trim();
      popover.close();
      toast(`${title} added`);
      calendarState.selected = startOfDay(starts);
      await loadCalendar();
    } catch (err) {
      toast(err.message, "error");
    }
  });
}


/* How many chips a month cell shows before it offers to open. */
const MONTH_CHIPS = 3;

function renderMonth() {
  const { from, monthStart } = periodBounds();
  const today = new Date();
  const weeks = [];
  for (let week = 0; week < 6; week += 1) {
    const days = [];
    for (let day = 0; day < 7; day += 1) {
      const date = new Date(from.getTime() + (week * 7 + day) * DAY_MS);
      const outside = date.getMonth() !== monthStart.getMonth();
      const dayTasks = tasksOn(date);
      const key = String(startOfDay(date).getTime());
      const open = calendarState.expandedDays.has(key);
      const shown = open ? dayTasks : dayTasks.slice(0, MONTH_CHIPS);
      const hidden = dayTasks.length - shown.length;
      days.push(`
        <div class="cal-day${outside ? " outside" : ""}${sameDay(date, today) ? " today" : ""}${
          sameDay(date, calendarState.selected) ? " selected" : ""}${
          open ? " expanded" : ""}"
          data-date="${date.getTime()}">
          <div class="cal-date">${date.getDate()}</div>
          <div class="cal-chips">${shown.map(taskChip).join("")}${
            hidden > 0
              ? `<button type="button" class="cal-more" data-expand-day="${key}">
                   +${hidden} more</button>`
              : ""}${
            open && dayTasks.length > MONTH_CHIPS
              ? `<button type="button" class="cal-more" data-expand-day="${key}">
                   show fewer</button>`
              : ""}</div>
        </div>`);
    }
    weeks.push(`<div class="cal-week">${days.join("")}</div>`);
  }
  $("#calendar-surface").innerHTML = `
    <div class="cal-grid month">
      <div class="cal-weekdays">${WEEKDAYS.map((d) => `<div>${d}</div>`).join("")}</div>
      ${weeks.join("")}
    </div>`;
}

function selectDay(date) {
  calendarState.selected = startOfDay(date);
  renderCalendar();
}

function renderDayPanel() {
  const date = calendarState.selected;
  const dayTasks = tasksOn(date);
  $("#cal-day-title").textContent = date.toLocaleDateString(undefined,
    { weekday: "long", year: "numeric", month: "long", day: "numeric" });
  // What is true that day comes before what runs that day: the state is the
  // context, the task is the event.
  $("#cal-day-tasks").innerHTML = (dayTasks.length
    ? `<ul class="cal-day-list">${dayTasks.map((task) => `
        <li>
          <span class="cal-day-time">${new Date(task.scheduled_at).toLocaleTimeString(
            undefined, { hour: "2-digit", minute: "2-digit" })}</span>
          <span class="cal-day-name">${escapeHtml(task.title)}</span>
          <span class="badge ${badgeClass(task.status)}">${escapeHtml(task.status)}</span>
          <span class="muted">${escapeHtml(task.execution_type)}</span>
        </li>`).join("")}</ul>`
    : '<div class="muted">Nothing scheduled on this day.</div>');
}

/* Section 10, as amended: an event opens.

   A chip is small on purpose - it has to fit a slot - so it can only ever
   carry a name and a time. Everything else about the task lives somewhere
   the user has to go and find, unless clicking the thing itself shows it. */
/* Section 52.2, as amended: a task says whether it will interrupt.

   Every scheduled task used to raise a notification when it ran, so a calendar
   of checks the agent had set for itself interrupted for all of them. The flag
   exists per task now, and it is shown here because a setting the user cannot
   see is one they cannot correct.
*/
/* Section 52.3: what "Repeats" says.

   This row used to read task.recurrence, which was never a field on a task -
   so it rendered blank on every real task while looking, in the code, as
   though repeating was supported. It is a field now, and this says it in the
   words a person would use.
*/
const RECUR_UNITS = [["week", 604800], ["day", 86400],
                     ["hour", 3600], ["minute", 60]];

function describeRecurrence(task) {
  const rule = task && task.recurrence;
  if (!rule || !rule.every_seconds) return "";
  const every = Number(rule.every_seconds);
  let interval = `every ${every} seconds`;
  for (const [name, size] of RECUR_UNITS) {
    if (every >= size && every % size === 0) {
      const amount = every / size;
      // Each a whole phrase in the interface's tables: "every {0} weeks".
      interval = amount === 1 ? `every ${name}` : `every ${amount} ${name}s`;
      break;
    }
  }
  // A repeat of days kept on another place's clock says whose.
  if (rule.zone && every % 86400 === 0 && !sameClockAsHere(rule.zone)) {
    interval = `${interval}, on ${rule.zone} time`;
  }
  const done = Number(task.runs || 0);
  if (rule.count) return `${interval}, ${done} of ${rule.count} runs`;
  if (rule.until) {
    return `${interval} until ${new Date(rule.until).toLocaleDateString()}`;
  }
  return done ? `${interval} (${done} so far)` : interval;
}

function taskNotifies(task) {
  // A disabled task tells nobody anything: it does not run.
  if (task && task.status === "disabled") return false;
  return Boolean(task && task.task_payload && task.task_payload.notify_user);
}

/* What a status is called on the calendar. Only the user disables, so a
   disabled task says so. */
function statusLabel(status) {
  return status === "disabled" ? "disabled by user" : String(status || "");
}

function notifyRow(task) {
  const on = taskNotifies(task);
  const off = task.status === "disabled";
  return `<div class="event-row">
      <span class="event-label">When it runs</span>
      <span class="notify-state">
        <span class="badge ${on ? "notify-on" : "notify-off"}">${
          off ? "Does not run - disabled by user"
              : on ? "Interrupts you" : "Stays on the calendar"}</span>
      </span>
    </div>`;
}

/* The reasoning is kept, but it is not the detail.

   It used to be written into the description, which made a five hundred
   character paragraph of evidence the first thing the user read. It is here,
   folded away, for when they want to know why the agent scheduled something.
*/
/* Section 52.7, as amended: nothing on this calendar is there without saying
   why - and the place to read it is here.

   Folded, not open. An earlier version showed the reasoning expanded and it
   pushed everything else out of the card, which is how the detail became
   unreadable; the requirement is that the reason is *recorded and reachable*,
   not that it is the first thing in the way.

   A user's own entry is the exception in the other direction. "added by user"
   is the whole and true answer to why it exists, and a disclosure triangle
   hiding that sentence would be pure ceremony - so it is shown as a plain row,
   or not at all when they wrote nothing beyond it.
*/
/* WHAT PUT IT ON THE CALENDAR, in words. "heartbeat" named a loop that
   now has steps, and only one of them schedules anything; the step that
   did is written on the task when it is made. */
/* When, by whom and why a task was called off - closed as already done,
   or cancelled - so the calendar still says what became of it. */
function calledOff(task) {
  const said = task.metadata || {};
  const kind = task.status === "closed" ? "closed" : "cancelled";
  const at = said[`${kind}_at`];
  const by = said[`${kind}_by`] || (kind === "closed" ? "the agent" : "");
  return `${at ? new Date(at).toLocaleString() : ""}${
    by ? `${at ? " " : ""}by ${by}` : ""}${at || by ? ": " : ""}${
    said[`${kind}_reason`] || "no reason recorded"}`;
}

function whoMadeIt(task) {
  const step = ((task && task.metadata) || {}).created_by_step;
  if (step) return String(step);
  const by = String((task && task.created_by) || "");
  return {user: "you", heartbeat: "the agent heartbeat",
          scheduler: "the scheduler", agent: "the agent"}[by] || "the agent";
}

/* Which kind of notification, and what the user can answer it with. */
function notificationKind(task) {
  if (!task || task.execution_type !== "notification") return "";
  const template = ((task.task_payload || {}).template) || "reminder";
  return template === "passive"
    ? "notice - something to know; answered with Got it (no more notifications), "
      + "Add to to-do (no more notifications; listed in To do on the Overview), "
      + `or ${BAD_LABEL}`
    : "reminder - something to do; answered with Got it (no more notifications), "
      + `Remind me in ${remindLaterMinutes} minutes, Add to to-do (no more `
      + `notifications; listed in To do on the Overview), or ${BAD_LABEL}`;
}

/* Each "Remind me later", in order: 7:00 -> 7:30 -> 8:00 - a day named only
   where it changes. */
function postponedChain(task) {
  const log = ((task && task.metadata) || {}).postponed || [];
  if (!log.length) return "";
  const times = [log[0].from, ...log.map((one) => one.to)]
    .map((one) => new Date(one)).filter((one) => !isNaN(one));
  let day = "";
  return times.map((one) => {
    const today = one.toDateString();
    const said = one.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
    const prefix = today !== day ? `${one.toLocaleDateString(undefined,
      { month: "short", day: "numeric" })} ` : "";
    day = today;
    return prefix + said;
  }).join(" → ") + ` (${log.length} time${log.length === 1 ? "" : "s"})`;
}

function rationaleBlock(task) {
  const why = (task && task.reason)
    || (task && task.metadata && task.metadata.rationale) || "";
  if (!why) return "";
  if ((task.created_by || "") === "user") {
    return why === "added by user" ? "" : `
      <div class="event-row"><span class="event-label">Why</span>
        <span>${escapeHtml(String(why))}</span></div>`;
  }
  const missing = String(why).startsWith("no reason recorded");
  const who = escapeHtml(whoMadeIt(task));
  return `<details class="event-why${missing ? " missing" : ""}">
      <summary>Why ${who} scheduled this${missing ? " - nothing was recorded" : ""}</summary>
      <div class="event-body">${escapeHtml(String(why))}</div>
    </details>`;
}

/* WHAT ITS TIME WAS TAKEN FROM, when there is something to check: a time
   the source wrote ("Thu 3pm"), another place's clock, or a night the clocks
   change. The agent heartbeat gives a time as a clock shows it and whose
   clock; the moment is worked out from that (scheduler/core/zones.py) - so
   a wrong guess of the zone is seen here, and moved with Edit. */
function timeTakenFrom(task) {
  const time = ((task && task.metadata) || {}).time || {};
  if (!time.wall) return "";
  // A zone the agent wrote that is no place's name, and was not named when
  // asked again: taken as the user's own time - said, so it can be checked.
  if (time.zone_unread) {
    return `the time's zone could not be read ("${time.zone_unread}"); taken as your own time`;
  }
  const zone = time.zone_said || time.zone;
  // On the clock the user is on now: the time the calendar shows is the one
  // meant, and there is nothing to say of the zone.
  if (!time.zone || time.zone === "local" || sameClockAsHere(time.zone)) {
    return time.as_written ? `written as "${time.as_written}", taken as your own time` : "";
  }
  // Their own time where they were when it was made - shown here converted.
  if (time.own) return `made on your own time then: ${zone} time, ${time.wall} there`;
  return time.as_written
    ? `written as "${time.as_written}", taken as ${zone} time, ${time.wall} there`
    : `taken as ${zone} time, ${time.wall} there`;
}

/* Whether a zone keeps the same clock as the one this page is on: the same
   offsets now and half a year on, daylight saving included. */
function sameClockAsHere(zone) {
  if (!zone || zone === "local") return true;
  if (zone === PAGE_ZONE) return true;
  try {
    const offset = (name, when) => new Intl.DateTimeFormat("en-US", {
      timeZone: name, timeZoneName: "longOffset" }).formatToParts(when)
      .find((part) => part.type === "timeZoneName").value;
    const now = new Date();
    const later = new Date(now.getTime() + 182 * 86400000);
    return [now, later].every((when) => offset(zone, when) === offset(PAGE_ZONE, when));
  } catch (err) {
    return false;
  }
}

function clockChangeNote(task) {
  const clock = (((task && task.metadata) || {}).time || {}).clock;
  if (clock === "skipped") {
    return "The clocks go forward that night and that time does not exist - it is taken as the same time after the jump.";
  }
  if (clock === "twice") {
    return "The clocks go back that night and that time comes twice - it is taken as the first.";
  }
  return "";
}

function openTask(taskId, anchor) {
  const task = (calendarState.tasks || []).find((candidate) => candidate.id === taskId);
  if (!task) return;
  // Acting on one block acts on the series that owns it: there is only one
  // task here, however many times it is drawn (section 52.3).
  const seriesId = task.occurrence_of || task.id;
  calendarState.openTask = taskId;
  const when = new Date(task.scheduled_at);
  const row = (label, value) => value
    ? `<div class="event-row"><span class="event-label">${escapeHtml(label)}</span>
       <span>${escapeHtml(String(value))}</span></div>` : "";
  const opened = openPopover(anchor, `
      <div class="event-head">
        <span class="badge ${escapeHtml(statusClass(task.status))}">${
          escapeHtml(statusLabel(task.status))}</span>
        <h3>${escapeHtml(task.title)}</h3>
        <button type="button" class="small secondary" id="event-close">Close</button>
      </div>
      ${row("When", when.toLocaleString(undefined, { weekday: "long", year: "numeric",
        month: "long", day: "numeric", hour: "2-digit", minute: "2-digit" }))}
      ${row("Its time", timeTakenFrom(task))}
      ${row("Clock change", clockChangeNote(task))}
      ${row("Postponed", postponedChain(task))}
      ${row("Kind", task.execution_type)}
      ${notifyRow(task)}
      ${row("Repeats", describeRecurrence(task))}
      ${task.occurrence_of && task.occurrence_index !== task.runs
        ? row("This block", `run ${task.occurrence_index + 1}, not yet reached`)
        : ""}
      ${row("Notification", notificationKind(task))}
      ${row("Created", task.created_at
        ? `${new Date(task.created_at).toLocaleString()} by ${whoMadeIt(task)}`
        : "")}
      ${task.status === "closed" || task.status === "cancelled"
        ? row(task.status === "closed" ? "Closed" : "Cancelled",
              calledOff(task)) : ""}
      ${row("Written by", xpWriter((task.metadata || {}).written_by))}
      ${row("Last run", task.last_run_at
        ? new Date(task.last_run_at).toLocaleString() : "never")}
      ${row("Result", task.last_result)}
      <div class="event-detail-body">
        <div class="muted">Detail</div>
        ${task.description
          ? `<div class="event-body">${escapeHtml(task.description)}</div>`
          : `<div class="event-body missing">No detail was written for this task,
               so there is nothing here saying what it will do.</div>`}
      </div>
      ${rationaleBlock(task)}
      <div class="event-actions">
        ${eventEditable(task) ? `<button type="button" class="small secondary"
          data-act="edit" title="Change its title, its message, its time or how it repeats${
            task.occurrence_of ? " - for every occurrence" : ""}">Edit</button>` : ""}
        ${task.status === "disabled" ? "" : `<button type="button"
          class="small secondary" data-act="disable"
          title="Keep it on the calendar, marked disabled by user; it no longer runs or notifies you">Disable</button>`}
        <button type="button" class="small secondary danger" data-act="delete"
          title="Take it off the calendar altogether; it no longer runs or notifies you">Delete</button>
      </div>`, () => { calendarState.openTask = null; });
  const close = opened.close;
  $("#event-close").addEventListener("click", close);
  $$("#event-detail [data-act]").forEach((button) =>
    button.addEventListener("click", async () => {
      const action = button.dataset.act;
      if (action === "edit") {
        openEventEdit(task, button.closest(".event-actions"), seriesId,
                      close, () => { close(); openTask(taskId, anchor); });
        return;
      }
      // Deleting is the one that cannot be undone, so it is the one that
      // asks - in the card itself, where the answer is given, rather than in
      // a browser dialog a desktop window may not show.
      if (action === "delete" && button.dataset.sure !== "yes") {
        const actions = button.closest(".event-actions");
        actions.innerHTML = `<span class="event-sure">Are you sure you want to
            delete "${escapeHtml(task.title)}"? It will be taken off the
            calendar and will not notify you.</span>
          <textarea class="event-why-said" rows="2" maxlength="2000"
            placeholder="Why? (optional - it helps the agent learn which notifications you want)"></textarea>
          <button type="button" class="small danger" data-act="delete"
            data-sure="yes">Yes, delete it</button>
          <button type="button" class="small secondary" data-act="keep">No,
            keep it</button>`;
        actions.querySelector("[data-act=keep]").addEventListener(
          "click", () => { close(); openTask(taskId, anchor); });
        actions.querySelector("[data-sure=yes]").addEventListener(
          "click", () => act(actions.querySelector("[data-sure=yes]")));
        return;
      }
      await act(button);
    }));
  async function act(button) {
      const action = button.dataset.act;
      button.disabled = true;
      const said = (button.closest(".event-actions")
        ?.querySelector(".event-why-said")?.value || "").trim();
      try {
        await api.post("/api/tasks/action",
                       { id: seriesId, action, ...(said ? { why: said } : {}) });
        toast(`${task.title}: ${action === "delete" ? "deleted" : "disabled"}`);
        close();
        await loadCalendar();
      } catch (err) {
        toast(err.message, "error");
        button.disabled = false;
      }
  }
}

/* -------------------------------------------------------- editing an event
   An event still to come can be edited in its card: its title, the words
   its notification shows, its time and how it repeats. A repeating one is
   edited whole, whichever block was opened - the form shows the series'
   next run, not the block's own time, and says it applies to every
   occurrence. Each edit is a lesson (what the user wanted instead), so the
   form asks why, as Delete does, and the Lessons panel shows it.

   Only what was changed is sent: a field the user left as it was is not an
   edit, and the lesson should not read it as one.

   Not drawn again under the typing: the calendar's refresh redraws the
   grid and the day panel, never the card (#event-detail), so the form is
   left as it is until Save or Cancel. */
const EVENT_EDITABLE = ["pending", "disabled", "scheduled"];
const EDIT_UNITS = [["weeks", 604800], ["days", 86400], ["hours", 3600],
                    ["minutes", 60]];

function eventEditable(task) {
  return Boolean(task) && EVENT_EDITABLE.includes(task.status);
}

/* "YYYY-MM-DDTHH:MM" in the user's own time, for a datetime-local field. */
function localInputValue(date) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
    + `T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/* A local moment as ISO-8601 with the user's own offset - the time they
   chose, in the zone they chose it in. */
function isoWithOffset(date) {
  const pad = (n) => String(Math.floor(Math.abs(n))).padStart(2, "0");
  const offset = -date.getTimezoneOffset();
  return `${localInputValue(date)}:00${offset >= 0 ? "+" : "-"}${
    pad(offset / 60)}:${pad(offset % 60)}`;
}

/* How the event repeats, as the form shows it. A count is of the runs
   still to come - an edit starts the count again from the next run. */
function editRepeatOf(task) {
  const rule = (task && task.recurrence) || {};
  const every = Number(rule.every_seconds || 0);
  if (!every) return { kind: "none", amount: 1, unit: "days", end: "never" };
  const [unit, size] = EDIT_UNITS.find(([, s]) => every % s === 0)
    || ["minutes", 60];
  const out = { kind: "every", amount: Math.max(1, Math.round(every / size)),
                unit, end: "never" };
  if (rule.count) {
    out.end = "after";
    out.count = Math.max(1, Number(rule.count) - Number(task.runs || 0));
  } else if (rule.until) {
    out.end = "on";
    out.until = localInputValue(new Date(rule.until)).slice(0, 10);
  }
  return out;
}

/* The repeat the form says, as the API takes it: null for once. */
function editRepeatValue(form) {
  const value = (name) => form.querySelector(`[name=${name}]`).value;
  if (value("repeat") !== "every") return null;
  const repeat = { every: Number(value("every")), unit: value("unit") };
  if (value("end") === "after") repeat.count = Number(value("count"));
  if (value("end") === "on" && value("until")) {
    const [y, m, d] = value("until").split("-").map(Number);
    repeat.until = isoWithOffset(new Date(y, m - 1, d, 23, 59));
  }
  return repeat;
}

function openEventEdit(task, actions, seriesId, close, cancel) {
  const series = Boolean(task.occurrence_of) || Boolean(
    task.recurrence && task.recurrence.every_seconds);
  const title = task.series_title || task.title || "";
  const message = ((task.task_payload || {}).message) || task.description || "";
  const at = localInputValue(new Date(task.series_at || task.scheduled_at));
  const repeat = editRepeatOf(task);
  const zone = (Intl.DateTimeFormat().resolvedOptions() || {}).timeZone || "";
  const option = (value, label, chosen) =>
    `<option value="${value}"${value === chosen ? " selected" : ""}>${label}</option>`;
  actions.innerHTML = `
    <form class="event-edit">
      ${series ? `<p class="event-edit-note">This repeats: the edit applies to
        every occurrence${task.occurrence_of ? ", not only the one opened" : ""}.
        A new time or repeat starts the series again from its next run.</p>` : ""}
      <label>Title <input name="title" maxlength="200"
        value="${escapeHtml(title)}"></label>
      <label>Message <textarea name="message" rows="3" maxlength="4000">${
        escapeHtml(message)}</textarea></label>
      <label>${series ? "Next run" : "When"} <span class="muted">(your time${
        zone ? `, ${escapeHtml(zone)}` : ""})</span>
        <input type="datetime-local" name="at" value="${at}"></label>
      <div class="event-edit-repeat">
        <label>Repeats <select name="repeat">
          ${option("none", "Does not repeat", repeat.kind)}
          ${option("every", "Every", repeat.kind)}</select></label>
        <span class="event-edit-every">
          <input type="number" name="every" min="1" step="1"
            value="${repeat.amount}" aria-label="How many">
          <select name="unit" aria-label="Unit">${EDIT_UNITS.map(([unit]) =>
            option(unit, unit, repeat.unit)).join("")}</select>
          <select name="end" aria-label="Ends">
            ${option("never", "no end", repeat.end)}
            ${option("on", "until a date", repeat.end)}
            ${option("after", "a number of times", repeat.end)}</select>
          <input type="date" name="until" value="${repeat.until || ""}"
            aria-label="Last day">
          <input type="number" name="count" min="1" step="1"
            value="${repeat.count || 1}" aria-label="How many times"></span>
      </div>
      <textarea class="event-why-said" name="why" rows="2" maxlength="2000"
        placeholder="Why? (optional - it helps the agent learn which notifications you want)"></textarea>
      <div class="event-edit-buttons">
        <button type="submit" class="small" data-edit="save">Save</button>
        <button type="button" class="small secondary" data-edit="cancel">Cancel</button>
      </div>
    </form>`;
  const form = actions.querySelector(".event-edit");
  const field = (name) => form.querySelector(`[name=${name}]`);
  const shown = JSON.stringify(editRepeatValue(form));
  // Only the parts of the repeat that mean something are shown.
  const showRepeat = () => {
    const every = field("repeat").value === "every";
    form.querySelector(".event-edit-every").hidden = !every;
    field("until").hidden = field("end").value !== "on";
    field("count").hidden = field("end").value !== "after";
  };
  ["repeat", "end"].forEach((name) => field(name).addEventListener("change", showRepeat));
  showRepeat();
  form.querySelector("[data-edit=cancel]").addEventListener("click", cancel);
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const body = { id: seriesId, action: "edit" };
    const newTitle = field("title").value.trim();
    const newMessage = field("message").value.trim();
    if (!newTitle) { toast("The title cannot be empty", "error"); return; }
    if (!newMessage) { toast("The message cannot be empty", "error"); return; }
    if (newTitle !== title.trim()) body.title = newTitle;
    if (newMessage !== message.trim()) body.message = newMessage;
    if (field("at").value && field("at").value !== at) {
      body.at = isoWithOffset(new Date(field("at").value));
    }
    const newRepeat = editRepeatValue(form);
    if (JSON.stringify(newRepeat) !== shown) body.repeat = newRepeat;
    if (Object.keys(body).length === 2) {
      toast("Nothing was changed");
      cancel();
      return;
    }
    const why = field("why").value.trim();
    if (why) body.why = why;
    const save = form.querySelector("[data-edit=save]");
    save.disabled = true;
    try {
      await api.post("/api/tasks/action", body);
      toast(`${newTitle}: edited${series ? " - every occurrence" : ""}`);
      close();
      await loadCalendar();
    } catch (err) {
      toast(err.message, "error");
      save.disabled = false;
    }
  });
  field("title").focus();
}

/* ---------------------------------------------------------------- lessons
   Each kind of lesson, with every lesson in it: what was done and when, the
   reading of why, and the complete record it was read from. The first kind
   is the notification lessons - what adding, disabling and deleting events,
   and marking notifications bad, say about the notifications wanted. */
const LESSON_ABOUT = {
  notifications: `Each event you add, edit, disable or delete on the calendar, and
    each notification you mark as a bad notification, is kept whole and
    thought about in the background: why you most likely did it, and the
    lesson - what the agent should do from now on. An edit is read as what
    you wanted instead: the event before it beside the event after it. The
    lessons are what the agent is given whenever it decides what to notify
    you of.`,
  connections: `Each change you make to your contacts - adding, editing,
    deleting, merging, moving an account - with when, and your reason if you
    gave one. Kept as you made them, not rewritten: the latest hundred word for
    word, the older ones summarised. They are what the agent is given whenever
    it adds or updates a contact; someone you deleted is added back only with
    strong evidence newer than the deletion.`,
};

/* What an edit changed, from what to what - kept with the lesson after the
   rest of the record has been let go of. */
const LESSON_FIELDS = { title: "Title", message: "Message", time: "Time",
                        repeat: "Repeats" };
function lessonChanges(one) {
  const changes = ((one.event || {}).changes || []).filter(Boolean);
  if (!changes.length) return "";
  return `<ul class="lesson-changes">${changes.map((change) => `
      <li><span class="lesson-field">${escapeHtml(
        LESSON_FIELDS[change.field] || change.field || "")}</span>
        <span class="lesson-before">${escapeHtml(change.before || "(none)")}</span>
        <span class="muted">&rarr;</span>
        <span class="lesson-after">${escapeHtml(change.after || "(none)")}</span></li>`)
    .join("")}</ul>`;
}

let lessonsTag = null;
// THE LESSON CARDS (GET /api/lessons/cards): each answered question, its
// answer, what it rests on, and how often it was used.
const LESSON_EVIDENCE = {
  user_said: "You said", user_code: "Your code", user_decision: "Your decision",
  model: "The model's own knowledge",
};
async function loadLessonCards() {
  const box = $("#lesson-cards");
  if (!box) return;
  let said;
  try {
    said = await api.get("/api/lessons/cards");
  } catch (err) {
    box.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  const open = new Set($$("#lesson-cards details[open]").map((d) => d.dataset.id));
  if (!(said.cards || []).length) {
    box.innerHTML = `<p class="muted">No lesson cards yet.</p>`;
    return;
  }
  // The question, the answer and the evidence are the agent's and the
  // user's words (.lesson-card-words): never translated.
  box.innerHTML = said.cards.map((card) => `
    <details class="lesson-card" data-id="${escapeHtml(card.id)}"${open.has(card.id) ? " open" : ""}>
      <summary><strong class="lesson-card-words">${escapeHtml(card.question)}</strong>
        <span class="badge">${card.tier === "user" ? "From you" : "An assumption"}</span>
        <span class="muted"><span>Version</span> ${card.version}</span>
        <span class="muted"><span>Used</span> ${card.uses}</span></summary>
      <div class="lesson-card-answer lesson-card-words">${escapeHtml(card.answer)}</div>
      <ul class="lesson-card-evidence">${(card.evidence || []).map((one) => `<li>
        <span class="muted">${escapeHtml(LESSON_EVIDENCE[one.type] || one.type)}</span>
        <span class="lesson-card-words">${escapeHtml(one.said || "")}</span>
        ${one.ref ? `<code>${escapeHtml(one.ref)}</code>` : ""}</li>`).join("")}</ul>
      ${(card.topics || []).length ? `<div class="muted"><span>Topics</span>
        <span class="lesson-card-words">${escapeHtml(card.topics.join(", "))}</span></div>` : ""}
    </details>`).join("");
}

async function loadLessons() {
  loadLessonCards();
  let said;
  try {
    // Drawn again only when a lesson has changed: redrawing on every
    // refresh closed whatever record was open and moved the page under
    // the reader.
    const got = await api.getIfChanged("/api/lessons", lessonsTag);
    if (!got.changed && $("#lessons-kinds").children.length) return;
    lessonsTag = got.tag;
    said = got.data || await api.get("/api/lessons");
  } catch (err) {
    $("#lessons-kinds").innerHTML =
      `<div class="card"><p class="muted">${escapeHtml(err.message)}</p></div>`;
    return;
  }
  const open = new Set($$("#lessons-kinds details[open]").map((d) => d.dataset.id));
  $("#lessons-kinds").innerHTML = (said.kinds || []).map((kind) => {
    // Counted as the lessons in force.
    const count = kind.engine ? (kind.engine.lessons || []).length
      : kind.kind === "notifications" && kind.list ? kind.list.length
      : kind.actions || 0;
    // An ACTION of the user's - what they did, a status, not a button:
    // its badge is named apart from the Delete button's class, which it
    // once shared ("lesson-delete" for a deletion) - a click on the badge
    // asked to delete, and the badge was pushed right with the button.
    // Learned from by the engine, the action is FORGOTTEN, not deleted.
    const forget = Boolean(kind.engine);
    const lessons = (kind.lessons || []).map((one) => `
      <li class="lesson lesson-did" data-lesson="${escapeHtml(one.id)}"
          data-kind="${escapeHtml(kind.kind)}">
        <div class="lesson-head lesson-did-head"><span class="muted lesson-did-when">${
          escapeHtml(new Date(one.acted_at).toLocaleString())}</span>
          <span class="badge lesson-act lesson-act-${escapeHtml(one.action)}">${
            escapeHtml(one.did)}</span>
          <strong class="lesson-did-title">${escapeHtml(one.title)}</strong>
          <button type="button" class="small secondary danger lesson-delete"
            title="${forget ? "Forget this action: the lessons no longer learn from it"
              : "Delete this lesson: the agent is no longer given it"}">${
              forget ? "Forget" : "Delete"}</button></div>
        <div class="lesson-sure" hidden>
          <span>${forget ? "Forget this action? The lessons will no longer learn from it."
            : "Delete this lesson? It will no longer be given to the agent."}</span>
          <button type="button" class="small danger lesson-yes">${forget
            ? "Yes, forget it" : "Yes, delete it"}</button>
          <button type="button" class="small secondary lesson-no">No, keep it</button>
        </div>
        ${lessonChanges(one)}
        ${(one.event || {}).user_said ? `<div class="lesson-said">You said: ${
          escapeHtml(one.event.user_said)}</div>` : ""}
        ${kind.engine ? lessonRead(one.read || []) : ""}
        ${kind.kind === "connections" ? (one.deleted_now ? `<div class="lesson-restore">
            <button type="button" class="small secondary lesson-restore-ask">Add back</button>
            <span class="lesson-restore-sure" hidden>
              <input placeholder="Reason (optional)" aria-label="Reason">
              <button type="button" class="small lesson-restore-yes" data-person="${
                escapeHtml(one.person_id || "")}">Yes, add back</button>
              <button type="button" class="small secondary lesson-restore-no">No</button>
            </span></div>` : "")
        : kind.engine ? ""
        : one.reasoned_at
          ? `<div class="lesson-text">${one.lesson ? (kind.kind === "notifications"
              // What this action changed in the lessons, a line each.
              ? one.lesson.split("\n").map((line) => `<div>${escapeHtml(line)}</div>`).join("")
              : escapeHtml(one.lesson))
              : `<span class="muted">Nothing new - a lesson already says
                 this.</span>`}</div>
             ${one.why ? `<div class="lesson-why muted">Why: ${
               escapeHtml(one.why)}</div>` : ""}`
          : `<div class="lesson-why muted">Not yet thought about.</div>`}
      </li>`).join("");
    // LEARNED FROM EVIDENCE: the lessons in force and those forming, each
    // with how sure, its cases and its history - above the actions, each
    // saying how it was read.
    const learned = kind.engine ? lessonsLearned(kind) : "";
    const inForce = !kind.engine && kind.kind === "notifications" && (kind.list || []).length
      ? `<h4 class="lesson-subhead">In force</h4><ul class="lessons lessons-in-force">${
        kind.list.map((one) => `<li class="lesson" data-lesson="${escapeHtml(one.id)}"
          data-kind="notifications">
          <div class="lesson-head"><span class="lesson-text">${escapeHtml(one.text)}</span>
            <button type="button" class="small secondary danger lesson-delete"
              title="Delete this lesson: the agent is no longer given it">Delete</button></div>
          <div class="lesson-sure" hidden>
            <span>Delete this lesson? It will no longer be given to the agent.</span>
            <button type="button" class="small danger lesson-yes">Yes, delete it</button>
            <button type="button" class="small secondary lesson-no">No, keep it</button>
          </div></li>`).join("")}</ul>
        <h4 class="lesson-subhead">What each of your actions changed</h4>` : "";
    // The connection lessons past a hundred, summarised, above the rest.
    const summary = kind.kind === "connections" && kind.summary && kind.summary.text
      ? `<details class="lesson-summary" open><summary>${Number(kind.summary.covers || 0)}
          older changes, summarised</summary><p>${escapeHtml(kind.summary.text)}</p></details>`
      : "";
    return `<div class="card lesson-kind">
      <h3>${escapeHtml(kind.title)} <span class="muted">${count
        ? `· ${count} lesson${count === 1 ? "" : "s"}${kind.waiting
          ? `, ${kind.waiting} still being thought about` : ""}` : ""}</span></h3>
      <p class="muted">${LESSON_ABOUT[kind.kind] || ""}</p>
      ${summary}
      ${learned}
      ${inForce}
      ${lessons ? `<ul class="lessons">${lessons}</ul>`
        : `<p class="muted">Nothing yet.</p>`}
    </div>`;
  }).join("");
}

/* THE LESSONS LEARNED, from the engine: in force, then forming - each
   with how sure, how many cases back it and against it, and its history;
   the user's say: pin, confirm, reject, reword. */
function lessonsLearned(kind) {
  const engine = kind.engine || {};
  const rule = (one, forming) => `<li class="lesson lesson-rule" data-rule="${
      escapeHtml(one.id)}">
    <div class="lesson-head"><span class="lesson-text">${escapeHtml(one.statement)}</span>
      <span class="badge${one.pinned ? " ok" : ""}">${one.pinned ? "pinned"
        : `${Math.round((one.confidence || 0) * 100)}% sure`}</span>
      <span class="muted">${Number(one.cases || 0)} case${one.cases === 1 ? "" : "s"}${
        one.against ? `, ${Number(one.against)} against` : ""}${forming && one.to_promote
        ? `, about ${Math.ceil(one.to_promote)} more to become a lesson` : ""}</span></div>
    <div class="lesson-rule-tools">
      ${forming ? `<button type="button" class="small" data-rule-op="confirm">Make it a lesson</button>`
        : `<button type="button" class="small secondary" data-rule-op="${one.pinned
          ? "unpin" : "pin"}">${one.pinned ? "Unpin" : "Pin"}</button>`}
      <button type="button" class="small secondary" data-rule-op="edit">Reword</button>
      <button type="button" class="small secondary danger" data-rule-op="reject">${forming
        ? "Not a lesson" : "Delete"}</button>
    </div>
    <details class="lesson-rule-why"><summary>What it rests on</summary>
      <ul>${(one.evidence || []).map((e) => `<li><span class="badge lesson-rel lesson-rel-${
        e.relation === "supports" ? "for" : "against"}">${escapeHtml(e.relation)}</span> ${
        escapeHtml(String(e.summary || "").split("\n")[0])}${e.why ? ` <span class="muted">- ${
        escapeHtml(e.why)}</span>` : ""}</li>`).join("")}</ul>
      ${(one.history || []).length ? `<p class="muted">${(one.history || []).map((h) =>
        `${escapeHtml(localStamp(h.at))}: ${escapeHtml(h.why || h.what || "")}`).join("<br>")}</p>` : ""}
    </details></li>`;
  const lessons = engine.lessons || [];
  const forming = engine.forming || [];
  // ABOVE THEM, AS ABOVE THE NATURES: principles, then patterns.
  const groups = engine.groups || {};
  const grouped = (groups.principles || []).length || (groups.patterns || []).length
    ? `<div class="lesson-groups">${(groups.principles || []).map((one) => `<div
        class="lesson-principle"><strong>${escapeHtml(one.statement)}</strong>${one.patterns
        && one.patterns.length ? `<div class="muted">${one.patterns.map(escapeHtml)
        .join(" · ")}</div>` : ""}</div>`).join("")}
      ${(groups.patterns || []).length ? `<details class="lesson-patterns"><summary>${
        groups.patterns.length} pattern${groups.patterns.length === 1 ? "" : "s"}</summary>
        <ul>${groups.patterns.map((one) => `<li><strong>${escapeHtml(one.statement)}</strong>${
          one.lessons && one.lessons.length ? `<div class="muted">${one.lessons.map(escapeHtml)
          .join("<br>")}</div>` : ""}</li>`).join("")}</ul></details>` : ""}</div>` : "";
  return `${grouped}<h4 class="lesson-subhead">Lessons in force <span class="muted">what the agent
      is given</span></h4>
    ${lessons.length ? `<ul class="lessons lessons-in-force">${lessons.map((one) =>
      rule(one, false)).join("")}</ul>` : `<p class="muted">None yet: a lesson forms once
      several of your edits point the same way.</p>`}
    ${forming.length ? `<h4 class="lesson-subhead">Forming <span class="muted">not given to
      the agent yet</span></h4><ul class="lessons">${forming.map((one) =>
      rule(one, true)).join("")}</ul>` : ""}
    ${engine.waiting ? `<p class="muted">${Number(engine.waiting)} of your edits not
      learned from yet - with the state heartbeat's next round, or
      <button type="button" class="small secondary" data-lessons-learn>Learn now</button></p>`
      : ""}
    <h4 class="lesson-subhead">What you did</h4>`;
}

/* How one action was read: the lessons it backs or goes against. */
function lessonRead(read) {
  if (!read.length) return "";
  if (read.some((one) => one.waiting)) {
    return `<div class="lesson-why muted">Still being read.</div>`;
  }
  return `<div class="lesson-why">${read.map((one) => `${one.relation === "supports"
    ? "Backs" : "Goes against"}: ${escapeHtml(one.statement || "")}`).join("<br>")}</div>`;
}

/* ----------------------------------------------------- Reading debugger

   What the user read, as the log keeps it: the topics, weightiest first,
   and the latest pieces - each with its kind, how long, its topics and the
   points it made. */
/* THE LANGUAGE DEBUGGER, read off the source each time: every place a model
   call's language is said (language=in_display(...) + in_english(...)),
   under what it says - English, the display language, partly each - and
   every call that says none; prompts that still say one in their own words;
   and what the calls of the last days were sent with, beside it. */
const LANGUAGE_RULES = [
  ["internal", "In English (the agent's internal language)"],
  ["display", "In your display language"],
  ["mixed", "Partly each"],
  ["unspecified", "Not specified"],
];

function languageParts(rules) {
  return (rules || []).length ? rules.map((part) => `<div><span class="lang-rule lang-${
    escapeHtml(part.rule)}">${escapeHtml(part.rule)}</span> ${escapeHtml(part.what)}</div>`)
    .join("") : '<span class="lang-rule lang-unspecified">unspecified</span>';
}

async function loadLanguages() {
  const host = $("#lang-debug");
  if (!host) return;
  let said;
  try {
    said = await api.get("/api/debugger/languages");
  } catch (err) {
    host.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  const table = (rows) => `<table class="lang-table"><thead><tr><th>Task</th><th>What it
    says</th><th>Where</th></tr></thead><tbody>${rows.map((one) => `<tr>
      <td><code>${escapeHtml(one.task || "")}</code>${one.through && one.through !== "ModelRequest"
        ? `<div class="muted">through ${escapeHtml(one.through)}()</div>` : ""}</td>
      <td>${languageParts(one.rules)}</td>
      <td class="muted"><code>${escapeHtml(one.where)}</code><div>${escapeHtml(one.in || "")}${
        one.via && one.via !== "call" ? ` - ${escapeHtml(one.via)}` : ""}</div></td></tr>`)
    .join("")}</tbody></table>`;
  const groups = said.groups || {};
  const sent = said.sent || [];
  // Sent with none: a call the code meant to say a language for and did not.
  const sentBare = sent.filter((one) => one.rule === "unspecified");
  host.innerHTML = `<p class="muted">Your display language: <strong>${escapeHtml(
      said.display_language || "")}</strong>. Read off the source now - a language added,
      changed or taken away in the code shows here the next time this is opened.</p>
    ${LANGUAGE_RULES.map(([key, title]) => `<h4 class="lang-head lang-head-${key}">${
      escapeHtml(title)} <span class="muted">(${(groups[key] || []).length})</span></h4>${
      (groups[key] || []).length ? table(groups[key]) : '<p class="muted">None.</p>'}`).join("")}
    <h4 class="lang-head">Still said inside a prompt <span class="muted">(${
      (said.inline || []).length})</span></h4>
    <p class="muted">Words in a prompt or a tool's description that name a language, rather
      than language= - invisible to the rest of this page.</p>
    ${(said.inline || []).length ? `<ul class="lang-inline">${said.inline.map((one) =>
      `<li><code>${escapeHtml(one.where)}</code> <span class="muted">${escapeHtml(one.in)}</span>
        <div class="muted">&hellip;${escapeHtml(one.words)}&hellip;</div></li>`).join("")}</ul>`
      : '<p class="muted">None.</p>'}
    <h4 class="lang-head">What was sent, the last ${Number(said.days) || 7} days
      <span class="muted">(${sent.length})</span></h4>
    <p class="muted">Each call records the language it carried. ${sentBare.length
      ? `<strong>${sentBare.length} kind${sentBare.length === 1 ? "" : "s"} of call went out
        with none</strong> - from before this was recorded, or a call the code does not say one for.`
      : "Every call went out with one."}</p>
    ${sent.length ? `<table class="lang-table"><thead><tr><th>Task</th><th>Sent with</th>
      <th>Calls</th><th>Last</th></tr></thead><tbody>${sent.map((one) => `<tr>
        <td><code>${escapeHtml(one.task)}</code></td><td>${languageParts(one.rules)}</td>
        <td>${Number(one.calls) || 0}</td><td class="muted">${escapeHtml(
          localStamp(one.last, "short"))}</td></tr>`).join("")}</tbody></table>`
      : '<p class="muted">No calls yet.</p>'}`;
}

/* THE CONNECTION DEBUGGER (heartbeat/connections/store.py `changes`): every
   change to the contacts, newest first - and, for the agent's, the start of
   what its model was asked and answered; the whole call opens from its file.
   Drawn again only when there is something new, and never over a change
   opened to read. */
const connectionsDebug = { data: null, seen: "" };

async function loadConnectionsDebugger() {
  let said;
  try {
    said = await api.get("/api/debugger/connections?most=300");
  } catch (err) {
    $("#cdbg-list").innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  const changes = said.changes || [];
  const seen = changes.length ? `${changes[0].id}|${changes.length}` : "none";
  if (seen === connectionsDebug.seen) return;
  connectionsDebug.data = said;
  connectionsDebug.seen = seen;
  drawConnectionsDebugger();
}

function cdbgShort(value, most) {
  const text = typeof value === "string" ? value : JSON.stringify(value, null, 1);
  return text.length > most ? `${text.slice(0, most)}…` : text;
}

function drawConnectionsDebugger() {
  const host = $("#cdbg-list");
  const said = connectionsDebug.data;
  if (!host || !said) return;
  const open = new Set([...host.querySelectorAll("details[open]")].map((one) => one.dataset.id));
  const filter = ($("#cdbg-filter")?.value || "").trim().toLowerCase();
  const rows = (said.changes || []).filter((one) => !filter
    || String(one.person_name || "").toLowerCase().includes(filter));
  if (!rows.length) {
    host.innerHTML = `<p class="muted">No change yet.</p>`;
    return;
  }
  host.innerHTML = rows.map((one) => {
    const call = one.call;
    const changed = Object.keys(one.after || {}).join(", ");
    return `<details class="cdbg-row" data-id="${escapeHtml(one.id)}"${open.has(one.id) ? " open" : ""}>
      <summary><span class="cdbg-when">${escapeHtml(localStamp(one.at))}</span>
        <span class="cdbg-who">${escapeHtml(one.by === "user" ? "you" : "the agent")}</span>
        <strong>${escapeHtml(one.action)}</strong> ${escapeHtml(one.person_name || "")}
        <span class="muted">${escapeHtml(changed)}</span></summary>
      ${one.reason ? `<p class="muted">Why: ${escapeHtml(one.reason)}</p>` : ""}
      <div class="cdbg-grid">
        <div><h4>Before</h4><pre>${escapeHtml(cdbgShort(one.before || {}, 2000))}</pre></div>
        <div><h4>After</h4><pre>${escapeHtml(cdbgShort(one.after || {}, 2000))}</pre></div>
      </div>
      ${call ? `<div class="cdbg-call">
        <p class="muted">From ${escapeHtml(call.source || "a model call")}, ${
          escapeHtml(localStamp(call.at))}${call.span ? ` - ${escapeHtml(call.span)}` : ""}</p>
        <h4>What it was asked (${Number(call.prompt_chars || 0).toLocaleString()} characters)</h4>
        <pre class="cdbg-prompt">${escapeHtml(call.prompt_start || "")}</pre>
        <h4>What it answered (${Number(call.answer_chars || 0).toLocaleString()} characters)</h4>
        <pre class="cdbg-answer">${escapeHtml(call.answer_start || "")}</pre>
        <button type="button" class="small secondary" data-cdbg-call="${escapeHtml(call.id)}">Show the whole call</button>
        ${call.archive ? `<p class="muted">Kept whole in <code>${escapeHtml(call.archive)}</code></p>` : ""}
      </div>` : ""}
    </details>`;
  }).join("");
}

$("#cdbg-filter")?.addEventListener("input", drawConnectionsDebugger);

document.addEventListener("click", async (event) => {
  const button = event.target.closest && event.target.closest("[data-cdbg-call]");
  if (!button) return;
  button.disabled = true;
  try {
    const call = await api.get(`/api/debugger/connections/call?id=${
      encodeURIComponent(button.dataset.cdbgCall)}`);
    const box = button.closest(".cdbg-call");
    box.querySelector(".cdbg-prompt").textContent = call.prompt || "";
    box.querySelector(".cdbg-answer").textContent = call.answer || "";
    button.remove();
  } catch (err) {
    toast(err.message, "error");
    button.disabled = false;
  }
});

async function loadReading() {
  let said;
  try {
    said = await api.get("/api/reading");
  } catch (err) {
    $("#reading-status").textContent = err.message;
    return;
  }
  const progress = said.progress || {};
  $("#reading-status").textContent = progress.running
    ? `${progress.stage || "working"}${Number(progress.total || 0)
      ? ` (${Number(progress.done || 0)} of ${Number(progress.total)})` : ""}`
    : `${Number(said.count || 0)} piece${said.count === 1 ? "" : "s"} kept${said.until
      ? ` · read up to ${localStamp(said.until)}` : ""}${progress.error
      ? ` · the last update failed: ${progress.error}` : ""}`;
  const topics = said.topics || [];
  const most = Math.max(0.0001, ...topics.map((one) => Number(one.weight) || 0));
  $("#reading-topics").innerHTML = topics.length ? `<ul class="reading-topics">${
    topics.map((one) => `<li><span class="reading-topic-name">${escapeHtml(one.label)}</span>
      <span class="reading-topic-bar"><span style="width:${Math.round(
        100 * (Number(one.weight) || 0) / most)}%"></span></span>
      <span class="muted">${Number(one.pieces || 0)} piece${one.pieces === 1 ? "" : "s"}
        · weight ${(Number(one.weight) || 0).toFixed(2)}</span>
      ${(one.latest || []).length ? `<div class="muted reading-latest">${one.latest.map(
        escapeHtml).join(" · ")}</div>` : ""}</li>`).join("")}</ul>`
    : `<p class="muted">No topics yet: they form as you read.</p>`;
  const pieces = said.pieces || [];
  $("#reading-pieces").innerHTML = pieces.length ? `<ul class="reading-pieces">${
    pieces.map((one) => `<li class="reading-piece">
      <div class="reading-piece-head"><span class="muted">${escapeHtml(localStamp(one.last_at))}</span>
        <span class="badge">${escapeHtml(one.kind || "")}</span>
        ${one.url ? `<a href="${escapeHtml(one.url)}" target="_blank" rel="noopener noreferrer"
          >${escapeHtml(one.title || one.url)}</a>` : `<strong>${escapeHtml(one.title || "")}</strong>`}
        <span class="muted">${Math.round(Number(one.seconds) || 0)}s${Number(one.visits) > 1
          ? ` · ${Number(one.visits)} visits` : ""}${one.fetched ? " · read again from the web"
          : ""}</span></div>
      ${(one.topics || []).length ? `<div class="muted">${one.topics.map(escapeHtml)
        .join(" · ")}</div>` : ""}
      ${(one.points || []).length ? `<ul class="reading-points">${one.points.map((point) =>
        `<li>${escapeHtml(point)}</li>`).join("")}</ul>` : ""}
    </li>`).join("")}</ul>` : `<p class="muted">Nothing kept yet.</p>`;
}

$("#reading-run").addEventListener("click", async () => {
  const button = $("#reading-run");
  button.disabled = true;
  try {
    const said = await api.post("/api/reading/run", {});
    toast(said.started ? "Updating what you read" : "It is already being updated");
    setTimeout(() => { loadReading(); button.disabled = false; }, 3000);
  } catch (err) {
    toast(err.message, "error");
    button.disabled = false;
  }
});

/* Learn now: what is due, without waiting for the next round. */
document.addEventListener("click", async (event) => {
  const button = event.target.closest?.("[data-lessons-learn]");
  if (!button) return;
  button.disabled = true;
  try {
    await api.post("/api/lessons/learn", {});
    toast("Learning from your edits now");
    setTimeout(() => { lessonsTag = null; loadLessons(); }, 4000);
  } catch (err) {
    toast(err.message, "error");
    button.disabled = false;
  }
});

/* Pin, confirm, reject or reword a learned lesson. */
document.addEventListener("click", async (event) => {
  const button = event.target.closest?.("[data-rule-op]");
  if (!button) return;
  const rule = button.closest("[data-rule]");
  const op = button.dataset.ruleOp;
  let statement = "";
  if (op === "edit") {
    const now = (rule.querySelector(".lesson-text") || {}).textContent || "";
    const box = rule.querySelector(".lesson-reword");
    if (!box) {
      rule.querySelector(".lesson-rule-tools").insertAdjacentHTML("afterend",
        `<div class="lesson-reword"><input class="wide" value="${escapeHtml(now)}"
          aria-label="The lesson"><button type="button" class="small"
          data-rule-op="save">Save</button></div>`);
      return;
    }
  }
  if (op === "save") {
    statement = (rule.querySelector(".lesson-reword input") || {}).value || "";
  }
  button.disabled = true;
  try {
    await api.post("/api/lessons/rule", { id: rule.dataset.rule,
      op: op === "save" ? "edit" : op, statement });
    toast({ confirm: "Now a lesson", reject: "Deleted - not learned again",
            pin: "Pinned", unpin: "Unpinned", save: "Reworded" }[op] || "Done");
    lessonsTag = null;
    loadLessons();
  } catch (err) {
    toast(err.message, "error");
    button.disabled = false;
  }
});

/* Deleting a lesson asks first, in the lesson itself. */
document.addEventListener("click", async (event) => {
  const lesson = event.target.closest?.(".lesson[data-lesson]");
  if (!lesson) return;
  const sure = lesson.querySelector(".lesson-sure");
  if (event.target.closest("button.lesson-delete")) {
    sure.hidden = false;
    return;
  }
  if (event.target.closest(".lesson-no")) {
    sure.hidden = true;
    return;
  }
  const restoreSure = lesson.querySelector(".lesson-restore-sure");
  if (event.target.closest(".lesson-restore-ask") && restoreSure) {
    restoreSure.hidden = false;
    return;
  }
  if (event.target.closest(".lesson-restore-no") && restoreSure) {
    restoreSure.hidden = true;
    return;
  }
  const restoreYes = event.target.closest(".lesson-restore-yes");
  if (restoreYes) {
    restoreYes.disabled = true;
    try {
      await api.post("/api/connections/person", { action: "restore",
        id: restoreYes.dataset.person,
        reason: (restoreSure.querySelector("input") || {}).value || "" });
      toast("Added back to your connections");
      lessonsTag = null;
      loadLessons();
    } catch (err) {
      toast(err.message, "error");
      restoreYes.disabled = false;
    }
    return;
  }
  if (event.target.closest(".lesson-yes")) {
    event.target.disabled = true;
    try {
      await api.post("/api/lessons/delete",
                     { kind: lesson.dataset.kind, id: lesson.dataset.lesson });
      const forgot = lesson.classList.contains("lesson-did")
        && Boolean(lesson.closest(".lesson-kind")?.querySelector(".lesson-rule, .lesson-subhead"));
      lesson.remove();
      toast(forgot ? "Forgotten - the lessons no longer learn from it"
        : "Lesson deleted - the agent is no longer given it");
      lessonsTag = null;
      loadLessons();
    } catch (err) {
      toast(err.message, "error");
      event.target.disabled = false;
    }
  }
});

/* A notification can be called a bad one: it is dismissed, and it becomes a
   lesson. */
async function markBadNotification(id, item) {
  try {
    await api.post("/api/notifications/bad", { id });
    if (item) item.remove();
    toast("Kept as a bad notification - see Lessons");
    if (activeTab === "lessons") loadLessons();
  } catch (err) {
    toast(err.message, "error");
  }
}

function statusClass(status) {
  if (status === "completed") return "ok";
  if (status === "failed") return "err";
  return "warn";
}

/* Back and on: a month at a time, or a day at a time in the day view. */
function stepCalendar(by) {
  if (calendarState.view === "day") {
    calendarState.selected = new Date(calendarState.selected.getFullYear(),
      calendarState.selected.getMonth(), calendarState.selected.getDate() + by);
  } else {
    calendarState.anchor = new Date(calendarState.anchor.getFullYear(),
                                    calendarState.anchor.getMonth() + by, 1);
  }
  loadCalendar();
}

$("#cal-prev").addEventListener("click", () => stepCalendar(-1));
$("#cal-next").addEventListener("click", () => stepCalendar(1));
$$("[data-cal-view]").forEach((button) =>
  button.addEventListener("click", () => setCalendarView(button.dataset.calView)));
/* + Add event: on the day shown, at the next whole hour of today - or at
   nine on another day. */
$("#cal-add")?.addEventListener("click", (event) => {
  const day = startOfDay(calendarState.selected);
  const now = new Date();
  const at = sameDay(day, now)
    ? new Date(now.getFullYear(), now.getMonth(), now.getDate(), now.getHours() + 1)
    : new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9);
  openAddEvent(at, event.currentTarget);
});

$("#cal-today").addEventListener("click", () => {
  calendarState.anchor = startOfDay(new Date());
  calendarState.selected = startOfDay(new Date());
  loadCalendar();
});

/* --------------------------------------------------------------- library
   Section 13 and 39.1, as amended. What was here was a force-directed canvas
   of nodes and weighted edges. There is no graph to draw any more: the agent's
   memory is five folders of files, and the useful view of a folder of files is
   a list you can read, not a picture of it.

   That is not a lesser view. The canvas showed which memories existed and how
   they were joined, and neither answered the question a person actually brings
   to this page - what does it think it knows about me, and is it right. A
   listing with each record's summary answers that, and clicking one shows the
   text exactly as the agent wrote it.
*/
/* A duration in words, which is the form these are read in. */
function inWords(seconds) {
  const value = Math.max(0, Math.round(Number(seconds) || 0));
  if (value < 60) return `${value}s`;
  if (value < 3600) return `${Math.round(value / 60)} min`;
  return `${(value / 3600).toFixed(1)} h`;
}

/* ------------------------------------------------------------------ chat */

/* THE CONVERSATION: chat.js's - the same as in the window the desktop agent
   opens. */
const chat = window.createChat?.({ api, toast }) || null;

/* A CITATION CARD, opened beside what cited it - a record or a state the
   Debugger's trails point at. */
function closeCitation() {
  const open = document.querySelector(".cite-card");
  if (open) open.remove();
  document.removeEventListener("keydown", citationKey, true);
  document.removeEventListener("click", closeCitation);
}

function citationKey(event) {
  if (event.key === "Escape") {
    event.stopPropagation();
    closeCitation();
  }
}

/* What a record says it was read from, in the parts a person can use.

   A reference is written as several clauses separated by semicolons, and one
   of them is the list of raw items the record was built out of - forty event
   ids, then "(+20 more)". Those are the audit trail and they are genuinely
   kept, but printed into a card opened mid-sentence they bury the two lines
   that answer the question: which file, which session, which application.
   So the ids are counted rather than listed, and the count is the useful
   part of them anyway.
*/
const RAW_ITEMS = /^\s*raw items\s*:/i;

function readFrom(references) {
  const clauses = [];
  for (const reference of references || []) {
    for (const part of String(reference).split(";")) {
      const clause = part.trim();
      if (clause) clauses.push(clause);
    }
  }
  const kept = [];
  let counted = 0;
  for (const clause of clauses) {
    if (!RAW_ITEMS.test(clause)) {
      kept.push(clause);
      continue;
    }
    const listed = clause.replace(RAW_ITEMS, "").split(",")
      .filter((piece) => piece.trim()).length;
    const more = /\(\+\s*(\d+)\s*more\)/.exec(clause);
    counted += listed + (more ? Number(more[1]) : 0);
  }
  if (counted) {
    kept.push(`${counted} recorded ${counted === 1 ? "item" : "items"} it was built from`);
  }
  return kept;
}

/* A time a person reads, from a time a machine wrote.

   The record's timestamp arrives as Python writes it - a space between the
   date and the time rather than a T - which is not the format Date parses
   reliably. Shown as-is on the machines where it does not, that reads as a
   fragment of a log rather than a date.
*/
function citedWhen(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const when = new Date(text.replace(" ", "T"));
  if (Number.isNaN(when.getTime())) return text.slice(0, 16);
  return when.toLocaleString(undefined, {
    year: "numeric", month: "short", day: "numeric",
    hour: "2-digit", minute: "2-digit",
  });
}

/* The facts about one memory, laid out as facts.

   Five lines of "label: value" run together as prose read as one paragraph
   of grey text, and the reader was scanning for one of them. Each is given a
   label in its own column, so the eye goes down the labels and stops.
*/
/* What the record actually says, with the matched words marked.

   The card showed a title and a summary. A word that matched is in the
   keywords, and a word the *writer* of the record drew a keyword from is
   usually in the body - so a reader asking "this word is nowhere in this
   record" was looking at the one part of it that did not contain the word,
   twice over, with no way to reach the rest.

   It scrolls rather than truncating, and opens at the first mark: nothing
   is hidden, and the card does not grow to the height of a record. */
function citationText(record) {
  const body = String(record.body || "").trim();
  if (!body) return "";
  return `<div class="cite-body">${markWords(body, record.matched_words)}</div>`;
}

function markWords(text, words) {
  const wanted = (words || []).filter(Boolean)
    .sort((a, b) => b.length - a.length);
  if (!wanted.length) return escapeHtml(text);
  // Matched against the escaped text, so the word is escaped the same way
  // first: a record mentioning `AT&T` holds `AT&amp;T` by the time this
  // runs, and a pattern built from the raw word would never meet it.
  const pattern = new RegExp(
    `(${wanted.map((word) => escapeForRegExp(escapeHtml(word))).join("|")})`, "gi");
  return escapeHtml(text).split(pattern)
    .map((piece, i) => (i % 2 ? `<mark>${piece}</mark>` : piece)).join("");
}

function escapeForRegExp(text) {
  return String(text).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function citationFacts(record) {
  // The keywords that did the matching come first.
  //
  // This row used to show the first eight as stored. A record found by its
  // tenth keyword therefore showed every keyword except the one the reader
  // had opened the card to ask about, with that one inside "(+9 more)".
  const hit = new Set(record.matched_keywords || []);
  const keywords = (record.keywords || []).filter(Boolean)
    .sort((a, b) => (hit.has(b) ? 1 : 0) - (hit.has(a) ? 1 : 0));
  const shownWords = keywords.slice(0, Math.max(8, hit.size));
  const sources = readFrom(record.references);
  const rows = [
    ["why", record.why || ""],
    // Set only when a retrieval trail opened this: the words that found it
    // on that occasion, which is a different question from the keywords it
    // carries. The same memory is found by different words each time.
    ["matched here", (record.matched_here || []).join(", ")],
    // Which of the record's own keywords the matched word sits inside.
    // Not a word from the question - it was being printed in the same list
    // as the question's words, which read as though it had been asked for.
    ["inside its keyword", (record.matched_keywords || []).join(" \u00b7 ")],
    ["when", citedWhen(record.created_at)],
    ["found by", shownWords.join(" · ")
      + (keywords.length > shownWords.length
        ? ` (+${keywords.length - shownWords.length} more)` : "")],
    ["read from", sources],
    ["written by", record.source || ""],
  ];
  return rows.filter(([, value]) => (Array.isArray(value) ? value.length : value))
    .map(([label, value]) => `<div class="cite-row">
      <span class="cite-label">${escapeHtml(label)}</span>
      <span class="cite-value">${Array.isArray(value)
        ? value.map((line) => `<span class="cite-line">${escapeHtml(line)}</span>`).join("")
        : escapeHtml(String(value))}</span></div>`).join("");
}

function showCitation(anchor, record) {
  closeCitation();
  const card = document.createElement("div");
  card.className = "cite-card";
  card.setAttribute("role", "dialog");
  // Section 44.3: whether the agent went looking for this stays on the
  // record. It is one word here rather than a heading, because the same
  // memory can be both offered and found.
  const how = record.found_by === "search" ? "went looking for this"
    : record.found_by === "floor" ? "had this already" : "";
  card.innerHTML = `
    <div class="cite-card-head">
      <strong>${escapeHtml(record.title || "(untitled memory)")}</strong>
      <span class="cite-folder">${escapeHtml(record.folder || "")}</span>
    </div>
    ${record.id ? `<code class="cite-id" title="the record's id">${
      escapeHtml(record.id)}</code>` : ""}
    ${record.summary ? `<p class="cite-summary">${escapeHtml(record.summary)}</p>` : ""}
    ${citationText(record)}
    <div class="cite-facts">${citationFacts(record)}</div>
    ${how ? `<div class="cite-how muted">the agent ${escapeHtml(how)}</div>` : ""}`;
  document.body.appendChild(card);

  // Beside the citation where there is room, otherwise above it: a card that
  // runs off the screen is worse than one on the unexpected side.
  const at = anchor.getBoundingClientRect();
  const box = card.getBoundingClientRect();
  let top = at.bottom + 6;
  if (top + box.height > window.innerHeight - 8) {
    top = Math.max(8, at.top - box.height - 6);
  }
  const left = Math.max(8, Math.min(at.left, window.innerWidth - box.width - 8));
  card.style.top = `${top + window.scrollY}px`;
  card.style.left = `${left + window.scrollX}px`;
  // At the first marked word rather than at the beginning. The reader
  // opened this to see one word in context, and a record runs to pages.
  const first = card.querySelector(".cite-body mark");
  if (first) {
    const box = card.querySelector(".cite-body");
    box.scrollTop = Math.max(0, first.offsetTop - box.offsetTop - 24);
  }

  card.addEventListener("click", (event) => event.stopPropagation());
  document.addEventListener("keydown", citationKey, true);
  setTimeout(() => document.addEventListener("click", closeCitation), 0);
}

/* A text cut to `most` characters, with an ellipsis. */
function shortened(text, most = 80) {
  const one = String(text || "").replace(/\s+/g, " ").trim();
  return one.length > most ? `${one.slice(0, most - 1)}\u2026` : one;
}

/* -------------------------------------------------------------- settings */
/* Whether "Refresh models" is waiting on Codex. Outside the render, because
   Settings is drawn again on a timer while it waits, and the new button must
   still say so. */
let codexModelsRefreshing = false;

/* WHAT THE OPERATING SYSTEM MUST ALLOW, beside each switch that needs it
   (platform_layer/permissions.py): allowed, not allowed, or that it cannot
   be told - and, where it is not allowed or cannot be told, a link to the
   place it is switched on. Looked at again whenever the page comes back
   into view: that is where the user has just been. */
const SYS_PERMISSIONS = {
  full_disk: "Full Disk Access",
  accessibility: "Accessibility",
  automation: "Automation: System Events",
  screen: "Screen & System Audio Recording",
  notifications: "Notifications",
  x11_session: "An X11 session",
};
const SYS_PERMISSION_HOW = {
  macos: {
    notifications: "macOS shows the agent's messages as Script Editor's: allow its "
      + "notifications. macOS does not let a program see whether they are allowed.",
  },
  windows: {
    notifications: "Turn notifications on, and Personal Agent WaterMelon in the list "
      + "of programs that may send them.",
  },
  linux: {
    x11_session: "Wayland lets no program see which window is in front, nor take a "
      + "picture of it. Sign in with an X11 session (for example GNOME on Xorg) for "
      + "this switch to work.",
  },
};
const sysPermissions = { data: null };

function sysPermissionsDraw() {
  const data = sysPermissions.data;
  if (!data) return;
  const items = new Map((data.items || []).map((one) => [one.key, one]));
  $$("[data-sys-permission-for]").forEach((box) => {
    const keys = (data.by_switch || {})[box.dataset.sysPermissionFor] || [];
    const lines = keys.map((key) => items.get(key)).filter((one) => one && one.needed);
    box.innerHTML = lines.map((one) => {
      const state = one.granted === true ? `<span class="sys-permission-state ok">allowed</span>`
        : one.granted === false
          ? `<span class="sys-permission-state missing">not allowed</span>`
          : `<span class="sys-permission-state">cannot be told from here</span>`;
      const how = (SYS_PERMISSION_HOW[data.platform] || {})[one.key]
        || (data.platform === "macos" && ["accessibility", "screen"].includes(one.key)
          ? MAC_ON_BUT_NOT_ALLOWED : "");
      const open = one.granted !== true && one.can_open
        ? ` <button type="button" class="small secondary" data-sys-permission-open="${
          escapeHtml(one.key)}">${data.platform === "windows" ? "Open Windows Settings"
          : "Open System Settings"}</button>` : "";
      return `<div><strong>Needs ${escapeHtml(SYS_PERMISSIONS[one.key] || one.key)}:</strong>
        ${state}${open}${how && one.granted !== true
          ? `<div class="muted">${escapeHtml(how)}</div>` : ""}</div>`;
    }).join("");
  });
}

async function refreshSysPermissions() {
  try {
    sysPermissions.data = await api.get("/api/permissions");
    sysPermissionsDraw();
  } catch (err) {
    console.warn(err);
  }
}

document.addEventListener("click", async (event) => {
  const at = event.target.closest && event.target.closest("[data-sys-permission-open]");
  if (!at) return;
  at.disabled = true;
  try {
    sysPermissions.data = await api.post("/api/permissions/open",
      { key: at.dataset.sysPermissionOpen });
    sysPermissionsDraw();
  } catch (err) {
    toast(err.message, "error");
    at.disabled = false;
  }
});
async function loadSettings() {
  // The panel needs to know which values are the user's own (section 12.1).
  const [data, models, defaults] = await Promise.all([
    api.get("/api/settings"),
    api.get("/api/models"),
    api.get("/api/settings/defaults"),
  ]);
  renderModels(models, data.choices);
  renderSettings({ ...data, user_defaults: defaults.user_defaults || {} });
  loadWebSearch();
  refreshSysPermissions();
}

/* THE WEB SEARCH: whether a Brave Search key is set - never the key. */
function renderWebSearch(status) {
  const line = $("#web-search-status");
  if (!line || !status) return;
  line.textContent = status.engine === "brave"
    ? (status.from_environment ? "Brave Search, with the key set in the environment."
      : "Brave Search, with your key.")
    : "No key: DuckDuckGo's page is tried, and may refuse.";
  const remove = $("#web-search-remove");
  if (remove) remove.disabled = !status.key_set;
  const chosen = $("#web-search-with");
  if (chosen && status.with) chosen.value = status.with;
}

$("#web-search-with")?.addEventListener("change", async (event) => {
  try {
    renderWebSearch(await api.post("/api/search/with", { with: event.target.value }));
    toast(event.target.value === "model" ? "The model's own search"
      : "The app's search: Brave, or DuckDuckGo");
  } catch (err) {
    toast(err.message, "error");
  }
});

async function loadWebSearch() {
  try { renderWebSearch(await api.get("/api/search")); } catch (err) { /* said later */ }
}

$("#web-search-form")?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const input = event.target.elements.api_key;
  const key = input.value.trim();
  if (!key) return;
  try {
    const said = await api.post("/api/search/key", { api_key: key });
    input.value = "";
    renderWebSearch(said);
    toast("Brave Search key saved");
  } catch (err) {
    toast(err.message, "error");
  }
});

$("#web-search-remove")?.addEventListener("click", async () => {
  try {
    renderWebSearch(await api.post("/api/search/key/remove", {}));
    toast("Brave Search key removed");
  } catch (err) {
    toast(err.message, "error");
  }
});

/* The models as last read: the list, and every provider (`renderModels`). */
let modelsNow = null;

/* An API, or a service on this computer (a client, or the offline stand-in). */
function modelKindOf(p) {
  return (p || {}).kind === "client" || (p || {}).kind === "offline" ? "client" : "api";
}

function renderModels(models, choices) {
  modelsNow = models;
  // Every part of the agent uses the list: one model, the first that works.
  renderModelChain(models);

  // -- every provider and its credential, by kind ----------------------------------
  const byKind = (kind) => models.providers.filter((p) => (p.kind || "api") === kind);
  const providerRow = (p) => `<tr><td>${escapeHtml(p.display_name)}</td>
        <td>${p.authentication_methods.join(", ")}</td>
        <td><span class="badge ${authClass(p.auth_status.state)}">${p.auth_status.state}</span></td>
        <td class="muted">${escapeHtml(p.auth_status.detail || "")}</td>
        <td class="muted">${p.usage.total_tokens} tokens</td></tr>`;
  const group = (kind) => {
    const rows = byKind(kind);
    return rows.length ? `<tr class="provider-kind"><th colspan="5">${
      escapeHtml(PROVIDER_KINDS[kind] || kind)}</th></tr>${rows.map(providerRow).join("")}` : "";
  };
  $("#model-register-panel").innerHTML = `
    <table><thead><tr><th>Provider</th><th>Methods</th><th>Credential</th><th></th>
      <th>Usage</th></tr></thead>
      <tbody>${["client", "api", "offline"].map(group).join("")}</tbody></table>
    <div class="muted">Credential storage: ${models.credential_backend.backend}.</div>`;

  // -- adding one: what it is, which one, its key or sign-in, its model -------------
  const providerSelect = $('#auth-form select[name="provider"]');
  const methodSelect = $('#auth-form select[name="method"]');
  const previous = { provider: providerSelect.value, method: methodSelect.value };
  const chosenKind = () =>
    ($('#auth-form input[name="kind"]:checked') || {}).value || "api";
  const fillProviders = () => {
    const kind = chosenKind();
    providerSelect.innerHTML = models.providers.filter((p) => modelKindOf(p) === kind)
      .map((p) => `<option value="${escapeHtml(p.provider)}">${escapeHtml(p.display_name)}</option>`)
      .join("");
  };
  fillProviders();
  if (previous.provider && [...providerSelect.options].some((o) => o.value === previous.provider)) {
    providerSelect.value = previous.provider;
  }
  $$('#auth-form input[name="kind"]').forEach((radio) => {
    radio.onchange = () => {
      fillProviders();
      $("#auth-result").innerHTML = "";
      updateMethods(null);
    };
  });

  const currentProvider = () =>
    models.providers.find((p) => p.provider === providerSelect.value);

  const methodDetails = () => {
    const provider = currentProvider();
    if (provider?.authentication_method_details) return provider.authentication_method_details;
    // A provider that predates the richer model: everything it lists is usable.
    return (provider?.authentication_methods || []).map((m) => ({ method: m, available: true }));
  };

  const updateMethods = (keepMethod) => {
    const details = methodDetails();
    // Section 77, as amended: a method that cannot be completed on this machine
    // is still shown — disabled, with the reason — rather than hidden, so the
    // user is never left believing the provider does not offer it.
    methodSelect.innerHTML = details
      .map((d) => `<option value="${d.method}"${d.available ? "" : " disabled"}>${
        METHOD_LABELS[d.method] || d.method}${d.available ? "" : " — unavailable here"}</option>`)
      .join("");
    const usable = details.filter((d) => d.available).map((d) => d.method);
    if (keepMethod && usable.includes(keepMethod)) methodSelect.value = keepMethod;
    else if (usable.length) methodSelect.value = usable[0];
    updateMethodFields();
  };

  // Section 77: show only the inputs the *selected method* actually uses.
  const updateMethodFields = () => {
    const method = methodSelect.value;
    $(".api-key-field").style.display = method === "api_key" ? "" : "none";
    updateApiFields();
    updateModelChoice();
    const chosen = currentProvider() || {};
    const ready = (chosen.auth_status || {}).state === "authenticated"
      || (chosen.authentication_methods || []).includes("none");
    $("#auth-submit").textContent = ready ? "Add to the list"
      : method === "account_login" ? "Sign in"
      : (chosen.models || []).length ? "Connect and add" : "Connect";
    if (method === "account_login") renderLoginTools();
    const blocked = methodDetails().filter((d) => !d.available);
    const hint = METHOD_HINTS[method] || "";
    const notes = blocked.map((d) => {
      const link = d.remedy_url
        ? ` <a href="${escapeHtml(d.remedy_url)}" target="_blank" rel="noopener noreferrer">How to install</a>`
        : "";
      return `<div class="method-blocked"><strong>${escapeHtml(
        METHOD_LABELS[d.method] || d.method)}</strong> is not available here: ${
        escapeHtml(d.reason || "")}. ${escapeHtml(d.remedy || "")}${link}</div>`;
    }).join("");
    $("#auth-hint").innerHTML = hint + notes;
    if (method !== "account_login") hideLoginPanel();
  };

  // AN API THAT SPEAKS THE OPENAI CHAT API: its address - its own, or one
  // the user gives (needed for "Other") - where a key is made, and what it
  // costs: billed by the token, a work run reads the same text again and
  // again, and how much of that its cache serves.
  function updateApiFields() {
    const p = currentProvider() || {};
    const takesAddress = p.default_base_url !== undefined;
    const field = $(".base-url-field");
    const input = $('#auth-form input[name="base_url"]');
    if (field && input) {
      field.hidden = !takesAddress;
      input.placeholder = p.default_base_url || "https://.../v1";
      input.required = Boolean(takesAddress && p.needs_base_url);
      if (input.dataset.provider !== p.provider) {
        // Its address shown when it is not the service's own.
        input.value = takesAddress && p.base_url && p.base_url !== p.default_base_url
          ? p.base_url : "";
        input.dataset.provider = p.provider || "";
      }
    }
    const note = $("#provider-key-note");
    if (note) {
      const parts = [];
      if (p.key_page) {
        parts.push(`<a href="${escapeHtml(p.key_page)}" target="_blank"
          rel="noopener noreferrer">Get a ${escapeHtml(p.display_name)} key</a>`);
      }
      if (p.note) parts.push(escapeHtml(p.note));
      note.innerHTML = parts.join(" · ");
      note.hidden = !parts.length;
    }
    const billing = $("#api-billing");
    if (billing) {
      const api = (p.kind || "api") === "api" && p.provider !== "offline";
      billing.hidden = !api;
      billing.innerHTML = api ? apiBillingNote(p) : "";
    }
  }

  // ITS MODEL, CHOSEN from those the provider offers. An API lists its
  // models once it has a key: until then, connect first. One that lists
  // none - an address of the user's - is the only one whose model is typed.
  function updateModelChoice() {
    const p = currentProvider() || {};
    const select = $('#auth-form select[name="model"]');
    const other = $(".model-other-field");
    const models = p.models || [];
    const ready = (p.auth_status || {}).state === "authenticated"
      || (p.authentication_methods || []).includes("none");
    // Filled again when the provider, its list or its connection changes.
    const shown = `${p.provider}|${models.map((m) => m.id).join(",")}|${ready}`;
    if (select && select.dataset.shown !== shown) {
      select.innerHTML = models.length
        ? models.map((m) => `<option value="${escapeHtml(m.id)}">${
            escapeHtml(m.display_name && m.display_name !== m.id
              ? `${m.display_name} (${m.id})` : m.id)}</option>`).join("")
        : `<option value="" disabled selected>${ready
            ? "it lists no models: name it below"
            : "connect it first: its models are listed then"}</option>`;
      select.dataset.shown = shown;
    }
    if (other) other.hidden = Boolean(models.length) || !ready;
    updateEffortChoice();
    if (select) select.onchange = updateEffortChoice;
    const state = $("#model-add-state");
    if (state) {
      const auth = p.auth_status || {};
      state.textContent = p.provider ? `${auth.state === "authenticated" ? "Ready" : "Not connected yet"}${
        auth.detail ? ` - ${auth.detail}` : ""}` : "";
    }
  }

  // HOW HARD IT THINKS: the levels the chosen model takes, or nothing to
  // choose for one that takes none.
  function updateEffortChoice() {
    const p = currentProvider() || {};
    const chosen = $('#auth-form select[name="model"]')?.value;
    const levels = modelEfforts(p, chosen);
    const field = $(".model-effort-field");
    const box = $('#auth-form select[name="effort"]');
    if (!field || !box) return;
    field.hidden = !levels.length;
    box.innerHTML = effortOptions(levels, "");
  }

  providerSelect.onchange = () => {
    $("#auth-result").innerHTML = "";
    updateMethods(null);
  };
  methodSelect.onchange = () => {
    $("#auth-result").innerHTML = "";
    updateMethodFields();
  };
  updateMethods(previous.method);
}

/* THE LIST, IN ORDER: each model, how it stands, its own model to choose,
   and up, down, remove. */
const MODEL_STATE_WORDS = {
  authentication_required: "sign in again", credential_invalid: "key not accepted",
  quota_exhausted: "credit or limit used up", rate_limited: "limited for now",
  model_unavailable: "model not offered", provider_unavailable: "not available",
  network_unavailable: "unreachable", permission_denied: "refused", unknown_error: "failed",
};

function renderModelChain(models) {
  const host = $("#model-chain");
  if (!host) return;
  const chain = models.chain || [];
  host.innerHTML = chain.map((one, i) => {
    const p = (models.providers || []).find((x) => x.provider === one.provider) || {};
    const av = one.availability;
    // Signed in - or needing no sign-in AND found: a local client that is
    // not installed (Codex, Claude Code) needs no sign-in either, and was
    // shown "ready" while every call to it said it was not installed.
    const authState = (one.auth_status || p.auth_status || {}).state;
    const ready = authState === "authenticated"
      || ((p.authentication_methods || []).includes("none")
          && !["not_configured", "authentication_required"].includes(authState));
    let badge;
    if (av && !av.available) {
      badge = `<span class="badge ${av.requires_user_action ? "err" : "warn"}">${
        escapeHtml(MODEL_STATE_WORDS[av.state] || av.state)}</span>`;
    } else if (models.answered === one.label) {
      badge = `<span class="badge ok">answering</span>`;
    } else {
      badge = `<span class="badge ${ready ? "ok" : "warn"}">${ready ? "ready" : "not connected"}</span>`;
    }
    const offered = (p.models || []).map((m) => m.id);
    if (!offered.includes(one.model)) offered.unshift(one.model);
    return `<li class="model-link" data-chain="${i}">
      <span class="chain-n">${i + 1}</span>
      <span class="chain-name"><strong>${escapeHtml(one.display_name || one.provider)}</strong>
        <span class="muted">${modelKindOf(one) === "api" ? "API, billed by the token"
          : "on this computer"}</span></span>
      <select class="chain-model" data-chain-model="${i}" aria-label="Its model">${
        offered.map((id) => `<option value="${escapeHtml(id)}"${id === one.model ? " selected" : ""}>${
          escapeHtml(id)}</option>`).join("")}</select>
      ${(one.efforts || []).length ? `<select class="chain-effort" data-chain-effort="${i}"
        aria-label="Reasoning effort" title="Reasoning effort">${
        effortOptions(one.efforts, one.effort || "")}</select>` : ""}
      ${badge}
      <button type="button" class="small secondary chain-sees${one.sees_images ? " on" : ""}"
        data-chain-sees="${i}" data-provider="${escapeHtml(one.provider)}"
        data-model="${escapeHtml(one.model)}" data-sees="${one.sees_images ? "1" : ""}"
        title="${one.sees_images
          ? "Given pictures as pictures. Click if it reads text only."
          : "Given the words read in a picture, on this computer. Click if it can see pictures."
        }">${one.sees_images ? "Sees pictures" : "Text only"}</button>
      ${one.provider === "codex" ? `<button type="button" class="small secondary"
        data-chain-refresh title="Ask Codex for its models now">Refresh models</button>` : ""}
      <button type="button" class="small secondary" data-chain-up="${i}"${
        i === 0 ? " disabled" : ""} aria-label="Up">↑</button>
      <button type="button" class="small secondary" data-chain-down="${i}"${
        i === chain.length - 1 ? " disabled" : ""} aria-label="Down">↓</button>
      <button type="button" class="small secondary" data-chain-remove="${i}">Remove</button>
      ${av && !av.available && av.reason ? `<div class="chain-why muted">${
        escapeHtml(av.reason)}</div>` : ""}
    </li>`;
  }).join("");
  // EVERY ONE REMOVED: said, so an empty list does not look like a fault.
  if (!chain.length) {
    host.innerHTML = `<li class="muted model-chain-empty">No model on the list.
      Nothing that needs one - states, summaries, work, chat - runs until you add one.</li>`;
  }
  // WHAT THE ORDER COSTS: an API billed by the token below a service on a
  // subscription answers whenever the service cannot - its usage limit
  // reached overnight, its sign-in expired - and a long run reads millions
  // of tokens.
  const cost = $("#model-chain-cost");
  if (cost) {
    const firstApi = chain.findIndex((one) => modelKindOf(one) === "api"
      && one.provider !== "offline");
    const serviceAbove = firstApi > 0 && chain.slice(0, firstApi)
      .some((one) => modelKindOf(one) === "client" && one.provider !== "offline");
    cost.hidden = !serviceAbove;
    cost.innerHTML = serviceAbove ? `<strong>Mind the order.</strong> ${
      escapeHtml(chain[firstApi].display_name || chain[firstApi].provider)} is billed by the
      token, and it is below a service you use on a subscription: whenever that service
      cannot answer - its usage limit reached, its sign-in expired - the work goes on with
      ${escapeHtml(chain[firstApi].display_name || chain[firstApi].provider)} and is billed.
      A two-hour work run read about 19 million tokens of input. Remove it, or keep it
      only if you want the work to go on that way.` : "";
  }
}

/* The list as it stands, as {provider, model, effort}. */
function chainNow() {
  return ((modelsNow || {}).chain || []).map((one) => ({ provider: one.provider, model: one.model,
                                                          ...(one.effort ? { effort: one.effort } : {}) }));
}

/* The levels of thinking a provider's model takes, as its catalog says. */
function modelEfforts(provider, model) {
  const one = ((provider || {}).models || []).find((m) => m.id === model) || {};
  return (one.reasoning_efforts || []).filter((level) => level !== "default");
}

function effortOptions(levels, chosen) {
  return [`<option value=""${chosen ? "" : " selected"}>default - the model's own</option>`,
    ...levels.map((level) => `<option value="${escapeHtml(level)}"${
      level === chosen ? " selected" : ""}>${escapeHtml(level)}</option>`)].join("");
}

async function saveModelChain(chain, said) {
  try {
    await api.post("/api/models/chain", { chain });
    if (said) toast(said);
  } catch (err) {
    toast(err.message, "error");
  }
  await loadSettings();
}

document.addEventListener("click", async (event) => {
  const at = (name) => event.target.closest?.(`[${name}]`);
  const chain = chainNow();
  const up = at("data-chain-up");
  const down = at("data-chain-down");
  if (up || down) {
    const i = Number((up || down).getAttribute(up ? "data-chain-up" : "data-chain-down"));
    const j = up ? i - 1 : i + 1;
    if (j < 0 || j >= chain.length) return;
    [chain[i], chain[j]] = [chain[j], chain[i]];
    await saveModelChain(chain, "The order is changed");
    return;
  }
  const sees = at("data-chain-sees");
  if (sees) {
    try {
      await api.post("/api/models/sees_images", { provider: sees.dataset.provider,
        model: sees.dataset.model, sees: !sees.dataset.sees });
    } catch (err) {
      toast(err.message, "error");
    }
    await loadSettings();
    return;
  }
  const remove = at("data-chain-remove");
  if (remove) {
    chain.splice(Number(remove.getAttribute("data-chain-remove")), 1);
    await saveModelChain(chain, "Removed from the list");
    return;
  }
  if (at("data-chain-refresh")) {
    try {
      await api.post("/api/models/codex/refresh", {});
    } catch (err) {
      toast(err.message, "error");
    }
    await loadSettings();
    return;
  }
  if (event.target.closest?.("#model-add-open")) {
    $("#auth-form").hidden = false;
    $("#model-add-open").hidden = true;
    return;
  }
  if (event.target.closest?.("#model-add-cancel")) {
    $("#auth-form").hidden = true;
    $("#model-add-open").hidden = false;
  }
});

document.addEventListener("change", async (event) => {
  const effortAt = event.target.closest?.("[data-chain-effort]");
  if (effortAt) {
    const chain = chainNow();
    const one = chain[Number(effortAt.dataset.chainEffort)];
    if (effortAt.value) one.effort = effortAt.value;
    else delete one.effort;
    await saveModelChain(chain, "Its reasoning effort is changed");
    return;
  }
  const at = event.target.closest?.("[data-chain-model]");
  if (!at) return;
  const chain = chainNow();
  const model = at.value.trim();
  if (!model) return;
  // Another model: its own levels - the effort of the last is not carried.
  chain[Number(at.dataset.chainModel)] = { provider: chain[Number(at.dataset.chainModel)].provider,
                                           model };
  await saveModelChain(chain, "Its model is changed");
});

/* What each kind of provider is called where they are grouped. */
const PROVIDER_KINDS = {
  client: "Command-line and desktop clients",
  api: "APIs",
  offline: "Offline",
};

/* AN API IS BILLED BY THE TOKEN. A work run sends its system prompt, its
   tools and every turn before this one with each call: a two-hour run read
   some nineteen million tokens of input, nearly all of it read before. What
   a service serves from its prompt cache costs about a tenth - so it is said
   whether this one caches, and how. A client (Claude Code, Codex) uses its
   subscription instead. */
function apiBillingNote(p) {
  const caching = {
    auto: "It caches a repeated prompt on its own, and what it serves from the cache is counted apart.",
    marked: "Its Claude and Gemini models cache only what a request marks: the agent marks the system prompt and the newest message, as it does for Anthropic; the others cache on their own.",
    unknown: "Whether this service caches a repeated prompt is not known: if it does not, every call is billed at the full price.",
  }[p.caching || (p.provider === "anthropic" ? "auto" : "unknown")] || "";
  return `<strong>Billed by the token.</strong> A work run reads the same text again and
    again - a two-hour run read about 19 million tokens of input, most of it read before.
    Read from a cache, that costs about a tenth of the full price; even so a long run
    can cost real money. ${escapeHtml(caching)} Claude Code and Codex use your
    subscription instead, and are not billed by the token.
    <br><strong>Where you put it on the list matters.</strong> Below a service on a
    subscription, it answers whenever that service cannot - its usage limit reached
    (overnight, say), its sign-in expired - and that work is billed here. Put it below
    only if you want the work to go on that way.`;
}

const METHOD_LABELS = {
  api_key: "API key",
  account_login: "Account login",
  oauth: "OAuth",
  none: "No credential required",
};

const METHOD_HINTS = {
  api_key:
    "The key is stored by the credential manager (OS keychain when available) and is never " +
    "shown again, logged, or sent to the model.",
  account_login:
    "Opens your browser to sign in with your Anthropic account, then finishes here — " +
    "paste back the code the sign-in page gives you. No terminal, and no API key to " +
    "manage. The sign-in is performed by a provider tool already installed on this " +
    "machine; which one, and what it bills to, is shown below before you start. The " +
    "credential it mints is stored by the credential manager and never shown again.",
  none: "This provider runs locally and needs no credential.",
};

function renderAuthResult(status) {
  const cls = authClass(status.state);
  $("#auth-result").innerHTML = `
    <span class="badge ${cls}">${escapeHtml(status.state)}</span>
    <span class="muted">${escapeHtml(status.detail || "")}</span>`;
}

function availabilityBadge(availability) {
  if (!availability) return '<span class="badge">not checked</span>';
  const cls = availability.available ? "ok" : availability.requires_user_action ? "err" : "warn";
  return `<span class="badge ${cls}">${availability.state}</span>
    <span class="muted">${escapeHtml(availability.reason || "")}</span>`;
}

function authClass(state) {
  if (state === "authenticated") return "ok";
  if (["invalid", "revoked", "error"].includes(state)) return "err";
  return "warn";
}

/* --------------------------------------------- account sign-in (75.2)
   The browser does the authorization; this window starts it, shows where the
   user is going, and takes the code back. Nothing sends the user to a terminal.
*/
/* Section 75.2: name the tool, the account and the billing before the user
   commits to a sign-in. */
async function renderLoginTools() {
  const host = $("#login-tools");
  if (!host) return;
  try {
    const provider = $('#auth-form select[name="provider"]').value;
    const { tools } = await api.get(
      `/api/models/login/tools?provider=${encodeURIComponent(provider)}`);
    const usable = (tools || []).filter((t) => t.usable);
    if (!usable.length) {
      host.hidden = true;
      return;
    }
    const tool = usable[0];
    host.hidden = false;
    host.innerHTML = `
      <div><strong>Signs in with ${escapeHtml(tool.tool)}</strong>${
        tools.filter((t) => t.installed && t !== tool).length
          ? ` <span class="muted">(also installed: ${escapeHtml(
              tools.filter((t) => t.installed && t !== tool)
                   .map((t) => t.tool).join(", "))})</span>`
          : ""}</div>
      <div class="muted">${escapeHtml(tool.account_note)}</div>
      <div class="muted">${tool.returns_token
        ? "The token it mints is stored by this application's credential manager, so it " +
          "travels with the agent root only when <code>credential_storage</code> is set " +
          "to <code>agent_root</code>."
        : "The credential is stored by " + escapeHtml(tool.tool) + " outside the agent " +
          "root, so it does not travel when you copy the root to another machine."
      }</div>`;
  } catch (err) {
    host.hidden = true;
  }
}

function hideLoginPanel() {
  const panel = $("#login-panel");
  if (panel) panel.hidden = true;
}

function renderLoginPanel(login) {
  const panel = $("#login-panel");
  if (!panel) return;
  panel.hidden = false;
  $("#login-step").textContent = login.tool
    ? `${login.tool}: ${login.detail || ""}`
    : (login.detail || "");
  const url = login.authorization_url;
  $("#login-url").hidden = !url;
  if (url) {
    const link = $("#login-link");
    link.href = url;
    link.textContent = url;
  }
  $("#login-code-row").hidden = !login.awaiting_code;
  if (login.awaiting_code) $("#login-code").focus();
  if (login.finished) {
    $("#login-code-row").hidden = true;
    $("#login-url").hidden = true;
    $("#login-step").textContent = login.state === "completed"
      ? `Signed in${login.tool ? ` through ${login.tool}` : ""}.`
      : $("#login-step").textContent;
  }
}

async function startAccountLogin(provider) {
  renderLoginPanel({ detail: "starting the sign-in…", awaiting_code: false });
  try {
    const result = await api.post("/api/models/login/start", { provider });
    renderLoginPanel(result.login);
    watchAccountLogin(provider);
    return result.login;
  } catch (err) {
    renderLoginPanel({ detail: err.message, finished: true });
    return null;
  }
}

/* The browser can complete the authorization by itself, in which case there is
   no code to paste and the page would otherwise sit waiting for one. */
let loginWatch = null;
function watchAccountLogin(provider) {
  if (loginWatch) clearInterval(loginWatch);
  loginWatch = setInterval(async () => {
    try {
      const { login } = await api.get(
        `/api/models/login/status?provider=${encodeURIComponent(provider)}`);
      renderLoginPanel(login);
      if (!login.finished) return;
      clearInterval(loginWatch);
      loginWatch = null;
      if (login.state === "completed") {
        const models = await api.get("/api/models");
        const entry = models.providers.find((p) => p.provider === provider);
        renderAuthResult(entry?.auth_status || { state: "authenticated", detail: login.detail });
        toast(`${provider}: signed in`);
        await loadSettings();
      } else if (login.state !== "cancelled") {
        renderAuthResult({ state: "error", detail: login.detail });
      }
    } catch (err) {
      clearInterval(loginWatch);
      loginWatch = null;
    }
  }, 2000);
}

$("#login-complete")?.addEventListener("click", async () => {
  const provider = $('#auth-form select[name="provider"]').value;
  const code = $("#login-code").value;
  renderLoginPanel({ detail: "completing the sign-in…", awaiting_code: false });
  try {
    const result = await api.post("/api/models/login/complete", { provider, code });
    $("#login-code").value = "";
    renderLoginPanel(result.login);
    renderAuthResult(result.auth_status);
    toast(`${provider}: ${result.auth_status.state}`,
          result.auth_status.state === "authenticated" ? "info" : "error");
    await loadSettings();
  } catch (err) {
    renderLoginPanel({ detail: err.message, finished: true });
    toast(err.message, "error");
  }
});

$("#login-cancel")?.addEventListener("click", async () => {
  const provider = $('#auth-form select[name="provider"]').value;
  if (loginWatch) {
    clearInterval(loginWatch);
    loginWatch = null;
  }
  try {
    await api.post("/api/models/login/cancel", { provider });
  } catch (err) {
    /* cancelling is best effort */
  }
  hideLoginPanel();
});

/* ADD A MODEL: connected first - a key given is stored and tried, a
   sign-in begins - then its model put at the end of the list. */
$("#auth-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const form = new FormData(event.target);
  const provider = String(form.get("provider") || "");
  const method = form.get("method");
  const key = String(form.get("api_key") || "").trim();
  const known = ((modelsNow || {}).providers || []).find((p) => p.provider === provider) || {};
  let ready = (known.auth_status || {}).state === "authenticated"
    || (known.authentication_methods || []).includes("none");
  try {
    if ((method === "api_key" && key) || (method === "account_login" && !ready)) {
      $("#auth-result").innerHTML = '<span class="muted">checking…</span>';
      const addressed = !$(".base-url-field")?.hidden;
      const result = await api.post("/api/models/authenticate", {
        provider, method, api_key: key,
        // An API at an address of the user's: sent, empty too - then its own.
        ...(addressed ? { base_url: String(form.get("base_url") || "").trim() } : {}),
      });
      const status = result.auth_status;
      renderAuthResult(status);
      if (method === "account_login" && status.state === "authenticating") {
        // The sign-in is running: show where the browser went and take the
        // code; Add again once it is done.
        renderLoginPanel(await api.get("/api/models/login/status?provider=" +
          encodeURIComponent(provider)).then((r) => r.login));
        watchAccountLogin(provider);
        return;
      }
      if (status.state !== "authenticated") {
        if (method === "account_login") hideLoginPanel();
        toast(`${known.display_name || provider}: ${status.state}`, "error");
        return;
      }
      $('#auth-form input[name="api_key"]').value = "";
      ready = true;
    }
    if (!ready) {
      renderAuthResult({ state: "not_configured", detail: method === "api_key"
        ? "enter its key first" : "it is not ready on this computer" });
      return;
    }
    const fresh = await api.get("/api/models");
    const entry = (fresh.providers || []).find((p) => p.provider === provider) || {};
    const model = String(form.get("model") || "").trim()
      || String(form.get("model_other") || "").trim();
    if (!model) {
      // Just connected: its models are listed now, to choose from.
      await loadSettings();
      await openModelSettings(provider);
      renderAuthResult({ state: "authenticated",
                         detail: "connected - now choose its model, then Add" });
      return;
    }
    let chain = (fresh.chain || []).map((one) => ({ provider: one.provider, model: one.model,
                                                    ...(one.effort ? { effort: one.effort } : {}) }));
    // The offline stand-in, alone, is what there was before any model.
    if (chain.length === 1 && chain[0].provider === "offline") chain = [];
    if (chain.some((one) => one.provider === provider && one.model === model)) {
      toast("It is on the list already");
      return;
    }
    const effort = String(form.get("effort") || "");
    chain.push({ provider, model, ...(effort ? { effort } : {}) });
    await api.post("/api/models/chain", { chain });
    toast(`${entry.display_name || provider} added as number ${chain.length}`);
    $("#auth-form").hidden = true;
    $("#model-add-open").hidden = false;
    $("#auth-result").innerHTML = "";
    await loadSettings();
  } catch (err) {
    renderAuthResult({ state: "error", detail: err.message });
    toast(err.message, "error");
  }
});

$("#logout-btn").addEventListener("click", async () => {
  const provider = $('#auth-form select[name="provider"]').value;
  await api.post("/api/models/logout", { provider });
  toast("logged out");
  loadSettings();
});

/* Section 12, as amended: a value that identifies something on the machine is
   chosen with the platform's chooser. Typing stays available. */
const CHOOSERS = {
  directory: {
    endpoint: "/api/settings/choose-directory",
    addLabel: "Add directory…",
    oneLabel: "Choose directory…",
    empty: "No directory chosen.",
    typed: "no chooser on this machine - type a path and press Enter",
    // A directory is stored as the path itself.
    valueOf: (result) => result.selected,
    check: async (value) => api.post("/api/settings/check-directory", { path: value }),
  },
  application: {
    endpoint: "/api/settings/choose-application",
    addLabel: "Add application…",
    oneLabel: "Choose application…",
    empty: "No application chosen.",
    typed: "no chooser on this machine - type a name and press Enter",
    // Activity is reported by the application's own name, so that is stored.
    valueOf: (result) => result.name || result.selected,
    check: async () => ({ usable: true, problem: "" }),
  },
};

/* Section 18, as amended: a detected list, ticked rather than typed.

   The value stays a newline-separated list of names, which is what every
   reader of this setting already expects - so what changes is the editor, not
   the stored shape, and a name for something not currently installed survives
   being shown rather than being silently dropped.
*/
function multiChoiceControl(field, value, data) {
  const options = field.choices || (data.choices || {})[field.choices_source] || [];
  const notes = (data.choice_notes || {})[field.key] || {};
  // "*": every one offered - one offered later too.
  const every = String(value ?? "").split("\n").some((line) => line.trim() === "*");
  const chosen = every ? options.map(String) : String(value ?? "")
    .split("\n").map((line) => line.trim()).filter(Boolean);

  const box = document.createElement("div");
  box.className = "multi-choice";
  box.dataset.key = field.key;

  const known = new Set(options.map(String));
  // A stored list is one per line, but not every setting of this shape was
  // written by this control: the pinned memory languages are stored as
  // "zh,en", and read a line at a time that is one entry named "zh,en" -
  // shown ticked, marked "not offered here", with the real zh and en sitting
  // unticked beneath it. So a line that is not an option, but is entirely
  // made of options separated by commas, is read as those options.
  const split = chosen.flatMap((line) => {
    if (known.has(line)) return [line];
    const parts = line.split(",").map((s) => s.trim()).filter(Boolean);
    return parts.length > 1 && parts.every((part) => known.has(part))
      ? parts : [line];
  });
  // Anything chosen that is no longer offered is still shown, ticked, so that
  // opening this panel on another machine does not quietly discard it.
  const rows = [...options.map(String),
                ...split.filter((name) => !known.has(name))];

  if (!rows.length) {
    box.innerHTML = `<div class="muted">${field.choices_source
      ? "No assistants were found on this machine."
      : "Nothing to choose from."}</div>`;
    box.value = "";
    return box;
  }

  // The thing being chosen reads first and the control that chooses it sits
  // at the right edge, so the column of ticks lines up and the eye runs down
  // the names rather than down a column of boxes with names hanging off them.
  box.innerHTML = rows.map((name) => {
    // Where an installed assistant keeps its transcripts is not a thing the
    // reader is deciding about. That it is missing is.
    const detected = notes[name] || "";
    const note = detected.startsWith("found at")
      ? "" : (detected || (known.has(name) ? "" : "not offered here"));
    // The tick first, in the column every other switch's tick is in.
    return `<label class="multi-choice-row">
      <input type="checkbox" value="${escapeHtml(name)}"${
        split.includes(name) ? " checked" : ""}${
        field.readonly ? " disabled" : ""}>
      <span class="multi-choice-name">${escapeHtml(name)}</span>
      ${note ? `<span class="muted multi-choice-where">${escapeHtml(note)}</span>` : ""}
    </label>`;
  }).join("") + (field.choices_source
    ? `<div class="muted multi-choice-note">What is ticked is
    recorded. Nothing ticked records nothing; all ticked is every one found, one
    installed later too.</div>`
    : "");

  // The control reads and writes like an input, so the surrounding code that
  // gathers values does not need to know this one is different.
  Object.defineProperty(box, "value", {
    get() {
      const ticked = [...box.querySelectorAll("input:checked")].map((input) => input.value);
      // Every one offered, by an assistant's list: every one, later ones too.
      return field.choices_source && options.length
        && options.every((name) => ticked.includes(String(name))) ? "*" : ticked.join("\n");
    },
    set(next) {
      const wanted = String(next ?? "").split("\n").map((s) => s.trim());
      box.querySelectorAll("input").forEach((input) => {
        input.checked = wanted.includes("*") || wanted.includes(input.value);
      });
    },
  });
  return box;
}

/* A duration, in the unit the reader thinks in.

   Every interval here is stored in seconds, because that is what the loops
   that read them expect, and every one of them was also *shown* in seconds.
   "How often should the agent wake?" answered as `3600` is a unit conversion
   the reader has to do in their head, in a field labelled "(s)", to check a
   value they never chose - and the two settings that decide most of what the
   agent costs when nobody is talking to it are exactly those.

   So the stored value stays in seconds and the control converts. The unit
   starts as the largest one the current value divides into evenly, because a
   value written as 1 hour was meant as an hour rather than as 3600 of
   something.
*/
const DURATION_UNITS = [["hours", 3600], ["minutes", 60], ["seconds", 1]];

function durationUnit(seconds) {
  for (const [name, size] of DURATION_UNITS) {
    if (seconds >= size && seconds % size === 0) return [name, size];
  }
  return ["seconds", 1];
}

function inWords(seconds) {
  const [name, size] = durationUnit(seconds);
  const many = Math.round(seconds / size);
  const one = name.replace(/s$/, "");
  if (name === "seconds" && seconds < 60) return `every ${many} ${many === 1 ? one : name}`;
  return many === 1 ? `every ${one}` : `every ${many} ${name}`;
}

function durationControl(field, value) {
  const seconds = Math.max(0, Number(value) || 0);
  const [unit, size] = durationUnit(seconds);

  const box = document.createElement("div");
  box.className = "duration";
  const amount = document.createElement("input");
  amount.type = "number";
  amount.className = "duration-amount";
  amount.value = String(Math.round(seconds / size));
  amount.min = "1";
  const chooser = document.createElement("select");
  chooser.className = "duration-unit";
  DURATION_UNITS.forEach(([name]) => {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    option.selected = name === unit;
    chooser.appendChild(option);
  });
  // What the number means, beside the number. This is the part that makes an
  // interval readable at a glance rather than after arithmetic.
  const says = document.createElement("span");
  says.className = "muted duration-says";
  says.textContent = inWords(seconds);
  box.append(amount, chooser, says);

  const held = () => {
    const chosen = DURATION_UNITS.find(([name]) => name === chooser.value);
    const total = Math.round((Number(amount.value) || 0) * (chosen ? chosen[1] : 1));
    const floor = field.minimum === null || field.minimum === undefined
      ? 1 : Number(field.minimum);
    const ceiling = field.maximum === null || field.maximum === undefined
      ? total : Number(field.maximum);
    return Math.min(Math.max(total, floor), ceiling);
  };
  // Changing the unit is not changing the interval: switching "3600 seconds"
  // to hours must read 1 hour, not 3600 hours. Converted from what the
  // control is holding now rather than from what it opened with, or a value
  // typed before the unit was changed would be silently thrown away.
  let counting = size;
  chooser.addEventListener("change", (event) => {
    event.stopPropagation();
    const chosen = DURATION_UNITS.find(([name]) => name === chooser.value);
    const next = chosen ? chosen[1] : 1;
    const total = (Number(amount.value) || 0) * counting;
    counting = next;
    amount.value = String(Math.max(1, Math.round(total / next)));
    says.textContent = inWords(held());
    box.dispatchEvent(new Event("change", { bubbles: true }));
  });
  amount.addEventListener("input", () => { says.textContent = inWords(held()); });

  Object.defineProperty(box, "value", { get: held, set() {} });
  return box;
}

function chosenValueControl(field, value) {
  const kind = CHOOSERS[field.chooser] || CHOOSERS.directory;
  const wrap = document.createElement("div");
  wrap.className = "dir-control";
  wrap.dataset.heldUntilSave = "1";
  const single = field.type !== "multiline";
  // A single-valued setting holds one location; a multiline one holds a list.
  let entries = (single
    ? [String(value ?? "")]
    : String(value ?? "").split("\n"))
    .map((line) => line.trim())
    .filter(Boolean);

  // Held until the card's Save, as every setting is.
  const save = async () => {
    const next = single ? (entries[0] || "") : entries.join("\n");
    wrap.dispatchEvent(new CustomEvent("held", { detail: next }));
    draw();
  };

  const add = async (path) => {
    const checked = await kind.check(path);
    if (!checked.usable) {
      toast(`${path}: ${checked.problem}`, "error");
      return;
    }
    if (single) entries = [path];
    else if (!entries.includes(path)) entries.push(path);
    await save();
  };

  function draw() {
    wrap.innerHTML = "";
    const list = document.createElement("div");
    list.className = "dir-list";
    // THE DATA FOLDER, first and locked: never listened to, whatever the
    // list says (common/file_noise.py) - set when it was installed, or with
    // --root, and not changed here.
    if (field.key === "listener_directory_exclusions" && settingsEdit.dataFolder) {
      const fixed = document.createElement("div");
      fixed.className = "dir-entry dir-entry-fixed";
      fixed.innerHTML = `<span class="dir-path" title="${escapeHtml(settingsEdit.dataFolder)}">${
        escapeHtml(settingsEdit.dataFolder)}</span>
        <span class="muted dir-fixed-note">The agent's data folder - never listened to;
        set when it was installed, it cannot be changed here</span>`;
      list.appendChild(fixed);
    }
    entries.forEach((path, index) => {
      const row = document.createElement("div");
      row.className = "dir-entry";
      row.innerHTML = `<span class="dir-path" title="${escapeHtml(path)}">${
        escapeHtml(path)}</span>`;
      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "small secondary";
      remove.textContent = "Remove";
      remove.addEventListener("click", async () => {
        entries.splice(index, 1);
        await save();
      });
      row.appendChild(remove);
      list.appendChild(row);
    });
    if (!entries.length) {
      list.innerHTML = `<div class="muted">${escapeHtml(kind.empty)}</div>`;
    }
    wrap.appendChild(list);

    const actions = document.createElement("div");
    actions.className = "dir-actions";
    const choose = document.createElement("button");
    choose.type = "button";
    choose.className = "small";
    choose.textContent = single ? kind.oneLabel : kind.addLabel;
    choose.addEventListener("click", async () => {
      choose.disabled = true;
      choose.textContent = "Choosing…";
      try {
        const result = await api.post(kind.endpoint, {
          title: field.label, start_at: entries[entries.length - 1] || null,
        });
        const chosen = result.selected ? kind.valueOf(result) : null;
        if (chosen) {
          await add(chosen);
        } else if (!result.available) {
          // No chooser on this machine, so typing is the only way left.
          typed.hidden = false;
          typed.placeholder = kind.typed;
          toast(result.reason || "no chooser here; type the path instead", "error");
        }
      } catch (err) {
        toast(err.message, "error");
      } finally {
        draw();
      }
    });
    actions.appendChild(choose);

    // Section 12, as amended: a location is browsed to, not typed. A typed
    // path is a path that can be misspelt, can name something that is not a
    // directory, and can be silently wrong for as long as nobody checks.
    // Typing reappears only where no chooser can run - a machine with no
    // desktop - and says so rather than sitting there as an equal option.
    const typed = document.createElement("input");
    typed.type = "text";
    typed.className = "dir-typed";
    typed.placeholder = kind.typed;
    typed.hidden = true;
    typed.addEventListener("keydown", async (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      const path = typed.value.trim();
      if (path) await add(path);
    });
    actions.appendChild(typed);
    wrap.appendChild(actions);
  }

  draw();
  return wrap;
}

/* BROWSER TESTING (Settings): install Google's Chrome for Testing headless
   shell for the work runs; its download's progress while it goes. */
const browserCard = { timer: null };

function mbOf(bytes) {
  return (Number(bytes || 0) / 1048576).toFixed(0) + " MB";
}

function renderBrowserCard(state) {
  if (!state) return;
  const job = state.job || {};
  const going = ["starting", "downloading"].includes(job.state);
  let line;
  if (going) {
    line = job.total
      ? `Downloading ${job.version || ""}… ${mbOf(job.done)} of ${mbOf(job.total)} ` +
        `(${Math.floor((100 * job.done) / job.total)}%)`
      : "Looking up the current version…";
  } else if (state.installed) {
    line = `Installed: Chrome for Testing ${state.version} (${mbOf(state.bytes)}).` +
      (state.usable ? " Work runs can use it." : ` Not given to runs: ${state.why_not}.`);
  } else {
    line = "Not installed: work runs test with their framework's test client only.";
  }
  if (job.state === "failed") line += ` The last install failed: ${job.error}`;
  if (job.state === "cancelled") line += " The last install was cancelled.";
  $("#browser-status").textContent = line;
  $("#browser-install").textContent = state.installed ? "Update" : "Install";
  $("#browser-install").hidden = going;
  $("#browser-cancel").hidden = !going;
  $("#browser-remove").hidden = going || !state.installed;
  clearTimeout(browserCard.timer);
  if (going) browserCard.timer = setTimeout(refreshBrowserCard, 1000);
}

async function refreshBrowserCard() {
  try { renderBrowserCard(await api.get("/api/browser")); }
  catch (err) { console.warn("browser", err); }
}

$("#browser-install").addEventListener("click", async () => {
  try { renderBrowserCard(await api.post("/api/browser/install", {})); }
  catch (err) { toast(err.message, "error"); }
});
$("#browser-cancel").addEventListener("click", async () => {
  try { renderBrowserCard(await api.post("/api/browser/cancel", {})); }
  catch (err) { toast(err.message, "error"); }
});
$("#browser-remove").addEventListener("click", async () => {
  try { renderBrowserCard(await api.post("/api/browser/remove", {})); }
  catch (err) { toast(err.message, "error"); }
});

/* RUN NOW (Overview > Summary task): the state heartbeat's round begun at
   once, and the next regular one counted from when it finishes. */
function renderOvRound(said) {
  const button = $("#ov-round-run");
  const line = $("#ov-round-next");
  if (!button || !line || !said) return;
  button.disabled = Boolean(said.running);
  button.textContent = said.running ? "Updating tasks…" : "Update tasks now";
  if (said.running) {
    line.textContent = "A round is running now; the tasks change as it goes.";
  } else if (said.next_at) {
    line.textContent = `Next regular round: ${clock(said.next_at)}`;
  } else {
    line.textContent = "";
  }
}

async function refreshOvRound() {
  try { renderOvRound(await api.get("/api/state_heartbeat/next")); }
  catch (err) { console.warn(err); }
}

$("#ov-round-run")?.addEventListener("click", async () => {
  try {
    const said = await api.post("/api/state_heartbeat/start", {});
    renderOvRound(said);
    if (!said.started) toast(said.why || "A round is already running; this one was not started.");
  } catch (err) {
    toast(err.message, "error");
  }
});

/* SETTINGS > SHORTCUTS: each shortcut with its keys, Change (then press
   the keys), Turn off and Default - held at once, or refused and said why
   when another program has them; and the button beside selected text. */
const shortcutEdit = { recording: "", said: null };

async function refreshShortcuts() {
  const host = $("#shortcuts-list");
  if (!host) return;
  try {
    shortcutEdit.said = await api.get("/api/shortcuts");
  } catch (err) {
    host.textContent = err.message;
    return;
  }
  renderShortcuts();
}

function shortcutKeys(combo) {
  const keys = document.createElement("span");
  keys.classList.add("shortcut-keys");
  if (!combo) {
    keys.classList.add("muted");
    keys.textContent = "Off";
    return keys;
  }
  combo.split("+").forEach((one) => {
    const key = document.createElement("kbd");
    key.textContent = one;
    keys.appendChild(key);
  });
  return keys;
}

function renderShortcuts() {
  const host = $("#shortcuts-list");
  const said = shortcutEdit.said;
  if (!host || !said) return;
  host.innerHTML = "";
  if (!said.available && said.why) {
    const why = document.createElement("p");
    why.classList.add("muted");
    why.textContent = said.why;
    host.appendChild(why);
  }
  (said.shortcuts || []).forEach((one) => {
    const row = document.createElement("div");
    row.classList.add("shortcut-row");
    row.dataset.shortcut = one.key;
    const words = document.createElement("div");
    words.classList.add("shortcut-words");
    const name = document.createElement("strong");
    name.textContent = one.name;
    const what = document.createElement("div");
    what.classList.add("muted");
    what.textContent = one.what;
    words.append(name, what);
    const recording = shortcutEdit.recording === one.key;
    const keys = recording ? document.createElement("span") : shortcutKeys(one.combo);
    if (recording) {
      keys.classList.add("shortcut-keys", "shortcut-recording");
      keys.textContent = "Press the keys… (Esc to cancel)";
    }
    const buttons = document.createElement("div");
    buttons.classList.add("shortcut-buttons");
    const change = document.createElement("button");
    change.type = "button";
    change.dataset.shortcutChange = one.key;
    change.textContent = recording ? "Cancel" : "Change";
    buttons.appendChild(change);
    if (one.combo) {
      const off = document.createElement("button");
      off.type = "button";
      off.className = "secondary";
      off.dataset.shortcutOff = one.key;
      off.textContent = "Turn off";
      buttons.appendChild(off);
    }
    if (one.combo !== one.default) {
      const back = document.createElement("button");
      back.type = "button";
      back.className = "secondary";
      back.dataset.shortcutDefault = one.key;
      back.textContent = `Back to ${one.default}`;
      buttons.appendChild(back);
    }
    row.append(words, keys, buttons);
    if (one.problem) {
      const problem = document.createElement("div");
      problem.classList.add("shortcut-problem");
      problem.textContent = one.problem;
      row.appendChild(problem);
    }
    host.appendChild(row);
  });
  // The button beside selected text: the other way to hand text over.
  const label = document.createElement("label");
  label.classList.add("shortcut-row", "shortcut-toggle");
  const box = document.createElement("input");
  box.type = "checkbox";
  box.id = "shortcut-selection-button";
  box.checked = Boolean(said.selection_button);
  const words = document.createElement("span");
  words.innerHTML = "";
  const name = document.createElement("strong");
  name.textContent = "Delegate work button beside selected text";
  const what = document.createElement("div");
  what.classList.add("muted");
  what.textContent = "A small button that appears for a few seconds next to text you select (Windows).";
  words.append(name, what);
  label.append(box, words);
  host.appendChild(label);
}

async function saveShortcut(body, done) {
  try {
    shortcutEdit.said = await api.post("/api/shortcuts", body);
    if (done) toast(done);
  } catch (err) {
    toast(err.message, "error");
  }
  shortcutEdit.recording = "";
  renderShortcuts();
}

/* What a key press is called in a shortcut - or "" for a modifier alone. */
function shortcutKeyName(event) {
  const code = event.code || "";
  if (/^Key[A-Z]$/.test(code)) return code.slice(3);
  if (/^Digit[0-9]$/.test(code)) return code.slice(5);
  if (/^F([1-9]|1[0-9]|2[0-4])$/.test(code)) return code;
  const named = { Space: "Space", Insert: "Insert", Delete: "Delete", Home: "Home",
    End: "End", PageUp: "PageUp", PageDown: "PageDown", ArrowLeft: "Left",
    ArrowUp: "Up", ArrowRight: "Right", ArrowDown: "Down" };
  return named[code] || "";
}

document.addEventListener("keydown", (event) => {
  if (!shortcutEdit.recording) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.key === "Escape") {
    shortcutEdit.recording = "";
    renderShortcuts();
    return;
  }
  const key = shortcutKeyName(event);
  if (!key) return;                         // a modifier alone: wait for the key
  const combo = [event.ctrlKey && "Ctrl", event.altKey && "Alt", event.shiftKey && "Shift",
    event.metaKey && "Win", key].filter(Boolean).join("+");
  saveShortcut({ key: shortcutEdit.recording, combo }, `Shortcut set: ${combo}`);
}, true);

document.addEventListener("click", (event) => {
  const change = event.target.closest?.("[data-shortcut-change]");
  if (change) {
    const key = change.dataset.shortcutChange;
    shortcutEdit.recording = shortcutEdit.recording === key ? "" : key;
    renderShortcuts();
    return;
  }
  const off = event.target.closest?.("[data-shortcut-off]");
  if (off) {
    saveShortcut({ key: off.dataset.shortcutOff, combo: "" }, "Shortcut turned off");
    return;
  }
  const back = event.target.closest?.("[data-shortcut-default]");
  if (back) {
    const one = ((shortcutEdit.said || {}).shortcuts || [])
      .find((s) => s.key === back.dataset.shortcutDefault);
    if (one) saveShortcut({ key: one.key, combo: one.default }, `Shortcut set: ${one.default}`);
  }
});

document.addEventListener("change", (event) => {
  if (event.target?.id === "shortcut-selection-button") {
    saveShortcut({ selection_button: event.target.checked },
      event.target.checked ? "The button beside selected text is on"
        : "The button beside selected text is off");
  }
});

/* NOT THIS WORK (State heartbeat debugger): what the model, summing a task
   up or saying where it stands, said is plainly about something else - each
   task with the states it named and the call that said so. Switched off,
   nothing is moved and this is the place to judge whether it should be. */
async function loadNotThisWork() {
  const list = $("#ntw-list");
  if (!list) return;
  let said;
  try {
    said = await api.get("/api/state_heartbeat/not_this_work");
  } catch (err) {
    list.textContent = err.message;
    return;
  }
  $("#ntw-note").textContent = said.on
    ? "Switched on: these states were taken out of their tasks, to the pile."
    : "Switched off: nothing was moved. This is what would have been taken out, for you to judge.";
  const entries = said.said || [];
  $("#ntw-count").textContent = entries.length
    ? `${entries.length} time${entries.length === 1 ? "" : "s"}` : "none yet";
  list.innerHTML = "";
  if (!entries.length) {
    list.innerHTML = `<p class="muted">The model has not named any state as not its task's work yet.</p>`;
    return;
  }
  entries.forEach((entry) => {
    const block = document.createElement("div");
    block.classList.add("ntw-entry");
    const head = document.createElement("div");
    head.classList.add("ntw-head");
    const task = document.createElement("strong");
    task.textContent = entry.task.title || entry.task.id;
    const when = document.createElement("span");
    when.classList.add("muted");
    when.textContent = ` ${clock(entry.at)} · ${entry.by === "summary" ? "summary" : "status"} call`;
    head.append(task, when);
    block.appendChild(head);
    const rows = document.createElement("ul");
    entry.states.forEach((state) => {
      const row = document.createElement("li");
      row.textContent = `${(state.at || "").slice(0, 16).replace("T", " ")}  ${state.title || state.id}`;
      rows.appendChild(row);
    });
    block.appendChild(rows);
    list.appendChild(block);
  });
}

/* THE RECORD LOG: the latest things recorded, from every source, each with
   the Privacy switch that recorded it and where a password or a code was
   hidden in it; opened, all of it. Then what the filters kept out, by rule.
   Drawn again only when something new was recorded, and what is open stays
   open. */
/* Of one kind, when one is chosen in Show (its types' beginning). */
const recordLog = { sig: "", open: new Set(), kind: "" };
const RECORD_RULES = {
  switch_off: "Its switch in Settings › Privacy is off",
  application_list: "The application allowlist or denylist",
  website_list: "The website allowlist or denylist",
  not_here: "Only while you are here: nobody was at the computer",
  not_yours: "Only what you did yourself: a program did it, not you",
  agents_own: "The agent's own files",
  excluded_folder: "An excluded folder",
  ignored_name: "An ignored file name",
  credentials: "A screenshot whose words held a password or a code",
};

/* Text with every "[hidden]" in it marked, as elements - never as HTML. */
function recordMarked(host, text) {
  String(text || "").split("[hidden]").forEach((part, at) => {
    if (at) {
      const mark = document.createElement("mark");
      mark.classList.add("record-mark");
      mark.textContent = "[hidden]";
      host.appendChild(mark);
    }
    if (part) host.appendChild(document.createTextNode(part));
  });
  return host;
}

function recordHead(one) {
  const head = document.createElement("summary");
  const when = document.createElement("span");
  when.classList.add("muted", "record-when");
  when.textContent = clock(one.at);
  const by = document.createElement("span");
  by.classList.add("record-switch");
  by.textContent = one.by_agent ? "The agent's own work"
    : one.switch ? one.switch.label : one.source;
  const title = recordMarked(document.createElement("span"), one.title);
  title.classList.add("record-title");
  head.append(when, by, title);
  if (one.hidden) {
    const hid = document.createElement("span");
    hid.classList.add("record-hidden");
    hid.textContent = one.hidden === 1 ? "1 password or code hidden"
      : `${one.hidden} passwords or codes hidden`;
    head.appendChild(hid);
  }
  return head;
}

function renderRecordHidden(changed) {
  const host = $("#recordlog-hidden");
  if (!host) return;
  host.innerHTML = "";
  if (!changed.length) {
    host.innerHTML = `<p class="muted">Nothing was hidden in the last 7 days.</p>`;
    return;
  }
  changed.forEach((one) => {
    const item = document.createElement("details");
    item.classList.add("record-item");
    item.open = true;
    item.appendChild(recordHead(one));
    (one.fields || []).forEach((field) => {
      const row = document.createElement("div");
      row.classList.add("record-field");
      const name = document.createElement("code");
      name.textContent = field.field;
      row.appendChild(name);
      row.appendChild(recordMarked(document.createElement("span"), field.text));
      item.appendChild(row);
    });
    host.appendChild(item);
  });
}

async function loadRecordLog(force = false) {
  const list = $("#recordlog-list");
  const dropped = $("#recordlog-dropped");
  if (!list || !dropped) return;
  const kind = $("#recordlog-kind");
  if (kind && !kind.dataset.bound) {
    kind.dataset.bound = "1";
    kind.addEventListener("change", () => {
      recordLog.kind = kind.value;
      list.innerHTML = `<p class="muted">Reading&hellip;</p>`;
      loadRecordLog(true);
    });
  }
  const asked = recordLog.kind;
  let said;
  try {
    said = await api.get(`/api/record_log?kind=${encodeURIComponent(asked)}`);
  } catch (err) {
    list.textContent = `Could not read the record log: ${err.message}`;
    return;
  }
  // Another kind was chosen while this one was read: that one is drawn.
  if (asked !== recordLog.kind) return;
  const sig = JSON.stringify([(said.events || []).map((one) => one.id),
    (said.changed || []).map((one) => one.id), said.dropped_counts || {}]);
  if (!force && sig === recordLog.sig) return;
  recordLog.sig = sig;
  renderRecordHidden(said.changed || []);
  list.innerHTML = "";
  if (!(said.events || []).length) {
    list.innerHTML = recordLog.kind ? `<p class="muted">Nothing of this kind recorded yet.</p>`
      : `<p class="muted">Nothing recorded yet.</p>`;
  }
  (said.events || []).forEach((one) => {
    const item = document.createElement("details");
    item.classList.add("record-item");
    item.dataset.record = one.id;
    if (recordLog.open.has(one.id)) item.open = true;
    item.addEventListener("toggle", () => {
      if (item.open) recordLog.open.add(one.id);
      else recordLog.open.delete(one.id);
    });
    item.appendChild(recordHead(one));
    if (one.about) {
      const about = recordMarked(document.createElement("p"), one.about);
      about.classList.add("muted", "record-about");
      item.appendChild(about);
    }
    const whole = recordMarked(document.createElement("pre"),
      JSON.stringify(one.detail, null, 2));
    whole.classList.add("record-detail");
    item.appendChild(whole);
    list.appendChild(item);
  });
  dropped.innerHTML = "";
  const counts = Object.entries(said.dropped_counts || {}).filter(([, n]) => n > 0);
  if (!counts.length) {
    dropped.innerHTML = `<p class="muted">Nothing was kept out since the agent started.</p>`;
    return;
  }
  const totals = document.createElement("ul");
  totals.classList.add("record-rules");
  counts.sort((a, b) => b[1] - a[1]).forEach(([rule, n]) => {
    const row = document.createElement("li");
    row.textContent = `${RECORD_RULES[rule] || rule}: ${n}`;
    totals.appendChild(row);
  });
  dropped.appendChild(totals);
  const latest = document.createElement("ul");
  latest.classList.add("record-dropped");
  (said.dropped || []).forEach((one) => {
    const row = document.createElement("li");
    row.textContent = [clock(one.at), one.category || one.source,
      one.application || "", one.type, RECORD_RULES[one.why] || one.why]
      .filter(Boolean).join(" - ");
    latest.appendChild(row);
  });
  dropped.appendChild(latest);
}

/* UPDATES (Settings > General): which version this is, the latest release,
   and what is being done about it. Installed by themselves by default; the
   choice is the setting above the buttons (platform_layer/updater.py). */
const UPDATE_CHOICES = {
  ask: "Tell me, and I choose the version",
  install: "Install the newest by itself",
  off: "Don't look for updates",
};

function renderUpdates(said) {
  const line = $("#updates-status");
  if (!line || !said) return;
  const parts = [`This is version ${said.current}.`];
  if (said.mode === "off") {
    parts.push("Updates are not looked for.");
  } else if (said.doing === "checking") {
    parts.push("Looking for newer versions…");
  } else if (said.doing) {
    parts.push(`Now: ${said.doing}.`);
  } else if (said.ready) {
    parts.push(`Version ${said.ready} is ready: it is used from the next start, `
      + "or when you have been away a while.");
  } else if (said.newer) {
    parts.push(`Version ${said.latest} is available.`);
    if (!said.can_install) {
      parts.push("This copy cannot update itself: download it from the releases page.");
    }
  } else if (said.checked_at) {
    parts.push("It is the latest.");
  }
  if (said.error) parts.push(`The last look failed: ${said.error}`);
  line.textContent = parts.join(" ");
  renderUpdateRestart(said);
  renderUpdateVersions(said);
  showWhatIsNew(said.just_updated);
}

/* MADE READY: "Restart now" uses it at once - the page following the
   agent to the new version (followUpdate). Otherwise it is used from the
   next start, or when the user has been away a while. */
function renderUpdateRestart(said) {
  let row = $("#updates-restart");
  if (!said.ready || said.mode === "off" || said.doing) {
    if (row) row.remove();
    return;
  }
  const line = $("#updates-status");
  if (!line) return;
  if (!row) {
    row = document.createElement("p");
    row.id = "updates-restart";
    line.after(row);
  }
  row.innerHTML = "";
  const button = document.createElement("button");
  button.type = "button";
  button.classList.add("small");
  button.textContent = "Restart now to use it";
  button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      renderUpdates(await api.post("/api/updates/restart", {}));
      followUpdate({ to: said.ready, step: "restarting" });
    } catch (err) {
      button.disabled = false;
      toast(err.message, "error");
    }
  });
  row.appendChild(button);
}

/* THE VERSION TO UPDATE TO: a box of every version newer than this one,
   newest first - empty, it says there is none, or that none was looked for
   yet - with what the chosen one says of itself and its own button: the
   user installs the one they choose. Never an older one - it may not read
   what a newer one wrote. */
function renderUpdateVersions(said) {
  const host = $("#updates-versions");
  if (!host) return;
  host.innerHTML = "";
  if (said.mode === "off") return;
  const versions = said.versions || [];
  const row = document.createElement("div");
  row.classList.add("update-version");
  const head = document.createElement("div");
  head.classList.add("update-version-head");
  const label = document.createElement("label");
  label.htmlFor = "updates-version";
  label.textContent = "Version to update to";
  const box = document.createElement("select");
  box.id = "updates-version";
  if (!versions.length) {
    const none = document.createElement("option");
    none.textContent = said.checked_at ? "No newer version" : "Not looked for yet - press Check now";
    box.appendChild(none);
    box.disabled = true;
  }
  versions.forEach((one) => {
    const option = document.createElement("option");
    option.value = one.tag;
    option.textContent = one.published ? `Version ${one.tag} (${clock(one.published)})`
      : `Version ${one.tag}`;
    box.appendChild(option);
  });
  // The one chosen stays chosen when the box is drawn again.
  if (versions.some((one) => one.tag === renderUpdateVersions.chosen)) {
    box.value = renderUpdateVersions.chosen;
  }
  head.append(label, box);
  row.appendChild(head);
  const chosen = () => versions.find((one) => one.tag === box.value);
  const action = document.createElement("span");
  action.classList.add("update-version-action");
  head.appendChild(action);
  const notes = document.createElement("details");
  const summary = document.createElement("summary");
  summary.textContent = "What is new";
  const text = document.createElement("div");
  text.classList.add("update-notes-text");
  notes.append(summary, text);
  const show = () => {
    const one = chosen();
    action.innerHTML = "";
    notes.hidden = !one;
    if (!one) return;
    renderUpdateVersions.chosen = one.tag;
    text.textContent = one.notes || "This release says nothing more about itself.";
    if (one.can_install && !said.doing) {
      const install = document.createElement("button");
      install.type = "button";
      install.classList.add("small");
      install.textContent = "Install this version";
      install.addEventListener("click", async () => {
        try {
          renderUpdates(await api.post("/api/updates/install", { version: one.tag }));
          // QUIETLY, LIKE EVERY UPDATE: made ready in the background, used
          // from the next start - or at once, with Restart now.
          toast(`Getting version ${one.tag} ready in the background`);
          refreshUpdatesUntilReady();
        } catch (err) {
          toast(err.message, "error");
        }
      });
      action.appendChild(install);
    } else if (one.page) {
      const link = document.createElement("a");
      link.href = one.page;
      link.target = "_blank";
      link.rel = "noopener";
      link.textContent = "The release on GitHub";
      action.appendChild(link);
    }
  };
  box.addEventListener("change", show);
  show();
  row.appendChild(notes);
  host.appendChild(row);
}

/* WHAT IS NEW, once, after an update: the release's own description - as
   written on GitHub, so shown as written - until it is closed. */
function showWhatIsNew(news) {
  const box = $("#update-notes");
  if (!box || !news || box.open || showWhatIsNew.shown) return;
  showWhatIsNew.shown = true;
  $("#update-notes-title").textContent = `Updated to version ${news.to}`;
  $("#update-notes-from").textContent = news.from ? `From version ${news.from}.` : "";
  $("#update-notes-text").textContent = news.notes || "This release says nothing more about itself.";
  const page = $("#update-notes-page");
  page.hidden = !news.page;
  if (news.page) page.href = news.page;
  try { box.showModal(); } catch (err) { box.setAttribute("open", ""); }
}

$("#update-notes-close")?.addEventListener("click", async () => {
  $("#update-notes").close?.();
  $("#update-notes").removeAttribute("open");
  try { await api.post("/api/updates/seen", {}); } catch (err) { /* shown again next time */ }
});

async function refreshUpdates() {
  try { renderUpdates(await api.get("/api/updates")); }
  catch (err) { console.warn("updates", err); }
}

/* Asked for, a version is made ready in the background: Settings says how
   far, and offers Restart now once it is ready. */
async function refreshUpdatesUntilReady() {
  for (let tries = 0; tries < 360; tries += 1) {
    await new Promise((done) => setTimeout(done, 5000));
    let said;
    try { said = await api.get("/api/updates"); } catch (err) { return; }
    renderUpdates(said);
    if (said.ready || said.error) return;
  }
}

/* AN UPDATE SEEN THROUGH (the user, 2026-10-27): the page outlives the
   agent it shows, so it follows an update to the end - the download with
   its share done, checked, installing, the agent closed and starting again
   - asking each second, and opens on the new version (its sign-in holds:
   the same address, a cookie made from the installation's own key). It
   says so when the new version is slow to answer. */
const UPDATE_STEPS = [
  ["downloading", "Downloading"],
  ["checking", "Checking the download"],
  ["installing", "Installing"],
  ["restarting", "Starting the new version"],
];
const UPDATE_SLOW_SECONDS = 180;

/* The lines of the card: each step done, at, or to come - `gone`, the agent
   has closed (it is installing or starting again). */
function updateStepLines(info, gone) {
  const at = gone ? "restarting" : (info.step || "downloading");
  const index = Math.max(0, UPDATE_STEPS.findIndex(([key]) => key === at));
  return UPDATE_STEPS.map(([key, label], i) => {
    let text = label;
    const p = info.progress || {};
    if (key === "downloading" && i === index && p.total > 0) {
      text += ` - ${Math.min(100, Math.floor((p.done / p.total) * 100))}% `
        + `(${Math.round(p.done / 1048576)} of ${Math.round(p.total / 1048576)} MB)`;
    }
    if (key === "restarting" && gone) {
      text += " - the agent is closed meanwhile";
    }
    return { key, text, state: i < index ? "done" : i === index ? "now" : "next" };
  });
}

let updateFollowing = null;

async function followUpdate(info) {
  if (!info || !info.to) return;
  if (updateFollowing) { updateFollowing.info = info; drawUpdateCard(false); return; }
  updateFollowing = { info, since: Date.now(), goneSince: 0 };
  drawUpdateCard(false);
  for (;;) {
    await new Promise((done) => setTimeout(done, 1000));
    let said = null;
    try {
      said = await api.get("/api/updates");
    } catch (err) {
      // Closed - installing, or starting again: asked again in a second.
      if (!updateFollowing.goneSince) updateFollowing.goneSince = Date.now();
      drawUpdateCard(true);
      continue;
    }
    if (version_of_tag(said.current) === version_of_tag(updateFollowing.info.to)) {
      // The new version answers: the page opens on it, with what is new.
      drawUpdateCard(true, "done");
      setTimeout(() => location.reload(), 600);
      return;
    }
    if (!updateFollowing.goneSince && !(said.step || "")) {
      // Not updating after all (the download failed, say): said, and left.
      updateFollowing = null;
      $("#update-follow")?.remove();
      renderUpdates(said);
      if (said.error) toast(`The update did not happen: ${said.error}`, "error");
      return;
    }
    if (said.step) updateFollowing.info = Object.assign({}, updateFollowing.info,
      { step: said.step, progress: said.progress });
    drawUpdateCard(Boolean(updateFollowing.goneSince));
  }
}

function version_of_tag(tag) {
  return String(tag || "").replace(/^v/i, "");
}

function drawUpdateCard(gone, done) {
  let card = $("#update-follow");
  if (!card) {
    card = document.createElement("section");
    card.id = "update-follow";
    card.className = "update-follow";
    card.setAttribute("role", "status");
    card.setAttribute("aria-live", "polite");
    document.body.appendChild(card);
  }
  const info = updateFollowing.info;
  const waited = updateFollowing.goneSince
    ? Math.round((Date.now() - updateFollowing.goneSince) / 1000) : 0;
  const lines = updateStepLines(info, gone).map((one) => `<li class="update-step-${
    done ? "done" : one.state}">${escapeHtml(one.text)}</li>`).join("");
  const slow = waited >= UPDATE_SLOW_SECONDS
    ? `<p class="update-follow-slow">${escapeHtml("It is taking longer than it should. "
      + "If the agent does not come back, open Personal Agent WaterMelon yourself - "
      + "the new version is installed, or the old one still is.")}</p>` : "";
  card.innerHTML = `<strong>${escapeHtml(done ? `Updated to version ${version_of_tag(info.to)}`
      : `Updating to version ${version_of_tag(info.to)}`)}</strong>
    <ol class="update-follow-steps">${lines}</ol>
    ${gone && !done ? `<p class="muted">${escapeHtml(`Waiting for the new version - ${waited} s. `
      + "This page opens on it by itself.")}</p>` : ""}${slow}`;
}

/* CHECK NOW: the button says it is looking until the look has answered -
   it runs on its own thread, so it is asked again until it is done. */
$("#updates-check")?.addEventListener("click", async (event) => {
  const button = event.currentTarget;
  if (button.disabled) return;
  button.disabled = true;
  button.textContent = "Checking…";
  try {
    let said = await api.post("/api/updates/check", {});
    renderUpdates(said);
    for (let tries = 0; said.doing === "checking" && tries < 40; tries += 1) {
      await new Promise((done) => setTimeout(done, 1000));
      said = await api.get("/api/updates");
      renderUpdates(said);
    }
  } catch (err) {
    toast(err.message, "error");
  } finally {
    button.disabled = false;
    button.textContent = "Check now";
  }
});

/* MACOS PERMISSIONS (Settings > Privacy). macOS asks for each kind of
   access on its own and only the user can switch one on, so they are
   listed together to be given in one sitting - Full Disk Access first,
   since it also covers the Desktop, Documents and Downloads folders and
   spares macOS's three questions about them. Looked at again whenever the
   window comes back, which is when the user returns from System Settings.
   (platform_layer/macos_permissions.py) */
const MAC_PERMISSIONS = {
  full_disk: { name: "Full Disk Access",
    why: "Your Desktop, Documents and Downloads folders, and Safari's history. "
      + "Allowed first, it spares the questions macOS would ask about each folder.",
    how: "Click +, choose Personal Agent WaterMelon in Applications, and switch it on." },
  accessibility: { name: "Accessibility",
    why: "The titles of the windows you work in.",
    how: "Switch on Personal Agent WaterMelon." },
  automation: { name: "Automation: System Events",
    why: "Which application is in front.",
    how: "Under Personal Agent WaterMelon, switch on System Events." },
  screen: { name: "Screen & System Audio Recording",
    why: "Pictures of the window in front, for the words in slides and figures. macOS "
      + "names this permission with audio too; the agent never records any sound.",
    how: "Switch on Personal Agent WaterMelon. macOS may ask to quit and reopen it." },
};
/* On a Mac a version signed ad hoc was, to macOS, another program: the
   switch an earlier version was given stayed on, and this one was refused. */
const MAC_ON_BUT_NOT_ALLOWED = "Already on in System Settings? It may be an earlier version's switch: select "
    + "Personal Agent WaterMelon there, remove it with -, press Open System Settings here, "
    + "switch it on again, then quit the agent and open it again.";
const macPermissions = { data: null, dismissed: false };

function renderMacPermissions(data) {
  macPermissions.data = data;
  const applies = Boolean(data && data.applies);
  const card = $("#mac-permissions-card");
  if (card) card.hidden = !applies;
  const banner = $("#macperm-banner");
  if (!applies) {
    if (banner) banner.hidden = true;
    return;
  }
  const list = $("#mac-permissions-list");
  if (list) {
    list.innerHTML = "";
    (data.items || []).forEach((item) => {
      const said = MAC_PERMISSIONS[item.key];
      if (!said) return;
      const row = document.createElement("div");
      row.classList.add("mac-permission");
      row.dataset.permission = item.key;
      const head = document.createElement("div");
      head.classList.add("mac-permission-head");
      const name = document.createElement("strong");
      name.textContent = said.name;
      const state = document.createElement("span");
      state.classList.add("mac-permission-state");
      if (!item.needed) {
        state.textContent = "Not needed with your Privacy switches";
      } else if (item.granted === true) {
        state.textContent = "Allowed";
        state.classList.add("ok");
      } else if (item.granted === false) {
        state.textContent = "Not allowed";
        state.classList.add("missing");
      } else {
        state.textContent = "Cannot be told";
      }
      head.append(name, state);
      const why = document.createElement("div");
      why.classList.add("muted");
      why.textContent = said.why;
      row.append(head, why);
      if (item.needed && item.granted !== true) {
        const how = document.createElement("div");
        how.classList.add("mac-permission-how");
        how.textContent = said.how;
        const open = document.createElement("button");
        open.type = "button";
        open.classList.add("small");
        open.textContent = "Open System Settings";
        open.addEventListener("click", async () => {
          try {
            renderMacPermissions(await api.post("/api/permissions/macos/open", { key: item.key }));
          } catch (err) {
            toast(err.message, "error");
          }
        });
        row.append(how, open);
        if (["accessibility", "screen"].includes(item.key) && item.granted === false) {
          const earlier = document.createElement("div");
          earlier.classList.add("mac-permission-how");
          earlier.textContent = MAC_ON_BUT_NOT_ALLOWED;
          row.append(earlier);
        }
        if (item.key === "screen" && item.granted === false) {
          // macOS answers a running program as it was when it started.
          const after = document.createElement("div");
          after.classList.add("mac-permission-how");
          after.textContent = "Once it is switched on in System Settings, it applies only after the agent is quit and opened again.";
          const again = document.createElement("button");
          again.type = "button";
          again.classList.add("small", "secondary");
          again.textContent = "Quit and open again";
          again.addEventListener("click", async () => {
            again.disabled = true;
            try {
              await api.post("/api/permissions/macos/start_again", {});
              toast("Opening the agent again…");
            } catch (err) {
              again.disabled = false;
              toast(err.message, "error");
            }
          });
          row.append(after, again);
        }
      }
      list.appendChild(row);
    });
  }
  const missing = (data.missing || []).length;
  if (banner) {
    banner.hidden = !missing || macPermissions.dismissed;
    $("#macperm-text").textContent = missing === 1
      ? "macOS has not yet allowed one thing the agent needs."
      : `macOS has not yet allowed ${missing} things the agent needs.`;
  }
}

async function refreshMacPermissions() {
  try {
    renderMacPermissions(await api.get("/api/permissions/macos"));
  } catch (err) {
    console.warn(err);
  }
}

// Looked at once as the page opens, and then only when asked: each look
// asks System Events, which takes a moment. Grey while it looks, so it is
// asked once.
$("#mac-permissions-check")?.addEventListener("click", async (event) => {
  const button = event.currentTarget;
  if (button.disabled) return;
  button.disabled = true;
  button.textContent = "Checking…";
  try {
    renderMacPermissions(await api.get("/api/permissions/macos"));
    const at = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    const said = $("#mac-permissions-checked");
    if (said) said.textContent = `Checked at ${at}`;
  } catch (err) {
    toast(err.message, "error");
  } finally {
    button.disabled = false;
    button.textContent = "Check again";
  }
});
// What is new after an update is shown wherever the page opens, not only on
// Settings.
refreshUpdates();
$("#macperm-go")?.addEventListener("click", () => {
  const tab = $('#tabs button[data-tab="settings"]');
  if (tab) tab.click();
  settingsView("privacy");
});
$("#macperm-dismiss")?.addEventListener("click", () => {
  // Not now: for as long as this page is open. It is said again next time.
  macPermissions.dismissed = true;
  $("#macperm-banner").hidden = true;
});
refreshMacPermissions();

/* THE HEARTBEATS' INTERVALS, set in minutes: the agent heartbeat's kept
   in seconds, the state heartbeat's in hours. */
const HEARTBEAT_MINUTES = {
  heartbeat_interval_seconds: { label: "Agent heartbeat, every (minutes)",
    shown: (stored) => stored / 60, kept: (minutes) => Math.round(minutes * 60) },
  state_heartbeat_every_hours: { label: "State heartbeat, every (minutes)",
    shown: (stored) => stored * 60, kept: (minutes) => minutes / 60 },
};

/* MODULES: each with what it does, what turning it off means and what it
   spent lately - ticked where it stands, as every settings card is; Save
   appears once one is changed, and sends what was. */
const modulesEdit = { data: null };

function modulesChanged() {
  const values = {};
  $$("#modules-list [data-module]").forEach((box) => {
    const one = ((modulesEdit.data || {}).modules || []).find((m) => m.setting === box.dataset.module);
    if (one && one.enabled !== box.checked) values[box.dataset.module] = box.checked;
  });
  return values;
}

async function loadModules() {
  const host = $("#modules-list");
  // Not while something ticked is waiting for Save.
  if (!host || Object.keys(modulesChanged()).length) return;
  try {
    modulesEdit.data = await api.get("/api/modules");
  } catch (err) {
    host.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  renderModules();
}

function moduleSpent(spent, hours, manual = false) {
  const one = spent || {};
  const tokens = Number(one.total_tokens || 0);
  const cost = Number(one.estimated_cost || 0);
  const by = one.by === "tokens" ? " (by tokens: nothing had a cost)" : "";
  const all = Number(one.of_all || 0);
  // Each a whole phrase, as the interface's tables hold it (HANDOFF.md 7a).
  return manual
    ? `last ${hours} hours: about $${cost.toFixed(2)} · ${tokens.toLocaleString()} tokens · ${all}% of everything${by}`
    : `last ${hours} hours: about $${cost.toFixed(2)} · ${tokens.toLocaleString()} tokens · ${
      Number(one.of_automatic || 0)}% of the functions · ${all}% of everything${by}`;
}

function renderModules() {
  const host = $("#modules-list");
  const data = modulesEdit.data;
  if (!host || !data) return;
  const days = data.hours || 72;
  // THE BAR'S COLOUR: what each spent beside the others - pale for little,
  // deep red for the most among them.
  const shares = (data.modules || []).map((one) => Number((one.spent || {}).of_automatic || 0));
  const most = Math.max(0, ...shares);
  const heat = (share) => Math.round(share > 0 && most > 0 ? 12 + 88 * (share / most) : 0);
  host.innerHTML = `<div class="settings-edit-bar settings-save-bar" data-modules-bar hidden>
      <span class="muted">Not saved yet</span>
      <button type="button" class="small" data-modules-save>Save</button>
      <button type="button" class="small secondary" data-modules-cancel>Cancel</button></div>
    <p class="module-heat-key muted"><span class="module-heat-scale"></span>
      The bar on the left: what each spent in the last ${days} hours beside the others -
      pale for little, deep red for the most.</p>
    <ul class="modules-list">
      ${(data.modules || []).map((one, at) => `<li class="module-row${one.enabled ? "" : " module-off"}"
        style="--heat:${heat(shares[at])}%">
        <label><input type="checkbox" data-module="${escapeHtml(one.setting)}"${
          one.enabled ? " checked" : ""}>
          <strong>${escapeHtml(one.name)}</strong>${one.enabled ? ""
            : ' <span class="badge warn">off</span>'}</label>
        <div class="module-what">${escapeHtml(one.what)}</div>
        <div class="module-off-says"><strong>If turned off:</strong> ${escapeHtml(one.off)}</div>
        <div class="module-spent muted">${escapeHtml(moduleSpent(one.spent, days))}</div></li>`)
        .join("")}
    </ul>
    ${(data.unassigned || []).map((one) => `<p class="muted">${escapeHtml(one.name
      === "heartbeat (before modules)" ? "The agent heartbeat, before its steps were counted "
      + "apart (until the agent restarts on this version)" : one.name)}, ${escapeHtml(
      moduleSpent(one, days))}.</p>`).join("")}
    <p class="muted">What you started yourself, ${escapeHtml(moduleSpent(data.manual, days,
      true))}${(data.manual_parts || []).length ? ":" : "."}</p>
    ${(data.manual_parts || []).length ? `<ul class="module-manual">${data.manual_parts.map(
      (one) => `<li class="muted">${escapeHtml(one.name.replace(/^Started by you: /, ""))} -
        ${escapeHtml(moduleSpent(one, days, true))}</li>`).join("")}</ul>` : ""}`;
}

document.addEventListener("change", (event) => {
  if (!event.target.closest?.("#modules-list [data-module]")) return;
  const bar = $("#modules-list [data-modules-bar]");
  if (bar) bar.hidden = !Object.keys(modulesChanged()).length;
});

document.addEventListener("click", async (event) => {
  if (event.target.closest?.("[data-modules-cancel]")) {
    renderModules();
    return;
  }
  const save = event.target.closest?.("[data-modules-save]");
  if (!save) return;
  const values = modulesChanged();
  save.disabled = true;
  try {
    if (Object.keys(values).length) await api.post("/api/settings", { values });
    toast(Object.keys(values).length ? "Functions saved" : "Nothing changed");
  } catch (err) {
    toast(err.message, "error");
  }
  if (modulesEdit.data) {
    (modulesEdit.data.modules || []).forEach((one) => {
      if (one.setting in values) one.enabled = values[one.setting];
    });
  }
  renderModules();
  await loadModules();
});

/* WAITING FOR A TIME: each open one, with whom and why - taken off by the
   user, or by the agent when its time is seen. */
async function loadPending() {
  const host = $("#pending-list");
  if (!host) return;
  let said;
  try {
    said = await api.get("/api/pending");
  } catch (err) {
    host.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  renderPending(said);
}

function renderPending(said) {
  const host = $("#pending-list");
  if (!host) return;
  const open = said.open || [];
  const done = (said.recent || []).filter((one) => one.status !== "open").slice(0, 5);
  host.innerHTML = `${open.length ? `<ul class="pending-list">${open.map((one) => `
      <li data-pending="${escapeHtml(one.id)}"><strong>${escapeHtml(one.title)}</strong>
        ${one.detail ? `<div class="muted">${escapeHtml(one.detail)}</div>` : ""}
        <span class="muted">since ${escapeHtml(localStamp(one.created_at))}${
          (one.people || []).length ? ` · with ${escapeHtml(one.people.join(", "))}` : ""}</span>
        <button type="button" class="small secondary" data-pending-drop="${
          escapeHtml(one.id)}">Take off</button></li>`).join("")}</ul>`
    : `<p class="muted">Nothing is waiting for a time.</p>`}
    ${done.length ? `<details class="pending-done"><summary>Lately settled</summary><ul>${
      done.map((one) => `<li>${escapeHtml(one.title)} <span class="muted">- ${
        one.status === "resolved" ? "put on the calendar" : "taken off"}${one.closed_why
        ? `: ${escapeHtml(one.closed_why)}` : ""}</span></li>`).join("")}</ul></details>` : ""}`;
}

document.addEventListener("click", async (event) => {
  const drop = event.target.closest?.("[data-pending-drop]");
  if (!drop) return;
  drop.disabled = true;
  try {
    renderPending(await api.post("/api/pending", { action: "drop", id: drop.dataset.pendingDrop }));
  } catch (err) {
    toast(err.message, "error");
    drop.disabled = false;
  }
});

/* OCR: which of the five languages are read here; the missing ones, added
   with a button - Windows asks for an administrator's yes. */
async function loadOcr() {
  const host = $("#ocr-languages");
  if (!host) return;
  let said;
  try {
    said = await api.get("/api/ocr");
  } catch (err) {
    host.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  renderOcr(said);
}

function renderOcr(said) {
  const host = $("#ocr-languages");
  if (!host) return;
  const languages = said.languages || [];
  const going = (said.downloading || {}).running;
  // Each language not yet here and that can be added: a tick of its own, so
  // only the ones wanted are downloaded.
  const pick = (one) => !one.installed && one.can_add;
  host.innerHTML = `${said.available ? `<p class="muted">Read with ${
      escapeHtml(said.engine || "")}.</p>`
    : `<p class="ocr-none">This computer has no OCR it can use yet: a model that reads
       text only cannot read pictures.</p>`}
    <ul class="ocr-list">${languages.map((one) => `<li>${pick(one)
      ? `<label class="ocr-pick"><input type="checkbox" data-ocr-code="${escapeHtml(one.code)}"${
          going ? " disabled" : ""}>` : ""}
      <span class="badge ${one.installed ? "ok" : "warn"}">${one.installed
        ? "supported" : "not yet"}</span> ${escapeHtml(one.name)}${pick(one) ? "</label>" : ""}</li>`)
      .join("")}</ul>
    ${languages.some(pick) ? `<button type="button" class="small" data-ocr-add disabled>${going
      ? "Downloading…" : "Download the ticked languages"}</button>
      <span class="muted ocr-pick-note">Tick the ones you want - each is downloaded on its
        own.</span>` : ""}
    ${said.how ? `<p class="muted ocr-how">${escapeHtml(said.how)}</p>` : ""}
    ${(said.downloading || {}).note ? `<p class="muted">${escapeHtml(said.downloading.note)}</p>`
      : ""}
    ${(said.downloading || {}).error ? `<p class="muted">The download failed: ${
      escapeHtml(said.downloading.error)}</p>` : ""}`;
}

function ocrTicked() {
  return $$("#ocr-languages [data-ocr-code]:checked").map((box) => box.dataset.ocrCode);
}

document.addEventListener("change", (event) => {
  if (!event.target.closest?.("#ocr-languages [data-ocr-code]")) return;
  const add = $("#ocr-languages [data-ocr-add]");
  const ticked = ocrTicked();
  if (!add) return;
  add.disabled = !ticked.length;
  add.textContent = ticked.length
    ? `Download ${ticked.length === 1 ? "1 language" : `${ticked.length} languages`}`
    : "Download the ticked languages";
});

document.addEventListener("click", async (event) => {
  const add = event.target.closest?.("[data-ocr-add]");
  if (!add) return;
  const codes = ocrTicked();
  if (!codes.length) return;
  add.disabled = true;
  try {
    const said = await api.post("/api/ocr/add", { codes });
    renderOcr(said);
    if (said.started) toast("Adding the languages - it may ask for your yes");
  } catch (err) {
    toast(err.message, "error");
    add.disabled = false;
  }
});

/* The times of day an issue is made: a time box each, added and taken off.
   Its value is them all, "08:00, 18:30"; a change is said as one. */
function recommendTimesControl(value, noneSaid) {
  const box = document.createElement("div");
  box.className = "times-control";
  const times = String(value || "").split(/[,\s]+/).filter((one) => /^\d{1,2}:\d{2}$/.test(one));
  const changed = () => box.dispatchEvent(new Event("change"));
  const row = (time) => {
    const one = document.createElement("span");
    one.className = "times-one";
    one.innerHTML = `<input type="time" value="${escapeHtml(time)}" aria-label="Time">
      <button type="button" class="small secondary x-remove" aria-label="Remove this time">&times;</button>`;
    one.querySelector("input").addEventListener("change", (event) => {
      event.stopPropagation();
      changed();
    });
    one.querySelector("button").addEventListener("click", () => {
      one.remove();
      saysNone();
      changed();
    });
    box.insertBefore(one, add);
    saysNone();
  };
  // EVERY TIME CAN GO: then no issue is made by itself - only with
  // "Make an issue now" - and it says so.
  const none = document.createElement("span");
  none.className = "muted times-none";
  none.textContent = noneSaid
    || "No daily time: an issue is made only when you press Make an issue now.";
  const saysNone = () => {
    none.hidden = Boolean(box.querySelector(".times-one"));
  };
  const add = document.createElement("button");
  add.type = "button";
  add.className = "small secondary";
  add.textContent = "Add a time";
  add.addEventListener("click", () => { row("12:00"); changed(); });
  box.appendChild(none);
  box.appendChild(add);
  times.forEach(row);
  saysNone();
  Object.defineProperty(box, "value", {
    get: () => [...box.querySelectorAll("input[type=time]")].map((one) => one.value)
      .filter(Boolean).join(", "),
  });
  return box;
}

/* WHAT IS LISTENED TO (Settings > Privacy): each switch's group, what is
   left without it, and what it costs the computer. */
const PRIVACY_LISTENING = {
  listener_hide_credentials: { group: "Protection",
    off: "Passwords, one-time codes and keys are recorded as they read - and what is "
      + "recorded can be given to a model; a screenshot showing one is kept. (Accounts "
      + "are kept either way, so it can be told whose they were; the agent's own sign-in "
      + "links are cut out either way.)",
    cost: "Light: a few searches of the text, on this computer; a screenshot is read once "
      + "more before it is kept." },
  listener_application_enabled: { group: "What is in front",
    off: "Not even which program or window you use: states, tasks, triggers and the "
      + "reading log lose their footing - the most the agent can lose.",
    cost: "Light: a look at the window in front every second or two." },
  listener_screen_enabled: { group: "What is in front",
    off: "Only window titles are left - a page's text is not read, so states, the "
      + "reading log and the triggers go by titles alone.",
    cost: "The heaviest: the window in front is read every few seconds, about a third "
      + "of a second each time." },
  listener_screenshots_enabled: { group: "What is in front",
    off: "The words in slides, figures and pictures are not read.",
    cost: "Heavy at times: a window is measured, pictured and read on this computer "
      + "when it holds more than text." },
  listener_browser_enabled: { group: "Browser",
    off: "Pages visited are not known from the browser's history - only from titles.",
    cost: "Light: the history is read once a minute." },
  listener_filesystem_enabled: { group: "Files and tools",
    off: "Files created and changed are not known: the agent learns less of your work.",
    cost: "Moderate: the watched folders are followed; many busy folders cost more." },
  listener_integrations_enabled: { group: "Files and tools",
    off: "Applications' own integrations (such as an editor's) report nothing.",
    cost: "Light." },
  listener_assistant_enabled: { group: "Files and tools",
    off: "Work done through coding assistants is not known - which project, when, for how "
      + "long. (What was said is the next switch.)",
    cost: "Light: their session files are read when they change." },
  listener_assistant_content_tools: { group: "Files and tools",
    off: "An assistant not ticked: what you and it said is not recorded - only that a "
      + "session happened, if Assistant activity is on.",
    cost: "Moderate: conversations are read as they grow." },
};

/* EACH SETTINGS CARD: changed where it stands - no Edit. A change is held
   until Save, which appears once something is changed and sends what was;
   Cancel puts the card back. `pending` what was changed, by setting;
   `hostOf` the card each was changed in. */
const settingsEdit = { pending: {}, labels: {}, hostOf: {} };

/* The page's header is sticky and its height changes with the window (its
   tabs wrap): kept as --header-h, for what sits just under it. */
(() => {
  // A page with no document to measure (a script read on its own) has none.
  if (typeof document === "undefined" || typeof document.querySelector !== "function") return;
  const header = document.querySelector("body > header, header");
  if (!header || !document.documentElement) return;
  const said = () => document.documentElement.style.setProperty(
    "--header-h", `${header.offsetHeight}px`);
  said();
  if (typeof ResizeObserver === "function") new ResizeObserver(said).observe(header);
  else window.addEventListener("resize", said);
})();

function settingsPendingIn(hostId) {
  return Object.keys(settingsEdit.pending).filter((key) => settingsEdit.hostOf[key] === hostId);
}

function settingsEditBar(host) {
  const bar = document.createElement("div");
  bar.className = "settings-edit-bar settings-save-bar";
  bar.dataset.saveBar = host.id;
  bar.innerHTML = `<span class="muted">Not saved yet</span>
    <button type="button" class="small" data-settings-save="${escapeHtml(host.id)}">Save</button>
    <button type="button" class="small secondary" data-settings-cancel="${
      escapeHtml(host.id)}">Cancel</button>`;
  bar.hidden = !settingsPendingIn(host.id).length;
  host.prepend(bar);
}

/* A setting changed in `row`: held, and its card's Save shown. */
function settingsChanged(row, key, value, label) {
  const host = row.closest?.("#settings-form, #settings-form-display, "
    + "#settings-form-heartbeats, #settings-form-privacy, #settings-form-startup");
  settingsEdit.pending[key] = value;
  settingsEdit.labels[key] = label;
  if (!host) return;
  settingsEdit.hostOf[key] = host.id;
  const bar = host.querySelector(`[data-save-bar="${host.id}"]`);
  if (bar) bar.hidden = false;
  if (key === "start_at_login") startupHeld();
}

document.addEventListener("click", async (event) => {
  const cancel = event.target.closest?.("[data-settings-cancel]");
  if (cancel) {
    settingsPendingIn(cancel.dataset.settingsCancel)
      .forEach((key) => { delete settingsEdit.pending[key]; });
    await loadSettings();
    return;
  }
  const save = event.target.closest?.("[data-settings-save]");
  if (!save) return;
  const keys = settingsPendingIn(save.dataset.settingsSave);
  const values = Object.fromEntries(keys.map((key) => [key, settingsEdit.pending[key]]));
  save.disabled = true;
  try {
    if (keys.length) {
      await api.post("/api/settings", { values });
      toast(`Saved: ${keys.map((key) =>
        (HEARTBEAT_MINUTES[key] || {}).label || settingsEdit.labels[key] || key).join(", ")}`);
    }
    keys.forEach((key) => { delete settingsEdit.pending[key]; });
    // The screens in the other language: drawn again, whole.
    if ("display_language" in values) {
      setTimeout(() => window.location.reload(), 300);
      return;
    }
    await loadSettings();
  } catch (err) {
    toast(err.message, "error");
    save.disabled = false;
  }
});

function renderSettings(data) {
  // The agent's data folder: shown, never listened to, never changed here.
  settingsEdit.dataFolder = String(((data || {}).values || {}).agent_root || "");
  // Another copy of the program already starts at sign-in (autostart.py).
  settingsEdit.startHeldBy = String((data || {}).start_at_login_held_by || "");
  settingsEdit.startOn = Boolean(((data || {}).values || {}).start_at_login);
  // DISPLAY: the language the agent writes and speaks in, its avatar and
  // the size of its text - each under its own heading. Every other setting
  // is in Others; the models have General.
  const DISPLAY_SETTINGS = { display_language: "Language",
                             font_size: "Text size", popup_font_size: "Text size" };
  // AVATAR: which one, and what it is called - on a panel of its own.
  const AVATAR_SETTINGS = { character: "Avatar", agent_name: "Avatar" };
  const avatarHost = $("#settings-form-avatar");
  // PRIVACY: what is listened to - each with what is left without it, and
  // what it costs the computer.
  const PRIVACY_SETTINGS = PRIVACY_LISTENING;
  refreshBrowserCard();
  const container = $("#settings-form");
  // Display's own settings; where there is no Display, with the rest.
  const display = $("#settings-form-display") || container;
  // The heartbeats, on General, in minutes.
  const beats = $("#settings-form-heartbeats") || container;
  // What is listened to, on Privacy.
  const privacy = $("#settings-form-privacy") || container;
  if (privacy !== container) privacy.innerHTML = "";
  // Starting when the user signs in, on General.
  const startup = $("#settings-form-startup") || container;
  if (startup !== container) startup.innerHTML = "";
  // Updates, on General.
  const updatesHost = $("#settings-form-updates") || container;
  if (updatesHost !== container) updatesHost.innerHTML = "";
  if (typeof refreshUpdates === "function") refreshUpdates();
  container.innerHTML = "";
  if (display !== container) display.innerHTML = "";
  if (avatarHost) avatarHost.innerHTML = "";
  if (beats !== container) beats.innerHTML = "";
  // Section 12.1: what the user chose is theirs, and undoing it is possible.
  const chosen = data.user_defaults || {};
  const chosenCount = Object.keys(chosen).length;
  const note = $("#settings-defaults-note");
  if (note) {
    note.textContent = chosenCount
      ? `${chosenCount} of these are your own defaults, and travel with the agent root`
      : "";
  }
  const sections = {};
  const hostOf = {};
  data.schema.forEach((field) => {
    // Section 25, as amended: a control is not a settings row.
    if (field.hidden) return;
    const looks = Boolean(avatarHost) && field.key in AVATAR_SETTINGS;
    const mine = field.key in DISPLAY_SETTINGS;
    const beat = field.key in HEARTBEAT_MINUTES;
    const heard = field.key in PRIVACY_SETTINGS;
    const starts = field.key === "start_at_login";
    const updating = field.key === "updates";
    const section = looks ? AVATAR_SETTINGS[field.key] : mine ? DISPLAY_SETTINGS[field.key]
      : beat ? "Heartbeats" : heard ? PRIVACY_SETTINGS[field.key].group
      : starts ? "Startup" : updating ? "Updates" : field.section;
    const key = `${looks ? "a" : mine ? "d" : beat ? "h" : heard ? "p" : starts ? "s"
      : updating ? "u" : "o"}|${section}`;
    hostOf[key] = looks ? avatarHost : mine ? display : beat ? beats : heard ? privacy
      : starts ? startup : updating ? updatesHost : container;
    (sections[key] = sections[key] || []).push(field);
  });
  Object.entries(sections).forEach(([key, fields]) => {
    const section = key.slice(2);
    const host = hostOf[key];
    const title = document.createElement("div");
    title.className = "section-title";
    title.textContent = section;
    host.appendChild(title);
    fields.forEach((field) => {
      const row = document.createElement("div");
      row.className = "setting-row";
      // Changed and not saved yet (in another card, saved first): kept.
      const value = field.key in settingsEdit.pending ? settingsEdit.pending[field.key]
        : data.values[field.key];
      let control;
      if (field.type === "bool") {
        control = document.createElement("input");
        control.type = "checkbox";
        control.checked = Boolean(value);
      } else if (field.type === "choice" || field.type === "dynamic_choice") {
        control = document.createElement("select");
        const options = field.choices || data.choices[field.choices_source] || [];
        const notes = (data.choice_notes || {})[field.key] || {};
        // Primary models are stored separately from their provider, while
        // picker options use provider/model. Match the same representation.
        const selectedValue = field.key === "primary_model" && value && !String(value).includes("/")
          ? `${data.values.primary_provider}/${value}` : value;
        // Each option by its full name where the server gives one.
        const labels = field.key === "updates" ? UPDATE_CHOICES
          : (data.choice_labels || {})[field.key] || {};
        control.innerHTML = options
          .map((o) => `<option value="${escapeHtml(String(o))}" ${
            o === selectedValue ? "selected" : ""}>${escapeHtml(
              field.key === "primary_reasoning_effort" && o === "default"
                ? "Use Codex default" : String(labels[o] || o))}</option>`)
          .join("");
        // A saved value the list no longer offers is shown as what it is,
        // not silently replaced by the first option - which a save would
        // then write over the user's choice.
        if (["primary_model", "primary_reasoning_effort"].includes(field.key)
            && selectedValue && !options.includes(selectedValue)) {
          const current = document.createElement("option");
          current.value = selectedValue;
          current.textContent = field.key === "primary_reasoning_effort"
            ? `${selectedValue} (not taken by this model)`
            : `${selectedValue} (current; not in the model list)`;
          current.selected = true;
          control.appendChild(current);
        }
      } else if (field.type === "multi_choice") {
        // Section 18, as amended: what is actually on this machine, ticked.
        //
        // Typing a name into a box means knowing what the application calls
        // the thing, and being told nothing when the spelling is wrong. The
        // list is detected, so the choice is recognition rather than recall,
        // and anything known but absent is shown as absent rather than left
        // out - an option that is quietly missing cannot be reasoned about.
        control = multiChoiceControl(field, value, data);
      } else if (field.key === "recommend_times") {
        // TIMES OF DAY, as many as wanted: each a time box, one added or
        // taken off - kept as "08:00, 18:30".
        control = recommendTimesControl(value);
      } else if (field.key in HEARTBEAT_MINUTES) {
        // In minutes, whatever it is kept in.
        control = document.createElement("input");
        control.type = "number";
        control.min = "1";
        control.step = "1";
        control.value = String(Math.round(HEARTBEAT_MINUTES[field.key].shown(Number(value) || 0)));
      } else if (field.chooser && !field.readonly) {
        control = chosenValueControl(field, value);
      } else if (field.type === "int" && field.key.endsWith("_seconds")) {
        // Stored in seconds, set in whatever the reader counts in.
        control = durationControl(field, value);
      } else if (field.type === "multiline") {
        control = document.createElement("textarea");
        control.rows = 3;
        control.value = value ?? "";
      } else {
        control = document.createElement("input");
        control.type = ["int", "float"].includes(field.type) ? "number" : "text";
        if (field.type === "float") control.step = "0.1";
        control.value = value ?? "";
      }
      // Which setting it is, for what is drawn beside it.
      if (control && control.dataset) control.dataset.key = field.key;
      // A derived value (section 110.1) is shown, not offered for editing: an
      // input that silently refuses what you type is worse than a plain value.
      if (field.readonly) {
        control.disabled = true;
        control.classList.add("readonly");
      } else if (control.dataset.heldUntilSave === "1") {
        // A directory chosen, or taken off: held until Save too.
        control.addEventListener("held", (event) => {
          settingsChanged(row, field.key, event.detail, field.label);
        });
      } else {
        // Typed: Save appears with the first letter, not when the box is left.
        if (control.tagName !== "SELECT" && control.type !== "checkbox") {
          control.addEventListener("input", () => control.dispatchEvent(new Event("change")));
        }
        control.addEventListener("change", async () => {
          // HELD UNTIL SAVE: the card's Save sends it all.
          const raw = field.type === "bool" ? control.checked : control.value;
          settingsChanged(row, field.key, field.key in HEARTBEAT_MINUTES
            ? HEARTBEAT_MINUTES[field.key].kept(Number(raw) || 1) : raw, field.label);
          if (settingsEdit.pending) return;
          const newValue = raw;
          try {
            const saved = await api.post("/api/settings", { values: { [field.key]: newValue } });
            // A model that does not take the effort chosen puts it back to
            // the default, and says so here rather than at the next call.
            const reset = saved?.corrected?.primary_reasoning_effort === "default"
              ? "; reasoning effort reset to the Codex default" : "";
            toast(`${field.label} saved${field.restart_required ? " (restart required)" : ""}${reset}`);
            if (["primary_model", "primary_provider", "primary_reasoning_effort"]
              .includes(field.key)) {
              await loadSettings();
              return;
            }
            // The screens in the other language: drawn again, whole.
            if (field.key === "display_language") {
              setTimeout(() => window.location.reload(), 300);
              return;
            }
            // Section 76.1: choosing a client that is not installed is
            // answered at the moment it is chosen, not later by silence.
            const note = ((data.choice_notes || {})[field.key] || {})[newValue];
            if (note) {
              const missing = /not installed/i.test(note);
              const line = row.querySelector(".choice-note") || (() => {
                const el = document.createElement("div");
                el.className = "choice-note";
                row.appendChild(el);
                return el;
              })();
              line.textContent = note;
              line.classList.toggle("warn", missing);
              if (missing) toast(note, "error");
            }
          } catch (err) {
            toast(err.message, "error");
          }
        });
      }
      const label = document.createElement("div");
      const tags = [];
      // Two different things (section 12, as amended): "this follows the
      // agent root, change that instead" and "the machinery takes a choice
      // here and this version does not offer one". A field that says
      // read-only when it means fixed sends the reader looking for the
      // setting it derives from, and there is not one.
      if (field.fixed) tags.push("fixed in this version");
      else if (field.readonly) tags.push("read-only");
      if (field.restart_required) tags.push("restart");
      // "your default" used to be tagged here as well as offered as an undo
      // button beneath the description. Two notices for one fact, and the tag
      // was the one that could not be acted on.
      label.innerHTML = `${escapeHtml((HEARTBEAT_MINUTES[field.key] || {}).label
        || field.label)}${
        tags.length ? ` <span class="muted">(${tags.join(", ")})</span>` : ""}`;
      row.appendChild(label);
      if (field.key === "primary_model") {
        // Codex's list is read from its own cache, which lags behind what
        // the account can use. This asks the installed Codex, now.
        const picker = document.createElement("div");
        picker.className = "model-picker";
        const refresh = document.createElement("button");
        refresh.type = "button";
        refresh.className = "small secondary refresh-models";
        refresh.disabled = codexModelsRefreshing;
        refresh.textContent = codexModelsRefreshing ? "Refreshing…" : "Refresh models";
        refresh.title = "Ask the installed Codex for its current model list";
        refresh.addEventListener("click", async () => {
          if (codexModelsRefreshing) return;
          codexModelsRefreshing = true;
          refresh.disabled = true;
          refresh.textContent = "Refreshing…";
          try {
            await api.post("/api/models/codex/refresh", {});
            await loadSettings();
            toast("Codex model list refreshed");
          } catch (err) {
            toast(err.message, "error");
          } finally {
            codexModelsRefreshing = false;
            // Settings may have been drawn again while this waited: the
            // button to restore is whichever one is on the page now.
            $$(".refresh-models").forEach((button) => {
              button.disabled = false;
              button.textContent = "Refresh models";
            });
          }
        });
        picker.append(control, refresh);
        row.appendChild(picker);
      } else {
        row.appendChild(control);
      }
      // Section 12, as amended: every setting explains itself, beneath its
      // control, in a smaller and visually secondary style.
      if (field.description) {
        const desc = document.createElement("div");
        desc.className = "muted desc";
        desc.textContent = field.description;
        if (Object.prototype.hasOwnProperty.call(chosen, field.key)) {
          const undo = document.createElement("button");
          undo.type = "button";
          undo.className = "small secondary undo-default";
          undo.textContent = "Use the built-in default";
          undo.addEventListener("click", async () => {
            try {
              await api.post("/api/settings/reset", { key: field.key });
              toast(`${field.label} reset`);
              await loadSettings();
            } catch (err) {
              toast(err.message, "error");
            }
          });
          desc.appendChild(undo);
        }
        row.appendChild(desc);
      }
      // A listening switch: what is left without it, and what it costs.
      const heard = PRIVACY_LISTENING[field.key];
      if (heard) {
        const said = document.createElement("div");
        said.className = "privacy-says";
        said.innerHTML = `<div><strong>If turned off:</strong> ${escapeHtml(heard.off)}</div>
          <div class="privacy-cost"><strong>Performance influence:</strong> ${
            escapeHtml(heard.cost)}</div>`;
        row.appendChild(said);
      }
      // What the operating system must allow for it, filled in once looked at
      // (sysPermissionsDraw).
      if (heard || field.key === "notifications_enabled") {
        const allowed = document.createElement("div");
        allowed.className = "sys-permission";
        allowed.dataset.sysPermissionFor = field.key;
        row.appendChild(allowed);
      }
      const note = ((data.choice_notes || {})[field.key] || {})[value];
      if (note) {
        const line = document.createElement("div");
        line.className = "choice-note";
        if (/not installed/i.test(note)) line.classList.add("warn");
        line.textContent = note;
        row.appendChild(line);
      }
      // The editor belongs with the character setting, not as an unrelated
      // panel after every other Settings section.
      host.appendChild(row);
    });
  });
  // Each card shown, until Edit.
  if (typeof avatarFormDrawn === "function") avatarFormDrawn(data);
  [...new Set([beats, display, avatarHost, privacy, startup, updatesHost, container])].forEach((host) => {
    if (host && host.id) settingsEditBar(host);
  });
  startupHeld();
}

/* STARTING AT SIGN-IN, WHEN ANOTHER COPY ALREADY DOES. The system's entry
   is one for every copy of the program, and it is not taken from a copy
   still on this machine (autostart.py): while the switch here is on, it
   says which copy holds it and its card cannot be saved until it is off. */
function startupHeld() {
  const host = typeof document !== "undefined" ? $("#settings-form-startup") : null;
  if (!host) return;
  const on = "start_at_login" in settingsEdit.pending
    ? Boolean(settingsEdit.pending.start_at_login) : Boolean(settingsEdit.startOn);
  const held = Boolean(settingsEdit.startHeldBy) && on;
  let note = host.querySelector("[data-start-held]");
  if (!note) {
    note = document.createElement("div");
    note.className = "start-held-note";
    note.dataset.startHeld = "1";
    host.appendChild(note);
  }
  note.hidden = !held;
  note.textContent = held ? `Another copy of Personal Agent WaterMelon already starts when you sign in: ${
    settingsEdit.startHeldBy}. Untick this to save, or turn it off in that copy first.` : "";
  const save = host.querySelector("[data-settings-save]");
  if (save) save.disabled = held;
}

/* -------------------------------------------------------------- debugger */
/* The System Debugger (section 14) lives in debugger.js: an interactive system
   map, component/connection inspectors and a trace timeline. */
async function loadDebugger() {
  if (window.debuggerPanel) await window.debuggerPanel.activate();
}

/* ------------------------------------------------------------ utilities */
function escapeHtml(text) {
  return String(text ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])
  );
}
function truncate(text, max) {
  const value = String(text ?? "");
  return value.length > max ? `${value.slice(0, max)}…` : value;
}
function badgeClass(status) {
  if (status === "completed") return "ok";
  if (["failed", "cancelled"].includes(status)) return "err";
  return "warn";
}

/* ------------------------------------------------------------- avatar */
function wireAvatarEditor() {
  const canvas = $("#pixel-painter");
  if (!canvas) return;
  const context = canvas.getContext("2d");
  let colour = $("#painter-colour").value;
  let brushSize = Number($("#painter-brush-size").value);
  let erasing = false;
  let pendingImage = "";
  let undoImage = null;
  let strokeBefore = null;
  let backgroundBase = null;
  context.clearRect(0, 0, 16, 16);
  const undo = $("#painter-undo");
  const recentHost = $("#painter-recent-colours");
  let recentColours = [];
  try { recentColours = JSON.parse(localStorage.getItem("pa-avatar-recent-colours") || "[]"); }
  catch (_err) { recentColours = []; }
  recentColours = recentColours.filter((item) => /^#[0-9a-f]{6}$/i.test(item)).slice(0, 5);

  const renderRecentColours = () => {
    recentHost.innerHTML = "";
    recentColours.forEach((recent) => {
      const swatch = document.createElement("button");
      swatch.type = "button";
      swatch.className = "recent-colour";
      swatch.style.backgroundColor = recent;
      swatch.title = `Use ${recent}`;
      swatch.setAttribute("aria-label", `Use recent colour ${recent}`);
      swatch.addEventListener("click", () => {
        colour = recent;
        $("#painter-colour").value = recent;
        erasing = false;
        $("#painter-erase").classList.remove("active");
      });
      recentHost.appendChild(swatch);
    });
  };
  const recordColour = () => {
    recentColours = [colour, ...recentColours.filter((item) => item !== colour)].slice(0, 5);
    try { localStorage.setItem("pa-avatar-recent-colours", JSON.stringify(recentColours)); }
    catch (_err) { /* recent colours still work for this page session */ }
    renderRecentColours();
  };
  renderRecentColours();

  const draw = (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.max(0, Math.min(15, Math.floor((event.clientX - rect.left) * 16 / rect.width)));
    const y = Math.max(0, Math.min(15, Math.floor((event.clientY - rect.top) * 16 / rect.height)));
    const startX = Math.max(0, x - Math.floor(brushSize / 2));
    const startY = Math.max(0, y - Math.floor(brushSize / 2));
    const width = Math.min(brushSize, 16 - startX);
    const height = Math.min(brushSize, 16 - startY);
    if (erasing) context.clearRect(startX, startY, width, height);
    else { context.fillStyle = colour; context.fillRect(startX, startY, width, height); }
  };
  let painting = false;
  canvas.addEventListener("pointerdown", (event) => {
    // A later paint stroke becomes part of the artwork. Its background may be
    // chosen again after saving or clearing it, rather than silently using a
    // stale snapshot.
    backgroundBase = null;
    strokeBefore = context.getImageData(0, 0, 16, 16);
    if (!erasing) recordColour();
    painting = true; canvas.setPointerCapture(event.pointerId); draw(event);
  });
  canvas.addEventListener("pointermove", (event) => { if (painting) draw(event); });
  canvas.addEventListener("pointerup", () => {
    painting = false;
    undoImage = strokeBefore;
    undo.disabled = !undoImage;
    strokeBefore = null;
  });
  canvas.addEventListener("pointercancel", () => { painting = false; strokeBefore = null; });
  $("#painter-colour").addEventListener("input", (event) => { colour = event.target.value; erasing = false; });
  $("#painter-brush-size").addEventListener("change", (event) => {
    brushSize = Number(event.target.value);
  });
  $("#painter-erase").addEventListener("click", () => { erasing = !erasing; $("#painter-erase").classList.toggle("active", erasing); });
  undo.addEventListener("click", () => {
    if (!undoImage) return;
    context.putImageData(undoImage, 0, 0);
    undoImage = null;
    undo.disabled = true;
  });
  $("#painter-clear").addEventListener("click", () => {
    undoImage = context.getImageData(0, 0, 16, 16);
    backgroundBase = null;
    context.clearRect(0, 0, 16, 16);
    undo.disabled = false;
  });
  $("#painter-apply-background").addEventListener("click", () => {
    // destination-over changes only transparent pixels, so this can be used
    // after painting without covering any of the pixel art. Keep the original
    // artwork separately so clicking this again replaces the prior background
    // rather than finding no transparency left to fill.
    undoImage = context.getImageData(0, 0, 16, 16);
    if (!backgroundBase) backgroundBase = context.getImageData(0, 0, 16, 16);
    context.putImageData(backgroundBase, 0, 0);
    context.save();
    context.globalCompositeOperation = "destination-over";
    context.fillStyle = $("#painter-background-colour").value;
    context.fillRect(0, 0, 16, 16);
    context.restore();
    undo.disabled = false;
  });

  async function save(image, pixelArt = false) {
    try {
      const result = await api.post("/api/characters/avatar", { image, pixel_art: pixelArt });
      $("#avatar-preview").src = result.preview;
      toast("Custom avatar saved and selected");
      await loadSettings();
    } catch (err) { toast(err.message, "error"); }
  }
  $("#avatar-file").addEventListener("change", (event) => {
    const file = event.target.files && event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => { pendingImage = reader.result; $("#avatar-preview").src = pendingImage; $("#avatar-upload-save").disabled = false; };
    reader.readAsDataURL(file);
  });
  $("#avatar-upload-save").addEventListener("click", () => { if (pendingImage) save(pendingImage); });
  $("#painter-save").addEventListener("click", () => save(canvas.toDataURL("image/png"), true));
}

/* THE AVATAR PANEL: the avatar alive, as on the desktop - drawn over its
   body and leaves from its rig (agent/character/watermelon.py, the same
   numbers): eyes on the pointer, a blink now and then, a smile when pointed
   at, a hop when clicked, and what it does while it talks, thinks or
   notifies. An avatar without a rig is its picture. */
const avatarStage = { list: null, chosen: "", mood: "idle", look: [0, 0], aim: [0, 0],
                      blinkAt: 0, hover: false, poked: -10, running: false, svg: null,
                      started: 0 };

async function loadAvatars() {
  try {
    const said = await api.get("/api/characters?layers=1");
    avatarStage.list = said.characters || [];
    if (!avatarStage.chosen) avatarStage.chosen = said.selected || "";
  } catch (_err) {
    avatarStage.list = avatarStage.list || [];
  }
  drawAvatarStage();
}

/* The form, drawn: the avatar list by name, and the name box saying what
   the avatar is called when it is left empty. */
function avatarFormDrawn(data) {
  const host = $("#settings-form-avatar");
  if (!host) return;
  const pick = host.querySelector('[data-key="character"]');
  const named = host.querySelector('[data-key="agent_name"]');
  const chosen = String(((data || {}).values || {}).character || "");
  if (chosen) avatarStage.chosen = pick ? pick.value || chosen : chosen;
  const ownName = () => {
    const one = (avatarStage.list || []).find((c) => c && c.name === avatarStage.chosen);
    return (one && one.display_name) || avatarStage.chosen || "";
  };
  const sayName = () => {
    if (!named) return;
    named.placeholder = ownName();
    let note = host.querySelector(".avatar-name-note");
    if (!note) {
      note = document.createElement("div");
      note.className = "choice-note avatar-name-note";
      named.closest(".setting-row")?.appendChild(note);
    }
    note.textContent = named.value.trim()
      ? `It is called ${named.value.trim()}.`
      : `Left empty, it is called by its own name: ${ownName()}.`;
  };
  if (pick) {
    pick.addEventListener("change", () => {
      avatarStage.chosen = pick.value;
      sayName();
      drawAvatarStage();
    });
  }
  if (named) named.addEventListener("input", sayName);
  if (avatarStage.list === null) loadAvatars().then(sayName);
  else { sayName(); drawAvatarStage(); }
}

function avatarArc(cx, cy, rx, ry, from, to) {
  // As PIL draws an arc: degrees clockwise from three o'clock.
  const points = [];
  for (let i = 0; i <= 24; i += 1) {
    const a = (from + (to - from) * (i / 24)) * Math.PI / 180;
    points.push(`${(cx + rx * Math.cos(a)).toFixed(2)},${(cy + ry * Math.sin(a)).toFixed(2)}`);
  }
  return `M${points.join(" L")}`;
}

/* A box's arc, as PIL's ImageDraw.arc takes it. */
function avatarBoxArc(x0, y0, x1, y1, from, to) {
  return avatarArc((x0 + x1) / 2, (y0 + y1) / 2, (x1 - x0) / 2, (y1 - y0) / 2, from, to);
}

function avatarFace(rig, mood, look, blink, t) {
  const c = rig.colours || {};
  const happy = mood === "hover";
  const [lx, ly] = look;
  const parts = [];
  rig.eyes.forEach(([cx, cy, rx, ry, ir], i) => {
    const lift = mood === "notification" || happy ? -2.2 : 0;
    const tilt = mood === "thinking" && i === 0 ? 2 : 0;
    const bx = cx + (rig.brow_shift ?? -1);
    const [from, to] = rig.brow_arc || [200, 320];
    parts.push(`<path d="${avatarBoxArc(bx - rx * 0.95, cy - ry - 8 + lift - tilt,
      bx + rx * 0.95, cy - ry + 2 + lift, from, to)}" stroke="${c.brow}" stroke-width="1.6"
      fill="none" stroke-linecap="round"/>`);
    if (happy) {
      parts.push(`<path d="${avatarBoxArc(cx - rx * 0.8, cy - ry * 0.5, cx + rx * 0.8,
        cy + ry * 0.7, 200, 340)}" stroke="${c.iris}" stroke-width="1.8" fill="none"
        stroke-linecap="round"/>`);
      return;
    }
    const open = Math.max(0, 1 - blink);
    if (open < 0.15) {
      parts.push(`<path d="${avatarBoxArc(cx - rx, cy - ry * 0.4, cx + rx, cy + ry * 0.4,
        10, 170)}" stroke="${c.iris}" stroke-width="1.6" fill="none" stroke-linecap="round"/>`);
      return;
    }
    const ery = ry * open;
    const px = cx + lx * (rx - ir * 0.75);
    const py = cy + ly * Math.max(0, ery - ir * 0.7);
    const irr = Math.min(ir, ery);
    parts.push(`<ellipse cx="${cx}" cy="${cy}" rx="${rx + 1.1}" ry="${ery + 1.1}" fill="${c.ink}"/>
      <ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ery}" fill="${c.cream}"/>
      <ellipse cx="${px}" cy="${py}" rx="${ir}" ry="${irr}" fill="${c.iris}"/>
      <ellipse cx="${px}" cy="${py}" rx="${ir * 0.55}" ry="${irr * 0.55}" fill="${c.pupil}"/>
      <circle cx="${px + ir * 0.35}" cy="${py - irr * 0.45}" r="${ir * 0.32}" fill="#fff"/>
      <circle cx="${px - ir * 0.35}" cy="${py + irr * 0.35}" r="${ir * 0.14}" fill="#fff"
        fill-opacity="0.86"/>`);
  });
  const [mx, my] = rig.mouth;
  if (mood === "talking") {
    const h = 3.5 + 2.5 * Math.abs(Math.sin(t * 9));
    parts.push(`<ellipse cx="${mx}" cy="${my + 1}" rx="4.2" ry="${h}" fill="#461814"
      stroke="${c.ink}" stroke-width="1.1"/>
      <ellipse cx="${mx}" cy="${my + 1 + h * 0.5}" rx="2.6" ry="${h * 0.35}" fill="#d65c5c"/>`);
  } else if (mood === "thinking") {
    parts.push(`<path d="M${mx - 3},${my + 1} L${mx + 3},${my - 0.5}" stroke="${c.ink}"
      stroke-width="1.4" stroke-linecap="round"/>`);
  } else {
    const w = happy ? 6.5 : 5;
    parts.push(`<path d="${avatarBoxArc(mx - w, my - 4, mx + w, my + 3.5, 20, 160)}"
      stroke="${c.ink}" stroke-width="1.5" fill="none" stroke-linecap="round"/>`);
  }
  if (mood === "notification") {
    (rig.cheeks || [[76, 69], [112, 64]]).forEach(([x, y]) => parts.push(
      `<ellipse cx="${x}" cy="${y}" rx="3.6" ry="2" fill="${c.blush}" fill-opacity="0.43"/>`));
  }
  return parts.join("");
}

function avatarExtras(rig, mood, t) {
  const c = rig.colours || {};
  if (mood === "notification") {
    const [x, y, r] = rig.badge || [114, 16, 10];
    return `<circle cx="${x}" cy="${y}" r="${r}" fill="#e24040" stroke="#fff" stroke-width="1.6"/>
      <path d="M${x},${y - 5.5} L${x},${y + 2.5}" stroke="#fff" stroke-width="2.4" stroke-linecap="round"/>
      <circle cx="${x}" cy="${y + 5.6}" r="1.4" fill="#fff"/>`;
  }
  if (mood === "thinking") {
    const shown = Math.floor(t * 2.5) % 4;
    return (rig.bubbles || [[100, 24, 2.2], [108, 16, 3], [118, 7, 3.8]])
      .filter((_one, i) => i < shown)
      .map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" fill-opacity="0.92"
        stroke="${c.outline}" stroke-width="0.8"/>`).join("");
  }
  return "";
}

function drawAvatarStage() {
  const host = $("#avatar-stage");
  if (!host) return;
  const one = (avatarStage.list || []).find((c) => c && c.name === avatarStage.chosen)
    || (avatarStage.list || [])[0];
  if (!one) {
    host.innerHTML = `<p class="muted">Reading the avatars&hellip;</p>`;
    return;
  }
  const rig = one.rig;
  const layers = one.layers || {};
  if (!rig || !layers.body) {
    host.innerHTML = one.preview
      ? `<img class="avatar-still" src="${escapeHtml(one.preview)}" alt="${escapeHtml(
        one.display_name || one.name)}">` : "";
    avatarStage.svg = null;
    return;
  }
  host.innerHTML = `<svg viewBox="0 0 128 128" class="avatar-svg" role="img"
      aria-label="${escapeHtml(one.display_name || one.name)}">
    <g class="avatar-extras"></g>
    <image href="${layers.leaves}" x="0" y="0" width="128" height="128"/>
    <g class="avatar-body"><image href="${layers.body}" x="0" y="0" width="128" height="128"/>
      <g class="avatar-face"></g></g>
    <g class="avatar-over"></g>
  </svg>`;
  avatarStage.svg = host.querySelector("svg");
  avatarStage.rig = rig;
  if (!avatarStage.started) avatarStage.started = performance.now();
  if (!avatarStage.running) {
    avatarStage.running = true;
    requestAnimationFrame(avatarTick);
  }
}

function avatarTick(now) {
  const svg = avatarStage.svg;
  if (!svg || !svg.isConnected) {
    avatarStage.running = false;
    return;
  }
  const t = (now - avatarStage.started) / 1000;
  const rig = avatarStage.rig;
  // Where the pointer is: the eyes turn toward it, easing there.
  avatarStage.look = avatarStage.look.map((v, i) => v + (avatarStage.aim[i] - v) * 0.25);
  // A blink every few seconds.
  if (!avatarStage.blinkAt) avatarStage.blinkAt = t + 2 + Math.random() * 3;
  let blink = 0;
  if (t >= avatarStage.blinkAt) {
    const into = (t - avatarStage.blinkAt) / 0.16;
    blink = into < 1 ? 1 - Math.abs(2 * into - 1) : 0;
    if (into >= 1) avatarStage.blinkAt = t + 2.5 + Math.random() * 3.5;
  }
  const mood = avatarStage.mood !== "idle" ? avatarStage.mood
    : avatarStage.hover ? "hover" : "idle";
  // Breathing; a hop and a squash when clicked, and while it notifies.
  const since = t - avatarStage.poked;
  let squash = 1 + 0.015 * Math.sin((2 * Math.PI * t) / 3.2);
  let hop = 0;
  if (since < 0.7) {
    squash = 1 - 0.18 * Math.exp(-since * 7) * Math.cos(since * 22);
    hop = since < 0.35 ? 7 * Math.sin((Math.PI * since) / 0.35) : 0;
  } else if (mood === "notification") {
    const beat = t % 1.6;
    hop = beat < 0.3 ? 4 * Math.sin((Math.PI * beat) / 0.3) : 0;
  }
  const sx = Math.sqrt(2 - squash);
  const ground = rig.ground || 97;
  svg.querySelector(".avatar-body").setAttribute("transform",
    `translate(64 ${ground - hop}) scale(${sx.toFixed(4)} ${squash.toFixed(4)}) translate(-64 ${-ground})`);
  svg.querySelector(".avatar-face").innerHTML = avatarFace(rig, mood, avatarStage.look, blink, t);
  svg.querySelector(".avatar-over").innerHTML = avatarExtras(rig, mood, t);
  requestAnimationFrame(avatarTick);
}

document.addEventListener("mousemove", (event) => {
  const svg = avatarStage.svg;
  if (!svg || !svg.isConnected) return;
  const box = svg.getBoundingClientRect();
  // From between its eyes, toward the pointer: all the way at 40% of the
  // page's width, as the desktop one does at 150 pixels.
  const [fx, fy] = (avatarStage.rig && avatarStage.rig.looks_from) || [94, 56];
  const cx = box.left + box.width * (fx / 128);
  const cy = box.top + box.height * (fy / 128);
  const reach = Math.max(120, window.innerWidth * 0.4);
  avatarStage.aim = [Math.max(-1, Math.min(1, (event.clientX - cx) / reach)),
                     Math.max(-1, Math.min(1, (event.clientY - cy) / reach))];
  const inside = event.clientX >= box.left && event.clientX <= box.right
    && event.clientY >= box.top && event.clientY <= box.bottom;
  avatarStage.hover = inside;
});

document.addEventListener("click", (event) => {
  if (event.target.closest && event.target.closest("#avatar-stage svg")) {
    avatarStage.poked = (performance.now() - avatarStage.started) / 1000;
  }
  const mood = event.target.closest && event.target.closest("[data-avatar-mood]");
  if (!mood) return;
  avatarStage.mood = mood.dataset.avatarMood;
  $$("[data-avatar-mood]").forEach((one) => one.classList.toggle("active", one === mood));
});

async function loadAvatarPreview() {
  try {
    const avatar = await api.get("/api/characters");
    if (avatar.preview) $("#avatar-preview").src = avatar.preview;
  } catch (_err) { /* the settings panel remains useful while the preview is unavailable */ }
}

/* ---------------------------------------------------------- connections

   THE PEOPLE AROUND THE USER (heartbeat/connections/). The agent adds them
   from what was on screen and from public pages; the user adds, changes,
   deletes, merges and restores them here, and each of those changes - with
   its reason, if one is given - is one of their connection lessons.

   The tab is read when it is opened and after each change, never on a
   timer: a list that redrew itself every fifteen seconds would close the
   group being read and reset the form being typed into. */
const cx = {
  data: null,          // GET /api/connections
  open: null,          // the id of the person on the right
  person: null,        // their details, GET /api/connections/person
  folded: new Set(),   // groups the user closed, kept across redraws
  editing: null,       // the id of the person whose details are being edited
};

/* What the API says when it has not said: the order the groups go in. */
const CX_RELATIONSHIPS = ["family", "partner", "friend", "colleague", "manager", "report",
  "mentor", "student", "classmate", "collaborator", "client", "recruiter",
  "acquaintance", "other"];
const CX_CLOSENESS = { 1: "barely", 2: "loosely", 3: "regularly", 4: "closely", 5: "closest" };

function cxRelationships() {
  return (cx.data && cx.data.relationships) || CX_RELATIONSHIPS;
}

function cxCloseness() {
  return (cx.data && cx.data.closeness) || CX_CLOSENESS;
}

function cxCapital(word) {
  const text = String(word || "");
  return text ? text[0].toUpperCase() + text.slice(1) : text;
}

/* A date or a time in the user's own zone; '' for nothing to show. */
function cxWhen(iso, withTime = true) {
  if (!iso) return "";
  const when = new Date(iso);
  if (Number.isNaN(when.getTime())) return String(iso);
  // With its time zone: a time read without one is a guess at which.
  return withTime ? when.toLocaleString(undefined, {
    year: "numeric", month: "numeric", day: "numeric", hour: "numeric",
    minute: "2-digit", second: "2-digit", timeZoneName: "short" })
    : when.toLocaleDateString();
}

/* A record's times: when it was found (a page read, a window seen) and when
   it was written or last changed - things go out of date. */
function cxTimes(found, updated, created) {
  const parts = [];
  if (found) parts.push(`found ${cxWhen(found, false)}`);
  if (created && created !== updated) parts.push(`recorded ${cxWhen(created, false)}`);
  if (updated) parts.push(`${created && created !== updated ? "updated" : "recorded"} ${
    cxWhen(updated, false)}`);
  return parts.join(" · ");
}

/* A field's times, beside its name in the form. */
function cxFieldTime(person, field) {
  const one = (person.field_times || {})[field];
  if (!one) return "";
  const said = cxTimes(one.found_at, one.updated_at);
  return said ? ` <span class="cx-field-time" title="${escapeHtml(
    `${said}${one.by ? ` · by ${one.by === "user" ? "you" : "the agent"}` : ""}`)}">${
    escapeHtml(cxWhen(one.found_at || one.updated_at, false))}</span>` : "";
}

/* A link only to a web page: an address that is anything else - a script,
   a file on this machine - is shown as words. */
function cxLink(url, text) {
  const words = escapeHtml(text || url);
  if (!/^https?:\/\//i.test(String(url || ""))) return words;
  return `<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${words}</a>`;
}

/* A level out of five as five small dots: closeness, or how much a thing
   to know matters. */
function cxLevel(level, title) {
  const n = Math.max(0, Math.min(5, Number(level) || 0));
  const dots = [1, 2, 3, 4, 5].map((i) => `<i class="${i <= n ? "on" : ""}"></i>`).join("");
  return `<span class="cx-level" role="img" title="${escapeHtml(title)}"
    aria-label="${escapeHtml(title)}">${dots}</span>`;
}

function cxClosenessLevel(person) {
  const n = Number(person.closeness) || 0;
  return cxLevel(n, n ? `Closeness: ${cxCloseness()[n] || n} (${n} of 5)` : "Closeness not rated");
}

/* A bar for the working-out of what the user needs to know: how far it
   has got, and the part it is on. */
function cxProgressHtml(progress, prefix = "") {
  const total = Number(progress.total) || 0;
  const done = Math.min(total, Number(progress.done) || 0);
  const share = total ? Math.round((100 * done) / total) : 0;
  return `<div class="sb-progress cx-progress">
    <div class="sb-progress-bar" role="progressbar" aria-valuemin="0"
      aria-valuemax="${total}" aria-valuenow="${done}"><span style="width:${share}%"></span></div>
    <p class="sb-progress-work">${escapeHtml(prefix)}${escapeHtml(progress.stage || "starting")}${
      total ? ` <span class="muted">(${done} of ${total})</span>` : ""}</p></div>`;
}

function cxOptions(pairs, selected) {
  return pairs.map(([value, label]) => `<option value="${escapeHtml(value)}"${
    String(value) === String(selected ?? "") ? " selected" : ""}>${escapeHtml(label)}</option>`)
    .join("");
}

function cxRelationshipOptions(selected) {
  return cxOptions([["", "Not set"], ...cxRelationships().map((r) => [r, cxCapital(r)])],
                   selected);
}

function cxClosenessOptions(selected) {
  const words = cxCloseness();
  return cxOptions([["0", "Not rated"],
    ...[1, 2, 3, 4, 5].map((n) => [String(n), `${n} - ${words[n] || ""}`])], selected || 0);
}

function cxTags(text) {
  return String(text || "").split(",").map((t) => t.trim()).filter(Boolean);
}

async function loadConnections() {
  try {
    cx.data = (await api.get("/api/connections")) || {};
    renderCxList();
    renderCxAddForm();
    renderCxMe();
    renderCxSuggestions();
    renderCxInbox();

    // The person open on the right is read again too: a change made to
    // them, or a merge into them, shows at once.
    if (cx.open) await openCxPerson(cx.open);
  } catch (err) {
    $("#cx-list").innerHTML = `<p class="muted">Your connections could not be read: ${
      escapeHtml(err.message)}</p>`;
  }
}

/* What the search box matches: every word the user might remember a person
   by. */
function cxMatches(person, query) {
  if (!query) return true;
  const hay = [person.name, ...(person.aliases || []), person.org, person.role,
    ...cxListOf(person, "profession", "professions"),
    ...cxListOf(person, "location", "locations"), ...(person.relationships || []),
    ...(person.affiliations || []).flatMap((a) => [a.org, a.role]),
    person.location, ...(person.tags || []), person.summary].join("\n").toLowerCase();
  return query.toLowerCase().split(/\s+/).filter(Boolean).every((w) => hay.includes(w));
}

/* The people in groups, in the order the chosen grouping reads in. */
function cxGroups(people, by) {
  const groups = new Map();
  const put = (key, label, person) => {
    if (!groups.has(key)) groups.set(key, { key, label, people: [] });
    groups.get(key).people.push(person);
  };
  if (by === "closeness") {
    const words = cxCloseness();
    [5, 4, 3, 2, 1].forEach((n) => groups.set(`c${n}`,
      { key: `c${n}`, label: cxCapital(words[n] || String(n)), people: [] }));
    groups.set("c0", { key: "c0", label: "Not rated", people: [] });
    people.forEach((p) => {
      const n = Number(p.closeness) || 0;
      put(`c${n >= 1 && n <= 5 ? n : 0}`, "Not rated", p);
    });
  } else if (by === "org") {
    // One group per organisation however it was capitalised, named the
    // first way it is written.
    const spelt = new Map();
    people.forEach((p) => {
      const org = String(p.org || "").trim();
      if (org && !spelt.has(org.toLowerCase())) spelt.set(org.toLowerCase(), org);
    });
    [...spelt.values()].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }))
      .forEach((org) => groups.set(`o:${org.toLowerCase()}`,
        { key: `o:${org.toLowerCase()}`, label: org, people: [] }));
    people.forEach((p) => {
      const org = String(p.org || "").trim();
      if (org) put(`o:${org.toLowerCase()}`, org, p);
      else put("o:", "No organisation", p);
    });
  } else {
    cxRelationships().forEach((r) => groups.set(`r:${r}`,
      { key: `r:${r}`, label: cxCapital(r), people: [] }));
    people.forEach((p) => {
      const r = p.relationship || "";
      put(`r:${r}`, r ? cxCapital(r) : "Not set", p);
    });
    // "Not set" last, after every relationship and any the list did not name.
    if (groups.has("r:")) {
      const unset = groups.get("r:");
      groups.delete("r:");
      groups.set("r:", unset);
    }
  }
  return [...groups.values()].filter((g) => g.people.length);
}

/* A PERSON'S PICTURE - from a public profile of theirs - or, with none,
   their initials on a colour of their own (the same name, the same colour). */
function cxAvatar(person, big = false) {
  const cls = `cx-avatar${big ? " cx-avatar-big" : ""}`;
  if (person.avatar) {
    return `<img class="${cls}" alt="" loading="lazy" src="/api/connections/avatar?id=${
      encodeURIComponent(person.id)}&v=${encodeURIComponent(person.avatar_tried_at || "")}">`;
  }
  // The first letter of the first and last words - letters and digits
  // only, so a stray symbol in a name never stands for it.
  const words = String(person.name || "").split(/\s+/)
    .map((w) => (w.match(/[\p{L}\p{N}]/gu) || []).join("")).filter(Boolean);
  const initials = (words.length > 1
    ? Array.from(words[0])[0] + Array.from(words[words.length - 1])[0]
    : Array.from(words[0] || "?").slice(0, 2).join("")).toUpperCase();
  let hue = 0;
  for (const ch of String(person.name || "")) hue = (hue * 31 + ch.codePointAt(0)) % 360;
  return `<span class="${cls} cx-avatar-none" style="--cx-hue:${hue}" aria-hidden="true">${
    escapeHtml(initials)}</span>`;
}

function cxRowHtml(person) {
  const aliases = (person.aliases || []).filter(Boolean);
  const work = [person.org, person.role || person.profession].filter(Boolean).join(" · ");
  const news = person.last_activity_at
    ? `last news ${escapeHtml(cxWhen(person.last_activity_at, false))}` : "no news yet";
  return `<button type="button" class="cx-row${person.id === cx.open ? " selected" : ""}"
      data-cx-person="${escapeHtml(person.id)}">
    ${cxAvatar(person)}
    <span class="cx-row-name"><strong>${escapeHtml(person.name)}</strong>${aliases.length
      ? ` <span class="muted">${escapeHtml(aliases.join(", "))}</span>` : ""}</span>
    <span class="cx-row-work muted">${escapeHtml(work)}</span>
    ${cxClosenessLevel(person)}
    <span class="cx-row-news muted">${news}</span>
  </button>`;
}

function renderCxList() {
  const host = $("#cx-list");
  const people = (cx.data && cx.data.people) || [];
  const query = $("#cx-search").value.trim();
  const shown = people.filter((p) => cxMatches(p, query));
  // Which groups were shut is read off the page before it is drawn again.
  $$("#cx-list details[data-cx-group]").forEach((d) => {
    if (d.open) cx.folded.delete(d.dataset.cxGroup);
    else cx.folded.add(d.dataset.cxGroup);
  });
  $("#cx-count").textContent = query
    ? `${shown.length} of ${people.length} ${people.length === 1 ? "person" : "people"}`
    : `${people.length} ${people.length === 1 ? "person" : "people"}`;
  if (!people.length) {
    host.innerHTML = `<p class="muted">No connections yet. The agent adds people
      from what you have on screen, or add one yourself.</p>`;
    return;
  }
  if (!shown.length) {
    host.innerHTML = `<p class="muted">Nobody matches "${escapeHtml(query)}".</p>`;
    return;
  }
  host.innerHTML = cxGroups(shown, $("#cx-group").value).map((g) => `
    <details class="cx-group" data-cx-group="${escapeHtml(g.key)}"${
      cx.folded.has(g.key) ? "" : " open"}>
      <summary><span class="cx-group-name">${escapeHtml(g.label)}</span>
        <span class="cx-group-count">${g.people.length}</span></summary>
      <div class="cx-rows">${g.people.map(cxRowHtml).join("")}</div>
    </details>`).join("");
}

/* The two lists the add form chooses from are the API's own. */
function renderCxAddForm() {
  const rel = $("#cx-add-relationship");
  const close = $("#cx-add-closeness");
  rel.innerHTML = cxRelationshipOptions(rel.value || "");
  close.innerHTML = cxClosenessOptions(close.value || "0");
}

async function openCxPerson(id) {
  // Another person opened: shown, not being edited.
  if (cx.editing !== id) cx.editing = null;
  cx.open = id;
  $$("#cx-list .cx-row").forEach((row) =>
    row.classList.toggle("selected", row.dataset.cxPerson === id));
  renderCxMe();
  try {
    const person = await api.get(`/api/connections/person?id=${encodeURIComponent(id)}`);
    if (cx.open !== id) return;          // another person was chosen meanwhile
    cx.person = person;
    renderCxPerson(person);
    // No picture yet, a public profile to look on, not tried today: looked
    // for now, in the background, and drawn when it comes.
    const tried = Date.parse(person.avatar_tried_at || "") || 0;
    if (!person.avatar && (person.accounts || []).some((a) => a.url || a.handle)
        && Date.now() - tried > 24 * 3600 * 1000) {
      cxGetPicture(person.id, true);
    }
  } catch (err) {
    cx.open = null;
    cx.person = null;
    $("#cx-person").innerHTML = `<p class="muted">This person could not be read: ${
      escapeHtml(err.message)}</p>`;
  }
}

async function cxGetPicture(id, quiet = false) {
  try {
    const said = await api.post("/api/connections/avatar", { id });
    if (!said.ok && !quiet) toast(said.error || "No public picture found.");
    if (said.ok) {
      await loadConnections();
      if (cx.open === id && said.person) {
        cx.person = Object.assign({}, cx.person, said.person);
        renderCxPerson(cx.person);
      }
    }
  } catch (err) {
    if (!quiet) toast(err.message, "error");
  }
}

/* What changed in one action, as "field: before → after". */
function cxChangeWords(action) {
  const before = action.before || {};
  const after = action.after || {};
  const said = (v) => Array.isArray(v) ? v.join(", ") : String(v ?? "");
  return Object.keys(after).filter((k) => said(before[k]) !== said(after[k]))
    .filter((k) => !["updated_at", "created_at", "user_set", "checked_at"].includes(k))
    .slice(0, 8)
    .map((k) => `${k}: ${said(before[k]) || "–"} → ${said(after[k]) || "–"}`).join("; ");
}

function renderCxPerson(person) {
  // NOT UNDER THE HANDS OF SOMEONE EDITING IT: read again while its form is
  // open - a picture found in the background, the agent's round ending - it
  // was drawn again with what was saved, and what was being typed was gone
  // (a name typed in, back to "You", and Save said nothing had changed).
  // Drawn when the editing ends: saved, or cancelled.
  const form = $("#cx-edit");
  if (cx.editing === person.id && form && form.isConnected) {
    cx.person = Object.assign({}, person);
    return;
  }
  const mine = new Set(person.user_set || []);
  const mark = (field) => (mine.has(field)
    ? ` <span class="cx-mine" title="You set this">set by you</span>` : "")
    + cxFieldTime(person, field);
  const others = ((cx.data && cx.data.people) || []).filter((p) => p.id !== person.id);
  // EACH ACCOUNT CAN BE MOVED to the person it belongs to - asked in its
  // row first, with an optional reason: one of the user's lessons.
  const accounts = (person.accounts || []).map((a) => `<li data-cx-account="${
      escapeHtml(a.id)}">
      <strong>${escapeHtml(a.platform || "account")}</strong>
      ${a.handle ? escapeHtml(a.handle) : ""}
      ${a.url ? cxLink(a.url, a.url) : ""}
      <span class="muted">${escapeHtml(cxTimes(a.found_at, a.updated_at, a.created_at))}</span>
      <button type="button" class="small secondary cx-x" data-cx-profile-remove
        title="Take this profile off" aria-label="Remove">×</button>
      <div class="cx-sure" data-cx-profile-box hidden>
        <span>Take this profile off ${escapeHtml(person.name)}?</span>
        <input type="text" data-cx-profile-reason placeholder="Reason (optional)">
        <button type="button" class="small danger" data-cx-profile-remove-yes="${
          escapeHtml(a.id)}">Yes, take it off</button>
        <button type="button" class="small secondary" data-cx-ask-no>No</button>
      </div>
      ${others.length ? `<button type="button" class="small secondary"
        data-cx-move-ask="${escapeHtml(a.id)}">Move to…</button>
      <div class="cx-sure" data-cx-move-box="${escapeHtml(a.id)}" hidden>
        <label>To <select data-cx-move-to>${cxOptions([["", "choose a person"],
          ...others.map((p) => [p.id, p.name])], "")}</select></label>
        <input type="text" data-cx-move-reason placeholder="Reason (optional)">
        <button type="button" class="small" data-cx-move-yes="${escapeHtml(a.id)}">Move it</button>
        <button type="button" class="small secondary" data-cx-ask-no>No</button>
      </div>` : ""}</li>`).join("");
  const activity = (person.activity || []).map((a) => `<li class="cx-activity">
      <span class="cx-activity-when">${a.at ? escapeHtml(cxWhen(a.at)) : "date unknown"}</span>
      <span>${escapeHtml(a.what)}</span>
      <span class="muted">${escapeHtml(a.source || "")}${a.url ? ` · ${cxLink(a.url, "link")}` : ""}
        · ${escapeHtml(cxTimes(a.found_at, a.updated_at, a.created_at))}</span></li>`).join("");
  const actions = (person.actions || []).map((a) => {
    const change = cxChangeWords(a);
    return `<li><span class="muted">${escapeHtml(cxWhen(a.at))}</span>
      ${a.by === "user" ? "by you" : "by the agent"}: <strong>${escapeHtml(a.action)}</strong>${
      change ? ` <span class="muted">${escapeHtml(change)}</span>` : ""}${
      a.reason ? ` <span class="cx-reason">- ${escapeHtml(a.reason)}</span>` : ""}</li>`;
  }).join("");
  const editing = cx.editing === person.id;
  $("#cx-person").innerHTML = `
    <div class="cx-person-head">
      ${cxAvatar(person, true)}
      <h4>${escapeHtml(person.name)}</h4>
      <button type="button" class="small secondary" data-cx-avatar-get
        title="Look for their picture on their public profiles">${
        person.avatar ? "New picture" : "Get picture"}</button>
      <span class="muted">${person.is_self ? "you" : `added by ${
        person.added_by === "user" ? "you" : "the agent"}`}${
        person.checked_at ? ` · last looked up ${escapeHtml(cxWhen(person.checked_at, false))}`
          : ""}</span>
      ${person.is_self ? `<button type="button" class="small secondary" data-cx-me-run
        title="Look yourself up on the public web now">Look me up now</button>` : ""}
    </div>
    ${editing ? cxEditForm(person, mark) : cxFacts(person, mark, others)}
    <div class="lesson-sure cx-sure" id="cx-delete-ask" hidden>
      <span>Delete ${escapeHtml(person.name)}? You can add them back from
        "Your changes".</span>
      <input id="cx-delete-reason" placeholder="Reason (optional)">
      <button type="button" class="small danger" data-cx-delete-yes>Yes, delete</button>
      <button type="button" class="small secondary" data-cx-ask-no>No, keep</button>
    </div>
    <div class="lesson-sure cx-sure" id="cx-merge-ask" hidden>
      <span>Merge</span>
      <select id="cx-merge-other" aria-label="The person to merge into this one">${
        cxOptions([["", "choose a person"], ...others.map((p) => [p.id, p.name])], "")}</select>
      <span>into ${escapeHtml(person.name)}? They become one person: this one.</span>
      <div id="cx-merge-preview" class="cx-merge-preview"></div>
      <input id="cx-merge-reason" placeholder="Reason (optional)">
      <button type="button" class="small danger" data-cx-merge-yes disabled>Yes, merge</button>
      <button type="button" class="small secondary" data-cx-ask-no>No</button>
    </div>
    <h4>Accounts and profiles</h4>
    ${accounts ? `<ul class="cx-list-plain">${accounts}</ul>`
      : `<p class="muted">No accounts known.</p>`}
    <form class="cx-source-add" data-cx-profile-add>
      <input type="url" placeholder="https://&hellip;" required
        aria-label="Address of another public profile of ${escapeHtml(person.name)}">
      <input name="label" list="cx-label-list" placeholder="Label (e.g. LinkedIn)"
        aria-label="Label of the profile" autocomplete="off">
      <button type="submit" class="small">Add a profile</button>
    </form>
    <h4>What happened</h4>
    ${activity ? `<ul class="cx-list-plain">${activity}</ul>`
      : `<p class="muted">No news yet.</p>`}
    <h4>Changes to this person</h4>
    ${actions ? `<ul class="cx-list-plain cx-actions">${actions}</ul>`
      : `<p class="muted">No changes yet.</p>`}`;
}

/* A PERSON'S DETAILS, SHOWN: their job, what they are to the user - the
   main one first - how close, each organisation with their role there (the
   main one marked), where they are, their other names, tags and summary.
   Edit opens the form. */
function cxFacts(person, mark, others) {
  const none = `<span class="muted">not set</span>`;
  const chips = (items, main) => items.length ? items.map((one, i) => `<span class="cx-chip${
    main && i === 0 ? " cx-chip-main" : ""}"${main && i === 0 ? ' title="The main one"' : ""}>${
    escapeHtml(main ? cxCapital(one) : one)}</span>`).join(" ") : none;
  const rels = person.relationships && person.relationships.length ? person.relationships
    : (person.relationship ? [person.relationship] : []);
  const affs = (person.affiliations && person.affiliations.length) ? person.affiliations
    : (person.org || person.role ? [{ org: person.org || "", role: person.role || "" }] : []);
  const close = Number(person.closeness) || 0;
  const fact = (label, field, body) => `<dt>${escapeHtml(label)}${mark(field)}</dt><dd>${body}</dd>`;
  const jobs = cxListOf(person, "profession", "professions");
  const places = cxListOf(person, "location", "locations");
  const plain = (items) => items.length ? items.map((one, i) => `<span class="cx-chip${
    i === 0 && items.length > 1 ? " cx-chip-main" : ""}"${i === 0 && items.length > 1
    ? ' title="The main one"' : ""}>${escapeHtml(one)}</span>`).join(" ") : none;
  return `<dl class="cx-facts">
      ${fact(jobs.length > 1 ? "Jobs / professions" : "Job / profession",
        (person.user_set || []).includes("professions") ? "professions" : "profession",
        plain(jobs))}
      ${fact(rels.length > 1 ? "Relationships" : "Relationship",
        (person.user_set || []).includes("relationships") ? "relationships" : "relationship",
        chips(rels, true))}
      ${fact("Closeness", "closeness", close
        ? `${cxClosenessLevel(person)} ${escapeHtml(cxCloseness()[close] || "")}` : none)}
      ${fact(affs.length > 1 ? "Organisations" : "Organisation",
        (person.user_set || []).includes("affiliations") ? "affiliations" : "org",
        affs.length ? `<ul class="cx-affiliations">${affs.map((a, i) => `<li>${a.role
          ? `${escapeHtml(a.role)}${a.org ? " at " : ""}` : ""}${a.org
          ? `<strong>${escapeHtml(a.org)}</strong>` : ""}${i === 0 && affs.length > 1
          ? ` <span class="cx-chip cx-chip-main">main</span>` : ""}</li>`).join("")}</ul>` : none)}
      ${fact(places.length > 1 ? "Locations" : "Location",
        (person.user_set || []).includes("locations") ? "locations" : "location",
        plain(places))}
      ${(person.aliases || []).length ? fact("Also known as", "aliases",
        escapeHtml(person.aliases.join(", "))) : ""}
      ${(person.tags || []).length ? fact("Tags", "tags", chips(person.tags, false)) : ""}
      ${person.summary ? fact("Summary", "summary",
        `<span class="cx-summary">${escapeHtml(person.summary)}</span>`) : ""}
    </dl>
    <div class="ov-lp-buttons">
      <button type="button" data-cx-edit-open>Edit</button>
      ${person.is_self ? `<span class="muted cx-me-note">Your own profile: what you
        change is made at once; what the agent finds on your public pages waits in
        the Inbox for you.</span>` : `<button type="button"
        class="secondary danger" data-cx-ask="delete">Delete</button>
      <button type="button" class="secondary" data-cx-ask="merge"${
        others.length ? "" : " disabled"}>Merge&hellip;</button>`}
    </div>`;
}

/* A list of a person's - "profession" the main one of "professions" -
   from before there were lists too. */
function cxListOf(person, single, many) {
  return (person[many] && person[many].length) ? person[many]
    : (person[single] ? [person[single]] : []);
}

/* ONE JOB, OR ONE PLACE, in the form - the main one marked. */
const CX_TEXT_ROWS = {
  job: { label: "Job / profession", placeholder: "e.g. software engineer" },
  place: { label: "Location", placeholder: "e.g. Lisbon" },
};

function cxTextRow(kind, value, main) {
  const said = CX_TEXT_ROWS[kind];
  return `<div class="cx-multi-row" data-cx-text-row="${kind}">
    <label class="cx-main" title="The main one"><input type="radio" name="${kind}-main"${
      main ? " checked" : ""}> main</label>
    <input class="cx-text" autocomplete="off" aria-label="${escapeHtml(said.label)}"
      value="${escapeHtml(value || "")}" placeholder="${escapeHtml(said.placeholder)}">
    <button type="button" class="small secondary cx-x" data-cx-row-remove
      aria-label="Remove" title="Remove">×</button></div>`;
}

/* One relationship in the form - the main one marked - and one
   organisation with the role there. */
function cxRelRow(value, main) {
  return `<div class="cx-multi-row" data-cx-rel-row>
    <label class="cx-main" title="The main one"><input type="radio" name="rel-main"${
      main ? " checked" : ""}> main</label>
    <input class="cx-rel" list="cx-rel-list" autocomplete="off" aria-label="Relationship"
      value="${escapeHtml(value || "")}" placeholder="e.g. colleague">
    <button type="button" class="small secondary cx-x" data-cx-row-remove
      aria-label="Remove" title="Remove">×</button></div>`;
}

function cxAffRow(aff, main) {
  return `<div class="cx-multi-row" data-cx-aff-row>
    <label class="cx-main" title="The main one"><input type="radio" name="aff-main"${
      main ? " checked" : ""}> main</label>
    <input class="cx-aff-org" list="cx-org-list" autocomplete="off" aria-label="Organisation"
      value="${escapeHtml((aff || {}).org || "")}" placeholder="Organisation">
    <input class="cx-aff-role" autocomplete="off" aria-label="Role there"
      value="${escapeHtml((aff || {}).role || "")}" placeholder="Role there">
    <button type="button" class="small secondary cx-x" data-cx-row-remove
      aria-label="Remove" title="Remove">×</button></div>`;
}

/* THE FORM, after Edit: every detail, the relationships and organisations
   as lists - add one, take one off, choose the main one. */
function cxEditForm(person, mark) {
  const jobs = cxListOf(person, "profession", "professions");
  const places = cxListOf(person, "location", "locations");
  const rels = person.relationships && person.relationships.length ? person.relationships
    : (person.relationship ? [person.relationship] : []);
  const affs = (person.affiliations && person.affiliations.length) ? person.affiliations
    : (person.org || person.role ? [{ org: person.org || "", role: person.role || "" }] : []);
  return `<form id="cx-edit" class="cx-edit">
      <div class="grid">
        <label><span>Name${mark("name")}</span><input name="name" required value="${
          escapeHtml(person.name)}"></label>
        <label><span>Closeness${mark("closeness")}</span><select name="closeness">${
          cxClosenessOptions(person.closeness || 0)}</select></label>
        <div class="wide cx-multi" data-cx-multi="job">
          <span>Jobs / professions - the main one marked${mark("profession")}</span>
          <div data-cx-rows>${(jobs.length ? jobs : [""]).map((v, i) => cxTextRow("job", v, i === 0))
            .join("")}</div>
          <button type="button" class="small secondary" data-cx-row-add="job">+ Another
            job</button>
        </div>
        <div class="wide cx-multi" data-cx-multi="place">
          <span>Locations - the main one marked${mark("location")}</span>
          <div data-cx-rows>${(places.length ? places : [""]).map((v, i) => cxTextRow("place", v, i === 0))
            .join("")}</div>
          <button type="button" class="small secondary" data-cx-row-add="place">+ Another
            place</button>
        </div>
        <div class="wide cx-multi" data-cx-multi="rel"${person.is_self ? " hidden" : ""}>
          <span>Relationships - the main one marked${mark("relationship")}</span>
          <div data-cx-rows>${(rels.length ? rels : [""]).map((r, i) => cxRelRow(r, i === 0))
            .join("")}</div>
          <button type="button" class="small secondary" data-cx-row-add="rel">+ Another
            relationship</button>
        </div>
        <div class="wide cx-multi" data-cx-multi="aff">
          <span>Organisations, each with the role there - the main one marked${mark("org")}</span>
          <div data-cx-rows>${(affs.length ? affs : [{}]).map((a, i) => cxAffRow(a, i === 0))
            .join("")}</div>
          <button type="button" class="small secondary" data-cx-row-add="aff">+ Another
            organisation</button>
        </div>
        <label class="wide"><span>Also known as (comma separated)${mark("aliases")}</span><input
          name="aliases" value="${escapeHtml((person.aliases || []).join(", "))}"></label>
        <label class="wide"><span>Tags (comma separated)${mark("tags")}</span><input name="tags" value="${
          escapeHtml((person.tags || []).join(", "))}"></label>
        <label class="wide"><span>Summary${mark("summary")}</span><textarea name="summary" rows="3">${
          escapeHtml(person.summary || "")}</textarea></label>
        <label class="wide">Reason (optional)<input name="reason"
          placeholder="Why you changed this - the agent learns from it"></label>
      </div>
      <div class="ov-lp-buttons">
        <button type="submit">Save</button>
        <button type="button" class="secondary" data-cx-edit-cancel>Cancel</button>
      </div>
    </form>`;
}

/* The relationships and organisations in the form, the main one first. */
function cxFormLists(form) {
  const ordered = (rows) => {
    const main = rows.findIndex((row) => row.querySelector('input[type="radio"]').checked);
    return main > 0 ? [rows[main], ...rows.filter((_r, i) => i !== main)] : rows;
  };
  const rels = ordered([...form.querySelectorAll("[data-cx-rel-row]")])
    .map((row) => row.querySelector(".cx-rel").value.trim().toLowerCase()).filter(Boolean);
  const affs = ordered([...form.querySelectorAll("[data-cx-aff-row]")])
    .map((row) => ({ org: row.querySelector(".cx-aff-org").value.trim(),
                     role: row.querySelector(".cx-aff-role").value.trim() }))
    .filter((a) => a.org || a.role);
  const texts = (kind) => [...new Set(ordered([...form.querySelectorAll(
    `[data-cx-text-row="${kind}"]`)]).map((row) => row.querySelector(".cx-text").value.trim())
    .filter(Boolean))];
  return { rels: [...new Set(rels)], affs, jobs: texts("job"), places: texts("place") };
}

/* An edit sends only what the user changed, so only that is marked as
   theirs and kept as a lesson. */
function cxEdits(form, person) {
  const value = (name) => form.elements[name].value.trim();
  const changed = {};
  ["name", "summary"].forEach((field) => {
    if (value(field) !== String(person[field] || "").trim()) changed[field] = value(field);
  });
  const lists = cxFormLists(form);
  // Jobs and places, each a list with its main one first.
  if (JSON.stringify(lists.jobs)
      !== JSON.stringify(cxListOf(person, "profession", "professions"))) {
    changed.professions = lists.jobs;
  }
  if (JSON.stringify(lists.places)
      !== JSON.stringify(cxListOf(person, "location", "locations"))) {
    changed.locations = lists.places;
  }
  const rels = person.relationships && person.relationships.length ? person.relationships
    : (person.relationship ? [person.relationship] : []);
  // Who you are to yourself is fixed: "myself".
  if (!person.is_self && JSON.stringify(lists.rels) !== JSON.stringify(rels)) {
    changed.relationships = lists.rels;
  }
  const affs = ((person.affiliations && person.affiliations.length) ? person.affiliations
    : (person.org || person.role ? [{ org: person.org || "", role: person.role || "" }] : []))
    .map((a) => ({ org: a.org || "", role: a.role || "" }));
  if (JSON.stringify(lists.affs) !== JSON.stringify(affs)) changed.affiliations = lists.affs;
  if (Number(value("closeness")) !== (Number(person.closeness) || 0)) {
    changed.closeness = Number(value("closeness"));
  }
  ["tags", "aliases"].forEach((field) => {
    const now = cxTags(value(field));
    if (now.join("\n") !== (person[field] || []).join("\n")) changed[field] = now;
  });
  return changed;
}

/* One change to a person, then the tab read again. */
/* WHAT A MERGE WOULD BRING OVER, shown when the other person is chosen and
   before "Yes, merge" can be pressed: their accounts, their activity, their
   names (other names of this one now), their tags, and what fills this
   one's empty fields. Nothing is merged until it is confirmed. */
async function cxMergePreview() {
  const box = $("#cx-merge-preview");
  const yes = $("[data-cx-merge-yes]");
  const other = $("#cx-merge-other").value;
  if (!box || !cx.person) return;
  if (yes) yes.disabled = true;
  if (!other) { box.innerHTML = ""; return; }
  box.innerHTML = `<p class="muted">Reading what would come over…</p>`;
  let said;
  try {
    said = await api.get(`/api/connections/merge_preview?id=${encodeURIComponent(
      cx.person.id)}&other=${encodeURIComponent(other)}`);
  } catch (err) {
    box.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
    return;
  }
  if ($("#cx-merge-other").value !== other) return;      // chosen again meanwhile
  const list = (items) => items.length
    ? `<ul class="cx-list-plain">${items.join("")}</ul>` : `<p class="muted">none</p>`;
  const accounts = (said.accounts || []).map((a) => `<li><strong>${escapeHtml(
    a.platform || "account")}</strong> ${escapeHtml(a.handle || "")} ${
    a.url ? cxLink(a.url, a.url) : ""}</li>`);
  const activity = (said.activity || []).map((a) => `<li><span class="muted">${
    a.at ? escapeHtml(cxWhen(a.at)) : "date unknown"}</span> ${escapeHtml(a.what)}</li>`);
  const filled = Object.entries(said.filled || {}).map(([k, v]) =>
    `<li>${escapeHtml(k)}: <strong>${escapeHtml(String(v))}</strong></li>`);
  const count = Number(said.activity_count) || 0;
  box.innerHTML = `<p><strong>${escapeHtml(said.other.name)}</strong> would be merged into
      <strong>${escapeHtml(said.keep.name)}</strong> and no longer listed. This comes over:</p>
    <div class="cx-merge-grid">
      <div><h5>Accounts (${accounts.length})</h5>${list(accounts)}</div>
      <div><h5>Activity (${count})</h5>${list(activity)}${count > activity.length
        ? `<p class="muted">and ${count - activity.length} more</p>` : ""}</div>
      <div><h5>Other names</h5>${list((said.names || []).map((n) => `<li>${escapeHtml(n)}</li>`))}</div>
      <div><h5>Tags added</h5>${list((said.tags || []).map((t) => `<li>${escapeHtml(t)}</li>`))}</div>
      <div><h5>Relationships added</h5>${list((said.relationships || []).map((r) =>
        `<li>${escapeHtml(r)}</li>`))}</div>
      <div><h5>Organisations added</h5>${list((said.affiliations || []).map((a) =>
        `<li>${escapeHtml([a.role, a.org].filter(Boolean).join(" at "))}</li>`))}</div>
      <div><h5>Filled in where ${escapeHtml(said.keep.name)} has nothing</h5>${list(filled)}</div>
    </div>`;
  if (yes) yes.disabled = false;
}

document.addEventListener("change", (event) => {
  if (event.target && event.target.id === "cx-merge-other") cxMergePreview();
});

async function cxChange(body, done) {
  try {
    const person = await api.post("/api/connections/person", body);
    toast(done);
    return person;
  } catch (err) {
    toast(err.message, "error");
    return null;
  } finally {
    await loadConnections();
  }
}

$("#cx-search").addEventListener("input", renderCxList);
$("#cx-group").addEventListener("change", renderCxList);
$("#cx-add-open").addEventListener("click", () => {
  $("#cx-add").hidden = false;
  renderCxAddForm();
  $("#cx-add-name").focus();
});
$("#cx-add-cancel").addEventListener("click", () => {
  $("#cx-add").reset();
  $("#cx-add").hidden = true;
});
$("#cx-add-link-more").addEventListener("click", () => {
  const row = $("#cx-add-links .cx-link-row").cloneNode(true);
  row.querySelectorAll("input").forEach((one) => { one.value = ""; });
  $("#cx-add-links").appendChild(row);
  row.querySelector(".cx-add-link").focus();
});

$("#cx-add").addEventListener("submit", async (event) => {
  event.preventDefault();
  const name = $("#cx-add-name").value.trim();
  if (!name) { toast("A name is needed", "error"); return; }
  const body = { action: "add", name };
  const relationship = $("#cx-add-relationship").value;
  const closeness = Number($("#cx-add-closeness").value) || 0;
  if (relationship) body.relationship = relationship;
  if (closeness) body.closeness = closeness;
  ["org", "role", "profession"].forEach((field) => {
    const said = $(`#cx-add-${field}`).value.trim();
    if (said) body[field] = said;
  });
  const tags = cxTags($("#cx-add-tags").value);
  if (tags.length) body.tags = tags;
  const reason = $("#cx-add-reason").value.trim();
  if (reason) body.reason = reason;
  const profiles = $$("#cx-add-links .cx-link-row").map((row) => ({
    url: row.querySelector(".cx-add-link").value.trim(),
    label: row.querySelector(".cx-add-label").value.trim() })).filter((one) => one.url);
  if (profiles.length) body.profiles = profiles;
  try {
    const person = await api.post("/api/connections/person", body);
    toast(`${name} added`);
    $("#cx-add").reset();
    $$("#cx-add-links .cx-link-row").slice(1).forEach((one) => one.remove());
    $("#cx-add").hidden = true;
    if (person && person.id) cx.open = person.id;
  } catch (err) {
    toast(err.message, "error");
    return;
  }
  await loadConnections();
});

/* The list, the person and the in-page asks answer clicks from one place. */
$("#connections").addEventListener("click", async (event) => {
  const row = event.target.closest("[data-cx-person]");
  if (row) { openCxPerson(row.dataset.cxPerson); return; }
  const ask = event.target.closest("[data-cx-ask]");
  if (ask) {
    $("#cx-delete-ask").hidden = ask.dataset.cxAsk !== "delete";
    $("#cx-merge-ask").hidden = ask.dataset.cxAsk !== "merge";
    return;
  }
  if (event.target.closest("[data-cx-ask-no]")) {
    event.target.closest(".cx-sure").hidden = true;
    return;
  }
  const person = cx.person;
  // Edit: the details become the form; Cancel: shown again, as they were.
  if (event.target.closest("[data-cx-edit-open]") && person) {
    cx.editing = person.id;
    renderCxPerson(person);
    const first = $("#cx-edit input[name=name]");
    if (first) first.focus();
    return;
  }
  if (event.target.closest("[data-cx-edit-cancel]") && person) {
    cx.editing = null;
    renderCxPerson(person);
    return;
  }
  const rowAdd = event.target.closest("[data-cx-row-add]");
  if (rowAdd) {
    const rows = rowAdd.closest("[data-cx-multi]").querySelector("[data-cx-rows]");
    const first = !rows.children.length;
    const kind = rowAdd.dataset.cxRowAdd;
    rows.insertAdjacentHTML("beforeend", kind === "rel" ? cxRelRow("", first)
      : kind === "aff" ? cxAffRow({}, first) : cxTextRow(kind, "", first));
    rows.lastElementChild.querySelector('input:not([type="radio"])').focus();
    return;
  }
  const rowRemove = event.target.closest("[data-cx-row-remove]");
  if (rowRemove) {
    const rows = rowRemove.closest("[data-cx-rows]");
    const wasMain = rowRemove.closest(".cx-multi-row").querySelector('input[type="radio"]').checked;
    rowRemove.closest(".cx-multi-row").remove();
    // The main one taken off: the next is the main one.
    if (wasMain && rows.firstElementChild) {
      rows.firstElementChild.querySelector('input[type="radio"]').checked = true;
    }
    return;
  }
  if (event.target.closest("[data-cx-delete-yes]") && person) {
    event.target.disabled = true;
    // Let go of them first, so the tab read again does not open them again.
    cx.open = null;
    const done = await cxChange({ action: "delete", id: person.id,
      reason: $("#cx-delete-reason").value.trim() }, `${person.name} deleted`);
    if (done) {
      cx.person = null;
      $("#cx-person").innerHTML = `<p class="muted">${escapeHtml(person.name)} was
        deleted. They can be added back from "Your changes".</p>`;
    } else {
      await openCxPerson(person.id);
    }
    return;
  }
  const getPicture = event.target.closest("[data-cx-avatar-get]");
  if (getPicture && person) {
    getPicture.disabled = true;
    await cxGetPicture(person.id);
    getPicture.disabled = false;
    return;
  }
  const moveAsk = event.target.closest("[data-cx-move-ask]");
  if (moveAsk) {
    const box = $(`[data-cx-move-box="${CSS.escape(moveAsk.dataset.cxMoveAsk)}"]`);
    if (box) box.hidden = !box.hidden;
    return;
  }
  const moveYes = event.target.closest("[data-cx-move-yes]");
  if (moveYes && person) {
    const box = moveYes.closest("[data-cx-move-box]");
    const to = box.querySelector("[data-cx-move-to]").value;
    if (!to) { toast("Choose the person it belongs to."); return; }
    moveYes.disabled = true;
    const name = (((cx.data && cx.data.people) || []).find((p) => p.id === to) || {}).name;
    await cxChange({ action: "move_account", id: to, account: moveYes.dataset.cxMoveYes,
      reason: box.querySelector("[data-cx-move-reason]").value.trim() },
    `Account moved to ${name || "them"}`);
    await openCxPerson(person.id);
    return;
  }
  if (event.target.closest("[data-cx-merge-yes]") && person) {
    const other = $("#cx-merge-other").value;
    if (!other) return;
    event.target.disabled = true;
    await cxChange({ action: "merge", id: person.id, other,
      reason: $("#cx-merge-reason").value.trim() }, `Merged into ${person.name}`);
    return;
  }
  // Restoring someone deleted asks first, with a reason, in their row.
  const restore = event.target.closest("[data-cx-restore]");
  if (restore) {
    restore.closest("li").querySelector(".cx-sure").hidden = false;
    return;
  }
  const restoreYes = event.target.closest("[data-cx-restore-yes]");
  if (restoreYes) {
    const item = restoreYes.closest("li");
    restoreYes.disabled = true;
    await cxChange({ action: "restore", id: restoreYes.dataset.cxRestoreYes,
      reason: item.querySelector("input").value.trim() }, "Added back");
    return;
  }
  const profileRemove = event.target.closest("[data-cx-profile-remove]");
  if (profileRemove) {
    profileRemove.closest("li").querySelector("[data-cx-profile-box]").hidden = false;
    return;
  }
  const profileYes = event.target.closest("[data-cx-profile-remove-yes]");
  if (profileYes && cx.person) {
    profileYes.disabled = true;
    const box = profileYes.closest("[data-cx-profile-box]");
    await cxChange({ action: "remove_profile", id: cx.person.id,
      account: profileYes.dataset.cxProfileRemoveYes,
      reason: box.querySelector("[data-cx-profile-reason]").value.trim() }, "Profile taken off");
  }
});

$("#connections").addEventListener("submit", async (event) => {
  if (event.target.matches("[data-cx-profile-add]")) {
    event.preventDefault();
    const url = event.target.querySelector('input[type="url"]').value.trim();
    const label = event.target.elements.label.value.trim();
    if (!url || !cx.person) return;
    await cxChange({ action: "add_profile", id: cx.person.id, url,
                     ...(label ? { label } : {}) }, "Profile added");
    return;
  }
  if (event.target.id !== "cx-edit") return;
  event.preventDefault();
  const person = cx.person;
  if (!person) return;
  const changed = cxEdits(event.target, person);
  if (!Object.keys(changed).length) { toast("Nothing has changed"); return; }
  if (changed.name === "") { toast("A name is needed", "error"); return; }
  const reason = event.target.elements.reason.value.trim();
  try {
    await api.post("/api/connections/person", { action: "edit", id: person.id, ...changed,
      ...(reason ? { reason } : {}) });
  } catch (err) {
    toast(err.message, "error");
    return;
  }
  cx.editing = null;
  toast(`${changed.name || person.name} saved`);
  await loadConnections();
});

/* THE INBOX: what the user is asked to check - changes to their own profile
   details found on a public page, each accepted (made) or dismissed (not
   asked again), with an optional reason. */
function renderCxInbox() {
  const open = (cx.data && cx.data.inbox) || [];
  const decided = (cx.data && cx.data.inbox_decided) || [];
  $("#cx-inbox-count").textContent = open.length ? String(open.length) : "";
  const sources = (item) => (item.sources || []).map((url) => cxLink(url, url)).join(" · ");
  const items = open.map((item) => `<li class="cx-inbox-item" data-cx-inbox="${
      escapeHtml(item.id)}">
      <div><strong>${escapeHtml(item.title)}</strong></div>
      ${item.detail ? `<div>${escapeHtml(item.detail)}</div>` : ""}
      <div class="muted">${sources(item) ? `${sources(item)} · ` : ""}${
        escapeHtml(cxTimes(item.found_at, "", ""))}${item.found_at ? " · " : ""}asked ${
        escapeHtml(cxWhen(item.created_at, false))}</div>
      <div class="cx-inbox-do">
        <input placeholder="Reason (optional)" aria-label="Reason">
        <button type="button" class="small" data-cx-inbox-accept>Accept</button>
        <button type="button" class="small secondary" data-cx-inbox-dismiss>Dismiss</button>
      </div></li>`).join("");
  const done = decided.map((item) => `<li><span class="muted">${
      escapeHtml(cxWhen(item.decided_at, false))}</span>
      <span class="badge">${escapeHtml(item.status)}</span> ${escapeHtml(item.title)}${
      item.reason ? ` <span class="cx-reason">- ${escapeHtml(item.reason)}</span>` : ""}</li>`)
    .join("");
  $("#cx-inbox").innerHTML = `
    ${items ? `<ul class="cx-list-plain">${items}</ul>`
      : `<p class="muted">Nothing to check.</p>`}
    ${done ? `<details class="cx-summary"><summary>Decided (${decided.length})</summary>
      <ul class="cx-list-plain">${done}</ul></details>` : ""}`;
}

$("#cx-inbox").addEventListener("click", async (event) => {
  const button = event.target.closest("[data-cx-inbox-accept], [data-cx-inbox-dismiss]");
  if (!button) return;
  const item = button.closest("[data-cx-inbox]");
  const accept = button.hasAttribute("data-cx-inbox-accept");
  item.querySelectorAll("button").forEach((one) => { one.disabled = true; });
  try {
    await api.post("/api/connections/inbox", { id: item.dataset.cxInbox, accept,
      reason: item.querySelector("input").value.trim() });
    toast(accept ? "Accepted - your profile is changed" : "Dismissed - it is not asked again");
  } catch (err) {
    toast(err.message, "error");
  }
  await loadConnections();
});

/* YOU, beside People: your picture, which opens your own profile on the
   right - shown as anyone's is. */
function renderCxMe() {
  const me = (cx.data && cx.data.me) || null;
  const button = $("#cx-me-open");
  button.hidden = !me;
  if (!me) return;
  button.innerHTML = cxAvatar(me);
  button.classList.toggle("selected", cx.open === me.id);
  button.title = `Your own profile - ${me.name || "you"}`;
}

/* What the label and organisation boxes suggest as one types. */
function renderCxSuggestions() {
  const fill = (id, names) => {
    $(id).innerHTML = (names || []).map((name) =>
      `<option value="${escapeHtml(name)}"></option>`).join("");
  };
  fill("#cx-label-list", cx.data && cx.data.labels);
  fill("#cx-org-list", cx.data && cx.data.orgs);
  fill("#cx-rel-list", cxRelationships());
}

$("#cx-me-open").addEventListener("click", () => {
  const me = cx.data && cx.data.me;
  if (me) openCxPerson(me.id).then(renderCxMe);
});

$("#connections").addEventListener("click", async (event) => {
  const run = event.target.closest("[data-cx-me-run]");
  if (!run) return;
  run.disabled = true;
  try {
    const said = await api.post("/api/connections/run", { me: true });
    toast(said.started ? "Looking you up - with the rest of the round"
      : "A round is going already");
  } catch (err) {
    toast(err.message, "error");
  } finally {
    run.disabled = false;
  }
});

/* ------------------------------------------ what you need to know (Overview)

   The briefing the connections round worked out: what is new with the
   people around the user and why it matters now. While a working-out runs
   the card asks again every second and a half, with a bar, and stops when
   it stops. */
//: `issue`: the id of the issue being read - "" for the newest, which is
//: then what a refresh shows.
const knowCard = { timer: null, wasRunning: false, issue: "", page: "", data: null };

/* The card's answer: the newest issue - or the one being read. */
function knowAsk() {
  return api.get(`/api/connections/briefing${knowCard.issue
    ? `?id=${encodeURIComponent(knowCard.issue)}` : ""}`);
}

function renderKnowCard(data) {
  if (!data) {
    $("#ov-know").innerHTML = `<p class="muted">Your connections could not be read.</p>`;
    return;
  }
  const progress = data.progress || {};
  const running = Boolean(progress.running);
  const briefing = data.briefing;
  $("#ov-know-run").disabled = running;
  $("#ov-know-progress").innerHTML = running ? cxProgressHtml(progress)
    : (progress.error ? `<p class="muted">The last working-out failed: ${
        escapeHtml(progress.error)}</p>` : "");
  // When the next issue is made, in which time zone - and the times of
  // day, set here, on the paper's own tab.
  const schedule = data.schedule || {};
  knowCard.schedule = schedule;
  // Not drawn again under a time being set: what is typed would go.
  if (!$("#rec-times")?.contains(document.activeElement)) renderRecTimes();
  $("#ov-know-when").textContent = schedule.next
    ? `Next issue ${knowIssueTime(schedule.next)}`
    : schedule.times && !schedule.times.length
      ? "No daily issue: made when you press Make an issue now" : "";
  knowCard.data = data;
  renderKnowPaper();
  clearTimeout(knowCard.timer);
  if (running) {
    knowCard.wasRunning = true;
    knowCard.timer = setTimeout(followKnowCard, 1500);
  } else if (knowCard.wasRunning) {
    // Just finished: the tab's own lists may have moved with it.
    knowCard.wasRunning = false;
    if (activeTab === "connections") loadConnections();
  }
}

/* THE FRONT PAGE: a masthead and its dateline - when it was worked out,
   with the time zone; the most important story leading, with its picture
   and why it matters; the stories of importance 1-2 "In brief" beside it;
   the rest in columns below. */
function knowIssueTime(value) {
  const at = value ? new Date(value) : null;
  return at && !Number.isNaN(at.getTime()) ? at.toLocaleString(undefined, {
    weekday: "long", day: "numeric", month: "long", year: "numeric", hour: "numeric",
    minute: "2-digit", timeZoneName: "short" }) : "";
}

/* The paper drawn from what was last read: the pages and issues down the
   left, the page chosen on the right. */
function renderKnowPaper() {
  const data = knowCard.data || {};
  const side = $("#rec-pages");
  if (side) side.innerHTML = knowSide(data.briefing, data.issues || []);
  $("#ov-know").innerHTML = knowFrontPage(data.briefing, []);
}

/* WHEN AN ISSUE IS MADE: the times of day, in this computer's time zone -
   shown until Edit, as a settings card is; Save sends them. */
/* THE TIMES OF DAY, changed where they stand - no Edit: a time added with
   "Add a time", taken off with its ×, each change kept at once (a time
   being typed, once the typing stops). */
function renderRecTimes() {
  const host = $("#rec-times");
  if (!host) return;
  const schedule = knowCard.schedule || {};
  const times = (schedule.times || []).join(", ");
  host.innerHTML = `<label class="checkbox"><input type="checkbox" id="rec-auto-on"${
    schedule.on ? " checked" : ""}> Make an issue by itself</label> <strong>each day at</strong>`;
  host.querySelector("#rec-auto-on").addEventListener("change", async (event) => {
    const on = event.target.checked;
    try {
      await api.post("/api/settings", { values: { recommend_auto_on: on } });
      knowCard.schedule = Object.assign({}, knowCard.schedule, { on });
      toast(on ? ((knowCard.schedule.times || []).length
        ? "An issue by itself at the times set" : "On: add a time for an issue by itself")
        : "No issue by itself - one is made when you press Make an issue now");
    } catch (err) {
      event.target.checked = !on;
      toast(err.message, "error");
    }
  });
  const control = recommendTimesControl(times);
  let waiting = null;
  control.addEventListener("change", () => {
    clearTimeout(waiting);
    waiting = setTimeout(() => saveRecTimes(control.value), 600);
  });
  host.appendChild(control);
  if (schedule.time_zone) {
    host.insertAdjacentHTML("beforeend",
      `<span class="muted">(${escapeHtml(schedule.time_zone)})</span>`);
  }
}

async function saveRecTimes(value) {
  if (value === (knowCard.schedule?.times || []).join(", ")) return;
  try {
    await api.post("/api/settings", { values: { recommend_times: value } });
    knowCard.schedule = Object.assign({}, knowCard.schedule,
      { times: value.split(", ").filter(Boolean) });
    toast(value ? "Saved: an issue each day at " + value
      : "Saved: no daily issue - one is made when you press Make an issue now");
  } catch (err) {
    toast(err.message, "error");
  }
}

/* DOWN THE LEFT: every issue kept (the newest hundred), and this issue's
   pages - the front page, then a page per topic, each with its stories. */
function knowSide(briefing, issues) {
  const paper = ((briefing && briefing.stats) || {}).paper || {};
  const pages = paper.pages || [];
  const current = knowCard.page || "";
  const picker = issues.length ? `<label class="rec-issue">Issue
      <select data-know-issue aria-label="Issue">${issues.map((one) =>
        `<option value="${escapeHtml(one.id)}"${briefing && one.id === briefing.id
          ? " selected" : ""}>${one.issue ? `No. ${one.issue}, ` : ""}${escapeHtml(
          knowIssueTime(one.at))}</option>`).join("")}</select></label>` : "";
  const list = briefing && (paper.front || pages.length) ? [
    { key: "", title: "Front page", count: (paper.front || []).length + (paper.brief || []).length },
    ...pages.map((one) => ({ key: one.key, title: one.title, count: (one.stories || []).length })),
  ] : [];
  const kept = ((knowCard.data || {}).collection || []).length;
  // THE COLLECTION FIRST: what the user kept, above any one issue - it is
  // theirs across issues, and below a long list of pages it went unseen.
  const collection = `<h3 class="rec-side-head">Collection</h3>
    <button type="button" class="rec-page rec-collection${current === "collection"
      ? " selected" : ""}" data-know-page="collection">Stories you kept<span class="muted">${
      kept === 1 ? "1 story" : `${kept} stories`}</span></button>`;
  return `${collection}${picker}${list.length ? `<h3 class="rec-side-head">Pages</h3>${list.map((one, n) =>
    `<button type="button" class="rec-page${current === one.key ? " selected" : ""}"
      data-know-page="${escapeHtml(one.key)}"><span class="paper-page-no">${
      String.fromCharCode(65 + n)}1</span> ${escapeHtml(one.title)}<span class="muted">${
      Number(one.count) || 0} stor${Number(one.count) === 1 ? "y" : "ies"}</span></button>`)
    .join("")}` : ""}`;
}

/* Whether a story is in the collection - of this issue, or kept from any. */
function knowKept(storyId) {
  const data = knowCard.data || {};
  return (data.collected || []).includes(storyId)
    || (data.collection || []).some((one) => one.story_id === storyId);
}

/* THE COLLECTION: the stories the user kept, the newest first, each as it
   was printed and with where it came from - kept until taken out, as a
   to-do is. Each can still be said "more like this", "not interested" or
   "already knew", as in its issue. */
function knowCollection(data) {
  const items = data.collection || [];
  const mast = `<header class="paper-mast">
      <h2 class="paper-title">Collection</h2>
      <div class="paper-dateline"><span>Stories you kept, the newest first</span></div>
    </header>`;
  if (!items.length) {
    return `<article class="paper">${mast}<p class="paper-empty">Nothing kept yet. "Add to
      collection" under a story keeps it here.</p></article>`;
  }
  return `<article class="paper">${mast}<div class="paper-stories paper-collection">${
    items.map((one) => {
      const story = one.story || {};
      const from = story.issue_no
        ? `From No. ${story.issue_no}, ${knowIssueTime(story.issue_at)}`
        : story.issue_at ? `From the issue of ${knowIssueTime(story.issue_at)}` : "";
      return `<div class="paper-kept">${from
        ? `<p class="paper-kept-from muted">${escapeHtml(from)}</p>` : ""}${
        knowStory(story, "story", one.issue_id)}</div>`;
    }).join("")}</div></article>`;
}

function knowFrontPage(briefing, issues = []) {
  if (knowCard.page === "collection") return knowCollection(knowCard.data || {});
  const items = (briefing && briefing.items) || [];
  const paper = ((briefing && briefing.stats) || {}).paper;
  // AN ISSUE OF CUSTOMIZED RECOMMENDATION: pages, one per topic.
  if (paper && (paper.pages || paper.front)) return knowPaper(briefing, issues, paper);
  const when = briefing ? knowIssueTime(briefing.at) : "";
  const number = briefing && briefing.issue ? `No. ${briefing.issue}, ` : "";
  // EVERY ISSUE KEPT - the newest hundred - each by its number and time.
  const picker = issues.length > 1 ? `<label class="paper-issues">Issue
      <select data-know-issue aria-label="Issue">${issues.map((one) =>
        `<option value="${escapeHtml(one.id)}"${briefing && one.id === briefing.id
          ? " selected" : ""}>${one.issue ? `No. ${one.issue}, ` : ""}${escapeHtml(
          knowIssueTime(one.at))}</option>`).join("")}</select></label>` : "";
  // An issue from before Newspaper keeps its own name.
  const mast = `<header class="paper-mast">
      <h2 class="paper-title">${briefing ? "What you need to know"
        : "Newspaper"}</h2>
      <div class="paper-dateline"><span>${escapeHtml(number)}${escapeHtml(when
        ? `worked out ${when}` : "")}</span>
        ${picker || `<span>From your current tasks, your contacts and the public web</span>`}</div>
    </header>`;
  if (!briefing) {
    return `<article class="paper">${mast}<p class="paper-empty">No issue yet: one is
      made at the times set in Settings, or now with "Make an issue now".</p></article>`;
  }
  if (!items.length) {
    return `<article class="paper">${mast}<p class="paper-empty">Nothing your tasks need
      to know right now.</p></article>`;
  }
  const [lead, ...rest] = items;
  const brief = rest.filter((one) => (Number(one.importance) || 1) <= 2);
  const stories = rest.filter((one) => (Number(one.importance) || 1) > 2);
  return `<article class="paper">${mast}
    <div class="paper-front${brief.length ? "" : " paper-front-whole"}">
      ${knowStory(lead, "lead")}
      ${brief.length ? `<aside class="paper-brief"><h3 class="paper-brief-head">In brief</h3>
        ${brief.map((one) => knowStory(one, "brief")).join("")}</aside>` : ""}
    </div>
    ${stories.length ? `<div class="paper-stories">${stories.map((one) =>
      knowStory(one, "story")).join("")}</div>` : ""}
  </article>`;
}

/* CUSTOMIZED RECOMMENDATION: a newspaper of several pages - the front page
   (the best of all, and "In brief"), then a page per topic, the web's and
   the contacts' stories together - turned by the row of pages at its top. */
function knowPaper(briefing, issues, paper) {
  const items = briefing.items || [];
  const byId = Object.fromEntries(items.map((one) => [one.id, one]));
  const pages = paper.pages || [];
  const page = pages.find((one) => one.key === knowCard.page) || null;
  const picker = issues.length > 1 ? `<label class="paper-issues">Issue
      <select data-know-issue aria-label="Issue">${issues.map((one) =>
        `<option value="${escapeHtml(one.id)}"${one.id === briefing.id
          ? " selected" : ""}>${one.issue ? `No. ${one.issue}, ` : ""}${escapeHtml(
          knowIssueTime(one.at))}</option>`).join("")}</select></label>` : "";
  const mast = `<header class="paper-mast">
      <h2 class="paper-title">Newspaper</h2>
      <div class="paper-dateline"><span>${briefing.issue ? `No. ${briefing.issue}, ` : ""}${
        escapeHtml(knowIssueTime(briefing.at))}</span>
        ${picker || `<span>From what you read, your tasks, your contacts and the public web</span>`}</div>
    </header>`;
  const pick = (ids) => (ids || []).map((id) => byId[id]).filter(Boolean);
  if (!items.length) {
    return `<article class="paper">${mast}<p class="paper-empty">Nothing new worth your
      time in this issue.</p></article>`;
  }
  if (page) {
    const [lead, ...rest] = pick(page.stories);
    return `<article class="paper">${mast}
      <h3 class="paper-section">${escapeHtml(page.title)}</h3>
      ${lead ? `<div class="paper-front paper-front-whole">${knowStory(lead, "lead", briefing.id)}</div>` : ""}
      ${rest.length ? `<div class="paper-stories">${rest.map((one) =>
        knowStory(one, "story", briefing.id)).join("")}</div>` : ""}
    </article>`;
  }
  const [lead, ...front] = pick(paper.front);
  const brief = pick(paper.brief);
  return `<article class="paper">${mast}
    <div class="paper-front${brief.length ? "" : " paper-front-whole"}">
      ${lead ? knowStory(lead, "lead", briefing.id) : ""}
      ${brief.length ? `<aside class="paper-brief"><h3 class="paper-brief-head">In brief</h3>
        ${brief.map((one) => knowStory(one, "brief", briefing.id)).join("")}</aside>` : ""}
    </div>
    ${front.length ? `<div class="paper-stories">${front.map((one) =>
      knowStory(one, "story", briefing.id)).join("")}</div>` : ""}
  </article>`;
}

/* The user's say on a story - and that they opened it. */
async function knowSay(issue, story, action) {
  try {
    await api.post("/api/recommend/feedback", { issue, story, action });
  } catch (err) {
    if (action !== "opened") toast(err.message, "error");
  }
}

document.addEventListener("click", async (event) => {
  const turn = event.target.closest?.("[data-know-page]");
  if (turn) {
    knowCard.page = turn.dataset.knowPage;
    if (knowCard.data) renderKnowPaper();
    return;
  }
  const keep = event.target.closest?.("[data-know-keep]");
  if (keep) {
    const story = keep.dataset.knowKeep;
    const wanted = !knowKept(story);
    keep.disabled = true;
    try {
      await api.post("/api/recommend/collection",
        { issue: keep.dataset.issue, story, keep: wanted });
      renderKnowCard(await knowAsk());
      toast(wanted ? "Kept in your collection" : "Taken out of your collection");
    } catch (err) {
      keep.disabled = false;
      toast(err.message, "error");
    }
    return;
  }
  const say = event.target.closest?.("[data-know-say]");
  if (say) {
    const was = ((knowCard.data || {}).says || {})[say.dataset.story];
    if (was === say.dataset.knowSay) return;      // said already: counted once
    say.closest(".paper-say")?.querySelectorAll("button").forEach((b) => { b.disabled = true; });
    await knowSay(say.dataset.issue, say.dataset.story, say.dataset.knowSay);
    // KEPT AND SHOWN: the story carries what was said, whatever is drawn
    // next; a change takes the one before back (recommend.record_feedback).
    if (knowCard.data) {
      knowCard.data.says = Object.assign({}, knowCard.data.says || {},
        { [say.dataset.story]: say.dataset.knowSay });
      renderKnowPaper();
    }
    toast({ more: "More like this, next time", less: "Less of this, next time",
      knew: "Kept as something you know: more on this topic, less like this story" }[
      say.dataset.knowSay] || "Noted");
    return;
  }
  const opened = event.target.closest?.("a[data-know-open]");
  if (opened) knowSay(opened.dataset.issue, opened.dataset.knowOpen, "opened");
});

function knowPicture(item, place) {
  const image = item.image || {};
  const src = image.person ? `/api/connections/avatar?id=${encodeURIComponent(image.person)}`
    : image.kept ? `/api/connections/briefing/picture?name=${encodeURIComponent(image.kept)}`
    : "";
  if (!src) return "";
  const caption = image.person ? (item.names || [])[0] || "" : knowSource(item);
  return `<figure class="paper-picture paper-picture-${place}${image.person
    ? " paper-portrait" : ""}"><img src="${escapeHtml(src)}" alt="" loading="lazy">${
    caption ? `<figcaption>${escapeHtml(caption)}</figcaption>` : ""}</figure>`;
}

function knowSource(item) {
  const first = (item.sources || []).find((one) => /^https?:\/\//.test(String(one)));
  if (!first) return "";
  try { return new URL(first).hostname.replace(/^www\./, ""); } catch (err) { return ""; }
}

function knowStory(item, place, issue = "") {
  const names = (item.names || []).filter(Boolean);
  const sources = (item.sources || []).filter((one) => /^https?:\/\//.test(String(one)));
  const urgent = Number(item.importance) >= 5;
  const byline = [names.length ? names.join(", ") : "", knowSource(item)].filter(Boolean);
  const heading = place === "lead" ? "h3" : "h4";
  return `<section class="paper-${place}${urgent ? " paper-urgent" : ""}">
    ${place !== "brief" ? knowPicture(item, place) : ""}
    ${item.explore ? `<p class="paper-kicker">Something different</p>`
      : item.for ? `<p class="paper-kicker${item.relation === "broad" ? " paper-broad" : ""}">${
      // A story of a topic's page is labelled with the page, as a section
      // is: "For" a page's name said nothing of why it was there - its
      // opening says that.
      /^(topic|page):/.test(String(item.page || "")) ? ""
        : urgent ? "Act on it now, for " : item.relation === "broad" ? "Related, for " : "For "}${
      escapeHtml(item.for)}</p>` : ""}
    <${heading} class="paper-headline">${escapeHtml(item.title)}</${heading}>
    ${place === "lead" && item.why && !item.opening
      ? `<p class="paper-standfirst">${escapeHtml(item.why)}</p>` : ""}
    ${item.opening ? `<p class="paper-opening">${escapeHtml(item.opening)}</p>` : ""}
    ${item.detail ? `<p class="paper-body">${escapeHtml(item.detail)}</p>` : ""}
    ${byline.length || sources.length ? `<p class="paper-byline">${escapeHtml(byline.join(", "))}${
      sources.length ? ` <a href="${escapeHtml(sources[0])}" target="_blank"
        rel="noopener noreferrer"${issue && item.id ? ` data-know-open="${escapeHtml(item.id)}"
        data-issue="${escapeHtml(issue)}"` : ""}>Read the source</a>` : ""}</p>` : ""}
    ${item.because && !item.opening ? `<p class="paper-because"><strong>Why it is here:</strong> ${
      escapeHtml(item.because)}</p>` : ""}
    ${item.new_to_you ? `<p class="paper-new"><strong>New to you:</strong> ${
      escapeHtml(item.new_to_you)}</p>` : ""}
    ${issue && item.id ? (() => {
      // WHAT THE USER SAID OF IT, kept: a label of its own colour, and the
      // button it came from marked - another may still be chosen.
      const said = ((knowCard.data || {}).says || {})[item.id] || "";
      const words = { more: "More like this", less: "Not interested", knew: "Already knew" };
      // KEPT IN THE COLLECTION, or not: apart from what was said of it -
      // keeping a story is not "more like this", and those stay to choose.
      const kept = knowKept(item.id);
      return `${said ? `<span class="paper-said paper-said-${said}">${words[said]}</span>` : ""}
        <div class="paper-say"><button type="button" class="small secondary paper-keep${
          kept ? " chosen" : ""}" data-know-keep="${escapeHtml(item.id)}"
          data-issue="${escapeHtml(issue)}" aria-pressed="${kept ? "true" : "false"}">${
          kept ? "In your collection" : "Add to collection"}</button>${Object.entries(words).map(([action, label]) =>
        `<button type="button" class="small secondary${said === action ? " chosen" : ""}"
          data-know-say="${action}" data-story="${escapeHtml(item.id)}"
          data-issue="${escapeHtml(issue)}"${said === action ? ' aria-pressed="true"' : ""}>${
          label}</button>`).join("")}</div>`;
    })() : ""}
  </section>`;
}

async function followKnowCard() {
  try {
    renderKnowCard(await knowAsk());
  } catch (err) {
    console.warn("connections", err);
  }
}

// An earlier issue read; the newest again by choosing it.
document.addEventListener("change", async (event) => {
  const chosen = event.target.closest?.("[data-know-issue]");
  if (!chosen) return;
  const newest = chosen.options[0] && chosen.options[0].value;
  knowCard.issue = chosen.value === newest ? "" : chosen.value;
  await followKnowCard();
});

$("#ov-know-run").addEventListener("click", async () => {
  $("#ov-know-run").disabled = true;
  try {
    const said = await api.post("/api/connections/run", {});
    if (!said.started) toast("It is already being worked out");
  } catch (err) {
    toast(err.message, "error");
  }
  await followKnowCard();
});

/* -------------------------------------- connections in the State heartbeat

   One line under the panel's head: a bar while the round works out what the
   user needs to know, and what the last one found once it has. Asked again
   every second and a half only while it runs and the tab is open. */
const beatConnections = { timer: null };

function renderStateBeatConnections(progress) {
  const host = $("#dbg-states-connections");
  // Asked again while it runs - or while a heartbeat round runs, which is
  // what starts it.
  clearTimeout(beatConnections.timer);
  if (activeTab === "statebeat" && ((progress && progress.running) || stateBeat.running)) {
    beatConnections.timer = setTimeout(loadStateBeatConnections, 1500);
  }
  if (!progress) { host.innerHTML = ""; return; }
  if (progress.running) {
    host.innerHTML = cxProgressHtml(progress, "Connections: ");
  } else if (progress.error) {
    host.textContent = `Connections: the last working-out failed - ${progress.error}`;
  } else if (progress.finished_at) {
    const n = Number(progress.items) || 0;
    host.textContent = `Connections: last worked out ${cxWhen(progress.finished_at)} - ` +
      `${n} thing${n === 1 ? "" : "s"} to know`;
  } else {
    host.textContent = "Connections: not worked out yet";
  }
}

async function loadStateBeatConnections() {
  try {
    // The small read: the whole state heartbeat report is the debugger's,
    // and far too much to ask for every second and a half.
    const said = await api.get("/api/connections/briefing");
    renderStateBeatConnections((said || {}).progress || null);
  } catch (err) {
    /* the line is an aid */
  }
}

/* ----------------------------------------------------------- refreshing */
async function refresh() {
  try {
    const status = await api.get("/api/status");
    speaksInBubble = Boolean(status.speaks_in_bubble);
    if (status.updating) followUpdate(status.updating);
    const app = status.application || {};
    // WHAT IT IS DOING, IF IT IS DOING ANYTHING. A grouping round is one
    // model call per task - minutes on a busy folder - and an application
    // that looks idle while it works is one somebody quits in the middle
    // of, or sits in front of without knowing there is anything to wait
    // for. The stage is named rather than a bare "busy", because the
    // question a person has after ten seconds of waiting is which part.
    const beats = status.heartbeats || {};
    const working = ["states", "agent"]
      .map((which) => beats[which])
      .filter((one) => one && one.busy);
    const doing = working.length
      ? " · ⟳ " + working.map((one) => {
          const stage = String(one.stage || "").trim();
          return stage ? `${one.doing}: ${stage}` : String(one.doing || "");
        }).join(" · ")
      : "";
    $("#status-pill").classList.toggle("pill-working", working.length > 0);
    // Put together of pieces, so each piece in the display language from
    // the interface's tables (i18n.js) - the whole matches no entry.
    const say = (text) => (window.interfaceLanguage && window.interfaceLanguage.lookUp(text))
      || text;
    $("#status-pill").textContent =
      `v${app.version || "?"} · ${say(status.running ? "running" : "stopped")} · ` +
      `${status.models.primary.label}${status.paths?.frozen ? ` · ${say("packaged")}` : ""}`
      + doing;
    $("#status-pill").title =
      `${app.name || "Personal Agent WaterMelon"} ${app.version || ""}\n` +
      `${say(`internal data: ${status.paths?.internal_data || "?"}`)}\n` +
      `${say(`workspace: ${status.runtime?.policy?.workspace_root || "?"}`)}`;
    renderReauth(status.reauthentication_required);
    if (activeTab === "overview") {
      // The token chart is drawn again now the tab is on screen: drawn at
      // load in a hidden tab, it had no width to draw at.
      try { renderTokenChart(); } catch (err) { /* one panel, not the tab */ }
      await loadOverview(OVERVIEW_PARTS);
      refreshOvRound();
    }
    if (activeTab === "naturedebug") await loadOverview(NATURE_PARTS);
    if (activeTab === "readingdebug") await loadReading();
    if (activeTab === "connectiondebug") await loadConnectionsDebugger();
    if (activeTab === "languagedebug") await loadLanguages();
    if (activeTab === "recommend") await followKnowCard();
    if (activeTab === "calendar") {
      await loadCalendar();
      await loadPending();
    }
    if (activeTab === "lessons") await loadLessons();
    if (activeTab === "recordlog") await loadRecordLog();
    // Not redrawn while something is changed and not saved, or being typed
    // into: what is typed would go.
    if (activeTab === "settings" && !Object.keys(settingsEdit.pending).length
        && !document.activeElement?.closest?.("[data-settings-pane]")) {
      await loadSettings();
      await loadAvatarPreview();
      await loadOcr();
      await loadModules();
    }
    if (activeTab === "debugger") {
      // Both charts are drawn again now that the tab is on screen. They were
      // first drawn at page load, when this panel had no layout and so no
      // width to draw at.
      //
      // Before the map and each in its own try, because one panel failing
      // must not take the others with it: these three are separate answers
      // to separate questions, and the map is the one most likely to throw -
      // it is the one that talks to the component registry.
      // What the computer was used for, moved here from the Overview.
      await loadOverview(USAGE_PARTS);
      // The cost of a gathering moves with what is on disk, so a reading
      // taken when the panel first opened goes stale.
      await loadDebugger();
    }
    if (activeTab === "experience") await loadExperience(false);
    if (activeTab === "xdebug") await loadDebuggerExperience();
    if (activeTab === "chatdebug" && window.chatDebuggerPanel) {
      await window.chatDebuggerPanel.activate();
    }
    if (activeTab === "listenerdebug" && window.listenerDebuggerPanel) {
      await window.listenerDebuggerPanel.activate();
    }
  } catch (err) {
    $("#status-pill").textContent = "backend unreachable";
  }
}

/* Section 75.3: the application uses a stored sign-in without asking, and says
   something only when that sign-in has stopped working. */
function renderReauth(request) {
  const banner = $("#reauth-banner");
  if (!banner) return;
  if (!request) {
    banner.hidden = true;
    return;
  }
  banner.hidden = false;
  reauthState.provider = request.provider || "";
  const where = request.role ? ` This is stopping ${request.role}.` : "";
  $("#reauth-text").textContent =
    `Sign in to ${request.provider} again — ${request.reason}.${where}`;
}

$("#reauth-dismiss")?.addEventListener("click", async () => {
  // Section 75.3: the user has read it; stop saying it. Nothing is fixed by
  // this, and the model's state is still shown where state belongs.
  $("#reauth-banner").hidden = true;
  try {
    await api.post("/api/models/reauthentication/dismiss", {});
  } catch (err) {
    /* dismissing is best effort */
  }
});

$("#reauth-go")?.addEventListener("click", () => openModelSettings(reauthState.provider));

/* SETTINGS IN TWO VIEWS: General - the model the agent thinks with, how
   it is reached, the languages - and Others, every other setting. The one
   last open is opened again. */
function settingsView(view) {
  // Every view there is - one not listed here opened General instead.
  const chosen = ["others", "display", "avatar", "modules", "privacy", "shortcuts"]
    .includes(view) ? view : "general";
  if (chosen === "shortcuts" && typeof refreshShortcuts === "function") refreshShortcuts();
  $$("[data-settings-pane]").forEach((pane) => {
    pane.hidden = pane.dataset.settingsPane !== chosen;
  });
  $$("[data-settings-view]").forEach((button) => {
    const on = button.dataset.settingsView === chosen;
    button.classList.toggle("active", on);
    button.setAttribute("aria-selected", String(on));
  });
  try { localStorage.setItem("settings-view", chosen); } catch (err) { /* kept for now only */ }
}

document.addEventListener("click", (event) => {
  const button = event.target.closest?.("[data-settings-view]");
  if (button) settingsView(button.dataset.settingsView);
});

(() => {
  let saved = "";
  try { saved = localStorage.getItem("settings-view") || ""; } catch (err) { saved = ""; }
  settingsView(saved || "general");
})();

/* Settings, at the provider's sign-in - from the prompt to sign in again,
   and from a run waiting on its model. */
async function openModelSettings(provider) {
  // Section 88.1: the point of the prompt is that signing in is one action.
  // Landing the user in Settings and leaving them to find the right provider
  // among the others is most of the work still to do.
  const tab = $('#tabs button[data-tab="settings"]');
  if (tab) tab.click();
  settingsView("general");
  await loadSettings();
  const form = $("#auth-form");
  if (form) form.hidden = false;
  const open = $("#model-add-open");
  if (open) open.hidden = true;
  const known = ((modelsNow || {}).providers || []).find((p) => p.provider === provider);
  const radio = $(`#auth-form input[name="kind"][value="${modelKindOf(known)}"]`);
  if (radio && !radio.checked) {
    radio.checked = true;
    radio.dispatchEvent(new Event("change"));
  }
  const select = $('#auth-form select[name="provider"]');
  if (select && provider) {
    select.value = provider;
    select.dispatchEvent(new Event("change"));
  }
  if (form) {
    form.scrollIntoView({ block: "center", behavior: "smooth" });
    form.classList.add("wants-attention");
    setTimeout(() => form.classList.remove("wants-attention"), 2500);
  }
}

/* What the prompt is about, so the button can act on it rather than only
   pointing in its general direction. */
const reauthState = { provider: "" };

/* ONCE, NOT TWICE. Where the agent runs with its avatar, every notification
   is said in the bubble beside it, with its buttons; the page showed it again
   as a card of its own - the same words twice, and the page's copy marked it
   read under the bubble. Only an agent with no avatar (headless) leaves it to
   the page. */
let speaksInBubble = false;

async function pollNotifications() {
  if (speaksInBubble) return;
  try {
    const data = await api.get("/api/notifications?unread=true&limit=5");
    if (Number(data.remind_later_minutes)) remindLaterMinutes = Number(data.remind_later_minutes);
    data.notifications.forEach((n) => {
      notificationToast(n);
      api.post("/api/notifications/read", { id: n.id });
    });
  } catch (err) {
    /* backend not ready */
  }
}


/* ------------------------------------------------------------------ states

   Section 34.1, as amended: a state is internal. It is half of the context
   behind every answer, which makes it worth being able to look at, and does
   not make it an entry in the user's diary.

   It used to be drawn on the calendar beside the things they had scheduled.
   Two problems with that. Every task now writes an accompanying state, so the
   same thing appeared twice - once as the task, once as a span saying the task
   was going to happen. And the rest of the states are the agent's inferences
   about the user, "quiet desk since 11:53", which is material for looking at
   the agent rather than for planning a week.

   So it is shown here, in the Debugger, and still as a calendar: a span is
   what a state is, and a list of them loses the thing that matters about them.
*/
/* ------------------------------------------------------- retrieval cost
   Section 14.36, as amended.

   The graph this replaced lived in a database, and its cost did not depend on
   how much was in it in any way a person needed to watch. A search over files
   does: every round of the data heartbeat adds records, nothing is deleted
   automatically, and the index grows with them. So "is this still fast" is a
   standing question rather than a settled one.

   Two views, and the default is the second-order one on purpose. A list of
   query times answers "was that slow", which is occasionally useful. The
   average plotted against how much was on disk answers "will this still work
   in six months", which is the question the design actually turns on.
*/

const dbgStates = {
  anchor: startOfDay(new Date()),
  states: [],
  open: true,
  //: Days the user has opened out. Kept across a redraw so that paging to the
  //: next month and back does not silently close what they were reading.
  expanded: new Set(),
};

/* Section 37, as amended: the heartbeat, run on demand and shown whole.

   It is the part of the agent nobody can watch. It runs on a timer, decides
   what is worth doing, and all that is visible afterwards is a calendar that
   has changed - so the question "why did it do that" had no answer short of
   reading a log. This runs one now and shows each step: what it went looking
   for, the text it was actually given, and what it did with it.

   The context is shown as text rather than as a list of titles. What a
   gathering found is a different question from what the model was handed,
   and the gap between them is where an odd answer is usually explained. */
const dbgBeat = { running: false, report: null, opened: new Set() };

function renderHeartbeatRun() {
  const host = $("#dbg-beat-body");
  if (!host) return;
  const note = $("#dbg-beat-note");
  const report = dbgBeat.report;
  if (dbgBeat.running && !report) {
    if (note) note.textContent = "gathering\u2026";
    host.innerHTML = `<p class="muted">Running. The four gatherings come
      first and are quick; the four model calls after them are what takes the
      minute, and each appears here as it answers.</p>`;
    return;
  }
  if (!report) {
    if (note) note.textContent = "";
    return;
  }
  if (report.skipped) {
    host.innerHTML = `<p class="muted">${escapeHtml(String(report.skipped))}</p>`;
    return;
  }
  const steps = report.steps || [];
  const spent = report.started_at && report.finished_at
    ? ((new Date(report.finished_at) - new Date(report.started_at)) / 1000).toFixed(1)
    : null;
  if (note) {
    if (dbgBeat.running) {
      const done = steps.filter((s) => s.phase === "answered").length;
      note.textContent = `step ${Math.min(done + 1, steps.length || 4)} of `
        + `${steps.length || 4}\u2026`;
    } else {
      note.textContent = spent !== null ? `last run took ${spent}s` : "";
    }
  }
  const blocked = report.blocked
    ? `<p class="beat-head-line"><strong>The model was not available.</strong>
       ${escapeHtml(String(report.reason || ""))} The steps below show what had
       already been gathered when it was asked.</p>`
    : "";
  const message = report.message_to_user
    ? `<p class="beat-head-line"><strong>It said to you:</strong>
       ${escapeHtml(String(report.message_to_user))}</p>`
    : "";
  // Labelled, because unlabelled it reads as though the panel itself were
  // narrating. It is step 1's answer to "what does the user appear to be
  // doing, and what matters now" - the model's words, not the agent's.
  const analysis = report.state_analysis
    ? `<div class="beat-analysis">
         <div class="beat-sub">what it made of the day \u2014 step 1's answer</div>
         <p>${escapeHtml(String(report.state_analysis))}</p>
       </div>`
    : "";
  host.innerHTML = blocked + analysis + message
    + (steps.length ? steps.map(beatStep).join("")
                    : `<p class="muted">This run produced no steps.</p>`);
}

/* How much of this step the model chose, and how much was chosen for it.

   Every step ends in a model's answer, so "the model did this step" is
   true of every step and tells a reader nothing. What differs is how much of
   the step was the model's: step 1 chooses what it looks at and keeps
   choosing until it stops; the other three are handed a context assembled
   before the question and choose only what to say about it. Reading the
   rows one at a time gets there eventually; the step should say it. */
function beatDecided(step) {
  // Nothing to summarise yet. This said "the model chose what to look at -
  // asked for more twice - and wrote the answer" while the step was on its
  // second round and had written nothing, which is not a summary of what
  // happened but a guess at how it will end.
  if (!["answered", "blocked"].includes(String(step.phase || ""))) {
    return `${beatSub(step, "in summary: who decided what")}
      <p class="beat-nothing">Not yet - this step is still going.</p>`;
  }
  const rows = step.trail || [];
  // Asks only. Answering is the model's decision too, and counting it as
  // one more "asked for more" reports a step that asked twice and then
  // stopped as a step that asked three times - which is the number this
  // line exists to give.
  const mine = rows.filter((row) => row.decided_by === "model"
    && row.did !== "answered");
  const rounds = Number(step.rounds || 0);
  const parts = mine.length
    ? [`asked for more ${mine.length} ${mine.length === 1 ? "time" : "times"}`,
       ...(rounds ? [`over ${rounds} rounds`] : [])]
    : [];
  const model = mine.length
    ? `chose what to look at - ${parts.join(", ")} - and wrote the answer`
    : "wrote the answer, and nothing else";
  const fixed = mine.length
    ? "the window it started from, and which tools it could use"
    : "the words searched for, the folders and the budget";
  const settings = [...new Set(rows.filter((row) => row.decided_by === "fixed")
    .map((row) => String(row.setting || "")).filter(Boolean))];
  // Named separately from both. Work that no one chose and no model saw -
  // a transform that runs the same way every time - is a third kind of
  // thing, and lumping it under either of the others misreports it.
  const code = rows.filter((row) => row.decided_by === "code")
    .map((row) => String(row.decision || "")).filter(Boolean);
  return `${beatSub(step, "in summary: who decided what")}
    <ul class="beat-decided">
      <li><span class="trail-who trail-who-model">the model</span>
        ${escapeHtml(model)} <span class="muted">- during this run</span></li>
      <li><span class="trail-who trail-who-fixed">fixed</span>
        ${escapeHtml(fixed)} <span class="muted">- set before the run</span>
        ${settings.map((name) =>
          `<code class="trail-setting">${escapeHtml(name)}</code>`).join(" ")}</li>
      ${code.length
        ? `<li><span class="trail-who trail-who-code">code</span>
            ${escapeHtml(code.join("; "))}
            <span class="muted">- no choice, no model</span></li>` : ""}
    </ul>`;
}

/* How big something is, in the unit that is actually spent.

   These read "132769 characters", which is a fact about a string. What is
   capped, paid for and worth deciding about is tokens, and nobody does
   that division in their head. The count comes from the agent, using the
   same estimator the budgets use; the fallback is for a report written
   before that count existed. */
function beatSize(tokens, text) {
  const count = tokens === undefined || !Number.isFinite(Number(tokens))
    ? Math.round(String(text || "").length / 4)
    : Number(tokens);
  return `${count.toLocaleString()} tokens`;
}

/* Everything this step is able to do, and how much of each it did.

   The outcome below shows what happened. It cannot be read for what did
   not: "nothing" covers a step that decided against, a step with nothing
   to decide about, and a step that was never able to do the thing the
   reader had in mind. The third is the common one - somebody looking at
   step one for a scheduled task is looking at the wrong step, and an empty
   outcome does not tell them so. */
function beatCouldDo(step) {
  const able = step.could_do || [];
  if (!able.length) return "";
  // Same reason. "None" against each thing it can do is a verdict, and a
  // step on its second round has not reached any of them.
  if (!["answered", "blocked"].includes(String(step.phase || ""))) {
    return `${beatSub(step, "in summary: what it could do")}
      <p class="beat-nothing">Not yet - this step is still going.</p>`;
  }
  const rows = able.map((row) => `<li class="${
    Number(row.count) ? "beat-did" : "beat-did-not"}">
    <span class="beat-did-count">${Number(row.count) || "none"}</span>
    ${escapeHtml(String(row.what))}</li>`).join("");
  return `${beatSub(step, "in summary: what it could do, and what it did")}
    <ul class="beat-could">${rows}</ul>
    ${step.cannot
      ? `<p class="muted beat-cannot">${escapeHtml(String(step.cannot))}</p>`
      : ""}`;
}

/* What this step cost, start to finish.

   The header read "1 memories, 41 ms", and 41 ms was the gathering - the
   cheap half. The minute somebody waits through is the model calls, and
   that was reported nowhere; nor was what the step spent, which is the
   number anybody deciding about the interval actually needs. Per step,
   because a total for the run says a heartbeat is expensive and not which
   part of it is. */
function beatCost(step) {
  if (!step.phase || step.phase === "gathered") return "waiting";
  const parts = [`${(step.records || []).length} memories`];
  // Printed whether or not there were any. A step that made no call cost
  // nothing, and a blank where the number goes reads as a step that was
  // not measured - which is the one thing it should not be confused with.
  const calls = Number(step.calls || 0);
  parts.push(`${calls} call${calls === 1 ? "" : "s"}`);
  parts.push(`${Number(step.tokens_total || 0).toLocaleString()} tokens (${
    Number(step.tokens_in || 0).toLocaleString()} in, ${
    Number(step.tokens_out || 0).toLocaleString()} out)`);
  // Both clocks. The gathering and the calls are different costs with
  // different remedies, and one number covering both hides which is which.
  const whole = Number(step.elapsed_ms || 0);
  const gathering = Math.round(Number(step.duration_ms || 0));
  parts.push(`${beatSeconds(whole)} (${gathering} ms gathering)`);
  return escapeHtml(parts.join(" \u00b7 "));
}

function beatSeconds(ms) {
  return ms >= 1000 ? `${(ms / 1000).toFixed(1)} s` : `${ms} ms`;
}

/* A numbered heading inside a step.

   The steps are numbered and everything inside them was not, so a
   reader who had scrolled past a trail of a dozen rows met "the context,
   as it stood at the end" with nothing saying which step it belonged to or
   how far through they were. Numbered 1.1, 1.2 and so on, it carries both. */
function beatSub(step, title, extra) {
  step.__section = (step.__section || 0) + 1;
  step.__at = `${step.step}.${step.__section}`;
  return `<div class="beat-sub">
    <span class="beat-sub-n">${escapeHtml(String(step.step))}.${
      step.__section}</span>
    ${escapeHtml(title)}${extra ? ` ${extra}` : ""}</div>`;
}

function beatStep(step) {
  // Reset, because the step object outlives the render: it is held in the
  // page between refreshes, and a counter left on it would carry on from
  // where the last render stopped.
  step.__section = 0;
  const key = String(step.id || step.step);
  const open = dbgBeat.opened.has(key) ? " open" : "";
  const records = step.records || [];
  const context = String(step.context || "");
  const outcome = step.outcome || {};
  /* Whether this step has finished.

     Most of what follows is written as a conclusion - "it did not search",
     "nothing came of it" - and a step being watched has not decided yet.
     Declared here because the first of those uses it. */
  const done = ["answered", "blocked"].includes(String(step.phase || ""));
  // Whether this step gathered for itself. The state step starts from a
  // floor and decides what else it wants; the other three are handed a
  // context assembled from a query written before they ran.
  const gathered = (step.trail || []).some((row) => row.did === "floor");
  /* Whether this step has begun.
     The steps are gathered for before any of them is asked, so all
     four had a context, a token count and a trail before the first was
     touched - and steps two, three and four sat there reporting what they
     were holding while step one was still on its first round. They run one
     after another; until its turn comes a step has one thing to say. */
  const begun = step.phase && step.phase !== "gathered";
  /* Whether this step's outcome is known yet, which is not the same as
     whether the step has answered.

     The states are written, the memories filed and the actions performed
     after every step has answered - so between its own answer and the
     end of the run, step one has an empty outcome that means "not yet".
     It was rendered as "Nothing came of this step", which is the opposite
     conclusion, and it was wrong for about a minute of every run. */
  const settled = step.outcome_known === true
    || String(step.phase || "") === "blocked";
  const produced = !settled
    ? `<div class="beat-outcome beat-nothing">Waiting - what a step wrote is
        recorded once the run has finished asking every step.</div>`
    : Object.keys(outcome).length
    ? Object.entries(outcome).map(([name, value]) =>
        `<div class="beat-label">${escapeHtml(name.split("_").join(" "))}</div>
         ${beatOutcomeValue(name, value)}`).join("")
    // In this step's own terms. One sentence was shown for every step, and
    // it was about the cost of interrupting - so a step that writes states
    // explained itself by the cost of a notification it cannot send.
    : `<div class="beat-outcome beat-nothing">${escapeHtml(String(
          step.nothing || "Nothing came of this step."))}</div>`;
  /* Three outcomes, and they used to be two.

     "Nothing matched" was written when every step searched the library
     before it was asked anything, so an empty result could only mean the
     library had nothing. Step 1 decides for itself whether to search, and
     mostly does not - so the line was reporting a fact about the library
     on a step that never asked it a question. A reader has no way to tell
     that from a search that genuinely came back empty, and the two lead
     somewhere completely different: one is a step that was satisfied, the
     other is a memory that could not help. */
  const searched = (step.trail || []).some((row) => row.did === "search")
    || Number(step.searches || 0) > 0;
  const found = records.length
    ? `<ul class="beat-records">${records.map((r) =>
        `<li><span class="trail-item">${escapeHtml(String(r.title || r.id || ""))}</span>
          <span class="muted">${escapeHtml(String(r.folder || ""))}</span></li>`)
        .join("")}</ul>`
    : !done
      ? `<p class="beat-nothing">Nothing yet. This step is still going.</p>`
      : searched
        ? `<p class="beat-nothing">It searched, and nothing matched. The step
            still ran, on what it already had.</p>`
        : `<p class="beat-nothing">It did not search. What it started with was
            enough to answer from.</p>`;
  return `<details class="beat-step" data-beat="${escapeHtml(key)}"${open}>
    <summary>
      <span class="beat-n">${escapeHtml(String(step.step))}</span>
      <span class="beat-title">${escapeHtml(String(step.title || ""))}</span>
      ${beatPhase(step)}
      <span class="beat-meta">${beatCost(step)}</span>
    </summary>
    <div class="beat-inner">
      ${!begun ? `<p class="beat-nothing">Waiting for the step before it.
        The steps run one after another.</p>` : `
      ${/* In the order the step ran, which is not the order these were
            written in. A reader following a numbered list expects the
            numbers to be a sequence: what it looked for, what it did,
            what that left it holding, the call, what came of it. The two
            summaries are summaries, so they come after the thing they
            summarise rather than in front of it. */ ""}
      ${/* Only where the query came first.

            Three of the steps are handed a context gathered from a query
            built before anything ran, so the query is the first thing that
            happened. The state step has no query until it writes one: its
            words are chosen during the loop, in the searches it decides to
            make, so listing them above the trail puts a result of the loop
            in front of the loop. Its searches carry their own words, one
            row each, which is where they happened. */ ""}
      ${gathered ? "" : `${beatSub(step, "what it searched for")}
        <p>${escapeHtml((step.asked_for || []).join(", ")) || "\u2014"}</p>`}
      ${beatSub(step, "what it did, round by round")}
      ${beatTrail(step.trail || [], step.__at)}
      ${found}
      ${/* "At the end" is a claim about a step that has ended. Mid-run
            the context is still growing, and a figure labelled as final
            is the wrong number and the wrong tense. */ ""}
      ${/* Only once there is an end to have been left at. A running total
            beside a heading that says "left holding" is a number that will
            be wrong by the time it is read. */ ""}
      ${beatSub(step, "what it was left holding",
        done && context ? `<span class="muted">the context at the end,
          ${beatSize(step.context_tokens, context)}</span>
          <button class="small secondary beat-expand" data-expand>expand</button>`
          : "")}
      ${!done
        ? `<p class="beat-nothing">Not yet - this step is still going.</p>`
        : context
          ? `<div class="beat-context">${escapeHtml(context)}</div>`
          : `<p class="beat-nothing">Nothing was given for this step.</p>`}
      ${beatCall(step)}
      ${beatSub(step, "what came of it",
        step.answers ? ` \u2014 ${escapeHtml(String(step.answers))}` : "")}
      ${produced}
      ${beatCouldDo(step)}
      ${beatDecided(step)}`}
    </div>
  </details>`;
}

/* Section 37, as amended: the gathering, round by round.

   "Three memories were gathered" and being able to see why the fourth was
   not are different things, and only the second answers the question this
   panel exists for. Each folder is searched in turn with its own room, the
   candidates are ranked together, and then each is taken or left for a
   reason - usually the token budget running out. */
/* A result that can be opened.

   Section 44.3 gives chat its citations: a memory the answer rests on, with
   a card saying what it is and why it was reached. A retrieval trail wants
   exactly the same card - more so, because the trail's whole subject is how
   each record got there - so it opens the same one, with the words that
   matched *on this occasion* added to it.

   Where there is no id there is nothing to open: a title on its own is
   still worth showing and is simply not a button. */
function trailRecord(entry) {
  const title = escapeHtml(String(entry.title || ""));
  if (!entry.id) return `<span class="trail-item">${title}</span>`;
  return `<button type="button" class="trail-item trail-open"
    data-record="${escapeHtml(String(entry.id))}"
    data-why="${escapeHtml(String(entry.why || ""))}"
    data-matched="${escapeHtml(matchedWords(entry).join("\n"))}"
    data-words="${escapeHtml((entry.matched || []).join("\n"))}"
    data-keywords="${escapeHtml((entry.matched_keywords || []).join("\n"))}"
    >${title}</button>${entry.id
      ? `<code class="trail-id">${escapeHtml(String(entry.id))}</code>` : ""}`;
}

/* Each matched word with the part of the record it was found in.

   The body is not indexed, so every match is in the keywords, the title or
   the summary - and a reader looking at a title and a summary that do not
   contain the word has no way to reach "then it was in the keywords". */
function matchedWords(entry) {
  const where = entry.matched_where || {};
  return (entry.matched || []).map((word) =>
    where[word] ? `${word} (${where[word]})` : word);
}

/* The same card the Debugger's states grid opens.

   A state shown here and a state shown there are the same thing, and the
   question is the same: what it is, how long it runs, where it came from
   and on what judgement the agent believes it. */
function openBeatState(anchor) {
  const wanted = anchor.dataset.beatState;
  const rows = (dbgBeat.report?.steps || [])
    .flatMap((step) => step.trail || [])
    .flatMap((row) => row.states_started || []);
  const state = rows.find((s) => String(s.id) === wanted);
  if (state) openDebuggerState(state, anchor);
}

async function openTrailRecord(anchor) {
  try {
    const record = await api.get(
      `/api/library/record?id=${encodeURIComponent(anchor.dataset.record)}`);
    showCitation(anchor, {
      ...record,
      why: anchor.dataset.why || record.why,
      matched_here: (anchor.dataset.matched || "").split("\n").filter(Boolean),
      matched_words: (anchor.dataset.words || "").split("\n").filter(Boolean),
      matched_keywords: (anchor.dataset.keywords || "").split("\n").filter(Boolean),
    });
  } catch (err) {
    toast(err.message, "error");
  }
}

/* When this was decided, and by what.

   A trail of searches and results does not say which of them anybody
   decided, and the three kinds read identically from their results:

     the model   chose it during this run, and could have chosen otherwise
     fixed       decided before the run, by a setting - which is named, so
                 that a reader who thinks it is wrong knows what to change
     code        no choice in it at all: a transform that runs the same way
                 every time, with nothing to configure and no model asked

   The middle one used to say "the agent", which was worse than vague: the
   model is part of the agent, and so is the code, so the label named the
   thing all three have in common. What distinguishes them is *when* the
   decision happened and whether anything could have gone differently. */
function whoDecided(row) {
  const who = String(row.decided_by || "");
  if (!who) return "";
  const label = who === "model" ? "the model chose, during this run"
    : who === "code" ? "code, no choice and no model"
      : "fixed before the run";
  return `<span class="trail-who trail-who-${escapeHtml(who)}">${label}</span>
    ${row.decision ? `<span class="trail-decision">${
      escapeHtml(String(row.decision))}</span>` : ""}
    ${row.setting ? `<code class="trail-setting">${
      escapeHtml(String(row.setting))}</code>` : ""}`;
}

/* What the model said in the same turn as the call.

   The arguments say what it asked for; this is the only account of why. A
   decision reported without it is a number - "looked back 240 minutes" -
   and the question a reader has is what made 240 the right answer. */
function whyItAsked(row) {
  if (!row.said) return "";
  return `<div class="trail-said">${escapeHtml(String(row.said))}</div>`;
}

/* The events themselves, rather than how many of them there were.

   This said "12 events" in a panel whose whole job is to say what the step
   read. The events are the answer to almost every question somebody opens
   it with, and the count was the one part of them that answers none. */
/* When each of them happened, not the stretch they span.

   "x3 over 02:20-02:21" is the same string for three clicks in four seconds
   and three visits over a minute, and those are a double-click and a person
   going back and forth. */
function eventTimes(event) {
  const times = event.at_times || [];
  if (!times.length) return String(event.at || "");
  const shown = times.join(", ");
  return event.times_left_out
    ? `${shown} and ${event.times_left_out} more` : shown;
}

function beatEvents(row) {
  const events = row.events;
  if (!Array.isArray(events) || !events.length) return "";
  const rows = events.map((event) => `<li>
    ${Number(event.count) > 1
      ? `<span class="ev-count">&times;${Number(event.count)}</span>` : ""}
    <span class="ev-at">${escapeHtml(eventTimes(event))}</span>
    <span class="ev-app">${escapeHtml(String(event.application || ""))}</span>
    <span class="muted">${escapeHtml(String(event.event_type || ""))}</span>
    ${event.title ? `<div class="ev-title">${escapeHtml(String(event.title))}</div>` : ""}
    ${(event.keywords || []).length
      ? `<div class="ov-about">${event.keywords.map((word) =>
          `<span class="ov-kw">${escapeHtml(String(word))}</span>`).join("")}</div>`
      : ""}
    ${event.url ? `<div class="ev-url">${escapeHtml(String(event.url))}</div>` : ""}
    ${event.path ? `<div class="ev-url">${escapeHtml(String(event.path))}</div>` : ""}
    ${event.text ? `<div class="ev-text">${escapeHtml(String(event.text))}</div>` : ""}
    ${(event.also_read || []).map((other) =>
      `<div class="ev-text muted">also read: ${escapeHtml(String(other))}</div>`).join("")}
    ${event.texts_left_out
      ? `<div class="ev-text muted">(${event.texts_left_out} further readings
          of this, not shown)</div>` : ""}
    ${event.borrowed
      ? `<div class="ev-text ev-borrowed">no text of its own &mdash; this
          window read at ${escapeHtml(String(event.borrowed_at || ""))}:
          ${escapeHtml(String(event.borrowed))}</div>` : ""}
    </li>`).join("");
  const more = row.events_not_shown
    ? `<li class="muted">and ${row.events_not_shown} more</li>` : "";
  return `<details class="trail-events"><summary>${events.length} shown${
    row.events_not_shown ? ` of ${events.length + row.events_not_shown}` : ""
  }</summary><ul class="ev-list">${rows}${more}</ul></details>`;
}

/* What a step produced, in the shape the thing itself has.

   Most outcomes are a line of text and read fine as one. States do not: a
   state is a title, a period, what it rests on and why the agent believes
   it, and flattening that into one string is the same loss as reporting
   "sources: 2" instead of the two sources. */
function beatOutcomeValue(name, value) {
  if (name === "states_written" && Array.isArray(value) && value.length) {
    return beatStateCards(value);
  }
  return `<div class="beat-outcome">${escapeHtml(asText(value))}</div>`;
}

/* Each state this step put on the calendar, written out.

   The card carries what somebody checking the state needs and nothing it
   would have to be taken on trust for: the period and how much of the
   window went to it, the files and pages themselves, the argument, and
   the stretch of activity the review read it from - which the script put
   there and the model was never asked for. */
function beatStateCards(states) {
  const list = (label, items) => (items || []).length
    ? `<div class="beat-card-part"><span class="event-label">${label}</span>
       <ul class="trace-evidence">${items.map((item) =>
         `<li>${escapeHtml(String(item))}</li>`).join("")}</ul></div>` : "";
  return `<ul class="beat-cards">${states.map((state) => `<li class="beat-card">
    <div class="beat-card-head">
      <span class="beat-card-title">${escapeHtml(String(state.title || "(untitled)"))}</span>
      <span class="trail-count">${escapeHtml(beatCardLasts(state))}</span>
    </div>
    ${state.continued
      ? `<div class="muted beat-card-part">Already on the calendar - this
          window carried it on and moved its end rather than writing a
          second one.</div>` : ""}
    ${state.detail
      ? `<div class="beat-card-detail">${escapeHtml(String(state.detail))}</div>` : ""}
    ${list("What it was built from", state.sources)}
    ${list("Evidence", state.evidence)}
    ${state.reasoning
      ? `<div class="beat-card-part"><span class="event-label">Reasoning</span>
         <span>${escapeHtml(String(state.reasoning))}</span></div>` : ""}
    <div class="beat-card-part"><span class="event-label">Read from</span>
      <span>${escapeHtml(stateReadFrom(state)
        || "the stretch was not recorded")}</span></div>
  </li>`).join("")}</ul>`;
}

/* When a state runs, and how much of the window actually went to it.

   Two different questions, and the second is the one four states at once
   raise: a window is only so long, and a state claiming most of it and one
   claiming two minutes are not the same claim about the user. */
function beatCardLasts(state) {
  const at = (value) => {
    const when = value ? new Date(value) : null;
    return when && !Number.isNaN(when.getTime()) ? when.toLocaleTimeString() : "";
  };
  const from = at(state.starts_at);
  const to = at(state.ends_at);
  const period = from && to ? `${from} to ${to}` : from || to || "no period";
  const mins = Number(state.minutes || 0);
  return mins ? `${period} · ${mins} minutes of the window` : period;
}

/* The states the step started from.

   Named, not counted - "2 states running" is the same failure as "12
   events", one line down - and each with how long it has been true, which
   is most of what a state is: one that started forty minutes ago and one
   that has held for a fortnight are different claims about the user, and a
   title says neither.

   Each opens the card the Debugger's own states grid opens, because the
   question a reader has here is the same one: what is this, where did it
   come from, and why does the agent believe it. */
function beatStates(row) {
  const states = row.states_started;
  if (!Array.isArray(states) || !states.length) return "";
  const rows = states.map((state) => `<li>
    <button type="button" class="trail-item trail-state"
      data-beat-state="${escapeHtml(String(state.id || ""))}">${
      escapeHtml(String(state.title || "(untitled state)"))}</button>
    <span class="trail-count">${escapeHtml(stateLasts(state))}</span>
    ${state.about === "agent"
      ? `<span class="muted">the agent intends</span>` : ""}
    </li>`).join("");
  const more = row.states_not_shown
    ? `<li class="muted">and ${row.states_not_shown} more</li>` : "";
  return `<div class="trail-sub">the states it started with</div>
    <ul class="trail-titles trail-states">${rows}${more}</ul>`;
}

/* How long it runs, and how much of that is behind it.

   "3 hours" answers what was written down; "started 40 minutes ago" answers
   what a reader looking at a heartbeat wants, which is how far into this
   the user already is. */
function stateLasts(state) {
  const hours = Number(state.span_hours || 0);
  const span = hours
    ? (hours >= 48 ? `${Math.round(hours / 24)} days`
      : hours >= 1 ? `${Math.round(hours)} hours`
        : `${Math.round(hours * 60)} minutes`)
    : "no end recorded";
  const from = state.starts_at ? new Date(state.starts_at) : null;
  if (!from || Number.isNaN(from.getTime())) return span;
  const mins = Math.round((Date.now() - from.getTime()) / 60000);
  const since = mins < 0 ? `starts in ${-mins} minutes`
    : mins < 90 ? `${mins} minutes in`
      : mins < 2880 ? `${Math.round(mins / 60)} hours in`
        : `${Math.round(mins / 1440)} days in`;
  return `${span} \u00b7 ${since}`;
}

/* One side of the fold, with its own size on the line that opens it.

   The counts were on the row, away from the text they describe, so reading
   "before folding" told you nothing about what you were about to open and
   the two numbers had to be carried back from a line above. */
/* What the model was offered, which is the other half of the ask.

   There is no separate call that asks "do you want to search" - the same
   message that asks for the answer carries the tools, and the model
   answers by using one or by not. So the offer belongs beside the
   message: it travels in the request rather than in the messages, and a
   reader rebuilding the call from the message alone sees it being told it
   may ask for things without ever seeing what. */
function beatTools(tools) {
  if (!Array.isArray(tools) || !tools.length) return "";
  const rows = tools.map((tool) => `<li>
    <code class="trail-setting">${escapeHtml(String(tool.name || ""))}</code>
    <div class="ev-text">${escapeHtml(String(tool.description || ""))}</div>
    ${tool.takes
      ? `<pre class="trail-feed">${escapeHtml(
          JSON.stringify(tool.takes, null, 2))}</pre>` : ""}
    </li>`).join("");
  return `<details class="trail-events">
    <summary>what it could ask for
      <span class="trail-count">${tools.length} tools</span></summary>
    <ul class="ev-list">${rows}</ul></details>`;
}

function beatFoldText(label, text, tokens, events) {
  if (!text) return "";
  const size = [
    events === undefined ? "" : `${events} events`,
    tokens === undefined ? "" : `${Number(tokens).toLocaleString()} tokens`,
  ].filter(Boolean).join(", ");
  return `<details class="trail-events"><summary>${escapeHtml(label)}
    ${size ? `<span class="trail-count">${escapeHtml(size)}</span>` : ""}
    </summary>
    <pre class="trail-feed">${escapeHtml(String(text))}</pre></details>`;
}

/* The trail, numbered inside its own section.

   Two numbering schemes were running down the same column: the sections
   (1.1, 1.2, 1.3) and the rounds a call is on (ask round 1, ask round 2,
   answer round 3). Read in sequence, "answer round 3" sits directly above
   "1.3" and the two look like the same counter disagreeing with itself.
   Every row now carries its place in the section it is inside, so the
   only numbers on the page are one sequence. */
function beatTrail(trail, at) {
  if (!trail.length) return "";
  const rows = trail.map((row, index) => {
    const step = at ? `<span class="trail-n">${escapeHtml(at)}.${
      index + 1}</span> ` : "";
    /* What this row cost, on the row.

       A trail said what happened and never what any of it took, so a
       reader looking for where a minute went had a list of events and no
       way to weigh them - the folding and a model call read the same. The
       zeros are printed too: a tool call spends no tokens and the folding
       spends none, and that is the fact, not a gap in the measuring. */
    const cost = row.ms === undefined && row.tokens === undefined ? ""
      : `<span class="trail-cost">${beatSeconds(Number(row.ms || 0))} \u00b7 ${
          Number(row.tokens || 0).toLocaleString()} tokens</span>`;
    const did = String(row.did || "");
    if (did === "plan") {
      return `<li>${step}<span class="trail-did">plan</span>${cost}
        ${(row.folders || []).map((f) =>
          `${escapeHtml(String(f.folder))}&times;${f.room_for}`).join(", ")}
        <span class="muted">at most ${row.at_most} records,
          ${row.token_budget} tokens</span>
        ${whoDecided(row)}</li>`;
    }
    /* Step 1 does not begin with a plan, because nothing planned it. It
       begins with everything since the last review - the window is the
       heartbeat's own interval - and anything after that is something the
       step went and asked for. */
    if (did === "floor") {
      const states = beatStates(row);
      // Both numbers. Folding that reports only what was sent is a
      // compression nobody can check, and the ratio is the thing to look at.
      const folded = row.events_folded
        ? `<span class="trail-count">${row.events_seen} events, folded to
            ${row.events_count}</span>`
        : `<span class="trail-count">${row.events_count} events</span>`;
      /* What this floor actually was, which is not the same for every
         step. The step that decides what to do is given no window at all -
         it starts from the calendar - and this line said "the last 0
         minutes, 0 events" for it, which reads as an empty window rather
         than as no window. */
      const window = Number(row.minutes)
        ? `the last ${row.minutes} minutes ${folded},` : "";
      return `<li class="trail-floor">${step}<span class="trail-did">start</span>${cost}
        ${window}
        <span class="trail-count">${row.states} ${
          Number(row.states) === 1 ? "state" : "states"}</span>
        ${whoDecided(row)}
        ${row.why ? `<span class="trail-why">${escapeHtml(String(row.why))}</span>` : ""}
        ${beatEvents(row)}${states}</li>`;
    }
    if (did === "open") {
      return `<li class="trail-read">${step}<span class="trail-did">open</span>${cost}
        ${trailRecord(row)}
        ${row.folder ? `<span class="muted">${escapeHtml(String(row.folder))}</span>` : ""}
        <span class="trail-why">read in full</span>
        ${whoDecided(row)}${whyItAsked(row)}</li>`;
    }
    /* Folding, with the input on both sides of it.

       A compression that reports its own output is one nobody can check,
       so the same feed is shown rendered the same way before and after -
       and the label says this was code rather than a model, because every
       other row in this trail is somebody choosing something. */
    /* The call itself. Without it the trail runs start, fold, search - and
       a reader cannot see that the search came *after* a model call, which
       is the only thing that explains why those words and not others. */
    if (did === "asked") {
      // The message, not a description of it. "20 lines of activity, 146
      // states" says how much went in and never what, and what was sent is
      // the only thing that explains what came back.
      const carried = row.carried_over
        ? `<span class="muted">plus the ${row.carried_over} message${
            row.carried_over === 1 ? "" : "s"} before it</span>` : "";
      return `<li class="trail-asked">${step}<span class="trail-did">ask</span>${cost}
        round ${row.round}
        ${row.context_tokens !== undefined
          ? `<span class="trail-count">${Number(row.context_tokens)
              .toLocaleString()} tokens of context</span>` : ""}
        ${whoDecided(row)}
        ${beatFoldText(row.round > 1 ? "what was added for this round"
                                     : "the message it was sent",
                       row.sent, row.sent_tokens)} ${carried}
        ${beatFoldText("the standing instruction, sent every round",
                       row.system)}
        ${beatTools(row.tools)}</li>`;
    }
    if (did === "answered") {
      return `<li class="trail-answered">${step}<span class="trail-did">answer</span>${cost}
        round ${row.round}
        ${whoDecided(row)}${whyItAsked(row)}</li>`;
    }
    if (did === "fold") {
      // The saving, worked out here rather than left to the reader. Two
      // numbers next to each other are a subtraction somebody has to do,
      // and the whole point of the row is what folding bought.
      const saved = Number(row.before_tokens || 0) - Number(row.after_tokens || 0);
      const share = Number(row.before_tokens)
        ? Math.round((saved / Number(row.before_tokens)) * 100) : 0;
      return `<li class="trail-fold">${step}<span class="trail-did">fold</span>${cost}
        <span class="trail-count">${row.before_events} events into
          ${row.after_events}</span>
        <span class="trail-count">${row.before_tokens} tokens into
          ${row.after_tokens}</span>
        ${saved > 0
          ? `<span class="trail-saved">${saved} tokens saved,
              ${share}%</span>` : ""}
        ${whoDecided(row)}
        ${beatFoldText("before folding", row.before_text,
                       row.before_tokens, row.before_events)}
        ${beatFoldText("after folding, which is what the model was given",
                       row.after_text, row.after_tokens, row.after_events)}</li>`;
    }
    if (did === "search") {
      // One <li> per title. Run together they read as a paragraph, and two
      // record titles with no boundary between them are one sentence that
      // makes no sense - which is how they were first shown.
      // Each result with the words that found it. "What came back" without
      // "why that one" leaves the interesting half to be guessed, and the
      // answer is usually a single word - sometimes one nobody expected to
      // be doing the work.
      const hits = row.hits || (row.titles || []).map((title) => ({ title }));
      const titles = hits.length
        ? `<ul class="trail-titles">${hits.map((hit) =>
            `<li>${trailRecord(hit)}
              ${hit.score !== undefined
                ? `<span class="trail-score">${Number(hit.score).toFixed(2)}</span>` : ""}
              ${hit.why ? `<span class="trail-why">${escapeHtml(String(hit.why))}</span>` : ""}
             </li>`).join("")}</ul>`
        : "";
      const outcome = row.fell_back ? "fell-back" : (row.found ? "hit" : "miss");
      return `<li class="trail-search trail-${outcome}">
        ${step}<span class="trail-did">search</span>${cost}
        <strong>${escapeHtml(String(row.folder))}</strong>
        ${(row.asked_for || []).length
          ? `<span class="trail-asked">${(row.asked_for || [])
              .map((q) => escapeHtml(String(q))).join(" / ")}</span>` : ""}
        ${(row.terms || []).length
          ? `<div class="trail-terms">searched by
              <code>${(row.terms || []).map((w) => escapeHtml(String(w)))
                .join("</code> <code>")}</code>
              ${(row.dropped || []).length
                ? `<span class="muted">- filler words, always ignored:
                    ${(row.dropped || []).map((w) => escapeHtml(String(w)))
                      .join(", ")}</span>` : ""}</div>` : ""}
        <span class="muted">room for ${row.room_for}</span>
        <span class="trail-count">found ${row.found}</span>
        ${whoDecided(row)}
        ${row.why ? `<span class="trail-why">${escapeHtml(String(row.why))}</span>` : ""}
        ${whyItAsked(row)}${titles}</li>`;
    }
    if (did === "rank") {
      // The order itself, not just how many there were: which record beat
      // which, by what score, and on what word.
      const order = (row.order || []).length
        ? `<ol class="trail-order">${(row.order || []).map((entry) =>
            `<li><span class="trail-score">${Number(entry.score).toFixed(2)}</span>
              ${trailRecord(entry)}
              <span class="muted">${escapeHtml(String(entry.folder || ""))}</span>
              ${entry.why ? `<span class="trail-why">${escapeHtml(String(entry.why))}</span>` : ""}
             </li>`).join("")}</ol>`
        : "";
      return `<li class="trail-rank">${step}<span class="trail-did">rank</span>${cost}
        ${row.candidates} candidates, considering ${row.considering}
        ${order}</li>`;
    }
    const mark = did === "take" ? "take" : (did === "stop" ? "stop" : "skip");
    return `<li class="trail-${mark}">${step}<span class="trail-did">${mark}</span>${cost}
      ${trailRecord(row)}
      ${row.folder ? `<span class="muted">${escapeHtml(String(row.folder))}</span>` : ""}
      ${row.tokens !== undefined
        ? `<span class="trail-count">${row.tokens} tokens, ${row.used} used</span>` : ""}
      ${row.why ? `<span class="trail-why">${escapeHtml(String(row.why))}</span>` : ""}
      </li>`;
  }).join("");
  return `<ol class="beat-trail">${rows}</ol>`;
}

/* Section 37, as amended: this step's own call.

   Each step is now asked on its own, so there is a prompt and an answer that
   belong to it rather than a quarter share of one of each. Both are shown
   closed: the prompt is the instruction, the context and what the earlier
   steps concluded, and the answer is the JSON that produced the outcome
   below it - which is the thing to read when an outcome looks wrong. */
function beatCall(step) {
  const prompt = String(step.prompt || "");
  const answer = String(step.answer || "");
  if (!prompt && !answer) return "";
  const blocked = step.blocked
    ? `<p class="beat-nothing">The model was not available for this step:
        ${escapeHtml(String(step.blocked))}</p>`
    : "";
  const parsed = (step.parsed || []).length
    ? `<span class="muted">answered ${(step.parsed || [])
        .map((key) => escapeHtml(String(key))).join(", ")}</span>`
    : "";
  // "The prompt" is the FIRST message, and for the state step there are
  // several: it is asked, it asks for something, it is asked again with
  // what came back. Labelled as the first, because a reader comparing it
  // against a search further down the trail otherwise concludes that the
  // search happened before the call that decided on it.
  const rounds = (step.trail || []).filter((row) => row.did === "asked").length;
  return `${beatSub(step, "the call for this step",
    rounds > 1 ? ` · ${rounds} rounds` : "")}
    ${blocked}
    <details class="beat-call">
      <summary>the first message it was sent${
        rounds > 1 ? ", before it asked for anything" : ""}
        <span class="muted">${beatSize(step.prompt_tokens, prompt)}</span></summary>
      <div class="beat-context beat-context-all">${escapeHtml(prompt)}</div>
    </details>
    ${answer
      ? `<details class="beat-call">
           <summary>what it answered, in the end
             <span class="muted">${beatSize(step.answer_tokens, answer)}</span>
             ${parsed}</summary>
           <div class="beat-context beat-context-all">${escapeHtml(answer)}</div>
         </details>`
      : ""}`;
}

/* Where a step has got to. The gatherings all finish before the first model
   is asked, so within a second or two of the button every step is showing
   what it found and the wait that remains is the calls, arriving one at a
   time. Without this the panel shows a finished-looking run in which three
   of the steps have simply produced nothing. */
const PHASES = {
  gathered: ["waiting", "beat-phase-waiting"],
  asking: ["asking the model\u2026", "beat-phase-asking"],
  answered: ["", ""],
  blocked: ["the model was away", "beat-phase-blocked"],
};

function beatPhase(step) {
  const [label, className] = PHASES[String(step.phase || "")] || ["", ""];
  if (!label) return "";
  return `<span class="beat-phase ${className}">${escapeHtml(label)}</span>`;
}

function asText(value) {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  return JSON.stringify(value, null, 2);
}

/* ------------------------------------------------------------------ */
/* Section 34.3: the state heartbeat, and the page it is tested from.

   The review that writes states is watched one run at a time, step by
   step. This is watched differently because it does something different:
   it reads every state at once, scores them against each other, and the
   thing a reader needs to judge is not the order events happened in but
   *why these were put together*. So the page is the groups, each opening
   out into the states under it and the words that joined them. */
/* `round` counts the rounds this page has started, so that an answer
   arriving after the round was abandoned can be told from one that is
   still wanted. Emptying the sandbox moves it on; a handler compares
   before it draws anything. Without it, a rehearsal that was given up on
   still posted its three rounds onto the page when the request finally
   returned - describing states that had been deleted a minute earlier. */
const stateBeat = { running: false, following: false, report: null,
                    rehearsal: null, round: 0, opened: new Set(),
                    // A draw held back because the reader is mid-selection,
                    // and whether the listener that releases it is bound.
                    pending: null, watching: false,
                    // The task whose pieces are open under the tree,
                    // and the piece whose to-dos are open under that.
                    openTask: null, openTasks: new Set(),
                    openPieces: new Set(),
                    // How the tasks are ordered: by how soon, by
                    // default, because the question a person opens this
                    // with is what needs doing.
                    sortBy: "urgency",
                    // How much of the calendar the tree shows, in days,
                    // and where the right-hand edge of that window sits.
                    // Null means the most recent thing there is.

                    // How large the tree is painted. 1 is full size.
                    treeZoom: 1,
                    // The last HTML written into the panel, so a redraw
                    // that would change nothing can be skipped.
                    drawn: null,
                    // The tree's viewBox while somebody is looking into
                    // it, and when they last dragged it.
                    zoom: null, dragged: 0 };

/* The tree, drawn as a dendrogram.

   A list of groups has to choose an altitude before it has seen anything,
   which is what a similarity threshold does quietly for every group at
   once. A fortnight on one paper is a handful of sittings on the scripts,
   a few on the figures and two on the letter: one thing at one altitude
   and three at another. The tree does not choose - it holds every
   altitude, and the cut is a line drawn across it.

   Laid out here rather than served as coordinates, because a layout is a
   property of the picture and not of the run: the same tree drawn in a
   narrower window wants different coordinates, and a report carrying
   pixels would have to be re-run to be re-drawn. */
const SB_WIDTH = 900;

/* How tall a row is, by how many there are.

   Every state is drawn. A thousand of them at a readable row height is a
   picture nobody scrolls to the end of, and a thousand collapsed into
   forty summarised ones is the list this was supposed to replace - so the
   rows get shorter and the labels drop away, and what is left is the
   shape, which is what a tree is for. */
function sbRow(count) {
  if (count <= 40) return 16;
  if (count <= 120) return 10;
  if (count <= 300) return 6;
  return 4;
}

/* A colour per group, from the golden angle.

   A fixed palette runs out: how many groups there are is what the run
   found, and the twelfth group would then repeat the first. Stepping the
   hue by 137.5 degrees gives every group a colour as far from its
   neighbours as the ones already taken allow, for any number of them.

   Every group too small to be summarised is the same grey. They are not
   findings, they are what is left over - and a dozen leftovers in a dozen
   colours reads as a dozen findings. */
function sbColour(group, big_enough) {
  if (big_enough === false) return "var(--muted, #8a8a8a)";
  const hue = Math.round((Number(group) || 0) * 137.508) % 360;
  // LIGHTER ON A DARK PAGE. At 48% the blues and purples were close to the
  // dark background and their names could not be read.
  return sbIsDark() ? `hsl(${hue} 70% 70%)` : `hsl(${hue} 62% 42%)`;
}

/* Whether the page is drawn dark: chosen in the page, or the system's. */
function sbIsDark() {
  const chosen = document.documentElement.dataset.theme;
  if (chosen === "dark") return true;
  if (chosen === "light") return false;
  try {
    return window.matchMedia
      && window.matchMedia("(prefers-color-scheme: dark)").matches;
  } catch (whatever) {
    return false;
  }
}

/* Which group each leaf fell into at the cut, and whether it is one the
   run would summarise. The tree is drawn in those colours, so the cut is
   readable as colour and as a line in the same picture. */
function sbGroupOfLeaf(report) {
  const of = new Map();
  const big = new Map();
  (report.communities || []).forEach((group, index) => {
    big.set(index, Boolean(group.big_enough));
    (group.members || []).forEach((member) => of.set(member.id, index));
  });
  return { of, big };
}

/* The whole calendar by when it happened, and what this round used of it.

   The point is the gap between those two. A round reads a window and
   groups some of what it reads: the states outside the window are never
   read, and the ones inside it that matched no task are in none. Neither
   shows up in a list of tasks, and both matter - the first is information
   the grouping will never see, the second is states it had nothing to say
   about. So each column is the states that happened in that stretch, and
   it is drawn in three parts: in a task, read but in none, and not read.

   The numbers are the folder's own. `states_in_all` is every file there
   is, not this round's reading, which is why two rounds an append apart
   show the same columns plus the new ones - and why the totals can be
   checked by counting the folder. */
/* Where the round has got to, while it is getting there.

   The stages are named rather than counted, because "scoring every pair"
   and "summarising task 3 of 8" are different kinds of waiting and a bar
   that only fills up says neither. Each one keeps what it cost, so a
   round that took twenty seconds can be read for where they went - which
   is how the model load turned out to be thirty-four seconds of a
   thirty-four second round. */
/* Take a prompt off the page, whole.

   Reading one on the page is not the same as having it: the thing a
   person does with a prompt that produced an odd summary is paste it
   somewhere and change a line. Selecting sixteen thousand characters out
   of a scrolling `pre` is a minute of dragging that the panel then
   interrupts, and it silently picks up the headings between the two
   halves.

   The button is in the summary, so the prompt can be taken without
   opening the block, which means the click has to be stopped from
   toggling the `details` it sits in. */
function sbCopyButton(what) {
  return `<button type="button" class="small secondary sb-copy"
    data-sb-copy="${escapeHtml(String(what))}"
    title="Copy the whole prompt - the instruction and the message">copy</button>`;
}

/* What the copy takes: the parts marked as the prompt, in the order they
   are on the page, and nothing else.

   Marked rather than "every `pre` in this block", because the block also
   holds what came back, and a button labelled `copy` beside the words
   "the prompt it was sent" must not hand over the model's replies as
   though they were part of it. */
function sbPromptText(host) {
  return [...host.querySelectorAll("[data-sb-part='prompt']")]
    .map((one) => one.textContent)
    .join("\n\n");
}

async function sbCopyThePrompt(button) {
  const block = button.closest("details");
  if (!block) return;
  const said = sbPromptText(block);
  if (!said) return;
  let done = false;
  try {
    await navigator.clipboard.writeText(said);
    done = true;
  } catch (err) {
    // No clipboard permission, or not a secure context. A hidden
    // textarea and the old command still work in both, and a button
    // that silently does nothing is worse than an old API.
    try {
      const box = document.createElement("textarea");
      box.value = said;
      box.setAttribute("readonly", "");
      box.style.position = "fixed";
      box.style.opacity = "0";
      document.body.appendChild(box);
      box.select();
      done = document.execCommand("copy");
      document.body.removeChild(box);
    } catch (also) {
      done = false;
    }
  }
  // Said on the button itself, because a toast somewhere else is a thing
  // to go and find. Put back after a moment, so a redraw that skips
  // because nothing changed cannot leave it reading "copied" for ever.
  const was = button.textContent;
  button.textContent = done
    ? `copied ${said.length.toLocaleString()} chars`
    : "could not copy";
  setTimeout(() => { button.textContent = was; }, 1800);
}

function stateBeatStage(report) {
  const stages = report.stages || [];
  if (!stages.length) return "";
  const running = Boolean(report.running);
  const now = stages[stages.length - 1] || {};
  const spent = stages.reduce((total, one) =>
    total + (Number(one.seconds) || 0), 0);
  return `<div class="sb-stage${running ? " sb-stage-running" : ""}">
    <p class="beat-head-line">
      ${running
        ? `<span class="sb-stage-spinner"></span>
           <strong>${escapeHtml(String(now.stage || ""))}</strong>
           ${now.detail ? `- ${escapeHtml(String(now.detail))}` : ""}`
        : `<strong>Finished</strong> in ${
            ((Number(report.duration_ms) || 0) / 1000).toFixed(1)}s`}
    </p>
    <ol class="sb-stage-list">${stages.map((one, index) => {
      const last = index === stages.length - 1;
      // The step's own instruction, or the round's. It is the same text on
      // every summary of a round and is sent once for that reason; a step
      // carries its own only where it was told something else.
      const instruction = one.instruction || report.instruction || "";
      return `<li class="${running && last ? "sb-stage-now" : ""}">
        <span class="sb-stage-name">${escapeHtml(String(one.stage || ""))}</span>
        <span class="sb-stage-detail">${escapeHtml(String(one.detail || ""))}</span>
        ${one.prompt
          ? `<details class="sb-stage-prompt" data-sb-open="stage-${index}"
               ${stateBeat.opened.has(`stage-${index}`) ? "open" : ""}
               ><summary>the whole prompt${
               Number(one.prompt_tokens || 0)
                 ? ` (${Number(one.prompt_tokens)} tokens: ${
                     Number(one.instruction_tokens || 0)} of instruction,
                     ${Number(one.message_tokens || 0)} of states)` : ""}${
               one.waiting_for ? ` - waiting for ${
                 escapeHtml(String(one.waiting_for))}`
                 : " - sent, and answered"}${
               Number(one.searches || 0) ? ` - after ${
                 Number(one.searches)} search${
                 Number(one.searches) === 1 ? "" : "es"}` : ""}
               ${sbCopyButton(`stage-${index}`)}</summary>
             ${instruction
               ? `<p class="event-label">the instruction, sent as the
                    system prompt on this call - the rules, the output
                    format, and the permission to search</p>
                  <pre class="sb-prompt" data-sb-part="prompt">${
                    escapeHtml(String(instruction))}</pre>`
               : ""}
             <p class="event-label">and the message: the states
               themselves</p>
             <pre class="sb-prompt" data-sb-part="prompt">${
               escapeHtml(String(one.prompt))}</pre></details>`
          : ""}
        <span class="sb-stage-cost">${running && last
          ? "running" : `${(Number(one.seconds) || 0).toFixed(2)}s`}${
          Number(one.calls || 0)
            ? ` · ${one.calls} call${one.calls === 1 ? "" : "s"}, ${
                Number(one.tokens_in || 0) + Number(one.tokens_new || 0)} new${
                Number(one.tokens_cached || 0)
                  ? ` + ${Number(one.tokens_cached)} already cached` : ""} in, ${
                Number(one.tokens_out || 0)} out`
            : ""}</span>
      </li>`;
    }).join("")}</ol>
    ${spent > 0 ? `<p class="muted">${spent.toFixed(1)}s across ${
      stages.length} stage${stages.length === 1 ? "" : "s"}${
      stages.reduce((n, one) => n + Number(one.calls || 0), 0)
        ? `, and ${stages.reduce((n, one) => n + Number(one.calls || 0), 0)}
           model call(s) costing ${
           stages.reduce((n, one) => n + Number(one.tokens_in || 0), 0)} tokens
           in and ${
           stages.reduce((n, one) => n + Number(one.tokens_out || 0), 0)} out`
        : ", with no model call at all"}.</p>` : ""}
  </div>`;
}

function stateBeatOverview(report) {
  const overview = report.overview || {};
  const buckets = overview.buckets || [];
  if (buckets.length < 2) return "";
  const width = SB_WIDTH;
  const rows = (overview.spans || []).length;
  const plot = 132;
  const strip = rows ? rows * 7 + 10 : 0;
  const height = plot + 34 + strip;
  const left = 34;
  const tallest = buckets.reduce((high, one) =>
    Math.max(high, Number(one.states) || 0), 1);
  const step = (width - left - 10) / buckets.length;
  const bar = Math.max(1, step - 1);
  const y = (value) => plot - (Number(value) / tallest) * (plot - 14);

  // Three parts to a column, stacked from the bottom: what a task holds,
  // what was read and joined nothing, and what was never read at all.
  const columns = buckets.map((one, index) => {
    const x = left + index * step;
    const all = Number(one.states) || 0;
    const read = Number(one.read) || 0;
    const held = Number(one.in_tasks) || 0;
    // What THIS round worked on, separated from what earlier rounds put
    // in a task. On an appending round the first is a handful and the
    // second is everything, and showing only the second was showing the
    // window rather than the work.
    const now = Math.min(held, Number(one.this_round) || 0);
    const before = Math.max(0, held - now);
    const loose = Math.max(0, read - held);
    const unread = Math.max(0, all - read);
    const parts = [];
    let bottom = plot;
    const piece = (count, className) => {
      if (count <= 0) return;
      const tall = (count / tallest) * (plot - 14);
      bottom -= tall;
      parts.push(`<rect class="${className}" x="${x.toFixed(1)}"
        y="${bottom.toFixed(1)}" width="${bar.toFixed(1)}"
        height="${tall.toFixed(1)}"></rect>`);
    };
    piece(now, "sb-ov-now");
    piece(before, "sb-ov-held");
    piece(loose, "sb-ov-loose");
    piece(unread, "sb-ov-unread");
    return `<g><title>${escapeHtml(clock(one.from))} - ${
      escapeHtml(clock(one.to))}: ${all} state${all === 1 ? "" : "s"}${
      now ? `, ${now} worked on this round` : ""}, ${
      before} already in a task, ${loose} in none, ${unread} not read</title>
      ${parts.join("")}</g>`;
  }).join("");

  // And the stretch each task drew on, one row each, in its own colour.
  const at = (moment) => {
    const from = new Date(overview.from).getTime();
    const to = new Date(overview.to).getTime();
    const here = new Date(moment).getTime();
    if (!Number.isFinite(here) || to <= from) return left;
    return left + ((here - from) / (to - from)) * (width - left - 10);
  };
  const bands = (overview.spans || []).map((span, index) => {
    const start = at(span.from);
    const end = Math.max(start + 1.5, at(span.to));
    return `<g><title>${escapeHtml(String(span.id || ""))}: ${
      Number(span.size || 0)} states, ${escapeHtml(clock(span.from))} to ${
      escapeHtml(clock(span.to))}</title>
      <rect x="${start.toFixed(1)}" y="${(plot + 26 + index * 7).toFixed(1)}"
        width="${(end - start).toFixed(1)}" height="5" rx="2"
        fill="${sbColour(sbStable(span.id || index), true)}" opacity=".75"></rect></g>`;
  }).join("");

  // The two thresholds that decide what is read, as lines on the same
  // axis. The columns are only the drawing's resolution; these are the
  // reason some of them are faint.
  const limits = overview.limits || {};
  const edge = (moment, className, label) => {
    if (!moment) return "";
    const x = at(moment);
    if (!Number.isFinite(x)) return "";
    return `<g class="${className}"><title>${escapeHtml(label)}</title>
      <line x1="${x.toFixed(1)}" y1="6" x2="${x.toFixed(1)}"
        y2="${plot}"></line>
      <text x="${(x + 3).toFixed(1)}" y="14">${escapeHtml(label)}</text></g>`;
  };
  const edges = [
    edge(limits.by_duration, "sb-ov-edge sb-ov-edge-days",
         `${Number(limits.max_days || 0)} days back`),
    edge(limits.by_count, "sb-ov-edge sb-ov-edge-count",
         `the newest ${Number(limits.max_states || 0)} reach here`),
    // Only on a round that did not work on the whole window: then the
    // line worth drawing is where this round's own states begin.
    limits.worked_on_all_of_it ? "" :
      edge(overview.this_round_from, "sb-ov-edge sb-ov-edge-now",
           `this round's ${Number(overview.this_round || 0)} start here`),
  ].join("");

  const ticks = [0, Math.floor(buckets.length / 2), buckets.length - 1]
    .map((index) => {
      const one = buckets[index];
      if (!one) return "";
      const x = left + index * step + bar / 2;
      return `<text class="sb-ov-tick" x="${x.toFixed(1)}" y="${plot + 14}"
        text-anchor="${index === 0 ? "start"
          : index === buckets.length - 1 ? "end" : "middle"}">${
        escapeHtml(clock(one.from))}</text>`;
    }).join("");

  return `<div class="sb-figure sb-overview">
    <svg viewBox="0 0 ${width} ${height}" class="sb-graph"
      preserveAspectRatio="xMidYMin meet" role="img"
      aria-label="states over time, and which of them this grouping used">
      <line class="sb-ov-axis" x1="${left}" y1="${plot}"
        x2="${width - 10}" y2="${plot}"></line>
      <text class="sb-ov-tick" x="0" y="16">${tallest}</text>
      <text class="sb-ov-tick" x="0" y="${plot}">0</text>
      ${columns}
      ${edges}
      ${ticks}
      ${bands}
    </svg>
    <p class="muted sb-figure-note">
      <strong>${Number(overview.states_in_all || 0)}</strong> states in the
      folder, by when each happened, ${Number(overview.columns || 0)} columns of
      about ${Number(overview.column_hours || 0)} hours.
      <span class="sb-ov-key sb-ov-key-now"></span> worked on by this round
      (${Number(overview.this_round || 0)}),
      <span class="sb-ov-key sb-ov-key-held"></span> already in a task
      (${Math.max(0, Number(overview.in_tasks || 0)
                     - Number(overview.this_round || 0))}),
      <span class="sb-ov-key sb-ov-key-loose"></span> read, offered to every
      task and taken by none
      (${Math.max(0, Number(overview.read || 0) - Number(overview.in_tasks || 0))}),
      <span class="sb-ov-key sb-ov-key-unread"></span> outside the window, so
      never read
      (${Math.max(0, Number(overview.states_in_all || 0) - Number(overview.read || 0))}).
      ${(overview.spans || []).length
        ? `The bars underneath are the stretch each task drew on.` : ""}
      ${(overview.limits || {}).bound_by
        ? `<br><strong>What cut the window:</strong> ${
            escapeHtml(String(overview.limits.bound_by))}.` : ""}
      ${escapeHtml(String(overview.why || ""))}</p>
  </div>`;
}

/* Zooming and moving the tree.

   A hundred states is a hundred rows, and at that size the names are four
   pixels tall and the interesting part - which joins happen left of the
   cut - is a smudge. The picture is an SVG with a `viewBox`, so zooming
   is arithmetic on four numbers and needs no library: narrow the box and
   the browser draws the same lines larger.

   PLAIN SCROLLING IS LEFT ALONE. A figure that swallows the wheel inside
   a page this long is a trap - the reader scrolls past it and instead
   zooms it by accident, and has no way to get out. So the wheel zooms
   only with Ctrl or Command held, which is what a browser's own zoom
   uses and what every map does, and there are buttons for the people who
   will never discover that.

   The box is kept in `stateBeat.zoom` and put back after a redraw, for
   the same reason the open blocks are: a round being followed redraws
   twice a second, and a picture that reset itself while being read would
   be worse than one that could not zoom at all. */
const SB_ZOOM_STEP = 1.35;
const SB_ZOOM_TIGHTEST = 0.02;   // how far in: a fiftieth of the whole

function sbZoomBox(svg) {
  const said = (svg.getAttribute("viewBox") || "").split(/[\s,]+/).map(Number);
  return said.length === 4 && said.every(Number.isFinite)
    ? { x: said[0], y: said[1], w: said[2], h: said[3] } : null;
}

function sbZoomSet(svg, box) {
  const whole = (svg.dataset.sbWhole || "").split(/[\s,]+/).map(Number);
  if (whole.length === 4 && whole.every(Number.isFinite)) {
    // Never smaller than a sliver, and never larger than the whole
    // picture: a box bigger than the drawing is empty space, and one
    // smaller than a few states is a line with no context round it.
    const most = whole[2];
    box.w = Math.min(most, Math.max(most * SB_ZOOM_TIGHTEST, box.w));
    const scale = box.w / most;
    box.h = whole[3] * scale;
    // And it stays over the drawing rather than wandering off it.
    box.x = Math.max(whole[0] - box.w * 0.1,
                     Math.min(whole[0] + most - box.w * 0.9, box.x));
    box.y = Math.max(whole[1] - box.h * 0.1,
                     Math.min(whole[1] + whole[3] - box.h * 0.9, box.y));
  }
  svg.setAttribute("viewBox",
    `${box.x.toFixed(2)} ${box.y.toFixed(2)} ${box.w.toFixed(2)} ${box.h.toFixed(2)}`);
  stateBeat.zoom = svg.getAttribute("viewBox");
  svg.classList.toggle("sb-graph-zoomed",
    Math.abs(box.w - (Number((svg.dataset.sbWhole || "").split(" ")[2]) || box.w))
      > 0.5);
}

/* Zoom about a point, so what is under the pointer stays under it. */
function sbZoomBy(svg, factor, at) {
  const box = sbZoomBox(svg);
  if (!box) return;
  const here = at || { fx: 0.5, fy: 0.5 };
  const onX = box.x + box.w * here.fx;
  const onY = box.y + box.h * here.fy;
  const wide = box.w / factor;
  const tall = box.h / factor;
  sbZoomSet(svg, { x: onX - wide * here.fx, y: onY - tall * here.fy,
                   w: wide, h: tall });
}

function sbZoomWhole(svg) {
  const whole = (svg.dataset.sbWhole || "").split(/[\s,]+/).map(Number);
  if (whole.length !== 4) return;
  svg.setAttribute("viewBox", svg.dataset.sbWhole);
  stateBeat.zoom = null;
  svg.classList.remove("sb-graph-zoomed");
}

/* Where the pointer is in the picture, as a fraction of the box. */
function sbZoomWhere(svg, event) {
  const frame = svg.getBoundingClientRect();
  if (!frame.width || !frame.height) return { fx: 0.5, fy: 0.5 };
  return { fx: (event.clientX - frame.left) / frame.width,
           fy: (event.clientY - frame.top) / frame.height };
}

function sbZoomWire(host) {
  if (host.dataset.sbZoomWired === "1") return;
  host.dataset.sbZoomWired = "1";

  // DRAGGING THE WINDOW BACK THROUGH TIME. The frame scrolls, which
  // moves the canvas; this moves the calendar, which is a different
  // thing - the canvas only ever holds the fortnight on show.
  //
  // Re-rendered on an animation frame rather than on every pointer
  // event: a move fires far faster than a panel this size can be
  // rebuilt, and the queue backs up into treacle.
  // The dates follow the scroll, so they are never the thing that got
  // away. Bound here with the rest of the picture's own handlers.
  host.addEventListener("scroll", (event) => {
    const frame = event.target.closest
      ? event.target.closest(".sb-tree-frame") : null;
    if (!frame) return;
    // Once it has been moved, it is theirs: the opening position is only
    // for a frame nobody has touched.
    frame.dataset.sbPlaced = "1";
    sbPinTheAxis(frame.querySelector(".sb-whole-graph"));
  }, true);

  let panning = null;
  host.addEventListener("pointerdown", (event) => {
    const svg = event.target.closest(".sb-whole-graph");
    if (!svg || event.button !== 0) return;
    // NOT ON SOMETHING THAT IS CLICKED. A press there that started a drag
    // took the pointer for the whole picture, so the click that followed
    // belonged to the picture and not to the row - which is how a project
    // could not be opened by clicking it, anywhere on it.
    if (event.target.closest(
      "[data-sb-task],[data-sb-piece],[data-sb-project],[data-sb-steps-for]")) {
      return;
    }
    const frame = svg.closest(".sb-tree-frame");
    if (!frame) return;
    // DRAGGING MOVES THE VIEW, both ways, the way a hand moves a map -
    // and not the time window, which has its own controls. The canvas
    // is wider than the frame whenever a name is long and taller than
    // it whenever a task is open, so both directions are worth having;
    // reaching for a scrollbar to read a picture is a poor way to read
    // a picture.
    // NO SELECTION DRAG. Holding the button and moving past an edge makes
    // the browser autoscroll the container to that edge, continuously,
    // as part of extending a text selection - which is why the view
    // still shot to the left even with the drag itself frozen: the
    // scrolling was not the drag's doing and ignoring the pointer could
    // not stop it. Refusing the default on the press is what stops a
    // selection from starting at all.
    event.preventDefault();
    panning = {x: event.clientX, y: event.clientY, frame: frame,
               left: frame.scrollLeft, top: frame.scrollTop};
    svg.classList.add("sb-graph-held");
    frame.classList.add("sb-frame-held");
    // Said where every redraw can see it, not just this closure.
    stateBeat.holding = true;
    // So the moves keep coming when the cursor leaves the panel.
    try {
      svg.setPointerCapture(event.pointerId);
      panning.held = {on: svg, id: event.pointerId};
    } catch (_err) {
      /* without capture the drag still works inside the panel, which is
         what it did before. */
    }
  });
  host.addEventListener("pointermove", (event) => {
    if (!panning) return;
    event.preventDefault();
    // OUTSIDE THE FRAME, NOTHING MOVES. Capturing the pointer keeps the
    // events arriving when the cursor leaves, which is what makes a drag
    // survive the edge - but the position in those events is outside the
    // picture, and a drag measured against it is measured against
    // somewhere the reader cannot see. Dragging out past the left edge
    // produced a jump to the far end, and a pixel of movement out there
    // then swept the whole view.
    //
    // So while the cursor is away the view holds still, and the drag
    // RE-BASES when it comes back: the pointer's new position is taken as
    // the new origin against the scroll as it stands, so returning
    // continues from where it froze instead of leaping by everything
    // that happened in between.
    const box = panning.frame.getBoundingClientRect();
    const inside = event.clientX >= box.left && event.clientX <= box.right
      && event.clientY >= box.top && event.clientY <= box.bottom;
    if (!inside) {
      panning.away = true;
      return;
    }
    if (panning.away) {
      panning.away = false;
      panning.x = event.clientX;
      panning.y = event.clientY;
      panning.left = panning.frame.scrollLeft;
      panning.top = panning.frame.scrollTop;
      return;
    }
    panning.frame.scrollLeft = panning.left - (event.clientX - panning.x);
    panning.frame.scrollTop = panning.top - (event.clientY - panning.y);
  });
  const letGoOfTime = () => {
    stateBeat.holding = false;
    document.querySelectorAll(".sb-frame-held").forEach(
      (one) => one.classList.remove("sb-frame-held"));
    if (!panning) return;
    if (panning.held) {
      try {
        panning.held.on.releasePointerCapture(panning.held.id);
      } catch (_err) {
        /* already released, or the element is gone with a redraw. */
      }
    }
    host.querySelectorAll(".sb-graph-held").forEach(
      (one) => one.classList.remove("sb-graph-held"));
    panning = null;
  };
  // A DRAG ENDS WHEN THE BUTTON IS RELEASED, AND NOT BEFORE. Leaving the
  // panel with the button still down used to end it, which is the
  // opposite of how dragging works everywhere else: a hand that moves
  // off the edge of a map has not let go of the map. The pointer is
  // captured instead, so the moves keep arriving while the cursor is
  // outside and the picture follows it back in.
  //
  // Still listening on the window for the release: with capture the
  // events come to the captured element, but a release that happens
  // after the element has been replaced by a redraw would otherwise
  // never be heard, and the picture would stay stuck to the cursor.
  host.addEventListener("pointerup", letGoOfTime);
  host.addEventListener("pointercancel", letGoOfTime);
  window.addEventListener("pointerup", letGoOfTime);

  // Ctrl and + or - over the picture. Bound on the document because a
  // key event goes to whatever has focus and an SVG usually has none;
  // held to the picture by asking whether the pointer is over it, so a
  // reader who wanted the browser's own zoom still gets it everywhere
  // else on the page.
  let over = false;
  host.addEventListener("pointerover", (event) => {
    over = Boolean(event.target.closest(".sb-tree-frame"));
  });
  host.addEventListener("pointerout", (event) => {
    if (!event.relatedTarget
        || !event.relatedTarget.closest
        || !event.relatedTarget.closest(".sb-tree-frame")) over = false;
  });
  // Ctrl and the wheel over the picture. This is the one that works:
  // Ctrl with + or - is a browser accelerator that a page cannot
  // reliably cancel, while Ctrl with the wheel is an ordinary wheel
  // event and stops where it is told. The keys are still bound below
  // for the browsers that do let them through, and the buttons are
  // there for everyone.
  host.addEventListener("wheel", (event) => {
    const svg = event.target.closest(".sb-whole-graph");
    if (!svg || !(event.ctrlKey || event.metaKey)) return;
    event.preventDefault();
    sbZoomTreeBy(event.deltaY < 0 ? 1.15 : 1 / 1.15);
  }, { passive: false });

  document.addEventListener("keydown", (event) => {
    if (!over || !(event.ctrlKey || event.metaKey)) return;
    if (event.key === "+" || event.key === "=") {
      event.preventDefault();
      sbZoomTreeBy(1.25);
    } else if (event.key === "-" || event.key === "_") {
      event.preventDefault();
      sbZoomTreeBy(1 / 1.25);
    } else if (event.key === "0") {
      event.preventDefault();
      stateBeat.treeZoom = 1;
      renderStateBeat();
    }
  });

  // The buttons are wired HERE and not among the page's other click
  // handlers. Those are attached once when the tab is built; this runs
  // whenever the panel is drawn, so the controls work in any context the
  // figure is drawn in - including a test that renders the panel and
  // never builds the tab.
  host.addEventListener("click", (event) => {
    const zoomer = event.target.closest("[data-sb-zoom]");
    if (!zoomer) return;
    event.preventDefault();
    event.stopPropagation();
    const figure = zoomer.closest(".sb-figure");
    const svg = figure && figure.querySelector(".sb-graph[data-sb-whole]");
    if (!svg) return;
    const what = zoomer.dataset.sbZoom;
    if (what === "reset") sbZoomWhole(svg);
    else sbZoomBy(svg, what === "in" ? SB_ZOOM_STEP : 1 / SB_ZOOM_STEP);
  });

  host.addEventListener("wheel", (event) => {
    const svg = event.target.closest(".sb-graph[data-sb-whole]");
    // Without the modifier this is ordinary scrolling and is not ours.
    if (!svg || !(event.ctrlKey || event.metaKey)) return;
    event.preventDefault();
    sbZoomBy(svg, event.deltaY < 0 ? SB_ZOOM_STEP : 1 / SB_ZOOM_STEP,
             sbZoomWhere(svg, event));
  }, { passive: false });

  let dragging = null;
  host.addEventListener("pointerdown", (event) => {
    const svg = event.target.closest(".sb-graph[data-sb-whole]");
    if (!svg || event.button !== 0) return;
    const box = sbZoomBox(svg);
    if (!box) return;
    dragging = { svg: svg, box: box, x: event.clientX, y: event.clientY,
                 moved: false };
    svg.classList.add("sb-graph-held");
  });
  host.addEventListener("pointermove", (event) => {
    if (!dragging) return;
    const frame = dragging.svg.getBoundingClientRect();
    if (!frame.width) return;
    const acrossX = (event.clientX - dragging.x) / frame.width * dragging.box.w;
    const acrossY = (event.clientY - dragging.y) / frame.height * dragging.box.h;
    if (Math.abs(event.clientX - dragging.x) > 3
        || Math.abs(event.clientY - dragging.y) > 3) {
      dragging.moved = true;
    }
    sbZoomSet(dragging.svg, { x: dragging.box.x - acrossX,
                              y: dragging.box.y - acrossY,
                              w: dragging.box.w, h: dragging.box.h });
  });
  const letGo = (event) => {
    if (!dragging) return;
    dragging.svg.classList.remove("sb-graph-held");
    // A drag that moved must not also open the state it started on.
    if (dragging.moved) stateBeat.dragged = Date.now();
    dragging = null;
  };
  host.addEventListener("pointerup", letGo);
  host.addEventListener("pointerleave", letGo);
  host.addEventListener("pointercancel", letGo);
}

/* What was put together before anything was scored, and what the tree
   then did with it.

   Two phases, and the page has to show both or the grouping looks like
   one step that produced an answer. First: states that were open on the
   same file or the same page are joined outright, because what a state
   was open on is a stronger signal than what it says - a description is
   the model's paraphrase of a quarter of an hour, and a path is the same
   string every time or it is absent. Then the tree runs with those
   already joined, so an anchor is one leaf's worth of the picture rather
   than eight.

   The third thing shown here is the one that decides nothing: a shared
   FOLDER, which shortens a distance and leaves the splitting to the rule
   that does that. `Research/AA/BB` and `Research/AA/CC` may be one task
   with two parts or two papers on one shelf, and the path cannot say. */
function stateBeatAnchors(report) {
  const held = (report.similarity || {}).anchored;
  if (!held || !held.of) return "";
  const anchors = held.anchors || [];
  const worded = held.by_word || [];
  const words = held.words || {};
  const pulls = held.pulls || [];
  const named = Number(held.named || 0);
  const of = Number(held.of || 0);
  // Which task each state ended in, so an anchor can say whether it
  // survived the clustering - an anchor that came apart across two tasks
  // is the one thing this must not do, and it should be visible rather
  // than assumed.
  const taskOf = new Map();
  (report.layers || []).forEach((task) => {
    const walk = (one) => {
      (one.states || []).forEach((id) => taskOf.set(String(id), task.id));
      (one.children || []).forEach(walk);
    };
    walk(task);
  });

  return `<details class="sb-anchors" data-sb-open="anchors">
    <summary><strong>What was anchored, before anything was scored</strong>
      <span class="muted">${anchors.length + worded.length} anchor${
        anchors.length + worded.length === 1 ? "" : "s"} over ${
        [...anchors, ...worded].reduce(
          (n, one) => n + Number(one.states || 0), 0)} states
        &middot; ${anchors.length} by what was open, ${
        worded.length} by rare words
        &middot; ${named} of ${of} states name a file or a page
        &middot; ${Number(held.pulled || 0)} pair${
          Number(held.pulled || 0) === 1 ? "" : "s"} drawn nearer by a
        shared folder</span></summary>

    <p class="muted">${escapeHtml(String(held.why || ""))}</p>

    ${anchors.length
      ? `<h4>Joined by what was open - the same file, the same page</h4>
         <p class="muted">A path is not a paraphrase. Two states naming
           one file are on one piece of work whatever either of them says
           about it, so these are put together before any pair is
           scored.</p>
         ${anchors.map((one) => {
           const tasks = [...new Set((one.ids || [])
             .map((id) => taskOf.get(String(id)))
             .filter(Boolean))];
           return `<div class="sb-anchor">
             <div class="sb-anchor-on"><code>${escapeHtml(
               String((one.on || [])[0] || ""))}</code>
               <span class="muted">${Number(one.states || 0)} states</span>
               ${tasks.length === 1
                 ? `<span class="badge">all of them in ${
                     escapeHtml(String(tasks[0]).split("_").join(" "))}</span>`
                 : tasks.length > 1
                   ? `<span class="badge sb-not-shown">split across ${
                       tasks.length} tasks - an anchor should not come
                       apart</span>`
                   : `<span class="muted">not in any task</span>`}</div>
             <ul class="sb-anchor-states">${(one.titles || []).map((title) =>
               `<li>${escapeHtml(String(title))}</li>`).join("")}</ul>
           </div>`;
         }).join("")}`
      : `<p class="muted">Nothing was joined by what was open. Either no
           two states named the same file or page, or the ones that did
           named something so common it is where the work lives rather
           than what it is.</p>`}

    ${worded.length
      ? `<h4>Joined by rare words they share</h4>
         <p class="muted">The second kind, over the states the first left
           alone - work with no file and no page still says "FieldNotes"
           or "survey-weights" over and over. This is not what the
           embedding does: the vectors are trained to know that "paper"
           and "manuscript" mean the same, which is the opposite of what
           is wanted for a proper noun, whose whole value is that nothing
           else is called that. Each of these shares at least ${
           Number(words.must_share || 0)} words that ${
           Number(words.rare_under || 0)} states or fewer use.</p>
         ${worded.map((one) => {
           const tasks = [...new Set((one.ids || [])
             .map((id) => taskOf.get(String(id))).filter(Boolean))];
           return `<div class="sb-anchor sb-anchor-words">
             <div class="sb-anchor-on">${(one.on || []).map((word) =>
               `<code>${escapeHtml(String(word))}</code>`).join(" ")}
               <span class="muted">${Number(one.states || 0)} states</span>
               ${tasks.length === 1
                 ? `<span class="badge">all of them in ${
                     escapeHtml(String(tasks[0]).split("_").join(" "))}</span>`
                 : tasks.length > 1
                   ? `<span class="badge sb-not-shown">split across ${
                       tasks.length} tasks - an anchor should not come
                       apart</span>`
                   : ""}</div>
             <ul class="sb-anchor-states">${(one.titles || []).map((title) =>
               `<li>${escapeHtml(String(title))}</li>`).join("")}</ul>
           </div>`;
         }).join("")}`
      : `<p class="muted">Nothing was joined by rare words${
          Number(words.considered || 0)
            ? ` among the ${Number(words.considered)} states the first kind
                left alone` : ""}.${Number(words.refused || 0)
            ? ` ${Number(words.refused)} group${
                Number(words.refused) === 1 ? " was" : "s were"} refused for
                having no word in common across all of ${
                Number(words.refused) === 1 ? "its" : "their"} members - a
                chain rather than a subject.` : ""}</p>`}

    ${pulls.length
      ? `<h4>Drawn nearer - under the same folder, but not the same thing</h4>
         <p class="muted">These were not joined. A shared folder is
           evidence and not proof, so it shortens the distance and leaves
           the question of whether they are one task to the splitting
           rule.</p>
         <p class="muted">"How far apart" is the number the tree works
           on: 0 means the vectors say these are the same thing, 1 means
           they have nothing in common. The tree joins the nearest pair
           first and repeats, so shortening a distance does not join
           anything - it moves the pair earlier in the queue, and the
           splitting rule still decides whether what they land in is one
           task or two.</p>
         <table class="sb-compare-table"><thead><tr>
           <th>two states</th><th>under the same</th>
           <th>how far apart, before &rarr; after</th>
         </tr></thead><tbody>${pulls.map((one) => `<tr>
           <td>${escapeHtml(String(one.a_title || one.a))}<br>
             <span class="muted">${escapeHtml(
               String(one.b_title || one.b))}</span></td>
           <td><code>${escapeHtml(String((one.under || [])[0] || ""))}</code>
             <span class="muted">${Math.round(Number(one.share || 0) * 100)}%
               of the path</span></td>
           <td>${Number(one.was).toFixed(2)} &rarr;
             <strong>${Number(one.now).toFixed(2)}</strong></td>
         </tr>`).join("")}</tbody></table>`
      : ""}

    ${named < of
      ? `<p class="muted"><strong>${of - named} state${
          of - named === 1 ? "" : "s"} named no file and no page</strong>, so
          took no part in this: they were grouped on what they say alone.
          Two states that both name nothing have nothing in common, and
          letting them anchor would put everything the listener could not
          see into one task.</p>`
      : ""}
  </details>`;
}

function stateBeatTree(report) {
  const tree = report.tree || {};
  const leaves = tree.leaves || [];
  const merges = tree.merges || [];
  const labels = tree.labels || [];
  if (leaves.length < 2) return "";
  const states = new Map((report.states || []).map((state) => [state.id, state]));
  const { of, big } = sbGroupOfLeaf(report);
  const row = sbRow(leaves.length);
  const named = row >= 10;
  const gutter = named ? 330 : 14;
  const height = leaves.length * row + 34;
  const width = SB_WIDTH;
  const tallest = merges.reduce((high, merge) =>
    Math.max(high, Number(merge.height) || 0), 0.0001);
  // Leaves on the left at distance zero, the root on the right at the
  // tallest join. Horizontal rather than vertical because the labels are
  // sentences: a vertical dendrogram would write them sideways.
  const x = (distance) => gutter + (Number(distance) / tallest)
    * (width - gutter - 18);
  const at = new Map();
  leaves.forEach((leaf, index) => {
    at.set(leaf, { x: gutter, y: 18 + index * row + row / 2,
                   group: of.get(labels[leaf]) });
  });
  const lines = [];
  merges.forEach((merge, index) => {
    const left = at.get(merge.left);
    const right = at.get(merge.right);
    if (!left || !right) return;
    const join = x(merge.height);
    // One group's colour while both halves are in it, grey once the join
    // crosses the cut - so the eye can see which joins the cut kept.
    const same = left.group !== undefined && left.group === right.group;
    const colour = same ? sbColour(left.group, big.get(left.group))
                        : "var(--line, rgba(127,127,127,.45))";
    lines.push(`<path d="M${left.x.toFixed(1)} ${left.y.toFixed(1)}
      H${join.toFixed(1)} V${right.y.toFixed(1)} H${right.x.toFixed(1)}"
      class="sb-branch" stroke="${colour}"><title>${escapeHtml(
        `joined at ${Number(merge.height).toFixed(2)} - ${merge.size} states`)
      }</title></path>`);
    at.set(labels.length + index, {
      x: join, y: (left.y + right.y) / 2,
      group: same ? left.group : undefined,
    });
  });
  const marks = leaves.map((leaf) => {
    const point = at.get(leaf);
    const id = labels[leaf];
    const state = states.get(id) || {};
    const colour = sbColour(point.group, big.get(point.group));
    const title = String(state.title || id || "");
    return `<g class="sb-leaf" data-sb-node="${escapeHtml(String(id || ""))}"
      tabindex="0" role="button">
      <circle cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}"
        r="${(row >= 10 ? 3.4 : 2).toFixed(1)}" fill="${colour}"/>
      ${named
        ? `<text x="${(point.x - 8).toFixed(1)}" y="${(point.y + 3.5).toFixed(1)}"
           text-anchor="end" fill="${colour}" class="sb-leaf-text">${
           escapeHtml(title.length > 52 ? title.slice(0, 51) + "\u2026" : title)
           }</text>`
        : ""}
      <title>${escapeHtml(title + " - click to open")}</title>
    </g>`;
  }).join("");
  const cutAt = Number(tree.cut_at);
  const cut = Number.isFinite(cutAt) && cutAt <= tallest
    ? `<line x1="${x(cutAt).toFixed(1)}" y1="6" x2="${x(cutAt).toFixed(1)}"
       y2="${(height - 16).toFixed(1)}" class="sb-cut"><title>${escapeHtml(
       `the cut, at a distance of ${cutAt.toFixed(2)}`)}</title></line>
       <text x="${(x(cutAt) + 4).toFixed(1)}" y="14" class="sb-cut-text">cut at ${
       cutAt.toFixed(2)}</text>`
    : "";
  const keys = (report.communities || []).slice(0, 14).map((group, index) =>
    `<span class="sb-key"><i style="background:${
      sbColour(index, Boolean(group.big_enough))}"></i>${
      escapeHtml(String(group.id || "").split("_").join(" "))} ·
      ${Number(group.size || 0)} states${
      group.big_enough ? "" : " · too small"}</span>`).join("");
  const more = (report.communities || []).length > 14
    ? `<span class="muted">and ${(report.communities || []).length - 14}
       more groups</span>` : "";
  const whole = `0 0 ${width} ${height}`;
  return `<div class="sb-figure">
    <div class="sb-zoom-bar">
      <span class="muted">A hundred states in a tree is a tall picture and
        the names are small. Drag to move it${
        ""}; hold Ctrl (or &#8984;) and scroll to zoom, or use these.</span>
      <button type="button" class="small secondary" data-sb-zoom="out"
        title="Zoom out">&minus;</button>
      <button type="button" class="small secondary" data-sb-zoom="in"
        title="Zoom in">+</button>
      <button type="button" class="small secondary" data-sb-zoom="reset"
        title="Show the whole tree again">fit</button>
    </div>
    <div class="sb-zoom-frame">
    <svg viewBox="0 0 ${width} ${height}" class="sb-graph"
      data-sb-whole="${whole}"
      preserveAspectRatio="xMidYMin meet" role="img"
      aria-label="the states as a tree, nearest pair joined first">
      <g class="sb-branches">${lines.join("")}</g>
      ${cut}
      <g class="sb-leaves">${marks}</g>
    </svg>
    </div>
    <div class="sb-keys">${keys}${more}</div>
    <p class="muted sb-figure-note">One leaf per state. Two states join
      where they are alike enough, and the further right a join is, the
      less the two halves had in common - so a tall narrow bracket on the
      left is a thing done repeatedly, and everything meeting at the right
      edge only meets because the tree has to end somewhere.
      ${named ? "Click a leaf" : "Click a point"} to open the state.
      Colour is the group the cut leaves it in; grey is a group too small
      to summarise.${(report.continuity && !report.continuity.rebuilt)
        ? ` This picture was drawn ${tree.as_of
             ? `at the last rebuild, ${escapeHtml(clock(tree.as_of))}`
             : "at the last rebuild"} and is not redrawn on a round that only
           appends: joining every state to every other is the work that
           appending exists to avoid. The colours are the tasks as they stand
           now, so a state that has joined a task since is coloured for it
           without having moved on the page.` : ""}</p>
    ${stateBeatHow(report)}
  </div>`;
}

/* How an edge is weighed and how the groups are found, in words.

   Beside the picture rather than in the documentation, because this is
   where somebody is standing when they ask why two states are joined -
   and the text comes from the run, built from the settings it actually
   used, so it cannot describe last month's formula. */
function stateBeatHow(report) {
  const how = report.how || {};
  if (!(how.steps || []).length && !how.clustering) return "";
  const row = (label, text) => text
    ? `<div class="sb-how-row"><span class="event-label">${label}</span>
       <span>${escapeHtml(String(text))}</span></div>` : "";
  const steps = (how.steps || []).map((step) =>
    `<li>${escapeHtml(String(step))}</li>`).join("");
  return `<details data-sb-open="how" class="sb-how">
    <summary class="muted">how two states are compared, and how the tree is built</summary>
    ${steps
      ? `<div class="sb-how-row"><span class="event-label">How the tree is
         built, step by step</span><ol class="sb-steps">${steps}</ol></div>`
      : ""}
    ${stateBeatWorked(report)}
    ${(how.parameters || []).length
      ? `<div class="sb-how-row"><span class="event-label">The numbers, and
         why they are those numbers</span>
         <ul class="sb-parameters">${(how.parameters || []).map((one) =>
           `<li><span class="sb-parameter-name">${escapeHtml(String(one.name))}</span>
            <code class="sb-term">${escapeHtml(String(one.value))}</code>
            <div class="sb-parameter-why">${escapeHtml(String(one.why))}</div>
            </li>`).join("")}</ul></div>`
      : ""}
    ${row("What reads them", how.reading)}
    ${row("Clustering", how.clustering)}
    ${row("Drawing", how.layout)}
    ${row("Summaries", how.summarised)}
  </details>
  ${stateBeatInstruction(report)}`;
}

/* The same measurement, done once on two real states from this run.

   A method is a claim about what the numbers would be; this is the
   numbers. Somebody deciding where to cut cannot do that from "cosine of
   two embeddings" - they can do it from two titles they recognise, the
   0.93 between them, and the height they were joined at. */
function stateBeatWorked(report) {
  const pair = ((report.similarity || {}).pairs || [])[0];
  if (!pair) return "";
  const source = String((report.similarity || {}).source || "");
  const threshold = Number((report.settings || {}).threshold || 0);
  const read = source === "embedding"
    ? `each state's title and detail read by
       <code>${escapeHtml(String((report.similarity || {}).model || ""))}</code>
       into 384 numbers`
    : "the words of each state's title and detail";
  const joined = Number(pair.score) >= threshold;
  return `<div class="sb-how-row"><span class="event-label">The same
    measurement, on two states from this run</span>
    <div class="sb-worked-pair">
      <div><span class="muted">one</span> ${
        escapeHtml(String(pair.a_title || ""))}</div>
      <div><span class="muted">the other</span> ${
        escapeHtml(String(pair.b_title || ""))}</div>
    </div>
    <ul class="sb-worked">
      <li><div class="sb-worked-line"><span class="muted">read as</span>
        ${read}</div></li>
      <li><div class="sb-worked-line"><span class="muted">alike</span>
        <strong>${Number(pair.score).toFixed(2)}</strong> of 1</div></li>
      <li><div class="sb-worked-line"><span class="muted">apart</span>
        1 &minus; ${Number(pair.score).toFixed(2)} =
        <strong>${Number(pair.distance).toFixed(2)}</strong>, which is the
        height they are joined at in the tree</div></li>
      <li><div class="sb-worked-line muted">${
        joined ? "Inside" : "Outside"} the cut at ${threshold.toFixed(2)}, so
        the two are ${joined ? "in one group" : "in different groups"} until
        the tree joins them higher up.</div></li>
      ${(pair.shared_said || []).length
        ? `<li><div class="sb-worked-line"><span class="muted">words in
           common</span> ${(pair.shared_said || []).map((word) =>
             `<code class="sb-term">${escapeHtml(String(word))}</code>`).join(" ")}
           <span class="muted">(not what decided it${
             source === "embedding" ? ", but worth seeing" : ""})</span></div></li>`
        : ""}
    </ul></div>`;
}

/* What the reader had opened, before the page is rebuilt.

   The panel follows a round by redrawing every four hundred milliseconds,
   and redrawing replaces the HTML - so every `details` the reader had
   opened closed again under their hands, about twice a second. Reading
   the open ones back out of the page first and putting them back
   afterwards is the whole fix; it works for blocks that did not exist
   when they were opened too, which is why the key is on the element
   rather than held in a list somewhere. */
/* Where each picture was scrolled to, kept across a redraw.

   A round is minutes and the panel redraws every time a name lands, so
   this is paid several times a minute while somebody is reading. Without
   it every redraw put them back at the beginning of a drawing they had
   dragged halfway across - which is worse than not updating at all,
   because the reader loses their place as a reward for watching.

   Remembered per frame rather than globally: the overview and the
   debugger draw the same tasks and are scrolled independently. */
function sbWhereItWas() {
  const held = {};
  document.querySelectorAll("[data-sb-frame]").forEach((frame) => {
    held[sbFrameKey(frame)] = {left: frame.scrollLeft,
                               top: frame.scrollTop};
  });
  return held;
}

/* WHICH frame, not only what it is called.

   The overview and the debugger draw the tree with the same function,
   so both frames are called "whole-tree" - and the note above said they
   were remembered separately while the key said otherwise. Remembering
   both under one name kept whichever came last on the page. A sort
   redraws the debugger first, with its frame at the far left, so the
   overview was then "put back" to the debugger's position: parked in the
   middle at 364, sorted, and back at 0. The panel the frame sits in is
   part of its name now. */
function sbFrameKey(frame) {
  const host = frame.closest("#ov-tasks, #dbg-statebeat-body");
  return `${host ? host.id : "page"}:${frame.dataset.sbFrame}`;
}

/* Where a picture opens: at the most recent end.

   EVERY CIRCLE AND EVERY NAME IS AT THE RIGHT-HAND END OF ITS LINE,
   because a reader scanning this wants what is happening NOW and the
   history trails back behind it. The frame, though, opens where any
   scrollable thing opens: at the left. On a calendar of any length that
   means the drawing is wider than the frame and the part on screen is
   the oldest stretch of it - all spans, no circles, no names, nothing
   that pulses.

   Measured in the running agent: a frame 835 pixels wide showing a
   drawing 2987 wide, scrolled to 0, with the first disc at x=1042. The
   working task was there and marked the whole time, a third of a screen
   past the right edge.

   So a frame that has not been scrolled by the reader opens at the end.
   Once they have moved it, their position is what is kept. */
/* WHERE THE MOST RECENT TASKS ARE, not the far right-hand end.

   The far end is past the newest disc by the width of its name, so the
   frame opened on one or two discs and a stretch of words, with the rest
   of what is going on just off to the left. It now opens on the stretch
   of the frame's width that holds the most discs, and of stretches that
   hold as many, the most recent - with a little room on the right for
   the newest one's name. */
function sbWhereMostAre(frame, most) {
  const svg = frame.querySelector("svg");
  const base = svg ? Number(svg.dataset.sbBaseWide || 0) : 0;
  if (!svg || !base) return most;
  const scale = svg.getBoundingClientRect().width / base || 1;
  const xs = [...svg.querySelectorAll("[data-sb-disc]")]
    .map((one) => Number(one.dataset.sbDisc) * scale)
    .filter(Number.isFinite).sort((a, b) => a - b);
  if (!xs.length) return most;
  const seen = frame.clientWidth;
  const roomForAName = Math.min(seen * 0.25, 180);
  let best = -1;
  let bestRight = xs[xs.length - 1];
  let from = 0;
  for (let to = 0; to < xs.length; to += 1) {
    while (xs[to] - xs[from] > seen - roomForAName - 24) from += 1;
    const holds = to - from + 1;
    if (holds >= best) {            // ties go to the later stretch
      best = holds;
      bestRight = xs[to];
    }
  }
  const left = bestRight + roomForAName - seen;
  return Math.max(0, Math.min(most, Math.round(left)));
}

/* THE TASK GOING ON NOW, ITS NAME AND WHAT IT IS, IN THE MIDDLE - on the
   Overview, where the page is opened to see what one is in the middle of.
   Opened on the stretch with the most circles, the newest one's name and
   description were still off to the right, a drag away. The current task
   is the newest one still open (the right-most circle not finished) - or
   the newest of all when every one is finished; centred on its circle and
   its words together, across and, where the frame scrolls, down. False
   when there is no task to centre. */
function sbCentreTheCurrent(frame) {
  const nodes = [...frame.querySelectorAll(".sb-tt-node")];
  const xOf = (node) => Number(node.querySelector("[data-sb-disc]")?.dataset.sbDisc);
  const newest = (list) => list.filter((node) => Number.isFinite(xOf(node)))
    .sort((a, b) => xOf(b) - xOf(a))[0];
  const current = newest(nodes.filter((node) => !node.classList.contains("sb-tt-done")))
    || newest(nodes);
  if (!current) return false;
  const parts = [...current.querySelectorAll(".sb-tt-disc, .sb-tt-name, .sb-tt-aside")]
    .map((one) => one.getBoundingClientRect())
    .filter((box) => box.width || box.height);
  if (!parts.length) return false;
  const left = Math.min(...parts.map((box) => box.left));
  const right = Math.max(...parts.map((box) => box.right));
  const top = Math.min(...parts.map((box) => box.top));
  const bottom = Math.max(...parts.map((box) => box.bottom));
  const seen = frame.getBoundingClientRect();
  frame.scrollLeft += (left + right) / 2 - (seen.left + seen.width / 2);
  frame.scrollTop += (top + bottom) / 2 - (seen.top + seen.height / 2);
  return true;
}

/* Every time the Overview is opened - not on its redraws, which keep where
   the reader has moved it. */
function ovCentreTheCurrent() {
  requestAnimationFrame(() => {
    document.querySelectorAll("#ov-tasks [data-sb-frame]").forEach((frame) => {
      if (sbCentreTheCurrent(frame)) frame.dataset.sbPlaced = "1";
    });
  });
}

function sbOpenAtTheEnd(host, had) {
  if (!host) return;
  host.querySelectorAll("[data-sb-frame]").forEach((frame) => {
    // ONLY A FRAME NOBODY HAS SEEN BEFORE. The mark was kept on the
    // element, and the element is replaced on every redraw - so every
    // redraw thought it was the first and threw the view back to the
    // right-hand end, several times a minute, while somebody was reading
    // the left of it. `had` is where the frames were a moment ago: a
    // frame in it is one that already existed and already has a
    // position, which `sbPutItBack` has just restored.
    if (had && Object.prototype.hasOwnProperty.call(had,
                                                    sbFrameKey(frame))) {
      return;
    }
    if (frame.dataset.sbPlaced === "1") return;
    if (frame.closest("#ov-tasks") && sbCentreTheCurrent(frame)) {
      frame.dataset.sbPlaced = "1";
      return;
    }
    const most = Math.max(0, frame.scrollWidth - frame.clientWidth);
    if (!most) return;
    frame.scrollLeft = sbWhereMostAre(frame, most);
    frame.dataset.sbPlaced = "1";
  });
}

function sbPutItBack(held) {
  if (!held) return;
  document.querySelectorAll("[data-sb-frame]").forEach((frame) => {
    const was = held[sbFrameKey(frame)];
    if (!was) return;
    // Only if there is still somewhere to scroll to. A drawing that grew
    // shorter would otherwise be left scrolled past its own end.
    frame.scrollLeft = Math.min(was.left,
      Math.max(0, frame.scrollWidth - frame.clientWidth));
    frame.scrollTop = Math.min(was.top,
      Math.max(0, frame.scrollHeight - frame.clientHeight));
  });
}

function stateBeatRemember() {
  const host = $("#dbg-statebeat-body");
  // ONLY WHAT IS ON SCREEN. The same keys are used by the Summary tab's
  // copy of a card; read from this panel while it was hidden, its stale,
  // shut sections marked as shut the ones being read over there.
  if (!host || !host.getClientRects().length) return;
  host.querySelectorAll("details[data-sb-open]").forEach((one) => {
    const key = one.dataset.sbOpen;
    if (!key) return;
    if (one.open) {
      stateBeat.opened.add(key);
      stateBeat.opened.delete(`shut:${key}`);
    } else {
      stateBeat.opened.delete(key);
      // Remembered as deliberately shut, because some blocks open by
      // default: without this, closing one of those reopened it on the
      // next redraw, which is the same complaint the other way round.
      stateBeat.opened.add(`shut:${key}`);
    }
  });
}

function stateBeatRestore(where) {
  sbPutItBack(where);
  // IN BOTH PLACES A CARD IS DRAWN: this panel and the Summary tab. Only
  // this panel's were put back, so on the Summary tab "Where the work is"
  // shut itself on every redraw while it was being read.
  $$("#dbg-statebeat-body details[data-sb-open], #ov-tasks details[data-sb-open]")
    .forEach((one) => {
      const key = one.dataset.sbOpen;
      if (!key) return;
      if (stateBeat.opened.has(`shut:${key}`)) one.open = false;
      else if (stateBeat.opened.has(key)) one.open = true;
    });
  const host = $("#dbg-statebeat-body");
  if (!host) return;
  // And where the tree was zoomed to. A round being followed redraws
  // twice a second, and a picture that reset itself while being read
  // would be worse than one that could not zoom at all.
  if (stateBeat.zoom) {
    const svg = host.querySelector(".sb-graph[data-sb-whole]");
    if (svg && svg.dataset.sbWhole !== stateBeat.zoom) {
      svg.setAttribute("viewBox", stateBeat.zoom);
      svg.classList.add("sb-graph-zoomed");
    }
  }
  sbZoomWire(host);
  // A round being followed redraws twice a second. The opened task is
  // in `stateBeat`, so it survives - laid out in place, without the
  // movement, which is right: the movement says "this came from the
  // thing you clicked" and nothing was clicked.
  sbOpenAtTheEnd(host, where);
  if (stateBeat.openTask) {
    const svg = host.querySelector(".sb-whole-graph");
    if (svg) {
      sbUnfold(svg, stateBeat.report || {},
               stateBeat.openTasks instanceof Set
                 ? stateBeat.openTasks : stateBeat.openTask);
    }
  }
}

/* Write the panel, but only when writing it changes something.

   A round is followed by asking every four hundred milliseconds and
   drawing what comes back, which is right for a progress bar and was
   quietly hostile to the one thing this page is for: reading the prompt.
   The prompt is shown BEFORE the answer arrives - that is the whole point
   of it - so the reader is looking at it during exactly the seconds the
   panel is redrawing itself, and replacing the HTML destroys the
   selection. Text could not be copied out of this page at all while a
   round ran.

   Two rules fix it, in this order.

   NOTHING CHANGED, NOTHING WRITTEN. Most of those polls return the same
   report: a summary takes ten or fifteen seconds and the step list does
   not move between them, so the great majority of the redraws were
   rewriting identical HTML. Comparing first is one string compare against
   a DOM rebuild, and it is what makes the page still after a round ends
   rather than merely slower.

   AND NEVER OVER A SELECTION. When something did change and the reader is
   mid-drag, the new HTML is held rather than written - they are reading
   something and the page is not entitled to take it away. It goes in as
   soon as the selection is dropped, so the panel is at most one beat
   behind and only for as long as somebody is holding onto it. */
function stateBeatDraw(host, html) {
  // Against what was last WRITTEN, not against what the element reads
  // back. `innerHTML` returns the DOM re-serialised - attributes in the
  // parser's order, entities normalised, `open` without its value - so a
  // comparison with the string that produced it is false every time, and
  // this whole guard did nothing at all in its first version.
  if (stateBeat.drawn === xpShows(html) && host.dataset.sbDrawn === "1") return;
  if (stateBeatHolding(host)) {
    stateBeat.pending = { host: host, html: html };
    return;
  }
  stateBeat.pending = null;
  // Taken BEFORE the replacement: once innerHTML is written the old
  // frame is gone and with it where it was scrolled to.
  const was = sbWhereItWas();
  host.innerHTML = html;
  host.dataset.sbDrawn = "1";
  stateBeat.drawn = xpShows(html);
  stateBeatRestore(was);
}

/* Whether the reader has hold of some of this panel's text. A collapsed
   selection is a caret and not a hold, and one that starts outside the
   panel is somebody else's. */
function stateBeatHolding(host) {
  // A DRAG IS A HOLD. The panel redraws on every poll - twice a second
  // while a round runs - and a redraw replaces the frame, so the drag
  // that was in progress was being measured against a frame that no
  // longer existed and the view snapped back to where it started. The
  // pointer capture kept the EVENTS coming; it could do nothing about
  // the picture underneath being rebuilt mid-gesture.
  if (stateBeat.holding) return true;
  const held = window.getSelection && window.getSelection();
  if (!held || held.isCollapsed || !held.rangeCount) return false;
  const range = held.getRangeAt(0);
  return host.contains(range.commonAncestorContainer);
}

/* Let go, and the held draw goes in. Bound once, on the document,
   because the elements it is about are replaced constantly. */
function stateBeatWatchTheSelection() {
  if (stateBeat.watching) return;
  stateBeat.watching = true;
  document.addEventListener("selectionchange", () => {
    const waiting = stateBeat.pending;
    if (!waiting || !waiting.host.isConnected) return;
    if (stateBeatHolding(waiting.host)) return;
    stateBeat.pending = null;
    const was = sbWhereItWas();
    waiting.host.innerHTML = waiting.html;
    waiting.host.dataset.sbDrawn = "1";
    stateBeat.drawn = waiting.html;
    stateBeatRestore(was);
  });
}

function renderStateBeat() {
  const out = renderStateBeatNow();
  sbMarkSelected();
  return out;
}

function renderStateBeatNow() {
  const host = $("#dbg-statebeat-body");
  if (!host) return;
  stateBeatWatchTheSelection();
  stateBeatRemember();
  const draw = (html) => stateBeatDraw(host, html);
  const note = $("#dbg-states-note");
  const report = stateBeat.report;
  if (stateBeat.running && !report) {
    if (note) note.textContent = "grouping\u2026";
    draw(`<p class="muted">Running. It will say where it has
      got to as soon as it gets anywhere - reading the states, reading
      what they mean, scoring the pairs, and one model call per task that
      needs one.</p>`);
    return;
  }
  if (!report) {
    // Nothing to show, so show nothing. Leaving the last result up was
    // the old behaviour, and it meant that emptying the sandbox left its
    // tasks, its overview and its list of states on the page, every one
    // of them about files that no longer exist.
    if (note) note.textContent = "";
    draw(`<p class="muted">Nothing to show. Use one of the
      buttons above - those marked (sandbox) work on made-up states in a
      folder of their own, and the one marked (real data) works on
      yours.</p>`);
    return;
  }
  if (report.skipped) {
    draw(`<p class="muted">${escapeHtml(String(report.skipped))}</p>`);
    return;
  }
  if (report.scheme === "projects") {
    if (note) {
      note.textContent = report.duration_ms
        ? `last run took ${(report.duration_ms / 1000).toFixed(1)}s` : "";
    }
    draw(pjDebugPanel(report));
    return;
  }
  const groups = report.communities || [];
  if (note) {
    note.textContent = report.duration_ms
      ? `last run took ${(report.duration_ms / 1000).toFixed(1)}s`
      : "";
  }
  draw(`
    ${stateBeatStage(report)}
    ${((report.where || {}).scope === "sandbox")
      ? `<p class="sb-sandbox-banner"><strong>This was the sandbox.</strong>
         The same code over a separate pair of folders, in
         <code>${escapeHtml(String((report.where || {}).library || ""))}</code>,
         with its own tasks and its own rows. The states in it are copies of
         real ones where there were enough to copy, and invented where there
         were not - so what is written here may well be about the user, and
         is still not part of what the application knows: nothing in this
         folder is read by anything but this page.</p>`
      : ""}
    ${stateBeatHead(report)}
    ${(report.not_shown || []).length
      ? `<p class="sb-not-shown-note"><strong>${report.not_shown.length} of
         these would not be shown to the user.</strong> They are ways of
         working rather than things with substance - true, kept, and not a
         list of what somebody is working on:
         ${report.not_shown.map((one) =>
           `<span class="sb-not-shown-one">${escapeHtml(String(one.title || one.task))}</span>`
         ).join(" ")}</p>`
      : ""}
    ${stateBeatRehearsal()}
    ${stateBeat.rehearsal ? "" : `
      ${stateBeatOverview(report)}
      ${stateBeatWholeTree(report)}
      ${stateBeatKept(report)}
      ${stateBeatAnchors(report)}
      ${stateBeatTree(report)}`}
    ${report.note ? `<p class="beat-nothing">${escapeHtml(String(report.note))}</p>` : ""}
    ${report.error ? `<p class="beat-head-line"><strong>It stopped:</strong>
      ${escapeHtml(String(report.error))}</p>` : ""}
    ${report.blocked ? `<p class="beat-head-line"><strong>The model was not
      available.</strong> ${escapeHtml(String(report.reason || ""))} The groups
      below were still found - the grouping needs no model.</p>` : ""}
    ${stateBeat.rehearsal ? ""
      : (report.layers || []).map((task) =>
          stateBeatTask(task, report)).join("")}
    ${(report.loose || []).length
      ? `<details class="sb-task sb-task-loose" data-sb-open="loose">
         <summary><span class="sb-layer">layer 1</span>
           <span class="sb-task-name">outside every task</span>
           <span class="trail-count">${report.loose.length} states</span>
           <span class="muted">each grouped with nothing</span></summary>
         <div class="sb-task-body"><ul class="sb-task-states">${
           report.loose.map((id) => {
             const state = (report.states || []).find((one) => one.id === id);
             return `<li><button type="button" class="trail-item"
               data-sb-node="${escapeHtml(String(id))}">${
               escapeHtml(state ? String(state.title || id) : String(id))
               }</button></li>`;}).join("")}</ul></div>
         </details>`
      : ""}
    ${stateBeatPairs(report)}`);
}

/* What the run was, in one line each: how much it read, what it found, and
   the settings that decided both.

   The settings are here rather than in Settings alone because this is the
   page somebody is on when they want to change one, and a threshold read
   without the pairs it produced is a number with nothing to judge it by. */
function stateBeatHead(report) {
  const settings = report.settings || {};
  const written = (report.summaries_written || []).length;
  const groups = report.layers || [];
  return `<div class="sb-head">
    <div class="sb-figures">
      <span><strong>${Number(report.states_considered || 0)}</strong> states read</span>
      <span><strong>${Number((report.similarity || {}).pairs_scored || 0)}</strong>
        pairs scored</span>
      <span><strong>${Number(report.tasks_found || groups.length)}</strong>
        tasks</span>
      <span><strong>${Number(report.deepest || 1)}</strong> layers deep</span>
      <span><strong>${written}</strong> summaries written</span>
      <span class="muted">${Number(report.calls || 0)} calls ·
        ${Number((report.tokens_in || 0) + (report.tokens_out || 0)).toLocaleString()}
        tokens</span>
    </div>
    <div class="muted sb-settings">
      a task splits at ${settings.stands_out ?? "?"} standard deviations ·
      opened at ${settings.min_nodes ?? "?"} states ·
      at most ${settings.most_children ?? "?"} sub-tasks in a layer ·
      every ${Math.round(Number(settings.interval_seconds || 0) / 60)} minutes
    </div>
  </div>`;
}

/* The pieces of one task, drawn the way a game draws a technology tree.

   Time runs left to right, so where a circle sits is when its states
   began. An arrow from one circle to another means the second could not
   have been started until the first was done - a DEPENDENCY, which is not
   the same as having happened later, and is the one thing on this picture
   that no arithmetic could supply: the model is asked for it, and told
   that most pairs have no edge, because a model asked for a graph will
   draw one.

   A finished piece is filled and ticked. An unfinished one is an outline,
   because "still open" is the thing a reader is looking for and absence
   of fill reads as absence of completion.

   Rows exist only to stop circles overlapping. A row means nothing. */
/* Everything the round found, as one picture.

   The tech tree below this draws the pieces of ONE task. This draws the
   tasks - which is the view a person actually wants when they sit down:
   what am I in the middle of, what started when, and what is waiting on
   something else.

   A circle per task, not a box. Time runs left to right and the circle
   sits where the task began; the line through it is how long its states
   ran, so a long quiet task and a short intense one look different. An
   arrow means the task it points at could not have been started until
   the other was done - a dependency, not merely a later date - and most
   pairs have none.

   Clicking a circle opens the task's own pieces underneath, which is the
   same tech tree drawn one level down. Only tasks the user would be
   shown are here: a way of working is not a thing that can wait on
   another thing.
*/
/* An emblem for a task: made up, and always the same one.

   A row of identical circles is a row of identical circles, and the eye
   has nothing to hold on to - which is the whole reason a tech tree in a
   game draws a different device on every tile. So each task gets a
   figure of its own, generated rather than drawn: rings, rays, wedges,
   dots or chevrons, with the count and the angles taken from the task.

   IT IS SEEDED FROM THE TASK'S ID, which is the one thing about a task
   that lasts. The id survives appending, re-summarising, growing,
   shrinking and being found again by a rebuild - so the emblem survives
   all of those too, and a reader who has learnt "the one with the
   spokes" keeps it from week to week. A task that drifts far enough to
   stop being the same task gets a new id, and with it a new emblem,
   which is the honest signal: the picture changed because the thing
   changed.

   Not meaningful, and it should not pretend to be. Nothing about the
   work decides which motif comes out. It is a handle, not a reading. */
function sbSeed(said) {
  // FNV-1a, which is small, has no dependencies and spreads short
  // strings like `task-live-4f2a91` well enough for this.
  let hash = 0x811c9dc5;
  const text = String(said || "");
  for (let at = 0; at < text.length; at += 1) {
    hash ^= text.charCodeAt(at);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash || 1;
}

/* A repeatable stream of numbers from that seed, so the same task draws
   the same emblem on every round, on every reload, and on any machine. */
function sbRolls(seed) {
  let state = seed >>> 0;
  return () => {
    state ^= state << 13; state >>>= 0;
    state ^= state >> 17;
    state ^= state << 5; state >>>= 0;
    return state / 4294967296;
  };
}

function sbEmblem(id, colour, r) {
  const roll = sbRolls(sbSeed(id));
  const pick = (n) => Math.floor(roll() * n);
  const kinds = ["rays", "rings", "wedges", "dots", "chevrons"];
  const kind = kinds[pick(kinds.length)];
  const ink = "rgba(255,255,255,.82)";
  const thin = Math.max(0.9, r * 0.12);
  const parts = [];

  if (kind === "rays") {
    const spokes = 5 + pick(5);
    const turn = roll() * Math.PI;
    for (let n = 0; n < spokes; n += 1) {
      const a = turn + (n / spokes) * Math.PI * 2;
      const inner = r * (0.28 + roll() * 0.18);
      const outer = r * 0.82;
      parts.push(`<line x1="${(Math.cos(a) * inner).toFixed(2)}"
        y1="${(Math.sin(a) * inner).toFixed(2)}"
        x2="${(Math.cos(a) * outer).toFixed(2)}"
        y2="${(Math.sin(a) * outer).toFixed(2)}"
        stroke="${ink}" stroke-width="${thin.toFixed(2)}"
        stroke-linecap="round"/>`);
    }
  } else if (kind === "rings") {
    const many = 2 + pick(3);
    for (let n = 0; n < many; n += 1) {
      parts.push(`<circle cx="0" cy="0"
        r="${(r * (0.26 + n * (0.56 / many))).toFixed(2)}"
        fill="none" stroke="${ink}" stroke-width="${thin.toFixed(2)}"/>`);
    }
    if (roll() > 0.5) {
      parts.push(`<circle cx="0" cy="0" r="${(r * 0.14).toFixed(2)}"
        fill="${ink}"/>`);
    }
  } else if (kind === "wedges") {
    const many = 3 + pick(4);
    const turn = roll() * Math.PI * 2;
    const wide = (Math.PI * 2) / (many * 2);
    for (let n = 0; n < many; n += 1) {
      const a = turn + (n / many) * Math.PI * 2;
      const far = r * 0.8;
      parts.push(`<path d="M0 0 L${(Math.cos(a) * far).toFixed(2)}
        ${(Math.sin(a) * far).toFixed(2)}
        A${far.toFixed(2)} ${far.toFixed(2)} 0 0 1
        ${(Math.cos(a + wide) * far).toFixed(2)}
        ${(Math.sin(a + wide) * far).toFixed(2)} Z"
        fill="${ink}" opacity=".55"/>`);
    }
  } else if (kind === "dots") {
    const many = 4 + pick(6);
    const turn = roll() * Math.PI * 2;
    const ring = r * (0.42 + roll() * 0.22);
    for (let n = 0; n < many; n += 1) {
      const a = turn + (n / many) * Math.PI * 2;
      parts.push(`<circle cx="${(Math.cos(a) * ring).toFixed(2)}"
        cy="${(Math.sin(a) * ring).toFixed(2)}"
        r="${(r * 0.13).toFixed(2)}" fill="${ink}"/>`);
    }
    parts.push(`<circle cx="0" cy="0" r="${(r * 0.17).toFixed(2)}"
      fill="none" stroke="${ink}" stroke-width="${thin.toFixed(2)}"/>`);
  } else {
    const many = 2 + pick(3);
    const turn = roll() * Math.PI * 2;
    for (let n = 0; n < many; n += 1) {
      const far = r * (0.34 + n * 0.22);
      const a = turn;
      parts.push(`<path d="M${(Math.cos(a - 0.7) * far).toFixed(2)}
        ${(Math.sin(a - 0.7) * far).toFixed(2)}
        L${(Math.cos(a) * far * 1.08).toFixed(2)}
        ${(Math.sin(a) * far * 1.08).toFixed(2)}
        L${(Math.cos(a + 0.7) * far).toFixed(2)}
        ${(Math.sin(a + 0.7) * far).toFixed(2)}"
        fill="none" stroke="${ink}" stroke-width="${thin.toFixed(2)}"
        stroke-linecap="round" stroke-linejoin="round"/>`);
    }
  }
  return parts.join("");
}

/* The task a circle was clicked on, opened underneath the tree.

   One level down, and in the same shape: the pieces of that task as
   circles on the same time axis, with the same emblems and the same
   arrows. Drawn here rather than only by opening the task's block
   further down the page, because the block is a page of prose and the
   question a click on a circle asks is "what is inside this" - which is
   a picture, and is answered where the picture is.

   It slides open rather than appearing. A panel that changes between one
   frame and the next leaves the reader to work out what moved; a quarter
   of a second of movement says "this came from the thing you clicked"
   without a word. */
function stateBeatOpenedTask(report, ordered) {
  const key = stateBeat.openTask;
  if (!key) return "";
  const task = (report.layers || []).find((one) => one.id === key);
  const chosen = (ordered || []).find((one) => one.id === key);
  if (!task && !chosen) return "";
  const title = String((task && (task.summary || {}).title)
    || (chosen && chosen.title) || key);
  const inside = task ? stateBeatTechTree(task) : "";
  return `<div class="sb-opened" data-sb-opened="${escapeHtml(String(key))}">
    <p class="sb-opened-head">
      <button type="button" class="small secondary sb-opened-shut"
        data-sb-task-shut="1" title="Close">&times;</button>
      <strong>${escapeHtml(title)}</strong>
      <span class="muted">${Number((chosen || {}).size || task.size || 0)}
        states${(task && (task.children || []).length)
          ? `, in ${task.children.length} pieces` : ""}</span>
    </p>
    ${inside || `<p class="muted">This task has no pieces inside it - its
      states are listed on the task itself, further down.</p>`}
  </div>`;
}

/* Opening a task in the picture itself.

   The obvious way is to set a flag and redraw, and it cannot animate:
   redrawing replaces the elements, and an element that did not exist a
   frame ago has nothing to move from. So this does not redraw. It moves
   the rows that are already there and puts the new ones among them,
   which is what lets a transition run at all.

   What happens, in order: the rows below the opened task slide down to
   make room; its pieces appear in the gap, each one growing out of the
   parent's circle along a line that draws itself; and the frame around
   the whole thing grows to fit. Closing runs the same thing backwards.

   `stateBeat.openTask` still records which is open, so a redraw - the
   panel follows a running round - comes back with the same task open,
   laid out correctly and without the movement. */
const SB_UNFOLD_MS = 280;

/* The dates, held at the bottom of what can be seen.

   The axis is one `<g>` at the foot of the drawing, which is right until
   the drawing is taller than its frame: then it is below the fold, and a
   reader who has scrolled down to a task has nothing left to place it in
   time with. Scrolling to the bottom to read a date and back up to see
   the task it belongs to is not reading a picture.

   So it is moved to the bottom edge of the visible area on every scroll.
   The arithmetic is in the drawing's own units - the frame scrolls in
   pixels and the drawing is scaled by the zoom - and it is clamped to the
   drawing, so at full height it sits exactly where it was drawn. */
function sbPinTheAxis(svg) {
  if (!svg) return;
  const foot = svg.querySelector(".sb-tt-foot");
  const frame = svg.closest(".sb-tree-frame");
  if (!foot || !frame) return;
  const size = sbTreeZoom() || 1;
  const home = Number(foot.dataset.sbAt || 0);
  const tall = Number((svg.getAttribute("viewBox") || "").split(/[\s,]+/)[3])
    || home + 20;
  const seen = (frame.scrollTop + frame.clientHeight) / size - 20;
  const where = Math.max(0, Math.min(home, seen));
  foot.classList.add("sb-tt-pinned");
  foot.style.transform = `translateY(${where.toFixed(1)}px)`;
}

function sbUnfold(svg, report, key, moving) {
  const step = Number(svg.dataset.sbStep || 46);
  const shut = Number(svg.dataset.sbShut || 0);
  const rows = [...svg.querySelectorAll(".sb-tt-row")];
  const foot = svg.querySelector(".sb-tt-foot");
  const branches = svg.querySelector(".sb-tt-branches");
  if (!branches) return;
  // ONLY REBUILT WHEN WHAT IS UNDER SOMETHING HAS CHANGED.
  //
  // This cleared and rebuilt every branch on every call, and it is
  // called on every poll - so twice a second each limb drew itself from
  // nothing again and each circle faded in again. That is the "refresh"
  // feeling: not one slow animation but the same quick one, restarting
  // forever. Expanding looked like a reload because, as far as the
  // elements were concerned, it was one.
  //
  // The signature is what the branches are drawn FROM: which tasks are
  // open, which pieces inside them, and what each is called. Rows still
  // move on every call, which is cheap and is what the transition on
  // `.sb-tt-row` makes smooth.
  // KEPT PER TASK, NOT ALL TOGETHER. Clearing this group and building it
  // again means opening ONE task replays the branches of every other
  // open task: their limbs draw themselves from nothing and their circles
  // fade in, although nothing about them changed. That is the "it redrew
  // everything" feeling, and it is loudest when the task clicked is near
  // an edge, because then the rows that replay are the ones already under
  // the reader's eye.
  //
  // So each open task's branches live in a group of their own, marked
  // with what they were drawn from. A group whose mark still matches is
  // left alone - no new elements, nothing to animate.

  // SEVERAL AT ONCE. This took one id and drew one task's insides, so
  // opening a second shut the first - which is not what opening
  // something means. Comparing two tasks is the ordinary reason to open
  // them, and it was the one thing the picture would not allow.
  //
  // A plain id is still accepted, because `stateBeatRestore` and the
  // tests pass one and a Set of one is the same thing.
  const open = key instanceof Set ? key : new Set(key ? [key] : []);
  const gap = step * 0.62;

  // WHAT IS UNDER A THING IS ALWAYS MORE SUMMARISED WORK, never the
  // states themselves. Every layer of this picture is a task that was
  // written up by a model: the top one, the pieces inside it, and the
  // pieces inside those. The bottom layer is the bottom because nothing
  // inside it divided again, NOT because it is a list of raw states.
  //
  // Showing states at the last level was the earlier reading and it was
  // wrong: it put two different kinds of thing under one gesture, so the
  // same click gave a summary in one place and a transcript in another,
  // and a reader could not tell from the shape which they were about to
  // get.
  //
  // A level with nothing under it says so in the splitter's own words.
  // An empty gap where a branch should be reads as a drawing that failed.
  const kidsOf = (node) => (node && node.children) || [];
  // Which node is being summarised, so a piece can show it too - and so
  // can a piece that merely HOLDS the one being summarised. Ids are
  // built by appending to the parent's, so an ancestor is a prefix at a
  // dot; without the dot `task_3` would claim `task_31`.
  // EVERY ONE BEING SUMMARISED: several calls may be going at once.
  const busyAll = [report.summarising, ...(report.summarising_all || [])]
    .map((one) => String(one || "")).filter(Boolean);
  const working = (id) => Boolean(id) && busyAll.some((busy) =>
    busy === String(id) || busy.startsWith(`${id}.`));
  // A SUB-TASK WITH NO NAME IS IN THE SAME POSITION AS A TASK WITH NO
  // NAME. This fell back to the id, so a sub-task the round had not
  // reached read `task_3.2` - which looks like an answer and is not one.
  // The placeholder is left to `sbNameOf`, which says "summarizing" for
  // the one being written now and "preparing" for one whose turn has not
  // come, exactly as the layer above does.
  const nameOf = (node) => String((node.summary || {}).title || "");
  const states = new Map((report.states || []).map((one) => [one.id, one]));
  // Finished means every state in it is finished. A piece half done is
  // not done, which is why this is `every` and not `some`.
  const allDone = (node) => {
    const ids = (node.states || []);
    return ids.length > 0 && ids.every((id) => sbIsDone(states.get(id)));
  };
  const openPieces = stateBeat.openPieces instanceof Set
    ? stateBeat.openPieces : new Set();
  // What hangs under ONE task, which is now asked once per open task.
  const under = (task) => {
    const out = [];
    const walk = (node, depth) => {
      kidsOf(node).forEach((kid) => {
        out.push({kind: "piece", id: kid.id, title: nameOf(kid),
                  size: (kid.states || []).length, of: kid,
                  depth: depth, done: allDone(kid),
                  working: working(kid.id)});
        if (!openPieces.has(kid.id)) return;
        if (kidsOf(kid).length) {
          walk(kid, depth + 1);
          return;
        }
        out.push({kind: "note", id: `${kid.id}-none`, depth: depth + 1,
                  said: String(kid.why_closed
                    || "nothing inside this one divides again")});
      });
    };
    if (!task) return out;
    if (kidsOf(task).length) {
      walk(task, 1);
    } else {
      out.push({kind: "note", id: "flat", depth: 1,
                said: String(task.why_closed
                  || "nothing inside this one divides")});
    }
    return out;
  };

  // Every open task, in the order the rows are drawn, with what hangs
  // under each.
  const unfolded = rows.map((row) => {
    const id = row.dataset.sbTask;
    if (!open.has(id)) return null;
    const task = (report.layers || []).find((one) => one.id === id);
    const rowsUnder = under(task);
    return rowsUnder.length ? {row: row, id: id, rowsUnder: rowsUnder} : null;
  }).filter(Boolean);

  // ROOM UNDER EACH OPEN TASK, and every row below it moves by the sum of
  // what was opened above it. With one task this is what it always was;
  // with three it is the only arrangement where each one's branches hang
  // under the right task.
  const roomAt = new Map(unfolded.map(
    (one) => [one.id, one.rowsUnder.length * gap]));
  const baseOf = new Map();
  let shift = 0;
  rows.forEach((row) => {
    const home = Number(row.dataset.sbAt || 0);
    row.style.transform = `translateY(${home + shift}px)`;
    baseOf.set(row.dataset.sbTask, home + shift);
    shift += roomAt.get(row.dataset.sbTask) || 0;
  });
  if (foot) {
    // Where it would sit at the bottom of the whole drawing, which is
    // what `sbPinTheAxis` clamps against; the pinning then decides
    // where it actually goes.
    foot.dataset.sbAt = String(Number(foot.dataset.sbAt || 0));
    foot.dataset.sbFull = String(shut + shift - 20);
  }
  const room = shift;
  // TALLER, NOT SMALLER. The viewBox and the pixel height move together,
  // so a row stays the size it was and the picture simply becomes
  // longer; the frame scrolls when that is more than fits. Changing the
  // viewBox alone - which is what this did - leaves the same box showing
  // more of the drawing, and the only way to do that is to shrink
  // everything, which is why opening a task turned the whole thing into
  // a thumbnail.
  const tall = shut + room;
  // Wide enough for the longest thing unfolded, not just for the tasks:
  // a to-do's words sit to the right of its circle and would otherwise
  // run off the end of the drawing, where no amount of scrolling
  // reaches them.
  //
  // Measured from the row, not from `parent`, which is declared further
  // down: reading a `const` before its declaration is a ReferenceError,
  // and one thrown here took the branches AND the card with it, because
  // both come after this line.
  const discAt = (row) => {
    const held = row.querySelector(".sb-tt-disc");
    return held ? Number(held.getAttribute("cx")) : 0;
  };
  const whereX = (fromHere, one, n) =>
    fromHere - (one.depth === 2 ? 62 : 28) - Math.min(n, 6) * 8;
  // EVERY ROW'S WORDS RUN RIGHT FROM ITS CIRCLE, so the only room needed
  // is on the right and the drawing still starts at zero.
  //
  // There was a leftward case: the bottom layer used to be the states
  // themselves, drawn as to-do items with their words to the left. That
  // layer is gone - every layer is summarised work now - and the
  // measurement for it was left behind, counting NOTES as leftward
  // although a note is drawn to the right like everything else. A task
  // with no pieces draws exactly one note, so clicking one asked for
  // hundreds of pixels of left margin and the frame was scrolled right
  // to compensate: the picture jumped to its right edge on a click.
  const wideEnough = unfolded.reduce((most, group) => {
    const fromHere = discAt(group.row);
    return group.rowsUnder.reduce((widest, one, n) =>
      Math.max(widest, whereX(fromHere, one, n) + 24 + sbTextWide(
        one.said || one.title || "", 6.1)), most);
  }, 0);
  const wide = Math.max(Number(svg.dataset.sbWide || SB_WIDTH) || SB_WIDTH,
                        wideEnough);
  // A negative start where a to-do's words reach left of zero: the
  // drawing keeps its own coordinates and the box moves, rather than
  // every row being nudged right and the time axis losing its meaning.
  // FROM ZERO, ALWAYS. Nothing is drawn left of the axis, so there is no
  // left margin to add and no scroll to compensate for adding one. The
  // compensation was correct for what it was written for and wrong the
  // moment nothing needed it: it moved the view on every unfold.
  svg.setAttribute("viewBox", `0 0 ${wide} ${tall}`);
  const size = sbTreeZoom();
  svg.style.height = `${(tall * size).toFixed(0)}px`;
  svg.style.width = `${(wide * size).toFixed(0)}px`;
  svg.dataset.sbZoom = String(size);
  if (foot) foot.dataset.sbAt = String(tall - 20);
  sbPinTheAxis(svg);
  // Groups for tasks that are no longer open, or whose contents changed,
  // go; the others stay exactly as they are.
  const wanted = new Map(unfolded.map((group) => [
    group.id,
    // WHAT THE BRANCHES ARE, NOT WHERE THEY SIT. The mark used to include
    // the row's position, and a row MOVES whenever anything above it
    // opens - so opening one task changed another's mark and rebuilt its
    // branches, which played their animation again. That is the replay
    // that survived two earlier attempts at this: each group is now
    // positioned by a transform and drawn relative to itself, so moving
    // it is a number and not a rebuild.
    JSON.stringify([group.rowsUnder.map((one) => [
      one.id, one.title || one.said || "", one.depth, Boolean(one.done),
      Boolean(one.working)]), Number(discAt(group.row))]),
  ]));
  [...branches.children].forEach((held) => {
    const mine = held.dataset.sbUnder;
    if (!wanted.has(mine) || wanted.get(mine) !== held.dataset.sbMark) {
      held.remove();
    }
  });
  if (!unfolded.length) return;

  unfolded.forEach((group) => {
  const parent = group.row;
  const rowsUnder = group.rowsUnder;
  // Where this group sits, which is the one thing that changes when
  // something else opens. Set on every call, on a group that is kept as
  // well as on one that is built.
  const base = Number(baseOf.get(group.id) || 0);
  const already = branches.querySelector(
    `[data-sb-under="${group.id}"]`);
  if (already) {
    already.style.transform = `translateY(${base}px)`;
    return;
  }
  const mine = document.createElementNS("http://www.w3.org/2000/svg", "g");
  mine.setAttribute("class", "sb-tt-under");
  mine.dataset.sbUnder = group.id;
  mine.dataset.sbMark = wanted.get(group.id);
  mine.style.transform = `translateY(${base}px)`;
  branches.appendChild(mine);
  const disc = parent.querySelector(".sb-tt-disc");
  // Out of the disc, which is now at the task's most recent end - so the
  // branches hang under the thing they belong to rather than reaching
  // across the picture from its beginning.
  const fromX = Number(disc ? disc.getAttribute("cx") : 0);
  // ZERO, because the group itself is placed by a transform. Drawing at
  // the row's absolute position meant the drawing had to be redone every
  // time the row moved, and a row moves whenever anything above it opens.
  const fromY = 0;
  const colour = disc ? disc.getAttribute("fill") : "currentColor";

  rowsUnder.forEach((one, n) => {
    const y = fromY + gap * (n + 1);
    const deep = one.depth === 2;
    // Backwards from the parent, since that is where its history is.
    const x = fromX - (deep ? 62 : 28) - Math.min(n, 6) * 8;
    const bit = document.createElementNS("http://www.w3.org/2000/svg", "g");
    // A class per layer as well as the attribute: a stylesheet and a
    // test both want "the third layer", and `[data-sb-depth="3"]` needs
    // quoting inside quoting wherever it is written.
    bit.setAttribute("class", `sb-tt-branch sb-tt-d${Number(one.depth || 1)}${
      deep ? " sb-tt-deep" : ""}${one.working ? " sb-tt-working" : ""}`);
    // ANIMATED ONLY WHEN SOMETHING WAS OPENED. A redraw rebuilds the
    // branches of tasks that were already open - nothing about them
    // changed, they are simply new elements - and letting them fade in
    // again is the "it refreshed" flicker: the picture replaying work the
    // reader did minutes ago. The fade belongs to the click that caused
    // it, so only the click asks for it.
    if (!moving) bit.style.animation = "none";
    // NO STAGGER. Forty milliseconds a row reads as a wave crossing the
    // picture, and with ten rows that is most of half a second before the
    // last one is there. They appear together.

    if (one.kind === "note") {
      bit.innerHTML = `
        <path d="M${fromX} ${fromY} V${y - 6} q0 6 -6 6 H${x + 6}"
          class="sb-tt-limb" stroke="${colour}"/>
        <text x="${x + 10}" y="${y + 3.5}"
          class="sb-tt-aside sb-tt-nothing">${escapeHtml(one.said)}</text>`;
      mine.appendChild(bit);
      return;
    }
    if (one.kind === "none") {
      bit.innerHTML = `
        <path d="M${fromX} ${fromY} V${y - 6} q0 6 -6 6 H${x + 6}"
          class="sb-tt-limb" stroke="${colour}"/>
        <text x="${x + 10}" y="${y + 3.5}"
          class="sb-tt-aside sb-tt-nothing">${
          deep ? "this piece holds no states"
               : "no pieces inside this one, and no states either"}</text>`;
      mine.appendChild(bit);
      return;
    }

    // Smaller the deeper it sits, so three layers of the same shape
    // still read as three layers.
    const size = Math.max(4.5, Math.min(11,
      (4 + Math.sqrt(Number(one.size || 1)) * 1.6)
      - (Number(one.depth || 1) - 1) * 1.2));
    // WHOLE, like the task names above them. A to-do cut at forty-six
    // characters is the half of a sentence that says least: the review
    // writes what was done at the front and which thing it was done to
    // at the back.
    const said = sbNameOf(one);
    // The PIECES that are open, not the tasks: `open` is the set of task
    // rows now, and reading it here would ring a piece whose id happened
    // to match a task's.
    const shown = one.kind === "piece" && openPieces.has(one.id);
    bit.innerHTML = `
      <path d="M${fromX} ${fromY} V${y - 6} q0 6 -6 6 H${x + size + 2}"
        class="sb-tt-limb" stroke="${colour}"/>
      ${`<circle cx="${x}" cy="${y}" r="${size.toFixed(1)}"
           fill="${one.done ? colour : "none"}"
           stroke="${shown ? "var(--text, #e8ecf3)" : colour}"
           stroke-width="${shown ? 2.6 : 1.6}" pointer-events="all"
           class="sb-tt-disc${one.done ? " sb-tt-whole" : ""}"/>
         <g transform="translate(${x} ${y})" pointer-events="none">${
           sbEmblem(String(one.task_id || one.id || ""), colour, size)}</g>`}
      ${(() => {
        const tail = one.kind === "piece"
          ? ` · ${Number(one.size || 0)} states`
          : (one.done ? " · done" : " · still open");
        // Right of the circle, like the names in the layer above: every
        // row here is a task, and the one kind of row that was drawn to
        // the left - a raw state, as a to-do item - is not a row any more.
        const atX = (x + size + 6).toFixed(1);
        const ends = "start";
        // Two lines rather than one long one, the same as the task names
        // above: it halves how far a to-do reaches past the edge, and the
        // reader was going to have to drag for the rest either way.
        const rows = one.kind === "piece"
          ? [said + tail] : sbWrapName(said + tail, 44);
        const lift = rows.length > 1 ? -4 : 3.5;
        return `<text x="${atX}" y="${y + lift}" text-anchor="${ends}"
          class="sb-tt-aside${one.done ? " sb-tt-struck" : ""}">${
          rows.map((line, row) =>
            `<tspan x="${atX}" dy="${row ? 12 : 0}">${
              escapeHtml(line)}</tspan>`).join("")}</text>`;
      })()}`;
    if (one.kind === "piece") {
      bit.setAttribute("data-sb-piece", String(one.id || ""));
      bit.setAttribute("data-sb-depth", String(one.depth || 1));
      bit.setAttribute("tabindex", "0");
      bit.setAttribute("role", "button");
    }
    mine.appendChild(bit);
  });
  });
}

/* Whether a state is finished. `done` and `retired` both mean there is
   nothing left to do in it; anything else is still open. */
function sbIsDone(state) {
  const said = String((state || {}).status || "").toLowerCase();
  return said === "done" || said === "retired";
}

/* The panel under the picture, for whichever task is selected.

   The tree answers "what am I in the middle of" at a glance and cannot
   answer anything else: there is room beside a circle for a name and a
   count, and a task is four paragraphs, a span, a cost and a list of
   pieces. So the picture selects and the panel reads out - the
   arrangement a strategy game uses for the same reason, a map you point
   at and a box that tells you what you pointed at.

   Its own function, and filled by hand on a click rather than by a
   redraw, because the click must not redraw: see `sbUnfold`. */

/* When a set of states ran, and for how long.

   Taken from the states themselves rather than from the plan, because a
   piece has no span of its own: it is a cut through one task's states,
   and its duration is whatever its own states cover. */
function sbSpanOf(report, ids) {
  const want = new Set((ids || []).map(String));
  const times = (report.states || [])
    .filter((one) => want.has(String(one.id)))
    .map((one) => [Date.parse(one.starts_at || one.ends_at || ""),
                   Date.parse(one.ends_at || one.starts_at || "")])
    .filter((pair) => !Number.isNaN(pair[0]));
  if (!times.length) return null;
  const from = Math.min(...times.map((pair) => pair[0]));
  const to = Math.max(...times.map((pair) => pair[1] || pair[0]));
  const hours = (to - from) / 3600000;
  const said = hours < 1 ? "under an hour"
    : hours < 48 ? `${Math.round(hours)} hours`
    : `${Math.round(hours / 24)} days`;
  return {from: new Date(from).toISOString(),
          to: new Date(to).toISOString(), hours: hours, said: said};
}

/* The two numbers, and what put them there.

   A task carries its own. A PIECE DOES NOT - it is part of one task and
   the weighing is of the task, so a piece shows its parent's and says
   whose they are. Saying "urgency 6" on a piece without that would read
   as a judgement of the piece, which nothing in the round ever made. */
/* A task still waiting for its turn, said as that.

   A round is one call per task, so on a busy folder the panel is read
   while it runs. Showing the words from six hours ago as though they
   were this round's is the thing to avoid: a reader cannot tell a name
   just written from one that is stale, and the whole point of a round
   is that something changed. What it said before is offered AS what it
   is - yesterday's - rather than silently reused. */
function sbWaitingLine(described) {
  const was = (described || {}).was || {};
  return `<p class="sb-card-part sb-waiting">
    <span class="event-label">waiting</span>
    <span class="sb-spin" aria-hidden="true"></span>
    This task has not been summarised yet in this round${
      (described || {}).waiting_size
        ? ` - ${Number(described.waiting_size)} states to read` : ""}.${
    was.title
      ? `<br><span class="muted">Last round called it
         &ldquo;${escapeHtml(String(was.title))}&rdquo;${was.status
           ? `, and said: ${escapeHtml(String(was.status))}` : ""}</span>`
      : ""}</p>`;
}

function sbWeighLine(described, whose) {
  const urgency = described.urgency;
  const importance = described.importance;
  if (urgency === undefined || urgency === null
      || importance === undefined || importance === null) {
    // Only for a task described before the weighing existed. A task
    // summarised under it always has both, because "the states give no
    // sign" is answered with a 4 and not with a blank.
    return `<p class="muted sb-card-part"><span class="event-label">weight
      </span>none recorded - this task was written up before the weighing
      existed, and the next round it moves in will give it one.</p>`;
  }
  return `<p class="sb-card-part"><span class="event-label">weight</span>
    <span class="badge sb-weigh">urgency ${Number(urgency)}/7</span>
    <span class="badge sb-weigh">importance ${Number(importance)}/7</span>${
      whose ? ` <span class="muted">(of the whole task)</span>` : ""}${
      described.weighed_how === "default"
        ? ` <span class="muted">(the middle - the states gave no sign)</span>`
        : ""}${
      described.weighed_why
        ? `<br><span class="muted">${escapeHtml(
            String(described.weighed_why))}</span>` : ""}</p>`;
}

/* One sub-task, read out in the panel.

   The same four parts a task has, because a piece is summarised the same
   way, plus what only a piece can say: how many of its to-do items are
   done, how long its own states cover, and - where it has no pieces of
   its own - the splitter's reason for stopping there. */
function sbPieceCard(report, key, which) {
  const task = (report.layers || []).find((one) => one.id === key) || {};
  // AT ANY DEPTH. A piece three layers down is not in `task.children`,
  // and looking for it only there is why the panel went blank on the
  // level the reader had just opened.
  const look = (node) => {
    for (const kid of (node.children || [])) {
      if (kid.id === which) return kid;
      const found = look(kid);
      if (found) return found;
    }
    return null;
  };
  const piece = look(task);
  if (!piece) {
    return `<p class="muted sb-card-empty">That piece is not in this
      round.</p>`;
  }
  const summary = piece.summary || {};
  const described = summary.described || {};
  const held = (task.summary || {}).described || {};
  const colour = sbColour(stateBeatTopIndex(task, report), true);
  const span = sbSpanOf(report, piece.states || []);
  const mine = new Set((piece.states || []).map(String));
  const states = (report.states || []).filter(
    (one) => mine.has(String(one.id)));
  const done = states.filter((one) => sbIsDone(one)).length;
  const parts = [["where", "Where the work lives"],
                 ["goal", "What it is in aid of"],
                 ["doing", "What the work is"],
                 ["status", "Where it stands"]];
  return `<div class="sb-card-body">
    <svg viewBox="-22 -22 44 44" class="sb-card-badge" aria-hidden="true">
      <circle cx="0" cy="0" r="19" fill="${colour}"/>
      ${sbEmblem(String(which), colour, 19)}
    </svg>
    <div class="sb-card-said">
      <p class="sb-card-title">${escapeHtml(String(
        summary.title || piece.id))}
        <span class="badge">${
          String(which).split(".").length > 2 ? "a piece of a piece"
            : "a piece"} of ${escapeHtml(String(
          (task.summary || {}).title || task.id))}</span></p>
      <p class="muted sb-card-figures">${(piece.states || []).length} states
        &middot; ${(piece.children || []).length
          ? `${piece.children.length} sub-task${
              piece.children.length === 1 ? "" : "s"} inside it${(() => {
              // NOT EVERY STATE LANDS IN A PIECE. A cluster smaller than
              // a task is allowed to be never becomes one, so it stays
              // held by its parent and is not a row anywhere. Saying
              // "2 pieces" over seven states and showing five of them
              // would leave the other two unaccounted for, and a reader
              // counting would be right to think the picture had lost
              // them.
              const inside = (piece.children || []).reduce(
                (sum, kid) => sum + (kid.states || []).length, 0);
              const over = (piece.states || []).length - inside;
              return over > 0
                ? `, ${over} in none of them (too few to be a sub-task)`
                : "";
            })()}`
          : "the bottom layer"} &middot; ${done} of ${
          states.length} states finished${
        span ? ` &middot; ${escapeHtml(clock(span.from))} to ${
          escapeHtml(clock(span.to))} &middot; ${escapeHtml(span.said)}`
          : " &middot; no times recorded"}</p>
      ${summary.summary
        ? `<p class="sb-card-line">${escapeHtml(String(summary.summary))}</p>`
        : ""}
      ${parts.filter(([name]) => String(described[name] || "").trim())
        .map(([name, heading]) => `<p class="sb-card-part">
          <span class="event-label">${escapeHtml(heading)}</span>
          ${escapeHtml(String(described[name]))}</p>`).join("")}
      ${sbWeighLine(held, true)}
      ${(piece.children || []).length
        ? `<p class="muted sb-card-part"><span class="event-label">below it
             </span>${piece.children.length} sub-task${
               piece.children.length === 1 ? "" : "s"} of its own.</p>`
        : `<p class="muted sb-card-part"><span class="event-label">below it
             </span>${escapeHtml(String(piece.why_closed
               || "nothing inside it divides again."))}</p>`}
    </div>
  </div>`;
}

/* WHAT THE CARD UNDER THE PICTURE IS SHOWING, kept rather than assumed.

   A click on a piece, or on a to-do inside one, wrote that thing into
   the card - and nothing remembered it. When the panel was rebuilt the
   card was filled from `stateBeat.openTask`, which is only ever the top
   task, so a reader reading a piece saw it replaced by its parent on the
   next refresh, mid-sentence. The click says what is being read; the
   rebuild reads it back. */
function sbCardFor(report) {
  const shows = stateBeat.cardShows || {};
  if (shows.kind === "piece" && shows.which) {
    return sbPieceCard(report, stateBeat.openTask, shows.which);
  }
  if (shows.kind === "project" && shows.which) {
    return sbProjectCard(report, shows.which);
  }
  return sbTaskCard(report, stateBeat.openTask);
}

/* QUIET: nothing has been added to it for days. It is still here, and
   still drawn - after a month it goes dormant and is not, until work in it
   picks it up again. */
function sbPhaseLine(task, said) {
  const phase = task.phase || said.phase || "active";
  if (phase !== "quiet") return "";
  const last = task.last_seen || said.ended || "";
  return `<p class="muted sb-card-quiet">Quiet${last
    ? ` since ${escapeHtml(clock(last))}` : ""} - nothing has been added to
    it for a few days. After a month without any, it goes dormant: not
    drawn, and picked up again if work in it comes back.</p>`;
}















/* A PROJECT: several tasks the model agreed are parts of one larger piece
   of work, found from where the work lives. Its name, why it is one, where
   it lives, and its tasks. */
function sbProjectCard(report, which) {
  const project = (report.projects || []).find((one) => one.id === which);
  if (!project) {
    return `<p class="muted sb-card-empty">That project is not in this
      picture.</p>`;
  }
  const layers = report.layers || [];
  const nodes = (report.plan || {}).nodes || [];
  const rowOf = (id) => {
    const layer = layers.find((one) => one.task_id === id) || {};
    const node = nodes.find((one) => one.task_id === id) || {};
    const said = (layer.summary || {}).described || {};
    return {title: ((layer.summary || {}).title) || node.title
              || "(not named yet)",
            status: said.status || "", urgency: said.urgency,
            importance: said.importance};
  };
  const stretches = (project.stretches || []).filter((pair) => pair && pair[0]);
  return `<div class="sb-card-body"><div class="sb-card-said">
    <p class="sb-card-title">${escapeHtml(project.name || "A project")}</p>
    <p class="muted sb-card-figures">${escapeHtml(sbProjectAside(project))}
      &middot; ${Number(project.count || 0)} states${project.began
        ? ` &middot; ${escapeHtml(clock(project.began))} to ${
            escapeHtml(clock(project.ended || project.began))}` : ""}${
      stretches.length > 1 ? ` &middot; in ${stretches.length} stretches`
        : ""}</p>
    ${project.status ? `<p class="sb-card-part"><span class="event-label">Where
      it stands</span> ${escapeHtml(project.status)}${xpWriter(project.written_by)
        ? ` <span class="muted">(written by ${escapeHtml(
            xpWriter(project.written_by))})</span>` : ""}</p>`
      : `<p class="muted">Where it stands is written after its tasks have
         theirs, in the next round.</p>`}
    ${project.why ? `<p class="sb-card-part"><span class="event-label">Why
      they are one</span> ${escapeHtml(project.why)}</p>` : ""}
    ${project.home ? `<p class="sb-card-part"><span class="event-label">Where
      it lives</span> <code title="${escapeHtml(project.home)}">${
      escapeHtml(sbShortPlace(project.home))}</code></p>` : ""}
    <p class="sb-card-part"><span class="event-label">Its tasks</span></p>
    <ul class="sb-round-list">${(project.tasks || []).map((id) => {
      const one = rowOf(id);
      return `<li><strong>${escapeHtml(one.title)}</strong>${
        one.urgency ? ` <span class="muted">urgency ${one.urgency}/7,
          importance ${one.importance}/7</span>` : ""}${one.status
        ? `<br><span class="muted">${escapeHtml(one.status)}</span>` : ""}</li>`;
    }).join("")}</ul>
    <p class="muted">Grouped because they share where the work lives, and
      confirmed by the model - never assumed. Click the project in the
      picture to open or close its tasks.</p>
  </div></div>`;
}

/* Under a project's name: how many tasks, and how urgent and important
   its most pressing part is. */
function sbFirstWords(text, most) {
  const said = String(text || "").trim();
  return said.length > most ? `${said.slice(0, most - 1).trimEnd()}…` : said;
}

function sbProjectAside(project) {
  const bits = [`${(project.tasks || []).length} tasks`,
                `${Number(project.count || 0)} states`];
  if (project.urgency) bits.push(`urgency ${project.urgency}/7`);
  if (project.importance) bits.push(`importance ${project.importance}/7`);
  if (project.phase === "quiet") bits.push("quiet");
  return bits.join(" · ");
}

/* The project a task is part of, on its own card. */
function sbProjectLine(report, task, said) {
  const id = task.task_id || said.task_id;
  const project = (report.projects || []).find((one) =>
    (one.tasks || []).includes(id));
  if (!project) return "";
  return `<p class="sb-card-part"><span class="event-label">Part of</span>
    ${escapeHtml(project.name || "a project")}${project.why
      ? ` <span class="muted">- ${escapeHtml(project.why)}</span>` : ""}</p>`;
}

/* A PATH, shortened to its last two parts; the whole of it on hover. */
function sbShortPlace(place) {
  const parts = String(place || "").split("/").filter(Boolean);
  return parts.length > 2 ? `…/${parts.slice(-2).join("/")}` : String(place);
}

/* WHERE THE WORK IS, AND WHAT EACH PLACE IS WORTH. Coverage is how much of
   the task touched it; "only this task" is how few other tasks use it;
   the weight is the two multiplied, and it is what a new state sharing
   that place is credited with when it is placed. Folded: it is the
   working, not the answer. */
function sbPlacesBlock(task, said) {
  const rows = (task.places || said.places || []).filter((row) =>
    row && row.place);
  const weight = Number(task.weight || said.weight || 0);
  if (!rows.length && !weight) return "";
  const pct = (value) => `${Math.round(Number(value || 0) * 100)}%`;
  // KEYED, so the panel's redraw - every second or two - keeps it as the
  // reader left it: without a key it shut itself while being read.
  return `<details class="sb-card-places" data-sb-open="card-places">
    <summary><span class="event-label">Where the work is</span>
      ${rows.length} place${rows.length === 1 ? "" : "s"}${weight
        ? ` &middot; weight ${weight.toFixed(1)}` : ""}</summary>
    ${weight ? `<p class="muted">The weight behind its centre: about 72 for
      a task worked on steadily, less when it has not been - a state's
      share halves after 50 later ones.</p>` : ""}
    ${rows.length ? `<table class="sb-places">
      <thead><tr><th>Place</th><th title="How much of this task touched it"
        >Coverage</th><th title="How few other tasks use it"
        >Only this task</th><th title="Coverage times only-this-task: what a
        new state sharing this place is credited with">Weight</th></tr></thead>
      <tbody>${rows.map((row) => `<tr>
        <td><code title="${escapeHtml(String(row.place))}">${
          escapeHtml(sbShortPlace(row.place))}</code></td>
        <td>${pct(row.coverage)}</td><td>${pct(row.specific)}</td>
        <td><strong>${Number(row.weight || 0).toFixed(2)}</strong></td>
      </tr>`).join("")}</tbody></table>` : ""}
  </details>`;
}

/* WHAT THIS ROUND DID WITH IT. Each state that joined, with how far it was
   from the task (or the piece it matched), what it shared, and through
   which place; and the states that came nearest without joining, with
   why not. */
function sbThisRoundBlock(task) {
  const did = task.this_round || {};
  const joined = did.joined || [];
  const nearly = did.nearly || [];
  if (!joined.length && !nearly.length) return "";
  const row = (one) => `<li>${escapeHtml(String(one.title || one.state))}
    <span class="muted"> &middot; distance ${Number(one.distance || 0)
      .toFixed(2)}${Number(one.workspace || 0) > 0
      ? ` &middot; shares ${escapeHtml(sbShortPlace(one.place))} (${
          Number(one.workspace).toFixed(2)})` : ""}${Number(one.part) >= 0
      ? ` &middot; through piece ${Number(one.part) + 1}` : ""}${one.why
      ? ` &middot; ${escapeHtml(String(one.why))}` : ""}</span></li>`;
  return `<details class="sb-card-round" data-sb-open="card-round" open>
    <summary><span class="event-label">This round</span>
      ${joined.length} joined${nearly.length
        ? `, ${nearly.length} came near and did not` : ""}</summary>
    ${joined.length ? `<ul class="sb-round-list">${joined.map(row).join("")}
      </ul>` : ""}
    ${nearly.length ? `<p class="muted">Nearest to this task, but left
      loose:</p><ul class="sb-round-list">${nearly.map(row).join("")}</ul>`
      : ""}
  </details>`;
}

/* A TASK'S HISTORY: what it was called before - each earlier name, when it
   was written and why it was described again - and the tasks it came from,
   split from or merged from, each with where it came from in turn. */
function sbHistoryHtml(said) {
  const when = (at) => at ? escapeHtml(clock(at)) : "";
  const versions = (said.versions || []).map((one) => `<li>
      <strong>${escapeHtml(one.title || "(no name)")}</strong>
      <span class="muted"> &middot; ${when(one.at)}${one.size
        ? ` &middot; ${Number(one.size)} states` : ""}${one.why
        ? ` &middot; replaced because ${escapeHtml(one.why)}` : ""}</span>
      ${one.summary ? `<div class="muted sb-history-said">${escapeHtml(
        sbFirstWords(one.summary, 280))}</div>` : ""}</li>`).join("");
  const how = {"split from": "split out of", "merged from": "merged from",
               "new": "found in"};
  const tree = (rows) => rows.length ? `<ul class="sb-history-from">${rows.map(
    (one) => `<li><span class="muted">${escapeHtml(how[one.how] || one.how
      || "came from")}</span> <strong>${escapeHtml(one.title || one.id)}</strong>
      <span class="muted">${one.retired_at ? " &middot; ended" : ""}${one.why
        ? ` &middot; ${escapeHtml(sbFirstWords(one.why, 200))}` : ""}</span>
      ${tree(one.came_from || [])}</li>`).join("")}</ul>` : "";
  return `<p class="sb-card-part"><span class="event-label">Earlier
      names</span></p>
    ${versions ? `<ol class="sb-history-list">${versions}</ol>`
      : `<p class="muted">None: it has had only the name it has now.</p>`}
    <p class="sb-card-part"><span class="event-label">Where it came
      from</span></p>
    ${tree(said.came_from || []) || `<p class="muted">It was found as it is:
      not split from or merged out of another task.</p>`}`;
}

document.addEventListener("click", async (event) => {
  const button = event.target.closest?.("[data-sb-history]");
  if (!button) return;
  const body = button.closest(".sb-card-said")?.querySelector(".sb-history");
  if (!body) return;
  if (!body.hidden) {
    body.hidden = true;
    return;
  }
  body.hidden = false;
  body.innerHTML = `<p class="muted">Reading its history&hellip;</p>`;
  try {
    const said = await api.get(`/api/state_heartbeat/task_history?id=${
      encodeURIComponent(button.dataset.sbHistory)}`);
    body.innerHTML = sbHistoryHtml(said);
  } catch (err) {
    body.innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
  }
});

/* WORKED ON IN STRETCHES: said when there was more than one, with the
   latest gap - "resumed on 3 Oct after 5 months" is the thing a reader
   wants to know about a task that came back. */
function sbStretchLine(task, said) {
  const stretches = (task.stretches || said.stretches || []).filter(
    (pair) => pair && pair[0]);
  if (stretches.length < 2) return "";
  const last = stretches[stretches.length - 1];
  const before = stretches[stretches.length - 2];
  const days = Math.round((Date.parse(last[0]) - Date.parse(before[1]))
                          / 86400000);
  const gap = days >= 60 ? `${Math.round(days / 30)} months`
    : `${days} day${days === 1 ? "" : "s"}`;
  return `<p class="muted">Worked on in ${stretches.length} stretches;
    picked up again on ${escapeHtml(clock(last[0]))} after ${gap}
    without any.</p>`;
}

/* WHERE THE WORK IS: the places most of its states touched, and few other
   tasks did. A path is shortened to its last two parts. */
function sbRegionLine(task, said) {
  const places = (task.region || said.region || []).filter(Boolean);
  if (!places.length) return "";
  const short = (place) => {
    const parts = String(place).split("/").filter(Boolean);
    return parts.length > 2 ? `…/${parts.slice(-2).join("/")}` : String(place);
  };
  return `<p class="sb-card-part"><span class="event-label">Mostly in</span>
    ${places.map((place) => `<code title="${escapeHtml(String(place))}">${
      escapeHtml(short(place))}</code>`).join(", ")}</p>`;
}


function sbTaskCard(report, key) {
  if (!key) {
    return `<p class="muted sb-card-empty sb-click-hint">Click a task above to read it
      here.</p>`;
  }
  const task = (report.layers || []).find((one) => one.id === key) || {};
  const summary = task.summary || {};
  const plan = report.plan || {};
  const said = (plan.nodes || []).find((one) => one.id === key) || {};
  const colour = sbColour(stateBeatTopIndex(task, report), true);
  const parts = [["where", "Where the work lives"],
                 ["goal", "What it is in aid of"],
                 ["doing", "What the work is"],
                 ["status", "Where it stands"]];
  const described = summary.described || {};
  return `<div class="sb-card-body">
    <svg viewBox="-22 -22 44 44" class="sb-card-badge" aria-hidden="true">
      <circle cx="0" cy="0" r="19" fill="${colour}"/>
      ${sbEmblem(String(task.task_id || said.task_id || key), colour, 19)}
    </svg>
    <div class="sb-card-said">
      <p class="sb-card-title">${escapeHtml(String(
        summary.title || said.title || key))}
        ${task.task_id || said.task_id ? `<button type="button"
          class="small secondary sb-history-open"
          data-sb-history="${escapeHtml(String(task.task_id || said.task_id))}"
          title="What this task was called before, and the tasks it came from">History</button>`
          : ""}</p>
      <div class="sb-history" hidden></div>
      <p class="muted sb-card-figures">${Number(task.count || said.count
          || task.size || said.size || 0)}
        states${(task.children || []).length
          ? ` in ${task.children.length} pieces` : ""}${said.began
          ? ` &middot; ${escapeHtml(clock(said.began))} to ${
              escapeHtml(clock(said.ended || said.began))}` : ""}${
        said.finished ? " &middot; finished" : ""}${
        sbSpanOf(report, task.states || [])
          ? ` &middot; ${escapeHtml(sbSpanOf(report,
              task.states || []).said)}` : ""}</p>
      ${sbProjectLine(report, task, said)}
      ${sbPhaseLine(task, said)}
      ${sbStretchLine(task, said)}
      ${sbRegionLine(task, said)}
      ${sbPlacesBlock(task, said)}
      ${sbThisRoundBlock(task)}
      ${described.waiting ? sbWaitingLine(described) : ""}
      ${sbWeighLine(described, false)}
      ${xpWriter(described.written_by) ? `<p class="muted sb-card-line">Written
        by ${escapeHtml(xpWriter(described.written_by))}</p>` : ""}
      ${summary.summary
        ? `<p class="sb-card-line">${escapeHtml(String(summary.summary))}</p>`
        : ""}
      ${parts.filter(([name]) => String(described[name] || "").trim())
        .map(([name, heading]) => `<p class="sb-card-part">
          <span class="event-label">${escapeHtml(heading)}</span>
          ${escapeHtml(String(described[name]))}</p>`).join("")}
      ${summary.concrete === false
        ? `<p class="sb-not-shown-why">Kept, not shown: this is a way of
             working rather than a thing with substance underneath it.</p>`
        : ""}
    </div>
  </div>`;
}

/* The order the tasks are read in.

   By urgency, or by importance, and the reader chooses. Urgency by
   default because the question a person opens this with is what needs
   doing, not what is weightiest - the weighty thing is often the one
   that can wait a week.

   TIES KEEP THE OLD ORDER. Two tasks the model marked 5 and 5 are not
   ranked against each other by some further invention; they fall back to
   the seat, which is the place a task is given when it first appears and
   keeps for life. So sorting rearranges what the numbers actually
   separate and leaves everything else exactly where the reader last saw
   it - which is the whole point of the seats, and would be undone by a
   tie-break that reached for size or recency instead.

   After the seat, the id: two tasks with the same seat cannot happen,
   and if it ever did the order would still not wobble between redraws. */
/* What a row is called, including when it is not called anything yet.

   Measured and drawn from the same function: the width used to be worked
   out from `one.title` while the drawing showed "loading..." for a task
   that had none, so the two were different strings of different lengths. */
/* The line under a task's name: its weights and its counts.

   Out here rather than inside the drawing, because the in-place update
   needs the same string the drawing would have produced - two copies of
   this would drift the moment one of them learned a new field. */
/* The round's three bars: tasks and projects described, the stages of
   each piece of work, and the patterns and principles named. */
function sbProgressBars(share, said, xp, after) {
  const bar = (label, part, count, aria) => `<div class="sb-progress-row">
      <span class="sb-progress-label">${label}</span>
      <div class="sb-progress-bar" role="img" aria-label="${escapeHtml(aria)}">
        <span style="width:${Math.max(0, Math.min(100, part))}%"></span></div>
      <span class="sb-progress-count">${count}</span></div>`;
  // ALL OF THEM FROM THE START - where each stands even when nothing is
  // being written to it, not only once a round reaches it. The two kinds of
  // nature are grouped apart and at once, so each has its own bar.
  xp = xp || {};
  const sorting = xp.sorting || {};
  const natureBar = (kind, label) => {
    const mine = xp[kind] || {};
    const patterns = Number(mine.patterns || 0);
    const named = Number(mine.named || 0);
    if (Number(sorting.sorting || 0) && !patterns) {
      const sorted = Number(sorting.sorted || 0);
      const of = Number(sorting.sorting || 0);
      return bar(label, Math.round((sorted / of) * 100),
        `sorting ${sorted} of ${of}`, `sorting nature records into kinds`);
    }
    return bar(label, patterns ? Math.round((named / patterns) * 100) : 0,
      patterns ? `${named} of ${patterns} named` : "none yet",
      `${named} of ${patterns} ${label.toLowerCase()} patterns named`);
  };
  // THE STEPS AFTER A ROUND: each kind of lesson - where it stands between
  // rounds, how far while it runs. (Newspaper has none: it
  // runs on its own clock, not in the round - recommend.py.)
  after = after || {};
  const lessons = after.lessons || null;
  const lessonBar = (kind, label) => {
    const mine = (lessons || {})[kind];
    if (!mine) return "";
    const counts = `${Number(mine.active || 0)} in force${Number(mine.forming || 0)
      ? `, ${Number(mine.forming)} forming` : ""}`;
    if (mine.running) {
      return bar(label, Number(mine.share || 0), `${mine.step}${Number(mine.of || 0)
        ? ` (${Number(mine.done || 0)} of ${Number(mine.of)})` : ""}`, `${label}: ${mine.step}`);
    }
    if (mine.failed) return bar(label, 0, `the last cycle failed · ${counts}`, "failed");
    return bar(label, mine.due ? 0 : 100, mine.due
      ? `${Number(mine.waiting || 0) ? `${Number(mine.waiting)} new to learn from`
        : "new to learn from"} · ${counts}`
      : `up to date · ${counts}`, `${label}: ${counts}`);
  };
  // NO STAGES BAR: the state heartbeat does not write stages - they are
  // written in the Experience panel, when asked, with their own bar there.
  return `<div class="sb-progress-bars">${[
    bar("Tasks and projects", share, `${share}%`, said),
    // NO PERSONAL NATURE BAR: nothing writes personal natures now - the
    // heartbeat's step for them is paused, and a stage's natures are work.
    natureBar("work", "Work nature"),
    lessonBar("notifications", "Notification lessons"),
    lessonBar("connections", "Connection lessons"),
    lessonBar("work", "Work nature lessons"),
  ].join("")}</div>`;
}

/* ONE LINE OF DESCRIPTION for every top-level row, task or project: where
   it stands, or what it is when nothing has been said about that yet. */
function sbStatusOf(one, report) {
  const layers = (report && report.layers) || [];
  const held = layers.find((row) => row.id === one.id) || {};
  const said = held.summary || one.summary || {};
  const described = said.described || {};
  return String(described.status || one.status || said.summary || "").trim();
}

function sbAsideFor(one, report) {
  const layers = (report && report.layers) || [];
  const held = layers.find((row) => row.id === one.id) || {};
  // NO WEIGHT, NO NUMBER. These printed the fallback - 4 out of 7, the
  // middle - for a task nobody has judged yet, so an unscored task was
  // indistinguishable from one the model had deliberately called
  // middling. A default dressed as a judgement is worse than none.
  const urgency = sbWeighGiven(held, report, "urgency");
  const importance = sbWeighGiven(held, report, "importance");
  const bits = [];
  if (urgency !== null) bits.push(`urgency ${urgency}/7`);
  if (importance !== null) bits.push(`importance ${importance}/7`);
  // HOW MANY STATES IT HOLDS, and nothing about pieces: a task is not
  // opened onto pieces any more. Every state it has taken, not only the
  // recent ones this round read.
  bits.push(`${Number(one.count || held.count || one.size || 0)} states`);
  if (one.closed) bits.push(`${one.closed} closed`);
  return bits.join(" \u00b7 ");
}

/* A date for the axis: short, and unambiguous about the year.

   Every label carrying a year is noise on a span of three weeks, and no
   label carrying one is a trap on a span that crosses a new year - which
   a calendar of real work does once a year and then looks wrong for
   months. So the year appears exactly where it changes something: when
   the date is not in the same year as the end of the axis. */
function sbWhenShort(when, newest) {
  const day = when.toLocaleDateString(undefined,
    {month: "short", day: "numeric"});
  return when.getFullYear() === newest.getFullYear()
    ? day : `${day} ${when.getFullYear()}`;
}

/* WHAT A ROUND COST: input and output tokens, model calls, and the time it
   took - every visit together, so a round stopped halfway by a quit and
   finished on the next start is counted whole. The last round to finish,
   and the one under way if there is one.

   ITS TIME IS WALL-CLOCK, NOT A SUM. The tasks and projects, the stages of
   the work, and the work and personal patterns run at once; the round took
   as long as it took for all of them to finish. Under it, each part's own
   time and tokens. */
const SB_PARTS = [["tasks", "Tasks and projects"],
  ["work", "Work nature"], ["personal", "Personal nature"],
  ["sorting", "Sorting nature records"]];

function sbTook(value) {
  const seconds = Math.round(Number(value || 0));
  return seconds >= 3600
    ? `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`
    : seconds >= 60 ? `${Math.floor(seconds / 60)}m ${seconds % 60}s`
    : `${seconds}s`;
}

function sbCostLine(round) {
  const number = (value) => Number(value || 0).toLocaleString();
  const said = (spent) => {
    const visits = Number(spent.visits || 0);
    return `<strong>${sbTook(spent.seconds)}</strong> until every part was
      done${visits > 1 ? ` (over ${visits} visits)` : ""},
      <strong>${number(spent.tokens_in)}</strong> input tokens,
      <strong>${number(spent.tokens_out)}</strong> output tokens,
      ${number(spent.calls)} model call${Number(spent.calls) === 1 ? "" : "s"}`;
  };
  const partsOf = (spent) => {
    const parts = spent.parts || {};
    const rows = SB_PARTS.filter(([key]) => parts[key]).map(([key, label]) => {
      const one = parts[key];
      return `<li><span class="sb-part-name">${label}</span>
        <span>${sbTook(one.seconds)}</span>
        <span>${number(one.tokens_in)} in · ${number(one.tokens_out)} out</span>
        <span class="muted">${number(one.calls)} call${
          Number(one.calls) === 1 ? "" : "s"}</span></li>`;
    });
    return rows.length ? `<ul class="sb-parts">${rows.join("")}</ul>` : "";
  };
  const last = round.last_spent || {};
  const now = round.spent || {};
  const parts = [];
  if (last.visits) {
    parts.push(`<p class="muted sb-cost">The last complete round:
      ${said(last)}${last.completed_at
        ? ` - finished ${escapeHtml(clock(last.completed_at))}` : ""}.</p>
      ${partsOf(last)}`);
  }
  if (!round.done && now.visits) {
    parts.push(`<p class="muted sb-cost">This round so far: ${said(now)}.</p>
      ${partsOf(now)}`);
  }
  if (!parts.length) return "";
  return `<div class="sb-cost-block">${parts.join("")}</div>`;
}

function sbProgressStrip(picture) {
    const nodes = ((picture.plan || {}).nodes) || [];
    if (!nodes.length) return "";
    const atWork = Boolean(picture.at_work);
    const named = nodes.filter((one) => one.title).length;
    const layers = picture.layers || [];
    const kids = layers.reduce((sum, one) => sum + (one.children || []).length, 0);
    const kidsNamed = layers.reduce((sum, one) => sum + (one.children || [])
      .filter((kid) => (kid.summary || {}).title).length, 0);
    // The bar is about what the round has to DO. Names alone counted a
    // task that needed nothing as outstanding for ever.
    const work = picture.work || {};
    // THE ROUND'S OWN PLAN: every task and every piece it set out to
    // describe, and every task it only has to bring up to date. Pieces
    // included - a round spends most of its calls on them, and a bar that
    // counted only the top layer stood still for all of that.
    const toDo = Number(work.summarise || 0) + Number(work.status || 0);
    const done = Number(work.summarised || 0)
      + Number(work.status_done || 0);
    // AND THE EXPERIENCE AT THE END - each piece of work's stages, then the
    // patterns and principles named - each on a bar of its own: three
    // kinds of work going at three paces, which one bar would blur.
    const xp = work.experience || {};
    const roundOpen = Boolean((picture.round || {}).started_at)
      && !((picture.round || {}).done);
    // WHICH ROUND THE BAR IS ABOUT. While a visit runs, it is the work
    // being done now. Between rounds there is no work being done - the
    // counts beside it are what the NEXT round will have to do, and
    // none of that has started, so measuring them gave a bar stuck at
    // nought under "7 of 7 tasks named" on a round that had just
    // finished. Between rounds the bar shows how far the folder is
    // described, which is the thing that actually stands still.
    const share = ((picture.at_work || roundOpen) && toDo)
      ? Math.round((done / toDo) * 100)
      : Math.round((named / Math.max(1, nodes.length)) * 100);
    const running = Boolean(picture.running);
    // THE STEP, FOR THE PART BEFORE ANY NAME EXISTS. A round reads its
    // states and groups them before it writes anything, and for that
    // whole stretch "0 of 9 named" on its own is indistinguishable from
    // a panel that has stopped working.
    const busy = Boolean(picture.at_work);
    const open = Boolean((picture.round || {}).started_at)
      && !((picture.round || {}).done);
    // WHAT IT IS DOING, or why nothing is moving. An open round that no
    // visit is working on right now has nothing to pulse, and saying so
    // is the difference between "waiting its turn" and "broken".
    const step = busy
      ? String(picture.stage_detail || picture.stage || "summarizing")
      // NOT "PAUSED", which sounds like something stopped it. The round
      // is open and nothing is executing this second: the visit that was
      // working on it ended, and the next one starts when the agent's own
      // heartbeat next finishes. Naming the thing it is waiting for says
      // more than naming the gap.
      // AN UNFINISHED ROUND IS NOT WAITING ON THE CLOCK. The hours
      // govern when a NEW round may begin; one already open is picked up
      // on the next look, which is a minute away at most. Saying it
      // "waits" invited the reader to wonder what for.
      // WHAT THE AGENT HAS ACTUALLY DECIDED, not a guess at it.
      //
      // This said "picking up again within the minute" for any open
      // round. It was wrong twice: an open round is looked at every two
      // seconds, not every minute - the interval changed and the
      // sentence did not - and a round that has tried everything it can
      // is not picking up again at all, it is waiting out its hours. The
      // gate has already worked this out and says so in `due`; repeating
      // the question here was how the two came to disagree.
      : (open
         // FIRST: COULD IT REACH THE MODEL AT ALL. A round held up by an
         // expired sign-in is not finished trying - it has not started -
         // and "it has tried everything it can" said the opposite of
         // what was true and what to do about it.
         ? ((picture.round || {}).blocked
            ? "paused: the model could not be reached · sign in again "
              + "and it carries on by itself"
            : (picture.due || {}).run
            ? "carrying on in a moment"
            : "it has tried everything it can this round · waiting "
              + "for its hours before another go")
         : "");
    // WHICH KIND OF ROUND, said plainly. One being finished has its
    // grouping and its samples already and writes only the names that
    // are missing; one starting reads every state and groups them again,
    // which is where the long silences come from. They look identical
    // from outside, and they cost quite different amounts.
    const carrying = Boolean((picture.round || {}).carrying_on);
    const kind = open
      ? (carrying
         ? "finishing the round already under way · nothing is "
           + "grouped again"
         : "a new round · reading and grouping every state first")
      : "";
    return `<div class="sb-progress${atWork ? " sb-progress-live" : ""}">
      ${sbProgressBars(share, `${named} of ${nodes.length} tasks named`, xp,
        picture.work || {})}
      <p class="sb-progress-work">${(() => {
        // THE TWO KINDS OF WORK, SEPARATELY. A task whose states have
        // barely moved keeps its summary and is only asked where it
        // stands - a short call. One that is half new, or was never
        // named, is written from nothing. Counting them together gives
        // the same "4 of 9" for two quite different rounds, and the one
        // a reader is waiting on is almost always the writing.
        const work = picture.work || {};
        const bits = [];
        // WORK DONE, OR WORK WAITING - they are different sentences.
        //
        // "0 of 3 summaries written" under "nothing running" describes a
        // round that is not happening as though it had stalled at the
        // start. Nothing is written because nothing is running: what the
        // counts are about, between rounds, is what the NEXT round has
        // to do.
        const busyNow = Boolean(picture.at_work);
        // ONLY WHILE A ROUND IS RUNNING. Its tasks are fixed then, so how
        // many it is describing afresh and how many it is only bringing
        // up to date are facts. Between rounds they are not: this used
        // to say "when it next runs: 1 to describe again, 2 to bring up
        // to date", worked out from the rows as they stand - but the next
        // round first reads every state that has arrived since, and THAT
        // is what decides which tasks have changed enough to describe
        // again. A forecast that leaves out the input that settles it is
        // not one.
        if (busyNow || roundOpen) {
          // WHAT THIS ROUND FOUND, then WHAT IT IS WRITING. The first is
          // decided when the round opens - which tasks are new, which
          // split off or merged, which it kept - and the second is the
          // work that follows from it, counted against the plan the
          // round wrote down rather than worked out afresh each time.
          const found = work.found || {};
          const kinds = [["new", "new"], ["split", "split off"],
                         ["merged", "merged"], ["kept", "kept"]]
            .filter(([key]) => Number(found[key] || 0))
            .map(([key, said]) => `<strong>${Number(found[key])}</strong> ${said}`);
          if (kinds.length) {
            bits.push(`<span class="muted">this round:</span> `
              + kinds.join(", "));
          }
          if (work.summarise) {
            bits.push(`<strong>${Number(work.summarised || 0)} of ${
              Number(work.summarise)}</strong> to summarise`);
          }
          if (work.status) {
            bits.push(`<strong>${Number(work.status_done || 0)} of ${
              Number(work.status)}</strong> status updates`);
          }
          // Each kind of nature's patterns, apart.
          const xpWork = work.experience || {};
          [["work", "work"]].forEach(([kind, said]) => {
            const mine = xpWork[kind] || {};
            if (mine.patterns) {
              bits.push(`<strong>${Number(mine.named || 0)} of ${
                Number(mine.patterns)}</strong> ${said} patterns named`);
            }
          });
        } else {
          // What IS known before the next round: how much is waiting for
          // it. These are states no task has taken yet, and the next
          // round is where they will be placed.
          const waiting = Number(((picture.due || {}).counted || {})
            .waiting || 0);
          if (waiting) {
            bits.push(`<strong>${waiting}</strong> new state${
              waiting === 1 ? "" : "s"} waiting for the next round`);
          }
        }
        const buried = Number(picture.hidden_count || 0);
        if (buried || sbShowingHidden()) {
          bits.push(`<button type="button" class="small secondary"
            data-sb-hidden="${sbShowingHidden() ? "off" : "on"}"
            title="Work activity: the tasks of your work only. Full
                   activity: everything you did - the tasks of leisure too,
                   and the groupings a summary judged not to be a task.">${
              sbShowingHidden() ? "show work activity" : "show full activity"
            }</button>`);
        }
        if (!bits.length) return "";
        return bits.join(" · ");
      })()}</p>
      <p class="sb-progress-said">${atWork
        ? `<span class="sb-spin" aria-hidden="true"></span>`
        : ""}<strong>${named} of ${nodes.length}</strong> tasks named${
        kids ? `, <strong>${kidsNamed} of ${kids}</strong> sub-tasks` : ""}${
        step ? ` · ${escapeHtml(step)}`
             : (running ? "" : " · nothing running")}${
        kind ? ` <span class="muted">· ${escapeHtml(kind)}</span>` : ""}</p>
    </div>`;
}

function sbDoingNow(picture) {
    const which = String(picture.summarising || "");
    if (!which || !picture.at_work) return "";
    const nodes = ((picture.plan || {}).nodes) || [];
    const top = nodes.find((one) => one.id === which)
      || nodes.find((one) => which.startsWith(`${one.id}.`));
    // WHAT, HOW FAR ALONG, AND HOW TO GET TO IT.
    //
    // The pulse marks the task in the drawing, and the drawing can be
    // three thousand pixels wide: measured on the live agent, the task
    // being summarised had its whole span between x=-1996 and x=-1296,
    // which is to say entirely outside a frame starting at 35. A reader
    // cannot be asked to go looking for the thing that tells them
    // something is happening, so it is said here in words - and the line
    // takes them to it.
    // WHICH SUB-TASK, BY NAME, not just that it is one. "In one of its
    // sub-tasks" tells a reader the work is somewhere they cannot see;
    // naming it tells them what is being written.
    const inside = (() => {
      if (!top || which === top.id) return "";
      const look = (rows) => {
        for (const row of rows || []) {
          if (row.id === which) return (row.summary || {}).title || "";
          const found = look(row.children);
          if (found) return found;
        }
        return "";
      };
      const layer = (picture.layers || []).find((one) => one.id === top.id);
      const name = look((layer || {}).children);
      return name ? `, its sub-task ${name}` : ", in one of its sub-tasks";
    })();
    const named = top && top.title
      ? `: ${top.title}`
      : ": a task that has no name yet";
    const deeper = inside;
    const done = nodes.filter((one) => one.title).length;
    // AND HOW MANY AT ONCE, with why that many: the machine is looked at
    // before each call starts, and the reader can see what it found.
    const others = Math.max(0, (picture.summarising_all || [])
      .filter((one) => one && one !== which).length);
    const atOnce = picture.at_once || {};
    const together = Number(atOnce.running) > 1
      ? ` <span class="muted">&middot; ${Number(atOnce.running)} at once${
          atOnce.why ? ` (${escapeHtml(String(atOnce.why))})` : ""}</span>`
      : atOnce.why && Number(atOnce.allowed) === 1
        ? ` <span class="muted">&middot; one at a time (${escapeHtml(
            String(atOnce.why))})</span>` : "";
    return `<p class="sb-doing-now"><span class="sb-spin"
      aria-hidden="true"></span>Summarizing now${escapeHtml(named)}${
      deeper}${others ? ` and ${others} more` : ""}${together} <span class="muted">&middot; ${done} of ${
      nodes.length} named</span>${top ? ` <button type="button"
      class="small secondary" data-sb-findit="${escapeHtml(String(top.id))}"
      >show me</button>` : ""}</p>`;
}

function sbNameOf(one) {
  // A NAME BEATS A STATUS. A task whose sub-task is being summarised is
  // working, and it already has a name - replacing that name with
  // "working..." would take away the one thing that says WHICH work is
  // going on. The pulse says it is working; the words say what it is.
  if (one.title) return String(one.title);
  // NO NAME YET, and the placeholder says which kind of no-name it is:
  // "summarizing" while a model is being asked about this very task,
  // "preparing" for one whose turn has not come. They were "working" and
  // "loading", which said how the PAGE felt rather than what the agent
  // was doing.
  //
  // And never the id. `task_4` is what this round happens to call its
  // fourth row; printing it where a name goes offers the reader something
  // that looks like an answer and tells them nothing.
  if (one.working) return "summarizing…";
  return "preparing…";
}

/* The weight a task was actually given, or nothing at all.

   `sbWeighOf` answers 4 where there is none, which is right for SORTING -
   every row needs a place - and wrong for showing, because 4 is also a
   real answer the model gives when the states say nothing. This one tells
   the two apart. */
function sbWeighGiven(task, report, which) {
  let summary = (task || {}).summary || {};
  if (summary[which] === undefined && task && task.id && report) {
    const layer = (report.layers || []).find((one) => one.id === task.id);
    summary = (layer || {}).summary || {};
  }
  let mark = Number(summary[which]);
  if (!Number.isFinite(mark)) mark = Number((summary.described || {})[which]);
  return Number.isFinite(mark) && mark >= 1 && mark <= 7 ? mark : null;
}

function sbWeighOf(task, report, which) {
  // FOUND BY ID WHERE IT IS NOT CARRIED. This read `task.summary`, and
  // the ordering hands it PLAN NODES - which have an id, a span and a
  // size, and no summary at all. So every task scored the default 4, the
  // sort found nothing to separate them, and "in order of urgency" was
  // the order they already happened to be in.
  let summary = (task || {}).summary || {};
  if (summary[which] === undefined && task && task.id && report) {
    const layer = (report.layers || []).find((one) => one.id === task.id);
    summary = (layer || {}).summary || {};
  }
  let mark = Number(summary[which]);
  if (!Number.isFinite(mark)) {
    mark = Number((summary.described || {})[which]);
  }
  return Number.isFinite(mark) && mark >= 1 && mark <= 7 ? mark : 4;
}

function sbInOrder(tasks, report) {
  const which = stateBeat.sortBy === "importance" ? "importance" : "urgency";
  const seatOf = new Map((tasks || []).map((one, index) =>
    [one.id, Number(one.seat !== undefined ? one.seat : index)]));
  return [...(tasks || [])].sort((a, b) => {
    const gap = sbWeighOf(b, report, which) - sbWeighOf(a, report, which);
    if (gap) return gap;
    const seats = (seatOf.get(a.id) || 0) - (seatOf.get(b.id) || 0);
    if (seats) return seats;
    return String(a.id).localeCompare(String(b.id));
  });
}

/* How much of the calendar to show at once.

   A quarter of a year across the width of a panel puts a week inside
   four pixels: every task starts in the same place and every span is the
   same length, which is a picture of nothing. So the axis holds a window
   - a fortnight by default - and the reader picks a wider or narrower
   one, or drags the window back through time.

   `all` is offered and is not the default, for the same reason: it is
   the view that answers "how long has this been going on" and no other
   question. */

/* How much bigger or smaller the picture is drawn.

   The viewBox never changes with this - only the pixel size the browser
   paints it at - so zooming in makes everything larger together and
   nothing reflows: the names stay where they are relative to their
   circles, which is the whole point of doing it here rather than by
   changing the layout.

   Ctrl and + or -, which is what a browser uses for the same job, and
   only while the pointer is over the picture. Taking that key everywhere
   on the page would steal the browser's own zoom from a reader who
   wanted it. */
function sbTreeZoom() {
  const said = Number(stateBeat.treeZoom);
  return Number.isFinite(said) && said > 0 ? said : 1;
}

/* Zoom, applied to the drawing that is already there.

   A zoom changes nothing about WHERE anything is - the viewBox is
   untouched and every coordinate in it stays as it was. All that changes
   is how many screen pixels one of those coordinates takes up, which is
   two numbers in the element's style. Redrawing for that threw away every
   element and played every animation again, which is why zooming looked
   like the picture being rebuilt: it was.

   Returns whether there was a drawing to resize. */
function sbSizeToZoom(host) {
  const svg = host && host.querySelector(".sb-whole-graph");
  if (!svg) return false;
  const box = (svg.getAttribute("viewBox") || "").split(/[\s,]+/).map(Number);
  if (box.length < 4 || !box[2] || !box[3]) return false;
  const size = sbTreeZoom();
  svg.style.width = `${(box[2] * size).toFixed(0)}px`;
  svg.style.height = `${(box[3] * size).toFixed(0)}px`;
  svg.dataset.sbZoom = String(size);
  // The axis is placed from the scroll and the zoom together, so it is
  // the one thing that has to be worked out again.
  sbPinTheAxis(svg);
  return true;
}

function sbZoomTreeBy(factor) {
  const now = sbTreeZoom();
  // Between a third and four times, which is as far as either direction
  // is worth going: smaller than a third and the names are unreadable,
  // larger than four and one task fills the frame.
  stateBeat.treeZoom = Math.max(0.34, Math.min(4, now * factor));
  // BOTH PICTURES, RESIZED RATHER THAN REDRAWN. A redraw here changed the
  // number and rebuilt the drawing; resizing changes the two numbers that
  // actually differ. Where there is no drawing to resize - a panel that
  // has not been opened yet - the ordinary redraw is what sets it up.
  let touched = false;
  ["#ov-tasks", "#dbg-statebeat-body"].forEach((which) => {
    if (sbSizeToZoom($(which))) touched = true;
  });
  if (!touched) sbRedrawPictures();
}

/* HOW FAR BACK THE OVERVIEW LOOKS: only work touched in the last so many
   days. A task last worked on in August is still a task, and still
   carried on if it is picked up again; it is not what somebody opening
   the overview wants to read past to get to this week. Starts at a week
   each time the page is opened. */
const SB_RECENT_DAYS = [1, 7, 15, 30, 180];

function sbRecentDays() {
  // 0 is no window at all - never offered, but what a picture of fixed
  // dates is drawn with when it is the drawing, not the dates, in question.
  if (stateBeat.recentDays === 0) return 0;
  return SB_RECENT_DAYS.includes(stateBeat.recentDays)
    ? stateBeat.recentDays : 7;
}

function sbRecentBar() {
  const which = sbRecentDays();
  return `<span class="sb-sort-bar sb-recent-bar"><span class="muted">active in
    the last</span>
    ${SB_RECENT_DAYS.map((days) => `<button type="button" class="small${
      which === days ? "" : " secondary"} sb-sort" data-sb-recent="${days}"
      title="Only tasks worked on in the last ${days} day${
        days === 1 ? "" : "s"}">${days === 1 ? "1 day" : `${days} days`}</button>`
    ).join("")}</span>`;
}

/* The picture with only what was worked on inside the window. The axis
   is worked out again from what is left, so a week is drawn as a week. */
function sbOnlyRecent(picture) {
  if (!picture) return picture;
  const days = sbRecentDays();
  if (!days) return picture;
  const since = Date.now() - days * 86400000;
  const plan = picture.plan || {};
  const every = plan.nodes || [];
  const recent = (one) => {
    const last = new Date(one.ended || one.began || "").getTime();
    return !Number.isFinite(last) || last >= since;
  };
  const kept = every.filter(recent);
  const ids = new Set(kept.map((one) => String(one.id)));
  const out = Object.assign({}, picture, {recent_days: days,
                                         recent_left_out: every.length - kept.length});
  out.plan = Object.assign({}, plan, {
    nodes: kept,
    edges: (plan.edges || []).filter((edge) =>
      ids.has(String(edge.before)) && ids.has(String(edge.after))),
  });
  out.layers = (picture.layers || []).filter((one) =>
    ids.has(String(one.id)));
  return out;
}

function sbSortBar() {
  const which = stateBeat.sortBy === "importance" ? "importance" : "urgency";
  const one = (key, said, why) =>
    `<button type="button" class="small${
      which === key ? "" : " secondary"} sb-sort" data-sb-sort="${key}"
      title="${escapeHtml(why)}">${said}</button>`;
  return `<span class="sb-sort-bar"><span class="muted">in order of</span>
    ${one("urgency", "urgency", "How soon it needs doing - a deadline, "
          + "something blocked on it, or several sittings running")}
    ${one("importance", "importance", "How much rests on it - a commitment "
          + "to someone else, or work that others depend on")}
    <span class="muted">ties keep the order they had</span></span>`;
}

/* A task's name, whole, over one line or two.

   Never shortened. A name cut at forty characters loses the part that
   tells one task from another - "Answer reviewer 2 on the weighting
   paper's method section" and "Answer reviewer 2 on the weighting
   paper's figures" are the same string for the first forty-three - and
   the naming rules in the prompt spend paragraphs getting the
   particulars in there. Throwing them away at the last step would make
   all of that pointless.

   So it wraps instead, at a space, as near the middle as a space
   allows; and if the whole thing will not go in two lines it goes in
   two long ones rather than losing anything. The canvas is widened to
   hold the longest of them and the frame scrolls - the picture is drawn
   at a fixed size and is never squeezed to fit, which is what turned it
   into a thumbnail as soon as a few tasks were open. */
const SB_NAME_CHARS = 46;

function sbWrapName(said, most) {
  const text = String(said || "").trim();
  const cap = Number(most || SB_NAME_CHARS);
  if (text.length <= cap) return [text];
  // BROKEN NEAR THE MIDDLE, not at the last space that fits. Filling the
  // first line and letting the rest fall onto the second gives a long
  // line over a stub - "Answer reviewer 2 on the method section of the" /
  // "weighting paper" - which reads as two unrelated things rather than
  // one sentence, and makes the block wider than it needs to be: the
  // drawing is sized by the LONGEST line, so balancing the two shortens
  // the picture as well as tidying it.
  const mid = text.length / 2;
  let best = -1;
  for (let at = 0; at < text.length; at += 1) {
    if (text[at] !== " ") continue;
    if (best < 0 || Math.abs(at - mid) < Math.abs(best - mid)) best = at;
  }
  if (best <= 0) return [text];
  let first = text.slice(0, best);
  let second = text.slice(best + 1);
  // Unless balancing leaves a line longer than the cap - a name with one
  // very long word in it - in which case the cap wins, because the width
  // was measured against it.
  if (first.length > cap || second.length > cap) {
    const cut = text.lastIndexOf(" ", cap);
    if (cut > 0) {
      first = text.slice(0, cut);
      second = text.slice(cut + 1);
    }
  }
  return [first, second];
}

/* About how wide a piece of text will be. Measured text would mean
   laying it out first; this is close enough to size a canvas, and the
   canvas only has to be big enough, not exact. */
function sbTextWide(said, per) {
  return String(said || "").length * (per || 6.3);
}

/* What is running now, on the overview.

   THE SAME DRAWING FUNCTION as the debugger's, fed a trimmed version of
   the same round under the same key names. A second function for the
   second place is how the two would drift: one would learn about a new
   layer or a changed field and the other would not, and the one nobody
   was testing would be the one on the page people actually open. */
/* The detail panel belonging to the picture a click landed in.

   The picture is drawn on the overview and in the debugger, and each has
   its own panel under it. Naming one by id - which is what this replaced
   - meant a click in either place wrote into the debugger's, so on the
   overview nothing appeared to happen. */
/* Redraw wherever the tree is drawn, not only in the debugger.

   `renderStateBeat` rewrites the debugger's panel, which was the only
   place this picture existed when the sort buttons were written. On the
   overview the flag changed and nothing moved, so the buttons looked
   dead - the order they had just chosen was still the old one. */
function sbRedrawPictures() {
  renderStateBeat();
  const host = $("#ov-tasks");
  // FROM THE WHOLE PICTURE, not the one on screen. What is on screen has
  // the rejected groupings taken out, so redrawing from it - opening a
  // project, say - counted none hidden and dropped the button that shows
  // them.
  const whole = stateBeat.whole || (host && host.sbReport);
  if (host && whole) drawWhatIsRunning(whole);
}

function sbCardNear(target) {
  const host = target && target.closest
    ? target.closest("#ov-tasks, #dbg-statebeat-body, .sb-whole-tree")
    : null;
  return (host || document).querySelector("[data-sb-card]");
}

/* A name landing, written into the drawing that is already there.

   THE PICTURE IS NOT REBUILT FOR A WORD. Replacing the host's HTML
   replaces every element in it, and that does three things a reader
   notices: every CSS animation starts again from nothing - which is the
   whole tree appearing to replay - the scroll position is lost and has
   to be put back, which is a visible jump, and anything unfolded is
   rebuilt. A round names one task at a time, so this was happening
   several times a minute while somebody was reading.

   What actually changes between those draws is small: a name, the line
   under it, which node is being worked on. Those are written into the
   elements that already exist. Anything larger - a different set of
   tasks, a different order - is a different picture and is drawn as one.

   Returns whether it could do the whole job. */
function sbWriteInPlace(host, picture) {
  const svg = host.querySelector(".sb-whole-graph");
  if (!svg) return false;
  const nodes = ((picture.plan || {}).nodes) || [];
  const rows = [...svg.querySelectorAll("[data-sb-task]")];
  if (nodes.length < 1 || rows.length !== nodes.length) return false;
  // A CHANGE OF ZOOM IS NOT A CHANGE OF NAME. Every coordinate in the
  // drawing is multiplied by it, so it is a new drawing - and it is a
  // deliberate, occasional act, which is exactly when redrawing costs
  // nothing. Writing names in place while ignoring this made zooming do
  // nothing at all.
  if (Math.abs(Number(svg.dataset.sbZoom || 1) - sbTreeZoom()) > 0.001) {
    return false;
  }

  // THE SAME TASKS IN THE SAME ORDER, or this is a different picture.
  // Order matters because the rows are placed by it: a sort would move
  // every circle, which is a redraw by any measure.
  const held = new Map();
  for (let at = 0; at < rows.length; at += 1) {
    const row = rows[at];
    const one = nodes[at];
    if (!one || String(one.id) !== row.dataset.sbTask) return false;
    held.set(row, one);
  }

  const zoom = sbTreeZoom();
  held.forEach((one, row) => {
    const label = row.querySelector(".sb-tt-label");
    const first = label && label.querySelector(".sb-tt-name");
    const name = sbNameOf(one);
    if (label && first && label.textContent !== name) {
      // The lines are rewritten, not the row: the row carries the
      // transform and the animation state, and replacing it is what
      // made the tree replay.
      const x = first.getAttribute("x");
      const y = Number(first.getAttribute("y"));
      const fill = first.getAttribute("fill");
      label.innerHTML = sbWrapName(name).map((line, at) =>
        `<text x="${x}" y="${y + at * 13}" fill="${fill}"
           class="sb-tt-name">${escapeHtml(line)}</text>`).join("");
    }
    const aside = row.querySelector(".sb-tt-aside");
    if (aside) {
      const said = sbAsideFor(one, picture);
      if (aside.textContent !== said) aside.textContent = said;
      // AND IT MOVES WITH THE NAME. The line under a name sits below the
      // LAST line of it, and a name landing can turn one line into two -
      // "loading..." is short and "Answer reviewer 2 on the method
      // section of the weighting paper" is not. Rewriting the name
      // without moving this left the weights printed through the second
      // line of the title.
      const cy = Number(row.dataset.sbCy || 0);
      const lines = sbWrapName(sbNameOf(one)).length;
      aside.setAttribute("y", String(cy + 1 + lines * 13));
    }
    row.classList.toggle("sb-tt-working", Boolean(one.working));
  });

  // What is unfolded is laid out again - rows may have moved if a name
  // grew to two lines - but the branches themselves are only rebuilt
  // when what they are drawn from has changed.
  svg.closest(".sb-tree-frame");
  if (stateBeat.openTasks instanceof Set && stateBeat.openTasks.size) {
    sbUnfold(svg, picture, stateBeat.openTasks);
  }
  host.sbReport = picture;
  // AND THE WORDS ABOVE THE DRAWING.
  //
  // This updated the picture and nothing else, so the strip kept
  // whatever it said when the panel was last built from scratch: a
  // round would start, every circle would move, and the line above
  // them still read "when it next runs". The counts are the part a
  // reader checks; they cannot be the stale part.
  const strip = host.querySelector(".sb-progress");
  if (strip) {
    const fresh = document.createElement("div");
    fresh.innerHTML = sbProgressStrip(picture);
    const made = fresh.firstElementChild;
    if (made) strip.replaceWith(made);
  }
  // Into its slot, which stays put: the line may come and go, the room
  // for it does not.
  const slot = host.querySelector(".sb-doing-slot");
  if (slot) slot.innerHTML = sbDoingNow(picture) || "";
  return true;
}

/* WHETHER TO DRAW THE GROUPINGS A SUMMARY REJECTED.

   Off by default, because they are heaps the clustering happened to
   make and a reader looking for their own work does not want them. On
   when somebody is asking WHY a count is what it is - which is most of
   the time the question, and the answer used to be invisible: the rows
   were dropped before the page saw them, so "nine tasks" and "four
   tasks" could not be reconciled from anything on screen. */
function sbShowingHidden() {
  // HIDDEN UNLESS ASKED, every time the page opens. Remembering "show"
  // for good meant one click to look made it the page's default from
  // then on; it now lasts until the page is loaded again.
  return Boolean(typeof stateBeat !== "undefined" && stateBeat.showHidden);
}

function sbOnlyShown(picture) {
  // A PICTURE THAT IS NOT THERE YET. The panel draws before the first
  // answer arrives, and this now stands between every caller and that
  // case - so it has to pass it through rather than reach into it.
  if (!picture || sbShowingHidden()) return picture;
  const out = Object.assign({}, picture);
  const plan = picture.plan || {};
  const every = plan.nodes || [];
  const moments = (key) => every.map((one) => new Date(one[key]).getTime())
    .filter(Number.isFinite);
  const starts = moments("began");
  const ends = moments("ended");
  // WORK ACTIVITY: the tasks of work only - not what a summary judged not
  // to be a task, and not the tasks of leisure. Full activity is all of it.
  out.plan = Object.assign({}, plan, {
    nodes: every.filter((one) => !one.hidden && !one.leisure),
    // The time axis of the whole, so hiding rows leaves it where it was.
    span: starts.length
      ? [Math.min(...starts), Math.max(...ends, ...starts)] : null,
  });
  out.layers = (picture.layers || []).filter((one) => !one.hidden && !one.leisure);
  return out;
}

/* TASKS AND PROJECTS (section 34.5). The projects, each with how long it
   was actually worked on: shown when worked on inside the chosen days and
   for at least the chosen time. Click one for its tasks. */
const PJ_LEAST_MINUTES = [15, 60, 360, 1440];

function pjLeastMinutes() {
  let said = 15;
  try {
    said = Number(localStorage.getItem("pa.projects.least") || 15);
  } catch (err) { /* private window: the default */ }
  return PJ_LEAST_MINUTES.includes(said) ? said : 15;
}

function pjHours(minutes) {
  const m = Math.round(Number(minutes) || 0);
  if (m < 60) return `${m} min`;
  const hours = m / 60;
  return `${hours < 10 ? hours.toFixed(1) : Math.round(hours)} h`;
}

function pjLeastBar() {
  const which = pjLeastMinutes();
  const named = { 15: "15 min", 60: "1 hour", 360: "6 hours", 1440: "1 day" };
  return `<span class="sb-sort-bar pj-least-bar"><span class="muted">worked on
    at least</span>
    ${PJ_LEAST_MINUTES.map((minutes) => `<button type="button" class="small${
      which === minutes ? "" : " secondary"} sb-sort" data-pj-least="${minutes}"
      >${named[minutes]}</button>`).join("")}</span>`;
}

function pjWhen(iso) {
  const at = Date.parse(iso || "");
  if (Number.isNaN(at)) return "";
  return new Date(at).toLocaleString([], { month: "short", day: "numeric",
                                            hour: "2-digit", minute: "2-digit" });
}

/* One colour per project, from its id - the same wherever it is drawn and
   whatever order the rows are in. */
function pjColour(id) {
  let sum = 0;
  for (const ch of String(id || "")) sum = (sum * 31 + ch.charCodeAt(0)) % 9973;
  return sbColour(sum, true);
}

function pjSpan(task) {
  const end = Date.parse(task.ends_at || "");
  const start = Date.parse(task.starts_at || "") || end;
  return [start, Number.isNaN(end) ? start : end];
}

/* THE PICTURE, as the tasks' one was: a row per project, its tasks as bars
   where they were worked on, the days along the top. Longest worked on
   first; with full activity the leisure ones under the work, apart, on the
   same days. */
function pjChart(projects, since, open) {
  const spans = projects.flatMap((one) => (one.tasks || []).map(pjSpan))
    .filter(([start]) => Number.isFinite(start));
  const DAY = 86400000;
  const high = Math.max(Date.now(), ...spans.map(([, end]) => end));
  const low = since || Math.min(high - DAY, ...spans.map(([start]) => start));
  const at = (ms) => Math.max(0, Math.min(100, ((ms - low) / (high - low)) * 100));
  const days = [];
  const first = new Date(low);
  first.setHours(24, 0, 0, 0);
  for (let day = first.getTime(); day < high; day += DAY) days.push(day);
  const every = Math.max(1, Math.ceil(days.length / 8));
  const grid = days.map((day) => `<span class="pj-grid" style="left:${at(day).toFixed(2)}%"></span>`)
    .join("");
  const axis = days.map((day, n) => (n % every ? "" : `<span class="pj-tick"
      style="left:${at(day).toFixed(2)}%">${escapeHtml(new Date(day).toLocaleDateString([],
      { month: "short", day: "numeric" }))}</span>`)).join("");
  const row = (one) => {
    const colour = pjColour(one.id);
    const bars = (one.tasks || []).map((task) => {
      const [start, end] = pjSpan(task);
      if (!Number.isFinite(start) || end < low) return "";
      const left = at(start);
      const wide = Math.max(0.8, at(end) - left);
      const said = `${task.title_display || task.title || ""} - ${pjHours(task.minutes)}, ${
        pjWhen(task.starts_at)} to ${pjWhen(task.ends_at)}`;
      return `<span class="pj-bar" style="left:${left.toFixed(2)}%;width:${wide.toFixed(2)}%;
        background:${colour}" title="${escapeHtml(said)}"></span>`;
    }).join("");
    return `<div class="pj-crow${one.id === open ? " open" : ""}${one.dormant ? " dormant" : ""}"
        data-pj-open="${escapeHtml(one.id)}" role="button" tabindex="0"
        aria-expanded="${one.id === open}">
      <div class="pj-cname"><span class="pj-disc" style="background:${colour}"></span>
        <span class="pj-cname-text"><strong>${escapeHtml(one.title || "")}</strong>
        <span class="muted">${pjHours(one.minutes)}${one.dormant ? " · dormant" : ""}</span>
        </span></div>
      <div class="pj-ctrack">${grid}${bars}</div>
    </div>`;
  };
  const longest = (a, b) => Number(b.minutes || 0) - Number(a.minutes || 0);
  const work = projects.filter((one) => one.kind !== "leisure").sort(longest);
  const leisure = projects.filter((one) => one.kind === "leisure").sort(longest);
  // Both named when both are there, so which is which is never left to
  // the reader.
  const rows = (leisure.length && work.length
    ? `<div class="pj-section pj-section-first" role="separator">Work</div>` : "")
    + work.map(row).join("") + (leisure.length
    ? `<div class="pj-section" role="separator">Leisure</div>${leisure.map(row).join("")}`
    : "");
  return `<div class="pj-chart">
    <div class="pj-crow pj-axis-row"><div class="pj-cname"></div>
      <div class="pj-ctrack pj-axis">${axis}</div></div>
    ${rows}
  </div>`;
}

/* The open project's card, under the picture, as a task's card was: what
   it is, what is being worked on in it now, since when and how long, and
   where. A project has no tasks under it to list - the bars in the picture
   are when it was worked on. */
function pjCard(one) {
  if (!one) {
    return `<p class="muted sb-card-empty sb-click-hint">Click a project above to read it
      here.</p>`;
  }
  const dirs = (one.directories || []).slice(0, 6)
    .map((dir) => `<code>${escapeHtml(dir)}</code>`).join(" ");
  return `<div class="pj-card" style="border-left-color:${pjColour(one.id)}">
    <p class="sb-card-title">${escapeHtml(one.title || "")}</p>
    <p class="muted">Since ${escapeHtml(pjWhen(one.first_seen))} · last active
      ${escapeHtml(pjWhen(one.last_seen))} · ${pjHours(one.minutes)} worked on${
      one.kind === "leisure" ? " · leisure" : ""}${one.dormant ? " · dormant" : ""}</p>
    ${one.what_it_is ? `<p class="sb-card-part"><span class="event-label">What it is</span>
      ${escapeHtml(one.what_it_is)}</p>` : ""}
    ${one.summary ? `<p class="sb-card-part"><span class="event-label">Being worked on</span>
      ${escapeHtml(one.summary)}</p>` : ""}
    ${dirs ? `<p class="sb-card-part pj-dirs"><span class="event-label">Where</span>
      ${dirs}</p>` : ""}
  </div>`;
}

function drawProjects(whole) {
  const host = $("#ov-tasks");
  if (!host) return;
  stateBeat.whole = whole;
  const days = sbRecentDays();
  const since = days ? Date.now() - days * 86400000 : 0;
  const least = pjLeastMinutes();
  // WORK ACTIVITY, OR FULL: the leisure projects are shown only when asked,
  // as the tasks of leisure were.
  const full = sbShowingHidden();
  // ONE THAT ENDED is drawn while it has history of its own: one carried on
  // gave its tasks to the project carrying it, one carried on by none kept
  // the tasks before the window (section 34.5).
  const every = (whole.projects || []).filter((one) => !one.ended || (one.tasks || []).length);
  const leisure = every.filter((one) => one.kind === "leisure").length;
  const toggle = leisure || full ? `<button type="button" class="small secondary"
      data-sb-hidden="${full ? "off" : "on"}"
      title="Work activity: the projects of your work only. Full activity: the
             projects of leisure too.">${full ? "show work activity"
      : "show full activity"}</button>` : "";
  const bars = `<div class="pj-bars">${sbRecentBar()} ${pjLeastBar()} ${toggle}</div>`;
  if (!every.length) {
    const due = whole.due || {};
    host.innerHTML = `${bars}<p class="muted">No project yet. ${
      escapeHtml(due.why || "The first run writes the last week's tasks.")}</p>`;
    return;
  }
  const shown = every.filter((one) => (full || one.kind !== "leisure")
    && (Date.parse(one.last_seen || "") || 0) >= since
    && Number(one.minutes || 0) >= least);
  const open = stateBeat.openProject || "";
  const hidden = every.length - shown.length;
  host.innerHTML = `${bars}${shown.length ? pjChart(shown, since, open)
      : `<p class="muted">No project in this range.</p>`}
    ${hidden ? `<p class="muted pj-hidden">${hidden} more outside the range, worked on
      for less${full ? "" : ", or of leisure"}.</p>` : ""}
    ${pjCard(shown.find((one) => one.id === open))}`;
}

document.addEventListener("click", (event) => {
  const least = event.target.closest && event.target.closest("[data-pj-least]");
  if (least) {
    event.preventDefault();
    try {
      localStorage.setItem("pa.projects.least", least.dataset.pjLeast);
    } catch (err) { /* private window: for this page only */ }
    if (stateBeat.whole && stateBeat.whole.scheme === "projects") drawProjects(stateBeat.whole);
    return;
  }
  const row = event.target.closest && event.target.closest("[data-pj-open]");
  if (row && !event.target.closest("a") && !event.target.closest("button")) {
    stateBeat.openProject = stateBeat.openProject === row.dataset.pjOpen
      ? "" : row.dataset.pjOpen;
    if (stateBeat.whole && stateBeat.whole.scheme === "projects") drawProjects(stateBeat.whole);
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  const row = event.target.closest && event.target.closest("[data-pj-open]");
  if (!row || event.target !== row) return;
  event.preventDefault();
  row.click();
});

/* THE TASK PANEL (debugger): what a run of tasks and projects did - each
   stretch it wrote, with what was sent and what came back - and every
   project as one row over time: since when, how long worked on, where it
   came from, and its tasks along the row; click a task to read it. */
function pjDebugPanel(report) {
  const stretches = (report.stretches || []).map((one, n) => {
    const tasks = (one.tasks || []).map((task) => `<li>${escapeHtml(task.title || "")}
      <span class="muted">${escapeHtml(task.kind || "")} · ${pjHours(task.minutes)}
      · ${(task.states || []).length} state(s)${task.continues ? " · continues a project" : ""}</span></li>`)
      .join("");
    const lines = Object.keys(one.lines || {}).length
      ? `<p class="muted">Lines written: ${Object.values(one.lines).map((line) =>
        escapeHtml(line.line || "")).join(" | ")}</p>` : "";
    return `<details class="pj-stretch"${n === (report.stretches || []).length - 1 ? " open" : ""}>
      <summary>${escapeHtml(pjWhen(one.from))} - ${escapeHtml(pjWhen(one.to))}:
        ${one.states} state(s), ${(one.tasks || []).length} task(s)
        ${one.seconds ? `<span class="muted">${one.seconds}s</span>` : ""}</summary>
      <ul>${tasks}</ul>${lines}
      <details><summary class="muted">Sent</summary><pre class="pj-pre">${escapeHtml(one.sent || "")}</pre></details>
      <details><summary class="muted">Reply</summary><pre class="pj-pre">${escapeHtml(one.reply || "")}</pre></details>
    </details>`;
  }).join("");
  const whole = (stateBeat.whole && stateBeat.whole.scheme === "projects") ? stateBeat.whole : null;
  const projects = whole ? whole.projects || [] : [];
  const times = [];
  projects.forEach((one) => (one.tasks || []).forEach((task) => {
    const at = Date.parse(task.ends_at || "");
    if (!Number.isNaN(at)) times.push(at);
  }));
  const low = Math.min(...times);
  const high = Math.max(...times);
  const span = Math.max(1, high - low);
  const picked = stateBeat.pjTask || "";
  const rows = projects.map((one) => {
    const born = one.born_of || {};
    // Carrying on (section 34.5): a project's earlier ones, by id or anew;
    // the ones before it called merged and split.
    const came = (born.from || []).length && born.kind !== "continued"
      ? `carries on ${born.from.length}` : born.kind === "merged"
        ? `merged from ${(born.from || []).length}` : born.kind === "split"
          ? "split from another" : "";
    const went = one.ended ? (born.joined_into ? " · carried on" : " · ended") : "";
    // Found again among the stopped ones (section 34.5), with the model's why.
    const back = [born.came_back, ...(born.carries_back || []), born.relinked].filter(Boolean);
    const backed = back.length ? ` · <span title="${escapeHtml(back.map((one) => one.why || "")
      .join(" / "))}">${born.came_back ? "came back" : `linked to ${back.length} earlier`}</span>` : "";
    const dots = (one.tasks || []).map((task) => {
      const at = Date.parse(task.ends_at || "");
      if (Number.isNaN(at)) return "";
      const left = ((at - low) / span) * 100;
      const key = `${one.id}|${task.id}`;
      return `<button type="button" class="pj-dot${picked === key ? " on" : ""}"
        style="left:${left.toFixed(2)}%" data-pj-task="${escapeHtml(key)}"
        title="${escapeHtml(task.title || "")}"></button>`;
    }).join("");
    const open = (one.tasks || []).find((task) => picked === `${one.id}|${task.id}`);
    return `<div class="pj-line">
      <div class="pj-line-head"><strong>${escapeHtml(one.title || "")}</strong>
        <span class="muted">since ${escapeHtml(pjWhen(one.first_seen))} ·
          ${pjHours(one.minutes)} worked${came ? ` · ${came}` : ""}${went}${backed}${one.dormant ? " · dormant" : ""}</span>
        <div class="muted">${escapeHtml(one.what_it_is || "")}</div></div>
      <div class="pj-track">${dots}</div>
      ${open ? `<div class="pj-task-open"><strong>${escapeHtml(open.title || "")}</strong>
        <span class="muted">${pjHours(open.minutes)} · ${escapeHtml(pjWhen(open.starts_at))}
          - ${escapeHtml(pjWhen(open.ends_at))} · ${(open.states || []).length} state(s)</span>
        <p>${escapeHtml(open.summary || "")}</p>
        ${open.summary_display && open.summary_display !== open.summary
          ? `<p class="muted">${escapeHtml(open.summary_display)}</p>` : ""}</div>` : ""}
    </div>`;
  }).join("");
  const switched = report.switched
    ? `<p class="muted">Switched to tasks and projects ${escapeHtml(pjWhen(report.switched.at))}:
        ${(report.switched.kept_as_history || {}).tasks || 0} earlier task(s) and
        ${(report.switched.kept_as_history || {}).projects || 0} project(s) kept as history.</p>` : "";
  return `${stateBeatStage(report)}
    <p>${report.states_read || 0} state(s) read, ${report.calls || 0} call(s),
      ${report.tokens_in || 0} tokens in, ${report.tokens_out || 0} out.
      ${report.note ? escapeHtml(report.note) : ""}
      ${report.blocked ? `<span class="error">${escapeHtml(report.blocked)}</span>` : ""}
      ${report.error ? `<span class="error">${escapeHtml(report.error)}</span>` : ""}</p>
    ${switched}
    <h4>Stretches written</h4>${stretches || `<p class="muted">None this run.</p>`}
    <h4>Projects over time</h4>
    ${rows || `<p class="muted">Open the Overview once to load the projects.</p>`}`;
}

document.addEventListener("click", (event) => {
  const dot = event.target.closest && event.target.closest("[data-pj-task]");
  if (!dot) return;
  event.preventDefault();
  stateBeat.pjTask = stateBeat.pjTask === dot.dataset.pjTask ? "" : dot.dataset.pjTask;
  renderStateBeat();
});

function drawWhatIsRunning(whole) {
  if (whole && whole.scheme === "projects") {
    drawProjects(whole);
    return undefined;
  }
  // WHERE THE READER HAD SCROLLED TO, kept. A redraw makes the picture anew,
  // and a wide one scrolled to its right-hand end went back to the left
  // every time the data moved.
  const host = $("#ov-tasks");
  const held = host ? sbScrollsIn(host) : [];
  const out = drawWhatIsRunningNow(whole);
  sbMarkSelected();
  if (host) sbScrollsBack(host, held);
  ovPlaceTodos();
  return out;
}

/* TO DO, on the Overview: what the user took off a notification to do later
   ("Add to to-do"), right of the Summary task's progress bars. Only the
   user takes one off - x, then "Remove it? Yes / No"; the agent never marks
   one done (its to-do step ticks a task's next steps, not these). Only the
   open ones are shown. */
let ovTodos = [];
let ovTodoDrawn = "";                     // what the box was last written with

async function loadTodos() {
  try {
    ovTodos = (await api.get("/api/todos")).todos || [];
  } catch (_err) {
    return;                               // the list stays as it was
  }
  ovPlaceTodos();
}

/* WHAT CAME OF A TO-DO HANDED OVER - EVERY TIME IT WAS (/api/todos, `work`,
   the user 2026-10-26). Delegate work stays, however often it was handed
   over: each time is a version of its own, V1, V2... And beside it ITS
   WORK, TRACKED: every version with where it stands this moment - its plan
   being written, starting, going and what it is doing now (the runs going,
   asked every few seconds: watchWorkGoing), paused, waiting for you,
   finished, stopped - each opened from there: the plan, the work in Work,
   or the result. A line of them, opened out into one row each. */
const OV_TODO_STATE = { going: "going", paused: "paused", waiting_for_you: "waiting for you" };

function ovTodoVersions(one) {
  return ((one.work || {}).versions || []).slice();
}

/* AN ONGOING VERSION RUN FROM ITS ROW (the user, 2026-10-26): Pause or
   Resume, and Stop - then Stop now while it wraps up - as in Work. */
function ovTodoControls(version) {
  const going = version.unit ? workGoing.byUnit[version.unit] : null;
  if (!going || !going.run) return "";
  const id = escapeHtml(going.run);
  const paused = going.pause_asked || going.state === "paused";
  const pause = going.stopping ? "" : paused
    ? `<button type="button" class="small" data-todo-run-resume="${id}">Resume</button>`
    : `<button type="button" class="small secondary" data-todo-run-pause="${id}"
        title="Stops at the next safe point and waits for you">Pause</button>`;
  const stop = going.stopping
    ? `<button type="button" class="small secondary danger" data-todo-run-stop-now="${id}"
        title="Stop at once - no slides, no to-do list; it goes back to its last save point when resumed">Stop now</button>`
    : `<button type="button" class="small secondary" data-todo-run-stop="${id}"
        title="It wraps up: slides of what exists, and a to-do list">Stop</button>`;
  return `<span class="ov-todo-controls">${pause}${stop}</span>`;
}

/* Where one version stands, in a few words - live while it goes. */
function ovTodoWhere(version) {
  if (version.state === "drafting") return "its plan, for you to check";
  if (version.state === "finished") {
    return `finished${version.ended ? ` ${localStamp(version.ended)}` : ""}`;
  }
  if (version.state === "stopped") {
    // Said as Work says it: one that did not stop cleanly, and why.
    return version.goes_back && XP_GOES_BACK[version.status]
      ? `did not stop cleanly - ${XP_GOES_BACK[version.status]}`
      : `stopped: ${version.status || ""}`;
  }
  const going = version.unit ? workGoing.byUnit[version.unit] : null;
  if (!going) return version.held || "starting";
  const state = OV_TODO_STATE[going.state] || going.state;
  return going.activity ? `${state} - ${going.activity}` : state;
}

function ovTodoWork(one) {
  const versions = ovTodoVersions(one);
  const next = versions.length + 1;
  const delegate = `<button type="button" class="small secondary ov-todo-delegate"
    title="${versions.length ? "Hand it over again: a new version, beside the others"
      : "Hand this to the agent: it collects the context and drafts a plan for you to check"}">
    ${delegateLabel()}${versions.length ? ` <span class="muted">V${next}</span>` : ""}</button>`;
  if (!versions.length) return delegate;
  // WORK STATUS: where each version stands is in it, opened out.
  const open = delegateState.tracking.has(one.id);
  return `${delegate}<button type="button" class="small ov-todo-track" aria-expanded="${open}"
    title="Every version handed over, and where each stands now">${open ? "&#9662;" : "&#9656;"}
    Work status (${versions.length})</button>`;
}

/* What a version made, before it is opened: each thing it handed over -
   an email, an event, a file or folder by its name - else the file or
   folder its result is in. */
function ovTodoMade(version) {
  if ((version.items || []).length) {
    return version.items.map((item) => ({
      what: `${XP_HANDED_KIND[item.kind] || item.kind} · ${item.name || item.title || ""}`,
      // Text and an answer are read and copied where the work is shown.
      shown: item.kind === "text" || item.kind === "answer",
      open: ` data-todo-handed="${escapeHtml(String(item.n))}"`,
      words: item.kind === "folder" ? "Open the folder" : item.kind === "email"
        ? "Open the email" : item.kind === "event" ? "Open the event" : "Open the file",
    }));
  }
  if (version.result) {
    const folder = version.result_kind === "folder";
    return [{ what: `${folder ? "Folder" : "File"} · ${version.result_name || version.result}`,
              open: ` data-todo-result="${escapeHtml(version.result)}"`,
              words: folder ? "Open the folder" : "Open the file" }];
  }
  return [];
}

/* The rows of a to-do's work, opened out: the newest first. Three columns -
   the version, where it stands, what opens it - so the buttons line up;
   a finished one has a row for each thing it made, saying what it is. */
function ovTodoTracked(one) {
  const versions = ovTodoVersions(one);
  if (!versions.length || !delegateState.tracking.has(one.id)) return "";
  // REMOVE, asked first (the user, 2026-10-26): not shown again, its files
  // kept; not while it goes.
  const remove = (version) => version.state === "ongoing" ? ""
    : delegateState.removingVersion === version.draft
      ? `<span class="ov-todo-confirm">Remove V${version.version}?
        <button type="button" class="small danger" data-todo-remove-yes="${
          escapeHtml(version.draft)}">Yes</button>
        <button type="button" class="small secondary" data-todo-remove-no="1">No</button></span>`
      : `<button type="button" class="small secondary" data-todo-remove="${
          escapeHtml(version.draft)}" title="Not shown again - its files are kept">Remove</button>`;
  const row = (state, v, where, button, version) => `<li class="ov-todo-version ov-todo-version-${
    escapeHtml(state)}"><span class="ov-todo-v">${v}</span><span class="ov-todo-where">${
    escapeHtml(where)}</span><span class="ov-todo-open">${button}</span><span class="ov-todo-drop">${
    version ? remove(version) : ""}</span></li>`;
  return `<ol class="ov-todo-versions">${versions.slice().reverse().map((version) => {
    const v = `V${version.version}`;
    if (version.state === "drafting") {
      return row("drafting", v, ovTodoWhere(version), `<button type="button"
        class="small secondary ov-todo-ongoing" data-todo-draft="${escapeHtml(version.draft)}">Open the plan</button>`,
        version);
    }
    const made = version.state === "finished" ? ovTodoMade(version) : [];
    if (made.length) {
      const when = `finished${version.ended ? ` ${localStamp(version.ended)}` : ""}`;
      return made.map((thing, at) => row("finished", at ? "" : v,
        at ? thing.what : `${when} - ${thing.what}`,
        thing.shown ? `<button type="button" class="small secondary ov-todo-ongoing"
          data-todo-unit="${escapeHtml(version.unit || "")}">See it in Work</button>`
          : `<button type="button" class="small ov-todo-result" data-todo-run="${
          escapeHtml(version.run)}"${thing.open}>${escapeHtml(thing.words)}</button>`,
        at ? null : version)).join("");
    }
    // Stopped and able to go on: Resume - back to its last save point - or
    // Continue, from where it stopped cleanly; as in Work.
    const goOn = version.state === "stopped" && version.continuable && version.run
      ? `<span class="ov-todo-controls"><button type="button" class="small"
          data-todo-run-continue="${escapeHtml(version.run)}" title="${escapeHtml(
          version.goes_back
            ? `It goes back to its last save point${version.back_to ? `, ${version.back_to}` : ""}, and goes on from there; what came after is given up`
            : "It goes on from where it stopped")}">${
          version.goes_back ? "Resume" : "Continue"}</button></span>` : "";
    return row(version.state, v, ovTodoWhere(version), version.unit ? `${
      version.state === "ongoing" ? ovTodoControls(version) : goOn}<button type="button"
      class="small secondary ov-todo-ongoing" data-todo-unit="${escapeHtml(version.unit)}">${
      version.state === "ongoing" ? "Follow it in Work" : "See it in Work"}</button>` : "",
      version);
  }).join("")}</ol>`;
}

function ovTodoBox() {
  // WHAT IS LEFT TO DO, and only that: one done, or not wanted, is removed -
  // with a Yes first - not ticked and kept.
  const open = ovTodos.filter((one) => !one.done_at);
  const asking = delegateState.removing;
  const items = open.map((one) => `<li class="ov-todo-item" data-todo="${escapeHtml(one.id)}">
    <span class="ov-todo-text">${escapeHtml(one.text)}</span>${
      one.detail ? `<span class="muted ov-todo-detail">${escapeHtml(one.detail)}</span>` : ""}
    <span class="ov-todo-actions">${ovTodoWork(one)}
    ${asking === one.id ? `<span class="ov-todo-confirm">Remove it?
        <button type="button" class="small danger ov-todo-yes">Yes</button>
        <button type="button" class="small secondary ov-todo-no">No</button></span>`
      : `<button type="button" class="small secondary ov-todo-delete">Remove</button>`}
    </span>${ovTodoTracked(one)}</li>`).join("");
  return `<h3 class="ov-head">To do${open.length ? ` <span class="ov-head-count">(${
    open.length})</span>` : ""}</h3>${
    open.length ? `<ul class="ov-todo-list">${items}</ul>`
      : `<p class="muted">Nothing yet. "Add to to-do" on a notification puts it here.</p>`}`;
}

/* To do, level with Summary task at the top of the card; the round's bars
   under Summary task. The bars are drawn inside the picture and redrawn
   with it, so each time they are moved up under the heading - the bars
   only: the line under them, with its buttons, stays with the drawing. */
function ovPlaceTodos() {
  const card = $("#ov-tasks-card");
  if (!card) return;
  const slot = card.querySelector(".ov-strip-slot");
  const bars = $("#ov-tasks") && $("#ov-tasks").querySelector(".sb-progress .sb-progress-bars");
  if (slot && bars) {
    slot.replaceChildren(bars);
  }
  // REWRITTEN ONLY WHEN IT CHANGED, and scrolled where it was. The picture
  // is redrawn whenever a round moves - every fifteen seconds while work
  // runs - and each time the list was made anew, back at its top: what was
  // below its first few could not be scrolled to.
  const box = card.querySelector("#ov-todo");
  if (!box) return;
  const html = ovTodoBox();
  if (ovTodoDrawn === html && box.firstChild) return;
  const list = box.querySelector(".ov-todo-list");
  const scrolled = list ? list.scrollTop : 0;
  box.innerHTML = html;
  ovTodoDrawn = html;
  const again = box.querySelector(".ov-todo-list");
  if (again) again.scrollTop = scrolled;
}

document.addEventListener("click", async (event) => {
  const at = event.target.closest && event.target.closest(
    "[data-todo-run-pause],[data-todo-run-resume],[data-todo-run-stop],[data-todo-run-stop-now],"
    + "[data-todo-run-continue]");
  if (!at) return;
  // The same as Work's own: paused at its next safe point, resumed exactly
  // there; stopped, it wraps up - stopped now, it ends at once. A run that
  // ended goes on with the usual limits - set others in Work.
  const d = at.dataset;
  at.disabled = true;
  try {
    if (d.todoRunContinue) {
      at.textContent = "Starting…";
      await api.post("/api/work/continue", { run: d.todoRunContinue });
      await loadTodos();
    } else if (d.todoRunPause || d.todoRunResume) {
      await api.post(d.todoRunPause ? "/api/work/pause" : "/api/work/resume",
        { run: d.todoRunPause || d.todoRunResume });
    } else {
      await api.post("/api/work/stop", d.todoRunStop ? { run: d.todoRunStop }
        : { run: d.todoRunStopNow, now: true });
    }
  } catch (err) {
    toast(err.message);
  }
  await watchWorkGoing();
});

document.addEventListener("click", (event) => {
  const handed = event.target.closest && event.target.closest(".ov-todo-delegate");
  if (!handed) return;
  const one = ovTodos.find((todo) => todo.id === handed.closest("[data-todo]").dataset.todo);
  if (one) openDelegate({ text: [one.text, one.detail].filter(Boolean).join("\n"),
                          source: "todo", todo: one.id });
});

document.addEventListener("click", async (event) => {
  if (!event.target.closest) return;
  const ask = event.target.closest("[data-todo-remove]");
  const yes = event.target.closest("[data-todo-remove-yes]");
  const no = event.target.closest("[data-todo-remove-no]");
  if (!(ask || yes || no)) return;
  delegateState.removingVersion = ask ? ask.dataset.todoRemove : "";
  if (yes) {
    try {
      await api.post("/api/work/drafts/remove", { id: yes.dataset.todoRemoveYes });
      toast("Removed - its files are kept");
    } catch (err) { toast(err.message, "error"); }
    loadTodos();
    return;
  }
  ovPlaceTodos();
});

document.addEventListener("click", (event) => {
  const track = event.target.closest && event.target.closest(".ov-todo-track");
  if (!track) return;
  const id = track.closest("[data-todo]").dataset.todo;
  if (delegateState.tracking.has(id)) delegateState.tracking.delete(id);
  else delegateState.tracking.add(id);
  ovPlaceTodos();
});

document.addEventListener("click", async (event) => {
  const going = event.target.closest && event.target.closest(".ov-todo-ongoing");
  if (going && going.dataset.todoDraft) {
    openDelegateDraft(going.dataset.todoDraft);
  } else if (going) {
    if (going.dataset.todoUnit) experienceState.unit = going.dataset.todoUnit;
    const tab = $('nav button[data-tab="experience"]');
    if (tab) tab.click();
  }
  const result = event.target.closest && event.target.closest(".ov-todo-result");
  if (result) {
    try {
      if (result.dataset.todoHanded !== undefined) {
        await api.post("/api/work/handed/open", { run: result.dataset.todoRun,
                                                  n: Number(result.dataset.todoHanded) });
      } else {
        await api.post("/api/work/reveal", { run: result.dataset.todoRun,
                                             path: result.dataset.todoResult, open: true });
      }
    } catch (err) { toast(err.message, "error"); }
  }
});

/* DELEGATE WORK - and every start of work. What was handed over goes to the
   agent; it collects the context (in a process of its own) and drafts a
   high-level plan, which the user reads, changes as they like, and starts -
   or cancels. Nothing runs before Start. */
const delegateState = { draft: null, timer: null, icon: "", folders: [],
                        tracking: new Set() };     // the to-dos whose work is opened out

/* SOLO: the box alone, in a window of its own (platform_layer/app_window.py) -
   opened from Explorer, the selection button or the avatar. Nothing else of
   the page is drawn or asked for, and the window closes with the box. */
const DELEGATE_SOLO = new URLSearchParams(location.search).get("solo") === "delegate";
if (DELEGATE_SOLO) {
  document.body.classList.add("delegate-solo");
  // The agent's name in it: the listener knows the agent's own windows by
  // it (listener/providers/screen.py), and must not read this one as the
  // user's activity.
  document.title = "Delegate work - Personal Agent WaterMelon";
  $("#delegate").addEventListener("close", () => setTimeout(() => window.close(), 60));
  // Sized and put in the middle of the screen from here: only the page knows
  // the screen as the window is measured - in its own units, at whatever
  // scaling the display has.
  try {
    const w = Math.min(780, screen.availWidth), h = Math.min(900, screen.availHeight);
    window.resizeTo(w, h);
    window.moveTo((screen.availLeft || 0) + Math.round((screen.availWidth - w) / 2),
                  (screen.availTop || 0) + Math.round((screen.availHeight - h) / 2));
  } catch (_err) { /* a browser that does not let it: left as it opened */ }
}

/* "Delegate work", then the avatar's face - the words line up with others. */
function delegateLabel(words = "Delegate work") {
  return `<span class="delegate-label">${escapeHtml(words)}</span>${delegateState.icon
    ? `<img class="delegate-icon" src="${delegateState.icon}" alt="" aria-hidden="true">` : ""}`;
}

async function loadDelegateIcon() {
  try {
    delegateState.icon = (await api.get("/api/avatar/icon?size=32")).png || "";
  } catch (_err) { delegateState.icon = ""; }
}

/* EVERY DELEGATE WORK, in three steps: the instruction first (what was
   handed over shown above it), then Create - the context collected and a
   plan drafted - then the plan approved with Start. */
async function openDelegate(handed) {
  const dialog = $("#delegate");
  if (!dialog) return;
  delegateState.draft = null;
  delegateStep("start");
  delegateClear();
  $("#delegate-body").innerHTML = `<p class="muted">Opening&hellip;</p>`;
  $("#delegate-start").disabled = true;
  delegateShow(dialog);
  try {
    const said = await api.post("/api/work/drafts", Object.assign({ write_first: true }, handed));
    delegateFollow(said.draft.id);
    if (handed.todo) loadTodos();         // handed over: the to-do says Ongoing
  } catch (err) {
    $("#delegate-body").innerHTML = `<p class="delegate-error">${escapeHtml(err.message)}</p>`;
  }
}

/* The box with nothing handed over yet (the avatar's menu): the instruction,
   then Create, as from anywhere else. */
function openDelegateNew() {
  openDelegate({ source: "menu" });
}

/* Which button ends the box's step: Create while the instruction is being
   written, Start once there is a plan - never both. */
function delegateStep(which) {
  const start = $("#delegate-start"), save = $("#delegate-save");
  if (save) save.disabled = false;
  // START AT ANY STEP (the user, 2026-10-26): before the plan is drafted it
  // starts the work once it is, with the settings as they are - no review.
  if (start) {
    start.hidden = false;
    start.disabled = Boolean(delegateState.folderHeld);
    start.title = which === "ready" ? "Start it with this plan and these settings"
      : "Start it once its context is collected and its plan drafted - with these "
        + "settings, and nothing more to approve";
  }
}

/* The box emptied for another piece of work. */
function delegateClear() {
  $("#delegate-head").innerHTML = "";
  const settings = $("#delegate-settings");
  settings.innerHTML = "";
  settings.dataset.draft = "";
  delegateState.settings = null;
  delegateState.folderHeld = "";
}

/* Step one: what was handed over, and the instruction - changed, or written. */
function delegateCompose(draft) {
  const asked = (draft.options || {}).instruction || "";
  const items = [...(draft.folders || []).map((one) => `<li><span class="delegate-kind">folder</span> <code>${
      escapeHtml(one)}</code></li>`), ...(draft.files || []).map((one) => `<li><span
      class="delegate-kind">file</span> <code>${escapeHtml(one)}</code></li>`)].join("");
  $("#delegate-head").innerHTML = `${delegateHanded(draft)}
    ${items ? `<ul class="delegate-items">${items}</ul>` : ""}
    <label><span>${draft.text || items || draft.unit_id
      ? `Your instruction <span class="muted">(anything to add or change - optional)</span>`
      : "What should the agent do?"}</span><textarea id="delegate-instruction" rows="5"
      placeholder="Say what you want done, as you would to a colleague">${escapeHtml(asked)}</textarea></label>`;
  $("#delegate-body").innerHTML = `<p class="muted">Start collects the context, drafts a plan and
    starts the work with these settings - nothing more to approve. Save as draft keeps it all, to
    open again from Work and start later.</p>`;
  delegateSettings(draft);
  delegateStep("write");
  const box = $("#delegate-instruction");
  if (box) { box.focus(); box.setSelectionRange(box.value.length, box.value.length); }
}

/* SAVE AS DRAFT (the user, 2026-10-26) - in place of Create: the box kept
   as it is - the instruction, where it works, the settings and the way, the
   plan as changed - closed, and listed in Work's drafts to open again and
   start. Saved before the instruction was taken, it is taken now, and the
   context collected and the plan drafted meanwhile. */
document.addEventListener("click", async (event) => {
  if (!(event.target.closest && event.target.closest("#delegate-save"))) return;
  const draft = delegateState.draft;
  if (!draft) return;
  $("#delegate-save").disabled = true;
  const settings = delegateReadSettings() || {};
  const ready = ["ready", "failed"].includes(draft.status);
  try {
    await api.post("/api/work/drafts/save", { id: draft.id,
      instruction: draft.status === "writing" ? ($("#delegate-instruction") || {}).value || "" : null,
      plan: ready ? delegatePlan() : null, folders: delegateState.folders,
      options: { limits: settings.limits, packages: settings.packages, way: settings.way,
                 sound: Boolean(settings.sound), unconfined: Boolean(settings.unconfined) } });
    clearTimeout(delegateState.timer);
    $("#delegate").close();
    toast("Saved - open it again from Work, under Drafts");
    if (draft.source === "todo") loadTodos();
    xpLoadDrafts();
  } catch (err) {
    toast(err.message, "error");
    $("#delegate-save").disabled = false;
  }
});

/* THE BOX FLOATS (the user, 2026-10-26): shown over the page, not in front
   of all of it - the page behind it is read, scrolled and copied from as it
   is open - and dragged by its title out of the way. */
function delegateShow(dialog) {
  if (dialog.open) return;
  if (DELEGATE_SOLO) { dialog.showModal(); return; }
  dialog.show();
}

document.addEventListener("pointerdown", (event) => {
  const title = event.target.closest && event.target.closest("#delegate-title");
  const dialog = $("#delegate");
  if (!title || !dialog || DELEGATE_SOLO || event.button !== 0) return;
  const box = dialog.getBoundingClientRect();
  const dx = event.clientX - box.left, dy = event.clientY - box.top;
  dialog.classList.add("delegate-moved");
  const move = (at) => {
    const left = Math.max(0, Math.min(window.innerWidth - 80, at.clientX - dx));
    const top = Math.max(0, Math.min(window.innerHeight - 40, at.clientY - dy));
    dialog.style.left = `${left}px`;
    dialog.style.top = `${top}px`;
  };
  move(event);
  const stop = () => {
    document.removeEventListener("pointermove", move);
    document.removeEventListener("pointerup", stop);
  };
  document.addEventListener("pointermove", move);
  document.addEventListener("pointerup", stop);
  event.preventDefault();
});

/* WORK'S DRAFTS: each saved one, to open again - and start - or throw away. */
async function xpLoadDrafts() {
  const box = $("#xp-drafts");
  if (!box) return;
  let drafts = [];
  try {
    drafts = (await api.get("/api/work/drafts/saved")).drafts || [];
  } catch (_err) {
    return;
  }
  const asking = experienceState.draftRemoving || "";
  const name = (one) => ((one.plan || {}).title || (one.options || {}).instruction
    || one.text || "Untitled").split("\n")[0].slice(0, 120);
  const where = { writing: "its instruction to finish", collecting: "collecting its context",
                  drafting: "drafting its plan", ready: "its plan, for you to check",
                  failed: "its plan, to write" };
  xpPut(box, drafts.length ? `<h4 class="xp-group">Drafts</h4><ul class="xp-drafts">${
    drafts.map((one) => `<li class="xp-draft"><span class="xp-draft-name">${escapeHtml(name(one))}</span>
      <span class="muted">${escapeHtml(where[one.status] || one.status)}${one.updated_at
        ? ` · ${escapeHtml(localStamp(one.updated_at))}` : ""}</span>
      <span class="xp-draft-buttons">${asking === one.id ? `Remove it? <span class="muted">its files are kept</span>
        <button type="button" class="small danger" data-xp-draft-yes="${escapeHtml(one.id)}">Yes</button>
        <button type="button" class="small secondary" data-xp-draft-no="1">No</button>`
        : `<button type="button" class="small" data-xp-draft-open="${escapeHtml(one.id)}">Open</button>
        <button type="button" class="small secondary" data-xp-draft-drop="${escapeHtml(one.id)}">Remove</button>`}
      </span></li>`).join("")}</ul>` : "");
}

document.addEventListener("click", async (event) => {
  if (!event.target.closest) return;
  const open = event.target.closest("[data-xp-draft-open]");
  const drop = event.target.closest("[data-xp-draft-drop]");
  const yes = event.target.closest("[data-xp-draft-yes]");
  const no = event.target.closest("[data-xp-draft-no]");
  if (!(open || drop || yes || no)) return;
  if (open) {
    openDelegateDraft(open.dataset.xpDraftOpen);
    return;
  }
  experienceState.draftRemoving = drop ? drop.dataset.xpDraftDrop : "";
  if (yes) {
    try {
      await api.post("/api/work/drafts/remove", { id: yes.dataset.xpDraftYes });
    } catch (err) { toast(err.message, "error"); }
    loadTodos();
  }
  xpLoadDrafts();
});

/* A draft made elsewhere - Explorer's menu, the button beside selected text -
   opened here by its id. */
function openDelegateDraft(id) {
  const dialog = $("#delegate");
  if (!dialog) return;
  delegateClear();
  $("#delegate-body").innerHTML = `<p class="muted">Collecting the context&hellip;</p>`;
  delegateShow(dialog);
  delegateFollow(id);
}

async function delegateFollow(id) {
  clearTimeout(delegateState.timer);
  let draft;
  try {
    draft = (await api.get(`/api/work/drafts?id=${encodeURIComponent(id)}`)).draft;
  } catch (err) {
    $("#delegate-body").innerHTML = `<p class="delegate-error">${escapeHtml(err.message)}</p>`;
    return;
  }
  const first = !delegateState.draft || delegateState.draft.id !== draft.id
    || delegateState.draft.status !== draft.status;
  delegateState.draft = draft;
  if (draft.status === "writing") {
    if (first) delegateCompose(draft);
    return;
  }
  delegateStep(draft.status === "ready" || draft.status === "failed" ? "ready" : "start");
  delegateSettings(draft);
  if (draft.status === "collecting" || draft.status === "drafting") {
    if (first) $("#delegate-head").innerHTML = delegateHanded(draft);
    $("#delegate-body").innerHTML = `<p class="muted delegate-wait">
      <span class="sb-spin" aria-hidden="true"></span>${draft.status === "collecting"
        ? "Collecting the context - what you handed over, the folders, and what of your own records bears on it&hellip;"
        : "Drafting a high-level plan for you to check&hellip;"}</p>`;
    delegateState.timer = setTimeout(() => delegateFollow(id), 1000);
    return;
  }
  if (first) delegateDraw(draft);
}

function delegateHanded(draft) {
  const where = draft.window || {};
  const asked = draft.status !== "writing" ? (draft.options || {}).instruction || "" : "";
  return `<div class="delegate-handed">${asked ? `<p class="delegate-asked"><strong>Your instruction:</strong> ${
      escapeHtml(asked.slice(0, 600))}${asked.length > 600 ? "&hellip;" : ""}</p>` : ""}${
    draft.text ? `<blockquote>${escapeHtml(
      draft.text.slice(0, 600))}${draft.text.length > 600 ? "&hellip;" : ""}</blockquote>` : ""}${
    where.title || where.url ? `<p class="muted">From: ${escapeHtml(where.title || "")}${
      where.url ? ` <span class="delegate-url">${escapeHtml(where.url)}</span>` : ""}</p>` : ""}</div>`;
}

function delegateDraw(draft) {
  const plan = draft.plan || {};
  const lines = (list) => (list || []).join("\n");
  const context = draft.context || {};
  const said = [];
  if ((context.window || {}).title) said.push(`the window "${context.window.title}"`);
  if ((context.page || {}).url) said.push(`its page${context.page.error ? " (could not be read)" : ""}`);
  if ((context.folders || []).length) said.push(`${context.folders.length} folder${
    context.folders.length === 1 ? "" : "s"}`);
  if ((context.found || []).length) said.push(`${context.found.length} of your own records`);
  if (context.work) said.push(`the work "${context.work.name}"`);
  // WHAT WAS FOUND OF YOUR OWN RECORDS, each whole: what, when, how relevant.
  const kinds = { state: "activity", task: "task", stage: "past work" };
  const found = (context.found || []).map((one) => `<li><span class="delegate-kind">${
      escapeHtml(kinds[one.kind] || one.kind)}</span> <strong>${escapeHtml(one.title || "")}</strong>${
      one.detail && one.detail !== one.title ? `<div class="muted">${escapeHtml(one.detail)}</div>` : ""}
      <div class="muted delegate-why">${one.at ? escapeHtml(localStamp(one.at)) + " · " : ""}relevance ${
      Math.round(Number(one.relevance || 0) * 100)}%</div></li>`).join("");
  const searched = (context.query || {}).keywords || [];
  $("#delegate-head").innerHTML = delegateHanded(draft);
  $("#delegate-body").innerHTML = `
    ${draft.status === "failed" ? `<p class="delegate-error">${escapeHtml(draft.error
      || "The plan could not be drafted.")} You can write it yourself below.</p>` : ""}
    <p class="muted">Context collected: ${escapeHtml(said.join(", ") || "only what you handed over")}.
      Check the plan - change anything - then Start. Nothing runs before that.</p>
    ${found ? `<details class="delegate-found"><summary>Found in your own records${
      searched.length ? ` <span class="muted">- searched for: ${escapeHtml(searched.join(", "))}</span>`
        : ""}</summary><ul>${found}</ul></details>` : ""}
    <label>Title<input type="text" data-plan="title" value="${escapeHtml(plan.title || "")}"></label>
    <label>What you want<textarea data-plan="understanding" rows="2">${escapeHtml(
      plan.understanding || "")}</textarea></label>
    <label>Goal<textarea data-plan="goal" rows="2">${escapeHtml(plan.goal || "")}</textarea></label>
    <label><span>Main steps <span class="muted">(one a line)</span></span><textarea data-plan="steps"
      rows="4">${escapeHtml(lines(plan.steps))}</textarea></label>
    <label><span>What you get <span class="muted">(one a line)</span></span><textarea data-plan="deliverables"
      rows="3">${escapeHtml(lines(plan.deliverables))}</textarea></label>
    <label><span>Not part of it <span class="muted">(one a line)</span></span><textarea data-plan="out_of_scope"
      rows="2">${escapeHtml(lines(plan.out_of_scope))}</textarea></label>
    ${(plan.questions || []).length ? `<label><span>Open questions <span class="muted">(answer them
      here, or leave them for the work to settle)</span></span><textarea data-plan="questions"
      rows="2">${escapeHtml(lines(plan.questions))}</textarea></label>` : ""}
`;
  delegateSettings(draft);
  // EACH FIELD WHOLE: as tall as what is in it - the box grows, the fields
  // do not scroll - and growing as it is typed into.
  $$("#delegate-body textarea").forEach((box) => {
    const fit = () => { box.style.height = "auto"; box.style.height = `${box.scrollHeight + 2}px`; };
    box.addEventListener("input", fit);
    requestAnimationFrame(fit);
  });
  $("#delegate-start").disabled = false;
}

function delegatePlan() {
  const plan = {};
  $$("#delegate-body [data-plan]").forEach((field) => {
    const name = field.dataset.plan;
    plan[name] = ["title", "understanding", "goal"].includes(name) ? field.value.trim()
      : field.value.split("\n").map((one) => one.trim()).filter(Boolean);
  });
  // The way as chosen - with the planner's why while it is the one it
  // suggested.
  const settings = delegateReadSettings();
  if (settings) {
    const suggested = ((delegateState.draft || {}).plan || {});
    plan.way = settings.way === "auto" ? suggested.way || "full" : settings.way;
    plan.way_why = plan.way === suggested.way ? suggested.way_why || "" : "";
  }
  return plan;
}

/* HOW IT IS DONE, AND ITS SETTINGS - in every box that starts work, the
   same as Work's own and with the same defaults (the user, 2026-10-26):
   Quick or Thorough, as the plan suggests it and why; the limits; how
   packages are asked for; a sound when it ends; without the sandbox.
   What the box was opened with (Work's own settings) first; what the user
   changes in it kept while it is redrawn. */
const DELEGATE_WAYS = {
  auto: "As the plan suggests",
  quick: "Quick - one agent on its own judgement, with what was learned of your work",
  full: "Thorough - a builder and a reviewer, with a contract each deliverable must meet",
};

async function delegateSettings(draft) {
  if (!experienceState.limits) {
    try {
      experienceState.limits = await api.get("/api/work/limits");
    } catch (_err) {
      experienceState.limits = { defaults: {} };
    }
  }
  const box = $("#delegate-settings");
  if (!box || (delegateState.draft || {}).id !== draft.id) return;
  const plan = draft.plan || {};
  // DRAWN ONCE FOR A DRAFT: what is chosen in it is not drawn over while the
  // context is collected; only the plan's suggestion is put in when it comes.
  if (box.dataset.draft === draft.id) {
    const said = $("#delegate-way-suggested");
    const text = plan.way ? `now: ${plan.way === "quick" ? "Quick" : "Thorough"}${
      plan.way_why ? ` - ${plan.way_why}` : ""}` : "not drafted yet";
    if (said && said.textContent !== text) said.textContent = text;
    return;
  }
  box.dataset.draft = draft.id;
  delegateState.folders = [...(draft.folders || [])];
  delegateState.kinds = Object.assign({}, draft.kinds || {});
  const options = draft.options || {};
  const held = (delegateState.settings || {}).draft === draft.id ? delegateState.settings : null;
  const given = Object.fromEntries(Object.entries(options.limits || {})
    .filter(([, value]) => value !== undefined && value !== null && value !== ""));
  const settings = held || {
    way: ["auto", "quick", "full"].includes(options.way) ? options.way : "auto",
    limits: Object.assign({}, (experienceState.limits || {}).defaults || {}, given),
    // Auto unless asked otherwise (the user, 2026-10-27); the server asks
    // anyway where the system does not confine what is installed.
    packages: options.packages === "ask" ? "ask" : "auto",
    sound: Boolean(options.sound), unconfined: Boolean(options.unconfined),
  };
  const limit = (name) => escapeHtml(String(settings.limits[name] ?? ""));
  box.innerHTML = `<div class="delegate-way"><strong>How it is done</strong>
      ${WAYS_SHOWN.map((way) => `<label><input type="radio" name="delegate-way" value="${way}"${
        settings.way === way ? " checked" : ""}> ${escapeHtml(DELEGATE_WAYS[way])}${
        way === "auto" ? ` <span class="muted" id="delegate-way-suggested">${plan.way
          ? escapeHtml(`now: ${plan.way === "quick" ? "Quick" : "Thorough"}${
            plan.way_why ? ` - ${plan.way_why}` : ""}`) : "not drafted yet"}</span>` : ""}</label>`)
        .join("")}
    </div>
    <div class="xp-limits"><strong>Limits:</strong>
      <label>minutes <input type="number" data-delegate-limit="minutes" value="${limit("minutes")}"></label>
      <label title="${escapeHtml(XP_INPUT_TOKENS_ABOUT)}">input tokens <input type="number"
        data-delegate-limit="tokens_in" step="100000" value="${limit("tokens_in")}"></label>
      <label title="What the models wrote">output tokens <input type="number"
        data-delegate-limit="tokens_out" step="10000" value="${limit("tokens_out")}"></label>
      <label>model calls <input type="number" data-delegate-limit="calls" value="${limit("calls")}"></label>
      <span class="muted">0 or less: no limit</span></div>
    <div class="xp-packages-mode"><strong>Python packages:</strong>
      <label><input type="radio" name="delegate-packages" value="ask"${
        settings.packages !== "auto" ? " checked" : ""}> Ask me before installing packages</label>
      <label><input type="radio" name="delegate-packages" value="auto"${
        settings.packages === "auto" ? " checked" : ""}> Auto</label></div>
    <div class="xp-unconfined-mode">${xpUnconfinedBox(
      `data-delegate-unconfined${settings.unconfined ? " checked" : ""}`)}</div>
    ${xpSoundBox("data-delegate-sound", settings.sound)}
    ${draft.unit_id && draft.source !== "delegate" ? ""
      : `<div class="delegate-folders" id="delegate-folders"></div>`}`;
  delegateState.settings = Object.assign({ draft: draft.id }, settings);
  delegateState.folderHeld = "";
  delegateFoldersDraw();
  if (!$("#delegate-folders")) delegateFolderCheck();
}

const WAYS_SHOWN = ["auto", "quick", "full"];

/* WHERE IT WORKS (the user, 2026-10-26), with the settings - before any
   plan: a folder given is where it works, changing what is in it; a file,
   that file alone, changed in place; none, it makes what it makes in a
   folder of its own. What was handed over is listed already, each to take
   off. */
function delegateFoldersDraw() {
  const box = $("#delegate-folders");
  if (!box) return;
  const kinds = delegateState.kinds || (delegateState.kinds = {});
  box.innerHTML = `<strong>Where it works</strong>
    <ul>${delegateState.folders.map((one, i) => `<li>${kinds[one] ? `<span
      class="delegate-kind">${escapeHtml(kinds[one])}</span> ` : ""}<code>${escapeHtml(one)}</code>
      <button type="button" class="link x-remove" data-delegate-drop="${i}" title="Take off">&times;</button></li>`).join("")
      || `<li class="muted">Nothing given: it makes what it makes in a folder of its own.</li>`}</ul>
    <button type="button" class="small secondary" id="delegate-add-folder"
      title="A folder or a file - whichever you select last">Add work directory</button>
    <span id="delegate-which" hidden>A folder or a file?
      <button type="button" class="small secondary" data-delegate-which="folder">Folder</button>
      <button type="button" class="small secondary" data-delegate-which="file">File</button></span>
    <span class="muted">it works in them directly - a folder: anything in it may be changed
      or deleted; a file: that file alone</span>
    <p class="delegate-error" id="delegate-folder-held" hidden></p>`;
  delegateFolderCheck();
}

/* ONE PIECE OF WORK AT A TIME IN A FOLDER (the user, 2026-10-26): while
   other work is going in a folder this one would work in - its own project's
   too - Start is not offered, and the box says which work it is waiting for.
   Asked again as the runs going change (watchWorkGoing). */
async function delegateFolderCheck() {
  const draft = delegateState.draft;
  if (!draft || !$("#delegate") || !$("#delegate").open) return;
  let said = {};
  try {
    said = await api.post("/api/work/folders/held", {
      paths: delegateState.folders || [],
      unit: draft.unit_id && draft.source !== "delegate" ? draft.unit_id : "" });
  } catch (_err) {
    return;                               // the start itself is refused then
  }
  delegateState.folderHeld = said.held ? said.said : "";
  const note = $("#delegate-folder-held");
  if (note) {
    note.hidden = !delegateState.folderHeld;
    note.textContent = delegateState.folderHeld ? `Start waits: ${delegateState.folderHeld}` : "";
  }
  const start = $("#delegate-start");
  if (start && !start.hidden) {
    start.disabled = Boolean(delegateState.folderHeld);
    if (delegateState.folderHeld) start.title = delegateState.folderHeld;
  }
}

/* The settings as the box shows them now - null before they are drawn. */
function delegateReadSettings() {
  const box = $("#delegate-settings");
  if (!box || !box.firstChild) return null;
  const limits = {};
  box.querySelectorAll("[data-delegate-limit]").forEach((field) => {
    if (field.value !== "") limits[field.dataset.delegateLimit] = Number(field.value);
  });
  const settings = {
    draft: (delegateState.draft || {}).id,
    way: (box.querySelector('input[name="delegate-way"]:checked') || {}).value || "auto",
    limits,
    packages: (box.querySelector('input[name="delegate-packages"]:checked') || {}).value || "auto",
    sound: Boolean((box.querySelector("[data-delegate-sound]") || {}).checked),
    unconfined: Boolean((box.querySelector("[data-delegate-unconfined]") || {}).checked),
  };
  delegateState.settings = settings;
  return settings;
}

document.addEventListener("change", (event) => {
  if (event.target.closest && event.target.closest("#delegate-settings")) delegateReadSettings();
});

document.addEventListener("click", async (event) => {
  if (!event.target.closest) return;
  const drop = event.target.closest("[data-delegate-drop]");
  if (drop) {
    delegateState.folders.splice(Number(drop.dataset.delegateDrop), 1);
    delegateFoldersDraw();
    return;
  }
  // ONE BUTTON FOR A FOLDER OR A FILE (the user, 2026-10-26): what is
  // selected last in the one chooser is what is added. Where the machine has
  // no chooser for both, which of the two is asked first.
  const which = event.target.closest("[data-delegate-which]");
  if (event.target.closest("#delegate-add-folder") || which) {
    const add = (path, kind) => {
      if (!path || delegateState.folders.includes(path)) return;
      delegateState.folders.push(path);
      (delegateState.kinds || (delegateState.kinds = {}))[path] = kind;
      delegateFoldersDraw();
    };
    try {
      if (which) {
        $("#delegate-which").hidden = true;
        const folder = which.dataset.delegateWhich === "folder";
        const chosen = await api.post(folder ? "/api/settings/choose-directory"
          : "/api/settings/choose-file", { title: folder
            ? "A folder the work may change - anything in it" : "A file the work may change - that file alone" });
        add(chosen.selected, folder ? "folder" : "file");
        return;
      }
      const chosen = await api.post("/api/settings/choose-place", {
        title: "Where the work may change things - a folder, or a file alone" });
      if (chosen.two) {
        $("#delegate-which").hidden = false;
        return;
      }
      add(chosen.selected, chosen.kind);
    } catch (err) { toast(err.message, "error"); }
    return;
  }
  if (event.target.closest("#delegate-cancel")) {
    clearTimeout(delegateState.timer);
    const draft = delegateState.draft;
    // A DRAFT SAVED stays as it was saved - Cancel only closes the box (Save
    // as draft again keeps what changed); one never saved is thrown away.
    if (draft && !(draft.options || {}).saved) {
      api.post("/api/work/drafts/cancel", { id: draft.id }).catch(() => {})
        .then(() => { if (draft.source === "todo") loadTodos(); });
    }
    $("#delegate").close();
    return;
  }
  if (event.target.closest("#delegate-start")) {
    const draft = delegateState.draft;
    if (!draft) return;
    $("#delegate-start").disabled = true;
    try {
      // STARTED BEFORE ITS PLAN IS DRAFTED (the user, 2026-10-26): the
      // instruction taken as Create takes it, and the work starts once its
      // context is collected and its plan drafted - with these settings,
      // and nothing more to approve.
      if (draft.status === "writing") {
        const instruction = ($("#delegate-instruction") || {}).value || "";
        if (!instruction.trim() && !draft.text && !(draft.folders || []).length
            && !(draft.files || []).length && !draft.unit_id) {
          toast("Say what you want done");
          $("#delegate-start").disabled = false;
          return;
        }
        await api.post("/api/work/drafts/compose", { id: draft.id, instruction });
      }
      clearTimeout(delegateState.timer);
      const ready = ["ready", "failed"].includes(draft.status);
      const settings = delegateReadSettings() || {};
      const plan = ready ? delegatePlan() : { way: settings.way || "auto" };
      // ANSWERED AT ONCE: the work is set going apart - seconds, with its
      // process to start - and how it went is asked of the draft.
      await api.post("/api/work/drafts/start", { id: draft.id,
        plan, folders: delegateState.folders,
        options: { limits: settings.limits, packages: settings.packages,
                   sound: Boolean(settings.sound), unconfined: Boolean(settings.unconfined) } });
      $("#delegate-head").innerHTML = "";
      $("#delegate-settings").innerHTML = "";
      if (DELEGATE_SOLO) {
        // Said in the box, which closes with its window once it is known.
        $("#delegate-body").innerHTML = `<p class="delegate-started">${ready ? "Starting&hellip;"
          : "Collecting its context - it starts once its plan is drafted&hellip;"}</p>`;
        $(".delegate-actions").hidden = true;
        const said = await delegateHowItStarted(draft.id);
        if (said.error) {
          $("#delegate-body").innerHTML = `<p class="delegate-error">It did not start: ${
            escapeHtml(said.error)}</p>`;
          $(".delegate-actions").hidden = false;
          $("#delegate-start").disabled = false;
          return;
        }
        $("#delegate-body").innerHTML = `<p class="delegate-started">${said.waiting
          ? `Waiting to start: ${escapeHtml(said.why || "")}`
          : "Started. Follow it in Work."}</p>`;
        setTimeout(() => $("#delegate").close(), 1800);
        return;
      }
      $("#delegate").close();
      toast(ready ? "Starting - see it in Work"
        : "It starts once its context is collected - see it in Work");
      if (draft.source === "todo") loadTodos();   // a to-do handed over: now Ongoing
      const said = await delegateHowItStarted(draft.id);
      if (said.error) {
        // Back in the box, as it was, with why: to change and Start again.
        toast(`It did not start: ${said.error}`, "error");
        openDelegateDraft(draft.id);
        return;
      }
      if (said.waiting) toast(`Waiting to start: ${said.why}`);
      loadTodos();
      if (activeTab === "experience") {
        if (said.unit) experienceState.unit = said.unit;
        await loadExperience(false);
      }
    } catch (err) {
      toast(err.message, "error");
      $("#delegate-start").disabled = false;
    }
  }
});

/* How a start went (`start_apart`): the draft asked until it is started -
   with what starting it said - or is back where it was, with why. Asked
   each second at first, then every three. */
async function delegateHowItStarted(id) {
  for (let asked = 0; asked < 1200; asked += 1) {
    await new Promise((done) => setTimeout(done, asked < 30 ? 1000 : 3000));
    let draft;
    try {
      draft = (await api.get(`/api/work/drafts?id=${encodeURIComponent(id)}`)).draft;
    } catch (_err) {
      continue;                           // asked again
    }
    if (draft.status === "started") return Object.assign({ unit: draft.unit_id }, draft.start || {});
    // Started before its plan was drafted: waiting for it, then starting.
    const waiting = ["collecting", "drafting", "starting"].includes(draft.status)
      || (draft.status === "ready" && (draft.options || {}).start_when_ready);
    if (!waiting) {
      return { error: draft.error || (draft.start || {}).error || "it did not start" };
    }
  }
  return { error: "it has not said it started" };
}

document.addEventListener("click", async (event) => {
  if (!event.target.closest) return;
  const item = event.target.closest(".ov-todo-item[data-todo]");
  if (!item) return;
  // × asks first; Yes removes it, No leaves it.
  if (event.target.closest(".ov-todo-delete")) {
    delegateState.removing = item.dataset.todo;
    ovPlaceTodos();
  } else if (event.target.closest(".ov-todo-no")) {
    delegateState.removing = null;
    ovPlaceTodos();
  } else if (event.target.closest(".ov-todo-yes")) {
    delegateState.removing = null;
    try {
      await api.post("/api/todos/delete", { id: item.dataset.todo });
    } catch (err) { toast(err.message, "error"); }
    loadTodos();
  }
});

/* Every scrolled box inside `host` (and `host` itself), by its class and
   its place among boxes of that class - which a redraw gives back. */
function sbScrollsIn(host) {
  const boxes = [host, ...host.querySelectorAll("*")];
  const seen = {};
  const out = [];
  boxes.forEach((box) => {
    const key = String(box.className && box.className.baseVal !== undefined
      ? box.className.baseVal : box.className || box.tagName);
    seen[key] = (seen[key] || 0) + 1;
    if (box.scrollLeft || box.scrollTop) {
      out.push({key, at: seen[key], left: box.scrollLeft, top: box.scrollTop});
    }
  });
  return out;
}

function sbScrollsBack(host, held) {
  if (!held.length) return;
  const boxes = [host, ...host.querySelectorAll("*")];
  const seen = {};
  boxes.forEach((box) => {
    const key = String(box.className && box.className.baseVal !== undefined
      ? box.className.baseVal : box.className || box.tagName);
    seen[key] = (seen[key] || 0) + 1;
    const was = held.find((one) => one.key === key && one.at === seen[key]);
    if (was) {
      box.scrollLeft = was.left;
      box.scrollTop = was.top;
    }
  });
}

/* A FRAME ROUND WHAT IS SELECTED - the task or project whose card is
   open below. Drawn again after every redraw, because a redraw makes the
   rows anew; it is worked out from what the card shows, which is the one
   thing every redraw keeps. */
function sbMarkSelected() {
  document.querySelectorAll(".sb-tt-selection").forEach((one) => one.remove());
  document.querySelectorAll(".sb-tt-selected").forEach(
    (one) => one.classList.remove("sb-tt-selected"));
  const shows = stateBeat.cardShows || {};
  let selector = "";
  if (shows.kind === "project" && shows.which) {
    selector = `[data-sb-project="${CSS.escape(String(shows.which))}"]`;
  } else if (shows.kind === "task" && stateBeat.openTask) {
    selector = `[data-sb-task="${CSS.escape(String(stateBeat.openTask))}"]`;
  }
  if (!selector) return;
  document.querySelectorAll(`.sb-whole-graph ${selector}`).forEach((row) => {
    row.classList.add("sb-tt-selected");
    // Round its marker and its words, not the line of its time: that runs
    // the width of the picture and would frame half of it.
    let box = null;
    row.querySelectorAll(".sb-tt-disc, text").forEach((part) => {
      let at;
      try { at = part.getBBox(); } catch (_err) { return; }
      if (!at || (!at.width && !at.height)) return;
      box = box ? {
        x: Math.min(box.x, at.x), y: Math.min(box.y, at.y),
        right: Math.max(box.right, at.x + at.width),
        bottom: Math.max(box.bottom, at.y + at.height),
      } : {x: at.x, y: at.y, right: at.x + at.width, bottom: at.y + at.height};
    });
    if (!box) return;
    const frame = document.createElementNS("http://www.w3.org/2000/svg", "rect");
    frame.setAttribute("class", "sb-tt-selection");
    frame.setAttribute("x", (box.x - 6).toFixed(1));
    frame.setAttribute("y", (box.y - 5).toFixed(1));
    frame.setAttribute("width", (box.right - box.x + 12).toFixed(1));
    frame.setAttribute("height", (box.bottom - box.y + 10).toFixed(1));
    frame.setAttribute("rx", "7");
    row.insertBefore(frame, row.firstChild);
  });
}

function drawWhatIsRunningNow(whole) {
  // Recent first, so the rejected groupings counted are the recent ones.
  const recent = sbOnlyRecent(whole);
  const picture = sbOnlyShown(recent);
  // NO PICTURE IS A CASE THIS FUNCTION ALREADY HANDLES - it says so on
  // the panel, because a blank reads as a fault. Returning early here
  // left whatever was on screen before, which is worse than either.
  if (picture) {
    // What "work activity" leaves out: the groupings judged not a task,
    // and the tasks of leisure.
    picture.hidden_count = (((recent || {}).plan || {}).nodes || [])
      .filter((one) => one.hidden || one.leisure).length;
  }
  // THE WHOLE THING, KEPT. What is drawn has had the rejected rows taken
  // out of it, so redrawing from it when the button is pressed would
  // have nothing to put back.
  stateBeat.whole = whole;
  const host = $("#ov-tasks");
  if (!host) return;
  if (!picture) {
    host.innerHTML = `<p class="muted">The grouping has not been asked
      about yet. It runs when an agent heartbeat finishes and enough time
      has passed.</p>`;
    return;
  }
  const due = picture.due || {};
  // WHAT IT IS WAITING FOR, AND HOW FAR ALONG. Before the first grouping
  // there is nothing to draw and nothing wrong, and those two look the
  // same from an empty panel. The count is the whole rule at this stage -
  // the hours do not apply until there is a picture - so saying "enough
  // time has passed" here would be describing a rule that is not the one
  // in force.
  if (due.waiting_for && !due.run && !((picture.plan || {}).nodes || []).length) {
    const got = Number(due.unread || 0);
    const want = Number(due.waiting_for);
    host.innerHTML = `<p class="muted sb-waiting-first">Waiting for the
      first ${want} states before the first grouping - <strong>${got}</strong>
      so far. Fewer than that is a list, and a list is what grouping
      replaces.</p>
      <div class="sb-first-bar" role="img"
        aria-label="${got} of ${want} states"><span
        style="width:${Math.min(100, Math.round(got * 100 / want))}%"></span>
      </div>`;
    return;
  }
  const nodes = ((picture.plan || {}).nodes || []).length;
  // NOTHING IN THE WINDOW, though there are tasks: said so, with the
  // choice beside it, rather than the reasons a grouping might be empty.
  if (!nodes && (((whole || {}).plan || {}).nodes || []).length) {
    host.innerHTML = `<p class="muted sb-recent-empty">No task was worked on
      in the last ${sbRecentDays() === 1 ? "day" : `${sbRecentDays()} days`}.
      ${sbRecentBar()}</p>`;
    return;
  }
  if (!nodes) {
    // WHY, not a blank. A page that shows nothing where a drawing goes
    // is read as a broken drawing, and the reasons are all facts about
    // the round rather than about the picture.
    const due = picture.due || {};
    const counted = due.counted || {};
    // THE EXACT NUMBERS, always. "No grouping to draw yet" plus a rule
    // about hours does not tell a reader whether there is anything to
    // group - and that is the question an empty picture raises. The
    // counts answer it: how many states the grouping reads, and how many
    // of them are in no task.
    const tally = counted.states !== undefined
      ? `<p class="muted sb-tally"><strong>${Number(counted.waiting || 0)}</strong>
         state${Number(counted.waiting) === 1 ? "" : "s"} in no task yet, of
         ${Number(counted.states || 0)} the grouping reads${
         Number(counted.tasks || 0)
           ? `, across ${Number(counted.tasks)} task${
               Number(counted.tasks) === 1 ? "" : "s"}` : ""}.</p>`
      : "";
    host.innerHTML = `<p class="muted">No grouping to draw yet.
      ${escapeHtml(String(due.why || ""))}${
      picture.running ? " A round is running now." : ""}</p>${tally}`;
    return;
  }
  // NOT WHILE A DRAG IS IN PROGRESS. Rebuilding the frame under a hand
  // that is moving it loses the gesture; the next poll a second later
  // draws whatever arrived in the meantime.
  if (stateBeat.holding) return;
  // A NAME LANDING IS NOT A NEW PICTURE. Written into the drawing that is
  // already there where it can be, which is most of the time while a
  // round runs - and that is exactly when somebody is watching.
  if (sbWriteInPlace(host, picture)) return;
  // The same care here: this redraws every poll while a round runs, and
  // the reader may have dragged the picture halfway across.
  const was = sbWhereItWas();
  // WHAT THIS SUMMARY WAS MADE FROM, in the reader's own clock with the
  // zone named. A round reads up to a line it draws before it starts, so
  // "these are your tasks" is really "these are your tasks as of a
  // quarter past ten this morning" - and that difference is the whole
  // question as soon as the morning has moved on. A bare local time
  // would be worse than a UTC one: it looks familiar and cannot be
  // checked, so the zone is always said.
  // HOW FAR THROUGH THE ROUND IT IS, in a strip that is always in the
  // same place.
  //
  // The picture marks the task being written by pulsing it, and a pulse
  // is only visible where the reader happens to be looking: measured on
  // the live agent, the working task's whole span sat two thousand pixels
  // to the left of the frame. A bar under the heading cannot be scrolled
  // away from, so it is the one signal that is always readable - the
  // pulse then says WHICH, for a reader who is looking at the right part
  // of the calendar.
  const progress = sbProgressStrip(picture);
  // WHAT IS BEING WRITTEN RIGHT NOW, said in words above the drawing.
  //
  // The picture shows it by pulsing, and a pulse can only be seen where
  // the reader is looking: the task being summarised might be anywhere
  // on a calendar wider than the frame. A line of text is in the same
  // place every time.
  const busyNow = sbDoingNow(picture);
  const since = picture.as_of || {};
  const line = since.said
    ? `<p class="muted sb-as-of">Summarised from the states recorded up to
         <strong>${escapeHtml(String(since.said))}</strong>${
         since.running ? " - a round is running now, so later states are "
                       + "in it from here on"
         : since.done ? "" : " - that round did not finish, so it is being "
                            + "resumed"}.${
         // ONLY WHEN THE ROUND BEING DESCRIBED IS THE FINISHED ONE.
         // `finished` is the last round that COMPLETED, and this said it
         // beside an unfinished round's line - so the panel read "that
         // round did not finish, so it is being resumed. The round
         // finished 19:58", which are two statements about two different
         // rounds presented as one.
         since.done && !since.running && since.finished_said
           // Bold, like the moment the states were read up to: they are
           // the two times on this line, and a reader looking for when
           // the picture was made is looking for both.
           ? ` The round finished <strong>${escapeHtml(
               String(since.finished_said))}</strong>.` : ""}${
         // AND WHEN THE NEXT ONE BEGINS, which is the thing a reader
         // looking at a finished round wants to know: whether to wait for
         // it or come back. Worked out on the agent from the same moment
         // the gate measures from, so it is the time it will say yes.
         since.next_said && !since.running
           ? ` The next round will start after <strong>${escapeHtml(
               String(since.next_said))}</strong>.` : ""}</p>`
    : `<p class="muted sb-as-of">No round has drawn a line yet, so there is
         nothing to say about how old this is.</p>`;
  // THE STRIP FIRST, directly under the heading. It went after the line
  // saying which states the picture was made from - two sentences of
  // provenance, which is worth reading once and pushes the one thing a
  // reader checks repeatedly below it.
  // IN A SLOT THAT IS ALWAYS THERE. The line naming what is being
  // written exists only while a visit runs, and visits start and stop
  // every few seconds - so the drawing under it jumped 35 pixels down
  // the page and back each time, which reads as the view being moved
  // from under the reader. The slot keeps its height whether or not
  // there is anything to say in it.
  host.innerHTML = progress
    + `<div class="sb-doing-slot">${busyNow || ""}</div>` + line
    + sbCostLine(picture.round || {})
    + stateBeatWholeTree(picture);
  // The same state the debugger's copy reads, so opening a task in one
  // place and then looking at the other does not show two different
  // things open.
  // THE REPORT THIS DRAWING CAME FROM, kept on the element that holds it.
  // A click used to unfold from `stateBeat.report`, which is whichever
  // report the DEBUGGER last saw: when the two held different tasks -
  // after a sandbox round, say - the task clicked on the overview was
  // looked for in a report that did not contain it, found nothing to put
  // under it, and appeared to do nothing at all.
  host.sbReport = picture;
  stateBeat.report = stateBeat.report && stateBeat.report.layers
    ? stateBeat.report : picture;
  stateBeatRestore(was);
  const svg = host.querySelector(".sb-whole-graph");
  if (svg) sbZoomWire(host);
  // AND WHAT WAS OPEN IS STILL OPEN. The branches are built into the
  // drawing by hand rather than being part of its HTML, so replacing the
  // HTML removes them; `stateBeat.openTask` survives, but nothing was
  // rebuilding them HERE. The one place that did look only inside the
  // debugger's panel, so on the overview every landing name - several a
  // minute while a round runs - collapsed whatever the reader had open.
  //
  // Laid out without the movement, because the movement means "this came
  // from the thing you clicked" and nothing was clicked.
  // At the most recent end, where the circles are, unless the reader has
  // already moved it.
  sbOpenAtTheEnd(host, was);
  const openNow = stateBeat.openTasks instanceof Set
    ? stateBeat.openTasks : new Set(stateBeat.openTask
                                    ? [stateBeat.openTask] : []);
  if (svg && openNow.size) sbUnfold(svg, picture, openNow);
  // AND THE VIEW PUT BACK LAST, once the drawing is its full height.
  //
  // It was put back earlier, inside the restore - before what was open
  // had been unfolded again, so into a drawing missing every opened
  // task and piece. A view scrolled to the bottom of the panel cannot
  // sit below the bottom of a shorter drawing, so the browser moved it
  // up to fit; the drawing then grew back and the view stayed where it
  // had been pushed. Measured: parked at 556 of 556, put back at 121,
  // on a refresh that changed nothing at all.
  sbPutItBack(was);
}

function stateBeatWholeTree(report) {
  // Its own arrowhead (see xpMarkerId): the Overview and the debugger draw
  // this picture at once.
  const sbArrow = xpMarkerId("sb-arrow");
  const plan = report.plan || {};
  const pieces = plan.nodes || [];
  // SAY WHY THERE IS NO PICTURE. Returning nothing left a blank where a
  // drawing goes, and a blank is read as a fault in the drawing - there
  // is no way to tell "this round made no plan" from "the picture is
  // broken" by looking. Every reason below is a fact about the round.
  // ONE TASK IS DRAWN. It used to be "a circle with nothing to depend
  // on", but the picture is when the work happened as well as what waits
  // on what - and in a window of the last day, one task is ordinary.
  if (pieces.length < 1) {
    const why = report.running
      ? `This round is still going. The picture is drawn from the plan,
         which is the last thing a round works out - it will appear when
         the round finishes.`
      : !report.plan
      ? ((report.summaries_written || []).length === 0
         && (report.layers || []).length > 0
         ? `This round reused every summary it had, so it never asked for
            a plan. The picture needs one: it is what the arrows are.`
         : `This round produced no plan. ${escapeHtml(String(
            report.note || report.error
            || "Nothing in the round says why, which is itself "
               + "worth reporting."))}`)
      : `There are no tasks in the plan.`;
    // NOT OPEN. The exception to "nothing opens itself" is earned by a
    // drawing, which is what a reader comes here for; a sentence saying
    // there is no drawing has not earned it.
    return `<details class="sb-whole-tree" data-sb-open="whole-tree">
      <summary><strong>Everything running now</strong>
        <span class="muted">no picture this round - why</span></summary>
      <p class="muted sb-no-picture">${why}</p>
    </details>`;
  }
  const edges = plan.edges || [];
  const left = 8;
  const named = 0;   // the names are at the near end now, not in a gutter

  const at = (moment) => new Date(moment).getTime();
  // THE SAME AXIS WHETHER OR NOT THE REJECTED GROUPINGS ARE SHOWN. The
  // span was taken from the rows being drawn, so hiding a grouping that
  // began earliest moved where every date sat, and the reader's view
  // slid with it. `sbOnlyShown` hands over the span of every row, drawn
  // or not.
  const spanned = (plan.span && plan.span.length === 2) ? plan.span : null;
  const starts = pieces.map((one) => at(one.began)).filter(Number.isFinite);
  const ends = pieces.map((one) => at(one.ended)).filter(Number.isFinite);
  const earliest = spanned ? spanned[0] : Math.min(...starts);
  const latest = spanned ? spanned[1] : Math.max(...ends, ...starts);

  // THE WHOLE CALENDAR, AND THE DRAWING IS AS WIDE AS IT NEEDS TO BE.
  //
  // This used to show a fortnight with a dropdown and a pair of arrows to
  // move it, because three months squeezed into the width of a panel puts
  // a week inside four pixels. The squeezing was the problem, not the
  // three months: the answer is to stop fitting the calendar to the panel
  // and let the picture be wider than its frame, which is what dragging
  // and zooming are already for. A window also hid anything older than
  // itself behind a control, so a task that ran six weeks ago could not
  // be seen at all without first working out that a control existed.
  const DAY = 86400000;
  const whole = Math.max(DAY, latest - earliest);
  const first = earliest;
  const last = latest;
  // Room enough that a day is legible, so a long calendar makes a long
  // drawing rather than a dense one. The frame scrolls; the reader drags.
  const SB_DAY_WIDE = 26;
  const needs = Math.ceil(whole / DAY) * SB_DAY_WIDE;
  const width = Math.max(SB_WIDTH, needs);
  const right = width - 8;
  const across = (moment) => {
    const here = at(moment);
    if (!Number.isFinite(here)) return left;
    return left + ((here - first) / (last - first)) * (right - left - 12);
  };
  // Where a thing sits when it is off the edge of the window: pinned at
  // the border rather than drawn outside it, so a task that began three
  // months ago still has a row and still says so.
  const onScreen = (x) => Math.max(left, Math.min(right - 12, x));

  // The ROWS are in the reader's chosen order; the circles still sit at
  // the time each task began, so the picture says both things at once -
  // down the page is what to do first, across it is when it happened.
  const byId = new Map((report.layers || []).map((one) => [one.id, one]));
  const ordered = sbInOrder(
    pieces.map((one) => ({...one, ...(byId.get(one.id) ? {} : {}),
                          summary: (byId.get(one.id) || {}).summary,
                          seat: (byId.get(one.id) || {}).seat})),
    report).map((one) => pieces.find((p) => p.id === one.id) || one);
  // PROJECTS ARE THE TOP LAYER. A project - tasks the model agreed are
  // parts of one larger piece of work - is a row of its own, drawn as a
  // task is: when it was worked on, how urgent and important its most
  // pressing part is, sorted among the tasks in no project. Opened, its
  // tasks hang under it, and each task opens onto its pieces as before.
  const projectsShown = (report.projects || []).filter((project) =>
    (project.tasks || []).length && (sbShowingHidden() || !project.hidden));
  const projectOf = new Map();
  projectsShown.forEach((project) =>
    (project.tasks || []).forEach((id) => projectOf.set(id, project)));
  const projectFor = (one) => projectOf.get(one.task_id || one.id)
    || projectOf.get((byId.get(one.id) || {}).task_id);
  const openProjects = stateBeat.openProjects instanceof Set
    ? stateBeat.openProjects : new Set();
  const membersOf = new Map();
  ordered.forEach((one) => {
    const project = projectFor(one);
    if (!project) return;
    if (!membersOf.has(project.id)) membersOf.set(project.id, []);
    membersOf.get(project.id).push(one);
  });
  const projectRow = (project) => ({
    id: `project:${project.id}`, kind: "project", project: project,
    task_id: `project:${project.id}`, title: project.name || "A project",
    began: project.began, ended: project.ended,
    stretches: project.stretches || [], size: project.count || 0,
    phase: project.phase || "active",
    summary: {title: project.name, urgency: project.urgency,
              importance: project.importance}});
  const top = [];
  const seenProject = new Set();
  ordered.forEach((one) => {
    const project = projectFor(one);
    if (!project) { top.push(one); return; }
    if (seenProject.has(project.id)) return;
    seenProject.add(project.id);
    top.push(projectRow(project));
  });
  const topSorted = sbInOrder(top, report);
  const slots = [];
  topSorted.forEach((item) => {
    if (item.kind !== "project") { slots.push({one: item}); return; }
    // ONLY THE TOP LAYER: a project is one row, and does not open onto its
    // tasks - its card lists them.
    slots.push({project: item.project, row: item});
  });
  const everyTask = ordered.length;
  const drawnTasks = slots.filter((slot) => slot.one).map((slot) => slot.one);
  ordered.length = 0;
  drawnTasks.forEach((one) => ordered.push(one));
  const inProject = new Set(slots.filter((slot) => slot.one && slot.project)
    .map((slot) => slot.one.id));
  const projectRows = slots.filter((slot) => slot.row).map((slot) => slot.row);
  const rowOf = new Map();
  slots.forEach((slot, index) =>
    rowOf.set(slot.one ? slot.one.id : slot.row.id, index));
  // Room for two lines of name and the figures under them.
  const step = 54;
  const height = slots.length * step + 44;
  const y = (id) => 26 + rowOf.get(id) * step;
  const sizeOf = (one) =>
    Math.max(7, Math.min(17, 6 + Math.sqrt(Number(one.size || 1)) * 2.2));

  // ONE COLOUR PER TASK, from the task itself and not from where it
  // happens to sit. This took its row number, which changes the moment
  // the reader sorts by importance instead of urgency - so the same task
  // was one colour in the picture and another in the panel under it, and
  // the two disagreed again every time the order changed. `stateBeatTop`
  // is what the task blocks and the card already use.
  const colourOf = (one) =>
    sbColour(stateBeatTopIndex(byId.get(one.id) || {id: one.id}, report),
             true);

  // THE LINE UNDER THE NAME, built once so that what is measured and what
  // is drawn cannot disagree. The width used to be worked out from the
  // name alone while this line - which is usually the longer of the two -
  // was drawn at the same place and ran off the right-hand edge, where
  // the furthest task's words could not be reached at all.
  const asideOf = (one) => sbAsideFor(one, report);
  // Wide enough for the longest thing drawn beside a disc, WHEREVER it
  // sits - the name's longest line or the line under it, whichever
  // reaches further. Nothing is cut off and nothing is scaled down to
  // make it fit. After `sizeOf`, which it measures from.
  const beside = (one) => Math.max(
    Math.max(...sbWrapName(sbNameOf(one)).map((line) => sbTextWide(line))),
    // The aside is a smaller font, so it is measured at a smaller width
    // per character rather than at the name's.
    sbTextWide(asideOf(one), 5.6),
    sbTextWide(sbFirstWords(sbStatusOf(one, report), 110), 5.6));
  const wide = Math.max(width, ...ordered.map((one) =>
    onScreen(across(one.ended)) + sizeOf(one) + 26 + beside(one)),
    ...projectRows.map((row) => onScreen(across(row.ended)) + sizeOf(row)
      + 26 + Math.max(sbTextWide(`▾ PROJECT ${row.title}`),
                      sbTextWide(sbProjectAside(row.project), 5.6),
                      sbTextWide(sbFirstWords(row.project.status || "", 110),
                                 5.6))));

  // ONE SEGMENT PER STRETCH OF WORK, with the gaps left empty. A task
  // left for months and picked up again was drawn as one line across the
  // months, as though it had gone on the whole time; the time it was not
  // worked on is part of what the picture says. A faint dotted line joins
  // the stretches, so they still read as one task.
  const spanOf = (one, index) => {
    const stretches = (one.stretches || []).filter((pair) =>
      pair && pair[0]);
    const line = (began, ended, extra) => {
      const x1 = onScreen(across(began));
      const x2 = Math.max(x1 + 2, onScreen(across(ended || began)));
      return `<line x1="${x1.toFixed(1)}" y1="0" x2="${x2.toFixed(1)}"
        y2="0" class="sb-tt-span${extra}" stroke="${colourOf(one)}"/>`;
    };
    if (stretches.length < 2) return line(one.began, one.ended, "");
    const joined = line(stretches[0][0], stretches[stretches.length - 1][1],
                        " sb-tt-span-gap");
    return joined + stretches.map((pair) =>
      line(pair[0], pair[1], "")).join("");
  };

  // AN ARROW TO A TASK IN A CLOSED PROJECT goes to the project, once; one
  // between two tasks of the same project is the project's own business,
  // shown when it is opened.
  const shownFor = (id) => {
    const drawnOne = ordered.find((one) => one.id === id);
    if (drawnOne) return drawnOne;
    const node = pieces.find((one) => one.id === id);
    const project = node ? projectFor(node) : null;
    return project ? projectRows.find((row) => row.project === project) : null;
  };
  const arrowsSeen = new Set();
  const drawn = edges.map((edge) => {
    const from = shownFor(edge.before);
    const to = shownFor(edge.after);
    if (!from || !to || from === to) return "";
    const key = `${from.id}>${to.id}`;
    if (arrowsSeen.has(key)) return "";
    arrowsSeen.add(key);
    const x1 = across(from.ended) + 4;
    const y1 = y(from.id);
    const x2 = across(to.began) - 10;
    const y2 = y(to.id);
    // Right angles, like a tech tree: out, across, and in.
    const mid = Math.max(x1 + 10, (x1 + x2) / 2);
    return `<path d="M${x1.toFixed(1)} ${y1} H${mid.toFixed(1)}
      V${y2} H${x2.toFixed(1)}" class="sb-tt-edge"
      marker-end="url(#${sbArrow})"><title>${escapeHtml(
      `${from.title} must be done before ${to.title}`)}</title></path>`;
  }).join("");

  // A ROW PER TASK, each in its own group at y=0 and put in place by a
  // transform - so opening a task can move the rows below it by changing
  // one number each, and CSS can make that a movement rather than a jump.
  // Drawing them at their final y would mean redrawing to move them, and
  // a redraw replaces the elements, which is how an animation gets lost.
  const circles = ordered.map((one, index) => {
    // THE DISC IS AT THE MOST RECENT END and its line runs BACK from
    // there. A reader scanning this is looking at what is happening now,
    // so the thing to put under their eye is where each task has got to,
    // with its history trailing behind it - not where it started, which
    // is the least interesting fact about a task that is still running.
    const cx = onScreen(across(one.ended));
    // THE NAME SITS AT THE MOST RECENT END of the task's own line, which
    // is where the eye already is: a reader scanning this is looking at
    // what is happening NOW, and a name in a gutter on the far left is a
    // name they have to travel to. It also gives the axis the whole
    // width, instead of a quarter of it going to a column of text.
    const endX = cx;
    const cy = 0;
    const colour = colourOf(one);
    const done = one.finished;
    // A CIRCLE WAITING FOR ITS NAME SAYS SO. The shape of the tree is
    // known before any of the names - grouping needs no model, naming is
    // one call per task - so the picture goes up first and fills in. A
    // circle labelled with its internal id instead would read as the name
    // of the work, which is the one thing it is not.
    // "working" for the one being summarised now, "loading" for the ones
    // whose turn has not come. All of them saying "loading" is true and
    // useless: a reader watching a round that takes minutes wants to know
    // which task is costing the time.
    const title = sbNameOf(one);
    return `<g class="sb-tt-row sb-tt-node${done ? " sb-tt-done" : ""}${
        one.working ? " sb-tt-working" : ""}${
        inProject.has(one.id) ? " sb-tt-in-project" : ""}${
        one.phase === "quiet" ? " sb-tt-quiet" : ""}${
        ((stateBeat.openTasks instanceof Set
          ? stateBeat.openTasks.has(one.id)
          : stateBeat.openTask === one.id) ? " sb-tt-open" : "")}"
        data-sb-task="${escapeHtml(String(one.id || ""))}"
        data-sb-at="${y(one.id)}"
        data-sb-cy="${cy}"
        style="transform:translateY(${y(one.id)}px)"
        tabindex="0" role="button">
      ${inProject.has(one.id)
        ? `<line x1="2" y1="-22" x2="2" y2="${step - 22}"
             class="sb-tt-project-tick"/>` : ""}
      ${spanOf(one, index)}
      <circle data-sb-disc="${cx.toFixed(1)}" cx="${cx.toFixed(1)}" cy="${cy}" r="${sizeOf(one).toFixed(1)}"
        fill="${colour}" stroke="${colour}" stroke-width="2"
        class="sb-tt-disc"/>
      <g transform="translate(${cx.toFixed(1)} ${cy})"
         class="sb-tt-emblem">${
        // FROM THE ID THAT LASTS. `one.id` is positional - the first row
        // is `task_1` whatever task that is this round - so an emblem
        // seeded from it follows the POSITION and the badges swap over
        // when the order changes. The stored id belongs to the task for
        // life, which is the whole reason the emblem exists.
        sbEmblem(String(one.task_id || one.id || ""), colour,
                 sizeOf(one))}</g>
      ${done
        ? `<circle cx="${(cx + sizeOf(one) * 0.72).toFixed(1)}"
             cy="${(cy - sizeOf(one) * 0.72).toFixed(1)}"
             r="${(sizeOf(one) * 0.42).toFixed(1)}" class="sb-tt-seal"/>
           <path d="M${(cx + sizeOf(one) * 0.72 - 3).toFixed(1)} ${
             (cy - sizeOf(one) * 0.72).toFixed(1)} l2.2 2.6 l4.4 -5"
             class="sb-tt-tick"/>`
        : ""}
      <g class="sb-tt-label">${sbWrapName(title).map((line, at) =>
        `<text x="${(endX + sizeOf(one) + 9).toFixed(1)}"
           y="${cy + 1 + at * 13}"
           fill="${colour}" class="sb-tt-name">${escapeHtml(line)}</text>`
        ).join("")}</g>
      <text x="${(endX + sizeOf(one) + 9).toFixed(1)}"
        y="${cy + 1 + sbWrapName(title).length * 13}"
        class="sb-tt-aside">${escapeHtml(asideOf(one))}</text>
      ${sbStatusOf(one, report) ? `<text x="${(endX + sizeOf(one) + 9).toFixed(1)}"
        y="${cy + 1 + (sbWrapName(title).length + 1) * 13}"
        class="sb-tt-aside sb-tt-project-status">${escapeHtml(
          sbFirstWords(sbStatusOf(one, report), 110))}</text>` : ""}
      <title>${escapeHtml(`${title} - ${one.size} states, ${
        one.began ? clock(one.began) : "?"} to ${
        one.ended ? clock(one.ended) : "?"}${
        done ? ", finished" : ", still open"}. Click to open it.`)}</title>
    </g>`;
  });
  const rowsFor = new Map(ordered.map((one, index) => [one.id,
                                                       circles[index]]));
  // A PROJECT'S TASKS HANG FROM IT. Opened, its tasks are drawn under it,
  // and without a line nothing says they are its own rather than the next
  // rows down. A rail runs down the left of its tasks' circles and each
  // one is reached from above, in the gap between rows where no words are.
  const projectLines = slots.map((slot, index) => {
    if (!slot.row || !openProjects.has(slot.project.id)) return "";
    const members = [];
    for (let at = index + 1; at < slots.length; at += 1) {
      if (!slots[at].one || slots[at].project !== slot.project) break;
      members.push({one: slots[at].one, y: 26 + at * step});
    }
    if (!members.length) return "";
    const top = 26 + index * step;
    const px = onScreen(across(slot.row.ended));
    const xs = members.map((m) => onScreen(across(m.one.ended)));
    const rail = Math.min(px, ...xs);
    const above = (y) => y - 21;
    const parts = [`M${px.toFixed(1)} ${(top + sizeOf(slot.row)).toFixed(1)}`
      + ` V${above(members[0].y).toFixed(1)} H${rail.toFixed(1)}`
      + ` V${above(members[members.length - 1].y).toFixed(1)}`];
    members.forEach((m, i) => parts.push(
      `M${rail.toFixed(1)} ${above(m.y).toFixed(1)} H${xs[i].toFixed(1)}`
      + ` V${(m.y - sizeOf(m.one)).toFixed(1)}`));
    return `<path d="${parts.join(" ")}" class="sb-tt-project-link"
      data-sb-link="${escapeHtml(String(slot.project.id || ""))}"
      stroke="${colourOf(slot.row)}"/>`;
  }).join("");
  const circlesDrawn = slots.map((slot, index) => {
    if (slot.one) return rowsFor.get(slot.one.id) || "";
    const row = slot.row;
    const at = 26 + index * step;
    const cx = onScreen(across(row.ended));
    const size = sizeOf(row);
    const colour = colourOf(row);
    const open = openProjects.has(row.project.id);
    return `<g class="sb-tt-row sb-tt-project-row${
        row.phase === "quiet" ? " sb-tt-quiet" : ""}${open ? " sb-tt-open" : ""}"
        data-sb-project="${escapeHtml(String(row.project.id || ""))}"
        data-sb-at="${at}" style="transform:translateY(${at}px)"
        tabindex="0" role="button">
      ${spanOf(row, index)}
      <circle cx="${cx.toFixed(1)}" cy="0" r="${(size + 4).toFixed(1)}"
        stroke="${colour}" class="sb-tt-project-ring"/>
      <circle data-sb-disc="${cx.toFixed(1)}" cx="${cx.toFixed(1)}" cy="0"
        r="${size.toFixed(1)}" fill="${colour}" stroke="${colour}"
        stroke-width="2" class="sb-tt-disc sb-tt-project-disc"/>
      <g transform="translate(${cx.toFixed(1)} 0)" class="sb-tt-emblem">${
        // A circle with its own emblem, as a task has, seeded from the
        // project's lasting id; the outer ring is what says "project".
        sbEmblem(`project:${row.project.id || ""}`, colour, size)}</g>
      <text x="${(cx + size + 9).toFixed(1)}" y="1"
        class="sb-tt-name sb-tt-project-name"><tspan
          class="sb-tt-project-tag" fill="${colour}">PROJECT</tspan> ${
          escapeHtml(row.title)}</text>
      <text x="${(cx + size + 9).toFixed(1)}" y="15"
        class="sb-tt-aside">${escapeHtml(sbProjectAside(row.project))}</text>
      ${row.project.status ? `<text x="${(cx + size + 9).toFixed(1)}" y="28"
        class="sb-tt-aside sb-tt-project-status">${escapeHtml(
          sbFirstWords(row.project.status, 110))}</text>` : ""}
      <title>${escapeHtml(`${row.title}: ${row.project.why || ""}. Click to
        read it.`)}</title>
    </g>`;
  }).join("");

  return `<details class="sb-whole-tree" data-sb-open="whole-tree" open>
    <summary><strong>Everything running now</strong>
      <span class="muted">${topSorted.length} at the top${
        projectsShown.length ? ` (${projectsShown.length} project${
          projectsShown.length === 1 ? "" : "s"})` : ""}, ${everyTask} tasks
        in all, ${edges.length} dependenc${edges.length === 1 ? "y" : "ies"}
        &middot; time runs left to right</span>
      ${sbSortBar()}
      ${report.recent_days ? sbRecentBar() : ""}
      <!-- What the shapes mean, said once, where it cannot scroll away
           from the thing it explains. -->
      <p class="sb-key">
        <span><em>preparing</em> is waiting its turn,
          <em>summarizing</em> is being written now</span></p>
      <span class="sb-span-bar"><span class="muted">size</span>
        <button type="button" class="small secondary" data-sb-treezoom="out"
          title="Smaller (Ctrl and minus, over the picture)">&minus;</button>
        <button type="button" class="small secondary" data-sb-treezoom="in"
          title="Bigger (Ctrl and plus, over the picture)">+</button>
        ${sbTreeZoom() !== 1
          ? `<button type="button" class="small secondary"
               data-sb-treezoom="reset" title="Back to full size">${
               Math.round(sbTreeZoom() * 100)}%</button>`
          : ""}</span></summary>
    <div class="sb-tree-frame" data-sb-frame="whole-tree">
    <svg viewBox="0 0 ${wide} ${height}"
      style="width:${(wide * sbTreeZoom()).toFixed(0)}px;height:${
        (height * sbTreeZoom()).toFixed(0)}px"
      class="sb-graph sb-whole-graph"
      data-sb-step="${step}" data-sb-shut="${height}" data-sb-wide="${wide}"
      data-sb-end="${last}" data-sb-from="${first}"
      data-sb-x0="${left}" data-sb-x1="${right - 12}"
      data-sb-base-wide="${wide}" data-sb-base-tall="${height}"
      data-sb-zoom="${sbTreeZoom()}"
      preserveAspectRatio="xMinYMin meet" role="img"
      aria-label="the active tasks, when each began, and what waits on what">
      <defs><marker id="${sbArrow}" viewBox="0 0 8 8" refX="7" refY="4"
        markerWidth="6" markerHeight="6" orient="auto">
        <path d="M0 0 L8 4 L0 8 z" class="sb-tt-head"/></marker></defs>
      <g class="sb-tt-edges">${drawn}</g>
      <g class="sb-tt-branches"></g>
      <g class="sb-tt-project-links">${projectLines}</g>
      ${circlesDrawn}
      <g class="sb-tt-foot" data-sb-at="${height - 20}"
         style="transform:translateY(${height - 20}px)">
        <line x1="${left + named}" y1="0" x2="${right - 20}" y2="0"
          class="sb-tt-axis"/>
        ${(() => {
          // A DATE EVERY SO MANY PIXELS, so that whatever part of the
          // calendar is on screen has at least two of them in it. Two ends
          // and nothing between is an axis that only works when the whole
          // drawing fits: zoom in or drag along a three-month span and
          // every label is somewhere off to the side, which leaves the
          // circles placed against nothing.
          //
          // The spacing is in drawing units, and the narrowest frame this
          // panel is given is around three hundred of them - so one label
          // every hundred and forty puts two in view at the worst case and
          // more at the usual one.
          const from = left + named;
          const to = right - 20;
          const EVERY = 140;
          const marks = [];
          for (let x = from; x <= to + 1; x += EVERY) {
            marks.push(Math.min(x, to));
          }
          // THE LAST ONE ONLY IF IT HAS ROOM. Forcing a label at the far
          // end put it on top of the one before it whenever the span did
          // not divide evenly - two dates printed through each other,
          // which is worse than one date fewer. Half the spacing is the
          // room a label needs.
          if (marks[marks.length - 1] < to - EVERY / 2) marks.push(to);
          return marks.map((x, at) => {
            const share = (to > from) ? (x - from) / (to - from) : 0;
            const when = new Date(first + share * (last - first));
            const last_one = at === marks.length - 1;
            return `<g class="sb-tt-mark">
              <line x1="${x.toFixed(1)}" y1="-4" x2="${x.toFixed(1)}" y2="0"
                class="sb-tt-axis"/>
              <text x="${x.toFixed(1)}" y="15" class="sb-tt-when"
                text-anchor="${at === 0 ? "start"
                  : last_one ? "end" : "middle"}">${
                escapeHtml(sbWhenShort(when, new Date(last)))}</text>
            </g>`;
          }).join("");
        })()}
      </g>
    </svg>
    </div>
    <p class="muted sb-figure-note">A circle is a task, placed where it
      began; the line through it is the stretch its states cover. A filled
      and ticked circle is finished. An arrow means the task it points at
      could not be started until the other was done - a dependency, not
      merely a later date, and most pairs have none. Rows only keep the
      circles apart and mean nothing.
      ${plan.why ? escapeHtml(String(plan.why)) : ""}</p>
    <div class="sb-task-card" data-sb-card>${sbCardFor(report)}</div>
    <p class="muted sb-click-hint">Click a project to open its tasks; click a task to read
      it below.</p>
  </details>`;
}

function stateBeatTechTree(task) {
  const sbTtArrow = xpMarkerId("sb-tt-arrow");
  const plan = task.plan || {};
  const pieces = plan.nodes || [];
  if (pieces.length < 2) return "";
  const edges = plan.edges || [];
  const width = SB_WIDTH;
  const left = 8;
  const right = width - 8;

  const at = (moment) => new Date(moment).getTime();
  const spans = pieces.map((one) => at(one.began)).filter(Number.isFinite);
  const ends = pieces.map((one) => at(one.ended)).filter(Number.isFinite);
  const first = Math.min(...spans);
  const last = Math.max(...ends, ...spans);
  const across = (moment) => {
    const here = at(moment);
    if (!Number.isFinite(here) || last <= first) return left + 40;
    return left + 40 + ((here - first) / (last - first)) * (right - left - 90);
  };

  // A row per piece, in the order they began, so no two circles collide.
  const ordered = [...pieces].sort((a, b) => at(a.began) - at(b.began));
  const rowOf = new Map();
  ordered.forEach((one, index) => rowOf.set(one.id, index));
  const rows = ordered.length;
  const step = 34;
  const height = rows * step + 46;
  const y = (id) => 22 + rowOf.get(id) * step;

  const spansDrawn = ordered.map((one) => {
    const x1 = across(one.began);
    const x2 = Math.max(x1 + 6, across(one.ended));
    return `<line class="sb-tt-span" x1="${x1.toFixed(1)}" y1="${y(one.id)}"
      x2="${x2.toFixed(1)}" y2="${y(one.id)}"></line>`;
  }).join("");

  const arrows = edges.map((edge) => {
    const from = ordered.find((one) => one.id === edge.before);
    const to = ordered.find((one) => one.id === edge.after);
    if (!from || !to) return "";
    const x1 = across(from.ended);
    const y1 = y(from.id);
    const x2 = across(to.began);
    const y2 = y(to.id);
    const bend = (x1 + x2) / 2;
    return `<path class="sb-tt-edge" marker-end="url(#${sbTtArrow})"
      d="M ${x1.toFixed(1)} ${y1} C ${bend.toFixed(1)} ${y1},
         ${bend.toFixed(1)} ${y2}, ${(x2 - 9).toFixed(1)} ${y2}"></path>`;
  }).join("");

  const circles = ordered.map((one) => {
    const x = across(one.began);
    const done = Boolean(one.finished);
    return `<g class="sb-tt-node${done ? " sb-tt-done" : ""}">
      <title>${escapeHtml(String(one.title || one.id))} - ${
        Number(one.size || 0)} states, ${escapeHtml(clock(one.began))} to ${
        escapeHtml(clock(one.ended))}${done ? ", finished" : ", still open"}${
        Number(one.closed || 0) ? `, ${one.closed} of ${one.of} states closed`
                                : ""}</title>
      <circle cx="${x.toFixed(1)}" cy="${y(one.id)}" r="7"></circle>
      ${done ? `<path class="sb-tt-tick" d="M ${(x - 3.2).toFixed(1)} ${
        y(one.id)} l 2.4 2.6 l 4.2 -5.2"></path>` : ""}
      <text class="sb-tt-name" x="${(x + 12).toFixed(1)}"
        y="${y(one.id) + 3.5}">${escapeHtml(
        String(one.title || one.id).slice(0, 64))}</text>
    </g>`;
  }).join("");

  const ticks = [first, (first + last) / 2, last].map((moment, index) => {
    const x = across(new Date(moment).toISOString());
    return `<text class="sb-tt-tick-label" x="${x.toFixed(1)}"
      y="${height - 8}" text-anchor="${
      index === 0 ? "start" : index === 2 ? "end" : "middle"}">${
      escapeHtml(clock(new Date(moment).toISOString()))}</text>`;
  }).join("");

  return `<div class="sb-figure sb-techtree">
    <svg viewBox="0 0 ${width} ${height}" class="sb-graph"
      preserveAspectRatio="xMidYMin meet" role="img"
      aria-label="the pieces of this task over time, and what depended on what">
      <defs><marker id="${sbTtArrow}" viewBox="0 0 8 8" refX="7" refY="4"
        markerWidth="7" markerHeight="7" orient="auto-start-reverse">
        <path d="M 0 1 L 7 4 L 0 7 z"></path></marker></defs>
      <line class="sb-tt-axis" x1="${left + 40}" y1="${height - 22}"
        x2="${right - 10}" y2="${height - 22}"></line>
      ${spansDrawn}
      ${arrows}
      ${circles}
      ${ticks}
    </svg>
    <p class="muted sb-figure-note">The pieces of this task, left to right by
      when each began; the line through a circle is how long its states ran.
      An arrow means the piece it points at <strong>could not be started until
      the other was done</strong> - a dependency, not merely a later date.
      A filled and ticked circle is finished. Rows only keep the circles
      apart and mean nothing.
      ${(plan.edges || []).length === 0
        ? ` No dependencies were found between these, which is the ordinary
            answer: most pieces of one job can be done in any order.`
        : ""}
      ${plan.why ? ` ${escapeHtml(String(plan.why))}` : ""}</p>
  </div>`;
}

/* One task, and the tasks inside it.

   The tree holds every grouping at once, which is the point of it and
   also unreadable: a hundred states is ninety-nine nested pairs. What a
   reader wants is what they would ask for out loud - a few things I have
   been doing, and what was inside each - so the page is that, opened as
   far as the reader cares to go.

   A task that was not opened says which of the three reasons stopped it,
   because "nothing here" and "three states, and a task opens at five"
   are different answers and only the second says what to change. */
/* Searched or not, in two words, on the row itself - so the answer is
   there before anything is opened. */
function stateBeatSearchBadge(task, report) {
  const found = stateBeatSummaryOf(task, report);
  const summary = found.summary;
  // THESE ARE TWO DIFFERENT FACTS AND THEY READ AS ONE. "No call" is
  // this round not asking the model anything, because the summary it
  // already has still describes what the task holds; "no search" is the
  // model being asked, and answering out of the states it was shown
  // without looking anything up. Written as "no call" and "no search"
  // they look like two shades of the same absence, and the reader is
  // left to work out which absence. So the badge leads with the number
  // of calls, which is the thing that differs, and the search is said
  // relative to it.
  if (summary.kept) {
    const said = summary.status_call || {};
    if (said.calls) {
      // A small call that asked one question. Saying "0 calls" here would
      // have been the same fault the badge was fixed for.
      return `<span class="badge sb-badge-status" title="The summary was not
        rewritten - the task has not turned over enough for that - but its
        states changed, so one small call asked where it stands now.">1 call
        - status ${said.changed ? "updated" : "unchanged"}</span>`;
    }
    return `<span class="badge" title="No model call this round: the summary
      it already has still describes what it holds, its states did not
      change, so nothing was sent and nothing was searched.">0 calls -
      summary reused</span>`;
  }
  if (!summary.title && !summary.prompt) return "";
  const calls = Math.max(1, Number(found.spent.calls || summary.calls || 1));
  const asked = Number(summary.searches || found.spent.searches
                       || (summary.looks || []).length);
  const many = (n, one) => `${n} ${one}${n === 1 ? "" : "s"}`;
  return asked
    ? `<span class="badge sb-badge-searched" title="The model was asked, and
         asked back: it looked things up inside this group before
         answering.">${many(calls, "call")}, ${many(asked, "search")}</span>`
    : `<span class="badge" title="The model was asked and answered without
         looking anything up - it is saying the states it was shown named
         what it needed.">${many(calls, "call")}, no search</span>`;
}

/* The task in four parts, with the ones this round wrote marked.

   A single paragraph answers "where was I doing this, what was it for,
   what is it, how far did I get" all at once and none of them well. These
   are the questions somebody actually has when they come back to
   something after a week, so they are four fields and not one.

   Marked, because they are updated a part at a time: a round that finds
   four new states usually moves `status` alone, and a reader looking at
   four paragraphs has no way to tell which of them is this hour's claim
   and which has stood for a fortnight. */
function stateBeatDescribed(summary) {
  const parts = summary.described || {};
  const fresh = new Set(summary.described_now || []);
  const rows = [
    ["where", "Where the work lives"],
    ["goal", "What it is in aid of"],
    ["doing", "What the work is"],
    ["status", "Where it stands"],
  ].filter(([name]) => String(parts[name] || "").trim());
  if (!rows.length) return "";
  return `<dl class="sb-described">${rows.map(([name, heading]) =>
    `<dt>${escapeHtml(heading)}${fresh.has(name)
      ? `<span class="badge sb-part-new">written this round</span>` : ""}</dt>
     <dd>${escapeHtml(String(parts[name]))}</dd>`).join("")}</dl>
    ${summary.changed_why
      ? `<p class="muted sb-changed-why">What moved: ${
          escapeHtml(String(summary.changed_why))}</p>`
      : ""}`;
}

function stateBeatTask(task, report, depth) {
  const level = Number(depth || 0);
  const key = String(task.id || "");
  // CLOSED, like everything else here. A top layer opened itself on the
  // grounds that a page which runs something and then shows a row of
  // closed rows has not shown anything - which was true when a task was a
  // title and a list of states. A task now carries its description in
  // four parts, what the call cost, whether it searched, every reply, and
  // a tech tree; eight of those unrolled at once is not a result, it is a
  // wall, and the reader cannot find the one they came for. The row
  // itself says the title, the size and whether it searched, which is
  // what choosing between them needs.
  const open = stateBeat.opened.has(key)
               && !stateBeat.opened.has(`shut:${key}`) ? " open" : "";
  const states = report.states || [];
  const summary = task.summary || {};
  const title = (id) => {
    const state = states.find((one) => one.id === id);
    return state ? String(state.title || id) : String(id);
  };
  const colour = sbColour(stateBeatTopIndex(task, report),
                          task.size >= Number((report.settings || {}).min_nodes || 5));
  const listed = (ids) => `<ul class="sb-task-states">${(ids || []).map((id) =>
    `<li><button type="button" class="trail-item"
       data-sb-node="${escapeHtml(String(id))}">${
       escapeHtml(title(id))}</button></li>`).join("")}</ul>`;
  const inside = (task.children || []).length
    ? stateBeatTechTree(task)
      + (task.children || []).map((child) =>
          stateBeatTask(child, report, level + 1)).join("")
    // The last layer: its states, as a list. There is nothing below this,
    // so listing them is the honest presentation rather than a placeholder.
    : listed(task.states);
  // What did not land in any sub-task. Said as that rather than as a
  // task of one: a state that grouped with nothing is a finding about
  // that state, and hiding it would lose it.
  const loose = (task.loose || []).length
    ? `<div class="sb-loose"><span class="event-label">${
        (task.loose || []).length} state${
        (task.loose || []).length === 1 ? "" : "s"} inside this one that are
        in none of its sub-tasks - each grouped with nothing</span>${
        listed(task.loose)}</div>`
    : "";
  return `<details class="sb-task" data-sb-open="${escapeHtml(key)}"${open}
      style="border-left-color:${colour}">
    <summary>
      <span class="sb-layer">layer ${level + 1}</span>
      <span class="sb-task-name">${escapeHtml(key.split("_").join(" "))}</span>
      <span class="trail-count">${Number(task.count || task.size || 0)}
        states</span>
      <span class="muted sb-task-figures">joined at ${
        Number(task.height || 0).toFixed(2)} · stands out ${
        Number(task.stands_out || 0).toFixed(2)}</span>
      ${stateBeatAge(task)}
      ${summary.title
        ? `<span class="sb-task-title">${escapeHtml(String(summary.title))}</span>`
        : ""}
      ${stateBeatSearchBadge(task, report)}
      ${(summary.title && summary.concrete === false)
        ? `<span class="badge sb-not-shown" title="${escapeHtml(
             String(summary.concrete_why || ""))}">not a task the user is
           shown</span>`
        : ""}
    </summary>
    <div class="sb-task-body">
      ${stateBeatSearchStory(task, report)}
      ${stateBeatCost(task, report)}
      ${stateBeatTook(task, title)}
      ${task.why_closed
        ? `<p class="beat-nothing">${escapeHtml(String(task.why_closed))}</p>`
        : ""}
      ${summary.summary
        ? `<div class="sb-summary">${escapeHtml(String(summary.summary))}</div>`
        : ""}
      ${stateBeatDescribed(summary)}
      ${summary.concrete === false
        ? `<p class="sb-not-shown-why"><strong>Kept, not shown.</strong>
           This is a way of working rather than a thing with substance
           underneath it, so it stays in the application's own notes and is
           not put in front of the user as something they are working on.
           ${escapeHtml(String(summary.concrete_why || ""))}
           <em>It is on this page because this page is the debugger.</em></p>`
        : ""}
      ${inside}
      ${loose}
    </div>
  </details>`;
}

/* Every search this summary made, in order, with all three parts.

   A summary that looked things up is not one call and cannot be read as
   one. Three things can be wrong on their own and each has to be visible:
   what it asked for, what came back, and what was then put to it. A panel
   showing only the last prompt hides the case that matters most - a search
   that returned nothing and a summary written anyway as though it had
   found something.

   The search loops, so these are numbered. */
function stateBeatSearches(summary) {
  const looks = summary.looks || [];
  if (!looks.length) {
    // Said, not omitted. A missing section and a section saying "no
    // searches" are different claims: the first could mean the field was
    // never recorded, and only the second says the model read the sample
    // and was satisfied by it.
    return `<p class="muted sb-search-none"><strong>No search.</strong> The
      states it was shown named what it needed, so it answered from the
      sample and asked for nothing further. Whatever it could not name, it
      could have looked up - it did not.</p>`;
  }
  return looks.map((look) => `<details data-sb-open="search-${
      escapeHtml(String(summary.record_id || summary.title || ""))}-${
      Number(look.number || 1)}" class="sb-search${
      look.found_nothing ? " sb-search-empty" : ""}">
    <summary><span class="event-label">search ${Number(look.number || 1)}</span>
      asked for ${(look.query && (look.query.keywords || []).length)
        ? `the words <code>${escapeHtml((look.query.keywords || []).join(", "))}</code>`
        : ""}${(look.query && (look.query.keywords || []).length
                && (look.query.ids || []).length) ? " and " : ""}${
        (look.query && (look.query.ids || []).length)
          ? `${look.query.ids.length} state${
              look.query.ids.length === 1 ? "" : "s"} by id`
          : ""}${(!(look.query && ((look.query.keywords || []).length
                 || (look.query.ids || []).length))) ? "nothing" : ""}
      - searched within the ${Number(look.searched_within || 0)} states of
      this group and nowhere else${look.found_nothing
        ? `, <strong>and found nothing</strong>` : ""}</summary>

    <p class="event-label">1. what it was asked, before it searched</p>
    <pre class="sb-prompt sb-prompt-whole">${
      escapeHtml(String(look.asked_with || ""))}</pre>

    <p class="event-label">2. what it replied - the request itself</p>
    <pre class="sb-prompt sb-prompt-whole">${
      escapeHtml(String(look.it_replied || ""))}</pre>

    <p class="event-label">3. what the search returned, from this group only</p>
    <pre class="sb-prompt sb-prompt-whole">${
      escapeHtml(String(look.found || ""))}</pre>

    <p class="event-label">4. and what was then put to it, entire${
      look.went_on === false ? " - after which it answered"
        : look.went_on ? " - after which it searched again" : ""}</p>
    <pre class="sb-prompt sb-prompt-whole">${
      escapeHtml(String(look.then_asked || ""))}</pre>
  </details>`).join("");
}

/* What this task's summary cost, and what it was actually sent.

   The prompt is here rather than described because a summary that reads
   oddly is nearly always a prompt that was odd, and the only way to see
   that is to read the thing the model read. The instruction above it is
   the same for every task and is shown once, at the foot of the page;
   what changes per task is this.

   Counted per task rather than per round: a round that spent thirty
   thousand tokens tells you nothing about which task to make cheaper. */
/* Every reply, in the order they came, and where the whole lot is kept.

   One call per summary was the first version and it is no longer true: a
   summary that looks something up is two calls or three, and the reply
   that asked for the search is a different piece of text from the reply
   that answered. Showing only the last of them hid the interesting one -
   the model saying it could not name the paper - behind the tidy answer
   it managed afterwards.

   Unaltered, and that matters here: what the user is shown has the state
   ids taken out of it, and the only way to check that rule did what it
   says is to read what arrived before the rule ran. */
function stateBeatReplies(summary) {
  const calls = summary.exchange || [];
  if (!calls.length) {
    return summary.answer
      ? `<p class="event-label">and what came back, unaltered</p>
         <pre class="sb-prompt sb-prompt-whole">${
           escapeHtml(String(summary.answer))}</pre>`
      : "";
  }
  return `<p class="event-label">and what came back - ${calls.length} repl${
    calls.length === 1 ? "y" : "ies"}, unaltered, in order</p>
    ${calls.map((one) => `<div class="sb-reply">
      <p class="muted sb-reply-head">reply ${Number(one.call || 1)} of ${
        calls.length} · ${one.asked_to_search
          ? `<strong>it asked to search</strong>${
              one.what_it_asked_for
                ? ` for ${escapeHtml([
                    (one.what_it_asked_for.keywords || []).join(", "),
                    (one.what_it_asked_for.ids || []).length
                      ? `${one.what_it_asked_for.ids.length} id(s)` : "",
                  ].filter(Boolean).join(" and "))}` : ""}`
          : "it did not ask to search"} · ${one.was_json
          ? "read as JSON" : "<strong>not JSON</strong> - nothing could be read out of it"
        } · ${Number(one.tokens_out || 0)} tokens written</p>
      <pre class="sb-prompt sb-prompt-whole">${
        escapeHtml(String(one.reply || ""))}</pre>
    </div>`).join("")}
    <p class="muted sb-kept-at">This is shown and not kept. The prompt,
      the replies, the searches and what was stripped out of the answer
      live in this page for as long as the round is on it - what the round
      produced is the task and its summary, and those are records in the
      library. Copy anything you want to keep.</p>`;
}

/* The summary a task was given, wherever it is filed.

   The cost is filed under the task the page shows and the summary under
   the community beneath it - one grouping in two orders - and a sub-task
   is summarised but has no row in `spent` at all. Both of those were
   separate bugs that showed as the same silence: no prompt, no cost, no
   search. One lookup now, used by everything that needs it. */
function stateBeatSummaryOf(task, report) {
  const spent = ((report.spent || {}).per_task || [])
    .find((one) => one.task === task.id) || {};
  const summary = ((report.communities || [])
    .find((one) => one.id === (spent.group || task.id)) || {}).summary
    || task.summary || {};
  return { spent: spent, summary: summary };
}

/* Did it search, said on the task itself.

   This was inside the cost block, which is a `details` inside a `details`:
   true, recorded, and two clicks from being read, so the honest answer to
   "did the model look anything up" was invisible on a page whose whole
   job is to answer that. The statement is out here where the task is; the
   prompts and the replies stay inside, because they are pages long. */
function stateBeatSearchStory(task, report) {
  const found = stateBeatSummaryOf(task, report);
  const summary = found.summary;
  const looks = summary.looks || [];
  const asked = Number(summary.searches || found.spent.searches || looks.length);
  if (!summary.title && !summary.prompt && !looks.length) return "";
  if (summary.kept) {
    const said = summary.status_call || {};
    if (said.calls) {
      return `<div class="sb-search-said">
        <p><strong>The summary was not rewritten; its status was.</strong>
          This task has not turned over enough for a new summary - where the
          work lives, what it is in aid of and what it consists of do not
          change because ${Number(said.arrived || 0)} state${
            Number(said.arrived || 0) === 1 ? "" : "s"} arrived${
            Number(said.left || 0)
              ? ` and ${Number(said.left)} left` : ""} - so one small call
          was made asking only where it stands now. It was shown the
          description it already had and the states that moved, and it
          ${said.changed ? "says the status has changed"
                         : "says the status has not changed"}.${said.why
            ? ` ${escapeHtml(String(said.why))}` : ""}</p>
        ${said.prompt
          ? `<details data-sb-open="status-${escapeHtml(String(task.id || ""))}">
               <summary>the whole of that call ${sbCopyButton(
                 `status-${task.id || ""}`)}</summary>
               <p class="event-label">the instruction</p>
               <pre class="sb-prompt sb-prompt-whole" data-sb-part="prompt">${
                 escapeHtml(String((said.exchange || [{}])[0].instruction
                   || ""))}</pre>
               <p class="event-label">and the message</p>
               <pre class="sb-prompt sb-prompt-whole" data-sb-part="prompt">${
                 escapeHtml(String(said.prompt))}</pre>
               <p class="event-label">and what came back, unaltered</p>
               <pre class="sb-prompt sb-prompt-whole">${
                 escapeHtml(String(said.answer || ""))}</pre>
             </details>`
          : ""}
      </div>`;
    }
    return `<p class="muted sb-search-said"><strong>Nothing was asked this
      round.</strong> The summary this task already has still describes what
      it holds and its states did not change, so no model call was made at
      all - which is a different thing from a call that chose not to
      search.${summary.why
        ? ` ${escapeHtml(String(summary.why))}` : ""}</p>`;
  }
  if (!asked) {
    // The reply it gave instead of searching, because "it did not search"
    // and "it was never asked" read the same otherwise.
    const last = (summary.exchange || [])[(summary.exchange || []).length - 1];
    return `<div class="sb-search-said sb-search-none">
      <p><strong>It was asked, and did not search.</strong> A model call was
        made for this task. It was shown a sample of the group, told the
        sample is incomplete and that it could ask for keywords or for any
        state by id, and it answered without asking - so it is saying the
        states it saw named what it needed.</p>
      ${last && last.reply
        ? `<details data-sb-open="answered-${escapeHtml(String(task.id || ""))}">
             <summary>the answer it gave instead, unaltered</summary>
             <pre class="sb-prompt sb-prompt-whole">${
               escapeHtml(String(last.reply))}</pre></details>`
        : ""}
    </div>`;
  }
  return `<div class="sb-search-said">
    <p><strong>It searched ${asked === 1 ? "once" : `${asked} times`}.</strong>
      Each search read the ${Number((looks[0] || {}).searched_within || 0)}
      states of this group and nothing else - reaching the whole calendar
      would answer with a state from another month and it could not tell
      that it had.</p>
    ${stateBeatSearches(summary)}
  </div>`;
}

function stateBeatCost(task, report) {
  const spent = ((report.spent || {}).per_task || [])
    .find((one) => one.task === task.id) || {};
  // By the id the cost was filed under, not by the task's own name. The
  // communities are named `group_1` and the tasks `task_1`, so comparing
  // the two never matched and this block was never once drawn - the
  // prompt was collected, sent to the page, and silently dropped here.
  //
  // AND FALLING BACK TO THE TASK'S OWN SUMMARY, because only the top layer
  // has a row in `spent`. A sub-task is summarised too - it has to be, for
  // the tech tree to have names on it - and without this fallback every
  // one of those summaries showed no prompt, no cost and no search at all,
  // which is the same silence as before in a different place.
  const summary = ((report.communities || [])
    .find((one) => one.id === (spent.group || task.id)) || {}).summary
    || task.summary || {};
  if (!spent.calls && !(summary.prompt || (summary.looks || []).length)) {
    return "";
  }
  if (spent.kept || summary.kept) {
    return `<p class="muted sb-cost">No model call: the summary it already
      has still describes what it holds.${summary.why
        ? ` ${escapeHtml(String(summary.why))}` : ""}</p>`;
  }
  return `<details class="sb-cost" data-sb-open="cost-${
      escapeHtml(String(task.id || ""))}">
    <summary><span class="event-label">~${Number(spent.sent_tokens || 0)} sent
      (${Number(spent.prompt_tokens || 0)} of states, ${
      Math.max(0, Number(spent.sent_tokens || 0)
                  - Number(spent.prompt_tokens || 0))} of instruction),
      ${Number(spent.searches || summary.searches || 0)
        ? `· looked things up ${Number(spent.searches || summary.searches)} time${
            Number(spent.searches || summary.searches) === 1 ? "" : "s"} `
        : "· did not look anything up "}·
      and the model saw ${Number(spent.tokens_in || 0)
        + Number(spent.tokens_new || 0)} it had not seen before${
      Number(spent.tokens_cached || 0)
        ? ` plus ${Number(spent.tokens_cached)} it had (its own system prompt
            and tools, which go with every call)`
        : ""}, and wrote ${Number(spent.tokens_out || 0)}, in ${
      ((Number(spent.ms || 0)) / 1000).toFixed(1)}s</span>
      - the prompt it was sent ${sbCopyButton(`task-${task.id || ""}`)}</summary>
    ${Number(summary.joins || 0) >= 2
      ? `<p class="muted sb-listy"><strong>This reads as a list, not a
           summary.</strong> Its first sentence joins ${
           Number(summary.joins)} things together, which is usually the
           group described from too low down - the states again, with the
           dates taken off. The prompt asks for the one thing they were all
           for; this is here so a change to it can be judged.</p>`
      : ""}
    <p class="event-label">the instruction, sent as the system prompt with
      every summary (${Number(report.instruction_tokens || 0)} tokens)</p>
    <pre class="sb-prompt sb-prompt-whole" data-sb-part="prompt">${
      escapeHtml(String(report.instruction || ""))}</pre>
    <p class="event-label">and then this, as the message - the whole of it,
      exactly as the model received it</p>
    <pre class="sb-prompt sb-prompt-whole" data-sb-part="prompt">${
      escapeHtml(String(summary.prompt || ""))}</pre>
    ${stateBeatReplies(summary)}
  </details>`;
}

/* Which of the top tasks this one is inside, so that a sub-task keeps the
   colour of the thing it belongs to rather than getting one of its own. */
/* What this round kept, and why it did or did not find the tasks again.

   The useful question on a quiet round is not "did it rebuild" but "how
   close was it", so every signal is shown with its value against its
   limit whether or not it fired. A panel that only says yes or no cannot
   answer that, and the reader is left watching a number they cannot see. */
function stateBeatKept(report) {
  const kept = report.continuity;
  if (!kept) return "";
  const signals = kept.signals || [];
  const lineage = (kept.lineage || []).filter((row) => !row.ended);
  const ended = (kept.lineage || []).filter((row) => row.ended);
  const bar = (signal) => {
    const value = Number(signal.value || 0);
    const limit = Number(signal.limit || 0);
    const share = limit > 0 ? Math.max(0, Math.min(1, value / limit)) : 0;
    return `<li class="sb-signal${signal.fired ? " sb-signal-fired" : ""}">
      <span class="sb-signal-name">${escapeHtml(String(signal.name || ""))}</span>
      <span class="sb-signal-track"><span class="sb-signal-fill"
        style="width:${(share * 100).toFixed(0)}%"></span></span>
      <span class="sb-signal-figures">${value} of ${limit}</span>
      <span class="sb-signal-why">${escapeHtml(String(signal.why || ""))}</span>
    </li>`;
  };
  const scope = kept.window || {};
  const outside = Number(scope.before_the_beginning || 0);
  return `<div class="sb-kept${kept.rebuilt ? " sb-kept-rebuilt" : ""}">
    <p class="muted sb-scope">
      <strong>${scope.kind === "first"
        ? `The first grouping: the last ${Number(scope.days || 0)} days`
        : "Every state since this grouping began"}</strong>
      - ${Number(scope.read || 0)} state${
        Number(scope.read || 0) === 1 ? "" : "s"} read${
        Number(scope.states_in_all || 0)
          ? ` of ${scope.states_in_all} on the calendar` : ""}.
      ${outside
        ? `${outside} older state${outside === 1 ? " is" : "s are"} outside
           this window. ${scope.kind === "first"
             ? `On a first grouping that is the ${Number(scope.days || 0)}-day
                limit, which defers rather than excludes: ${
                outside === 1 ? "it" : "they"} will be read on the next round
                if ${outside === 1 ? "it is" : "they are"} among the newest
                ${Number(scope.cap || 0)} by then.`
             : `Being outside the newest ${Number(scope.cap || 0)} is what
                keeps ${outside === 1 ? "it" : "them"} out, and ${
                outside === 1 ? "it stays" : "they stay"} out while that is
                true.`}`
        : ""}
      ${scope.at_the_cap
        ? `The window is full at ${Number(scope.cap || 0)}, so the oldest have
           fallen outside it and the tasks holding them have let them go.`
        : ""}
    </p>
    <p class="beat-head-line">
      <strong>${kept.rebuilt
        ? "The tasks were found again from every state."
        : "The tasks are the ones that were already here."}</strong>
      ${escapeHtml(String(kept.why || ""))}
    </p>
    <p class="muted">${Number(kept.kept_tasks || 0)} task${
      Number(kept.kept_tasks || 0) === 1 ? "" : "s"} ·
      ${Number(kept.arrivals || 0)} state${
      Number(kept.arrivals || 0) === 1 ? "" : "s"} new since the last round,
      of which ${Number(kept.placed || 0)} joined a task and ${
      Number(kept.loose || 0)} matched none ·
      the calendar has grown by ${Number(kept.since_rebuild || 0)} state${
      Number(kept.since_rebuild || 0) === 1 ? "" : "s"} since the last
      rebuild${Number(kept.forgotten || 0)
        ? ` · ${kept.forgotten} state${kept.forgotten === 1 ? " is" : "s are"}
           no longer active and ${kept.forgotten === 1 ? "was" : "were"}
           forgotten by the task holding ${kept.forgotten === 1 ? "it" : "them"}`
        : ""}</p>
    ${signals.length
      ? `<ul class="sb-signals">${signals.map(bar).join("")}</ul>`
      : `<p class="beat-nothing">No signals were asked: there was nothing kept
         to compare this round against.</p>`}
    ${lineage.length
      ? `<details class="sb-lineage" data-sb-open="lineage"
         ><summary>What became what</summary>
         <ul>${lineage.map((row) => `<li>
           <span class="badge">${escapeHtml(String(row.kind || ""))}</span>
           ${Number(row.size || 0)} states${row.overlap
             ? ` · ${(Number(row.overlap) * 100).toFixed(0)}% of it was the
                 same task before` : ""}${(row.from || []).length
             ? ` · out of ${escapeHtml((row.from || []).join(", "))}` : ""}
           </li>`).join("")}
         ${ended.map((row) => `<li><span class="badge">ended</span>
           ${escapeHtml((row.ended || []).join(", "))} - kept, not deleted, so
           what replaced it can point back at it</li>`).join("")}
         </ul></details>`
      : ""}
  </div>`;
}

/* How long this has been this task. A task that has held together for
   three weeks is a different claim from one found ten minutes ago, and
   the page should not make them look the same. */
function stateBeatAge(task) {
  const kept = task.kept;
  if (!kept || !kept.since) return "";
  const since = new Date(kept.since);
  if (Number.isNaN(since.getTime())) return "";
  const days = Math.floor((Date.now() - since.getTime()) / 86400000);
  const age = days < 1 ? "found today"
    : days === 1 ? "a task since yesterday"
    : `a task for ${days} days`;
  return `<span class="muted sb-task-age">${age}${
    Number(kept.version || 1) > 1
      ? ` · through ${kept.version - 1} rebuild${kept.version === 2 ? "" : "s"}`
      : ""}${Number(kept.drift || 0) > 0
      ? ` · centre moved ${Number(kept.drift).toFixed(3)}` : ""}</span>`;
}

/* The states that joined this task this round, named. Not a count: the
   whole question a reader has about an appending round is whether the
   thing that arrived belongs where it was put, and a number cannot be
   disagreed with. */
function stateBeatTook(task, title) {
  const took = ((task.kept || {}).took) || [];
  if (!took.length) return "";
  return `<div class="sb-took"><span class="event-label">${took.length} new
    state${took.length === 1 ? "" : "s"} joined this task this round, without
    the grouping being computed again</span>
    <ul class="sb-task-states">${took.map((id) =>
      `<li><button type="button" class="trail-item"
        data-sb-node="${escapeHtml(String(id))}">${
        escapeHtml(title(id))}</button></li>`).join("")}</ul></div>`;
}

/* A number that is always the same for the same text: what a thing's
   colour is drawn from when it has no seat. */
function sbStable(text) {
  let hash = 2166136261;
  for (const ch of String(text || "")) {
    hash ^= ch.codePointAt(0);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return hash % 997;
}

/* WHICH COLOUR A TASK IS, for life. Its seat - assigned once and kept -
   and, for something with none, its id. Never its row: the row moves when
   the picture is cut to the last day instead of the last week, or sorted
   another way, and the same task came out another colour. */
function stateBeatTopIndex(task, report) {
  const top = report.layers || [];
  const seated = (one) => one && Number.isInteger(one.seat) && one.seat >= 0;
  if (seated(task)) return task.seat;
  if (task && (task.id || task.task_id)) {
    const known = top.find((one) => one.id === task.id
      || (task.task_id && one.task_id === task.task_id));
    if (seated(known)) return known.seat;
    return sbStable(task.task_id || task.id);
  }
  return stateBeatTopIndexByStates(task, report);
}

function stateBeatTopIndexByStates(task, report) {
  const top = report.layers || [];
  // BY ID FIRST. This matched on shared STATE ids, which works for the
  // things it was written for - groups carrying their members - and not
  // at all for the tree, whose nodes carry an id, a span and a size and
  // no states. Every node therefore fell through to the default 0 and
  // every task in the picture was drawn the same colour, which is
  // visible in a screenshot and invisible in any count of elements.
  const mine = new Set(task.states || []);
  for (let index = 0; index < top.length; index += 1) {
    if ((top[index].states || []).some((id) => mine.has(id))) {
      const one = top[index];
      return Number.isInteger(one.seat) && one.seat >= 0
        ? one.seat : sbStable(one.task_id || one.id);
    }
  }
  return 0;
}

/* The words every member shares, which is usually why the group exists.

   Shown apart from the summary because they are the evidence for the
   grouping rather than for the summary: a group whose only shared word is
   a filename is a group a reader should distrust, and that is visible here
   and nowhere else. */
function stateBeatShared(group) {
  const said = group.shared_said || [];
  // The whole files where every member names the same one, and the term
  // pieces otherwise: the pieces are what the grouping ran on, and
  // `01749, 023, com, https` is not something to put in front of a reader.
  const rests = (group.shared_sources || []).length
    ? group.shared_sources : (group.shared_rests_on || []);
  if (!said.length && !rests.length) {
    return `<div class="sb-part muted">Nothing is shared by every member -
      they are joined through each other rather than all at once.</div>`;
  }
  const row = (label, words) => words.length
    ? `<div class="sb-part"><span class="event-label">${label}</span>
       ${words.map((word) => `<code class="sb-term">${escapeHtml(String(word))}</code>`)
         .join(" ")}</div>`
    : "";
  return row("Words all of them use", said)
    + row("Files and pages all of them rest on", rests);
}

function stateBeatWhen(state) {
  const at = (value) => {
    const when = value ? new Date(value) : null;
    return when && !Number.isNaN(when.getTime()) ? when.toLocaleString() : "";
  };
  const from = at(state.starts_at);
  const added = at(state.added);
  return from ? `${from}${added ? ` · added ${added}` : ""}` : added;
}

/* The pairs, highest score first.

   This is the part that answers "why is this threshold wrong": a reader
   who thinks two groups should be one can see the pair that did not quite
   join and what it scored, and a reader who thinks one group should be two
   can see the pair that joined them and on what word. */
function stateBeatPairs(report) {
  const pairs = (report.similarity || {}).pairs || [];
  if (!pairs.length) return "";
  const threshold = Number((report.settings || {}).threshold || 0);
  const rows = pairs.map((pair) => `<tr class="${
    Number(pair.score) >= threshold ? "" : "sb-unjoined"}">
    <td class="sb-score">${Number(pair.score).toFixed(2)}</td>
    <td class="muted">${Number(pair.distance).toFixed(2)}</td>
    <td>${escapeHtml(String(pair.a_title || ""))}</td>
    <td>${escapeHtml(String(pair.b_title || ""))}</td>
    <td class="muted">${(pair.shared_said || []).slice(0, 6)
      .map((word) => escapeHtml(String(word))).join(", ")}</td>
  </tr>`).join("");
  /* Said in full, because "every pair that shared anything, highest
     first (60 shown)" named neither what was counted nor what was left
     out: 60 of what, out of how many, and what makes a row grey. */
  const scored = Number((report.similarity || {}).pairs_scored || pairs.length);
  const states = Number(report.states_considered || 0);
  const possible = states > 1 ? (states * (states - 1)) / 2 : 0;
  const silent = Math.max(0, possible - scored);
  return `<details data-sb-open="pairs" class="sb-pairs">
    <summary class="muted">the ${pairs.length} highest-scoring pairs of
      states${scored > pairs.length ? `, out of ${scored.toLocaleString()} scored`
        : ""}</summary>
    <p class="muted sb-figure-note">Every state was compared with every other
      one: ${possible.toLocaleString()} pairs.
      ${silent ? `${silent.toLocaleString()} of them had no word in common at
        all and are not scored or listed; the remaining
        ${scored.toLocaleString()} are, ` : `All ${scored.toLocaleString()} of
        them shared at least one word, `}and the strongest
      ${pairs.length} are in the table. Each row is one pair: its combined
      score, then the two halves it is made of, then the words the two
      states share. <span class="sb-unjoined">Rows in grey scored below
      ${threshold ?? "the threshold"} and did not join</span> - those are
      the ones to read if two groups should have been one.</p>
    <table class="sb-table">
      <thead><tr><th>alike</th><th>apart</th><th>one state</th>
        <th>the other</th><th>words they share</th></tr></thead>
      <tbody>${rows}</tbody>
    </table>
  </details>`;
}

/* One state, opened from its node.

   A node carries a title in a tooltip, which answers "which state is
   this" and none of the questions that follow: what it rests on, when it
   ran, which group it landed in and why. Those are on the state, and the
   picture is where somebody is standing when they want them - so the node
   opens the state rather than sending the reader to find it in the list
   underneath. */
function openStateBeatNode(circle) {
  const report = stateBeat.report || {};
  const id = circle.getAttribute("data-sb-node");
  const state = (report.states || []).find((one) => one.id === id);
  if (!state) return;
  // Which group the cut left it in, read off the groups themselves. The
  // picture is the tree now, and its leaves are the states rather than a
  // second copy of them.
  const group = (report.communities || []).find((one) =>
    (one.members || []).some((member) => member.id === id));
  const row = (label, value) => value
    ? `<div class="event-row"><span class="event-label">${escapeHtml(label)}</span>
       <span>${escapeHtml(String(value))}</span></div>` : "";
  const list = (label, items) => (items || []).length
    ? `<div class="event-detail-body"><div class="muted">${escapeHtml(label)}</div>
       <ul class="trace-evidence">${items.map((item) =>
         `<li>${escapeHtml(String(item))}</li>`).join("")}</ul></div>` : "";
  // Its strongest neighbours, which is the question the picture raises:
  // this node is over here rather than over there, and these are the
  // edges that put it there.
  const threshold = Number((report.settings || {}).threshold || 0);
  const near = ((report.similarity || {}).pairs || [])
    .filter((pair) => pair.a === id || pair.b === id)
    .slice(0, 6)
    .map((pair) => {
      const other = pair.a === id ? pair.b : pair.a;
      const title = ((report.states || []).find((one) => one.id === other)
                     || {}).title || other;
      return `${Number(pair.score).toFixed(2)}${
        Number(pair.score) >= threshold ? "" : " (outside the cut)"}`
        + ` \u2014 ${title}`;
    });
  const opened = openPopover(circle, `
      <div class="event-head">
        <span class="badge ${group && group.big_enough ? "ok" : ""}">${
          group ? escapeHtml(String(group.id || "").split("_").join(" "))
                : "no group"}${group && !group.big_enough ? " · too small" : ""}</span>
        <h3>${escapeHtml(String(state.title || "(untitled state)"))}</h3>
        <button type="button" class="small secondary" id="event-close">Close</button>
      </div>
      ${row("Ran", [state.starts_at, state.ends_at].filter(Boolean)
        .map((when) => new Date(when).toLocaleString()).join(" to "))}
      ${row("Added", state.added ? new Date(state.added).toLocaleString() : "")}
      ${row("Status", state.status)}
      <div class="event-detail-body">
        <div class="muted">Detail</div>
        ${state.detail
          ? `<div class="event-body">${escapeHtml(String(state.detail))}</div>`
          : `<div class="event-body missing">No detail was written for this
             state.</div>`}
      </div>
      ${list("What it rests on", state.sources)}
      ${list("Evidence", state.evidence)}
      ${list("Most alike, of every other state", near)}
      <div class="muted event-note">Grouped by what the states mean, not by
        anything a model was asked.</div>`);
  $("#event-close").addEventListener("click", opened.close);
}

/* The instruction every group is summarised under.

   A panel that shows the message and not the instruction shows half of
   what the model was asked - and the half that varies. The message is the
   states; the instruction is what it was told to make of them, and an
   answer that reads oddly is usually explained by the second.

   Once, not per group: it is the same text every time, and printing it
   beside each group would be the same two thousand tokens repeated down
   the page. Which is also what it costs - it is sent again with every
   call, and the per-group line says so. */
function stateBeatInstruction(report) {
  const instruction = String(report.instruction || "");
  if (!instruction) return "";
  return `<details data-sb-open="how-two" class="sb-how">
    <summary class="muted">the instruction every group is summarised under,
      ${Number(report.instruction_tokens || 0).toLocaleString()} tokens ·
      sent again with each call</summary>
    <pre class="beat-context">${escapeHtml(instruction)}</pre>
  </details>`;
}

async function runStateBeat(scope) {
  if (stateBeat.running) return;
  const mine = stateBeat.round;
  stateBeat.running = true;
  stateBeat.attached = false;
  stateBeat.report = null;
  stateBeat.rehearsal = null;
  renderStateBeat();
  followStateBeat();
  try {
    const finished = await api.post("/api/state_heartbeat/run",
                                    { scope: scope === "sandbox" ? "sandbox" : "live" });
    if (mine !== stateBeat.round) return;
    stateBeat.report = finished;
  } catch (err) {
    stateBeat.report = { skipped: err.message };
  } finally {
    stateBeat.running = false;
    renderStateBeat();
    // A real round may have started working out the connections.
    loadStateBeatConnections();
  }
}

/* Follow a round while it runs, the way a progress bar does: only while
   there is something happening, and stopping the moment there is not.

   Not a standing timer. A page that reloads itself every fifteen seconds
   is doing work when nobody is looking and is still out of date at the
   moment someone is; this asks four hundred milliseconds apart for as
   long as a round is in flight and then stops, which is the opposite
   arrangement.

   What it reads is the half-written report itself, not a separate
   account of it - the round fills one object and this is that object, so
   the two cannot disagree. */
async function followStateBeat() {
  if (stateBeat.following) return;
  stateBeat.following = true;
  let tag = null;
  try {
    while (stateBeat.running) {
      // Only while it can be seen: the report is megabytes, and drawing it
      // into a tab nobody is looking at is all cost. The next look after
      // the tab is back catches up at once.
      if (!document.hidden && activeTab === "statebeat") {
        try {
          const got = await api.getIfChanged("/api/state_heartbeat/progress", tag);
          tag = got.tag;
          const state = got.data;
          if (got.changed && state && Object.keys(state).length
              && stateBeat.running) {
            stateBeat.report = state;
            // A round this page did not start has no answer coming back
            // to end the following; its own report saying it has stopped
            // is the end.
            if (stateBeat.attached && !state.running) stateBeat.running = false;
            renderStateBeat();
          }
        } catch (err) {
          /* following is an aid, never a reason for the round to fail */
        }
      }
      await new Promise((resolve) => setTimeout(resolve, 400));
    }
  } finally {
    stateBeat.following = false;
  }
}

/* One look, when the tab is opened. If a round happens to be in flight -
   started by the timer, or still going from a previous visit - the page
   attaches to it rather than showing a stale result with no sign that
   anything is happening. */
async function loadStateBeat() {
  try {
    const state = await api.get("/api/state_heartbeat/progress");
    if (!state || !Object.keys(state).length) return;
    stateBeat.report = state;
    stateBeat.running = Boolean(state.running);
    stateBeat.attached = stateBeat.running;
    renderStateBeat();
    if (stateBeat.running) followStateBeat();
  } catch (err) {
    /* the panel is an aid */
  }
}

/* Where the sandbox is and what is in it, said in one line. The two
   folders are named in full because the point of the sandbox is that a
   person can go and look at what went in and what came out. */
async function loadSandbox() {
  const host = $("#dbg-sb-where");
  if (!host) return;
  try {
    const state = await api.get("/api/state_heartbeat/sandbox");
    const where = state.where || {};
    host.innerHTML = `${Number(state.states || 0)} made-up state${
      Number(state.states || 0) === 1 ? "" : "s"} in
      <code>${escapeHtml(String(where.states_from || ""))}</code>,
      ${Number(state.tasks_written || 0)} task${
      Number(state.tasks_written || 0) === 1 ? "" : "s"} written to
      <code>${escapeHtml(String(where.tasks_to || ""))}</code>
      (${Number(state.tasks_kept || 0)} kept between runs,
      ${Number(state.runs || 0)} run${Number(state.runs || 0) === 1 ? "" : "s"}).`;
  } catch (err) {
    host.textContent = err.message;
  }
}

async function makeUpStates() {
  const count = Number($("#dbg-sb-count")?.value || 60);
  const days = Number($("#dbg-sb-days")?.value || 14);
  try {
    const made = await api.post("/api/state_heartbeat/sandbox/states",
                                { how_many: count, days });
    const subjects = Object.entries(made.subjects || {})
      .map(([name, n]) => `${n} ${name}`).join(", ");
    toast(`${made.written} states made up: ${subjects}`, "ok");
    await loadSandbox();
  } catch (err) {
    toast(err.message, "error");
  }
}

/* The whole mechanism in one press: more states than the window holds,
   then a few more, then a few more again.

   Three rounds rather than two, because two do not show it. The second
   round over a fresh grouping nearly always rebuilds - a first grouping
   leaves states in no task, those are offered again every round, and a
   handful more pushes the pile over the limit - so it is the third that
   shows the ordinary hour: a few dot products and no model call. */
async function rehearseAppending() {
  if (stateBeat.running) return;
  const mine = stateBeat.round;
  stateBeat.running = true;
  stateBeat.attached = false;
  stateBeat.report = null;
  renderStateBeat();
  followStateBeat();
  try {
    const out = await api.post("/api/state_heartbeat/sandbox/rehearse", {
      then: Number($("#dbg-sb-count")?.value || 40),
      days: Number($("#dbg-sb-days")?.value || 30),
    });
    // Given up on while this was in flight: its three rounds describe
    // states that have been deleted since, so they are not drawn.
    if (mine !== stateBeat.round) return;
    if (out.given_up) {
      stateBeat.rehearsal = null;
      stateBeat.report = null;
      toast(String(out.why || "The sandbox was emptied."), "ok");
      return;
    }
    stateBeat.rehearsal = out;
    // The last round is the one the page shows, because it is the one
    // that demonstrates appending. The two before it are in the trace.
    stateBeat.report = out.round_three || out.round_two || out.round_one;
  } catch (err) {
    stateBeat.report = { skipped: err.message };
  } finally {
    stateBeat.running = false;
    renderStateBeat();
    loadSandbox();
  }
}

/* A rehearsal, read one round at a time and then compared.

   The rounds have to be readable separately, because the thing being
   looked at is what CHANGED between them: the first grouping, then an
   append, then another. A single result with the three of them averaged
   into it answers nothing. So each round gets its own section - what it
   did, the whole calendar as it stood, and the tasks it ended with - and
   the three are put side by side afterwards, which is the only place a
   comparison belongs. */
function stateBeatRehearsal() {
  const out = stateBeat.rehearsal;
  if (!out) return "";
  const rounds = stateBeatRounds(out);
  return `<div class="sb-rehearsal">
    <p class="beat-head-line"><strong>Rehearsal</strong>
      <span class="muted">${rounds.length} rounds over a window of ${
        Number(out.cap || 0)} states.
        ${escapeHtml(String(out.why || ""))}</span></p>
    ${rounds.map((one, index) =>
      stateBeatRound(one, index, out)).join("")}
    ${stateBeatCompare(rounds, out)}
  </div>`;
}

/* The rounds that happened, with the steps that belong to each. */
function stateBeatRounds(out) {
  const named = [
    { name: "Round one: the first grouping", report: out.round_one },
    { name: "Round two: appending", report: out.round_two },
    { name: "Round three: appending again", report: out.round_three },
  ].filter((one) => one.report && Object.keys(one.report).length);
  // The trace is a flat list of steps; each round's own step is the one
  // that names it, and whatever preceded it belongs to it too.
  const steps = out.trace || [];
  let taken = 0;
  return named.map((one, index) => {
    const at = steps.findIndex((step, where) =>
      where >= taken && /^round /i.test(String(step.step || "")));
    const mine = at < 0 ? [] : steps.slice(taken, at + 1);
    taken = at < 0 ? taken : at + 1;
    return { ...one, steps: mine, index };
  });
}

/* One round: what it did, the calendar as it stood, and its tasks. */
function stateBeatRound(one, index, out) {
  const report = one.report;
  const kept = report.continuity || {};
  const key = `rehearsal-round-${index}`;
  // Closed unless the reader opened it. Opening the first one for them was
  // a guess about which round they came to read, and three rounds of tasks
  // and overviews unrolled at once is a page nobody can find their place
  // on.
  const open = stateBeat.opened.has(key) ? " open" : "";
  const detail = (entry) => Object.entries(entry.detail || {})
    .map(([name, value]) => `<li>${escapeHtml(name.split("_").join(" "))}:
      <code>${escapeHtml(typeof value === "object"
        ? JSON.stringify(value) : String(value))}</code></li>`).join("");
  return `<details class="sb-round" data-sb-open="${escapeHtml(key)}"${open}>
    <summary>
      <span class="sb-task-name">${escapeHtml(one.name)}</span>
      <span class="trail-count">${Number(kept.kept_tasks || 0)} tasks</span>
      <span class="muted">${Number(report.states_considered || 0)} states read,
        ${Number(kept.arrivals || 0)} new, ${
        kept.rebuilt ? "rebuilt" : "appended only"}, ${
        ((Number(report.duration_ms) || 0) / 1000).toFixed(1)}s</span>
    </summary>
    <div class="sb-round-body">
      <ol class="sb-trace">${(one.steps || []).map((entry) => `<li>
        <strong>${escapeHtml(String(entry.step || ""))}</strong>
        <ul class="sb-trace-detail">${detail(entry)}</ul>
        ${entry.why ? `<p class="muted">${escapeHtml(String(entry.why))}</p>` : ""}
      </li>`).join("")}</ol>
      ${stateBeatStage(report)}
      ${stateBeatOverview(report)}
      ${stateBeatWholeTree(report)}
      ${stateBeatKept(report)}
      ${stateBeatAnchors(report)}
      ${(report.layers || []).map((task) =>
        stateBeatTask(task, report)).join("")}
      ${(report.loose || []).length
        ? `<p class="muted">${report.loose.length} state${
            report.loose.length === 1 ? "" : "s"} in no task at the end of
            this round.</p>`
        : ""}
    </div>
  </details>`;
}

/* And the three of them together, which is the only place a comparison
   belongs: the rounds above are each true on their own, and this says
   what moved between them. */
/* One task, followed through every round of the rehearsal.

   The table above says how big each task was in each round, which
   answers "did it grow" and nothing else. The question a rehearsal
   exists to answer is what APPENDING DID: which states arrived, whether
   the task was still the same task afterwards, and whether the words
   describing it changed - and if they did, which of them and why.

   Every task that existed in any round appears, including ones that only
   appear later: a task absent from round one is a finding about round
   one, and leaving it out of the table would hide the arrival that the
   rehearsal was run to watch. */
/* One state, with everything the model was given about it.

   The same fields in the same order as `_whole_state` puts in front of
   the model: what it said, why the review wrote it, when it ran on the
   user's own clock, what it rests on and what it recorded. A panel that
   shows a title where the model read eight fields is a panel that cannot
   answer why the model concluded what it did - and a list of titles that
   stops at six and says "and 8 more" hides the states most likely to be
   the odd ones, since they are in no particular order.

   An empty field is SAID to be empty, for the reason the prompt says it:
   a missing line and a line saying "none" are different claims, and only
   the second one can be checked. */
function sbWholeStateRow(state, saw) {
  // HOW MUCH OF IT THE MODEL READ. Three depths, and drawing all three
  // the same way invites the reader to explain a summary by a field the
  // model never saw.
  //
  //   in full  - it asked for this state by name or by word, and got
  //              everything: the reasoning, the status, every source and
  //              every piece of evidence.
  //   sampled  - it was one of the forty shown with the group: title,
  //              detail, when it ran, and the first eight of each kind
  //              of evidence. No reasoning and no status.
  //   neither  - it was never in front of the model at all. A sampled
  //              state stood in for it and it was a number in "and 12
  //              more like it".
  const how = (saw || {}).in_full && saw.in_full.includes(state.id)
    ? "full"
    : ((saw || {}).sampled && saw.sampled.includes(state.id))
      ? "sample" : "unseen";
  if (how === "unseen") {
    return `<div class="sb-whole-state sb-state-unseen">
      <div class="sb-whole-title">${escapeHtml(String(
        state.title || state.id))}</div>
      <p class="muted">The model never saw this state. It was in the
        group and outside the sample, so another state stood in for it and
        it reached the prompt only as a number. Its words are here because
        this is the debugger.</p>
      <p>${escapeHtml(String(state.detail || "(no detail)"))}</p>
    </div>`;
  }
  return sbStateAsRead(state, how);
}

function sbStateAsRead(state, how) {
  const said = state.local || {};
  const ran = said.starts_at
    ? `${escapeHtml(String(said.starts_at_day || ""))}, ${
        escapeHtml(String(said.starts_at))}${said.ends_at
        ? ` to ${escapeHtml(String(said.ends_at))}` : ""}${said.zone
        ? ` [${escapeHtml(String(said.zone))}]` : ""}`
    : `${escapeHtml(String(state.starts_at || "?"))} to ${
        escapeHtml(String(state.ends_at || "?"))} (UTC - no local time)`;
  const list = (items, empty) => (items || []).length
    ? `<ul>${(items || []).map((one) =>
        `<li>${escapeHtml(String(one))}</li>`).join("")}</ul>`
    : `<p class="muted">${empty}</p>`;
  const whole = how === "full";
  // The sample is shown the first eight of each; a state fetched by name
  // is shown all of them. Saying which is shown is the difference
  // between "it rests on three files" and "it rests on three of the
  // nineteen files it names".
  const some = (items) => whole ? (items || []) : (items || []).slice(0, 8);
  return `<div class="sb-whole-state">
    <div class="sb-whole-title">${escapeHtml(String(state.title || state.id))}
      <span class="badge sb-state-how">${whole
        ? "read in full - it asked for this one"
        : "as it appeared in the sample"}</span></div>
    <p>${escapeHtml(String(state.detail || "(no detail)"))}</p>
    ${whole
      ? `<p class="muted"><span class="event-label">why the review wrote
           it</span> ${escapeHtml(String(
           state.reasoning || "(it did not say)"))}</p>`
      : ""}
    <p class="muted"><span class="event-label">ran</span> ${ran}${whole
      ? ` &middot; <span class="event-label">status</span> ${
          escapeHtml(String(state.status || "(none)"))}` : ""}</p>
    <div class="sb-whole-rests"><span class="event-label">rests on</span>
      ${list(some(state.sources),
             "this state names no file, page or window")}${
      !whole && (state.sources || []).length > 8
        ? `<p class="muted">and ${(state.sources || []).length - 8} more it
           did not see</p>` : ""}</div>
    <div class="sb-whole-rests"><span class="event-label">evidence</span>
      ${list(some(state.evidence), "this state records none")}${
      !whole && (state.evidence || []).length > 8
        ? `<p class="muted">and ${(state.evidence || []).length - 8} more it
           did not see</p>` : ""}</div>
  </div>`;
}

function stateBeatTaskRounds(rounds, every, shownAs) {
  const layerOf = (one, taskId) =>
    ((one.report || {}).layers || [])
      .find((task) => task.task_id === taskId) || null;
  const stateIn = (one, id) =>
    ((one.report || {}).states || []).find((state) => state.id === id)
      || { id: id };
  const PARTS = [["where", "Where the work lives"],
                 ["goal", "What it is in aid of"],
                 ["doing", "What the work is"],
                 ["status", "Where it stands"]];

  return every.map((taskId) => {
    let before = null;          // the members when it was last seen
    let saidBefore = {};        // and what it was described as then
    const rows = rounds.map((one, index) => {
      const task = layerOf(one, taskId);
      if (!task) {
        // NOT YET, or gone. Said either way rather than left blank: an
        // empty cell reads as "nothing changed".
        return `<tr><td class="sb-across-when">${
          escapeHtml(one.name.split(":")[0])}</td>
          <td colspan="2" class="muted">n/a - ${before === null
            ? "this task did not exist in this round"
            : "this task is not in this round; it ended or was merged away"
          }</td></tr>`;
      }
      const mine = (task.states || []).map(String);
      const fresh = before === null
        ? [] : mine.filter((id) => !before.includes(id));
      const lost = before === null
        ? [] : before.filter((id) => !mine.includes(id));
      const said = (task.summary || {}).described || {};
      const moved = new Set((task.summary || {}).described_now || []);
      const heldOn = before === null
        ? 0 : mine.filter((id) => before.includes(id)).length;
      const states = before === null
        ? `<strong>${mine.length}</strong> state${mine.length === 1 ? "" : "s"}
           to begin with`
        : `<strong>${mine.length}</strong> in all: ${heldOn} stayed${
            fresh.length ? `, ${fresh.length} new` : `, none new`}${
            lost.length ? `, ${lost.length} gone` : ""}`;
      // ALL of them, each to the depth the model read it, in three
      // groups: what arrived, WHAT STAYED, and what left. What stayed is
      // as much a fact as what moved - a task of twenty-six that gained
      // eighteen and lost seventeen has eight states running through it,
      // and those eight are the thing that makes it the same task. A page
      // that shows only the movement shows the churn and hides the
      // subject. Not the first six and a count, either: the states left
      // out of a truncated list are in no particular order, so the ones
      // hidden are as likely as not to be the ones worth reading.
      const saw = (task.summary || {}).seen || {};
      const block = (ids, key, said) => ids.length
        ? `<details class="sb-across-states-block"
             data-sb-open="${key}-${escapeHtml(String(taskId))}-${index}">
             <summary>${said(ids.length)}</summary>
             ${ids.map((id) =>
               sbWholeStateRow(stateIn(one, id), saw)).join("")}
           </details>`
        : "";
      const listed = before === null
        ? block(mine, "all", (n) =>
            `all ${n} state${n === 1 ? "" : "s"} it began with`)
        : block(fresh, "arrived", (n) =>
            `the ${n} state${n === 1 ? "" : "s"} that arrived`);
      const stayed = before === null ? "" : block(
        mine.filter((id) => before.includes(id)), "kept", (n) =>
          // The verb agrees as well as the noun: "the 1 state that were
          // already in it" is the kind of sentence that makes a reader
          // wonder what else was written without being read.
          `the ${n} state${n === 1 ? " that was" : "s that were"} already
           in it and stayed`);
      const went = block(lost, "left", (n) =>
        `the ${n} state${n === 1 ? "" : "s"} that left it`);
      const described = (task.summary || {}).title || Object.keys(said).length
        ? `<div class="sb-across-said">
             <div class="sb-across-title">${escapeHtml(
               String((task.summary || {}).title || "(no title yet)"))}</div>
             ${PARTS.map(([name, heading]) => {
               const now = String(said[name] || "").trim();
               const was = String(saidBefore[name] || "").trim();
               if (!now) return "";
               const changed = moved.has(name) || (was && was !== now);
               const first = !was;
               return `<div class="sb-across-part${
                 changed ? " sb-across-changed" : ""}">
                 <span class="event-label">${escapeHtml(heading)}${
                   first && index > 0 ? " - written for the first time"
                     : changed ? " - changed this round" : " - unchanged"
                 }</span>
                 <p>${escapeHtml(now)}</p></div>`;
             }).join("")}
           </div>`
        : `<span class="muted">not summarised in this round</span>`;
      before = mine;
      if (Object.keys(said).length) saidBefore = said;
      return `<tr><td class="sb-across-when">${
        escapeHtml(one.name.split(":")[0])}</td>
        <td class="sb-across-states">${states}${listed}${stayed}${went}</td>
        <td>${described}</td></tr>`;
    }).join("");

    return `<details class="sb-across" data-sb-open="across-${
        escapeHtml(String(taskId))}">
      <summary><span class="sb-across-title">${escapeHtml(String(
          stateBeatFirstTitle(rounds, taskId) || "never summarised"))}</span>
        <code class="muted">${escapeHtml(String(taskId))}</code>
        <span class="muted">shown as ${
          escapeHtml(shownAs(taskId))} when it first appeared</span>
      </summary>
      <table class="sb-compare-table sb-across-table">
        <thead><tr><th>round</th><th>states</th>
          <th>how it was described</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </details>`;
  }).join("");
}

/* The first title this task was ever given, for the row that names it. */
function stateBeatFirstTitle(rounds, taskId) {
  for (const one of rounds) {
    const found = ((one.report || {}).layers || [])
      .find((task) => task.task_id === taskId);
    const title = found && (found.summary || {}).title;
    if (title) return title;
  }
  return "";
}

function stateBeatCompare(rounds, out) {
  if (rounds.length < 2) return "";
  const identity = out.identity || {};
  const every = [];
  rounds.forEach((one) => {
    ((one.report || {}).layers || []).forEach((task) => {
      if (!every.includes(task.task_id)) every.push(task.task_id);
    });
  });
  const sizeIn = (one, taskId) => {
    const found = ((one.report || {}).layers || [])
      .find((task) => task.task_id === taskId);
    return found ? Number(found.size || 0) : null;
  };
  const shownAs = (taskId) => {
    for (const one of rounds) {
      const found = ((one.report || {}).layers || [])
        .find((task) => task.task_id === taskId);
      if (found) return found.id;
    }
    return taskId;
  };
  return `<details class="sb-compare" data-sb-open="compare">
    <summary><strong>The rounds compared</strong>
      <span class="muted">${every.length} tasks in all, ${
        Number(identity.kept_their_id_throughout || 0)} of ${
        Number(identity.tasks_after_round_one || 0)} kept their id from the
        first round to the last</span></summary>

    <h4>Every task: how many states it held at the end of each round</h4>
    <p class="muted">The number is <strong>everything the task held</strong>
      at that point, not what it gained - what it gained is in brackets
      after it. A task is named by what it was first called, because the
      <code>task_3</code> style of name is a POSITION and positions are
      filled by different work in different rounds: two rows both reading
      <code>task_3</code> was two tasks that each sat third at some point,
      which is exactly the confusion the stable ids exist to end.</p>
    <table class="sb-compare-table">
      <thead><tr><th>task</th>${rounds.map((one) =>
        `<th>${escapeHtml(one.name.split(":")[0])}</th>`).join("")}</tr></thead>
      <tbody>${every.map((taskId) => {
        let before = null;
        return `<tr>
        <td class="sb-compare-name">
          <span class="sb-across-title">${escapeHtml(String(
            stateBeatFirstTitle(rounds, taskId) || "never summarised"))}</span>
          <code class="muted">${escapeHtml(String(taskId))}</code>
        </td>
        ${rounds.map((one) => {
          const size = sizeIn(one, taskId);
          if (size === null) {
            // Not "0": a task that did not exist held no states and a
            // task that lost all of them is a different event.
            return `<td><span class="muted">${before === null
              ? "not yet" : "gone"}</span></td>`;
          }
          const moved = before === null ? null : size - before;
          before = size;
          return `<td>${size}${moved === null
            ? `<span class="muted"> first seen</span>`
            : moved === 0
              ? `<span class="muted"> (no change)</span>`
              : `<span class="${moved > 0 ? "sb-grew" : "sb-shrank"}"> (${
                  moved > 0 ? "+" : ""}${moved})</span>`}</td>`;
        }).join("")}
      </tr>`; }).join("")}</tbody>
    </table>

    <h4>Every task, round by round</h4>
    <p class="muted">What appending actually did to each one: which states
      arrived, and whether the words describing it changed. A task that did
      not exist in a round says so rather than leaving a blank, because a
      blank reads as "nothing changed".</p>
    ${stateBeatTaskRounds(rounds, every, shownAs)}

    <h4>Every round, and what it cost</h4>
    <table class="sb-compare-table">
      <thead><tr><th>round</th><th>states read</th><th>new</th>
        <th>pairs scored</th><th>rebuilt</th><th>model calls</th>
        <th>took</th></tr></thead>
      <tbody>${rounds.map((one) => {
        const report = one.report || {};
        const kept = report.continuity || {};
        return `<tr>
          <td>${escapeHtml(one.name.split(":")[0])}</td>
          <td>${Number(report.states_considered || 0)}</td>
          <td>${Number(kept.arrivals || 0)}</td>
          <td>${Number((report.similarity || {}).pairs_scored || 0)}</td>
          <td>${kept.rebuilt ? "yes" : "no"}</td>
          <td>${(report.summaries_written || []).length}</td>
          <td>${((Number(report.duration_ms) || 0) / 1000).toFixed(1)}s</td>
        </tr>`;
      }).join("")}</tbody>
    </table>

    <h4>Every overview, one under the other</h4>
    ${rounds.map((one) => `<div class="sb-compare-one">
      <p class="event-label">${escapeHtml(one.name)} -
        ${Number(((one.report || {}).overview || {}).states_in_all || 0)} states
        in the folder, ${
        Number(((one.report || {}).overview || {}).this_round || 0)} worked on
        by this round</p>
      ${stateBeatOverview(one.report || {})}
    </div>`).join("")}
  </details>`;
}

async function clearSandbox() {
  try {
    // Whatever is running in the sandbox is being given up on, so the
    // page stops following it and stops waiting for its answer BEFORE
    // the deleting is asked for - the round is already on its way out by
    // the time the files go.
    const showing = (stateBeat.report || {}).where || {};
    const ours = stateBeat.rehearsal || showing.scope === "sandbox"
                 || stateBeat.running;
    if (ours) {
      stateBeat.round += 1;
      stateBeat.running = false;
      stateBeat.rehearsal = null;
      stateBeat.report = null;
      renderStateBeat();
    }
    const gone = await api.post("/api/state_heartbeat/sandbox/clear", {});
    // Named rather than counted. "562 files and 11 rows" is two numbers
    // nobody can check; a task is one row and one write-up over many
    // state files, so the two were never going to match.
    const named = (group) => Object.entries(group || {})
      .filter(([, n]) => Number(n) > 0)
      .map(([name, n]) => `${n} ${name}`).join(", ");
    const files = named(gone.files) || "no files";
    const rows = named(gone.rows) || "no rows";
    toast(`Emptied: ${files}; and ${rows}`, "ok");
    await loadSandbox();
  } catch (err) {
    toast(err.message, "error");
  }
}

function wireStateBeat() {
  $("#dbg-states-run")?.addEventListener("click", () => runStateBeat("live"));
  $("#dbg-sb-run")?.addEventListener("click", async () => {
    await runStateBeat("sandbox");
    await loadSandbox();
  });
  $("#dbg-sb-make")?.addEventListener("click", makeUpStates);
  $("#dbg-sb-rehearse")?.addEventListener("click", rehearseAppending);
  $("#dbg-sb-clear")?.addEventListener("click", clearSandbox);
  loadSandbox();
  // BOTH PLACES THE PICTURE IS DRAWN, from one handler. The overview
  // shows the same tree as the debugger, and a click that worked in one
  // and did nothing in the other would read as the overview's copy being
  // a picture of a picture. Listed rather than bound to `document` so a
  // stray click elsewhere on the page still reaches whatever owns it.
  ["#dbg-statebeat-body", "#ov-tasks"].forEach((which) => {
    $(which)?.addEventListener("click", sbClicked);
    // AND THE BROWSER DOES NOT SCROLL THE THING IT FOCUSES. Every circle
    // carries `tabindex` so it can be reached from the keyboard, and a
    // click on a focusable element focuses it - at which point the
    // browser scrolls it into view. The discs sit at the MOST RECENT end
    // of their lines, which on a wide calendar is far off to the right,
    // so clicking a task threw the picture to the right edge.
    //
    // The focus is still given, with the scrolling refused: a reader
    // using the keyboard keeps what `tabindex` is for, and a reader using
    // the mouse keeps their place.
    $(which)?.addEventListener("mousedown", (event) => {
      const node = event.target.closest(
        "[data-sb-task], [data-sb-piece]");
      if (!node) return;
      event.preventDefault();
      try {
        node.focus({preventScroll: true});
      } catch (_err) {
        /* an older engine without the option: no focus is better than a
           picture that jumps. */
      }
    });
  });


  function sbClicked(event) {
    // The copy button sits inside a `summary`, so a plain click would
    // toggle the block as well as copy it. Taken first, because the
    // handlers below look for other things and would not stop it.
    // A drag that moved the picture ends in a click on whatever leaf it
    // started over. Opening that state would make the tree unmovable in
    // practice: every attempt to look at another part of it would open
    // something.
    if (stateBeat.dragged && Date.now() - stateBeat.dragged < 250) return;
    const copier = event.target.closest("[data-sb-copy]");
    if (copier) {
      event.preventDefault();
      event.stopPropagation();
      sbCopyThePrompt(copier);
      return;
    }
    if (event.target.closest("[data-sb-next]")) return;
    const zoomTree = event.target.closest("[data-sb-treezoom]");
    if (zoomTree) {
      event.preventDefault();
      event.stopPropagation();
      const what = zoomTree.dataset.sbTreezoom;
      if (what === "reset") { stateBeat.treeZoom = 1; renderStateBeat(); }
      else sbZoomTreeBy(what === "in" ? 1.25 : 1 / 1.25);
      return;
    }
    const hiddenAt = event.target.closest("[data-sb-hidden]");
    if (hiddenAt) {
      event.preventDefault();
      event.stopPropagation();
      stateBeat.showHidden = hiddenAt.dataset.sbHidden === "on";
      const again = stateBeat.whole || stateBeat.report;
      if (again) drawWhatIsRunning(again);
      return;
    }
    const findAt = event.target.closest("[data-sb-findit]");
    if (findAt) {
      event.preventDefault();
      event.stopPropagation();
      const host = findAt.closest("#ov-tasks, #dbg-statebeat-body");
      const row = host && host.querySelector(
        `[data-sb-task="${findAt.dataset.sbFindit}"]`);
      const frame = host && host.querySelector(".sb-tree-frame");
      const disc = row && row.querySelector(".sb-tt-disc");
      if (frame && disc) {
        // Centred, not merely brought inside the edge: a thing that
        // arrives hard against the frame's border still reads as "not
        // quite there".
        const where = Number(disc.getAttribute("cx")) * sbTreeZoom();
        frame.scrollLeft = Math.max(0, where - frame.clientWidth / 2);
        frame.dataset.sbPlaced = "1";
        if (row.dataset.sbAt) {
          frame.scrollTop = Math.max(
            0, Number(row.dataset.sbAt) * sbTreeZoom()
               - frame.clientHeight / 2);
        }
      }
      // The frame goes with what is selected, wherever it was found from.
      sbMarkSelected();
      return;
    }
    const recentAt = event.target.closest("[data-sb-recent]");
    if (recentAt) {
      event.preventDefault();
      event.stopPropagation();
      stateBeat.recentDays = Number(recentAt.dataset.sbRecent);
      sbRedrawPictures();
      return;
    }
    const sortAt = event.target.closest("[data-sb-sort]");
    if (sortAt) {
      event.preventDefault();
      event.stopPropagation();
      stateBeat.sortBy = sortAt.dataset.sbSort;
      sbRedrawPictures();
      return;
    }
    if (event.target.closest("[data-sb-task-shut]")) {
      event.stopPropagation();
      stateBeat.openTask = null;
      // The set as well, or the picture reopens them on the next draw.
      stateBeat.openTasks = new Set();
      stateBeat.openPieces = new Set();
      stateBeat.cardShows = {kind: "task"};
      sbRedrawPictures();
      return;
    }
    const projectAt = event.target.closest("[data-sb-project]");
    if (projectAt) {
      event.stopPropagation();
      const which = projectAt.dataset.sbProject;
      if (!(stateBeat.openProjects instanceof Set)) {
        stateBeat.openProjects = new Set();
      }
      stateBeat.openProjects = new Set();
      stateBeat.cardShows = {kind: "project", which: which};
      const owner = projectAt.closest("#ov-tasks, #dbg-statebeat-body");
      sbRedrawPictures();
      // ITS CARD, WRITTEN - AND THE VIEW LEFT WHERE IT IS. A redraw that
      // only writes names into the drawing in place leaves the card as it
      // was, so the click looked like it did nothing. The page is not
      // scrolled to the card: the reader clicked something in the picture
      // and is looking at the picture, and its next steps open there.
      const card = owner && owner.isConnected
        ? owner.querySelector("[data-sb-card]") : null;
      if (card) {
        card.innerHTML = sbProjectCard(owner.sbReport || stateBeat.report
                                       || {}, which);
      }
      return;
    }
    const pieceAt = event.target.closest("[data-sb-piece]");
    if (pieceAt) {
      event.stopPropagation();
      const which = pieceAt.dataset.sbPiece;
      const svg = pieceAt.closest(".sb-whole-graph");
      // A SET, not one id: three layers deep means a piece can be open
      // inside an open piece, and remembering only the last one clicked
      // would shut its parent and take the row out from under the
      // cursor.
      if (!(stateBeat.openPieces instanceof Set)) {
        stateBeat.openPieces = new Set();
      }
      const was = stateBeat.openPieces.has(which);
      if (was) {
        // Shutting one shuts what was open inside it, which is what the
        // picture does anyway - a branch of a branch that is gone cannot
        // be shown hanging off nothing.
        stateBeat.openPieces.forEach((id) => {
          if (String(id).startsWith(`${which}.`)) {
            stateBeat.openPieces.delete(id);
          }
        });
        stateBeat.openPieces.delete(which);
      } else {
        stateBeat.openPieces.add(which);
      }
      const now = was ? "" : which;
      // Remembered, so the next rebuild shows this piece and not its
      // parent. Closing the piece hands the card back to the task.
      stateBeat.cardShows = was ? {kind: "task"} : {kind: "piece", which};
      // The panel reads whatever was last clicked, and a piece is a thing
      // with a status of its own.
      const card = sbCardNear(event.target);
      if (card) {
        const owner = pieceAt.closest("#ov-tasks, #dbg-statebeat-body");
        card.innerHTML = sbPieceCard((owner && owner.sbReport)
                                     || stateBeat.report || {},
                                     stateBeat.openTask, which);
      }
      // THE WHOLE SET OF OPEN TASKS, AND THIS PICTURE'S OWN REPORT.
      //
      // This passed `svg.dataset.sbOpenTask` - one id, left over from
      // when only one task could be open - so opening a sub-task redrew
      // the branches for whatever that stale value held: usually nothing,
      // which collapsed the task and made the click look ignored. It is
      // the exact case of "a top task expands, then a second-layer click
      // does nothing".
      if (svg) {
        const owner = pieceAt.closest("#ov-tasks, #dbg-statebeat-body");
        sbUnfold(svg, (owner && owner.sbReport) || stateBeat.report || {},
                 stateBeat.openTasks instanceof Set
                   ? stateBeat.openTasks : stateBeat.openTask, true);
      }
      return;
    }
    const taskAt = event.target.closest("[data-sb-task]");
    if (taskAt) {
      event.stopPropagation();
      // A TASK IS READ, NOT OPENED. Only the top layer is described, so
      // there is nothing under a task to unfold: clicking it makes it the
      // one being read - framed, and its card shown below.
      const key = taskAt.dataset.sbTask;
      stateBeat.openTasks = new Set();
      stateBeat.openPieces = new Set();
      stateBeat.openTask = key;
      stateBeat.cardShows = {kind: "task"};
      const owner = taskAt.closest("#ov-tasks, #dbg-statebeat-body");
      const showing = (owner && owner.sbReport) || stateBeat.report || {};
      const card = sbCardNear(taskAt);
      // The card reads out what was clicked, and the view stays exactly
      // where it is - as for a project.
      if (card) card.innerHTML = sbTaskCard(showing, key);
      sbMarkSelected();
      return;
    }
    const circle = event.target.closest("[data-sb-node]");
    if (!circle) return;
    event.stopPropagation();
    openStateBeatNode(circle);
  }
  // A node is reachable from the keyboard, so it answers to the keyboard.
  $("#dbg-statebeat-body")?.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const circle = event.target.closest("[data-sb-node]");
    if (!circle) return;
    event.preventDefault();
    openStateBeatNode(circle);
  });
  // A KEYED SECTION REMEMBERED THE MOMENT IT IS OPENED OR SHUT, wherever
  // the card is - the Summary tab's redraw takes no note of its own.
  document.addEventListener("toggle", (event) => {
    const one = event.target;
    if (!one || !one.matches || !one.matches("details[data-sb-open]")
        || !one.closest("#ov-tasks, #dbg-statebeat-body")) return;
    const key = one.dataset.sbOpen;
    if (one.open) {
      stateBeat.opened.add(key);
      stateBeat.opened.delete(`shut:${key}`);
    } else {
      stateBeat.opened.delete(key);
      stateBeat.opened.add(`shut:${key}`);
    }
  }, true);
  $("#dbg-statebeat-body")?.addEventListener("toggle", (event) => {
    const group = event.target.closest("[data-sb-group]");
    if (!group) return;
    const key = group.getAttribute("data-sb-group");
    if (group.open) stateBeat.opened.add(key);
    else stateBeat.opened.delete(key);
  }, true);
}

async function runOneHeartbeat() {
  if (dbgBeat.running) return;
  dbgBeat.running = true;
  dbgBeat.report = null;
  renderHeartbeatRun();
  try {
    const finished = await api.post("/api/heartbeat/run", {});
    dbgBeat.report = finished;
    // Opened by default: a page that runs something and then shows four
    // closed rows has not shown anything.
    (finished.steps || []).forEach((step) =>
      dbgBeat.opened.add(String(step.id || step.step)));
  } catch (err) {
    dbgBeat.report = { skipped: err.message };
  } finally {
    dbgBeat.running = false;
    renderHeartbeatRun();
  }
}

/* The run so far, asked for once.

   This polled twice a second while a run was going, so that the steps
   appeared as they were answered. A run takes about a minute, and for that
   minute the rest of the interface was sharing its connection with a
   half-second request carrying every event the step had read - which is
   what made watching a heartbeat and using the Overview two different
   sittings.

   So it is asked for when somebody asks. The run is still watchable, in
   that a half-finished one comes back with the steps it has answered; what
   is gone is the page deciding for itself when to want it. */
async function refreshHeartbeat() {
  try {
    const state = await api.get("/api/heartbeat/progress");
    if (!state || !(state.steps || []).length) return;
    dbgBeat.report = state;
    dbgBeat.running = Boolean(state.running);
    (state.steps || []).forEach((step) =>
      dbgBeat.opened.add(String(step.id || step.step)));
    renderHeartbeatRun();
  } catch (err) {
    toast(err.message, "error");
  }
}

function wireHeartbeatRun() {
  $("#dbg-beat-run")?.addEventListener("click", runOneHeartbeat);
  $("#dbg-beat-refresh")?.addEventListener("click", refreshHeartbeat);
  $("#dbg-beat-body")?.addEventListener("click", (event) => {
    const state = event.target.closest("[data-beat-state]");
    if (state) {
      event.stopPropagation();
      openBeatState(state);
      return;
    }
    const opener = event.target.closest(".trail-open");
    if (!opener) return;
    event.stopPropagation();
    openTrailRecord(opener);
  });
  // The last run, after a reload. It is kept whole on the agent, and a page
  // that empties itself when it is reloaded has thrown away the thing the
  // reader opened it to look at. Once, here - not on a timer.
  api.get("/api/heartbeat/progress").then((state) => {
    if (!state || dbgBeat.report || dbgBeat.running) return;
    if (!(state.steps || []).length) return;
    dbgBeat.report = state;
    dbgBeat.running = Boolean(state.running);
    renderHeartbeatRun();
  }).catch(() => {});
  // The context of one step runs to tens of thousands of characters. It is
  // shown in a window that scrolls, and opens out in place for anyone who
  // would rather read it than scroll it.
  $("#dbg-beat-body")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-expand]");
    if (!button) return;
    const text = button.closest(".beat-sub")?.nextElementSibling;
    if (!text) return;
    const opened = text.classList.toggle("beat-context-all");
    button.textContent = opened ? "collapse" : "expand";
  });
  const host = $("#dbg-beat-body");
  if (host) {
    host.addEventListener("toggle", (event) => {
      const row = event.target.closest("[data-beat]");
      if (!row) return;
      const key = row.dataset.beat;
      if (row.open) dbgBeat.opened.add(key);
      else dbgBeat.opened.delete(key);
    }, true);
  }
}

/* How many chips a square of a month grid holds before it stops being one. */
const DBG_STATES_PER_CELL = 4;

function dbgStateMonthBounds(anchor) {
  const from = new Date(anchor.getFullYear(), anchor.getMonth(), 1);
  const to = new Date(anchor.getFullYear(), anchor.getMonth() + 1, 0);
  return { from, to };
}

async function loadDebuggerStates() {
  const host = $("#dbg-states-body");
  if (!host) return;
  const { from, to } = dbgStateMonthBounds(dbgStates.anchor);
  try {
    const days = Math.ceil((to - from) / DAY_MS) + 2;
    const data = await api.get(
      `/api/debugger/states?days=${days}&around=${encodeURIComponent(from.toISOString())}`);
    stateBeat.states = data.states || [];
  } catch (err) {
    // A build made without the Debugger does not serve this, and neither does
    // one whose collection is switched off. Saying so beats an empty grid.
    host.innerHTML = `<p class="muted">States are not available in this build.</p>`;
    return;
  }
  renderDebuggerStates();
}

function stateBeatOn(date) {
  const dayStart = startOfDay(date);
  const dayEnd = new Date(dayStart.getTime() + DAY_MS - 1);
  return stateBeat.states.filter((state) => {
    const from = state.starts_at ? new Date(state.starts_at) : null;
    const to = state.ends_at ? new Date(state.ends_at) : null;
    return (!from || from <= dayEnd) && (!to || to >= dayStart);
  }).sort((a, b) => (b.span_hours || 0) - (a.span_hours || 0));
}

function renderDebuggerStates() {
  const host = $("#dbg-states-body");
  if (!host) return;
  const { from, to } = dbgStateMonthBounds(dbgStates.anchor);
  $("#dbg-states-range").textContent = dbgStates.anchor.toLocaleDateString(
    undefined, { month: "long", year: "numeric" });

  if (!stateBeat.states.length) {
    host.innerHTML = `<p class="muted">No states in this month. The agent
      heartbeat writes them; nothing has been inferred yet.</p>`;
    return;
  }

  // Monday-first, like the calendar, so the two read the same way.
  const first = new Date(from);
  first.setDate(first.getDate() - ((first.getDay() + 6) % 7));
  const cells = [];
  for (let day = new Date(first); day <= to || cells.length % 7; day.setDate(day.getDate() + 1)) {
    const date = new Date(day);
    const outside = date.getMonth() !== dbgStates.anchor.getMonth();
    const states = stateBeatOn(date);
    const key = String(startOfDay(date).getTime());
    // A cell is one square of a month grid, so it can hold about four chips
    // before the grid stops being a month. Expanding is how the rest are
    // reached: a day the agent inferred nine things about is exactly the day
    // worth looking at, and "+5 more" that cannot be opened is a dead end.
    const open = stateBeat.expanded.has(key);
    const shown = open ? states : states.slice(0, DBG_STATES_PER_CELL);
    const hidden = states.length - shown.length;
    cells.push(`
      <div class="dbg-state-cell${outside ? " outside" : ""}${open ? " expanded" : ""}"
        data-day="${key}">
        <div class="dbg-state-day">${date.getDate()}</div>
        ${shown.map(stateChip).join("")}
        ${hidden > 0
          ? `<button type="button" class="dbg-state-more" data-expand="${key}">
               +${hidden} more</button>`
          : ""}
        ${open && states.length > DBG_STATES_PER_CELL
          ? `<button type="button" class="dbg-state-more" data-expand="${key}">
               show fewer</button>`
          : ""}
      </div>`);
    if (cells.length > 42) break;
  }

  const byTask = stateBeat.states.filter((s) => s.task_id).length;
  host.innerHTML = `
    <div class="dbg-state-grid">${cells.join("")}</div>
    <div class="muted">${stateBeat.states.length} states this month ·
      ${byTask} accompany a scheduled task ·
      ${stateBeat.states.length - byTask} are things the heartbeat noticed.
      A state is shown, never run.</div>`;
}

function wireDebuggerStates() {
  const prev = $("#dbg-states-prev");
  const next = $("#dbg-states-next");
  if (!prev || !next) return;
  prev.addEventListener("click", () => {
    dbgStates.anchor = new Date(dbgStates.anchor.getFullYear(),
                                dbgStates.anchor.getMonth() - 1, 1);
    loadDebuggerStates();
  });
  next.addEventListener("click", () => {
    dbgStates.anchor = new Date(dbgStates.anchor.getFullYear(),
                                dbgStates.anchor.getMonth() + 1, 1);
    loadDebuggerStates();
  });
  const collapse = $("#dbg-states-collapse");
  if (collapse) {
    collapse.addEventListener("click", () => {
      stateBeat.open = !stateBeat.open;
      $("#dbg-states-body").hidden = !stateBeat.open;
      collapse.textContent = stateBeat.open ? "⌴" : "⌵";
    });
  }
  $("#dbg-states-body").addEventListener("click", (event) => {
    // Opening a day out, and closing it again. Checked before the chip,
    // because the button sits among them.
    const toggle = event.target.closest("[data-expand]");
    if (toggle) {
      const key = toggle.dataset.expand;
      if (stateBeat.expanded.has(key)) stateBeat.expanded.delete(key);
      else stateBeat.expanded.add(key);
      renderDebuggerStates();
      return;
    }
    // The detail opens beside the chip, the same way it did on the calendar.
    const chip = event.target.closest("[data-state]");
    if (!chip) return;
    const state = stateBeat.states.find((s) => s.id === chip.dataset.state);
    if (state) openDebuggerState(state, chip);
  });

  // The toolbar already says "expand all" and "collapse all" for the panels;
  // a states grid that ignored them would be the one thing on the page those
  // buttons did not reach.
  const expandAll = $("#dbg-expand-all");
  if (expandAll) {
    expandAll.addEventListener("click", () => {
      stateBeat.states.forEach((state) => {
        if (!state.starts_at) return;
        stateBeat.expanded.add(String(startOfDay(new Date(state.starts_at)).getTime()));
      });
      renderDebuggerStates();
    });
  }
  const collapseAll = $("#dbg-collapse-all");
  if (collapseAll) {
    collapseAll.addEventListener("click", () => {
      stateBeat.expanded.clear();
      renderDebuggerStates();
    });
  }
}

/* Whether this build carries the Debugger at all (section 14.33, as amended).
   A build made with --no-debugger serves none of its routes, so the tab is
   removed rather than left to answer 404 at every click. */
async function applyDebuggerAvailability() {
  let available = true;
  try {
    available = (await api.get("/api/status")).debugger_built_in !== false;
  } catch (err) {
    return;
  }
  if (available) return;
  // What the computer was used for is the Debugger's (section 8, as amended
  // 2026-10-16): with no Debugger it is not shown anywhere.
  $("#dbg-usage")?.remove();
  document.querySelector('[data-tab="debugger"]')?.remove();
  document.querySelector("#debugger")?.remove();
  // The Experience debugger's routes are the Debugger's too.
  document.querySelector('[data-tab="xdebug"]')?.remove();
  document.querySelector("#xdebug")?.remove();
  // The heartbeat page is its own tab now and the same kind of thing: a
  // build without the Debugger should not ship one door into it still open.
  document.querySelector('[data-tab="heartbeat"]')?.remove();
  document.querySelector("#heartbeat")?.remove();
  // And the chat debugger, whose routes are the Debugger's too.
  document.querySelector('[data-tab="chatdebug"]')?.remove();
  document.querySelector("#chatdebug")?.remove();
  document.querySelector('[data-tab="listenerdebug"]')?.remove();
  document.querySelector("#listenerdebug")?.remove();
  // EVERY DEBUGGER: an installed build is for the user, not for whoever
  // develops the agent - run from Python, they are all there.
  ["naturedebug", "connectiondebug", "readingdebug", "languagedebug", "resourcedebug", "lessons"].forEach((name) => {
    document.querySelector(`[data-tab="${name}"]`)?.remove();
    document.querySelector(`#${name}`)?.remove();
  });
  // The state heartbeat's debugger: its tab goes; its section stays, hidden,
  // for the Overview draws the same picture with the same code.
  document.querySelector('[data-tab="statebeat"]')?.remove();
}


/* ------------------------------------------------------- resource debugger

   WHAT THE APPLICATION COSTS THE COMPUTER, as it goes (debugger/
   resources.py): its own process and every one it started - by what each is
   for - every two seconds while this tab is open, and nothing while it is
   not. Three charts of the last fifteen minutes, one measure each and one
   axis each: processors (a share of the whole computer), memory, graphics.
   Each is the application's parts STACKED - the top edge is all of it - in
   the token chart's validated colours, always the same colour for the same
   part, named in a legend above; the whole computer's own use, other
   programs too, is the dashed line in ink on the processors' chart, so what
   is ours reads against it. Hovering shows a crosshair and every part's
   value then; the process table beneath is the same numbers as a table.
   Then the folders on disk, and what an earlier run left going. */
const RD = { timer: null, data: null, open: new Set(), diskAt: "", endAsk: false,
             hover: {} };
const RD_KINDS = ["app", "embedding", "work", "debugger", "models", "other"];

function rdColour(kind) {
  const set = sbIsDark() ? TOKEN_COLOURS.dark : TOKEN_COLOURS.light;
  const at = RD_KINDS.indexOf(kind);
  return set[at < 0 ? RD_KINDS.length - 1 : at];
}

function rdLabel(kind) {
  const found = ((RD.data || {}).kinds || []).find((one) => one.id === kind);
  return found ? found.label : kind;
}

function rdPercent(value) {
  const n = Number(value || 0);
  return `${n < 10 ? n.toFixed(1) : n.toFixed(0)}%`;
}

function rdClock(seconds) {
  return new Date(seconds * 1000).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit",
    second: "2-digit" });
}

/* Asked again every two seconds while the tab is open and the page is in
   view; the server stops sampling once nobody asks. */
function rdTick() {
  clearTimeout(RD.timer);
  if (activeTab !== "resourcedebug") return;
  RD.timer = setTimeout(rdTick, 2000);
  if (document.hidden) return;
  api.get("/api/debugger/resources").then((said) => {
    RD.data = said;
    rdDraw();
  }).catch((err) => {
    $("#rd-now").innerHTML = `<p class="muted">${escapeHtml(err.message)}</p>`;
  });
}

function rdDraw() {
  const data = RD.data || {};
  const latest = data.latest || {};
  const machine = latest.machine || {};
  const totals = latest.totals || {};
  const sum = (field) => RD_KINDS.reduce((all, kind) => all + Number((totals[kind] || {})[field] || 0), 0);
  const disk = (data.disk || {}).places || [];
  const onDisk = disk.reduce((all, place) => all + Number(place.bytes || 0), 0);
  if (!latest.t) {
    $("#rd-now").innerHTML = `<p class="muted">Taking the first look…</p>`;
  } else {
    const gpu = data.gpu || {};
    $("#rd-now").innerHTML = `
      <div class="rd-figure"><span class="rd-figure-value">${rdPercent(sum("cpu"))}</span>
        <span class="muted">of the processors (${Number(machine.cores || 0)} cores) -
        the whole computer is at ${rdPercent(machine.cpu)}</span></div>
      <div class="rd-figure"><span class="rd-figure-value">${lpBytes(sum("memory"))}</span>
        <span class="muted">of memory - ${lpBytes(machine.memory_used)} of
        ${lpBytes(machine.memory_total)} in use on the computer</span></div>
      <div class="rd-figure"><span class="rd-figure-value">${gpu.measured
        ? rdPercent(sum("gpu")) : "-"}</span>
        <span class="muted">${gpu.measured ? `of the graphics processor${
          machine.gpu == null ? "" : ` - the computer's at ${rdPercent(machine.gpu)}`}${
          sum("gpu_memory") ? `, ${lpBytes(sum("gpu_memory"))} of its memory` : ""}`
          : escapeHtml(gpu.how || "graphics not measured")}</span></div>
      <div class="rd-figure"><span class="rd-figure-value">${(data.disk || {}).measured_at
        ? lpBytes(onDisk) : "…"}</span>
        <span class="muted">on disk${(data.disk || {}).measuring ? " - being measured" : ""}</span></div>`;
  }
  rdLegend();
  rdChart("cpu", (point) => point.cpu, rdPercent, (point) => point.machine_cpu);
  rdChart("memory", (point) => point.memory, lpBytes);
  if ((data.gpu || {}).measured) {
    $("#rd-gpu-card").hidden = false;
    rdChart("gpu", (point) => point.gpu, rdPercent);
  } else {
    $("#rd-gpu-card").hidden = true;
  }
  rdProcesses(latest.processes || []);
  if ((data.disk || {}).measured_at !== RD.diskAt || (data.disk || {}).measuring !== RD.diskMeasuring) {
    RD.diskAt = (data.disk || {}).measured_at;
    RD.diskMeasuring = (data.disk || {}).measuring;
    rdDisk(data.disk || {});
  }
  rdLeftovers(data.leftovers || []);
}

function rdLegend() {
  const html = RD_KINDS.map((kind) => `<span class="rd-key"><span class="rd-swatch"
      style="background:${rdColour(kind)}"></span>${escapeHtml(rdLabel(kind))}</span>`).join("")
    + `<span class="rd-key"><span class="rd-swatch rd-swatch-line"></span>The whole computer
      (processors)</span>`;
  const at = $("#rd-legend");
  if (at._rdHtml !== html) {
    at.innerHTML = html;
    at._rdHtml = html;
  }
}

/* ONE CHART: the parts stacked over the minutes kept. `take` gives a
   sample's values by part; `whole`, if given, a line of the computer's own. */
function rdChart(name, take, say, whole) {
  const box = $(`#rd-${name}-chart`);
  const points = ((RD.data || {}).history || []);
  if (points.length < 2) {
    box.innerHTML = `<p class="muted">The line starts in a moment.</p>`;
    return;
  }
  const width = Math.max(320, box.clientWidth || 640);
  const height = 170;
  const pad = { left: 56, right: 12, top: 10, bottom: 22 };
  const t0 = points[0].t;
  const t1 = points[points.length - 1].t;
  const span = Math.max(1, t1 - t0);
  const x = (t) => pad.left + (t - t0) / span * (width - pad.left - pad.right);
  const stacks = points.map((point) => {
    let below = 0;
    const values = take(point) || {};
    return RD_KINDS.map((kind) => {
      const from = below;
      below += Math.max(0, Number(values[kind] || 0));
      return [from, below];
    });
  });
  let top = Math.max(...stacks.map((one) => one[one.length - 1][1]),
                     ...(whole ? points.map((p) => Number(whole(p) || 0)) : [0]));
  top = name === "memory" ? Math.max(top * 1.1, 2 ** 28) : Math.max(5, Math.ceil(top * 1.15 / 5) * 5);
  const y = (v) => height - pad.bottom - v / top * (height - pad.top - pad.bottom);
  const areas = RD_KINDS.map((kind, k) => {
    if (!stacks.some((one) => one[k][1] > one[k][0])) return "";
    const upper = points.map((p, i) => `${x(p.t).toFixed(1)},${y(stacks[i][k][1]).toFixed(1)}`);
    const lower = points.map((p, i) => `${x(p.t).toFixed(1)},${y(stacks[i][k][0]).toFixed(1)}`).reverse();
    return `<polygon points="${upper.concat(lower).join(" ")}" fill="${rdColour(kind)}"
      fill-opacity="0.85" stroke="var(--panel)" stroke-width="1"/>`;
  }).join("");
  const line = whole ? `<polyline points="${points.map((p) => `${x(p.t).toFixed(1)},${
    y(Number(whole(p) || 0)).toFixed(1)}`).join(" ")}" fill="none" stroke="var(--ink)"
    stroke-width="2" stroke-dasharray="5 4" stroke-linejoin="round"/>` : "";
  const ticks = [0, top / 2, top].map((v) => `<line x1="${pad.left}" x2="${width - pad.right}"
      y1="${y(v)}" y2="${y(v)}" stroke="var(--line)" stroke-width="1"/>
    <text x="${pad.left - 6}" y="${y(v) + 4}" text-anchor="end" class="rd-axis">${escapeHtml(say(v))}</text>`).join("");
  const times = `<text x="${pad.left}" y="${height - 6}" class="rd-axis">${rdClock(t0)}</text>
    <text x="${width - pad.right}" y="${height - 6}" text-anchor="end" class="rd-axis">${rdClock(t1)}</text>`;
  const hover = RD.hover[name];
  let cross = "";
  if (hover != null && points[hover]) {
    const hx = x(points[hover].t);
    cross = `<line x1="${hx}" x2="${hx}" y1="${pad.top}" y2="${height - pad.bottom}"
      stroke="var(--muted)" stroke-width="1"/>`;
  }
  box.innerHTML = `<svg class="rd-svg" width="${width}" height="${height}" role="img"
      aria-label="${escapeHtml(name)} over the last minutes, by what it is for - the table below has the numbers"
      data-rd-chart="${escapeHtml(name)}">${ticks}${areas}${line}${times}${cross}
      <rect x="${pad.left}" y="${pad.top}" width="${width - pad.left - pad.right}"
        height="${height - pad.top - pad.bottom}" fill="transparent"/></svg>
    <div class="rd-tip" hidden></div>`;
  const svg = box.querySelector("svg");
  const tip = box.querySelector(".rd-tip");
  const show = (index) => {
    const point = points[index];
    const values = take(point) || {};
    const rows = RD_KINDS.filter((kind) => Number(values[kind] || 0) > 0).map((kind) =>
      `<div class="rd-tip-row"><span class="rd-swatch" style="background:${rdColour(kind)}"></span>
        ${escapeHtml(rdLabel(kind))}<span class="rd-tip-value">${escapeHtml(say(values[kind]))}</span></div>`);
    const total = RD_KINDS.reduce((all, kind) => all + Number(values[kind] || 0), 0);
    tip.innerHTML = `<div class="muted">${rdClock(point.t)}</div>
      <div class="rd-tip-row"><strong>In all</strong><span class="rd-tip-value">${
        escapeHtml(say(total))}</span></div>${rows.join("")}${whole
        ? `<div class="rd-tip-row">The whole computer<span class="rd-tip-value">${
          escapeHtml(say(whole(point)))}</span></div>` : ""}`;
    tip.hidden = false;
    const left = x(point.t);
    tip.style.left = `${Math.min(Math.max(0, left + 12), width - 240)}px`;
    tip.style.top = "8px";
  };
  svg.addEventListener("mousemove", (event) => {
    const box2 = svg.getBoundingClientRect();
    const at = event.clientX - box2.left;
    let best = 0;
    points.forEach((p, i) => {
      if (Math.abs(x(p.t) - at) < Math.abs(x(points[best].t) - at)) best = i;
    });
    RD.hover[name] = best;
    let mark = svg.querySelector(".rd-cross");
    if (!mark) {
      mark = document.createElementNS("http://www.w3.org/2000/svg", "line");
      mark.setAttribute("class", "rd-cross");
      mark.setAttribute("stroke", "var(--muted)");
      svg.appendChild(mark);
    }
    const hx = x(points[best].t);
    mark.setAttribute("x1", hx); mark.setAttribute("x2", hx);
    mark.setAttribute("y1", pad.top); mark.setAttribute("y2", height - pad.bottom);
    show(best);
  });
  svg.addEventListener("mouseleave", () => {
    RD.hover[name] = null;
    tip.hidden = true;
    svg.querySelector(".rd-cross")?.remove();
  });
  if (hover != null && points[hover]) show(hover);
}

/* EVERY PROCESS, under what it is for - the largest first. */
function rdProcesses(rows) {
  const groups = new Map();
  rows.forEach((row) => {
    const key = `${row.kind}\u0000${row.owner}`;
    if (!groups.has(key)) groups.set(key, { kind: row.kind, owner: row.owner, rows: [] });
    groups.get(key).rows.push(row);
  });
  const measured = ((RD.data || {}).gpu || {}).measured;
  const ordered = [...groups.values()].map((group) => ({ ...group,
    cpu: group.rows.reduce((all, r) => all + Number(r.cpu || 0), 0),
    memory: group.rows.reduce((all, r) => all + Number(r.memory || 0), 0),
    gpu: group.rows.reduce((all, r) => all + Number(r.gpu || 0), 0),
    gpuMemory: group.rows.reduce((all, r) => all + Number(r.gpu_memory || 0), 0) }))
    .sort((a, b) => RD_KINDS.indexOf(a.kind) - RD_KINDS.indexOf(b.kind) || b.memory - a.memory);
  const cell = (value, say) => `<td class="rd-num">${value == null ? "-" : escapeHtml(say(value))}</td>`;
  const body = ordered.map((group) => `<tbody>
      <tr class="rd-group"><th colspan="3" scope="rowgroup"><span class="rd-swatch"
          style="background:${rdColour(group.kind)}"></span>${escapeHtml(group.owner)}
          <span class="muted">${group.owner === rdLabel(group.kind)
            ? `processes: ${group.rows.length}`
            : `${escapeHtml(rdLabel(group.kind))} - processes: ${group.rows.length}`}</span></th>
        ${cell(group.cpu, rdPercent)}${cell(group.memory, lpBytes)}${measured
          ? `${cell(group.gpu, rdPercent)}${cell(group.gpuMemory, lpBytes)}` : ""}</tr>
      ${group.rows.sort((a, b) => b.memory - a.memory).map((row) => `<tr>
        <td class="rd-name" title="${escapeHtml(row.command || "")}">${escapeHtml(row.name)}</td>
        <td class="rd-num">${Number(row.pid)}</td>
        <td class="muted">${escapeHtml(new Date(row.started).toLocaleTimeString())}</td>
        ${cell(row.cpu, rdPercent)}${cell(row.memory, lpBytes)}${measured
          ? `${cell(row.gpu, rdPercent)}${cell(row.gpu_memory, lpBytes)}` : ""}</tr>`).join("")}
    </tbody>`).join("");
  const html = `<table class="rd-table"><thead><tr><th scope="col">Process</th>
      <th scope="col" class="rd-num">PID</th><th scope="col">Started</th>
      <th scope="col" class="rd-num">Processors</th><th scope="col" class="rd-num">Memory</th>
      ${measured ? `<th scope="col" class="rd-num">Graphics</th>
      <th scope="col" class="rd-num">Graphics memory</th>` : ""}</tr></thead>${body}</table>`;
  $("#rd-processes").innerHTML = rows.length ? html : `<p class="muted">Taking the first look…</p>`;
}

/* THE FOLDERS: each with its size and files, its largest parts inside -
   opened ones stay open as it is measured again. */
function rdDisk(disk) {
  const places = disk.places || [];
  const largest = Math.max(1, ...places.map((place) => Number(place.bytes || 0)));
  $("#rd-measure").disabled = Boolean(disk.measuring);
  $("#rd-disk-when").textContent = disk.measuring ? "Being measured…"
    : disk.measured_at ? `Measured at ${new Date(disk.measured_at).toLocaleTimeString()}` : "";
  if (!places.length) {
    $("#rd-disk").innerHTML = `<p class="muted">${disk.measuring ? "Measuring its folders…"
      : "Nothing measured yet."}</p>`;
    return;
  }
  $("#rd-disk").innerHTML = places.map((place) => `<details class="rd-place"
      data-rd-place="${escapeHtml(place.path)}"${RD.open.has(place.path) ? " open" : ""}>
      <summary><span class="rd-place-name">${escapeHtml(place.label)}</span>
        <span class="rd-bar" aria-hidden="true"><span style="width:${
          (Number(place.bytes || 0) / largest * 100).toFixed(1)}%"></span></span>
        <span class="rd-num">${lpBytes(place.bytes)}</span>
        <span class="muted rd-num">${Number(place.files || 0).toLocaleString()} files</span></summary>
      <p class="muted"><code>${escapeHtml(place.path)}</code>${place.exists ? ""
        : " - not there any more"}${place.cut_short ? " - too many files to count in time; more than this" : ""}</p>
      ${(place.parts || []).length ? `<table class="rd-table rd-parts"><tbody>${place.parts.map((part) =>
        `<tr><td>${part.rest ? `<span class="muted">${escapeHtml(part.name)}</span>`
          : `<code>${escapeHtml(part.name)}</code>`}</td>
          <td class="rd-num">${lpBytes(part.bytes)}</td>
          <td class="rd-num muted">${Number(part.files || 0).toLocaleString()} files</td></tr>`).join("")}
        </tbody></table>` : ""}
    </details>`).join("");
}

/* WHAT AN EARLIER RUN LEFT GOING - normally nothing: the operating system
   ends every process the application started when it ends. */
function rdLeftovers(found) {
  const html = !found.length
    ? `<p class="muted">None - every process this application started belongs to it now.</p>`
    : `<p>Left going by an earlier run of the application: ${found.length}</p>
      <table class="rd-table"><tbody>${found.map((one) => `<tr>
        <td class="rd-name" title="${escapeHtml(one.command || "")}">${escapeHtml(one.name)}</td>
        <td class="rd-num">${Number(one.pid)}</td><td class="rd-num">${lpBytes(one.memory)}</td>
        <td class="muted">since ${escapeHtml(new Date(one.started).toLocaleString())}</td></tr>`).join("")}
      </tbody></table>
      ${RD.endAsk ? `<p class="xd-try-ask" role="alert">End them, with everything they
          started? What they were doing is lost.
          <button type="button" class="small danger" data-rd-end-yes="1">End them</button>
          <button type="button" class="small secondary" data-rd-end-no="1">Keep</button></p>`
        : `<button type="button" class="small secondary danger-text" data-rd-end="1">End them</button>`}`;
  const at = $("#rd-leftovers");
  if (at._rdHtml !== html) {
    at.innerHTML = html;
    at._rdHtml = html;
  }
}

document.addEventListener("click", async (event) => {
  const at = (selector) => event.target.closest && event.target.closest(selector);
  if (!at("#resourcedebug")) return;
  if (at("#rd-measure")) {
    $("#rd-measure").disabled = true;
    try { await api.post("/api/debugger/resources/disk", {}); } catch (err) { toast(err.message); }
    rdTick();
    return;
  }
  if (at("[data-rd-end]")) { RD.endAsk = true; rdLeftovers((RD.data || {}).leftovers || []); return; }
  if (at("[data-rd-end-no]")) { RD.endAsk = false; rdLeftovers((RD.data || {}).leftovers || []); return; }
  if (at("[data-rd-end-yes]")) {
    RD.endAsk = false;
    try {
      const said = await api.post("/api/debugger/resources/leftovers", {});
      toast(`Processes ended: ${Number(said.ended || 0)}`);
    } catch (err) {
      toast(err.message);
    }
    rdTick();
  }
});

document.addEventListener("toggle", (event) => {
  const place = event.target.closest && event.target.closest("[data-rd-place]");
  if (!place) return;
  if (place.open) RD.open.add(place.dataset.rdPlace);
  else RD.open.delete(place.dataset.rdPlace);
}, true);

/* ------------------------------------------------------- token usage

   Section 14.33, as amended: what the model time was spent on.

   The snapshot already carried tokens over time, as a timestamp and a number.
   That answers "how much" and never "on what", and on what is the question
   worth asking, because its answer is actionable: a heartbeat that outspends
   every conversation put together is a setting to change, and it looks exactly
   like a busy week until the lines are drawn apart.

   Cumulative rather than per-call. A scatter of individual calls says which
   single call was largest, which is rarely the thing anyone is looking for;
   a line that climbs says which kind of work is taking the budget, and the
   steepness says how fast.
*/
const dbgTokens = { calls: [], since: "", metric: "total_tokens", open: true,
                    hidden: new Set(), view: "days", days: 30, daily: null,
                    order: [], group: "task", taskModules: {}, manualTasks: [] };

/* BY MODULE: each call's module (common/modules.py), as its name. */
const MODULE_NAMES = { core: "Activity and states", tasks: "Task organisation",
  calendar: "Calendar management", connections: "Connections",
  recommend: "Newspaper", experience: "Work learning",
  experience_manual: "Work: tasks into stages (started by you)",
  manual: "Started by you", other: "Other",
  "heartbeat (before modules)": "Agent heartbeat (before modules)" };

function moduleOfTask(task) {
  const name = String(task || "");
  if (name in dbgTokens.taskModules) return dbgTokens.taskModules[name];
  if (name.startsWith("heartbeat:")) return "core";
  if (dbgTokens.manualTasks.includes(name) || name.startsWith("work")) return "manual";
  return "other";
}

/* The rows as the chart groups them: by the kind of work, or by module. */
function tokenGrouped(rows) {
  // REMOVED FROM THE APPLICATION - the data heartbeat, the knowledge
  // library (common/modules.py counts their calls "other"): their tokens
  // are Other, in either view, and take no colour from what still runs.
  // (They held three of the seven colours, and what runs now was put in
  // Other for them.)
  if (dbgTokens.group !== "module") {
    return rows.map((row) => (row.module === "other"
      ? Object.assign({}, row, { task: "other" }) : row));
  }
  // Named by the agent where it can: what the user started, each kind of
  // it, and a function they ran with a button, apart.
  return rows.map((row) => Object.assign({}, row, { task: row.module === "other" ? "other"
    : row.module_name || MODULE_NAMES[row.module || moduleOfTask(row.task)] || row.module
    || moduleOfTask(row.task) }));
}

/* One colour per kind of work, and the same one in both views.

   Eight colours, in a fixed order checked for telling apart - colour-blind
   readers included - on this panel's own backgrounds, and a set for each
   theme. The seven kinds that spent the most over the whole history
   (`order`) take the first seven; the next seven take the same seven
   STRIPED (dashed, as a line) - so every kind that runs has its own, the
   user's choice - and only past that, or a part removed from the
   application, is "Other", in the eighth. In either view a kind is the same
   colour whichever is shown. */
const TOKEN_COLOURS = {
  light: ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300",
          "#4a3aa7", "#e34948"],
  dark: ["#3987e5", "#d95926", "#199e70", "#c98500", "#d55181", "#008300",
         "#9085e9", "#e66767"],
};
const TOKEN_OWN_COLOURS = 7;
const TOKEN_STRIPED = 7;

function tokenKind(task) {
  const name = task || "general";
  if (name === "other") return "other";
  const at = dbgTokens.order.indexOf(name);
  return at >= 0 && at < TOKEN_OWN_COLOURS + TOKEN_STRIPED ? name : "other";
}

/* A kind's colour, and whether it is the striped one of it. */
function tokenLook(kind) {
  const dark = window.matchMedia
    && window.matchMedia("(prefers-color-scheme: dark)").matches;
  const set = dark ? TOKEN_COLOURS.dark : TOKEN_COLOURS.light;
  const at = kind === "other" ? -1 : dbgTokens.order.indexOf(kind);
  if (at < 0 || at >= TOKEN_OWN_COLOURS + TOKEN_STRIPED) {
    return { colour: set[TOKEN_OWN_COLOURS], striped: false };
  }
  return { colour: set[at % TOKEN_OWN_COLOURS], striped: at >= TOKEN_OWN_COLOURS };
}

function tokenColour(kind) {
  return tokenLook(kind).colour;
}

/* How a bar of it is filled: its colour, or its colour striped with the
   panel's own. */
function tokenFill(ctx, kind, panel) {
  const { colour, striped } = tokenLook(kind);
  if (!striped || typeof document === "undefined") return colour;
  const tile = document.createElement("canvas");
  tile.width = tile.height = 6;
  const t = tile.getContext("2d");
  t.fillStyle = colour;
  t.fillRect(0, 0, 6, 6);
  t.strokeStyle = panel || "#ffffff";
  t.lineWidth = 1.6;
  t.beginPath();
  t.moveTo(-1, 7); t.lineTo(7, -1);
  t.moveTo(5, 7); t.lineTo(7, 5);
  t.moveTo(-1, 1); t.lineTo(1, -1);
  t.stroke();
  return ctx.createPattern(tile, "repeat") || colour;
}

/* Its key in the legend and the tip: dashed when it is the striped one. */
function tokenSwatch(kind) {
  const { colour, striped } = tokenLook(kind);
  return striped ? `repeating-linear-gradient(90deg, ${colour} 0 3px, transparent 3px 5px)`
    : colour;
}

/* Kinds the whole history did not rank (none yet, or new since) are ranked
   after it by what they spent in what is shown. */
function tokenRank(entries) {
  const spent = {};
  entries.forEach(([task, value]) => {
    const name = task || "general";
    spent[name] = (spent[name] || 0) + Number(value || 0);
  });
  Object.keys(spent).filter((t) => t !== "other" && !dbgTokens.order.includes(t))
    .sort((a, b) => spent[b] - spent[a] || a.localeCompare(b))
    .forEach((t) => dbgTokens.order.push(t));
}

/* The kinds in colour order, "Other" last; and what "Other" holds. */
function tokenKindsIn(tasks) {
  const kinds = [...new Set(tasks.map(tokenKind))];
  kinds.sort((a, b) => (a === "other") - (b === "other")
    || dbgTokens.order.indexOf(a) - dbgTokens.order.indexOf(b));
  return kinds;
}

function tokenOthers(tasks) {
  return [...new Set(tasks.filter((t) => tokenKind(t) === "other"))].sort();
}

function tokenSeries() {
  /* One series per task, each a running total, sharing the x axis of all
     calls in order - so the lines are directly comparable at any moment. */
  const calls = tokenGrouped(dbgTokens.calls);
  tokenRank(calls.map((c) => [c.task, c.total_tokens]));
  const tasks = tokenKindsIn(calls.map((c) => c.task || "general"));
  const running = Object.fromEntries(tasks.map((t) => [t, 0]));
  const series = Object.fromEntries(tasks.map((t) => [t, []]));
  calls.forEach((call, index) => {
    const task = tokenKind(call.task);
    const value = Number(call[dbgTokens.metric] || 0);
    running[task] += value;
    // Every series gets a point at every x, so they can be read against each
    // other rather than each having its own ragged timeline.
    tasks.forEach((t) => series[t].push({ x: index, y: running[t] }));
  });
  return { tasks, series };
}

/* Draw when there is somewhere to draw.

   Both Debugger charts are drawn once when the page loads - while the
   Debugger tab is still hidden, so their canvases have no layout at all. A
   canvas with no layout does not report zero and refuse; it reports zero and
   the code carries on, so one chart sized itself to a fallback of 600 and
   the other to a single pixel, and both then had the browser stretch that
   bitmap across a thousand. Axis labels ended up outside the visible area,
   which is why the axis looked as though it had never been drawn.

   Nothing redrew them when the tab was opened, so the first thing that
   happened to re-render - changing a view, toggling a series - was what
   appeared to "make the chart work".

   So: a draw is skipped while the element has no width, and repeated once it
   has one. The observer covers every way that can happen - opening the tab,
   un-collapsing the panel, resizing the window - rather than each being
   wired up separately and one of them being missed.
*/
function redrawWhenSized(canvas, render) {
  if (!canvas || canvas.__sizeWatched) return;
  canvas.__sizeWatched = true;
  if (typeof ResizeObserver !== "function") return;
  let lastWidth = 0;
  const observer = new ResizeObserver(() => {
    const width = canvas.clientWidth;
    if (width > 0 && width !== lastWidth) {
      lastWidth = width;
      render();
    }
  });
  observer.observe(canvas);
}

function renderTokenChart() {
  const canvas = $("#dbg-tokens-chart");
  const legend = $("#dbg-tokens-legend");
  if (!canvas || !legend) return;
  const note = $("#dbg-tokens-note");
  // What a cost is, when cost is shown.
  const costNote = $("#dbg-cost-note");
  if (costNote) costNote.hidden = dbgTokens.metric !== "estimated_cost";
  // The days to show, named, only when the chart is by day.
  const days = $("#dbg-tokens-days-label");
  if (days) days.hidden = dbgTokens.view !== "days";
  tokenTip(null);

  const byDay = dbgTokens.view === "days";
  const empty = byDay ? !(dbgTokens.daily && dbgTokens.daily.rows.length)
    : !dbgTokens.calls.length;
  if (empty) {
    if (note) {
      note.textContent = byDay
        ? (dbgTokens.daily ? `No model calls in the last ${dbgTokens.days} days.`
          : "Reading the days...")
        : "No model calls yet in this run.";
    }
    const blank = canvas.getContext("2d");
    blank.clearRect(0, 0, canvas.width, canvas.height);
    legend.innerHTML = "";
    canvas.__hover = null;
    return;
  }

  // Same as the chart below: no layout yet means no width to draw at, and
  // Math.max(1, 0) is a one-pixel bitmap stretched across a thousand.
  const rect = canvas.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const ratio = window.devicePixelRatio || 1;
  canvas.width = Math.max(1, rect.width * ratio);
  canvas.height = Math.max(1, rect.height * ratio);
  const ctx = canvas.getContext("2d");
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.clearRect(0, 0, rect.width, rect.height);
  const style = getComputedStyle(document.body);
  const look = {
    line: style.getPropertyValue("--line").trim() || "#30363d",
    muted: style.getPropertyValue("--muted").trim() || "#8b949e",
    panel: style.getPropertyValue("--panel").trim() || "#ffffff",
  };
  const pad = { left: 54, right: 10, top: 10, bottom: 22 };
  const plot = { rect, pad, w: Math.max(1, rect.width - pad.left - pad.right),
                 h: Math.max(1, rect.height - pad.top - pad.bottom) };
  const drawn = byDay ? drawTokenDays(ctx, plot, look, note)
    : drawTokenCalls(ctx, plot, look, note);

  // The legend doubles as the control: a chart of eight lines is unreadable
  // until seven of them can be put away. Each key carries its name and its
  // total - the colours alone are not enough to go by.
  const others = drawn.others;
  legend.innerHTML = drawn.kinds.map((kind) => {
    const off = dbgTokens.hidden.has(kind);
    // Other: what was removed from the application, and any kind past the
    // fourteenth - counted only for those.
    const past = others.filter((one) => one !== "other");
    const name = kind === "other" ? (past.length ? `Other (${past.length})` : "Other") : kind;
    const title = kind === "other"
      ? `${["Parts removed from the application"].concat(past).join(", ")} - show or hide`
      : "Show or hide";
    return `<button type="button" class="dbg-token-key${off ? " off" : ""}"
      data-task="${escapeHtml(kind)}" title="${escapeHtml(title)}">
      <span class="dbg-token-swatch" style="background:${
        tokenSwatch(kind)}"></span>
      ${escapeHtml(name)} <span class="muted">${
        formatTokenValue(drawn.totals[kind] || 0)}</span>
    </button>`;
  }).join("") + (Object.values(drawn.cached || {}).some((v) => v > 0)
    ? `<span class="muted dbg-token-cache-key"><span class="dbg-token-swatch dbg-token-swatch-cache">
      </span>Faded: read from the cache, at a fraction of the price</span>` : "");
}

/* The top of the scale, rounded up to about four round steps - so the
   gridlines read 1M, 2M, 3M rather than 845.6k and 1.7M. */
function tokenNice(raw) {
  if (!(raw > 0)) raw = 4;           // nothing yet: a plain 0-4 scale
  const rough = raw / 4;
  const power = 10 ** Math.floor(Math.log10(rough));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * power).find((s) => s >= rough);
  return { peak: step * Math.ceil(raw / step - 1e-9) || step, step };
}

/* Gridlines with the value each stands for. A chart without numbers on it
   says only "up". */
function tokenGrid(ctx, plot, look, nice, y) {
  ctx.strokeStyle = look.line;
  ctx.fillStyle = look.muted;
  ctx.font = "10px system-ui, sans-serif";
  ctx.lineWidth = 1;
  for (let value = 0; value <= nice.peak + nice.step / 2; value += nice.step) {
    const at = Math.round(y(value)) + 0.5;
    ctx.beginPath();
    ctx.moveTo(plot.pad.left, at);
    ctx.lineTo(plot.pad.left + plot.w, at);
    ctx.stroke();
    ctx.textAlign = "right";
    ctx.fillText(formatTokenValue(value), plot.pad.left - 6, at + 3);
  }
  ctx.textAlign = "left";
}

/* THE LAST CALLS: a running total per kind, call by call. */
function drawTokenCalls(ctx, plot, look, note) {
  const { tasks, series } = tokenSeries();
  const shown = tasks.filter((t) => !dbgTokens.hidden.has(t));
  const calls = dbgTokens.calls;
  // The history outlives the process now (section 14.35, as amended), so the
  // note says what it actually covers. It used to say "since the agent
  // started", which was true and was the problem: the one question worth
  // asking is whether this is getting more expensive, and that cannot be
  // answered from a window that restarts whenever anything is fixed.
  if (note) {
    const from = dbgTokens.since
      ? new Date(dbgTokens.since).toLocaleDateString(undefined,
          { day: "numeric", month: "short", year: "numeric" })
      : "";
    note.textContent = `${calls.length} calls`
      + (from ? `, recorded since ${from}` : "");
  }
  const { pad } = plot;
  const lastX = Math.max(1, calls.length - 1);
  const nice = tokenNice(Math.max(0, ...shown.flatMap((t) => series[t].map((p) => p.y))));
  const peak = nice.peak;
  const x = (i) => pad.left + (i / lastX) * plot.w;
  const y = (v) => pad.top + plot.h - (v / peak) * plot.h;
  tokenGrid(ctx, plot, look, nice, y);
  ctx.fillText(`${calls.length} calls`, pad.left, plot.rect.height - 6);
  shown.forEach((task) => {
    ctx.strokeStyle = tokenColour(task);
    ctx.lineWidth = 2;
    ctx.lineJoin = "round";
    // The striped one of a colour, dashed.
    ctx.setLineDash(tokenLook(task).striped ? [6, 4] : []);
    ctx.beginPath();
    series[task].forEach((point, index) => {
      const px = x(point.x);
      const py = y(point.y);
      if (index === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.stroke();
  });
  ctx.setLineDash([]);
  const totals = Object.fromEntries(tasks.map((t) =>
    [t, series[t][series[t].length - 1].y]));
  // The hover: the call under the pointer, and every kind's total by then.
  ctx.canvas.__hover = (px) => {
    const index = Math.round(((px - pad.left) / plot.w) * lastX);
    if (index < 0 || index > lastX || px < pad.left - 4) return null;
    const call = calls[index];
    const at = call.timestamp ? new Date(call.timestamp) : null;
    return {
      x: x(index), band: 0,
      head: `Call ${index + 1} of ${calls.length}${at ? ` · ${
        at.toLocaleString(undefined, { month: "short", day: "numeric",
          hour: "2-digit", minute: "2-digit" })}` : ""}`,
      sub: `${call.task || "general"}: ${formatTokenValue(
        Number(call[dbgTokens.metric] || 0))} this call`,
      rows: shown.map((t) => [t, series[t][index].y]),
      rowsSay: "running total",
    };
  };
  return { kinds: tasks, totals, others: tokenOthers(tokenGrouped(calls).map((c) => c.task)) };
}

/* PER DAY, the last N days: one bar a day, stacked by kind of work - the
   trend the last calls cannot show, since a busy hour fills them. */
function drawTokenDays(ctx, plot, look, note) {
  const days = dbgTokens.daily.days;
  const rows = tokenGrouped(dbgTokens.daily.rows);
  const metric = dbgTokens.metric;
  tokenRank(rows.map((r) => [r.task, r.total_tokens]));
  const kinds = tokenKindsIn(rows.map((r) => r.task));
  const shown = kinds.filter((k) => !dbgTokens.hidden.has(k));
  const per = days.map(() => Object.fromEntries(kinds.map((k) => [k, 0])));
  // WHAT WAS READ FROM THE CACHE, of tokens read: part of each kind's bar,
  // drawn lighter - it costs a fraction of the rest.
  const withCache = metric === "total_tokens" || metric === "input_tokens";
  const cache = days.map(() => Object.fromEntries(kinds.map((k) => [k, 0])));
  const calls = days.map(() => 0);
  const totals = Object.fromEntries(kinds.map((k) => [k, 0]));
  const cached = Object.fromEntries(kinds.map((k) => [k, 0]));
  rows.forEach((row) => {
    const at = days.indexOf(row.day);
    if (at < 0) return;
    const kind = tokenKind(row.task);
    per[at][kind] += Number(row[metric] || 0);
    totals[kind] += Number(row[metric] || 0);
    if (withCache) {
      cache[at][kind] += Number(row.cached_tokens || 0);
      cached[kind] += Number(row.cached_tokens || 0);
    }
    calls[at] += row.calls;
  });
  const dayTotal = per.map((one) => shown.reduce((s, k) => s + one[k], 0));
  const dayCache = cache.map((one) => shown.reduce((s, k) => s + one[k], 0));
  if (note) {
    const all = calls.reduce((s, n) => s + n, 0);
    const busy = dayTotal.filter((v) => v > 0).length;
    note.textContent = `${all} calls over the last ${days.length} days`
      + ` · ${formatTokenValue(dayTotal.reduce((s, v) => s + v, 0) / Math.max(1, busy))}`
      + " a day on days with calls";
  }
  const { pad } = plot;
  const nice = tokenNice(Math.max(0, ...dayTotal));
  const peak = nice.peak;
  const y = (v) => pad.top + plot.h - (v / peak) * plot.h;
  tokenGrid(ctx, plot, look, nice, y);
  const slot = plot.w / days.length;
  const barW = Math.max(2, Math.min(28, slot * 0.72));
  const xOf = (i) => pad.left + slot * i + (slot - barW) / 2;
  const label = (day) => new Date(`${day}T12:00:00`).toLocaleDateString(
    undefined, { month: "short", day: "numeric" });
  // Dates under the bars, as many as fit without touching.
  const every = Math.max(1, Math.ceil(56 / slot));
  ctx.fillStyle = look.muted;
  ctx.textAlign = "center";
  days.forEach((day, i) => {
    if ((days.length - 1 - i) % every) return;
    ctx.fillText(label(day), pad.left + slot * i + slot / 2, plot.rect.height - 6);
  });
  ctx.textAlign = "left";
  const base = y(0);
  days.forEach((day, i) => {
    let top = base;
    const parts = shown.filter((k) => per[i][k] > 0);
    parts.forEach((kind, n) => {
      const height = (per[i][kind] / peak) * plot.h;
      const last = n === parts.length - 1;
      // A 2px gap of the panel's own colour between kinds, and the bar's
      // top end rounded.
      const h = Math.max(0, height - (last ? 0 : 2));
      ctx.fillStyle = tokenFill(ctx, kind, look.panel);
      ctx.beginPath();
      if (last && ctx.roundRect && h > 4) {
        ctx.roundRect(xOf(i), top - height, barW, h, [4, 4, 0, 0]);
      } else {
        ctx.rect(xOf(i), top - height + (last ? 0 : 2), barW, h);
      }
      ctx.fill();
      // Its cache reads, the upper part of it, lighter: the panel's colour
      // laid over half-through.
      const share = per[i][kind] > 0 ? Math.min(1, cache[i][kind] / per[i][kind]) : 0;
      if (share > 0) {
        ctx.save();
        ctx.clip();
        ctx.globalAlpha = 0.5;
        ctx.fillStyle = look.panel;
        ctx.fillRect(xOf(i), top - height, barW, height * share);
        ctx.restore();
      }
      top -= height;
    });
  });
  ctx.canvas.__hover = (px) => {
    const i = Math.floor((px - pad.left) / slot);
    if (i < 0 || i >= days.length) return null;
    return {
      x: pad.left + slot * i + slot / 2, band: slot,
      head: new Date(`${days[i]}T12:00:00`).toLocaleDateString(undefined,
        { weekday: "short", month: "short", day: "numeric" }),
      sub: `${formatTokenValue(dayTotal[i])} · ${calls[i]} calls`,
      rows: shown.filter((k) => per[i][k] > 0).map((k) => [k, per[i][k]]),
      rowsSay: dayCache[i] > 0 ? `${formatTokenValue(dayCache[i])} of it from the cache` : "",
    };
  };
  return { kinds, totals, cached, others: tokenOthers(rows.map((r) => r.task)) };
}

/* What the pointer is over, in a box beside it: the kinds by name and
   value, so nothing depends on telling the colours apart. */
function tokenTip(at) {
  const tip = $("#dbg-tokens-tip");
  const band = $("#dbg-tokens-band");
  if (!tip || !band) return;
  if (!at) { tip.hidden = true; band.hidden = true; return; }
  const name = (k) => (k === "other" ? "Other" : k);
  tip.innerHTML = `<strong>${escapeHtml(at.head)}</strong>
    <div class="muted">${escapeHtml(at.sub)}</div>
    ${at.rows.length ? `<table>${at.rows.map(([k, v]) => `<tr><td><span
      class="dbg-token-swatch" style="background:${tokenSwatch(k)}"></span>
      ${escapeHtml(name(k))}</td><td>${formatTokenValue(v)}</td></tr>`).join("")}
    </table>` : ""}${at.rowsSay ? `<div class="muted">${escapeHtml(at.rowsSay)}</div>` : ""}`;
  tip.hidden = false;
  const box = tip.parentNode.getBoundingClientRect();
  const canvas = $("#dbg-tokens-chart");
  const offset = canvas.getBoundingClientRect().left - box.left;
  const left = offset + at.x;
  band.hidden = false;
  band.style.left = `${left - Math.max(1, at.band) / 2}px`;
  band.style.width = `${Math.max(1, at.band)}px`;
  band.style.top = `${canvas.offsetTop}px`;
  band.style.height = `${canvas.offsetHeight}px`;
  const wide = tip.offsetWidth;
  tip.style.left = `${left + 12 + wide > box.width ? left - 12 - wide : left + 12}px`;
  tip.style.top = `${canvas.offsetTop + 4}px`;
}

function formatTokenValue(value) {
  if (dbgTokens.metric === "estimated_cost") {
    return value >= 1 ? `$${value.toFixed(2)}` : `$${value.toFixed(4)}`;
  }
  // 1M, not 1.0M; 2.5M as it is.
  const short = (n) => String(Number(n.toFixed(1)));
  if (value >= 1e6) return `${short(value / 1e6)}M`;
  if (value >= 1e3) return `${short(value / 1e3)}k`;
  return String(Math.round(value));
}

async function loadTokenUsage() {
  try {
    // In every build - not the Debugger's, which a released one has not
    // (the user, 2026-10-27: the Overview's Token usage was empty).
    const metrics = await api.get("/api/tokens") || {};
    dbgTokens.calls = metrics.tokens_over_time || [];
    dbgTokens.since = metrics.measured_since || "";
    // Biggest spender first, over the whole history: what keeps a colour.
    // By kind of work only: by module, the order is of the modules, ranked
    // as they are drawn - set back to the kinds of work, every module fell
    // past the seventh place and was drawn as "Other".
    if (dbgTokens.group !== "module") dbgTokens.order = Object.keys(metrics.by_task || {});
  } catch (err) {
    dbgTokens.calls = [];
    dbgTokens.since = "";
  }
  if (dbgTokens.view === "days") await loadTokenDays();
  renderTokenChart();
}

async function loadTokenDays() {
  try {
    const said = await api.get(`/api/tokens/by_day?days=${
      dbgTokens.days}&east=${-new Date().getTimezoneOffset()}`) || {};
    // Both lists always there: the per-day view is the default now, and an
    // answer without them stopped the page's script as it loaded.
    dbgTokens.daily = { ...said, days: said.days || [], rows: said.rows || [] };
  } catch (err) {
    dbgTokens.daily = { days: [], rows: [] };
  }
}

function wireTokenUsage() {
  redrawWhenSized($("#dbg-tokens-chart"), renderTokenChart);
  const metric = $("#dbg-tokens-metric");
  if (!metric) return;
  // Bound once, however many times this is called. A second set of listeners
  // does not look wrong - the chart still draws - it just makes every toggle
  // fire twice and land back where it started, which reads as a button that
  // does nothing at all.
  if (window.__tokensWired) return;
  window.__tokensWired = true;
  metric.addEventListener("change", () => {
    dbgTokens.metric = metric.value;
    renderTokenChart();
  });
  const group = $("#dbg-tokens-group");
  if (group) {
    group.addEventListener("change", async () => {
      dbgTokens.group = group.value;
      // Colours ranked anew for what is now grouped; nothing kept hidden.
      dbgTokens.order = [];
      dbgTokens.hidden = new Set();
      if (dbgTokens.group === "module" && !Object.keys(dbgTokens.taskModules).length) {
        try {
          const said = await api.get("/api/modules");
          dbgTokens.taskModules = said.task_modules || {};
          dbgTokens.manualTasks = said.manual_tasks || [];
        } catch (err) { /* grouped as well as it can be */ }
      }
      renderTokenChart();
    });
  }
  const view = $("#dbg-tokens-view");
  const days = $("#dbg-tokens-days");
  const showDays = async () => {
    dbgTokens.view = view.value;
    dbgTokens.days = Number(days.value) || 30;
    if (dbgTokens.view === "days") {
      dbgTokens.daily = null;
      renderTokenChart();
      await loadTokenDays();
    }
    renderTokenChart();
  };
  if (view) view.addEventListener("change", showDays);
  if (days) days.addEventListener("change", showDays);
  const canvas = $("#dbg-tokens-chart");
  canvas.addEventListener("mousemove", (event) => {
    const hover = canvas.__hover;
    const rect = canvas.getBoundingClientRect();
    tokenTip(hover ? hover(event.clientX - rect.left) : null);
  });
  canvas.addEventListener("mouseleave", () => tokenTip(null));
  $("#dbg-tokens-legend").addEventListener("click", (event) => {
    const key = event.target.closest("[data-task]");
    if (!key) return;
    const task = key.dataset.task;
    if (dbgTokens.hidden.has(task)) dbgTokens.hidden.delete(task);
    else dbgTokens.hidden.add(task);
    renderTokenChart();
  });
  const collapse = $("#dbg-tokens-collapse");
  if (collapse) {
    collapse.addEventListener("click", () => {
      dbgTokens.open = !dbgTokens.open;
      $("#dbg-tokens-body").hidden = !dbgTokens.open;
      collapse.textContent = dbgTokens.open ? "⌴" : "⌵";
      if (dbgTokens.open) renderTokenChart();
    });
  }
  // A canvas sized from its box has to be redrawn when the box changes.
  window.addEventListener("resize", () => {
    if (dbgTokens.open) renderTokenChart();
  });
}

/* ------------------------------------------------- the experience debugger */
/* THE EXPERIENCE DEBUGGER: one piece of work done three ways - each a view of
   its own, chosen by its tab, so the three are not all going on the page at
   once (each tab says how its way stands) -
   one model on its own, builder and reviewer with none of your experience,
   and the whole system - to see what each part is worth. A project here is
   made by hand, never one you are working on, and never shown in
   Experience: a name, your description, and a folder - in which a
   subfolder is made for each way, each sealed from the other two. Each way
   is started on its own, with the instruction typed as it starts - offered
   the words the last way began with, so all three can start alike;
   started, they may run at once. Nothing limits them unless you set a
   limit.

   Each way's runs are drawn as the Experience tab draws a run (xpRun): the
   live session, the versions and their slides, the contract in force,
   Stop, Pause and Continue - the same controls, with this panel as their
   host - and the tree of its cards and stages as the Experience tab draws
   the agents' work on a piece of work. Never drawn again under your typing
   (xpEditing / xpDefer); while a way goes, only its live parts change. */
const XD_VARIANTS = [
  { variant: "single", label: "Single model", folder: "A",
    about: "one model with the same tools - no contract, no stages, no reviewer" },
  { variant: "noctx", label: "Builder + reviewer, no context", folder: "B",
    about: "contract and rounds, but the reviewer gets none of your experience" },
  { variant: "full", label: "Full", folder: "C",
    about: "the whole system, its reviewer reading your experience" },
];
const xdState = { open: true, projects: [], project: null, newOpen: false, newFolder: "",
                  drafts: {}, editing: null, removeAsk: false, clearAsk: "", clearAllAsk: false, runs: {},
                  runVariant: {}, timer: null, loading: false, way: "", waySnaps: {},
                  waiting: {}, leaveOut: null, leaveOutAsk: "" };

/* EACH WAY'S OWN TREE of cards and stages - how its work evolved - drawn and
   opened as the Experience tab draws the agents' work on a piece of work
   (xpGraphSvg, xpShowStage, xpShowCard), in boxes of its own: "xd-<way>". */
experienceState.xdTrees = experienceState.xdTrees || {};
XD_VARIANTS.forEach((v) => {
  XP_VIEWS[`xd-${v.variant}`] = {
    graphs: () => [experienceState.xdTrees[v.variant] || {}], box: `#xd-stage-${v.variant}`,
    frame: `#xd-tree-${v.variant}`, stage: `xdStage-${v.variant}`,
    card: `xdCard-${v.variant}`, work: true };
});

/* THE PROJECT OPEN, REMEMBERED - across a refresh and a restart of the
   application. It was kept in the page's memory alone, so a reload showed no
   project open and the one just made seemed to be gone. Only this viewer's
   convenience: the projects themselves are in the database. */
const XD_OPEN_KEY = "pa.xdebug.open";

function xdRemember(project) {
  try {
    if (project) localStorage.setItem(XD_OPEN_KEY, project.id);
    else localStorage.removeItem(XD_OPEN_KEY);
  } catch (err) { /* storage refused: the newest project opens instead */ }
}

function xdRemembered() {
  try { return localStorage.getItem(XD_OPEN_KEY) || ""; } catch (err) { return ""; }
}

/* What was typed - kept as it is typed, so a redraw does not lose it. */
function xdDraft(key, fallback = "") {
  return key in xdState.drafts ? xdState.drafts[key] : fallback;
}

/* A path in the folder the user chose, written as it writes its own. */
function xdUnder(folder, name) {
  const sep = String(folder).includes("\\") ? "\\" : "/";
  return `${String(folder).replace(/[\\/]+$/, "")}${sep}${name}`;
}

/* The limits set for one way - each left empty is not sent, and is then no
   limit at all. */
function xdLimits(at) {
  const box = at && at.closest ? at.closest("[data-xd-variant]") : null;
  const limit = (name) => {
    const typed = box ? (box.querySelector(`[data-xd-limit="${name}"]`) || {}).value : "";
    return typed === undefined || typed === "" ? undefined : Number(typed);
  };
  return Object.fromEntries(XP_LIMITS.map((name) => [name, limit(name)]));
}

const XD_HOST = {
  redraw: (force) => loadDebuggerExperience(force),
  limits: (at) => xdLimits(at),
  continueUrl: "/api/debugger/experience/continue",
  extra: (runId) => ({ project: (xdState.project || {}).id,
                       variant: xdState.runVariant[runId] }),
};

function xdNewForm() {
  const folder = xdState.newFolder;
  return `<div class="xd-new" id="xd-new">
    <label>Name <input type="text" data-xd-field="new-name" maxlength="300"
      value="${escapeHtml(xdDraft("new-name"))}"></label>
    <label>Your description <textarea rows="2" data-xd-field="new-description"
      maxlength="4000">${escapeHtml(xdDraft("new-description"))}</textarea></label>
    <div class="xd-new-folder"><button type="button" class="small secondary"
      data-xd-choose="1">Choose folder…</button>
      ${folder ? `<code>${escapeHtml(folder)}</code>
        <ul class="xp-work-list xd-subfolders">${XD_VARIANTS.map((v) => `<li><code>${
          escapeHtml(xdUnder(folder, v.folder))}</code> <span class="muted">${
          escapeHtml(v.label)}</span></li>`).join("")}</ul>
        <p class="muted">These three are made in it. Each way writes only in its own,
          and cannot read the other two.</p>`
        : `<span class="muted">no folder chosen</span>`}</div>
    <p><button type="button" class="small" data-xd-create="1">Create</button>
      <button type="button" class="small secondary" data-xd-new-cancel="1">Cancel</button></p>
  </div>`;
}

/* One of the project's words - its name, description or instruction - with
   a way to change it in place. */
function xdWords(project, field, label) {
  const words = String(project[field] || "");
  if (xdState.editing === field) {
    const key = `edit-${field}`;
    return `<div class="xp-about xp-about-editing xd-words"><span class="xp-about-label">${
      escapeHtml(label)}</span>
      ${field === "name" ? `<input type="text" data-xd-field="${key}" maxlength="300"
        value="${escapeHtml(xdDraft(key, words))}">`
        : `<textarea rows="3" data-xd-field="${key}" maxlength="8000">${
          escapeHtml(xdDraft(key, words))}</textarea>`}
      <span class="xp-about-buttons"><button type="button" class="small"
        data-xd-save="${field}">Save</button>
      <button type="button" class="small secondary" data-xd-edit-cancel="1">Cancel</button></span>
    </div>`;
  }
  return `<div class="xp-about xd-words"><span class="xp-about-label">${escapeHtml(label)}</span>
    ${words ? `<span class="xp-about-words">${escapeHtml(words)}</span>`
      : `<span class="muted">none</span>`}
    <span class="xp-about-edit" role="button" tabindex="0" data-xd-edit="${field}">edit</span>
  </div>`;
}

/* CLEAR A WAY: everything it wrote in its folder, emptied - the folder
   kept - and its runs forgotten; the other two ways and the project stay.
   Asked in the page first, naming the folder; not while this way goes (the
   other two may). */
/* CLEAR ALL: the three ways at once, beside Remove. Not while any of them
   goes - the server refuses it too, so none is left half-cleared. */
function xdClearAllButton() {
  const project = xdState.project || {};
  const going = XD_VARIANTS.some((v) => {
    const shown = (project.variants || []).find((one) => one.variant === v.variant) || {};
    return Boolean(xdWayState(v).going || shown.alive);
  });
  return `<button type="button" class="small secondary" data-xd-clear-all="1"${going
    ? ` disabled title="A way is going: stop it first"`
    : ` title="Empty all three ways' folders and forget their runs - the project stays"`
  }>Clear all</button>`;
}

function xdClearLine(v, folder, going) {
  const id = escapeHtml(v.variant);
  if (xdState.clearAsk === v.variant) {
    return `<p class="xd-clear-ask" data-xd-clear-ask="${id}">Clear everything this way
      wrote in <code>${escapeHtml(folder)}</code>? Its runs are forgotten; the other two
      ways and the project stay.
      <button type="button" class="small danger" data-xd-clear-yes="${id}">Clear</button>
      <button type="button" class="small secondary" data-xd-clear-no="${id}">Keep it</button></p>`;
  }
  return `<button type="button" class="small secondary" data-xd-clear="${id}"${going
    ? ` disabled title="This way is going: stop it first"`
    : ` title="Empty this way's folder and forget its runs - the other two ways stay"`
  }>Clear</button>`;
}

/* WHERE A WAY'S RUN STANDS: going, paused, waiting for you, ended (and
   how), interrupted - or not started. From the live session while it is
   followed - the freshest word - else from the runs' list; the runs' list
   saying it is over is over, whatever the session said last. */
/* A WAY WAITING FOR ROOM: everything going side by side shares the
   computer (common/pool.py), and a way started while there is none waits
   its turn, then starts by itself. Its wait - why, how far along - or null. */
function xdWaits(variant) {
  const said = (xdState.waiting || {})[variant] || {};
  return said.why ? said : null;
}

function xdWayState(v) {
  const runs = xdState.runs[v.variant] || [];
  const going = runs.find((run) => run.alive);
  const latest = going || runs[0];
  const waits = going ? null : xdWaits(v.variant);
  if (waits && waits.starting) {
    // Its process getting ready - a minute or two for the full way: its last
    // run, ended, is not where it stands.
    return { state: "starting", words: "starting", latest, going: null, waits, data: {} };
  }
  if (waits) {
    return { state: "waiting_room", words: "waiting for room", latest, going: null,
             waits, data: {} };
  }
  if (!latest) return { state: "none", words: "not started", latest: null, going: null };
  const live = xpLiveState(latest.id);
  const data = live.open ? live.data : null;
  const ended = latest.status === "interrupted" ? "interrupted" : "ended";
  let state = data && data.state ? data.state
    : latest.alive ? (latest.status === "waiting for you" ? "waiting_for_you"
      : latest.paused ? "paused" : "going") : ended;
  if (!latest.alive && !["ended", "interrupted"].includes(state)) state = ended;
  const outcome = !latest.alive && state === "ended" ? String(latest.status || "") : "";
  return { state, words: XP_LIVE_STATE[state] || state, outcome, latest, going,
           failed: /fail/i.test(outcome), data: data || {} };
}

/* A WAY'S HEADING: its name - and, beside it, where its run stands (going,
   with a spinner while it works; paused; waiting for you; ended, and how)
   and its Stop and Clear. They were below its limits and inside the run,
   where you had to look for them; beside the name, one glance says how the
   way stands and how to stop or clear it. Changed in place - from the live
   session about once a second, and as the panel is asked again - never
   drawing anything else of the way. */
function xdWayLive(v) {
  const project = xdState.project || {};
  const shown = (project.variants || []).find((one) => one.variant === v.variant) || {};
  const folder = shown.folder || xdUnder(project.folder || "", v.folder);
  const way = xdWayState(v);
  const parts = [];
  const said = (xdState.waiting || {})[v.variant] || {};
  const refused = said.could_not_start;
  if (way.state === "starting") {
    return `<span class="xp-live-state xp-live-state-going" data-xd-way-state="starting">${
      escapeHtml(way.words)}</span> <span class="xp-live-spin xd-way-spin" aria-hidden="true"></span>
      <span class="muted xd-way-wait">its process is getting ready - this can take a minute or two</span>`;
  }
  if (way.waits) {
    parts.push(`<span class="xp-live-state xp-live-state-waiting_room"
      data-xd-way-state="waiting_room">${escapeHtml(way.words)}</span>`);
    parts.push(`<span class="muted xd-way-wait">${escapeHtml(way.waits.why)} - ${
      Number(way.waits.position) === 1 ? "next in line"
        : `${Number(way.waits.position)} in line`}; it starts by itself</span>`);
    parts.push(`<button type="button" class="small secondary" data-xd-unwait="${
      escapeHtml(v.variant)}">Don't start it</button>`);
    return parts.join(" ");
  }
  if (refused && !way.going) {
    // Asked for and not started - its process could not get going - is said
    // so, not left reading "not started" (2026-10-24).
    parts.push(said.waited
      ? `<span class="danger-text">Its turn came, but it could not start: ${escapeHtml(refused)}</span>`
      : `<span class="danger-text">It could not start: ${escapeHtml(refused)}</span>`);
  }
  if (way.latest) {
    parts.push(`<span class="xp-live-state xp-live-state-${escapeHtml(way.state)}"
      data-xd-way-state="${escapeHtml(way.state)}">${escapeHtml(way.words)}</span>`);
    if (way.state === "going") {
      parts.push(`<span class="xp-live-spin xd-way-spin" aria-hidden="true"></span>`);
    }
    if (way.outcome) parts.push(`<span class="muted">${escapeHtml(way.outcome)}</span>`);
  } else {
    parts.push(`<span class="muted">not started</span>`);
  }
  if (way.going && !["ended", "interrupted"].includes(way.state)) {
    const pause = xpPauseButton(way.going, way.data);
    if (pause) parts.push(pause);
    const stopping = way.going.stopping || (way.data.progress || {}).stopping;
    parts.push(stopping
      ? `<span class="muted">wrapping up…</span> <button type="button" class="small secondary danger"
          data-xp-stop-now="${escapeHtml(way.going.id)}"
          title="Stop at once - no slides, no to-do list">Stop now</button>`
      : `<button type="button" class="small secondary" data-xp-stop="${escapeHtml(way.going.id)}"
          title="It wraps up: slides of what exists, and a to-do list">Stop</button>`);
  }
  if (xdState.clearAsk !== v.variant) {
    parts.push(xdClearLine(v, folder, Boolean(way.going || shown.alive)));
  }
  return parts.join(" ");
}

/* A way's tab's badge: how it stands, at a glance, whichever way is shown -
   a spinner while it goes. */
function xdWayBadge(v) {
  const way = xdWayState(v);
  const refused = way.state === "none"
    && ((xdState.waiting || {})[v.variant] || {}).could_not_start;
  const kind = way.failed || refused ? "failed" : way.state;
  const said = way.failed ? "failed" : refused ? "could not start"
    : way.state === "ended" ? "ended" : way.state === "none" ? "not started" : way.words;
  return `${way.state === "going" ? `<span class="xp-live-spin" aria-hidden="true"></span>` : ""}<span
    class="xd-badge xd-badge-${escapeHtml(kind)}">${escapeHtml(said)}</span>`;
}

function xdWayPatch(variant) {
  const v = XD_VARIANTS.find((one) => one.variant === variant);
  if (!v) return;
  const put = (at, html) => {
    if (!at || at._xpHtml === xpShows(html)) return;
    at.innerHTML = html;
    at._xpHtml = xpShows(html);
  };
  put($(`#dbg-xd [data-xd-way-live="${CSS.escape(variant)}"]`), xdWayLive(v));
  put($(`#dbg-xd [data-xd-tab-badge="${CSS.escape(variant)}"]`), xdWayBadge(v));
}

/* A run's live session heard from: if the run is one of a way's, the way's
   heading and tab follow it. */
function xdWayFollow(runId) {
  const variant = xdState.runVariant[runId];
  if (variant) xdWayPatch(variant);
}

/* THE WAY SHOWN - one at a time, chosen by its tab, so the three are not
   all going on the page at once; remembered for each project (in this
   browser: XD_WAY_KEY). Not chosen yet: a way that goes, else the full one. */
const XD_WAY_KEY = "pa.xdebug.way.";

function xdWayShown() {
  const project = xdState.project;
  if (!project) return "";
  let saved = "";
  try { saved = localStorage.getItem(XD_WAY_KEY + project.id) || ""; } catch (err) { saved = ""; }
  if (XD_VARIANTS.some((v) => v.variant === saved)) return saved;
  const going = XD_VARIANTS.find((v) => (xdState.runs[v.variant] || []).some((run) => run.alive));
  return (going || XD_VARIANTS[XD_VARIANTS.length - 1]).variant;
}

/* Another way shown: the one left keeps where it was scrolled to (kept
   now, put back when it is shown again - a box out of sight forgets it),
   and nothing is drawn again: the three are all on the page, two of them
   hidden, with what was typed in them. Its chart is drawn at its width. */
function xdShowWay(variant) {
  const project = xdState.project;
  const body = $("#dbg-xd-body");
  if (!project || !body) return;
  const before = xdWayShown();
  const leaving = body.querySelector(`[data-xd-variant="${CSS.escape(before)}"]`);
  if (leaving && before !== variant) xdState.waySnaps[before] = xpViewKeep(leaving);
  try { localStorage.setItem(XD_WAY_KEY + project.id, variant); } catch (err) { /* this page */ }
  xdWayTabs(body);
}

/* The tabs and the ways shown as the choice is. */
function xdWayTabs(body) {
  const variant = xdWayShown();
  $$("[data-xd-tab]", body).forEach((tab) => {
    const on = tab.dataset.xdTab === variant;
    tab.setAttribute("aria-selected", on ? "true" : "false");
    tab.tabIndex = on ? 0 : -1;
    tab.classList.toggle("selected", on);
  });
  $$("[data-xd-variant]", body).forEach((section) => {
    const on = section.dataset.xdVariant === variant;
    if (section.hidden !== !on) section.hidden = !on;
    if (!on) return;
    xpCallsDrawAll(section);
    const snap = xdState.waySnaps[variant];
    if (snap) {
      xpViewPut(section, snap, true);
      delete xdState.waySnaps[variant];
    } else {
      // Shown for the first time: each live session at its newest line.
      $$(".xp-live-scroll", section).forEach((one) => {
        if (!one.scrollTop) one.scrollTop = one.scrollHeight;
      });
    }
  });
}

/* A WAY'S OWN TREE of cards and stages - how its work evolved, round by
   round - as the Experience tab shows the agents' work on a piece of work:
   a row per card, a dot per stage, opened below it. The single model works
   alone, with no cards and no stages: said so. */
function xdTreeHtml(v) {
  if (v.variant === "single") {
    return `<p class="muted xd-no-tree">The single model works alone - no contract, no cards,
      no stages: there is no tree of its work to show.</p>`;
  }
  const tree = experienceState.xdTrees[v.variant] || {};
  return (tree.stages || []).length ? xpGraphSvg(tree, `xd-${v.variant}`)
    : `<p class="muted">No stages yet - each round of the work is drawn here as it is
      made.</p>`;
}

/* A new stage or round while the way goes: its tree drawn again in place -
   the box where it was scrolled, the stage or card open still open. */
function xdTreePatch(v) {
  const box = $(`#xd-tree-${v.variant}`);
  if (!box) return;
  const html = xdTreeHtml(v);
  if (box._xpHtml === xpShows(html)) return;
  const frame = box.querySelector(".xp-frame");
  const at = frame ? [frame.scrollLeft, frame.scrollTop] : [0, 0];
  box.innerHTML = html;
  box._xpHtml = xpShows(html);
  const again = box.querySelector(".xp-frame");
  if (again) [again.scrollLeft, again.scrollTop] = at;
  xdStageAgain(v);
}

function xdStageAgain(v) {
  const where = `xd-${v.variant}`;
  const view = XP_VIEWS[where];
  const box = $(view.box);
  const top = box ? box.scrollTop : 0;
  if (experienceState[view.stage]) xpShowStage(experienceState[view.stage], where);
  else if (experienceState[view.card]) xpShowCard(experienceState[view.card], where);
  if (box) box.scrollTop = top;
}

/* One way of the open project: its heading - the name, where its run
   stands, Stop and Clear - its limits, how packages come, Start, the tree
   of its work, and its runs, drawn as any run is. */
function xdVariant(project, v, shown) {
  const runs = xdState.runs[v.variant] || [];
  const way = (project.variants || []).find((one) => one.variant === v.variant) || {};
  const going = runs.find((run) => run.alive);
  const folder = way.folder || xdUnder(project.folder, v.folder);
  const key = (name) => `limit-${v.variant}-${name}`;
  // AUTO unless changed: a way being measured is not stopped to ask the
  // user about each package - the user's decision for the debugger.
  const mode = xdDraft(`packages-${v.variant}`, "auto");
  const field = (name, label, step = "") => `<label>${label} <input type="number"
    data-xd-limit="${name}" data-xd-field="${key(name)}"${step ? ` step="${step}"` : ""}
    placeholder="no limit" value="${escapeHtml(String(xdDraft(key(name))))}"></label>`;
  const id = escapeHtml(v.variant);
  // Its runs' links into the tree lead to this way's own tree.
  const drawn = runs.map((run, i) => xpRun(run, !going, i === 0)).join("")
    .split('data-xp-where="work"').join(`data-xp-where="xd-${id}"`);
  return `<section class="xd-variant" data-xd-variant="${id}" role="tabpanel"
      id="xd-way-${id}" aria-labelledby="xd-tab-${id}"${shown ? "" : " hidden"}>
    <div class="xd-way-head">
      <h4 class="xd-way-name">${escapeHtml(v.label)} <span class="muted">· folder ${
        escapeHtml(v.folder)}</span></h4>
      <span class="xd-way-live" data-xd-way-live="${id}">${xdWayLive(v)}</span>
    </div>
    ${xdState.clearAsk === v.variant ? xdClearLine(v, folder, Boolean(going || way.alive)) : ""}
    <p class="muted">${escapeHtml(v.about)}</p>
    <p class="muted">Works in <code>${escapeHtml(folder)}</code></p>
    <div class="xp-limits xd-limits"><strong>Limits:</strong>
      ${field("minutes", "minutes")}${field("tokens_in", "input tokens", "100000")}${
      field("tokens_out", "output tokens", "10000")}${field("calls", "model calls")}
      <span class="muted">empty: no limit</span></div>
    <div class="xp-packages-mode"><strong>Python packages:</strong>
      <label><input type="radio" name="xd-packages-${id}" value="ask"
        data-xd-field="packages-${id}"${mode !== "auto" ? " checked" : ""}>
        Ask me</label>
      <label><input type="radio" name="xd-packages-${id}" value="auto"
        data-xd-field="packages-${id}"${mode === "auto" ? " checked" : ""}>
        Auto</label></div>
    ${going || xdWaits(v.variant) ? "" : `<p class="xd-actions">${runs.length ? xdGoOn(runs[0], id)
        : `<label class="xd-instruction">Instruction <textarea rows="3" maxlength="8000"
            data-xd-field="instruction-${id}"
            placeholder="what you want done">${escapeHtml(xdDraft(
              `instruction-${v.variant}`, project.instruction || ""))}</textarea></label>
          ${project.instruction ? `<span class="muted">the words the last way began
            with - keep them to compare the three alike</span>` : ""}
          <button type="button" class="small" data-xd-start="${id}"
            >Start</button> ${xpSoundBox(`data-xd-sound="${id}" data-xd-field="sound-${
          id}"`, xdDraft(`sound-${v.variant}`, "1") === "1")}`}</p>`}
    <div class="xd-work-tree" data-xp-keep="xd-tree:${id}">
      <h4>The agents' work on it</h4>
      <div class="xd-tree" id="xd-tree-${id}">${xdTreeHtml(v)}</div>
      <div class="xd-stage xp-stage" id="xd-stage-${id}" data-xp-keep="xd-stage:${id}"></div>
    </div>
    <div class="xd-runs">${drawn || `<p class="muted">Not started yet.</p>`}</div>
  </section>`;
}

/* A WAY ALREADY STARTED: its run interrupted - the application closed, the
   computer went off - goes on from its last saved version with Resume,
   here where Start was; one that ended otherwise is continued below. */
function xdGoOn(latest, id) {
  if (latest && !latest.alive && xpGoesBack(latest)) {
    const at = (latest.milestone || {}).version;
    return `<button type="button" class="small" data-xp-continue="${escapeHtml(latest.id)}"
        >Resume</button> <span class="muted">it did not stop cleanly - ${
        escapeHtml(XP_GOES_BACK[latest.status])} - it goes back to ${at
        ? `its last save point, ${escapeHtml((latest.milestone || {}).label || at)}`
        : "where it was"}, with the limits above</span>`;
  }
  return `<button type="button" class="small" data-xd-start="${id}"
      disabled>Start</button> <span class="muted">started - continue its run below</span>`;
}

/* THE TRIES: the same instruction tried again, each in its own subfolder
   of the project's folder, each blind to every other - its ways may read
   no other try's folder, nor the Claude Code or Codex sessions held in
   one. The one shown is the one started and continued here. */
function xdTries(project) {
  const tries = project.tries || [1];
  const shown = Number(project.try) || 1;
  return `<div class="xd-tries" role="group" aria-label="Tries">
      <span class="muted">Try</span>
      ${tries.map((n) => {
        const button = document.createElement("button");
        button.type = "button";
        button.classList.add("small");
        if (n !== shown) button.classList.add("secondary");
        button.dataset.xdTry = String(n);
        if (n === shown) button.setAttribute("aria-pressed", "true");
        button.textContent = String(n);
        return button.outerHTML;
      }).join("")}
      <button type="button" class="small secondary" data-xd-new-try="1">New try</button>
      ${tries.length > 1 ? xdState.removeTryAsk === shown
        ? `<span class="xd-try-ask" role="alert">Remove try ${shown}? Its folder
            <code>${escapeHtml(project.try_folder || "")}</code> and everything in it - what
            its three ways made and what you wrote there - is deleted, with its runs and the
            Claude Code and Codex sessions of work in it. This cannot be undone.
            <button type="button" class="small danger" data-xd-remove-try-yes="${shown}">Remove try ${shown}</button>
            <button type="button" class="small secondary" data-xd-remove-try-no="1">Keep it</button></span>`
        : `<button type="button" class="small secondary danger-text" data-xd-remove-try="${shown}"${
            (project.variants || []).some((v) => v.alive)
              ? ` disabled title="A way of this try is going: stop it first"` : ""}>Remove this try</button>`
        : ""}
      <span class="muted xd-try-folder">Sees none of the other tries:
        <code>${escapeHtml(project.try_folder || "")}</code></span>
    </div>`;
}

/* WHAT THE FULL WAY IS NOT GIVEN of what was learned of your work: the
   project's own folder - its tries, and what you wrote of them - and the
   folders you name for it, such as the project it redoes; with what Claude
   Code and Codex kept of work in each. The folders you name are closed to
   all three ways besides. (debug_projects.leave_out_view) */
function xdLeaveOut(project) {
  const base = String(project.id || "").split("~")[0];
  const view = xdState.leaveOut && xdState.leaveOut.id === base
    && Array.isArray(xdState.leaveOut.folders) ? xdState.leaveOut : null;
  const folders = view ? view.folders : (project.leave_out || [project.folder]).map((path) => ({
    path, own: path === project.folder, agent: path === project.agent_folder }));
  const rows = folders.map((one) => {
    const path = escapeHtml(one.path);
    const asking = xdState.leaveOutAsk === one.path;
    const claude = (one.claude || []).map((dir) => `<code>${escapeHtml(dir)}</code>`).join(", ");
    return `<li><code>${path}</code> ${one.own
      ? `<span class="muted">this project's folder</span>`
      : one.agent ? `<span class="muted">the agent's own folder</span>`
      : asking ? `<span class="xd-try-ask" role="alert">Give C what was learned from this folder
          again, and let the three ways read it?
          <button type="button" class="small danger" data-xd-leave-remove-yes="${path}">Use it again</button>
          <button type="button" class="small secondary" data-xd-leave-remove-no="1">Keep it left out</button></span>`
        : `<button type="button" class="small secondary" data-xd-leave-remove="${path}">Remove</button>`}
      ${view ? `<div class="muted">${claude ? `<span>Claude Code conversations in ${claude}</span>`
        : `<span>No Claude Code conversations in it</span>`}${one.codex
        ? `, <span>${Number(one.codex)} Codex conversations</span>` : ""}</div>` : ""}</li>`;
  }).join("");
  return `<div class="xd-leave-out">
      <p><strong>Experience left out</strong> <span class="muted">C's reviewer is given nothing
        learned from these folders and all their subfolders, nor from the Claude Code and Codex
        conversations held of work in any of them; and no way finds, in your records, what was
        done in them. A folder you add - the project this one redoes, say - is closed to all
        three ways as well, with all its subfolders. So is the agent's own folder.</span></p>
      <ul class="xd-leave-out-list">${rows}</ul>
      <p>${view ? `<span class="muted">Left out of what was learned: ${Number(view.cases)} cases whole, ${
        Number(view.judgments)} judgments in all.</span> `
        : ""}<button type="button" class="small secondary" data-xd-leave-add="1">Add a folder…</button></p>
    </div>`;
}

/* The folders left out of the project shown, read again when another is
   shown or they changed. */
async function xdLoadLeaveOut(project, again = false) {
  const base = String((project || {}).id || "").split("~")[0];
  if (!base || (!again && xdState.leaveOut && xdState.leaveOut.id === base)) return;
  try {
    const said = await api.get(`/api/debugger/experience/leave_out?project=${encodeURIComponent(base)}`);
    xdState.leaveOut = Object.assign({ id: base }, said);
  } catch (err) {
    xdState.leaveOut = null;
  }
}

function xdDraw() {
  const project = xdState.project;
  const list = xdState.projects.length ? `<ul class="xd-list">${xdState.projects.map((p) =>
    `<li><button type="button" class="xd-project${project && project.id === p.id
      ? " selected" : ""}" data-xd-open="${escapeHtml(p.id)}">${escapeHtml(xpName(p.name))}</button>
      <span class="muted">${(p.variants || []).filter((v) => v.alive).length
        ? `${p.variants.filter((v) => v.alive).length} going` : ""}</span></li>`).join("")}</ul>`
    : `<p class="muted">No projects yet.</p>`;
  const shown = xdWayShown();
  return `<div class="xd-head">
      <strong>Projects</strong>
      <button type="button" class="small secondary" data-xd-new="1">New project</button>
    </div>
    ${list}
    ${xdState.newOpen ? xdNewForm() : ""}
    ${project ? `<div class="xd-project-view" data-xd-project="${escapeHtml(project.id)}">
      ${xdWords(project, "name", "Name")}
      ${xdWords(project, "description", "Your description")}
      ${xdLeaveOut(project)}
      <p class="muted">Folder: <code>${escapeHtml(project.folder)}</code> ·
        ${xdState.removeAsk ? `Remove this project? Its records go; nothing in its folder
          is deleted. <button type="button" class="small danger" data-xd-remove-yes="1">Remove</button>
          <button type="button" class="small secondary" data-xd-remove-no="1">Keep it</button>`
          : xdState.clearAllAsk ? `Clear all three ways? Everything they wrote in
          ${XD_VARIANTS.map((v) => `<code>${escapeHtml(v.folder || "")}</code>`).join(", ")}
          is deleted and their runs are forgotten; the folders, your own files beside them
          and the project stay.
          <button type="button" class="small danger" data-xd-clear-all-yes="1">Clear all</button>
          <button type="button" class="small secondary" data-xd-clear-all-no="1">Keep them</button>`
          : `<button type="button" class="small secondary" data-xd-remove="1">Remove</button>
          ${xdClearAllButton()}`}</p>
      ${xdTries(project)}
      <div class="xd-tabs" role="tablist" aria-label="The three ways">${XD_VARIANTS.map((v) => `
        <button type="button" role="tab" class="xd-tab${v.variant === shown ? " selected" : ""}"
          id="xd-tab-${escapeHtml(v.variant)}" data-xd-tab="${escapeHtml(v.variant)}"
          aria-controls="xd-way-${escapeHtml(v.variant)}"
          aria-selected="${v.variant === shown ? "true" : "false"}"
          tabindex="${v.variant === shown ? "0" : "-1"}"><span class="xd-tab-name">${
          escapeHtml(v.label)} · ${escapeHtml(v.folder)}</span><span class="xd-tab-badge"
          data-xd-tab-badge="${escapeHtml(v.variant)}">${xdWayBadge(v)}</span></button>`).join("")}
      </div>
      <div class="xd-variants">${XD_VARIANTS.map((v) => xdVariant(project, v,
        v.variant === shown)).join("")}</div>
    </div>` : ""}`;
}

/* What makes the panel drawn again whole: the projects and which is open,
   the forms and questions open in it, each way's runs in kind (xpRunSig),
   and whether its tree has anything yet. Not what only goes on while a way
   works - that is changed in place - nor which way is shown: switching
   draws nothing. */
function xdSig() {
  const project = xdState.project;
  return JSON.stringify([
    xdState.projects.map((p) => [p.id, p.name, (p.variants || []).map((v) => Boolean(v.alive))]),
    project ? [project.id, project.name, project.description, project.instruction,
               project.folder, (project.variants || []).map((v) => v.folder || ""),
               project.try, (project.tries || []).join(","), (project.leave_out || []).join("|")] : null,
    xdState.leaveOut, xdState.leaveOutAsk,
    xdState.newOpen, xdState.newFolder, xdState.editing, xdState.removeAsk, xdState.clearAsk,
    XD_VARIANTS.map((v) => (xdState.runs[v.variant] || []).map(xpRunSig)),
    XD_VARIANTS.map((v) => Boolean(xdWaits(v.variant))),
    XD_VARIANTS.map((v) => Boolean(((experienceState.xdTrees[v.variant] || {}).stages || []).length))]);
}

/* THE PANEL, asked for again - changed in place when only what is live
   changed (each run's live parts, each way's heading, tab badge and tree);
   drawn whole only when something changed in kind, and never under the
   user's typing: then once the field is left. Drawn whole, the live
   sessions open in it are kept and moved into it, and the view is put back
   exactly as it was (xpViewKeep / xpViewPut), as the Experience tab does
   with its own. */
async function loadDebuggerExperience(force = false) {
  const body = $("#dbg-xd-body");
  if (!body || !xdState.open) return;
  let projects;
  try {
    projects = (await api.get("/api/debugger/experience/projects")).projects || [];
  } catch (err) {
    body.innerHTML = `<p class="muted">The Work debugger is not available in this build.</p>`;
    body._xpSig = "";
    return;
  }
  xdState.projects = projects;
  // The one open; else the one open last time; else the newest - a project
  // is never left closed just because the page was loaded again.
  const wanted = xdState.project ? xdState.project.id : (xdState.closed ? "" : xdRemembered());
  // By the project, whichever of its tries is shown: "<id>~<try>" is a try
  // of "<id>".
  const baseOf = (id) => String(id || "").split("~")[0];
  const chosen = (wanted && xdState.projects.find((p) => baseOf(p.id) === baseOf(wanted)))
    || (!xdState.project && !xdState.closed ? xdState.projects[0] : null);
  xdState.project = chosen || null;
  if (xdState.project) xdRemember(xdState.project);
  if (xdState.project) await xdLoadLeaveOut(xdState.project);
  const runsNow = {};
  const treesNow = {};
  const waitsNow = {};
  if (xdState.project) {
    const id = encodeURIComponent(xdState.project.id);
    const got = await Promise.all(XD_VARIANTS.map((v) => Promise.all([
      api.get(`/api/debugger/experience/runs?project=${id}&variant=${v.variant}`)
        .then((r) => { waitsNow[v.variant] = r.waiting || {}; return r.runs || []; })
        .catch(() => []),
      v.variant === "single" ? Promise.resolve({})
        : api.get(`/api/debugger/experience/tree?project=${id}&variant=${v.variant}`)
          .catch(() => ({}))])));
    XD_VARIANTS.forEach((v, i) => {
      [runsNow[v.variant], treesNow[v.variant]] = got[i];
    });
  }
  xdState.runs = runsNow;
  xdState.waiting = waitsNow;
  experienceState.xdTrees = treesNow;
  const kept = xpVersionsState();
  kept.idle = kept.idle || {};
  const all = [];
  Object.entries(xdState.runs).forEach(([variant, runs]) => {
    const going = runs.some((run) => run.alive);
    runs.forEach((run) => {
      kept.runs[run.id] = run;
      kept.idle[run.id] = !going;
      xdState.runVariant[run.id] = variant;
      all.push(run);
    });
  });
  // A way waiting for room is followed as one going is: it starts by itself.
  const alive = all.some((run) => run.alive)
    || XD_VARIANTS.some((v) => Boolean(xdWaits(v.variant)));
  if (!force && xpPanelSame(body, xdSig())) {
    // Only what is live: each run in place, each way's heading, tab and tree.
    all.forEach(xpRunPatch);
    XD_VARIANTS.forEach((v) => { xdWayPatch(v.variant); xdTreePatch(v); });
    xdTimer(alive);
    return;
  }
  if (!force && xpEditing("#dbg-xd")) {
    xpDefer("#dbg-xd", () => loadDebuggerExperience());
    xdTimer(alive);
    return;
  }
  await xpVersionsReady(all);
  if (!force && xpEditing("#dbg-xd")) {
    xpDefer("#dbg-xd", () => loadDebuggerExperience());
    return;
  }
  const view = xpViewKeep(body);
  const lives = xpLiveKeep(body);
  body.innerHTML = xdDraw();
  body._xpSig = xdSig();
  XD_VARIANTS.forEach((v) => {
    const tree = $(`#xd-tree-${v.variant}`);
    if (tree) tree._xpHtml = xpShows(xdTreeHtml(v));
    if (tree) xdStageAgain(v);
  });
  all.forEach((run) => {
    if (kept.views[run.id]) {
      xpVersionSlides($(`#xp-version-view-${CSS.escape(run.id)}`), kept.views[run.id]);
    }
  });
  xpLivePut(body, lives);
  all.forEach((run) => {
    if (!xpLiveState(run.id).open) return;
    xpLiveDraw(run.id, null, true);
    xpLiveFollow(run.id);
  });
  xpCallsDrawAll(body);
  XD_VARIANTS.forEach((v) => xdWayPatch(v.variant));
  xpViewPut(body, view);
  xdWayTabs(body);
  requestAnimationFrame(() => xpViewPut(body, view, true));
  xdTimer(alive);
}

/* While a way goes, looked at again every few seconds - while the
   Experience debugger is the tab shown. */
function xdTimer(alive) {
  clearTimeout(xdState.timer);
  if (!alive) return;
  xdState.timer = setTimeout(() => {
    if (activeTab === "xdebug" && !document.hidden) loadDebuggerExperience();
  }, 5000);
}

async function xdClick(event) {
  const at = (selector) => event.target.closest(selector);
  const tabAt = at("[data-xd-tab]");
  if (tabAt) {
    // Another way shown: nothing drawn again.
    xdShowWay(tabAt.dataset.xdTab);
    return;
  }
  if (at("[data-xd-new]")) {
    xdState.newOpen = !xdState.newOpen;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-new-cancel]")) {
    xdState.newOpen = false;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-choose]")) {
    const path = await xpChooseFolder("A folder for the three ways - a subfolder is made in it for each");
    if (path) xdState.newFolder = path;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-create]")) {
    const name = String(xdDraft("new-name")).trim();
    if (!name) { toast("Give it a name."); return; }
    if (!xdState.newFolder) { toast("Choose a folder."); return; }
    try {
      const said = await api.post("/api/debugger/experience/projects", { action: "create",
        name, description: String(xdDraft("new-description")).trim(),
        folder: xdState.newFolder });
      xdState.project = said.project || null;
      xdRemember(xdState.project);
      xdState.newOpen = false;
      xdState.newFolder = "";
      ["new-name", "new-description"].forEach((k) => delete xdState.drafts[k]);
    } catch (err) {
      toast(err.message);
    }
    await loadDebuggerExperience(true);
    return;
  }
  const openAt = at("[data-xd-open]");
  if (openAt) {
    xdState.project = xdState.projects.find((p) => p.id === openAt.dataset.xdOpen) || null;
    xdRemember(xdState.project);
    xdState.editing = null;
    xdState.removeAsk = false;
    xdState.clearAsk = "";
    await loadDebuggerExperience(true);
    return;
  }
  const tryAt = at("[data-xd-try]");
  if ((tryAt || at("[data-xd-new-try]")) && xdState.project) {
    try {
      await api.post("/api/debugger/experience/projects", tryAt
        ? { action: "use_try", id: xdState.project.id, try: Number(tryAt.dataset.xdTry) }
        : { action: "new_try", id: xdState.project.id });
    } catch (err) {
      toast(err.message);
    }
    await loadDebuggerExperience(true);
    return;
  }
  const editAt = at("[data-xd-edit]");
  if (editAt) {
    xdState.editing = editAt.dataset.xdEdit;
    delete xdState.drafts[`edit-${xdState.editing}`];
    await loadDebuggerExperience(true);
    $(`#dbg-xd [data-xd-field="edit-${xdState.editing}"]`)?.focus();
    return;
  }
  if (at("[data-xd-edit-cancel]")) {
    xdState.editing = null;
    await loadDebuggerExperience(true);
    return;
  }
  const saveAt = at("[data-xd-save]");
  if (saveAt && xdState.project) {
    const field = saveAt.dataset.xdSave;
    const box = $(`#dbg-xd [data-xd-field="edit-${field}"]`);
    try {
      await api.post("/api/debugger/experience/projects", { action: "update",
        id: xdState.project.id, [field]: box ? box.value : xdDraft(`edit-${field}`) });
      xdState.editing = null;
      delete xdState.drafts[`edit-${field}`];
    } catch (err) {
      toast(err.message);
    }
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-remove]") || at("[data-xd-remove-no]")) {
    xdState.removeAsk = Boolean(at("[data-xd-remove]"));
    xdState.clearAsk = "";
    xdState.clearAllAsk = false;
    await loadDebuggerExperience(true);
    return;
  }
  // REMOVE A TRY: asked first, in the row of tries; then its folder and all
  // in it deleted.
  if (at("[data-xd-remove-try]") || at("[data-xd-remove-try-no]")) {
    const asking = at("[data-xd-remove-try]");
    xdState.removeTryAsk = asking ? Number(asking.dataset.xdRemoveTry) : 0;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-remove-try-yes]") && xdState.project) {
    if (xdState.removingTry) return;
    xdState.removingTry = true;
    at("[data-xd-remove-try-yes]").disabled = true;
    try {
      const said = await api.post("/api/debugger/experience/projects", { action: "remove_try",
        id: xdState.project.id });
      const left = (said.not_removed || []).length + (said.left_alone || []).length;
      toast(`Removed try ${said.removed_try}: ${Number(said.files || 0)} file${said.files === 1 ? "" : "s"}, ${
        Number(said.runs || 0)} run${said.runs === 1 ? "" : "s"} and ${
        Number(said.sessions || 0)} session${said.sessions === 1 ? "" : "s"}${left
        ? ` - ${left} could not be removed` : ""}.`);
      if (said.project) xdState.project = said.project;
    } catch (err) {
      toast(err.message);
    }
    xdState.removeTryAsk = 0;
    xdState.removingTry = false;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-clear-all]") || at("[data-xd-clear-all-no]")) {
    xdState.clearAllAsk = Boolean(at("[data-xd-clear-all]"));
    xdState.clearAsk = "";
    xdState.removeAsk = false;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-clear-all-yes]") && xdState.project) {
    // Once: a second click while it goes is not a second clear.
    if (xdState.clearing) return;
    xdState.clearing = true;
    at("[data-xd-clear-all-yes]").disabled = true;
    try {
      const said = await api.post("/api/debugger/experience/projects", { action: "clear_all",
        id: xdState.project.id });
      // Every way's runs, forgotten here too.
      const kept = xpVersionsState();
      Object.keys(xdState.runVariant).forEach((runId) => {
        delete kept.runs[runId];
        delete kept.trees[runId];
        delete kept.views[runId];
        delete kept.from[runId];
        delete xdState.runVariant[runId];
      });
      const left = (said.not_removed || []).length + (said.left_alone || []).length;
      toast(`Cleared all three ways: ${Number(said.files || 0)} file${said.files === 1 ? "" : "s"}, ${
        Number(said.folders || 0)} folder${said.folders === 1 ? "" : "s"} and ${
        Number(said.runs || 0)} run${said.runs === 1 ? "" : "s"}${left
        ? ` - ${left} could not be removed` : ""}.`);
    } catch (err) {
      toast(err.message);
    }
    xdState.clearAllAsk = false;
    xdState.clearing = false;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-clear]") || at("[data-xd-clear-no]")) {
    xdState.clearAsk = at("[data-xd-clear]") ? at("[data-xd-clear]").dataset.xdClear : "";
    xdState.removeAsk = false;
    xdState.clearAllAsk = false;
    await loadDebuggerExperience(true);
    return;
  }
  const clearYes = at("[data-xd-clear-yes]");
  if (clearYes && xdState.project) {
    const variant = clearYes.dataset.xdClearYes;
    if (xdState.clearing) return;
    xdState.clearing = true;
    clearYes.disabled = true;
    try {
      const said = await api.post("/api/debugger/experience/projects", { action: "clear",
        id: xdState.project.id, variant });
      // That way's runs, forgotten here too; the other two ways' are kept.
      const kept = xpVersionsState();
      Object.keys(xdState.runVariant).filter((runId) => xdState.runVariant[runId] === variant)
        .forEach((runId) => {
          delete kept.runs[runId];
          delete kept.trees[runId];
          delete kept.views[runId];
          delete kept.from[runId];
          delete xdState.runVariant[runId];
        });
      const left = (said.not_removed || []).length + (said.left_alone || []).length;
      toast(`Cleared: ${Number(said.files || 0)} file${said.files === 1 ? "" : "s"}, ${
        Number(said.folders || 0)} folder${said.folders === 1 ? "" : "s"}${said.links
        ? `, ${Number(said.links)} link${said.links === 1 ? "" : "s"}` : ""} and ${
        Number(said.runs || 0)} run${said.runs === 1 ? "" : "s"}${left
        ? ` - ${left} could not be removed` : ""}.`);
    } catch (err) {
      toast(err.message);
    }
    xdState.clearAsk = "";
    xdState.clearing = false;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-leave-add]") && xdState.project) {
    const path = await xpChooseFolder("A folder whose experience C is not given");
    if (!path) return;
    try {
      const said = await api.post("/api/debugger/experience/projects", { action: "leave_out",
        id: xdState.project.id, add: path });
      xdState.leaveOut = Object.assign({ id: String(xdState.project.id).split("~")[0] }, said);
    } catch (err) {
      toast(err.message);
    }
    await loadDebuggerExperience(true);
    return;
  }
  const leaveAt = at("[data-xd-leave-remove]");
  if (leaveAt) {
    xdState.leaveOutAsk = leaveAt.dataset.xdLeaveRemove;
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-leave-remove-no]")) {
    xdState.leaveOutAsk = "";
    await loadDebuggerExperience(true);
    return;
  }
  const leaveYes = at("[data-xd-leave-remove-yes]");
  if (leaveYes && xdState.project) {
    try {
      const said = await api.post("/api/debugger/experience/projects", { action: "leave_out",
        id: xdState.project.id, remove: leaveYes.dataset.xdLeaveRemoveYes });
      xdState.leaveOut = Object.assign({ id: String(xdState.project.id).split("~")[0] }, said);
    } catch (err) {
      toast(err.message);
    }
    xdState.leaveOutAsk = "";
    await loadDebuggerExperience(true);
    return;
  }
  if (at("[data-xd-remove-yes]") && xdState.project) {
    try {
      await api.post("/api/debugger/experience/projects", { action: "remove",
        id: xdState.project.id });
      xdState.project = null;
      xdState.closed = true;
      xdRemember(null);
    } catch (err) {
      toast(err.message);
    }
    xdState.removeAsk = false;
    await loadDebuggerExperience(true);
    return;
  }
  const unwaitAt = at("[data-xd-unwait]");
  if (unwaitAt && xdState.project) {
    unwaitAt.disabled = true;
    try {
      await api.post("/api/debugger/experience/unwait", { project: xdState.project.id,
        variant: unwaitAt.dataset.xdUnwait });
    } catch (err) {
      toast(err.message);
    }
    await loadDebuggerExperience(true);
    return;
  }
  const startAt = at("[data-xd-start]");
  if (startAt && xdState.project) {
    const variant = startAt.dataset.xdStart;
    const box = startAt.closest("[data-xd-variant]")
      ?.querySelector(`[data-xd-field="instruction-${variant}"]`);
    const instruction = String(box ? box.value : xdDraft(`instruction-${variant}`)).trim();
    if (!instruction) { toast("Say what you want done."); return; }
    startAt.disabled = true;
    // Said at once: a Start that only went grey read as one that could not
    // be pressed.
    startAt.textContent = "Starting\u2026";
    try {
      const said = await api.post("/api/debugger/experience/start", {
        project: xdState.project.id, variant,
        instruction, limits: xdLimits(startAt),
        packages: xdDraft(`packages-${variant}`, "auto"),
        sound: xdDraft(`sound-${variant}`, "1") === "1" });
      delete xdState.drafts[`instruction-${variant}`];
      if (said && said.waiting) toast(`Waiting for room: ${said.why}. It starts by itself.`);
    } catch (err) {
      toast(err.message);
    }
    await loadDebuggerExperience(true);
    return;
  }
  // A way's own tree: a stage or a card opened under it, as in the
  // Experience tab. (A link to the Experience tab's own tree leads nowhere
  // here.)
  const stageAt = at("[data-xp-stage]");
  const cardAt = at("[data-xp-card]");
  if (stageAt || cardAt) {
    event.preventDefault();
    const where = (stageAt || cardAt).dataset.xpWhere || "";
    if (!where.startsWith("xd-") || !XP_VIEWS[where]) return;
    if (stageAt) xpShowStage(stageAt.dataset.xpStage, where);
    else xpShowCard(cardAt.dataset.xpCard, where);
    $(XP_VIEWS[where].box)?.scrollIntoView({ block: "nearest" });
    return;
  }
  await xpRunClick(event, XD_HOST);
}

function wireDebuggerExperience() {
  // A tab of its own: nothing to collapse.
  const panel = $("#dbg-xd");
  if (!panel) return;
  panel.addEventListener("click", (event) => { xdClick(event); });
  // The ways' tabs, as tabs go: ← → to the next, Home and End.
  panel.addEventListener("keydown", (event) => {
    const tab = event.target.closest && event.target.closest("[data-xd-tab]");
    if (!tab || !["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    const tabs = $$("[data-xd-tab]", panel);
    const at = tabs.indexOf(tab);
    const next = event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1
      : (at + (event.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length;
    xdShowWay(tabs[next].dataset.xdTab);
    tabs[next].focus();
  });
  // A box ticked is kept as "1", one not as "".
  const valueOf = (field) => (field.type === "checkbox" ? (field.checked ? "1" : "")
    : field.value);
  panel.addEventListener("input", (event) => {
    const field = event.target.closest && event.target.closest("[data-xd-field]");
    if (field) xdState.drafts[field.dataset.xdField] = valueOf(field);
    const words = event.target.closest && event.target.closest("[data-xp-continue-instruction]");
    if (words) xpVersionsState().words[words.dataset.xpContinueInstruction] = words.value;
  });
  panel.addEventListener("change", (event) => {
    const field = event.target.closest && event.target.closest("[data-xd-field]");
    if (field) xdState.drafts[field.dataset.xdField] = valueOf(field);
  });
}

if (DELEGATE_SOLO || LEARN_SOLO) {
  // The box alone: its face, and nothing else of the page asked for.
  loadDelegateIcon();
} else {
refresh();
wireAvatarEditor();
applyDebuggerAvailability();
// The avatar's face, for each "Delegate work".
loadDelegateIcon().then(() => { if (typeof ovPlaceTodos === "function") ovPlaceTodos(); });
wireDebuggerStates();
loadDebuggerStates();
wireFileActivity();
wireDebuggerExperience();
loadDebuggerExperience();
wireHeartbeatRun();
wireStateBeat();
wireTokenUsage();
loadTokenUsage();
setInterval(() => { if (dbgTokens.open) loadTokenUsage(); }, 30000);
// The tab's panels are fetched again only while somebody can see them: a
// minimised window asking for its nine overview answers every fifteen
// seconds is all cost. Coming back asks at once, so nothing is stale.
setInterval(() => { if (!document.hidden) refresh(); }, 15000);
document.addEventListener("visibilitychange", () => {
  if (!document.hidden) refresh();
});
setInterval(pollNotifications, 20000);
}

/* Where the page opens. "#chatdebug" - or any tab's name after the # - opens
   that tab, which is how the desktop's menu reaches one; an address naming a
   conversation or a chat project opens the Chat tab on it. */
(() => {
  const params = new URLSearchParams(location.search);
  const wanted = location.hash.replace(/^#/, "");
  // Handed to the learning from Explorer: its learning plan drafted, to check.
  if (params.has("learn_inbox")) {
    const id = params.get("learn_inbox");
    history.replaceState(null, "", location.pathname);
    $("#learn-box").showModal();
    $("#learn-body").innerHTML = `<p class="muted">Looking at it&hellip;</p>`;
    api.post("/api/learning/inbox", { id })
      .then((said) => learnFollow(said.draft.id))
      .catch((err) => toast(err.message, "error"));
    return;
  }
  // The selection's "Learn": its learning plan being drafted already.
  if (wanted.startsWith("learn=")) {
    const id = decodeURIComponent(wanted.slice("learn=".length));
    history.replaceState(null, "", location.pathname);
    learnFollow(id);
    return;
  }
  // Handed over from Explorer: made a piece of work, and its plan shown.
  if (params.has("delegate_inbox")) {
    const id = params.get("delegate_inbox");
    history.replaceState(null, "", location.pathname);
    api.post("/api/work/drafts/inbox", { id })
      .then((said) => openDelegateDraft(said.draft.id))
      .catch((err) => toast(err.message, "error"));
    return;
  }
  // A piece of work handed over from outside the page: its plan, to check -
  // or, from the avatar's menu, the box empty, to say what to hand over.
  if (wanted.startsWith("delegate=")) {
    const id = decodeURIComponent(wanted.slice("delegate=".length));
    history.replaceState(null, "", location.pathname);
    if (id === "new") openDelegateNew();
    else openDelegateDraft(id);
    return;
  }
  const tab = wanted && $(`#tabs button[data-tab="${CSS.escape(wanted)}"]`);
  if (params.get("tab") === "chat" || params.has("conversation") || params.has("project")) {
    $('#tabs button[data-tab="chat"]')?.click();
  } else if (tab) {
    tab.click();
  }
})();
